[23] = {
    en = "Ursangous's Paw",
    T = "Лапа Урсангоуса",
    D = "Лапа могутнього ведмедя Урсангоуса — це ваш трофей за цю частину полювання в Попеліній долині. На лапі зображено невеликий емблему у формі чверті місяця; значення цієї емблеми залишається загадкою.$B$BЛапу слід віднести до Сенані Громосердечної у форпості Сплінтертрі, щоб довести, що ви перемогли цю могутню істоту та завершили цю частину полювання.",
    O = "Принесіть «Лапу Урсангоуса» Сенані Громосерцеві у форпості Сплінтертрі, що в Попелястій долині.",
