[253] = {
    en = "Bride of the Embalmer",
    T = "«Наречена бальзаміста»",
    D = "«Бальзамувальник» — це персонаж, про якого розповідається в одній із наших дитячих казок. Він був доброзичливим алхіміком, якого довела до божевілля смерть його дружини Елізи. Щоб повернути її до життя, він скористався темною магією й помістив своє власне серце в груди померлої дружини.$B$BЦе оживило Елізу... але наклало на неї прокляття — жагу до людського м’яса, що змусило «Бальзамувальника» тримати її похованою.$B$BЙого серце — це його сила. Знайдіть могилу його дружини, дістаньте його серце і принесіть його мені, поки воно ще б’ється. Зробіть це — і його сила буде зламана.",
    O = "Знайдіть могилу Елізи. Заберіть у неї «Серце бальзамувальника», а потім поверніться до Елло Ебонлока.",
    P = "Ти вже знайшов могилу Елізи? У тебе є серце бальзамувальника?",
    C = "Ти це зробив! Магія в його серці стане захистом від зла Бальзамувальника та потужною опікою над містом Даркшир.$B$BВи зробили велику справу для нашого народу, $N. Ваше ім'я назавжди залишиться в наших літописах.",
},

[254] = {
    en = "Digging Through the Dirt",
    T = "Копаючись у землі",
    D = "",
    O = "",
    P = "",
    C = "Ти розкопуєш напівпухкий ґрунт над могилою… і знаходиш залишки труни.$B$BЗсередини труни ти відчуваєш вібруючі шкрябання пазуристих пальців і скрегіт гнилих зубів…$B$BЧи відкриєте ви труну й дістанете серце бальзамувальника?",
