[412] = {
    en = "Operation Recombobulation",
    T = "Операція «Рекомбобуляція»",
    D = "Після детальнішого аналізу ситуації в Гномерегані виявляється, що ми не тільки не змогли знищити трогів, а й, виявляється, перетворили більшу частину гномів на жахливих, бездумних і злочинних гномів-прокажених.$B$BОззі та я плануємо нейтралізувати цей жахливий ефект прокази за допомогою нашого останнього винаходу — рекомбобулятора. Машина майже готова, але нам терміново потрібні кілька рестабілізаційних шестерень та гіромеханічних передач. Знайдіть їх для нас у прокажених гномів перед Гномереганом.",
    O = "Принесіть Razzle Sprysprocket у Харанос 8 шестерень для рестабілізації та 8 гіромеханічних шестерень.",
    P = "«Рекомбобулятор» запрацює, щойно ми отримаємо достатню кількість «зубчастих коліс рестабілізації» та «гіромеханічних шестерень».",
    C = "Ці гіромеханічні шестерні та рестабілізаційні зубчасті колеса повністю відповідають схемам Оззі для пристрою «Рекомбобуляція». Як тільки я додам трохи гідромастила до поршнів внутрішнього згоряння, відрегулюю кривошип-трещотку та підвищу в’язкість електрогумового гелю, гномська раса стане як нова.",
},

[413] = {
    en = "Shimmer Stout",
    T = "Shimmer Stout",
    D = "Я хотів би, щоб мій брат Велларт скуштував мій новий «Шіммер Стаут». Він — альпініст, який несе службу в південній сторожовій вежі, одній із двох веж на кордоні з Лох-Моданом.$B$BМоже, він і не пивовар, як решта нас, Барлібрю, але він обожнює випивку, і я впевнений, що це пиво йому сподобається.$B$BЧи не могли б ви передати йому від мене цю бочку «Шіммер Стаут»?",
    O = "Віднесіть бочку «Shimmer Stout» до пивоварні «Mountaineer Barleybrew».",
    P = "Привіт, $C! А що тебе привело аж сюди?$B$BСподіваюся, щось цікаве. Я вже кілька днів не брав участі в хорошій бійці, а ця бочка елю майже порожня...",
    C = "<«Маунтінір Барлібрю» пробує «Шіммер Стаут»...>$B$BО. Ого! Це пиво справді додає блиску очам. Мені здається, ніби я можу бачити в темряві!",
},

[414] = {
    en = "Stout to Kadrell",
    T = "Від Стаута до Кадрелла",
    D = "Я останнім часом частіше п’ю той «Shimmer Stout», який зварив мій брат — це просто чудове пиво! Хочу, щоб хтось із «Мountaineers» його спробував. Його звати Кадрелл, і зазвичай він патрулює дорогу, що проходить через Телсамар у Лох-Модані.$B$BЩоб дістатися до Телсамара, йдіть на південний схід через тунель, а потім, коли стежка розгалужується на дорогу, поверніть на північний схід. Йдіть цією дорогою прямо до Телсамара.$B$BВіддайте альпіністу Кадрелу цю бочку «Shimmer Stout» і поцікавтеся, що він про неї думає!",
    O = "Віднесіть бочку «Шіммер Стаут» альпіністу Кадреллу.",
    P = "Вітаю, $C, і ласкаво просимо до Телсамара!",
    C = "А тепер дай-но я спробую... $B$BБорода Магні! Ця штука просто збиває з ніг! І ще й ноги стають легкими. $B$BТаке відчуття, ніби я можу літати!",
},

[415] = {
    en = "Rejold's New Brew",
    T = "Новий напій від Rejold",
    D = "Реджолд Барлібрю з села Брюналл розпитував про тебе.$B$BВін хоче поговорити з тобою про новий напій, який він варить... Згадував щось про те, що ти міг би йому в цьому допомогти. Можливо, тобі варто повернутися до селища Брюналл і дізнатися, що він має на думці.$B$BМожливо, тобі вдасться отримати трохи безкоштовного алкоголю...",
    O = "Поговоріть з Реджолдом Барлібрю.",
    P = "",
    C = "$N! Пам'ятаєш, як ти приніс мені ту «Шіммервід»? Так ось, я використав її в кількох рецептах, над якими працював, і один із них вийшов просто чудовим!$B$BОсь, спробуй і скажи, що думаєш...",
},

[416] = {
    en = "Rat Catching",
    T = "Полювання на щурів",
    D = "На заході у нас справжня проблема з навалою шкідників. Кобольди-тунельні щури заселили передгір’я, облаштували там лігва і забруднюють нашу землю своїм брудом!$B$BМи хочемо, щоб їх знищили. Полюйте на них, принесіть мені їхні вуха й заробіть винагороду.$B$BКоболів-тунельних щурів та їхні лігвища ви знайдете на захід від Телсамара — вони розкидані вздовж схилу гори.",
    O = "Принесіть 12 «вух тунельної щури» альпіністу Кадреллу в Тельсамарі.",
