},

[417] = {
    en = "A Pilot's Revenge",
    T = "Помста пілота",
    D = "Хільдельве записав у своєму щоденнику, що на нього напав Мангеклоу — «величезний крижаний кігтястий ведмідь». Він відігнав звіра, але не встиг уникнути жорстокого побоїща.$B$BСудячи зі стану тіла Хільдельве, Мангеклоу, мабуть, згодом повернувся і вбив його.$B$BОднак Хільдельве записав у своєму щоденнику своє єдине, останнє бажання:$B$Bпомститися Мангеклаву.",
    O = "Вбий Мангеклоу.$B$BПринеси його «Паршиву лапу» та «Щоденник Хільдельве» Пілоту Хаммерфуту.",
    P = "Привіт, $N. Чи є у тебе якісь новини про мою подругу Хільдельве?",
    C = "Це сумна новина, адже Хільдельве був хорошим другом. Якби ж я міг бути поруч із тобою, коли ти знайшов ту bestію, Мангеклоу!$B$BДякую, $N. Твій подвиг запам’ятають пілоти Облогової бригади Айронфорджа.",
},

[418] = {
    en = "Thelsamar Blood Sausages",
    T = "Кров'яні ковбаси «Телсамар»",
    D = "У Телсамарі ніколи не бракує голодних, діти бігають туди-сюди, а робітники з розкопок заходять сюди після важкого робочого дня. Ми славимося своїми кров’яними ковбасками, мабуть, ти їх ще ніколи не куштував?$B$BНі? Ну, тут за їжу треба попрацювати, і не думайте, що тільки тому, що ви такий вишуканий $c, вам буде зроблено виняток.$B$BМені знадобиться м’ясо ведмедя, кишки кабана для оболонок та іхор павука як приправа. Принесіть мені все це, а приготування залиште Відрі!",
    O = "Принесіть 3 шматки ведмежачого м’яса, 3 качани кабана та 3 порції павукової іхори до Відра Хертстоув у Телсамарі.",
    P = "Я вже готова почати готувати, у тебе є для мене інгредієнти?",
    C = "Повірте, це набагато складніше, ніж здається, але...$B$BОй, я ще ніколи не зустрічав людей, які б так цікавилися приготуванням ковбас, але на всяк випадок дам вам рецепт. Ось, будь ласка, тільки їжте їх свіжими!",
},

[419] = {
    en = "The Lost Pilot",
    T = "Загублений пілот",
    D = "Мій друг і колега-пілот облогової машини, Морі Хільдельве, загубився в горах. Ми шукали рідкісну руду, необхідну для виготовлення високоякісного вибухового пороху, і під час пошуків він піднявся на своїй машині на крутий схил і розбив її!$B$BВсе ще переконаний, що руда була саме в цих горах, Хільдельве доручив мені охороняти наші машини, а сам продовжив пошуки пішки.$B$BМинуло вже кілька днів, і вночі я чую у горах звіряче гарчання. Морі — міцний як сталь, але я хвилююся.$B$BБудь ласка, $N. Знайдіть його.",
    O = "Знайдіть пілота Хільдельве.",
    P = "",
    C = "Ось тут лежить труп карлика — пошматований, замерзлий і обгризений гірськими хижаками. У його руці стиснута книга з недбало накиданими нотатками Морі Хільдеве. А навколо трупа, що досі перебуває у чудовому стані, лежить жилет бригадира.$B$BЦя моторошна сцена, мабуть, і стала місцем, де пілот облогової машини знайшов свою смерть.",
},

[420] = {
    en = "Senir's Observations",
    T = "Спостереження Сеніра",
    D = "Троги в тунелі надзвичайно ворожі й не вагаються нападати на мандрівників, які проходять через тунель. Але ти, здається, досить міцний, тож, мабуть, тобі нічого не загрожує.$B$BЯк туди дістатися? Якщо ти збираєшся поговорити з Сеніром, ти знайдеш його в Хараносі.$B$BПройди через тунель, а коли вийдеш з іншого боку, просто йди далі дорогою — вона приведе тебе прямо до Хараноса.",
    O = "Передайте звіт Греліна Сеніру Білобородому в Хараносі.",
    P = "Як справи? Може, вип’ємо разом? У таку холодну погоду більше нічого робити.",
    C = "Що це? А, звіт мого брата. Хм...$B$BЯ казав йому не зловживати ім’ям Короля, але він не послухав. Гадаю, нічого страшного, хоча це, безперечно, роздратує декого в Сенаті. Хоча ці «пір'я» й заслуговували на те, щоб їх розбурхати! Ха!$B$BУ будь-якому разі, мабуть, це означає, що я маю надіслати свій звіт і до Айронфорджа, але мушу зізнатися, що трохи запізнююся. Чорт забирай, як холодно.$B$BПізніше у мене, мабуть, знайдеться для тебе робота, якщо ти зацікавлений.",
},

[421] = {
    en = "Prove Your Worth",
    T = "Доведіть свою цінність",
    D = "Леді Сильвана доручила Варіматрасу завоювати землі людей і гномів на півдні.$B$BАле той дурень, Аругал — шарлатан із Даларана, а тепер проклята bestia з фортеці Тіньовий Ікло — дозволив своїй необачній магії нанести руйнівний удар по стратегічній фортеці Сріблястого Лісу.$B$BМені потрібен хтось, хто добре володіє бойовими мистецтвами, щоб допомогти навести лад після Аругала. Доведи мені свою спроможність, вбивши 5 «Місячних лютих білошкірих». Цих жахливих тварюк часто можна зустріти просто біля дороги, внизу, під схилом.",
    O = "Далар Світоткач із Гробниці просить вас вбити 5 «Місячних лютих» Білошкірих.",
    P = "Якщо ти хочеш довести мені свою спроможність, ти повинен вбити 5 «Місячних лютих» з білими скальпами. Виконай це завдання, і я подбаю про те, щоб твої здібності були використані в більш гідних справах.",
    C = "Ти добре мені послужив, $c. Для мене цілком очевидно, що ти станеш гідним помічником у моїх зусиллях позбавити Ліс Срібної Сосни прокляття Аругала.",
},

[422] = {
    en = "Arugal's Folly",
    T = "«Божевілля Аругала»",
    D = "Як Аругалу вдалося завоювати визнання в Кірін-Торі — для мене залишається загадкою. Його знання в галузі магії здавалися такими ж прозорими, як скляна іграшка, видута з повітря.$B$BЗараз важливо з’ясувати, яку саме магію використовував Аругал, щоб я міг обернути її проти нього та забезпечити Срібний Сосновий Ліс для Темної Леді.$B$BСпочатку Аругал зупинився на пшеничній фермі трохи північніше від мосту. Один із «Смертошукачів» повідомив, що бачив кілька книг заклинань, але не зміг їх забрати. Знайди для мене в цих книгах заклинання під назвою «Ліки Аругала».",
    O = "Знайдіть ліки Аругала для Далар Світоткача у Гробниці.",
    P = "Перш ніж я з’ясую, з чим ми тут маємо справу, $c, мені потрібно вивчити заклинання під назвою «Ліки Аругала». Принеси його мені негайно, інакше я буду змушений знайти собі гідного слугу.",
    C = "Це саме те заклинання, яке я шукав, $c. Якщо твоя відданість справі Темної Леді залишиться непохитною, ти побачиш, що у тебе є чудове майбутнє серед Покинутих.",
},

[423] = {
    en = "Arugal's Folly",
    T = "«Божевілля Аругала»",
    D = "Після вивчення робіт Аругала мої найгірші підозри підтвердилися. Цей старий шахрай не мав кваліфікації навіть для чищення нічних горщиків у Даларані, не кажучи вже про те, щоб представляти Кірін-Тор у найважчу годину. Дурні!$B$BАругал використовував зачаровані предмети, щоб підсилити свою слабку магію. Мені потрібно особисто дослідити ці предмети. Рушайте в дорогу й вбивайте «Місячних лютих ненажер» та «Місячних лютих темних душ», доки не зберете достатню кількість їхніх зачарованих кайданів для моїх досліджень. Цих огидних створінь бачили на півночі та сході.",
    O = "Принесіть 6 кайданів «Глуттон» і 3 кайдани «Дарксоул» Далару Доунвіверу в «Склепі».",
    P = "Мені знадобиться 6 кайданів «Жадібних» і 3 кайдани «Темних душ», перш ніж я зможу оцінити ситуацію та знайти остаточне рішення щодо Аругала. Тож виконуй моє доручення й знищуй «Жадібних Місячної люті» та «Темних душ Місячної люті», доки не збереш те, що мені потрібно.",
    C = "Сподіваюся, що мені вистачить енергії, отриманої з такого обмеженого зразка. Мабуть, мені слід було попросити тебе зібрати більше кайданів.$B$BПроте ти проявив неабияку вправність у їх зборі, $C.",
},

[424] = {
    en = "Arugal's Folly",
    T = "«Божевілля Аругала»",
    D = "Мені справді знадобиться більше часу, ніж я думав, щоб розкрити темні таємниці заклинань, якими користувався Аругал.$B$BАле тим часом мені потрібно, щоб ти розібрався з невеликою проблемою, яку виявили наші «Даркстокери». Схоже, Аругал дозволив своїй магії поширитися на шахту «Глибока Елем» у пагорбах на південному сході.$B$BЦя шахта може стати чудовим ресурсом для наступу Варіматраса.$B$BЯ хочу, щоб ти обезголовив зараженого бригадира шахти, Блідого Грімсона. З його смертю шахта стане нашою.",
    O = "Вбий Грімсона Блідого та принеси його голову Далару Світоткачу до Гробниці.",
    P = "Чи вбили Грімсона Блідого? Варіматрас не буде задоволений, якщо ми проігноруємо його наказ.",
    C = "Чудово. Ця шахта забезпечить наші війська чудовими ресурсами, коли ми будемо просуватися по Срібній Сосні та вглиб Азерота.",
},

[425] = {
    en = "Ivar the Foul",
    T = "Івар Гнусний",
    D = "Мені та моєму братові Квіну доручили провести розвідку в Лісі Срібної Сосни та доповісти про це Верховному Виконавцю Хадреку. Але далеко ми не заїхали — коли ми пробиралися через цю ферму, на нас напав гуль Івар Мерзенний.$B$BНам вдалося втекти від Івара, але він серйозно пошматував Квіна. Він одужує завдяки зіллю, яке ти йому дав, але Івар може повернутися, перш ніж Квінн одужає.$B$BВбий Івара, щоб Квінн встиг одужати. Івар зазвичай перебуває в тому сараї, чекаючи, поки я втрачу пильність.",
    O = "Вбийте Івара Мерзенного та принесіть голову Івара Ране Йоріку на «Івар-Патч».",
    P = "Ти вже вбив Івара Мерзенного? Якщо не хочеш зробити це заради мене та мого брата, то зроби це заради «Покинутих».",
    C = "Ах, дякую. Я вам дуже вдячний, $N.$B$BІ я згадаю про вас у звіті, який подаватиму своїм керівникам.",
},

[426] = {
    en = "The Mills Overrun",
    T = "«Міллс» — перевищення ліміту",
