},

[475] = {
    en = "A Troubling Breeze",
    T = "Неспокійний вітерець",
    D = "Лісом віє тривожний вітерець.$B$BГаеролас Талветрен виконує обов'язки Великого Стража друїдів «Кігтя», які перебувають у стані зимової сплячки в лігві Бан'етіл-Барроу. Його обов'язок як обраного захисника Сплячих — забезпечити їхню безпеку, щоб їхній пакт з Ісерою залишався чинним.$B$BАле звістка від Гаероласа затримується, і я починаю нервувати. Подорожуй на схід до селища Старбріз і принеси звідти звістку від Гаероласа, щоб я міг заспокоїтися, знаючи, що мої брати-мрійники спокійно сплять у безпеці.",
    O = "Знайдіть Гаероласа Талветрена в селищі Старбріз.$B",
    P = "",
    C = "Слава лісовим духам, що ти тут! Я знав, що Атрідас відчує небезпеку й надішле допомогу.",
},

[476] = {
    en = "Gnarlpine Corruption",
    T = "Корупція в Гнарпайні",
    D = "Плем'я Гнарпайн було спотворене!$B$BКолись мирні фурболги обернулися проти захисників лісу. Вони влаштували на мене засідку, коли я вирушав до лігва Бан'етіл-Барроу, а потім почали грабувати селище Старбріз. Урсал Руйнівник, їхній вождь, використовує злі сили Фель-моху, щоб звести їх з розуму.$B$BЯ занадто поранений, щоб повернутися до Атрідаса й повідомити йому цю страшну новину. Це завдання залишається за тобою, юний $c. Залишається лише сподіватися, що збожеволілі Гнарлпайни ще не дісталися до Бан'етіла!",
    O = "Поверніться до Атрідаса Беармантла в Доланаарі.",
    P = "",
    C = "Боже мій! Це справді дуже тривожно!",
},

[477] = {
    en = "Border Crossings",
    T = "Прикордонні переходи",
    D = "Як вам, мабуть, відомо, містечко Амбермілл і досі залишається осередком опору людей, головним чином завдяки підтримці, яку вони отримують від чарівників Даларана.$B$BЯ не знаю, який у них план, але те, що вони проявляють інтерес до такого загубленого селища, як Амбермілл, свідчить про те, що воно, мабуть, має якесь особливе значення.$B$BВони відправляють ящики цілими возами з Хіллсбрада. Багато з цих припасів потрапляють до невеликого табору на північ від селища Пайрвуд. Знайдіть вміст одного з ящиків і поверніть його мені.",
    O = "Дістаньте вміст однієї з скринь чарівників Даларана. На південь від вас розташоване селище Пайрвуд.",
    P = "",
    C = "<Відкривши кришку ящика, ви знайдете набір ретельно упакованих предметів. Зверху на ящику лежить пачка карт, пожовклих від часу, на яких, судячи з усього, зображено Ліс Срібної Сосни та інші частини західного Лордаерону.$B$BПід картами лежить загадковий на вигляд магічний кулон.>",
},

[478] = {
    en = "Maps and Runes",
    T = "Карти та руни",
    D = "<Ти швидко дістаєш кулон із ящика й закриваєш кришку.>",
    O = "Віднесіть цей дивний кулон до тіньового священика Алістера в Гробниці.",
    P = "Ти дізнався щось корисне, $N?",
    C = "Карти та цей... кулон, га? Цікаво.$B$BОчевидно, що чарівники Даларана з якихось причин цікавляться Амберміллом, але їхня мета мені досі залишається невідомою.$B$BМожливо, Далар щось знає про їхнє призначення.",
},

[479] = {
    en = "Ambermill Investigations",
    T = "«Ambermill Investigations»",
    D = "Далар намагається визначити джерело чарівників. А поки що нам доведеться будь-якими способами сповільнити їхній поступ...$B$BЧарівники, маги та захисники, без сумніву, носять на собі ці кулони. Зніміть їх і заберіть.$B$BРухайтеся головною дорогою на південь, а потім східною відгалуженням до Амбермілла.",
    O = "Знайдіть 8 кулонів Даларана для тіньового священика Алістера в Гробниці.",
    P = "Ми мусимо поспішати, їхні плани не повинні втілитися в життя, інакше ми можемо втратити контроль над Лісом Срібної Сосни.",
    C = "Далар виявив, що, незважаючи на невдачу, процес плетіння вже досить далеко просунувся.$B$BМагічну енергію керує чарівник великої сили. Його треба якнайшвидше зупинити.",
},

[480] = {
    en = "The Weaver",
    T = "«Ткач»",
    D = "Архімаг великої сили керує процесом відновлення вузла енергії лей-ліній. З огляду на досягнутий ними прогрес, наша єдина надія зупинити їх — це вбити його. Це буде важко, адже він, без сумніву, перебуває під захистом багатьох інших магів та охоронців.$B$BТи повинен вирушити туди й швидко з ним покінчити. Коли він загине, принеси мені його посох. Вирушай негайно.",
    O = "Вбийте архімага Даларана, а потім принесіть його посох тіньовому священику Алістеру в Гробниці.",
    P = "Швидше, час спливає, $N!",
    C = "Магія чарівників розсіюється, а енергії лей переходять у стан спокою. Твої зусилля принесли плоди, $N, і ми завдали серйозного удару нашим ворогам та зарозумілим чарівникам з Даларана.$B$BОднак ми маємо бути пильними, знаючи, що джерело енергії знаходиться так близько... Треба розробляти плани на майбутнє.",
},

[481] = {
    en = "Dalar's Analysis",
    T = "Аналіз Далара",
    D = "Віднесіть кулон Далару Доунвіверу — можливо, він зможе пролити світло на плани чарівників.",
    O = "Віднесіть кулон з рунічним написом Далару Світоткачу в Гробниці.",
    P = "Так, $C? У чому справа?",
    C = "Цікаво, схоже, це чергові інтриги Кірін-Тор. Це потужний артефакт. Його часто використовували могутні чарівники Кірін-Тор для спрямування магічної енергії.$B$BТе, що вони доставляють так багато таких артефактів до Амбермілла, свідчить про те, що вони, мабуть, реалізують якийсь масштабний проект.$B$BЯ спробую пробити їхні захисні щити й з’ясувати їхні наміри.",
},

[482] = {
    en = "Dalaran's Intentions",
    T = "Наміри Даларана",
    D = "Звичайно! Як я міг про це забути?$B$BАмбермілл був одним із місць, визначених Кірін-Тором, відомих тим, що там розташований неактивний вузол енергії лей. Чарівники, мабуть, планують реактивувати цей вузол і використати його енергію для якоїсь великої мети.$B$BМи не можемо допустити, щоб це сталося...$B$BДля активації енергій лей-ліній у цій місцевості знадобиться величезна кількість сили, тож ми можемо затримати їх, відібравши у чарівників кулони.$B$BПередайте цю інформацію Алістеру, він визначить подальші дії.",
    O = "Поговоріть із тіньовим жерцем Алістером у Гробниці.",
    P = "",
    C = "Ти приніс погані новини, $N. Якщо Далар має рацію — а в мене немає підстав вважати, що це не так — ми мусимо діяти швидко.$B$BЯ мушу порадитися з ним щодо нашого плану атаки. Але тим часом нам доведеться затримати їхній поступ.",
},

[483] = {
    en = "The Relics of Wakening",
    T = "Реліквії Пробудження",
    D = "На заході було помічено, як загарбники з Гнарпайну розорюють лігво «Банетіл Барроу».$B$BЯкщо ми не допоможемо, дрімаючі друїди назавжди залишаться у полоні Смарагдового Сну, навіть не підозрюючи про свою долю. Делікатний ритуал зимової сплячки неможливо перервати без Реліквій Пробудження.$B$BВідправляйся до Лігва та знайди Талісман Воронячого Кігтя, Перо Чорного Птаха, Сапфір Неба та Руну Гніздування. Друїди зберігають їх у священних скринях. Поверніть їх мені, і я підготую ритуал пробудження.",
    O = "Знайдіть Реліквії Пробудження та принесіть їх Атрідасу Беармантлу в Доланаарі.",
    P = "$N, викрадені друїди «Кігтя» назавжди залишаться у полоні Смарагдового Сну, якщо нам не вдасться дістати Реліквії Пробудження з лігва «Бан’етіль» на заході.$B$BЗ кожною хвилиною затримки їхня доля на крок наближається до вічної загибелі.",
    C = "Ти впорався, юний $C! Молодець. І, до речі, якраз вчасно.",
},

[484] = {
    en = "Young Crocolisk Skins",
    T = "Скіни молодих кроколісків",
    D = "Я — Джеймс Халлоран, кожум’яжник. Мої вичинені шкури кроколісків користуються попитом усюди, а партії відправляються морем до портів по всьому світу.$B$BЗустрічав Ейнара? Він — один із мисливців, які приносять мені шкури кроколісків.$B$BУ мене трохи не вистачає м’яких шкур, які отримують від молодих кроколісків.$B$BОскільки запаси у мене закінчуються, я заплачу вам найвищу ціну за стос таких шкур. Молодих кроколісків ти можеш знайти на болотах прямо за містом.",
    O = "Знайдіть 4 шкури молодих кроколісків для Джеймса Халлорана в гавані Менетіл.",
    P = "$N, так? У тебе є мої скіни?",
    C = "Ти чудово попрацював, $N. Якість цих шкір просто чудова. Мені треба якнайшвидше відправити їх на обробку. Але, перш ніж я до цього приступлю, у мене є ще одне завдання, яке, гадаю, ти міг би виконати.",
},

[485] = {
    en = "Find OOX-09/HL!",
    T = "Знайдіть OOX-09/HL!",
    D = "Ви виявили якийсь дивний металевий пристрій у формі яйця. Покрутивши одну з його ручок, ви оживили яйце — воно розкрилося, перетворившись на якийсь гномський робот-пристрій! Зсередини робо-яйця пролунав хрипкий голос.$B$B«Мене звати Оглторп Обнотікус, і мій навігаційний робот зазнав аварії! Я винагороджу вас за його повернення; будь ласка, віднесіть цей маяк до робота!»$B$B«Я щойно обчислив для вас координати робота; він розбився біля витоку річки неподалік від Скалки Скулк!»",
    O = "Віднесіть аварійний маяк до навідного робота Оглторпа, що знаходиться у верхів’ї річки в Гінтерлендсі, неподалік від Скулк-Рок.",
    P = "Схоже, ти виявив уламки... роботизованої курки? Голос ізсередини яйця знову оживає: $B$B «Так, чудова робота! Це справді мій навігаційний робот, хоча мої датчики показують, що йому потрібно трохи підзарядити, перш ніж він зможе полетіти назад до Буті-Бей для ремонту. Давай, помісти маяк усередину ровера — маяк подбає про решту!»",
    C = "Ви поміщаєте яйце… аварійний маяк… всередину курки… робота-навідника.$B$BЗсередини робота доносяться гудіння та шурхіт, коли він намагається встати. Після того, як робот оживає, знову лунає голос Оглеторпа, але тепер уже зсередини робота:$B$B«OOX-09/HL принаймні працює, але йому потрібен капітальний ремонт! Він занадто важкий, щоб ти міг його нести... але, здається, у мене є ідея. Ти готовий ще трохи доглянути за ним?»",
},

[486] = {
    en = "Ursal the Mauler",
    T = "Урсал-руйнівник",
    D = "Настав час врятувати друїдів «Кігтя». Якщо ми зараз зазнаємо поразки, $N, вони назавжди зануряться у сон.$B$BЯ підготую Реліквії Пробудження та проведу ритуал. Щоб моя робота дала результат, прокляту bestію, винну в цій жахливій ситуації, треба вбити. Лише тоді ритуал буде завершено.$B$BСаме Урсал Руйнівник втрутився у покликання наших братів, і саме Урсал Руйнівник повинен тепер заплатити за це, щоб вони могли бути звільнені. Відправляйся до фортеці Гнарпайн на південному заході й вбий його.",
    O = "Вбийте Урсала Маулера та поверніться до Атрідаса Беармантла в Доланаарі.",
    P = "Наших побратимів не можна пробудити, доки не буде вбитий Урсал Руйнівник, $N.",
    C = "$N Ти довів, що є надзвичайно гідним і здібним $C. Нічний ельф, який так непохитно, як ти, дотримується шляху честі, неодмінно знайде велику славу в цьому світі.$B$BНехай лісові духи захищають тебе, куди б не завели тебе твої мандри.",
},

[487] = {
    en = "The Road to Darnassus",
    T = "Шлях до Дарнасуса",
    D = "Дорогу до Дарнасуса необхідно убезпечити. Мандрівники, що прямують із Доланаара до Дарнасуса, повідомляють про жорстокі напади зіпсованих фурболгів із племені Гнарпайн.$B$BЦією дорогою щодня проходять важливі новини та торгові каравани, що прямують до Дарнасуса та з нього. Ми не можемо дозволити, щоб банда язичників тероризувала людей.$B$BВізьміть зброю в ім’я священного лісу, $c. Їхнє лігво знаходиться десь нижче цієї оглядової точки. Вбийте 6 таких нападників із племені Гнарпайн і повідомте мені про це.",
    O = "Знищте 6 нападників-Гнарпайнів і поверніться до вартового Амари Нічної Ходочки, що стоїть біля Доланаара.",
    P = "Дорога досі небезпечна, $c. Рушай у дорогу, знищ 6 нападників з Гнарпайну та повернися до мене.",
    C = "Ти добре служив добрим людям Доланаара та Дарнассуса, хоробрий $C. Як член загону «Вартових» Телдрасіля, я віддаю шану твоїм зусиллям.",
},

[488] = {
    en = "Zenn's Bidding",
    T = "Система ставок Zenn",
    D = "Бачу, ти дуже хочеш працювати. Тобі пощастило, адже не минає й дня, щоб я не мріяв про молодого $c, який виконував би мої доручення.$B$BРозумієш, $N, я можу зробити тебе дуже щасливим і надати тобі те, про що ти навіть не мріяв. Але для цього ти повинен принести мені певні предмети.$B$BМоя діяльність у лісі часто вимагає певних... реагентів. Принеси мені 3 ікла нічного меча, 3 пір’їни сови-стрігіди та 3 шматочки павутинного шовку з Вебвуду.$B$BНехай це залишиться нашою маленькою таємницею, $r.",
    O = "Принесіть Зенну Фоулхуфу за межі Доланаара 3 ікла нічного меча, 3 пір'їни сови-стрігіда та 3 зразки павутини «Вебвуд».",
    P = "Ти, мабуть, працювала, як бджілка, $N? Я чекала, коли ти принесеш мені те, що мені потрібно.",
    C = "Ха-ха! Ну, справді, молодець.$B$BХто б міг подумати, що я, Зенн Фоулхуф, матиму $R, який виконуватиме мої накази? Звичайно, не я! Але так воно й є... наш улюблений світ сповнений сюрпризів.$B$BТри рази «ура» наївним і довірливим!",
},

[489] = {
    en = "Seek Redemption!",
    T = "Шукайте спокути!",
    D = "Рада Лісу отримала інформацію про те, що ти допоміг Зенну Фоулхуфу. Цей сатир — ворог лісу. Як $r, ти мав би знати, що не можна оскверняти ліс, вбиваючи створінь Природи.$B$BТи мусиш виправити своє становище в очах Ради, якщо хочеш і надалі залишатися другом Телдрасіла.$B$BПрочитай Фоулхуфу урок — і ти будеш виправданий. «Фель-шишки» — це зіпсовані насіння, що падають з дерев. З них виривається зелений дим.$B$BДай кілька таких Фоулхуфу. Він подумає, що ти приніс йому нешкідливу закуску.",
    O = "Зберіть 3 «Конуси Фелу» та передайте їх Зенну Фоулхуфу, що знаходиться за межами Доланаара.",
    P = "Що ти для мене приніс, $N? Мабуть, смачний перекус?",
    C = "О, який чудовий $R! Я знав, що ти станеш у нагоді!",
},

[491] = {
    en = "Wand to Bethor",
    T = "Від Ванда до Бетора",
    D = "Колись Туле розповів мені, що давним-давно він разом із двома колегами створив чарівну палицю, сплетену з палиць-учнів, які були у кожного з магів. Ця палиця була символом їхньої дружби, і хоча Туле з часом почав її зневажати, він не міг ні розлучитися з нею, ні віддати її іншим. Тож він викрав палицю й сховав її у фортеці Фенріс.$B$BОсь. Віднеси палицю Бетору Айсшарду, одному з давніх друзів Туле. Я впевнений, що він її захоче.",
    O = "Віднесіть «Плетену паличку» до Бетора Айсшарда в «Магічному кварталі» Підміста.",
    P = "$N. Ви вже перемогли Туле Равенклоу?",
    C = "...що це таке? У Туле опинилася наша «Плетена паличка»? Я думала, що вона загубилася, коли наша дружба розпалася і він перейшов на бік Короля Ліча!$B$BМабуть, він не задіяв її силу, бо якби задіяв, я б це відчула. І добре, що він не скористався ним...$B$BЦе чудова знахідка. Я тобі вдячний, $N, і ти отримаєш нагороду.",
},

[492] = {
    en = "A New Plague",
    T = "Нова чума",
    D = "За інформацією «Смертної гвардії», щойно було захоплено ще одного з тих безглуздих гірських карликів. «Смертна гвардія» полюбляє використовувати підвал таверни «Кінець шибениці» як камеру попереднього ув’язнення, доки з в’язнями не розберуться «як слід».$B$BЧому б тобі не піти подивитися, як полонений альпініст насолоджується цим особливим напоєм, який я приготував для нього? У ньому відчувається ледь вловимий натяк на те, що Темна Леді запланувала для решти Азерота.",
    O = "Принесіть «Особливий напій Йохана» полоненому альпіністу.",
    P = "Якби у мене була моя надійна гвинтівка, ти б уже був мертвий, $C. Просто почекай, поки на допомогу мені прибуде Бригада парових танків!",
    C = "Ах, нарешті випивка. Звісно, це не «Rhapsody Malt», але в такій ситуації я готовий випити що завгодно, аби тільки втамувати спрагу.",
},

[493] = {
    en = "Journey to Hillsbrad Foothills",
    T = "Подорож до передгір’їв Хіллсбрада",
    D = "Королівське товариство аптекарів перебуває під надзвичайним тиском з боку Темної Леді, яка вимагає розробити «Нову чуму». Ми старанно працюємо і вже досягли значного прогресу. Ми переконані, що успіх буде досягнуто набагато швидше, якщо ми будемо обмінюватися інформацією всередині Товариства.$B$BСаме тому я хочу, щоб ти доставив мої останні відкриття аптекарю Лайдону в Таррен-Міллі — невеликому містечку, розташованому в передгір’ях Хіллсбрада. Подорож буде довгою.$B$BРухайся на південь і тримайся доріг. Уважно слідуй за вказівниками!",
    O = "Передайте висновки аптекаря Ренферела аптекарю Лайдону в містечку Таррен-Мілл, що в передгір'ях Хіллсбрада.",
    P = "У тебе для мене щось є?",
    C = "Ах, чудово. Аптекар Ренферел заслуговує на мою найглибшу повагу. Я з нетерпінням чекаю на можливість ознайомитися з його роботами.",
},

[494] = {
    en = "Time To Strike",
    T = "Час діяти",
    D = "Замовкни і слухай уважно, $c.$B$BМене відправили на цю позицію, щоб провести розвідку міста Гіллсбрад. Моє завдання — розвідка. Тобі необхідно негайно передати повідомлення Верховному виконавцю Дарталії в Таррен-Міллі. Передай їй, що я, Смертоносець Леш, надсилаю таке повідомлення:$B$B«Крик ворона із заходу кличе».$B$BЙди дорогою на схід і уважно стеж за знаками. А тепер поспішайте! Рушайте до Таррен-Мілл, і, до речі, якнайшвидше!",
    O = "Відправляйся до Таррен-Мілл, щоб передати повідомлення Леша «Смертошукача» Верховному виконавцю Дарталії.",
    P = "",
    C = "Чи не кличе нас крик ворона із заходу?$B$BЧудова новина! Гіллсбрад готовий до нападу. Тепер ми можемо втілити наш план знищення. Варіматрас буде задоволений.",
},

[495] = {
    en = "The Crown of Will",
    T = "Корона Волі",
    D = "Муг'Тол та його загін огрів були відправлені до Альтерака, щоб повернути Корону Волі для леді Сильвани. На жаль, замість того, щоб повернути її, цей ідіот вирішив приміряти її на себе... Мабуть, огри не можуть встояти перед усім, що блищить і сяє.$B$BОднак його незграбні вчинки стали справжньою проблемою. «Корона Волі» дозволила йому протистояти закляттю, накладеному на нього, щоб служити леді Сильвані.$B$BТемна Леді хоче, щоб його покарали як приклад. Подорожуйте до Таррен-Мілл у Хіллсбраді та звітуйте моїй заступниці Мелісарі.",
    O = "Зверніться до Мелісари в Таррен-Міллі, що в передгір’ях Хіллсбрада.",
    P = "",
    C = "Тебе прислала Шаліндра? Що ж, тоді ти переконаєшся, що я не витрачаю багато часу на пусті балачки.$B$BМуг’Тол — справжня прикра, і ми розберемося з ним швидко, досконало і без зайвих ускладнень.",
},

[496] = {
    en = "Elixir of Suffering",
    T = "Еліксир страждання",
    D = "Ах, ще один жахливий день у Таррен-Міллі. Усе це чисте повітря так мене дратує, $N.$B$BЧим швидше ми зможемо заразити тут людей, тим краще. Я інтенсивно досліджував можливі отруйні речовини для використання у своїх зіллях, але в мене немає часу зібрати їх усі.$B$BЯкщо хочеш бути корисним, дістань для мене такі предмети: 10 язиків сірого ведмедя та дуже рідкісну й важкодоступну іхору повзуна. І ведмедів, і повзунів ти знайдеш неподалік від Таррен-Мілл.",
    O = "Аптекар Лайдон із Таррен-Мілл потребує 10 язиків сірого ведмедя та трохи іхору повзуна.",
    P = "Бачу, ти повернувся. Сподіваюся, тобі вдалося зібрати тих агентів, які мені потрібні. Ще один день без смертей — і я впаду в такий похмурий настрій.",
    C = "Ці зразки просто ідеальні. Що ж, $N, тобі вдалося подарувати мені хоч найменший проблиск радості в черговий похмурий день. Я ціную твої зусилля.",
},

[498] = {
    en = "The Rescue",
    T = "Рятувальна операція",
    D = "Вождь відправив мене та ще кількох воїнів до Дурнхолда, щоб забрати там певний предмет і розібратися з цим так званим «Синдикатом».$B$BМи вирушили до Дурнхолда, щоб розвідати обстановку, але нас застали зненацька великі сили людей. Ми хоробро билися, але їхня чисельна перевага виявилася вирішальною. Кількох із нас взяли в полон, але мені вдалося втекти.$B$BДурнхолд розташований на південний схід від цього місця, за річкою. Там утримують Друлла та Тог'тара, тож ти мусиш вирушити туди й врятувати їх.",
    O = "Круск у Таррен-Міллі просить тебе звільнити Друлла та Тог'тара з фортеці Дурнхолд.",
    P = "Тобі треба поспішати, $C. Мені страшно навіть уявити, що люди можуть робити з Друллом і Тог'таром.",
    C = "Тож люди вирішили перетворити наших воїнів на рабів, так? Ми їм покажемо!$B$BСхоже, вони вивезли Гол’діра, нашого ватажка, в інше місце. Ми мусимо знайти його й врятувати. Але наразі ми не маємо жодного уявлення, де він перебуває...$B$BКоли у нас з’явиться якась зачіпка, я обов’язково тобі про це скажу, $N.",
},

[499] = {
    en = "Elixir of Suffering",
    T = "Еліксир страждання",
    D = "Мені знадобиться лише мить, щоб змішати ці компоненти в те, що я назвала «Еліксиром страждання».$B$BОсь і готово! Ах, ніщо так не розяснює похмурий день у цих жалюгідних передгір’ях, як привнести у світ трохи страждань.$B$BПодивимося, чи наш маленький зілля досяг бажаного ефекту.$B$BНехай мій помічник Умпі відчує на собі те, що Темна Леді запланувала як для людей, так і для Покарання.",
    O = "Дай Умпі еліксир страждання.",
    P = "Ква-ква!",
    C = "Ква-ква!",
},

[500] = {
    en = "Crushridge Bounty",
    T = "«Crushridge Bounty»",
    D = "Огри з Крушріджа викопали огрівський курган у горах Альтерак, неподалік від зруйнованого міста Альтерак. А мої розвідники повідомляють, що вони також захопили ці руїни.$B$BМи не можемо дозволити їм там затишно влаштуватися; якщо вони вважатимуть, що там у них безпечно, то їхнім наступним кроком стане спуск у передгір’я, і тоді вони опиняться прямо під нашими дверима!$B$BРушайте на північ, до Альтеракських гір, і полюйте на огрів. Принесіть мені «Брудні кісточки», які вони носять із собою, і ви отримаєте гарну винагороду.",
    O = "Зберіть 9 брудних кісточок від огрів у Крушріджі в горах Альтерак. Принесіть їх маршалу Редпату в Саутшорі.",
    P = "$N, ти досі полюєш на огрів? Ти вже зібрав ті кісточки, які я тебе просив зібрати?",
    C = "Дуже добре, $N Ти, мабуть, пробився крізь цілу зграю огрів, щоб зібрати всі ці кістки.$B$BЦе має утримати їх подалі від нас. Принаймні, на деякий час.",
},

[501] = {
    en = "Elixir of Pain",
    T = "Еліксир болю",
    D = "О, $N... У Хіллсбраді розквітають квіти, а повітря таке свіже й бадьоре. Я не можу не поринути у відчай від усього цього. Я дивлюся крізь своє забруднене вікно й мрію про той день, коли наша Нова Чума принесе цьому світу смерть, на яку він заслуговує.$B$BХоч як би мені хотілося сидіти й замислюватися цілий день, мій обов’язок перед Темною Леді кличе мене. Допоможеш мені, будь ласка? Мої дослідження дають підстави вважати, що з крові пуми я зможу зварити найчудовіше зілля смерті. Принеси мені трохи, і ми трохи розважимося.",
    O = "Принесіть 10 флаконів «Крові пуми» аптекарю Лайдону в Таррен-Міллі.",
    P = "Я пам'ятаю тебе, $N. Ти мав допомогти мені у приготуванні мого нового еліксиру. Мені знадобиться ця кров, перш ніж я зможу обдарувати мешканців Хіллсбрада своїм особливим видом страждань.",
    C = "Чудова колекція, $N.",
},

[502] = {
    en = "Elixir of Pain",
    T = "Еліксир болю",
    D = "Ах, немає нічого кращого за запах свіжої крові в передгір’ях!$B$BТепер додамо трохи того й трохи цього — і нехай почнеться справжня веселість! Те, що я створила з цієї крові, я люблю називати «Еліксиром болю». Якщо мої розрахунки правильні, ця суміш може стати початком чогось дуже прекрасного для леді Сильвани. Але нам потрібно провести випробування.$B$BВіднеси цей еліксир на північну ферму в Хіллсбрадських полях, що на південному заході. Подивимося, як маленькому собаці фермера Рея, Стенлі, сподобається цей «ласощі».",
    O = "Дай Стенлі «Еліксир болю».",
    P = "Гав?",
    C = "Ти наливаєш трохи еліксиру на долоню і підносиш її до рота Стенлі.",
},

[503] = {
    en = "Gol'dir",
    T = "Гол'дір",
    D = "З того, що я можу судити з документів, які ви дістали, Голдір утримується на великій базі Синдикату на півночі, найімовірніше, в горах Альтерак. Він перебуває в полоні вже занадто довго, і його треба звільнити.",
    O = "Звільніть Гол’діра, а потім поверніться до Круска в Таррен-Міллі.",
    P = "Дай мені ключ, $C, я сам відімкну замок.",
    C = "Дякую, $N. Я очолював експедицію з Дуротара за наказом Вождя, але, як бачиш, наші плани дещо зійшли з колії. Мене утримують у полоні тут, у цьому містечку, змушуючи працювати: тягати вантажі, копати...$B$BОднак те, що я пережив, не має значення. Є важлива інформація, яку ти повинен передати тому, хто зараз очолює нашу групу.",
},

[504] = {
    en = "Crushridge Warmongers",
    T = "«Крушрідж»: підбурювачі війни",
    D = "Тепер, коли ти вже познайомився з ограми з Крушріджа, я хочу, щоб ти по-справжньому розбив їм носи...$B$BЗайдіть у Руїни Альтерака й знайдіть войовничих велетнів з Круш-Риджа. Я хочу, щоб ви знищили чималу їх кількість — тільки так ці брутальні велетні навчаться триматися подалі від території Альянсу.",
    O = "Знищте 15 войовничих мешканців Крушріджа, а потім поверніться до маршала Редпата в Саутшорі.",
    P = "Тобі ще треба вбити більше войовничих, $N. Ти мав би бути в горах, виконуючи своє завдання, а не тут, з прибраною зброєю.",
    C = "Дуже добре. Ось твоя нагорода.$B$BА коли ти полював на тих «Військових», як виглядало місто Альтерак? Гадаю, воно в жахливому стані. Огри не славляться своєю охайністю.$B$BНа щастя, ваші зусилля допоможуть утримати їх подалі від Південного берега.",
},

[505] = {
    en = "Syndicate Assassins",
    T = "Вбивці синдикату",
    D = "Я — новий магістрат Саутшора, якого нещодавно призначили на цю посаду після вбивства попереднього магістрата. Вбивць так і не знайшли, але завдяки нашим розслідуванням ми майже впевнені, що їх найняв «Синдикат» — угруповання злодіїв, очолюване підступними аристократами з нині занепалого королівства Альтерака.$B$B«Синдикат» має табір на північ від зайнятого Ордою Таррен-Мілл, і наші останні підказки привели нас саме до цього табору. Знищте членів «Синдикату», яких ви там знайдете.",
    O = "Вбийте 12 бандитів-піхотинців синдикату та 8 злодіїв синдикату, а потім поверніться до магістрата Генрі Малеба в Саутшорі.",
    P = "Сподіваюся, ти вбив тих бандитів із «Синдикату»?",
