[539] = {
    en = "Battle of Hillsbrad",
    T = "Битва за Хіллсбрад",
    D = "Згідно з даними реєстру міста Хіллсбрад, шахта «Лазуровий жила» перебуває під контролем Альянсу. Крім того, ця шахта є головним джерелом залізної руди для зброярських майстерень Альянсу.$B$BНезважаючи на те, що ми завдали вирішального удару по місту Хіллсбрад, Альянс все ще палко підтримує та захищає шахту «Лазуровий рудник».$B$BШахта розташована прямо на південь від Хіллсбрада. Відправляйтеся туди й убийте бригадира — людину на ім’я Бондс. Убийте також і його шахтарів. Це має стати чітким сигналом для Альянсу.",
    O = "Вбийте Формана Бондса та 10 гірників з Хіллсбрада, а потім поверніться до Дарталії в Таррен-Міллі.",
    P = "Тобі було дано прямий наказ атакувати шахту «Азурлоуд». Твої причини для того, щоб байдикувати в Таррен-Міллі, мають бути вагомими, інакше я відрубаю тобі голову за зраду.",
    C = "«Темна Леді» буде задоволена, коли дізнається, що у неї з’явилася нова шахта, з якої вона зможе озброювати своїх солдатів.",
},

[540] = {
    en = "Preserving Knowledge",
    T = "Збереження знань",
    D = "Ці жахливі огри тепер мешкають у руїнах Альтерака, і мене аж морозить від думки про те, що вони роблять із дорогоцінними книгами, які там ще залишилися. Ти повинен знайти все, що зможеш!$B$BЗайди в руїни Альтерака й пошукай фоліанти, розграбовані ограми. Візьміть усе, що зможете знайти, і принесіть мені, але також пошукайте одну конкретну книгу: «Рука Грі'лека». Вона містить стародавні знання тролів, які я мушу вивчити, а руїни Альтерака були останнім відомим місцем, де зберігався неушкоджений примірник цієї книги.",
    O = "Принесіть 5 відновлених фоліантів та зношену шкіряну книгу, що містить «Руку Грі'лека», до майстра знань Діббса в Саутшорі.",
    P = "Я б теж хотів обшукати руїни, але боюся, що ці кістки не витримають мене під час сходження в гори. А як просувається твоє прагнення до знань, $N?",
    C = "О, ти їх знайшов! Чудово! Я мушу негайно почати вивчати «Руку Грі'лека»!",
},

[541] = {
    en = "Battle of Hillsbrad",
    T = "Битва за Хіллсбрад",
    D = "Гноми допомагають людям? Хай їх чорт забере, цих брудних маленьких тварюк.$B$BМи перевіримо силу так званого Альянсу. Побачимо, наскільки ці маленькі набридливі тварюки будуть охочі допомагати людям, коли відчують наш гнів. Ми точно знаємо, де на цій території розташована їхня фортеця.$B$BВони облаштували казарми на південному сході Хіллсбрада, вздовж Стіни Торадіна, під назвою Дун Гарок. Остаточне завдання цієї битви — взяти в облогу Дун Гарок, $c. Капітан Айронхілл, їхній ватажок, має загинути.",
    O = "Відправляйтеся до Дун-Гарока, вбийте 10 альпіністів, 8 стрільців, 4 священиків та капітана Айронхілла, а потім поверніться до Дарталії в Таррен-Міллі.",
    P = "Дун Гарок виявився для тебе занадто серйозною перешкодою, $C? А я ще думала, що ти достойно зарекомендував себе в Хіллсбраді.$B$BЯкщо ти не в змозі впоратися з дорученим тобі завданням, я знайду іншого, хто зможе досягти кращих результатів. Що стосується тебе, то я впевнений, що Темній Леді завжди знадобляться ще кілька могильників у Тирісфальських гаях.",
    C = "Ваші дії на полі бою заслуговують на найвищу похвалу.",
},

[542] = {
    en = "Return to Milton",
    T = "Повернутися до Мілтона",
    D = "Мені потрібно трохи часу, щоб вивчити книгу «Рука Грі’лека», яку ти мені приніс, хоча я впевнений, що Мілтон з нетерпінням чекає, коли інші знайдені книги потраплять до колекції Штормграда.$B$BОсь книги, які ти зібрав у Руїнах Альтерака — вони вже упаковані та каталогізовані. Віднеси їх Мілтону Шифу в Штормграді, і я впевнений, що він буде тобі вдячний.",
    O = "Принесіть «Томів Альтерака» Мілтону Шифу в Штормграді.",
    P = "$N, ти повернувся! Як пройшла твоя вилазка в Альтерак? Ти щось привіз із собою?",
    C = "Ой-ой! Тільки погляньте на це! Не можу повірити, що вони вціліли після руйнування Альтерака. І всі ці огри теж!$B$BДякую, $N. Дуже дякую! Ти допоміг зберегти знання людства і додав величі Королівській бібліотеці Штормвінда.",
},

[543] = {
    en = "The Perenolde Tiara",
    T = "Тіара Перенольде",
    D = "Тіара Перенольде — це старовинна родинна реліквія «знаті» Перенольде — правлячої династії Альтерака до того, як це королівство занепало. Кажуть, що її виготовили майстри-ювеліри в Айронфорджі та оздобили найдосконалішими смарагдами.$B$BКоли Альтерак був зруйнований, тіара зникла, але ходять чутки, що маг-огр Грельборг Скупий знайшов її і тепер блукає руїнами Альтерака у пошуках інших скарбів.$B$BМи хочемо, щоб ви знайшли цю тіару для нас.",
    O = "Принесіть тіару Перенольде Ремінгтону Ріджвелу в Штормвінд.",
    P = "Вітаю, $N. Будь ласка, намагайся не наступати на манжети моїх штанів. Цей костюм щойно пошитий.",
    C = "О, це чудово. Звісно, її доведеться почистити, але ти справді перевершив себе, $N. Я доручу комусь підготувати тіару й якнайшвидше додати її до нашої колекції.$B$BЯ впевнений, ти погодишся, що наша вдячність така ж велична, як і наша колекція.",
},

[544] = {
    en = "Prison Break In",
    T = "Вторгнення до в'язниці",
    D = "Я прибув до Таррен-Мілл з науковою місією, але тепер мушу вирішити кризову ситуацію. Справа в тому, що кілька місяців тому четверо Покинутих втекли з Підмістя. Вони зрадили своїх побратимів, але що ще гірше... вони вкрали скарби у Темної Леді.$B$BЦі злодії проникли в надійно охоронюване сховище й викрали чотири артефакти — предмети, необхідні нашим аптекарям для певних досліджень. Сільвана вимагає повернути ці артефакти.$B$BЗлодії втекли з Підміста до Даларана, і тамтешні чарівники помістили їх у карантин у таборі для інтернованих «Лордамер».",
