[579] = {
    en = "Stormwind Library",
    T = "Бібліотека Штормграда",
    D = "",
    O = "",
    P = "Король Андуїн приділяє велику увагу освіті, тому виділив кошти на виготовлення копій різних фоліантів і праць, які будуть доступні для широкої громадськості. Все дуже просто. Принесіть мені бібліотечний талон, і я надам вам копію однієї з доступних книг.",
    C = "Чи зацікавила тебе якась із цих книг, $N?",
