[580] = {
    en = "Whiskey Slim's Lost Grog",
    T = "«Загублений грог» Віскі Сліма",
    D = "Ми там не по-дрібному наливали собі за душу біля скель Оверлук, а старі Хінтерленди виднілися десь удалині. Здавалося, що море ось-ось проковтне нас цілком.$B$BСтарий Слім знає все про «рідку сміливість»! У капітана була ящик портвейну «Пупеллівербос», який ми конфіскували у капера, що прямував до Штормвінда.$B$BТож коли біля Замежжя розігралася буря, я накинувся на грог. Велика хвиля вдарила і викинула ті пляшки за борт. Капітан дасть мені прочуханки, якщо ви не допоможете мені їх повернути!",
    O = "Віскі Слім із Буті-Бей просить тебе принести йому пляшки портвейну «Пупеллівербос», які він загубив.",
    P = "Чорт забирай! У мене тут майже закінчився алкоголь! Капітан збирається підняти якір, а старий Слім залишиться сухим, як пустеля Танаріс. І коли він виявить, що його порт зник... Ой-ой-ой!",
    C = "О, хай мені дерева! Ти знайшов грог капітана!$B$BЯ тобі дуже в боргу, друже.$B$BСхоже, надворі назріває буря. Може, я просто зігріюся однією з цих пляшок, поки чекаємо, поки вона мине....",
},

[581] = {
    en = "Hunt for Yenniku",
    T = "Полювання на Єнніку",
    D = "Прокляття, безперечно, існує. Доля, що спіткала наймолодшого сина мого вождя, Єнніку. Згідно зі звичаєм нашого народу, його віддали тролям Гурубаші із Зул'Гуруба, але після того, як моє плем'я, плем'я Темних Списів, пішло разом з орком Тралом, ми втратили бідного Єнніку. Мене відправили з далекого Оргримара назад до Странглторна, щоб я розшукав сина мого вождя.$B$BІ я вважаю, що він перебуває у племені Кровоскалів.$B$BЯкщо ти хочеш мені допомогти, то полюй на «Криваві скальпи». Ти можеш знайти їх на півночі. Збери їхні бивні та повернися до мене.",
    O = "Принесіть 9 бивнів «Кровавої шерсті» Німбої у табір «Гром’гол».",
    P = "$C. Доведи мені, що ти здобув трофеї у племені «Криваві скальпи».$B$BПокажи мені свої трофеї.",
    C = "Це чудові бивні, $N. Ти довів, що маєш силу полювати на Кровоскальпів.$B$BІ це добре, адже ти ще не закінчив полювання на них.",
},

[582] = {
    en = "Headhunting",
    T = "Пошук керівників",
    D = "Ми мусимо з’ясувати, чи загинув Єнніку.$B$BЗнищте мисливців за головами «Криваві скальпи» та заберіть у них їхні зморщені голови. Ти повинен зібрати дуже багато голів, а я перевірю їх, щоб переконатися, що серед них немає голови Єнніку.$B$BА якщо Єнніку вбили «Криваві скальпи», нехай 600-річне прокляття впаде на дух їхнього вождя, Ган’зули!$B$BІди, $N. Ти можеш знайти багато мисливців за головами в руїнах Зуулдаї та Зул’Кунди, вздовж узбережжя на півночі.",
    O = "Принесіть 20 зменшених голів Німбої в табір Гром'гол.",
    P = "$N. Я хвилююся за сина нашого вождя. Чи є у вас зморщені голови, щоб я міг їх оглянути?",
    C = "Дякую, $N. Я огляну ці голови, щоб переконатися, що бідолашному Єнніку вдалося уникнути сокири мисливця за головами.",
},

[583] = {
    en = "Welcome to the Jungle",
    T = "Ласкаво просимо до джунглів",
    D = "Ласкаво просимо до Странглторна!$B$BМожливо, ти цього не знаєш, але той карлик он там — це сам Хемет Несінгварі, видатний військовий герой Альянсу та майстер полювання на велику дичину. Він не з тих, хто радо приймає незнайомців у своєму таборі, але ви, здається, бачили в своєму житті чимало пригод, $c.$B$BСам будучи ветераном багатьох битв, майстер Несінгварі з теплотою ставиться до своїх побратимів-героїв.$B$BПідійдіть і поговоріть з ним. Можливо, він дасть вам кілька порад щодо полювання.",
    O = "Поговоріть з Хеметом Несінгварі.",
    P = "",
    C = "Дуже приємно познайомитися з тобою, $n. Давно вже не бачив $c у цих краях.$B$BЯ приєднався до цієї експедиції з однією метою: полювати на велику й невловиму тварину. Оскільки ти, здається, герой, я готовий дозволити тобі взяти участь у полюванні, але спершу ти маєш довести свою спроможність.$B$BЯ навчу тебе, як вбивати хижаків. Аджек навчить тебе полювати на тигрів. А сер Ерлгадін — майстер у вистежуванні пантер.$B$BДоведи свою майстерність, і я допущу тебе до великого полювання.",
},

[584] = {
    en = "Bloodscalp Clan Heads",
    T = "Вожді клану «Кривава Шкіра»",
    D = "Єнніку не було серед тих, чиї голови принесли, і я дякую Великому Змію за це. Але ми ні на крок не наблизилися до того, щоб знайти його.$B$BМи мусимо дізнатися правду, і я боюся, що її знають лише вождь «Кривавих Скальпів» та його знахар. Вони — вороги племені Темних Списів і не будуть говорити відверто, тож ми мусимо вирвати правду з їхніх мертвих вуст!$B$BПринесіть мені голови Ган’зули та Незліока Жахливого й покладіть їх у цей казан.$B$BВони перебувають у глибинах Зул’Кунди. Принесіть їхні голови… тоді ми змусимо їх говорити.",
    O = "Принесіть голову Ган'зули та голову Неззліока до киплячого казана в таборі Гром'гол.",
    P = "У казані булькає зеленуватий відвар.",
    C = "Ви кладете голови Ган'зули та Неззліока у казан...",
},

[585] = {
    en = "Speaking with Nezzliok",
    T = "Розмова з Неззліоком",
    D = "<Говорить вождь Неззліок.>$B$BЦе правда. Я знаю, куди викрали дитину з роду Даркспірсів. Ти переміг мене і скував мій дух, але я нічого не скажу, поки не отримаю винагороди!$B$BКровоскальпи воюють зі Скаллспліттерами. Щоб здобути мою прихильність, викрадіть у «Розколювачів Черепів» 3 їхні трофейні черепи та принесіть їх сюди, до нас, щоб мій дух мав рабів у Нетері. Один череп має бути з їхньої купи трофеїв у Балія’ма, інший — із Зіата’джай, а останній — із Зул’Мамве.",
    O = "Принесіть трофей «Балія'мах», трофей «Зіата'джай» та трофей «Зул'Мамве» до «Булькаючого казана» у базовому таборі Гром'гол.",
    P = "Я чекаю на черепи...",
    C = "Так. Вони мені добре знадобляться. Коли мій дух звільниться, я увійду до Нетера разом із трьома чудовими слугами!$B$BТи робиш честь своєму $R клану, і ти задобрив мене.",
},

[586] = {
    en = "Speaking with Gan'zulah",
    T = "Розмова з Ган'зулою",
    D = "<Говорить ватажок Ган'зули.>$B$BХай тебе проклянуть! І хай проклянуть твоїх предків!!$B$BЛише кров і помста можуть вгамувати мій гнів, тож якщо це твоє бажання, то... зроби ось що:$B$BКинься в саме серце «Розколювачів Черепів» на сході. Вбий найлютіших серед них, і якщо ти виживеш... то зіткнися з їхнім вождем, Ана’теком Жорстоким. Ха! Принеси мені його розтрощені обладунки, якщо зможеш!$B$BНехай він відірве тобі кінцівки й залишить тебе гнити й бути з’їденим хижаками.",
    O = "Вбийте 8 мисливців «Розбивачів черепів», 6 мисливців за головами «Розбивачів черепів» та 4 берсерків «Розбивачів черепів».$B$BПринесіть пошкоджену броню Ана'тека до «Булькаючого казана» у базовому таборі Гром'гол.",
    P = "Хоча моє власне тіло випаровується з мого черепа, я все одно відчуваю запах твого страху.$B$BХа! Ти ніколи не виконаєш моє завдання...",
    C = "Я не хочу в це вірити, але не можу заперечувати те, що ти зробив. І моя лють вщухає, тепер, коли Ана’тек переможений. $B$BТвоя сила спонукатиме тебе до великих подвигів, $N. Але одного дня...Я зустріну тебе в Нетері, і ми знову зійдемося в двобої.$B$BЯ чекатиму.",
},

[587] = {
    en = "Up to Snuff",
    T = "На висоті",
    D = "Ах, морське життя. Не скажу, що це ідеальне життя, але це моє життя.$B$BКоли я припливаю до порту, мені подобається знайти собі гарну пляшку грогу та трохи високоякісного нюхального тютюну. Погані звички, але що ж таке пірат без своїх пороків, правда?$B$BТож ви можете уявити, як мені було прикро, коли я дізнався, що травник у цьому містечку зник, а його товар розпродався. Каже, що його вантаж перехопили ці кляті «Криваві вітрила».$B$BГотовий побитися об заклад, що такий безстрашний $c як ти зміг би переконати їх поділитися товаром, еге ж?",
    O = "Діг із Буті-Бей просить вас принести йому 15 порцій снуфу.",
    P = "Тобі пощастило знайти те, що шукав, друже?",
    C = "Чудово, $N! І це якраз перед тим, як мені теж доведеться вирушати! Не знаю, як тобі віддячити, старий друже.",
},

[588] = {
    en = "The Fate of Yenniku",
    T = "Доля Єнніку",
    D = "<Говорить Неззліок.>$B$BТи задовольнив мене та мого вождя, тож я розповім тобі те, що ти прагнеш дізнатися...$B$BМолодий Єнніку зник з свого клану.$B$BЙого викрав чаклун Занзіл-Ізгой. Тепер Занзіл контролює його, тіло й душу, і лише найпотужніша магія зможе звільнити його.$B$BМагії, якої у тебе немає, $c.$B$BМожливо, твої союзники з племені Темних Списів можуть дати надію на порятунок Єнніку. Але я в цьому сумніваюся.",
    O = "Поговоріть із Кін’вілеєм.",
    P = "",
    C = "Занзіл-вигнанець??$B$BЯкщо Єнніку утримує той троль — підлий і могутній знахар, — то, боюся, залишається лише слабка надія. Слабка. І крихітна, як найменша комаха.$B$BАле все ж це надія.",
},

[589] = {
    en = "The Singing Crystals",
    T = "Співаючі кристали",
    D = "Легенди розповідають про коштовність, заховану глибоко в самому серці Стренглторна. Ми називаємо її «Оком Розуму», і вона володіє величезною силою. Якщо ти здобудеш це Око, то, можливо, ми зможемо використати його, щоб повернути зниклих Єнніку з темряви.$B$BЯ пораджуся з духами джунглів, щоб знайти «Око Розуму». Поки я це робитиму, ти зайди до шахти «Кришталева жила», що на південному сході від нас, і збери «Пульсуючі блакитні осколки» у залізнощелепних базилісків. Ці осколки рідкісні, але нам знадобиться їхня магія, щоб підкорити «Око Розуму» нашій волі.",
    O = "Принесіть 3 пульсуючі блакитні осколки Кін’вілею в табір Гром’гол.",
    P = "У тебе є осколки, $N? Вони знадобляться для мого останнього ритуалу, після того як ми отримаємо «Око Розуму».",
    C = "Ти добре впорався, $N. Ці осколки мають гарну форму. Я вже чую, як вони співають мені.$B$BІ поки тебе не було, я розмовляв із духами джунглів. Я знаю, де спочиває «Око Розуму»...$B$B...І хто його охороняє.",
},

[590] = {
    en = "A Rogue's Deal",
    T = "Угода шахрая",
    D = "Що?$B$BЩо?!$B$BТи хочеш грошей? Я тобі нічого не винен.$B$BЛист? Який лист? А, то ти хочеш побитися? Гаразд, друже... давай поб’ємося! Я тобі нічим не винен...",
