[902] = {
    en = "Samophlange",
    T = "Самофланж",
    D = "Відкривши передню панель консолі управління, ви бачите щільне сплетіння дротів, трубок та інших дивних механічних предметів — більшість із яких, здається, не мають жодного практичного призначення. Відсунувши їх убік і заглянувши глибше в консоль, ви знаходите самофланж. Один ривок — і він виймається з корпусу.",
    O = "Поверни «Самофланж» Спутервалу в Ратчеті.",
