[927] = {
    en = "The Moss-twined Heart",
    T = "Серце, оповите мохом",
    D = "Серце Блекмосса Смердючого вкрите темним, маслянистим мохом. Насправді, єдиний спосіб розпізнати, що це серце, — це його повільне, ритмічне биття… Биття, яке триває навіть зараз.$B$BМожливо, Деналан захоче подивитися на це серце.",
    O = "Принесіть «Серце, обплетене мохом» Деналану біля озера Аль-Амет.",
