[940] = {
    en = "Teldrassil",
    T = "Телдрасіл",
    D = "Ліс шепоче про твої подвиги, $n. Коли я відчув, як гарпії були вигнані зі своїх гнізд, у лісі запанував ще більший спокій, і його мешканці знову відчули себе в безпеці. Я боявся відправляти ще одного посланця до Верховного Друїда, але знаю, що ти безпечно донесеш моє послання до нього.$B$BПередай це йому і знай, що ліс захистить тебе на твоєму шляху до Кам’яного лісу.",
    O = "Передайте звіт про Дерево Оракула верховному друїду Фандралу Стагхельму в Дарнассусі.",
    P = "Хм... Ти випромінюєш сильний дух лісу, $C. Яка у тебе справа до Верховного друїда калдореїв?",
    C = "Я замислився, чому Дерево Оракула так довго не зв’язувалося зі мною... Схоже, що деякі проблеми втрачають актуальність, тоді як інші переростають у ще більші турботи.$B$BЯ боюся, що моя робота над Телдрасілом ніколи не буде завершена, а наше безсмертя — ніколи не відновлено.$B$BПроте ти добре виконав завдання Дерева Оракула і заслуговуєш на нагороду за свою старанність.",
