[942] = {
    en = "The Absent Minded Prospector",
    T = "Розсіяний золотошукач",
    D = "Ця скам'янілість разюче схожа на ту, яку я колись бачив в Айронфорджі. Археолог на ім'я Флагонгут приніс її на нашу щорічну конференцію Ліги дослідників. Він вважав, що ця скам'янілість має силу, яку можна якось розкрити.$B$BЗ останніх новин я знаю, що Флагонгут затаївся в таверні «Глибока вода» у гавані Менетіла, чекаючи на супровід до місця розкопок у Велгарі. Знайдіть його та покажіть йому скам’янілість Ремтревела. Можливо, він зможе розкрити таємниці минулого.$B$BКорабель до Менетілу відпливає з Терамора.",
    O = "Віднесіть цю загадкову скам’янілість археологу Флагонгуту в гавані Менетіл.",
    P = "Що там у тебе, друже?",
    C = "Ой! Ти кажеш, це привезли з далеких земель Калімдору?$B$BНеймовірно! Просто неймовірно!",
},

[943] = {
    en = "The Absent Minded Prospector",
    T = "Розсіяний золотошукач",
    D = "Золотошукач Велгар тепер зберігає оригінальну скам’янілість на своїй ділянці у Водно-болотних угіддях. Коли я виявив Камінь Релу, я вважав, що це ключ до розгадки таємниці скам'янілості.$B$BПоки я подорожував дорогою, щоб зустрітися з Велгаром, на мене напали раптори, і реліквія загубилася. Я не знаю, яка саме з цих плямистих bestii проковтнула реліквію, але якщо ти зможеш її повернути, я зможу розкрити силу цих артефактів.$B$BПринеси мені і Камінь Релу, і оригінальну скам’янілість, яку він зберігає.",
    O = "Археолог Флагонгут у гавані Менетіл просить вас принести йому Камінь Релу та скам’янілість Флагонгута.",
    P = "За допомогою Каменя Релу я зможу розкрити приховані таємниці своєї скам’янілості, а також скам’янілості Ремтревела з Темного Берега, $N.",
    C = "Чудово, $N!$B$BТепер подивимося, чи зможу я за допомогою каменю розгадати таємницю сил скам’янілостей.",
},

[944] = {
    en = "The Master's Glaive",
    T = "Глейв Майстра",
    D = "Дивно, що наги опинилися тут, у Темному березі. Але ще дивнішими... є «Молот Сутінків». Цей культ поклоняється давнім-давнім володарям землі. Повелителі, переможені ще дуже давно.$B$B«Глейв Майстра», що на півдні, — це місце, де загинув один із таких древніх повелителів.$B$BВідправляйся туди й пошукай ще більше послідовників культу «Молота Сутінок».$B$BВізьми цю флакончик для ворожіння. Використовуй його, щоб створити чашу для ворожіння після обшуку «Глейва Майстра». Потім звернися до мене через цю чашу.",
    O = "Зберіть інформацію, а потім за допомогою «Флакона для ворожіння» створіть «Чашу для ворожіння». Використовуйте чашу, щоб поговорити з Ону.",
