},

[970] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталакс",
    D = "Лист Балтуле — це справжня біда. Цей «Культ Темної Нитки» — як кістка в горлі, яку треба витягнути. Я мав справу з деякими представниками цієї наволочі з «Темної Нитки» на північному сході відсюди, в Орділ'Арані. Один із них володіє самоцвітом душі, який, як я вважаю, містить таємницю сили культу.$B$BПринесіть його мені, і я зможу розшифрувати таємниці, що в ньому приховані.",
    O = "Зберіть Сяючий камінь душі та поверніть його Делгрену Очиснику в Пост Маестри.",
    P = "Ти вже здобув той самоцвіт душі?",
    C = "Хм, цей камінь душі наділений якоюсь темною магією. Давай подивимося, що там заховано, гаразд?",
},

[971] = {
    en = "Knowledge in the Deeps",
    T = "Знання з глибин",
    D = "Як ви, мабуть, знаєте, я збираю перекази. Стародавні перекази. Потужні перекази. Знання, що відкривають двері, і знання, здатні пробудити Тих, Хто Спить.$B$BХодять чутки про стародавній рукопис — «Рукопис Лоргаліса» — що лежить на дні Чорноглибинної безодні в Ешенвейлі. Це місце — колишня обитель ельфів, які давно померли. Ельфів, які володіли величезними знаннями, перш ніж їхнє місто занепало.$B$BШукайте рукопис у Чорноглибинних безоднях. Зробіть це, і я цього не забуду. Навіть після… кінця світу.",
    O = "Віднесіть рукопис Лоргаліса Геррігу Боунегріпу в Печері Занедбаних у Айронфорзі.",
    P = "Подорож до Ешенвейла довга, і твоє завдання не з легких. Але якщо ти принесеш мені рукопис, $N... то твоя нагорода буде великою.",
    C = "Ти знайшов рукопис! Який же це радісний день! Будуть зроблені копії та розповсюджені, і стародавні знання Лоргаліса нарешті стануть відомими моїм братам і сестрам!$B$BВаша послуга для нас вартує більше, ніж ви уявляєте, $N. Але я сподіваюся, що цей подарунок продемонструє вам нашу вдячність, яку ми висловлюємо нашим союзникам.",
},

[972] = {
    en = "Water Sapta",
    T = "Вода Сапта",
    D = "",
    O = "",
    P = "",
    C = "Візьми «Воду сапта» і знайди забруднене водоймище в Срібній Сосні, $N. Я дуже вірю у твої здібності.",
