[973] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталакс",
    D = "Ілкруд Магтрулл. Так, я про нього чув. Це могутній орк-чаклун, який мешкає у Святилищі «Вогняний Шрам» — місці великого зла на південному заході Ашенвейлу.$B$BДосі він був для мене не більше ніж дрібною прикростю, і я не мав з ним справ, але, схоже, його час настав.",
    O = "Принесіть «Трактат Ілкруда Магтрулла» Делгрену Очиснику в Пост Маестри.",
    P = "Ти виглядаєш трохи розгубленим, $n. З тобою все гаразд?",
    C = "Ти сьогодні вчинив велично, $n. Ти можеш пишатися собою за те, що зміг протистояти чаклуну такої сили.$B$BА тепер давай подивимося, що ми можемо дізнатися з праць Ілкруда.",
},

[974] = {
    en = "Finding the Source",
    T = "Пошук джерела",
    D = "Місцеві гарячі джерела для мене — справжня загадка. Звідки береться це тепло?$B$BДивлячись на те, як близько ці басейни розташовані до хребта «Вогняний стовп», я справді замислююся, чи не має до цього якогось стосунку вулкан. Я створив термометр, щоб вимірювати температуру на вулкані, і хотів би знайти найгарячіше місце. Він показує температуру в градусах Кракленгайт!$B$BОсь, візьми його і вимірюй температуру на хребті, коли побачиш гарячу точку!",
    O = "Кракле з кратера Ун'Горо просить вас знайти найгарячішу ділянку хребта Вогняного Струменя.$B$BЩоразу, коли ви знайдете гарячу ділянку, клацніть правою кнопкою миші на термометрі, щоб перевірити температуру. Продовжуйте шукати, доки не знайдете найгарячішу.",
    P = "Я б сам туди пішов, але... я трохи боюся тих вогняних елементалів!",
    C = "Так, я дійсно бачу тут взаємозв’язок між температурою вулкана та гарячими джерелами. Мені доведеться ще раз перевірити точність своїх рівнянь, але, схоже, це залежить від відстані та швидкості передачі тепла… Хм…",
},

[975] = {
    en = "Cache of Mau'ari",
    T = "Схованка Мауарі",
    D = "Отже, перш ніж віддати тобі цей амулет, краще поясню, як ним користуватися.$B$BЯкщо ти носитимеш амулет із собою, то помітиш, що з істот, з якими ти борешся, випадатимуть певні предмети. Якщо ж амулету з тобою не буде, ти їх не знайдеш. Зрозуміло?$B$BЦі особливі предмети можна впізнати за назвою — вони називаються «Е'ко». Якщо знайдеш будь-який із цих предметів, просто принеси його старенькій Мауарі, і вона тобі допоможе.$B$BЗачекайте тут, поки я полагоджу ваш талісман.",
    O = "Згодом знову поговоріть із шаманом Мауарі, щоб отримати талісман на щастя.",
    P = "",
    C = "Ось воно, $N. Пам’ятай, ти маєш носити його з собою. Чому б тобі не повернутися до Вінтерспринга й не подивитися, що там можна знайти?",
},

[976] = {
    en = "Supplies to Auberdine",
    T = "Поставки до Аубердіна",
    D = "Делгрен попросив мене доставити повідомлення та припаси до «Сентинел Старбріз» в Аубердіні, але я не хочу вирушати туди сам. У лісі орудують небезпечні вороги, і я не хочу ризикувати, щоб ці припаси та інформація потрапили в чужі руки.$B$BЯкщо ви та інші зможете супроводжувати мене, я зможу вирушити вже зараз. З вашим захистом я не маю сумнівів, що ми зможемо безпечно доправити ці товари до Аубердіна.",
    O = "Після того як ви безпечно проведете Фіро через Ліс Ашенвейл, поговоріть із Делгреном Очисником у Пості Маестри.",
    P = "«Вартові» гостро потребують припасів для зміцнення своїх позицій у Темному березі.",
    C = "Ти сьогодні добре попрацював, $C. Речі, які ми надіслали на допомогу Аубердіну, стануть у нагоді вже зараз у боротьбі з темними загрозами, що заполонили ліс.$B$BПрийми це разом із моєю щирою вдячністю.",
},

[977] = {
    en = "Are We There, Yeti?",
    T = "Ми вже приїхали, Єті?",
    D = "Тепер, коли у мене є все необхідне для захисту рухомих механічних деталей, мені потрібна лише ще одна річ. Ну, власне, дві. Два роги!$B$BНайбільші роги мають патріархи та матріархи крижаного чортополоху, тож, звісно, саме їх я й хочу. Цей вид єті мешкає в печері на південному сході. Там їх чимало, тож ти без проблем їх знайдеш.$B$BПам’ятай, мені потрібні лише найкрасивіші — ніяких пошкоджених чи зламаних рогів, будь ласка!",
    O = "Зберіть 2 бездоганні роги єті для Умі Румплснеккера в Еверлуку.",
    P = "Я вже майже закінчив прикріплювати хутро, $N. Будь ласка, швидше повертайся з тими рогами!",
    C = "Не можу дочекатися, щоб показати це своїм друзям! А тепер зачекайте хвилинку, я тільки прикріплю ось ці... $B$BЧудово!",
},

[978] = {
    en = "Moontouched Wildkin",
    T = "Дикі істоти, до яких доторкнувся Місяць",
    D = "Пір'я вайлдкінів із Гінтерленду, здається, містить сліди магічних властивостей. Ці сили... схоже, що ці істоти ними не користуються, скоріше, вони просто притаманні цьому виду — є частиною їхньої самої сутності.$B$BПід час навчання я чув, що на засніжених землях Вінтерспринга мешкає чимала популяція вайлдкінів. Чи можуть ці істоти мати такі самі здібності? Будь ласка, допоможи мені знайти відповідь, $N. Відправляйся до Вінтерспринга, збери пір'я, що впало на землю, а потім повертайся до мене.",
    O = "Зберіть 10 «Місячних пір’їн» у Вінтерспрингу, а потім поверніться до Ереласа Амберскі в селі Рут’теран.",
    P = "Звідки ж могли взятися ці здібності? Гадаю, ми на правильному шляху до відповіді, $N.",
    C = "Тепер я можу порівняти пір'я... Подивимося...",
},

