[1001] = {
    en = "Buzzbox 411",
    T = "Buzzbox 411",
    D = "З глибини машини доноситься ледь чутний голос.$B$B«Це Візбанг! Наступний «Базбокс» знаходиться на північ від Аубердіна, на пляжі$B$BОтже, цей «Базбокс» — номер 411, і для його ремонту потрібно 3 ока косарів. Вони прямо біля узбережжя! Косарі з Темного берега... *Гік*… Вибачте…$B$BЯк і минулого разу, коли ви передасте «Базбоксу» необхідні речі, він видасть вам нагороду. *Гік*… Що? Ні, все гаразд!»",
    O = "Зберіть 3 «Очі молотильника» у молотильників Темного берега в глибокому морі поблизу «Базбокса 411».",
    P = "Люк машини відкритий, і здається, вона з нетерпінням чекає, коли всередину покладуть 3 «Очі косаря».",
    C = "Buzzbox починає тихо гудіти, щойно ви покладете всередину «Очі жниварки». Пролунає короткий шум, і потім ви почуєте знайомий тихий голосок: $B$B «Вино «Кроулер» — найкраще...» *хик* $B$B «Що? О, ти вже його полагодив? Вау, ти швидкий. А може, полагодиш ще одне?»$B$BТобі здається, що ти чуєш, як рідину наливають у чашку, а потім — гучні звуки ковтання.",
},

[1002] = {
    en = "Buzzbox 323",
    T = "Buzzbox 323",
    D = "Buzzbox видає спалах шумів, і ви чуєте, як Візбанг починає говорити.$B$B«Наступний Buzzbox — номер 323. Десь на північ від Обердіна, але… а де ж ель? Що? О, воно десь на дорозі, тож тобі не складе труднощів знайти його біля мосту.»$B$BВізбанг щось незрозуміло бурмоче, а потім ви чуєте гучний звук ковтання.$B$B«Для цього потрібні ікла Місячного мисливця... шість штук».",
    O = "Зберіть 6 іклів Місячного мисливця та покладіть їх у Buzzbox 323.",
