},

[1131] = {
    en = "Steelsnap",
    T = "Steelsnap",
    D = "Іноді ми полюємо за їжею. Іноді — за честю. А іноді — щоб заслужити настанови Матері-Землі.$B$BАле полювання, яке я зараз доручаю тобі, не має нічого спільного з цим. Його мета — вбити істоту, яка перебуває поза благословенням Матері-Землі.$B$BГієна Стілснап бродить по Тисячі Голках, на південь від Пусток. Він — тиран, що приваблює до себе інших гієн і сіє страх та кровопролиття серед більш мирних звірів.$B$BЗнайдіть Стілснапа, $N. Знайдіть його та переможіть.",
    O = "Принесіть ребро Стілснапа Мелору Стоунхуфу в Грім-Скелі.",
    P = "Ти вже переміг огидного Стілснапа, $N?",
    C = "Здолавши істоту Стілснап, ти очистив Тисячу Голків від жахливого прокляття.$B$BІ це, $N, і є твій урок на сьогодні.",
},

[1132] = {
    en = "Fiora Longears",
    T = "Фіора Довгоуха",
    D = "О, якби я знову опинився в морі! Відчути поцілунок вітру і щоб хвилі колисали мене, як колись, давно, моя благословенна мати!$B$BО, якби ж я мав твою долю, добрий $c, бо я бачу море у твоєму майбутньому!$B$BМоє покликання — розповідати охочим душам про землю Калімдор, землю можливостей! Якщо ти готовий випробувати свою долю за морем, то сідай тут на корабель до чарівного порту Терамора. Там поговори з моєю напарницею, ельфійкою Фіорою Довгоухою.$B$BВона допоможе тобі розпочати твою пригоду в Калімдорі!",
    O = "Поговоріть із Фіорою Лонгірс у Тераморі.",
    P = "",
    C = "Доброго дня! Вас направив пан Флінт із Менетіл-Харбор? Що ж, пан Флінт чудово розбирається в людях. Якщо він вас направив, то без сумніву, вам саме тут, у Калімдорі, місце!",
},

[1133] = {
    en = "Journey to Astranaar",
    T = "Подорож до Астранаара",
    D = "Якщо ти щойно прибув із Менетіла, то перше, що тобі слід зробити, — це... вирушити до Астранаара. Я впевнений, що такий завзятий член Альянсу, як ти, зможе там чимало корисного зробити. Поговоріть із Шіндрелл Свіфтфайр і запропонуйте свої послуги.$B$BАле не варто згадувати, хто вас прислав. Шіндрелл мене не знає...",
    O = "Поговоріть із Шіндреллом Свіфтфайром в Астранаарі.",
    P = "",
    C = "Ви прийшли сюди, щоб запропонувати свої послуги Альянсу, $N? Ми раді вашій допомозі, адже, хоч його краса й залишилася... Ліс Ешенвейл вже не є таким спокійним місцем, яким був колись.",
},

[1134] = {
    en = "Pridewings of Stonetalon",
    T = "«Горді крила» Стоунталона",
    D = "Ми не ведемо відкритої війни з Ордою, але наш мир є крихким. Ми часто виявляємо їхніх агентів, які діють проти нас, але вони роблять це таємно.$B$BПро одну з таких операцій нам повідомили приховані джерела в Тераморі, стверджуючи, що орки збирають отруту у гордокрилих поблизу озера Міркфаллон, у горах Стоунтелон на півдні. Потім орківські вбивці використовують цю отруту під час своїх таємних смертоносних нальотів проти Альянсу!$B$BЯкщо це правда, то ми мусимо їх зупинити, $N. Ми мусимо позбавити їх джерела отрути.",
    O = "Принесіть 12 отруйних мішечків «Прайдвінг» Шіндреллу Свіфтфайру в Астранаарі.",
    P = "У тебе є отруйні залози «прайдвінгів», $N? Ми не можемо дозволити оркам використовувати отруту цих звірів проти нас!",
    C = "Дякую, $N. Мені прикро наказувати вбивати істот, які, можливо, й не з власної волі допомагають нашим ворогам, але це мій обов’язок.$B$BМожливо, твоє серце сумує за гордокрилами, яких ти вбив, друже мій, але нехай воно наповниться радістю від усвідомлення, що твої союзники в безпеці від отрути гордокрилів.",
},

[1135] = {
    en = "Highperch Venom",
    T = "Highperch Venom",
    D = "Як ти, мабуть, знаєш, орки часто приручають віверн, щоб використовувати їх як верхових тварин. Але мало хто знає, що в деяких колах отрута віверна цінується більше, ніж сама тварина. Тож якщо ти не боїшся трохи пополювати на віверн, то... У мене є для вас завдання.$B$BУ краю Тисячі Голків, на захід відсюди, є місце під назвою Хайперч. Виверни з Хайперча мають потужну отруту. Потужну й цінну.",
    O = "Принесіть 10 мішечків з отрутою «Хайперч» Фіорі Лонгерс у Тераморі.",
    P = "Ти знайшов Хайперч, $N? Як там справи з вивернами?",
    C = "Ах, більшість із них просто переповнені отрутою, $N. Зазвичай такі збирають лише у молодих виверн або у плідних самок. Мабуть, у Хайперчі там відбулася справжня різанина!",
},

[1136] = {
    en = "Frostmaw",
    T = "Фростмоу",
    D = "$N, настав час вирушити до далеких країв. Ти готовий.$B$BТепер тобі належить полювати на Фростмау, єті з Альтеракських гір. Він невловимий: його біле хутро зливається зі снігом його гірської домівки. Він рідко показується.$B$BАле я покажу тобі, як заманити таку істоту. Ось, візьми цей сувій. На ньому я написав, як можна заманити Фростмоу.$B$BА тепер іди, $N. Твоя подорож буде довгою, і на тебе чекає чимало випробувань. Лише коли ти повернешся з гривою Фростмоу, твоє завдання буде виконано.",
    O = "Принесіть гриву Фростмау Мелору Стоунхуфу в Грім-Скелю.",
    P = "Ти бував у горах Альтерак, $N? Чи доводилося тобі битися з невловимим Морозним Пащею?",
    C = "Щоб знайти й перемогти Фростмау, $N потрібні були і сила, і хитрість. У тебе є й те, й інше.$B$BВаш шлях привів вас до долин Тисячі Голків і до високих гір Альтерака. Одного дня він проведе вас через усі землі Матері-Землі, бо таким є шлях мисливця.",
},

[1137] = {
    en = "News for Fizzle",
    T = "Новини для Fizzle",
    D = "Індурій має дивовижну термостійкість! Я впевнений, що воно підійде для поршнів Фіззла. Але йому знадобиться справжня руда індурію, а не просто пластівці.$B$BЩоб дістати руду, її треба видобувати з глибин Улдаману, що на північних кордонах Пусток. Саме там знаходиться справжнє джерело індурію.$B$BПередайте Фіззлу Брассболту мої вітання та розкажіть йому те, що я вам сказав.$B$BЩасливої дороги, $N. І я не здивуюся, якщо ми ще зустрінемося — щойно Фіззл дізнається про індурій, він, мабуть, відправить тебе до Улдамана, щоб дістати його!",
    O = "Поговоріть із Фіззлом Брассболтом у «Мерехтливих рівнинах».",
    P = "",
    C = "$N, ти повернувся! Ти знайшов Мартека? Ти з ним розмовляв? Що він сказав? Він може допомогти??$B$BРозкажи, розкажи, розкажи!!",
},

[1138] = {
    en = "Fruit of the Sea",
    T = "Дари моря",
    D = "Я обожнюю крабів. Краби — це дари моря! Їх можна запікати, готувати на грилі, варити та смажити під грилем. Їх смажать на сковороді, у фритюрі та у вок-сковороді. Є крабовий салат, крабовий суп, крабове рагу, краб з перцем, краб з лимоном, краб з коренем віпперу та краб «сюрприз з Айронфорджа». Ось... мабуть, і все.$B$BЗараз я тут рибалю, тому не можу дістати ніяких гарних шматочків краба. Їх можна дістати з рифових раків та раків, вкритих нальотом. З них можна приготувати багато чого. Їх можна запікати, готувати на грилі, варити...",
    O = "Зберіть 6 шматочків вишуканого краба для Губбера Блампа в Аубердіні.",
    P = "...лимонний краб, краб «Віппер-рут» і краб-сюрприз з Айронфорджа. Ось і все.$B$BО, привіт $N. А у тебе є ті чудові шматочки краба, про які я тобі розповідав?",
    C = "Ого, ці чудові шматочки краба — саме те, що мені потрібно. Дякую, $N! Я знайшов це, коли недавно рибалив, але мені це ні до чого. Може, тобі це знадобиться. З цього точно не вийде ніякої смачної страви з краба.$B$BЯ ж тобі все розповідав про крабів, правда?",
},

[1139] = {
    en = "The Lost Tablets of Will",
    T = "Загублені таблички Вілла",
    D = "Нам вдалося уповільнити просування клану «Тіньової Кузні», відрізавши їх від Шпиля Чорної Скелі, але завдання Хаммертоу досі не виконано. Його смерть не повинна бути марною. Він мріяв знайти «Таблетку Волі» — кам'яний уламок, на якому титани власноруч викарбували магічне заклинання, щоб наділити своїх створінь життям і власною волею — принаймні так кажуть легенди.$B$BМи все ще мусимо знайти Скрижаль, перш ніж її знайде клан «Тіньової Кузні».$B$BПоверніться до Улдамана, знайдіть Скрижаль і негайно поверніться сюди.",
    O = "Знайдіть Табличку Волі та поверніть її раднику Белгруму в Айронфорзі.",
    P = "Місія Хаммертоу має бути виконана, $N. Я йому це винен.$B$BТвоє повернення до Улдамана є вкрай необхідним не лише для досягнення цієї мети, а й для безпеки всього народу гномів. Якщо табличка опиниться в руках Темних Залізних, хто знає, наскільки потужною стане їхня армія големів.",
    C = "<Радник Белгрум з недовірою хитає головою, коли ти подаєш йому уламок каменю.>$B$B$N, це дивовижно. Я доручу якнайшвидше доставити його до королівських магів. Вони захочуть дослідити його, щоб з’ясувати, чи правдиві легенди. Але про це поговоримо іншим разом: ти допоміг нашому народу більше, ніж я міг би коли-небудь сподіватися — дякую тобі.",
},

[1140] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталакс",
    D = "Почерк орків ледь кращий за дитячі каракулі. Багато хто з членів мого ордену насміхався, коли я вирішив вивчити їхню мову, але я переконався, що це допомагає краще зрозуміти моїх ворогів.$B$BЗ записів Ілкруда випливає, що Атрікус досі володіє двома самоцвітами душі, і вони зберігаються в Найт-Ран та Сатирнаар — територіях, контрольованих сатирами на північному сході Ашенвейла.$B$BБудь обережним там, $n, просочені кров’ю храми сатирів можуть викликати тривогу навіть у такого досвідченого $c, як ти.",
    O = "Звільніть ув’язнені душі Високородних у «Нічному пробігу» та Сатірнарі, а потім поверніться до Делгрена Очисника в «Посту Маестри».",
    P = "Я колись чула пошепки, що історія сатирів якимось чином пов’язана з історією нічних ельфів, але мої шановні господарі, як виявилося, не бажають говорити на цю тему.",
    C = "Можливо, сатирам занадто довго дозволяли залишатися в лісі. Я поговорю про це з Еліссою, коли наступного разу поїду до Аубердіна.$B$BПроте, після знищення душевих самоцвітів сила Атрікуса значно зменшиться. Ми мусимо скористатися цією нагодою, щоб знищити його та його культ.",
},

[1141] = {
    en = "The Family and the Fishing Pole",
    T = "Сім’я та вудка",
    D = "Я люблю рибалити. Сім’я Блумпів відома своєю пристрастю до риболовлі. Мене звати Губер Блумп; я рибалю.$B$BУ цих краях є риба, яку я люблю ловити, — це групер з Темного берега. Раніше я виходив на човні ловити груперів, але з тих пір, як тут оселилися ті підлі старі мурлоки, човни більше не виходять у море. Готовий побитися об заклад, що вони ще й усіх груперів з’їли.$B$BСкажи, не хочеш допомогти мені зловити групера з Темного берега? Якщо допоможеш, я подарую тобі справжню рибальську вудку родини Блумпів! На ній дуже добре ловиться риба.",
    O = "Зловіть 6 груперів з Темного берега для Губбера Блампа в Обердіні.",
    P = "Існує безліч смачних страв, для приготування яких використовують груперів з Темного берега. Вони смачні, але, на мою думку, ловити їх набагато цікавіше.$B$BТи вже зловив хоч одного групера з Темного берега?",
    C = "Це справді гарні групери, $N! Дякую, що допоміг мені!$B$BТи рибалка не гірший за мого кузена Грауна Блумпа. Вона теж має бороду і трохи дивно пахне, але це анітрохи не заважає їй рибалити. Гадаю, у тебе є все необхідне, щоб користуватися рибальською вудкою родини Блумп.",
},

[1142] = {
    en = "Mortality Wanes",
    T = "Смертність знижується",
    D = "Мені залишилося недовго жити... я такий... такий... слабкий.$B$B...с-с-сміливий карлик, Лонеброу, був відправлений, щоб п-п-попередити Фалфіндела...$B$BАле перш ніж я... п-п-помру...$B$B...моя дружина, Трешала... її кулон, що пов'язує нас... вкрали... один із о-о-огидних нападників...$B$BЗнайдіть його, б-б-будь ласка... і поверніть його Трешалі в Дарнассусі...$B$B...разом із п-п-повідомленням про мою самотню... смерть.",
    O = "Знайдіть кулон Трешали та поверніть його Трешалі Фаллоубрук у Дарнассусі.",
    P = "Що привело тебе до мене додому, $R?",
    C = "Ні!$B$BЦе несправедливо. О, жорстокий і нестерпний світ!$B$BТепер я мушу нести цей тягар скорботи й не дозволити, щоб справа Гералата загинула разом із ним.$B$BТи проявив мужність, вирушивши з такого небезпечного місця, $N. Але, будь ласка, залиш мене зараз.$B$BЯ буду оплакувати його на самоті.",
},

[1143] = {
    en = "The Tower of Althalaxx",
    T = "Вежа Алталакс",
    D = "Розумію. Що ж, якщо те, що ти кажеш, правда, то саме зараз час діяти. Я вважаю, що Атрікус перебуває на вершині вежі. Але будь обережним: його оточує багато могутніх чаклунів, набагато небезпечніших за тих, з якими ти стикався раніше.",
    O = "Вбий Атрікуса Нарасіна та принеси його голову до Балтуле Шейдоустрайка, що знаходиться поблизу Вежі Алталакс.",
    P = "Атрікус Нарасін — стародавній і могутній чаклун. Можливо, нам слід дочекатися допомоги від Делгрена, але він, очевидно, дуже тобі довіряв, якщо відправив тебе одного.",
    C = "Сподіваюся, що зі смертю Атрікуса демонічні сили в цій місцевості будуть відкинуті. Я не маю сумнівів, що вони перегрупуються і повернуться, але тоді ми будемо ще краще готові протистояти їхній загрозі.",
},

[1144] = {
    en = "Willix the Importer",
    T = "Віллікс-імпортер",
    D = "Нарешті, допомога прибула!$B$BТи навіть не уявляєш, як довго мене тут тримають у полоні. Я навіть не пам’ятаю, коли востаннє бачив світ за межами цього місця.$B$BРозумієте, я — підприємець. Як то кажуть, завжди в пошуках заробітку. Я почув чутки, що Мебок Міззірікс добре платить за бульби «Червоного листя» з цієї свинарні. Я думав, що це буде проста справа — зайти й вийти. Як бачите, я трохи помилився!$B$BУ будь-якому разі, якщо ви будете настільки люб’язні, що допоможете мені вибратися звідси, я вам це віддячу.",
    O = "Супроводити Вілікса-імпортера з Разорфен-Краула.",
    P = "",
    C = "Ще раз дякую, друже! Я ж казав, що ти не пошкодуєш.",
},

[1145] = {
    en = "The Swarm Grows",
    T = "«Рій» розростається",
    D = "Багато мандрівників, які проїжджали через «Перехрестя», допомагали мені збирати яйця на «Полі гігантів», і багато хто з них розповідає, наскільки смертоносні ці істоти. Я почув достатньо, щоб вважати цих комах набагато більшою загрозою, ніж спочатку думали мої господарі.$B$BМені потрібен кур'єр, який поїде до Оргримара, щоб зустрітися з Белгромом Рокмаулом. Це не проста справа, і туди має вирушити той, хто серйозно поставиться до цього завдання.$B$BБелгрома зазвичай можна знайти біля будинку гільдії воїнів.",
    O = "Доставте запечатану записку Коррана Белгрому Рокмаулу в Оргримарі.",
    P = "Я тобі заздрю, $c. Ти виглядаєш так, ніби вже деякий час перебуваєш за межами стін Оргримара.$B$BЯ сам би подорожував від імені Вождя, якби Траллу не знадобилися мої вміння тут, у місті. Але він добре керує нами, і я довіряю його судженням — я залишатимуся тут, доки я йому потрібен.",
    C = "А, записка від Коррана. Він уже деякий час є моїм вірним слугою. Мені було цікаво, як у нього йдуть справи на Перехресті.",
},

[1146] = {
    en = "The Swarm Grows",
    T = "«Рій» розростається",
    D = "Отже, Корран дійшов подібного висновку щодо цих комах — схоже, вони становлять більшу загрозу, ніж ми припускали.$B$BКілька днів тому до мене з «Тисячі Голків» повернувся мисливець, який ледь не загинув. Він був у складі рейдового загону, відправленого для вигнання команди карликів-археологів із «Мерехтливих рівнин». Під час нападу з печери на місці розкопок вирвалося ще більше цих комах, які ледь не знищили загін.$B$BЇх очолював Моктар Крін, і вони знайшли притулок на кордоні Мерехтливих рівнин. Передай йому цю записку.",
    O = "Доставте запечатану записку Белгрома Моктару Кріну в «Тисячі Голках».",
    P = "Війна привела мене та мою групу до Мерехтливих рівнин, $c. А що привело вас сюди?",
    C = "Не звертайте уваги на гуркітливе відлуння, що розноситься від гірських схилів. Гобліни та гноми розбігалися по Рівнинах, змагаючись у жорстокостях, породжених тим, що вони називають наукою. У Тисячі Голках є й більші загрози, одна з яких вбила більше половини мого бойового загону.$B$BАле ми залишаємося тут, доки не отримаємо звістку від Белгрома в Оргримарі. До того часу ми утримуємо тут свої позиції й залишаємося пильними.",
},

[1147] = {
    en = "The Swarm Grows",
    T = "«Рой» розширюється",
    D = "Хм. Схоже, Белгром вважає цих монстрів загрозою. Він хоче, щоб їх відігнали назад у ті глибини, звідки вони виповзли.$B$BМабуть, вбити гномів, яких прислала Ліга Дослідників, було недостатньо — тепер мені доведеться відправити напівмертвий військовий загін у чергову битву. Самі ми з цим не впораємося; принаймні, поки перебуваємо в такому стані. Місце розкопок розташоване на південь від нас. Там уже не повинно бути гномів, з якими доведеться мати справу. Чи готові ви взяти до рук меч чи посох і зробити свій внесок, щоб допомогти нам?",
    O = "Вбийте 5 силітидських розвідників, 5 силітидських трутнів з вулика та 5 силітидських загарбників і поверніться до Моктара Кріна в «Тисячі Голках».",
    P = "З огляду на кількість мандрівників, які вирушають до Флетс на ці перегони, я впевнений, що нам вдасться залучити достатньо любителів пригод, щоб разом відігнати цих комах. Ми з моєю групою не зможемо виїхати, доки цього не зробимо.",
    C = "Ха! Ця іхора, якою ти вкритий, насправді робить тебе ще гарнішим, $N! Хоча, звичайно, від тебе при цьому й тхне не дуже приємно. Не стій надто близько до кодо — інакше або спричиниш панічну втечу, або змусиш їх увійти в період розпалу.$B$BГадаю, мої товариші погодяться, що сам лише твій запах — це доказ того, що ти зробила свій внесок, допомагаючи нам у боротьбі з тими комахоподібними істотами. Дякую, $N.$B",
},

[1148] = {
    en = "Parts of the Swarm",
    T = "Частини Рою",
    D = "Ви уважно оглядаєте панцир. Перевертаючи його в руках, ви розумієте, що хітинові пластини переплітаються таким чином, що роблять його неймовірно міцним. Це не схоже на те, що ви коли-небудь бачили. Ви далі оглядаєте решту трупа і розумієте, що ці істоти дуже сильні та високорозвинені.$B$BЗнову дивлячись на панцир, ви думаєте, що Коррану сподобалося б докладніше дослідити цих істот. Це могло б допомогти йому з’ясувати, що це за істоти і звідки вони походять.",
    O = "Принесіть 1 серце силітіда, 5 кігтів силітіда та 3 цілі панцирі силітіда Коррану на Роздоріжжі.",
    P = "О, давно ти до мене не заглядав, $N. Чим можу тобі допомогти сьогодні? Ти виглядаєш так, ніби нещодавно побував на полі бою. Добре... це добре для Орди і добре для тебе. Чим більше битв ти переживеш, тим кориснішим станеш; і сильнішим теж.",
    C = "Ага, ти нещодавно бачив Моктара? Він завжди піклується про мене. Мені шкода, що він витрачає час на нагляд за своїм маленьким бойовим загоном замість того, щоб брати участь у боях, але я впевнений, що він отримує велике задоволення від вбивства членів Ліги Дослідників.$B$BТи вчинив розумно, принісши мені ці зразки, $N. Разом із яйцями, які ми знаходимо на Полі Гігантів, вони мають стати для мене гарним початком у з’ясуванні, що це за комахи і чого вони хочуть.",
},

[1149] = {
    en = "Test of Faith",
    T = "Випробування віри",
    D = "Отже, ти сам мене розшукав, чи, можливо, доля привела тебе до мене? Не має значення. Ти вже тут, тож твоя подорож почнеться заново.$B$BІстота складається з багатьох граней: духу, тіла, розуму. Деякі з них можна виміряти за традиціями культури. Інші ми можемо лише сподіватися, що вони існують у нас самих. Якщо ти згоден, я перевірю деякі з цих аспектів у тобі.$B$BЯкщо ти пройдеш випробування, то станеш сильнішим. Якщо ж зазнаєш поразки, то усвідомиш безмежність Нижнього Світу.$B$BПерше — це Випробування Віри.",
    O = "Якщо ти віриш, стрибни з дощок, що виходять на Тисячу Голків.",
    P = "Віра. Вона набагато важливіша, ніж дехто уявляє.$B$BІноді не має значення, у що саме ти віриш. Важливо лише те, що ти в щось віриш.",
    C = "Лише зіткнувшись із непередбаченими труднощами, ми починаємо розуміти, наскільки сильним є наш дух. Ти зважився на цей крок, незважаючи на те, що не мав жодних гарантій, що виживеш. Твій розум відкритий, а дух готовий до того, що чекає попереду.$B$BЯкщо ти готовий, то наступне випробування вже чекає на тебе.",
},

[1150] = {
    en = "Test of Endurance",
    T = "Випробування на витривалість",
    D = "Мені приємно бачити, що твоя мужність залишається непохитною, зважаючи на те, що ти вже зробив. Оскільки твоя віра не похитнулася, настав час випробувати твоє тіло.$B$BСпочатку — випробування на витривалість. Рушай разом із друзями до Лігва «Блукаюче Перо», що на захід від Посту «Вільний Вітер». Проникніть углиб їхнього лігва та знищіть їхні запаси їжі. До того часу ви вже маєте розлютити їх, і якщо вам вдасться протриматися достатньо довго, сама Гренка Кровокрик прийде за вами — вбийте її та принесіть мені її пазур, щоб завершити випробування.",
    O = "Принесіть «Кіготь Гренки» Дорну Плейнстолкеру в «Тисячі Голках».",
    P = "Ви повинні бути готовими духовно, фізично та психологічно до викликів, які чекають на вас попереду.$B$BЗанадто часто ми кидаємося вперед, не підготувавшись належним чином. Я вважаю своїм обов’язком перед молоддю, незалежно від того, до якого племені вона належить, підготувати її до небезпек, з якими вона може зіткнутися після того, як покине затишок рідного дому.",
    C = "Гренка був могутнім навіть за мірками тролів. Ти маєш пишатися своїм сьогоднішнім досягненням.$B$BПід час випробування на вірність ти продемонстрував силу духу, а тепер проявив витривалість у бою, зіткнувшись із гарпіями з племені «Рогове пір’я», але настав час для нового випробування.",
},

[1151] = {
    en = "Test of Strength",
    T = "Випробування на міцність",
    D = "За часів Стародавніх Богів елементалі населяли значну частину цього світу. Вони поклонялися Стародавнім Богам, а Боги, завдяки своїй силі, утримували елементалів у цьому світі. Коли Стародавніх Богів було вигнано, елементалі зникли з нашого світу і тепер повертаються лише на веління могутніх магів.$B$BОднак є й винятки. Деякі елементалі були достатньо могутніми, щоб залишитися тут самостійно. Одним із таких елементалів є Рок’Алім.$B$BЩоб перевірити свою силу, знайдіть Рок’Аліма в Тисячі Голках і вбийте його.",
    O = "Принесіть уламки Рок’Аліма Дорну Плейнстолкеру в «Тисячі Голках».",
    P = "Племена кентаврів у Тисячі Голках також називають Рок’Аліма «Толокачем» через гуркітливий звук, який видають його кулаки, коли він б’є тих істот, які настільки сміливі — чи, може, настільки дурні, — що наважуються стати йому на шляху.",
    C = "Випробування на силу завершено. Ти продемонстрував силу та хоробрість, і тепер ти готовий до останнього випробування перед завершенням цих обрядів.",
},

[1152] = {
    en = "Test of Lore",
    T = "Випробування знань",
    D = "Ваш час зі мною добігає кінця. Я обізнаний, але не мені проводити «Випробування Знань». Є уроки, які потрібно засвоїти, і місця, які варто відвідати, але вони знаходяться під владою інших.$B$BЯкщо ти готовий, то знайди Брауга Дімспіріта — він шаман великої мудрості. Він піддасть тебе подальшим випробуванням, тож прислухайся до його слів, $N.$B$BКоли будеш готовий, знайди тунель, що з’єднує Гори Кам’яного Копита з Попелястою Долиною: Брауг мешкає неподалік. І будь обережним, $N, нічні ельфи можуть спробувати перешкодити твоєму випробуванню.",
    O = "Знайдіть Брауга Дімспіріта біля входу на Стежку Талондіп у Горах Стоунталон.",
    P = "",
    C = "Дні й ночі по всьому світу стають дедалі холоднішими, поки гобліни спустошують землю, а нічні ельфи звинувачують молодші раси. Не лише «Покинуті» та орки винні у тих лихах, що спіткали Калімдор і Лордаерон. Багато розумних рас причетні до страждань світу. Дорн знає це, і він послав тебе до мене, бо ти проявив якості, необхідні для того, щоб усвідомити це також.$B$BТепер ти стоїш перед Браугом.",
},

[1153] = {
    en = "A New Ore Sample",
    T = "Новий зразок руди",
    D = "$C, ти добре допоміг мені раніше. Вождь поки що задоволений моїми досягненнями і просить мене продовжувати з новою рішучістю. Моя честь вимагає, щоб я належним чином віддячив вождю за все, що ти зробив, але спершу я хотів би знову попросити тебе про допомогу.$B$BНещодавно з півдня прибули мандрівники з місця під назвою «Тисяча Голків». Там вони вбили кобольда, який мав зразок незвичайної руди, але відмовилися його продати. Мені потрібен зразок цієї руди для дослідження.",
    O = "Знайдіть зразок необробленої руди на екскаваторі «Гравелсноут» або на «Сервеййорі» та принесіть його до Таттернака Стілфорджа в таборі Таурахо в Пустках.",
    P = "Я знову побачив тих мандрівників — тих самих, які відмовилися продати мені зразок руди. Я плюнув на них за те, що вони не допомогли воєначальнику.$B$BНехай вони загинуть у бою як боягузи, а не як воїни, як це має бути для всіх, хто приєднується до Орди.",
    C = "Гарний зразок, $N. Справді, гарний зразок.$B$BТепер, коли тобі вдалося досягти успіху, ті мандрівники більше не зможуть вихвалятися перед мною знайденою рудою.$B$BЯ негайно візьмуся за роботу. Якщо матеріал виявиться достатньо міцним, я надішлю вождю зброю, виготовлену з нього, щоб продемонструвати йому наш успіх.$B$BЯ не забуду про твою допомогу, $C.",
},

[1154] = {
    en = "Test of Lore",
    T = "Випробування знань",
    D = "Ти пройшов випробування Дорна, і тепер прагнеш подолати наступне випробування. Дуже добре. Але досі ваші випробування були дитячими. Перевірити ваше тіло легко — а от розум — це зовсім інша справа.$B$BЯ поясню просто: знайдіть книгу, яку я назву, вивчіть її та дайте відповідь на моє запитання щодо її змісту.$B$B«Яка книга?» — запитаєте ви. «Спадщина Аспектів». Її можна знайти на дні Дор’даніла в південній частині Ешенвелю, де її охороняють мертві друїди та їхні вбивці.",
    O = "Знайдіть Спадщину Аспектів і поверніть її Браугу Дімспіріту біля входу на Стежку Талондіп у Горах Стоунталон.",
    P = "Принеси мені книгу після того, як вивчиш її. Я не буду ставити тобі запитання, доки ти не віддаси мені книгу.",
    C = "Ось книга, яку я назвав. Тоді є надія, що ти правильно відповіси на моє запитання... якщо, звичайно, ти не забув вивчити її зміст.$B$BКоли будеш готовий, звернися до мене знову, і я задам тобі запитання.",
},

