},

[1195] = {
    en = "The Sacred Flame",
    T = "Священне полум'я",
    D = "Кентаври Галак у Тисячі Голках охороняють артефакт часів створення кентаврів.$B$BМи хотіли б його забрати, але для цього нам потрібна флакончик води з одного з місячних джерел нічних ельфів.$B$BЩоб набрати воду, спочатку вам потрібно дістати одну з флаконів, які носять дріади поблизу «Райневудського притулку» у самому серці Лісу Ешенвейл. Біля західного берега річки Фалфаррен, на південь від головної дороги, знаходиться місячний колодязь, де ви зможете наповнити флакон.",
    O = "Поверніть заповнену гравіровану флаконку Зангену Стоунхуфу в Громовому Утвірі.",
    P = "Як тільки ми отримаємо наповнену флакон, зможемо відправити його моєму колезі Рау в «Тисячі Голках». Саме він попросив флакон з водою, тож він краще знатиме, як ми можемо його використати.",
    C = "Дуже добре. Це має цілком задовольнити прохання Рау. Чи не могли б ви передати це йому? Можливо, вам сподобається провести трохи часу в Нідлз.",
