[1391] = {
    en = "Nothing But The Truth",
    T = "Тільки правда",
    D = "Нам треба діяти з певною обережністю. Адже ти ж не збираєшся просто так зайти туди й переконати того дурня випити тут зілля Фаустіна, правда?$B$BАле якщо є щось, від чого ці люди не можуть відмовитися, то це алкоголь. Я візьму сироватку Фаустіна і змішаю її з цим елем. Гарантую, що той бідолаха не буде нітрохи вагатися, коли дійде справа до того, щоб випити цей напій.$B$BПоспішай до Стонарда в Болоті Скорботи, $n. І тримай нашу маленьку місію в таємниці...",
    O = "Віднесіть «Напій Зраедуса» інфільтратору Марксену в Стонарді.",
    P = "Будь ласка, змилуйтеся наді мною! У мене є інформація, яка виходить за межі альянсу. Хоча я й не є прихильником Орди, але зараз відбувається політична зрада, про яку необхідно розповісти!",
    C = "Мені випити? Як мило. Мені вже кілька днів не дозволяють пити. Дай-но я це вип’ю, а потім розповім тобі, що я дізнався...",
},

[1392] = {
    en = "Noboru the Cudgel",
    T = "Нобору «Дубинка»",
    D = "Нобору вже кілька місяців тероризує драені з «Притулку», а його палиця є символом жорстокості, якої вони зазнали від рук «загублених».",
    O = "Віднесіть палицю Нобору до ватажка «Притулку» у «Болоті Скорботи».",
    P = "Вітаю. І ласкаво просимо до «Харборедж».",
    C = "Ти здобув зброю страхітливого Нобору? То він, мабуть, загинув?$B$BЦе радісний день для «Притулку». Нобору та його банда були для нас справжнім жахом: вони блукали болотами й вбивали кожного драені, який траплявся їм на шляху. Він становив пряму загрозу нашому виживанню, а ми не мали сил протистояти йому.$B$BНам пощастило, що у нас є такий друг, як ти, $N.",
},

[1393] = {
    en = "Galen's Escape",
    T = "Втеча Галена",
    D = "Допоможіть, будь ласка! Ці істоти мене з’їдять!$B$BДопоможіть мені вибратися звідси, і я віддам вам величезний скарб! Він знаходиться в моєму таборі на болоті на північ від Стонарда, але зачинений у сейфі, який можна відкрити за допомогою хитрості, яку знаю лише я.$B$BЯкщо ти допоможеш мені втекти, я навчу тебе цьому.",
    O = "Виведіть Галена з небезпеки, а потім знайдіть його табір у Болоті Скорботи та відкрийте його скриню.",
    P = "",
    C = "Замочна щілина цього сейфа заповнена чорною смолою. Його неможливо відкрити.$B$BАле Гален розповів вам про прихований засув на дні скриньки... $B$B...Після швидкого огляду засувку знайдено. Засувку перекидають, і скринька відкривається...",
},

[1394] = {
    en = "Final Passage",
    T = "Останній абзац",
    D = "Ти добре впорався, $N. Ти пройшов моє випробування, а також випробування, що передували йому. Повертайся до Дорна в «Тисячі Голках». Він відчує зміни в тобі й побачить, що твій розум, тіло та дух достатньо сильні, щоб ти отримав нагороду за свої зусилля.$B$BЗалишайся вірним рівновазі, яку ти демонстрував протягом усіх цих випробувань, $N. Якщо ти це зробиш, Дорн знову випробує тебе в майбутньому.",
    O = "Поговоріть із Дорном Плейнстокером у «Тисячі Голках».",
    P = "",
    C = "Ах, $N. Скільки ж часу минуло з того моменту, як ти востаннє завітав до мого дому. Здається, минуло чимало місяців відтоді, як ти зробив той перший крок, що визначив твій шлях.$B$BА тепер ти повертаєшся до мене сильнішим, ніж був колись... більш просвітленим. Це мене тішить. І ти маєш отримати справедливу нагороду за те, що пройшов мої випробування до кінця.",
},

[1395] = {
    en = "Supplies for Nethergarde",
    T = "Припаси для Нетергарда",
    D = "Цю скриню з каменями сили потрібно доставити до фортеці Нетергард у Спустошених землях. Вони не зможуть довго зберігати свою силу, тому ми не можемо відправити їх із наступним караваном.$B$BТи повинен їх забрати, і зробити це потрібно швидко.$B$BДоставте їх інтенданту Лунгерцу у фортецю Нетергард. Щоб дістатися до фортеці, вам слід рухатися на схід через Перевал Мертвого Вітру, потім на схід через Болото Скорботи, а потім на південь через Спустошені землі.$B$BБудьте обережні, $N. Ви подорожуватимете небезпечними землями, але не маєте права на помилку.",
    O = "Принесіть ящик з енергетичними каменями до інтенданта Лунгерца, доки термін дії енергетичних каменів не закінчиться.",
    P = "Привіт! Не звертай уваги на весь цей галас — у фортеці Нетергард це звичайна справа.$B$BУ тебе є щось для мене?",
    C = "Ах, камені сили! Маги будуть раді їх побачити!$B$BЩиро дякую, $N. Я знаю, що твоя подорож із Даркширу була нелегкою.",
},

[1396] = {
    en = "Encroaching Wildlife",
    T = "Дикі тварини, що вторгаються на територію",
    D = "Мій караван прямував до східного узбережжя, але ми так і не дісталися до місця призначення. На нас напали «Загублені», вбивши охоронців і розграбувавши запаси.$B$BЛише я один вижив після їхнього нападу. Я поклявся захищати ті запаси, що залишилися, але поблизу крадуться дикі тварини. Будь ласка, допоможіть мені захистити мій табір від цих звірів!",
    O = "Вбийте 8 молодих пилкозубих кроколісків, 10 «Смуткових прядильників» і 10 «Болотних ягуарів», а потім поверніться до Спостерігача Біггса в «Болоті Смутку».",
    P = "Болотні істоти насуваються, $N. Будь ласка, ти повинен захистити табір!",
    C = "Звуки тварин тепер ледь чутні, вони лунають дедалі далі. Дякую, $N. А тепер сподіваймося, що вони не повернуться!",
},

[1398] = {
    en = "Driftwood",
    T = "Корення",
    D = "Я тобі дуже вдячний, $N. У тобі б’ється благородне серце. А тепер у мене є ще одне завдання, у виконанні якого я смиренно прошу твоєї допомоги.$B$BЯкщо я коли-небудь хочу дістатися до Нетергарда, то мушу полагодити цей візок. А для цього... мені знадобиться деревина. Міцна, суха деревина — а не м’яка й заплутана, як у болотних дерев.$B$B$N, йди на схід, до узбережжя, і знайди корчі, висушені сонцем. Принеси їх мені.",
    O = "Принесіть 8 шматків висушеного на сонці корча до Спостерігача Біггса у «Болоті Скорботи».",
    P = "Ти знайшов якесь корчі, $N?",
    C = "Ця деревина легка, але міцна. Дякую, $N. Вона чудово підійде.",
},

[1418] = {
    en = "Neeka Bloodscar",
    T = "Ніка Бладскар",
    D = "«Бедлендс» — суворий регіон, що розташований неподалік від контрольованої Альянсом території Лох-Модан, тому зв’язок між Стонардом та форпостом «Каргат» у «Бедлендс» часто переривається.$B$BДоведи свою спроможність, $N. Відправляйся до Пусток і поговори з Нікою Бладскар, головною розвідницею форпосту Каргат. Поговори з нею, а потім надішли мені її звіт.",
    O = "Поговоріть з Нікою Бладскар.",
    P = "",
    C = "Хельгрум хоче звіт, так? Я відправив гінця до Стонарда не більше трьох днів тому. Чи він провалив своє завдання? Якщо у Стонарда немає мого звіту, то, схоже, він справді провалив.$B$BБудемо сподіватися, що наступний гінця, якого я відправлю, виявиться більш вправним або матиме більше щастя.",
},

[1419] = {
    en = "Coyote Thieves",
    T = "Злодії-койоти",
    D = "Чи провів ти багато днів у Бедлендсі, $c? Чи відчував ти його спеку? Чи стикалися ви з звірами, що бродять по його запилених рівнинах? Настав час це зробити.$B$BСкельні койоти — витривала порода. Витривала й настільки зухвала, що пробирається до Каргата й краде наші запаси їжі. Допоможи позбавити форпост цих злодіїв!$B$BПолюй на скельних койотів, $N. Полюй на них і принеси мені їхні щелепи. Принеси мені достатньо, і, можливо, я повірю, коли ти скажеш, що знаєш Пустощі.",
    O = "Принесіть 30 щелеп койота Ніці Кровавій Шрамі в Каргаті.",
    P = "У вас є щелепні кістки?",
    C = "Гарна колекція щелеп, $N. Тепер ці койоти не будуть розривати наші запаси в пошуках залишків.$B$BМолодець. Койоти з Бедлендів — нелегка здобич. Твій вчинок показує мені, що ти, можливо, зможеш тут вижити.",
},

[1420] = {
    en = "Report to Helgrum",
    T = "Звіт для Гелгрума",
    D = "Я написав новий звіт для Хельгрума у Стонарді. Передай його йому.$B$BІ якщо ти вважаєш себе розвідником, то не збивайся зі шляху. І не потрапляй у руки ворога.",
    O = "Віднесіть звіт Ніки до Гелгрума Швидкого у Стонарді.",
    P = "Ти повернувся. У тебе є звіт?",
    C = "Дякую, $N. Зі звіту Ніки я бачу, що Альянс теж має свої проблеми. І, можливо, виявиться, що у нас є спільні вороги.",
},

[1421] = {
    en = "The Lost Caravan",
    T = "Загублений караван",
    D = "Під час нападу «Загублених» я втратив свідомість, але перш ніж все потемніло перед очима, я встиг помітити, як один із наших возів тягнуть до «Святилища Фаллоу» — селища «Загублених», що розташоване на півночі.$B$BУ тому возі був караванний скринь із цінними реагентами, які мають вирішальне значення для досліджень чарівників фортеці Нетергард. Знайди скринь і дістань ці реагенти, $N. Дістань їх і принеси мені.",
    O = "Знайдіть скриню каравану в «Запущеному притулку», дістаньте реагенти чарівників і віднесіть їх Спостерігачеві Біггсу.",
    P = "У тебе є реактиви чарівника, $N?",
    C = "А, ти їх знайшов! Завдяки цим предметам чарівники в Нетергарді зможуть продовжити свою роботу. Я не знаю, чим саме вони займаються, але це пов’язано з Темним порталом у Зруйнованих землях і має вирішальне значення для безпеки Альянсу.",
},

[1422] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Поки я почну працювати над твоєю зброєю, чому б тобі не поговорити з Катаром? Він згадував, що йому потрібна допомога з патрулюванням узбережжя, і я б волів, щоб ти зберігав тверезість і тримав зброю напоготові, замість того щоб напиватися разом з тими негідниками, з якими я ділю цей табір.",
    O = "Поговоріть із Катаром у Болоті Скорботи.",
    P = "",
    C = "Помовчи хвилинку, $C. Навіть крізь глухий гуркіт моря все одно чути те огидне булькання риболюдей.",
},

[1423] = {
    en = "The Lost Supplies",
    T = "Загублені запаси",
    D = "Ця бочка невелика, але міцна. Її шви заклеєні жовтим воском із різким запахом. На дні бочки вибито напис: $B$BКВАРТЕРМЕСТЕР ЛУНГЕРЦ $B$BФОРТЕЦЯ НЕТЕРГАРДЕ",
    O = "Принесіть загублені припаси до інтенданта Лунгерца.",
    P = "У тебе для мене щось є?",
    C = "Ах, дякую, $N! Стільки припасів загубилося на шляху з Даркширу сюди. Приємно бачити, що частину з них вдалося повернути.",
},

[1424] = {
    en = "Pool of Tears",
    T = "Озеро сліз",
    D = "Військовий вождь відправив нас розслідувати дивні події в Храмі Атал'Хакара.$B$BТролі Атал'аї — це плем'я темних чарівників, відомих тим, що практикують заборонену магію. Можете уявити, як ми здивувалися, коли, прибувши сюди, виявили, що храм затопило.$B$BЗараз це місце охороняють зелені дракони, які називають себе захисниками Азерота.$B$BНам потрібно з’ясувати, що сталося. Дослідіть околиці Басейну сліз і зберіть артефакти Атала’аї. За їхньою допомогою я зможу почати складати цю головоломку.",
    O = "Фельзерул у Стонарді хоче, щоб ви зібрали 10 артефактів Атал’ай.",
    P = "Ніхто не знає, які темні обряди відбувалися всередині Храму Атал'Хаккара. Але ми знаємо, що там використовувалися великі й могутні магічні сили.$B$BМи мусимо дізнатися якомога більше про таку магію. Можливо, заклинання Атал'аїв виявляться корисними для Орди.$B$BКоли ви зберете достатньо артефактів Атал'аїв навколо Басейну Сліз, я зможу почати розуміти, чого прагнули досягти тролі та що пішло так жахливо не так.",
    C = "Ваша старанність у зборі артефактів Аталаї заслуговує на похвалу, $C.",
},

[1425] = {
    en = "Deliver the Shipment",
    T = "Доставити вантаж",
    D = "Поки я лагоджу цей візок, $N, у мене є для тебе останнє завдання.$B$BЯ спакував найнеобхідніші припаси, врятовані від нападів огрів. Віднеси їх до фортеці Нетергард. Фортеця розташована серед північних пагорбів Спустошених земель і охороняє Темний портал.$B$BЩоб дістатися до Нетергарда, йди дорогою на схід. Коли дорога розгалужується, рухайся на південь у бік Спустошених земель, а на наступному роздоріжжі поверни ліворуч. Йдіть дорогою, $N, і будьте обережні.",
    O = "Доставте вантаж до Нетергарда, до інтенданта Лунгерца у фортеці Нетергард.",
    P = "У вас до мене є якась справа?",
    C = "Що? Посилка з каравану Біггса? Ми вже думали, що і вона, і він — загубилися.$B$BДякуємо, $N. Якщо пощастить, серед цих припасів будуть і такі необхідні нам реагенти — кристали Азорана. Наші запаси майже вичерпалися...",
},

[1426] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Я не відчуваю ніякої любові до моря, ані до жодної істоти, яку бачив, що походить з його глибин. Це могутня, але сліпа володарка; безсердечна й жорстока. Я отримав би велике задоволення, вбиваючи риболюдей сотнями, якби це було в моїх силах. Але я отримую певне задоволення, спостерігаючи за їхньою загибеллю від рук тих, хто виконує волю Орди.$B$BІ це приводить нас до тебе, $c. Скільки ти зможеш їх убити? Чи випробуєш ти себе у бою проти наймогутніших із них?",
    O = "Вбийте 10 болотних мурлоків, 10 болотних чорниловиків і 10 болотних м'ясоїдів, а потім поверніться до Катара в «Болоті Скорботи».",
    P = "Я терплячий. Терплячий і вічний, як стародавній камінь «канк» із Дренора. Люди-риби не прорвуться через наші кордони — принаймні, доки я ще стою на ногах. Якби у нашому розпорядженні була армія, я б очистив цей світ і всі інші від їхньої присутності. Я відчуваю, як моя ненависть закипає, щойно я про них згадую.",
    C = "Море здається безмежним і невблаганним, але ти заплямував його кров’ю його власного потомства. Риболюди знають, що таке біль. Їхня дурість змусить їх відновлювати свої ряди після руйнувань, які ти спричинив, і це добре.$B$BНехай їхні булькаючі крики заглушають ревіння моря аж до пізньої ночі. Я посміхатимуся щоразу, коли чутиму, як одного з них змушують замовкнути.$B$BПовертайся до мене, якщо бажаєш вбити ще більше риболюдей. Я з радістю знову винагороджу тебе.",
},

[1427] = {
    en = "Threat From the Sea",
    T = "Загроза з моря",
    D = "Перш ніж відпочити, ще раз поговори з Ток’Каром. Гадаю, поки тебе не було, він завершив роботу над кількома одиницями зброї. За твою допомогу тут він запропонує тобі одну з них. Коли будеш готовий, тобі варто випробувати її на міцність у бою з риболюдьми… але лише для того, щоб ще більше порадувати мене.",
    O = "Поговоріть із Ток'Каром у Болоті Скорботи.",
    P = "",
    C = "А, $N, ти повернувся. Добре. Я закінчив виготовляти ще зброю для нашої боротьби з мурлоками. За те, що ти приніс нам свіже м’ясо пилкозуба і викликав легку посмішку на обличчі Катара, я дарую тобі одну з них.",
},

[1428] = {
    en = "Continued Threat",
    T = "Постійна загроза",
    D = "Мені приємно бачити, що твоя ненависть до риболюдей зростає разом із моєю.$B$BЗнайди ще таких, як вони, на узбережжі, а коли наборешся боїв, повертайся до мене. Тоді ми поговоримо про нагороду за твою старанність.",
    O = "Вбийте 10 болотних чорнильних бризків, 10 болотних м’ясоїдів та 10 болотних оракулів, а потім поверніться до Катара у Болоті Скорботи.",
    P = "Я не заспокоюся, доки море та всі його мешканці не замовкнуть… особливо ці огидні риболюди.",
    C = "Молодець, $C. Я закликаю пролити ще більше їхньої крові. Нехай загинуть усі риболюди.",
},

[1429] = {
    en = "The Atal'ai Exile",
    T = "Вигнанець Аталаї",
    D = "Поки ти боровся з небезпеками «Водойми Сліз», один із моїх розвідників повернувся зі свитком, написаним кров’ю на висушеному м’ясі. Схоже, це судовий вирок щодо жерця племені Атал’ай.$B$BЦього жерця засудили до долі, гіршої за смерть серед Атал’ай.$B$BЙого заслали жити далеко на північ, у Глибину, до тролів Вітербарк.$B$BЯ зберу ці артефакти. Тобі слід розшукати засланця та з’ясувати їхнє справжнє призначення. Повернися до мене, коли завершиш свою подорож.",
    O = "Віднесіть пакунок з артефактами Аталаї до вигнанця Аталаї в Глибинках.",
    P = "Ти дуже сміливий, що прийшов сюди. Сміливий чи безрозсудний...",
    C = "Ти приніс мені артефакти для виклику Атай'аї?$B$BБачу, пророк Джаммалан веде послідовників «Камби Крові» назустріч долі, яку вони обрали. Цікаво, чи повернувся Хаккар до Храму? Чи настала їхня доля?",
},

[1430] = {
    en = "Fresh Meat",
    T = "«Свіже м'ясо»",
    D = "Серед моїх клієнтів існує великий попит на соковите м’ясо повзунів, особливо м’ясо гігантських повзунів.$B$BЯкщо ви плануєте вирушити на узбережжя, я з радістю винагороджу вас, якщо ви принесете мені кілька їхніх ніг, щоб я міг відправити їх до Оргримара.$B$BУзбережжя знаходиться на схід від цього місця, і вам не складе труднощів знайти цих істот, що метушаться вздовж пляжів та під водою.",
    O = "Принесіть 10 монструозних ніг повзуна Дару в «Болоті Скорботи».",
    P = "У мене є бочка вина, яка чекає на твій успіх, $N. Звісно, я маю скуштувати цей товар, перш ніж відправити його своїм клієнтам.",
    C = "О, це має бути просто чудово. Не можу дочекатися, щоб скуштувати їх, коли їх ідеально приготують на відкритому вогні. Тобі варто взяти з собою трохи цього на подорож. Це справді дуже смачно.",
},

[1431] = {
    en = "Alliance Relations",
    T = "Відносини в рамках альянсу",
    D = "Заспокойся, $c, і дозволь мені поділитися з тобою чимось важливим для нашого народу, але далеко не очевидним.$B$BМи — горда раса, і війна з людьми випробувала навіть велике терпіння Тралла. Розумієте, наш вождь мудрий і розважливий, і він, як і раніше, ставить інтереси свого народу понад усе. Зрештою, він — дипломат, і за час, проведений серед людей, він багато дізнався про їхні звичаї.$B$BЯкщо розповідь, яку я розпочав, зацікавила вас, то знайдіть Келдрана біля західного виходу з міста. Там знаходиться його халупа.",
    O = "Поговоріть із Келдраном в Оргримарі.",
    P = "",
    C = "Путанні, благородний $c. Я — Келдран, учень магії… та інших містичних мистецтв.$B$BСправа, з приводу якої Крейвен відправив тебе сюди, щоб поговорити зі мною, вимагає трохи більше тактовності, ніж тобі доводилося проявляти раніше, але це не означає, що ти не можеш допомогти нашій справі.$B$BБудь ласка, влаштовуйся зручніше, і я розповім тобі, чому вождь потребує моєї допомоги... і вашої.$B$BВсе починається з зовнішнього вигляду, $N. З того, як Орда бачить саму себе. Як нас бачать наші союзники. І, найголовніше, як нас бачать наші вороги.",
},

[1432] = {
    en = "Alliance Relations",
    T = "Відносини в рамках альянсу",
    D = "У міру того, як Альянс просувається все глибше й глибше в Калімдор, можуть виникнути хибні висновки про те, що Орда укладає угоди з Палаючим Легіоном. Вождь війни не може цього допустити. І з його благословення я беру на себе контроль над тим, щоб усунути тих, хто їх курирує.$B$BУ мене є агенти в районі Десоласу, на посту «Примарний мандрівник», що на північ від великого кладовища кодо. Рушайте на південь від Обвугленої долини в Горах Кам'яного Кігтя, і ви натрапите на нього. Прибувши туди, знайдіть Такату Сталеве Лезо.",
    O = "Поговоріть із Такатою Стілблейдом у Десоласі.",
    P = "",
    C = "Вітаю, $c. Ти приніс новини з Оргримара; це добре.$B$BПошесть демонів заполонила цю місцевість навіть сильніше, ніж сморід від екскрементів кентаврів. Кінні люди вважають цю землю своєю, але, очевидно, існують сили, які виходять за межі їхнього контролю і які знищать їх, якщо їх не стримати.$B$BМені не до вподоби, що ми опосередковано допомагаємо кентаврам, але це на благо Орди, тож я виконую свій обов’язок перед Вождем, навіть якщо це означає допомагати чаклунам у складі Орди.",
},

[1433] = {
    en = "Alliance Relations",
    T = "Відносини в рамках альянсу",
    D = "«Палаюче Лезо» має безліч планів, але знайте: вони до самої суті злі, їхні душі зіпсовані, і лише їхнє знищення може перешкодити реалізації їхніх цілей.$B$BКелдран відправив Мауріна зі мною саме через його знання про «Лезо» та звичаї чаклунів.$B$BВін керує нашими замовами проти «Палаючого меча», а я займаюся іншими демонічними загрозами тут, у Десоласі.$B$BПоговоріть з ним, і він вкаже вам, як діяти згідно з його планами.",
    O = "Поговоріть з Мауріном Боунспліттером у Десоласі.",
    P = "",
    C = "Ах, так. Допомога від тих, хто відданий Вождю, завжди вітається.$B$BМене звати Маурін. Я тут за дорученням Кельдрана та молодого Вождя Тралла. Я прагну допомогти молодому лідерові у боротьбі зі злом, яке загрожує його правлінню.$B$BПідійди, підійди ближче, $c. Я поясню тобі свій план щодо усунення гнійного нариву, яким є «Палаюче Лезо».",
},

[1434] = {
    en = "Befouled by Satyr",
    T = "Зневажений Сатиром",
    D = "Зараження демонами не відбувається без інших чинників — щось інше дозволяє злу закріпитися.$B$BЦе може початися з ослабленого духу, марного прагнення влади; можливо, це жага помсти або прагнення остаточної справедливості. Коли нас охоплює біль, зло користується нашою слабкістю — таке зло, як сатири.$B$BМіж ними та «Палаючим Мечем» встановлено зв’язки, і Трал хоче, щоб їх знищили. Знайдіть їх на північному сході від цього місця і поверніться до мене, коли ви їх відіб’єте.",
    O = "Знищте 7 розбійників «Ненависної люті», 7 прихильників «Ненависної люті», 7 зрадників «Ненависної люті» та 7 покликачів пекла «Ненависної люті», а потім поверніться до Такати Сталевого Клинка в Десоласі.",
    P = "Мій товариш-таурен попередив мене, що сатири не такі, якими здаються на перший погляд. Він вважає, що за ними ховається щось більше, що їхнє зло — це спотворення їхньої справжньої природи. Але я нічого такого не бачив.$B$BЯ бачу лише безжалісне винищення слабких і спотворення тих, хто прагне темної сили.$B$BЯ продовжуватиму виконувати свій обов’язок — знищувати їх, доки Вождь не дасть мені інших вказівок. До того часу я не відчуватиму до них жодного жалю.",
    C = "Ти добре впорався, $c. Ти проявив честь і відданість.$B$BКоли наша кампанія в Десоласі завершиться, Вождь дізнається, що ти допомагав нам у наших діях тут і що ти допоміг втілити його волю.$B$BЯ дякую тобі.",
},

[1435] = {
    en = "The Burning of Spirits",
    T = "Спалення спиртних напоїв",
    D = "Смерть — це найкраще, що може трапитися з тими огидними створіннями, які з таких егоїстичних міркувань зраджують свого володаря. Але смерті замало, коли йдеться про тих, хто віддався темряві.$B$BВізьми цей самоцвіт. Коли хтось із «Палаючих Мечів» опиниться на межі смерті, активуй його магію. Заклинання вирве спотворений дух із тіла жертви, залишивши після себе наповнений магією самоцвіт.$B$BПринесіть мені ці наповнені магією самоцвіти, щоб я міг належним чином їх утилізувати.$B$BІдіть тепер, і нехай вам вдасться уникнути смерті.",
    O = "Поверніть «Палаючий самоцвіт» та 15 «Насичених палаючих самоцвітів» Мауріну Кісткорозбивачу в Десоласі.",
    P = "Я намагався зробити ці магічні ритуали якомога простішими. Витягнути дух своєї жертви з її пораненого тіла має бути ділою дитячою. Не покладайтеся на силу самоцвіту, щоб повністю знищити свого ворога. Ви повинні активувати самоцвіт лише тоді, коли він буде на межі смерті, інакше це буде марно.",
    C = "А, ти повернувся з успіхом. Це добре. Віддай мені самоцвіти, і я сховаю їх у безпечне місце...$B$BТвої завдання виконано, $c. Поговори з Такатою, коли відпочинеш. Можливо, він доручить тобі інші завдання, а може, попросить повернутися до Оргримара, щоб повідомити Келдрана про наші успіхи тут, у Десоласі.",
},

[1436] = {
    en = "Alliance Relations",
    T = "Відносини в рамках альянсу",
    D = "Бій йде добре, $N. Можливо, Вождь дозволить нам повернутися додому ще до зміни пір року, якщо ми й надалі досягатимемо таких значних успіхів у боротьбі проти демонів та їхніх поплічників.$B$BПоверніться до Кельдрана й розкажіть йому про наші досягнення. Я впевнений, що він винагородить тебе за твої зусилля тут. Його справа для нього важлива, і він буде пишатися тим, що Вождь поважає його турботи.",
    O = "Поговоріть із Келдраном в Оргримарі.",
    P = "",
    C = "Ти повернувся з Десоласа з великим успіхом, $N. Дякую.$B$BДякую за твої зусилля, твій час і розуміння мого прохання. Трал розуміє і прагне миру між Ордою та Альянсом, і, вживши заходів, щоб забезпечити прийнятний вигляд нашої делегації, ми не спровокуємо жодних подальших загроз непотрібного насильства.$B$BЯ у боргу перед вами.",
},

[1437] = {
    en = "Vahlarriel's Search",
    T = "Пошук Вахларріеля",
    D = "Я — Валарріель, $N. Я прибув сюди, щоб з’ясувати місцеперебування двох зниклих представників знатного роду дарнасських купців — дому Малем. Глава роду побоюється найгіршого, і я маю зробити все, що в моїх силах, аби знайти його зниклих дітей. Я ще не розпочав пошуки Тираніса чи Далінди, але сподіваюся, що не затримаюся тут надовго.$B$BЗ останніх відомостей випливає, що кілька тижнів тому вони проїжджали через Гори Кам’яного Копита.$B$BЯкщо ви знайдете їхній віз, будь ласка, негайно прийдіть до мене.",
    O = "Знайдіть і обшукайте візок Тираніса та Далінди Малем у Десоласі.",
    P = "",
    C = "Коли ви обшукуєте уламки воза, стає очевидним, що на нього напали як за допомогою заклинань, так і зброї. Бій, судячи з усього, був одностороннім і швидким: тут немає ні крові, ні залишків тіл.$B$B Той, хто напав на віз, діяв ефективно й швидко.",
},

[1438] = {
    en = "Vahlarriel's Search",
    T = "Пошук Вахларріеля",
    D = "Знайдіть, якщо зможете, і Далінду, і Тираніса, а потім поверніться до мене з результатами своїх пошуків. Почніть пошуки з цієї фортеці. Я негайно зв’яжуся зі своїм керівництвом у Дарнасусі та повідомлю їм про ситуацію.$B$B$N, є ще дещо, на чому я хотів би наголосити. Моє керівництво висловило певне занепокоєння щодо Тираніса та його мотивів приїзду сюди. Для них важливіше, щоб Далінду знайшли та благополучно повернули. Тираніса треба... оцінити, перш ніж відправити додому.",
    O = "Знайдіть Далінду Малем у Десоласі.",
    P = "",
    C = "Слава Елуні, нарешті хтось прийшов на допомогу. Будь ласка, $C, мені потрібна твоя допомога. Мене та мого брата Тираніса захопили й привели сюди «Палаюче Лезо». Гадаю, вони мають намір принести мене в жертву своїм демонічним господарям!$B$BЯ знала, що приїжджати до Десоласу було помилкою, але Тираніс останнім часом почав жадати знань про все таємниче — навіть всупереч бажанням нашого народу. Він вирішив вирушити в цю подорож навіть після того, як почув розповіді про навалу демонів у цій землі.$B$BЯ боюся найгіршого для нього.",
},

[1439] = {
    en = "Search for Tyranis",
    T = "Пошук «Tyranis»",
    D = "Нас привели сюди після того, як орки винищили всіх наших охоронців і слуг. О, які жахливі речі вони з ними зробили! Я була впевнена, що вони вб’ють нас тут же, але стало очевидно, що в них були інші плани.$B$BТираніс спробував з ними поговорити. Гадаю, він хотів вразити їх своїми знаннями в галузі магії… Не знаю, навіщо.$B$BБлагаю, я не можу піти звідси, доки не дізнаюся, що сталося з моїм братом. Знайдіть його, а потім поверніться за мною, коли стане відомо, що з ним сталося.",
    O = "Знайдіть Тираніса Малема в Десоласі.",
    P = "Я побоююся, що Тираніс спробує дізнатися таємниці «Палаючого Меча» і приєднається до їхнього кола, якщо вони йому це дозволять — він завжди захоплювався тією силою, яку магія дарує тим, кого вона спокушає.$B$BНе впевнений, що зміг би витримати повернення додому, до своєї родини, з новиною про те, що душа Тираніса заграє з такими небезпеками. Для мого роду вже й так є жахливим злочином займатися такими речами, а стати тим, від чого ми намагаємося захиститися, — це взагалі жахливо.",
    C = "Це жахливо! Але, мабуть, це було необхідно. Якби не ти, то це неодмінно зробили б мої люди. Мабуть, я маю тобі подякувати — пробач, будь ласка, якщо це не виглядає щиро. Я не хотів нікого образити.$B$BТепер, коли я знаю про долю мого брата, здається, настав час для моєї втечі. Якщо ти все ще готовий, я прийму твою допомогу, щоб втекти з цього жахливого місця.$B$BКоли ти будеш готовий, ми зможемо вирушити в безпечне місце.",
},

[1440] = {
    en = "Return to Vahlarriel",
    T = "Повернутися до Вахларріеля",
    D = "Тож, настав час? Я ціную ваші зусилля, і якщо ситуація не складеться, дозвольте мені вже зараз подякувати вам за все, що ви зробили для мене та моєї родини. Якщо ви готові, то мені тут більше нічого робити — ми можемо вирушати, коли ви вважатимете за потрібне.",
    O = "Супроводи Далінду Малем із фортеці «Громовий сокира», а потім повернися до Вахларріеля, Вбивці демонів, у Десоласі.",
    P = "",
    C = "Дякую, $N. Далінда благополучно повернулася сюди, до Ніджел-Пойнт, і в набагато кращому стані, ніж я міг би сподіватися. Те, що вона дісталася сюди самостійно, було добрим знаком. Сподіваюся, у тебе все гаразд? $B$B Мені боляче усвідомлювати, що й Тираніс, і Далінда не повернулися, але сором за рішення Тираніс доведеться пережити їй самій. Це те, з чим їй доведеться розібратися, коли вона повернеться до Дарнассуса.",
},

[1442] = {
    en = "Seeking the Kor Gem",
    T = "У пошуках самоцвіту «Кор»",
    D = "Вітаю, $N. Чим я можу допомогти тому, хто йде святим шляхом?$B$BАх, так, Стілвелл, коваль… ще з давніх часів. Я добре його пам’ятаю, хоча вже давно не чув його імені.$B$BВін ніколи не здавався мені зухвалим чоловіком, тож я можу лише припустити, що його бажання здобути самоцвіт Кор є благородним.$B$BЯкщо ти справді бажаєш отримати один із самоцвітів, тобі слід вирушити на північний захід від Ашенвейлу. Там, серед стародавніх руїн, ти знайдеш Чорноглибінні. Наги, які досі використовують ці самоцвіти, перебувають там, внизу. Не йди сам, $c.",
    O = "Принесіть самоцвіт Кор до Тундріса Віндвівера в Темному Березі.",
    P = "Я б не так довіряв тому, хто не йде святим шляхом, якби він прийшов до мене з проханням про самоцвіт Кор. Але я довіряю вашому роду більше, ніж деяким із моїх родичів. Я не суджу весь ваш орден за діями лише одного з ваших зрадників.",
    C = "Це справді той самоцвіт, якого прагне Стілвелл, але перш ніж я дозволю тобі передати його йому, його треба очистити від скверни — наги-дівки наділяють самоцвіти силою, це правда, але своєю власною, злою силою.$B$BПовідомте Стілвелла, що сила самоцвіту не втрачена, і він має добре спрацювати в будь-якому ритуалі, частиною якого він захоче його зробити.$B$BСподіваюся, ви знаєте, що робите, $C, адже у вас у руках не простий предмет.",
},

[1444] = {
    en = "Return to Fel'Zerul",
    T = "Повернутися до Фель'Зерула",
    D = "Пророк Джаммалан засудив мене до вигнання з Храму Атал’Хаккара. Колись я вважав, що верховний жрець — гідний вождь.$B$BЙого непохитна віра у власне пророцтво призведе до знищення Аталаїв. Якщо це вже не сталося.$B$BКоли я висловив свої побоювання, мене назвали невірним і вигнали з храму.$B$BТі артефакти, які ти приніс мені, нешкідливі. Але якщо Джаммалан знайшов належне зачарування-фетиш для ритуалу виклику, світ опиниться у великій небезпеці...",
    O = "Поверніться до Фель'Зерула в Стонарді.",
    P = "",
    C = "Ми вже досить давно не спілкувалися, $C. Сподіваюся, твоя подорож була вдалою.$B$BЯкі знання ти отримав від вигнанців Атал’аї в Глибинних землях?",
},

[1445] = {
    en = "The Temple of Atal'Hakkar",
    T = "Храм Атал'Хаккара",
    D = "Тож він згадав про пророцтво Джаммалана?$B$BДуховний лідер Атал’ай вірить, що коли Хаккар повернеться до Азероту з Нетера, бог дарує племені Атал’ай безсмертя.$B$BНа мій погляд, це безглузда хитрість, яка може призвести до передчасного кінця світу.$B$BАле ти кажеш, що вигнанець згадував про зачаровані фетиші? Це мене дуже турбує. Якщо вони й справді є ключем до ритуалу Атал’аї, який спричинив цей безлад, ми мусимо з’ясувати, які сили в них приховані.$B$BЗайдіть до Храму й захопіть ці фетиші!",
    O = "Зберіть 20 фетишів Хаккара та принесіть їх Фель'Зерулу в Стонарді.",
    P = "Якщо фетиші Аталаї мають силу викликати Хаккара та здійснити пророцтво Джаммалана, їх необхідно захопити. Орда повинна зрозуміти суть таких сил!",
    C = "Хоробрий $C, ти довів, що є великим чемпіоном Орди.$B$BА тепер треба негайно розібратися з цією колекцією фетишів Хаккара!",
},

[1446] = {
    en = "Jammal'an the Prophet",
    T = "Пророк Джаммалан",
    D = "Мої товариші з Вітербарка не дуже прихильно ставляться до чужинців поблизу свого дому.$B$BА я? У мене більше немає дому. Мене вигнали з мого народу — великого племені Атал’ай з Болота Скорботи.$B$BНаш духовний лідер, Джаммалан, мав те, що він називав пророцтвом. Він вірить, що прикликання бога Хаккара принесе Атал’аї безсмертя.$B$BАле я закликав до обережності. А що, якщо це пророцтво — лише маніпуляція?$B$BЯ хочу помститися за своє вигнання. Принеси мені голову Джаммалана. Можливо, тоді мій народ стане вільним.",
    O = "Вигнанець Аталаї в Замежжя хоче отримати голову Джаммалана.",
    P = "Як тільки Джаммалана буде усунуто, у мене з’явиться шанс повернутися до свого народу.$B$BЗ Джаммаланом на чолі Атал’ай чекає неминуча загибель.",
    C = "Безрозсудна віра Джаммалана у хибні видіння привела мій народ до вічної загибелі.$B$BЯ дякую тобі, $C, за те, що ти помстився за моє вигнання. Я сумую за своїм народом. Мені немає додому, куди можна було б повернутися.",
},

[1447] = {
    en = "The Missing Diplomat",
    T = "Зниклий дипломат",
    D = "Так, ти, звісно, не найрозумніший $c з тих, хто приїхав до Штормвінда, але незабаром станеш одним із найдурніших, хто звідти ніколи не поїде.$B$BТи вже знайомий з моїми друзями?",
    O = "Переможіть Дашела Стоунфіста у Штормграді.",
    P = "Я не мав на увазі нічого поганого, коли сказав, що ти дурний $C. Ми ж друзі, правда? Ніяких образ?",
    C = "Отже, ви не просто так до мене прийшли. Що вам потрібно?",
},

[1448] = {
    en = "In Search of The Temple",
    T = "У пошуках храму",
    D = "Були часи, коли я був молодим і сповненим сил, як і ти, $c.$B$BАле тепер я старий і вже не можу мандрувати світом, як колись. Ах, скільки всього я бачив!$B$BАле була одна таємниця, яка залишилася для мене нерозкритою. У рамках мого останнього завдання Ліга дослідників відправила мене на пошуки Храму Атал'Хаккара. Ходили чутки, що він розташований у Болоті Скорботи.$B$BЧерез мою кволу старість я мандрував небесами на грифоні, шукаючи його, але так і не знайшов.$B$BДопоможеш старому гному? Можливо, тобі пощастить більше, якщо ти підеш пішки.",
    O = "Брохан Каскбеллі у Штормграді просить вас відшукати Храм Атал’Хаккара.",
    P = "Я об’їхав увесь світ — від джунглів Азерота до засніжених вершин Хаз-Модана.$B$BНіколи раніше я не просив допомоги у своїх пригодах. Але мої старі кістки втомилися.$B$BНіщо не принесло б мені більшого задоволення, ніж усвідомлення того, що я виконав своє останнє завдання для Ліги дослідників$B$BЯкщо ви будете такі люб’язні й допоможете мені знайти Храм Атал’Хаккара, $c, я буду вам дуже вдячний.$B$BПрочешіть Болото Скорботи й повідомте мені про свої знахідки!",
    C = "Храм Атал'Хаккара затонув у Басейні сліз? І його оточує зелений драконячий полк?$B$BДивовижне відкриття, $C. Але, очевидно, щось пішло страшенно не так.",
},

[1449] = {
    en = "To The Hinterlands",
    T = "У глибинку",
    D = "Як я вже згадував раніше, я спробував самостійно розвідати храм з повітря. Щоправда, я був не зовсім сам.$B$BЯ вирушив до знаменитої вольєри грифонів на Піку Аері в Замежжя. Там я заручився допомогою одного з найкращих їхніх пілотів. Пілот впав зі свого верхового звіра прямо в болото...$B$BУ моєму похилому віці ім’я того бідолахи вилетіло з голови. Господар вольєра, без сумніву, пригадає.$B$BПодорожуйте туди й розшукайте Фальстада Вайлдхаммера.$B$BНам потрібно з’ясувати, що сталося з тим пілотом.",
    O = "Поговоріть із Верховним таном Фальстадом Вайлдхаммером на Піку Орлиного Гнізда в Замежжя.",
    P = "",
    C = "Чого тобі треба, хлопче? Хіба ти не бачиш, що мені тут треба вирішувати проблеми? Хто має час стояти й базікати з якимось $R балакуном?$B$BЗ усіх боків вилазять тролі! Поспішай.",
},

[1450] = {
    en = "Gryphon Master Talonaxe",
    T = "Майстер грифонів Талонакс",
    D = "То ти, виходить, просто посіпака $g — хлопчик чи дівчинка — якогось старого дідугана з Ліги Дослідників, так?$B$BНу, то послухай мене, $c. Я не знаю, з ким твій старий приятель літав там, в Азероті. Я тобі схожий на майстра грифонів Талонакса? Схожий?$B$BЯкщо тебе так цікавлять завдання з польотів, чому б тобі не запитати самого майстра грифонів? Якщо я ще раз побачу, що ти тут без діла тиняєшся, я дам тобі справжню роботу.$B$BА тепер рухайся.",
    O = "Поговоріть з майстром грифонів Талонаксом у пташнику на Піку Орлиного Гнізда.",
    P = "",
    C = "А, так. Звісно, я пам’ятаю, як відправив одного зі своїх вершників на грифоні, щоб той допоміг Брогану Каскбеллі.$B$BУ моєму серці завжди було особливе місце для Ліги дослідників. Мій батько, до речі, допомагав у першій експедиції, яка відкрила Улдаман.$B$BЯ відправив із Броханном того, кого на той час вважав своїм найкращим вершником на грифоні. Це був хлопець на ім’я Рапсоді Шіндігер.$B$BІ який же він був вершник на грифоні! Ну, доки...",
},

[1451] = {
    en = "Rhapsody Shindigger",
    T = "«Рапсодія Шіндіггер»",
    D = "Рапсодія дуже пристрастилася до випивки. Тільки не зрозумійте мене неправильно — усі ми, гноми з цієї пташиної вольєри, любимо випити гарного елю, коли настає відповідний час.$B$BАле старий Шіндіггер пристрастився до алкоголю так само, як грифон злітає в небо. І це було справді прикро. Ніхто не міг літати так, як Рапсодія.$B$BПершою ознакою неприємностей стало те, що він повернувся, спотикаючись, із тієї місії разом із твоїм приятелем Броханом. Після цього все швидко пішло шкереберть. Довелося його звільнити.$B$BЗ того, що я чув, він облаштував пивоварний табір на схід від нас...",
    O = "Знайдіть Рапсоді Шіндіггер у Замежжя.",
    P = "",
    C = "Гік!$B$BЯ дивлюся прямо на тебе, а ти весь час підскакуєш вгору-вниз. У мене від цього крутиться голова. Хо-хо!$B$BХікуп!$B$BОго! Ти це відчув? Земля тремтить, друже. Мені треба випити.$B$BХікуп!",
},

[1452] = {
    en = "Rhapsody's Kalimdor Kocktail",
    T = "«Калімдорський коктейль» від Rhapsody",
    D = "Гік!$B$BТо цей божевільний дурень Брохан тебе прислав? Ой, у нас була справжня пригода...Гіккуп!$B$BЯкщо хочеш, щоб я розповів тобі, що сталося там, у болоті, мені знадобиться щось міцне випити. Це була не дуже приємна картина, розумієш. Гік!$B$BОсь що... принеси мені все, що треба для «Калімдорського коктейлю», і я тобі все розповім.$B$BПотрібні шлунки років із Танарісу... і, подивимося... печінки гроддоків та залізних хутрових з Фераласу...$B$BГарний міцний «Калімдорський коктейль»... ось це змусить мене розговоритися!",
    O = "Рапсоді Шіндігер із «Замежжя» просить вас принести йому 3 шлунки рока, 3 печінки гроддока та 3 печінки залізної шерсті.",
    P = "Ти коли-небудь пробував «Rhapsody Malt»? Це одне з моїх найкращих пив, якщо можна так сказати. Гік!$B$BАле якщо мені доведеться знову пережити жахи того фатального польоту над… гік… болотом, то мені знадобиться щось трохи міцніше. Гік!$B$BМоже, ти знайшов мені ті шлунки та печінки, які мені потрібні, щоб додати моєму «Калімдорському коктейлю» трохи більше запалу?$B$BГік!",
    C = "Бачу, ти без жодних проблем дістав мені те, що мені потрібно! Мабуть, у тебе там, у далекому Калімдорі, вийшла неабияка пригода.$B$BМені знадобиться лише мить, щоб витягнути з цих шлунків і печінок те, що мені потрібно. Гік!$B$BПотім я зможу зварити собі міцненьке зілля й нарешті розповісти тобі те, що ти хочеш знати.$B$BГік!$B$BМене аж морозить від однієї думки про те старе болото.$B$BГік!$B$BДай-но я швидко зб’ю собі випивку.",
},

[1453] = {
    en = "Reclaimers' Business in Desolace",
    T = "Бізнес рекуператорів у Десоласі",
    D = "У Десоласі, $N, є робота. Це жахливе місце, заполонене кентаврами та іншими потворами. Але якщо ти хочеш чесно попрацювати цілий тиждень, то вирушай туди, зустрінься з Крелдігом Унгором і скажи йому, що я тебе послав.$B$BВи знайдете його в Ніджелс-Пойнт — це невеликий затишний табір, захований у горах на півночі Десоласу. Просто рухайтеся на схід, якщо входите зі Стоунталонських гір. Його легко пропустити, тож будьте пильні.",
    O = "Поговоріть із Крелдігом Унгором у Десоласі.",
    P = "",
    C = "Радий бачити, що «Реклаймерам» не бракує ані роботи, ані шукачів пригод, готових допомогти.$B$BЯ — Крелдіг, $N. Ти вчинив мудро, вирішивши допомогти «Реклаймерам». У наш час кожному щось потрібно: хтось втратив сімейну реліквію, хтось — магічний предмет, а хтось — кохану людину. Ніколи не знаєш, що може трапитися. Але з «Реклаймерами» поруч немає причин, щоб за відповідну ціну кожен не зміг знайти те, що втратив.",
},

[1454] = {
    en = "The Karnitol Shipwreck",
    T = "Затонулий корабель «Карнітол»",
    D = "Перше, що я маю зробити, стосується мага Карнітола — якогось аристократа зі Штормвінда. Схоже, його корабель зазнав нападу морських велетнів біля північно-західного узбережжя Десоласу. Він та його слуги намагалися винести на берег одну з найцінніших скринь, але коли морські велетні накинулися на них цілими зграями, він вирішив покинути скриню й телепортувати себе та своїх слуг у безпечне місце.$B$BВін хоче, щоб ми знайшли скриню та її вміст і повернули їх йому у Штормграді.",
    O = "Знайдіть скриню Карнітола в Десоласі.",
    P = "",
    C = "Ви помічаєте, що скриня, судячи з усього, не має слідів пошкодження від води.$B$BДалі ви помічаєте, що кришка скрині була силоміць відкрита, а будь-які магічні пастки, встановлені для її захисту, вже давно спрацювали — про це свідчать сліди опіків по краях кришки.",
},

[1455] = {
    en = "The Karnitol Shipwreck",
    T = "Затонулий корабель «Карнітол»",
    D = "Ви витрачаєте кілька хвилин, щоб з’ясувати, чим саме було розбито скриню, і помічаєте вздовж боків та зверху скрині довгі, глибокі подряпини, які свідчать про те, що нею цікавилося щось інше, ніж людина чи велетень. Ці сліди не схожі на ті, що могли б залишити кинджал чи меч.$B$BПереглянувши вміст скрині, ви виявляєте, що вона повністю порожня.$B$BНе маючи іншого виходу, ви закриваєте скриню й готуєтеся піти. Крелдіг буде розчарований.",
    O = "Поверніться до Крелдіга Унгора в Десоласі.",
    P = "",
    C = "Ласкаво просимо назад до «Ніджелс-Пойнт», $N. Тож, розкажи, що ти знайшов.$B$BЩо!? Нічого? Боюся, що за порожній скриню нам не заплатять.$B$BРозкажи мені докладніше про ті сліди, які ти бачив… про ці порізи.",
},

[1456] = {
    en = "The Karnitol Shipwreck",
    T = "Затонулий корабель «Карнітол»",
    D = "Цікаво.$B$BНу, можливо, ще не все втрачено.$B$BУздовж того самого узбережжя, але на північ, поблизу острова Раназджар, на дні океану знаходяться руїни нічних ельфів. Плем'я нагів, «Слизьові Клинки», оселилося там. Гадаю, це наш найкращий варіант.$B$BЯкщо розвідувальний загін дістався так далеко на південь, то він, мабуть, був досить потужним. Якщо ти збираєшся знайти речі Карнітола, я б почав із найпотужніших нагів: мисливців за припливами або морських відьом.",
    O = "Знайдіть сумку Карнітола та поверніть її Крелдігу Унгору в Десоласі.",
    P = "Не хочу нікого образити, хто б цей Найджел не був, але цей табір — не найкомфортніше місце, де я коли-небудь ночував, якщо ти розумієш, про що я, $N.",
    C = "Це чудово, $N! Ти знайшов речі Карнітола! $B$B Ці кляті наги, завжди створюють проблеми. Гадаю, я б краще провів життя у війні з Ордою, ніж мав би боротися проти їхнього роду. Ти зробив велику послугу «Відвойовникам».",
},

[1457] = {
    en = "The Karnitol Shipwreck",
    T = "Затонулий корабель «Карнітол»",
    D = "Віднеси речі Карнітола до Роттена в Айронфорджі, і він заплатить тобі за добре виконану роботу.$B$BХа-ха, якщо ти не будеш обережним, він буде настільки задоволений тобою, що запропонує тобі приєднатися до нас на постійній основі.$B$BЩе раз, чудова робота, $N.$B$BБудь обережним на зворотному шляху і не затримуйся надто довго — Карнітол не найтерплячіший з людей, але, попри це, він дуже щедрий.",
    O = "Віднесіть сумку Карнітола до Роттена Стоунхаммера в Айронфорджі.",
    P = "Справи йдуть на підйомі, $N, і в мене небагато часу на запитання. Якщо у вас є справи з «Реклаймерами», то давайте про це поговоримо. Якщо ні, то мені доведеться попросити вас звернутися до когось із моїх підлеглих — вони цілком впораються з усіма справами тут.",
    C = "Ага, справа з Карнітолом у Десоласі. Чудово!$B$BОтже, скриня знищена, але всі предмети тут, так? Ну, нехай він сам це вирішує. Один із плюсів цієї справи, якою я тут займаюся, полягає в тому, що якщо вони незадоволені, я можу сказати їм, щоб пішли до біса! Вони покладаються на нас, щоб ми знайшли їхні речі... а не дбали про те, щоб усе було гарненьке й у хорошому стані, коли вони їх отримають назад.$B$BГарна робота, $N. Давай подивимося, як тобі виплатити гонорар.",
},

[1458] = {
    en = "Reagents for Reclaimers Inc.",
    T = "Реагенти для компанії «Reclaimers Inc.»",
    D = "Одне з моїх завдань тут полягає в тому, щоб дістати кілька реагентів для Лефтвіч, гном-мага з Хараноса. Роеттен, здається, вважає, що це легкі гроші, оскільки ми й так уже тут. Йому байдуже, що у нас і так не вистачає людей.$B$BПерші кілька пунктів у його списку дістати має бути досить просто, і той, хто мені допоможе, отримає чималу суму грошей.$B$BМені потрібні роги та кігті сатира Ненависної Фурії, що мешкає на схід від нас. Принесіть їх мені, і ми візьмемося за решту списку.",
    O = "Принесіть 10 «Кігтів Ненависті» та 10 «Рогов Ненависті» Крелдігу Унгору в Десоласі.",
    P = "Сатири — огидні створіння. За переказами, вони якось пов’язані з нічними ельфами, але я не дуже в це вірю.$B$BГадаю, така думка з’явилася через того одного ельфа, який кілька років тому втягнув їх у війну. З тих пір світ вже не той. Він став набагато небезпечнішим і набагато страшнішим.",
    C = "Добре, добре, $N. Не впевнений, чи вони хорошої якості, але якщо Leftwitch хотів якийсь конкретний тип, то йому слід було вказати це ще до того, як відправляти сюди «Реклаймерів».$B$BЩо скажеш, перейдемо до наступного пункту його списку?",
},

[1459] = {
    en = "Reagents for Reclaimers Inc.",
    T = "Реагенти для компанії «Reclaimers Inc.»",
    D = "Наступним у списку Leftwitch є… подивимося… хм. О, ось воно.$B$BДосить просто, але в його вказівках все досить чітко викладено. Йому потрібна отрута скорпаші та шкура якогось кодо. У дрібному шрифті зазначено, що обидва інгредієнти мають бути від конкретних істот: отрута має бути від будь-якого скорпаші, а шкура — від старого кодо, а не від вмираючого чи древнього.$B$BМаги, кажу вам, деякі речі, яких вони хочуть... просто дивні.",
    O = "Принесіть 7 флаконів отрути скорпаші та 3 витримані шкури кодо до Крелдіга Унгора в Десоласі.",
    P = "Вибач, що не зміг підказати тобі, де знайти кодо чи скорпаші. Я не дуже добре знаю цю місцевість і ще не встиг її дослідити.",
    C = "Твоя допомога тут — справжнє благо, $N. Завдяки тобі час, який я проведу тут, у Десоласі, скоротиться щонайменше вдвічі. З твоєю допомогою я миттю повернуся до Айронфорджа, щоб зігріти ноги.$B$BКоли ми впораємося з цим списком і я повернуся додому, зазирни до мене — я обов’язково пригощу тебе елем.$B$BА поки що давай зберемо решту цих реагентів.",
},

