[1699] = {
    en = "The Rethban Gauntlet",
    T = "Рукавиця Ретбана",
    D = "Я називаю своє випробування «Випробуванням Ретбана». Щоб пройти його, потрібно лише увійти в Печери Ретбана, дійти до першого розгалуження, а потім повернутися сюди. Просто! Тільки ось є кілька нюансів...$B$BТи повинен повернутися протягом години.$B$BНа шляху стоїть ціла зграя гнолів з Редріджа.$B$BПерш ніж вирушати, ви маєте випити ковток фірмового напою моєї родини — «Ячмінного окропу»!$B$BТо що скажете? Печери Ретбан розташовані в передгір’ях на північ від Лейкширу. Чи готові ви пройти випробування Ретбан?",
    O = "Увійдіть до Печер Ретбана, дійдіть до першого розгалуження і поверніться до Йоруса Барлібрю в межах відведеного часу.$B$BВи не повинні загинути й покинути цей світ.",
    P = "",
    C = "Ти це зробив! Молодець! Три рази «ура» за $N!",
},

[1700] = {
    en = "Grimand Elmore",
    T = "Гріманд Елмор",
    D = "Я зробив копію своїх нотаток про техніки, які вивчив під час виготовлення твоїх обладунків, і мені потрібно, щоб їх передали Гріманду Елмору. Він перебуває тут, у Дварфському кварталі, у крамниці зброї.$B$BІ пригнися, коли будеш передавати йому ці нотатки. Він дуже пишається своїми навичками і йому не сподобається думка, що він чогось навчився від мене...",
    O = "Віднесіть нотатки Фурена до Гріманда Елмора.",
    P = "Вітаю, радий вас бачити. Чим можу вам допомогти?",
    C = "Це Фурен написав? Як він посмів! Адже я навчила його всьому, що він знає! Думати, що він може мене чогось навчити, — це обурливо! Обурливо!$B$BХм... але в його нотатках є дещо, що я хотіла б спробувати...",
},

[1701] = {
    en = "Fire Hardened Mail",
    T = "Пошта, випробувана вогнем",
    D = "Отже, я подарував тобі гарний щит, але на цьому не обов’язково зупинятися. Я знаю секрети виготовлення надзвичайно міцних кольчужних обладунків. Це нелегко, і для цього потрібні дуже рідкісні матеріали, але якщо ти готовий докласти зусиль, я зроблю для тебе такий предмет.$B$BЩо скажеш, $N? Якщо ти готовий прийняти виклик, я дам тобі список того, що потрібно дістати, і де це можна знайти.",
    O = "Зберіть матеріали, які потрібні Фурену Довгобородому, і принесіть їх йому до Штормграда.",
    P = "Як проходить квест, $N? У тебе є все необхідне?",
    C = "Ти все зрозумів? Чудово! Я вже боявся, що ті химери тебе точно зжеруть!$B$BНу що ж, давай візьмемося за цю броню...",
},

[1702] = {
    en = "The Shieldsmith",
    T = "«Коваль щитів»",
    D = "Ти справді продемонстрував, на що здатний, коли пройшов «Випробування Ретбана», $N. А я дотримуюся свого слова. Я дам тобі обіцяну нагороду...$B$BТільки вона знаходиться у Штормграді.$B$BПоговори з моїм другом, Фуреном Довгобородим, у Дварфському районі Штормграда. Він — найкращий майстер щитів, якого ти коли-небудь зустрінеш, і він у мене в великому боргу.$B$BОсь, віднеси Фурену цю бочку «Ячмінного ошпарювача» і попроси в нього щит. Він дасть тобі гарний.",
    O = "Принесіть бочку Скалдера Фурену Довгобородому.",
    P = "Привіт! Сьогодні якось сухо, чи не так?",
    C = "А, Барлібрю Скалдер. Чудова річ! То ти був у Йоруса, так?$B$BЯ можу дістати тобі щит, так, сер! Кращого ти не знайдеш, і це не брехня!",
},

[1703] = {
    en = "Mathiel",
    T = "Матіель",
    D = "Я зробив копію своїх нотаток про техніки, які я освоїв під час виготовлення вашої броні, і мені потрібно, щоб їх передали ковалю Матіелю. Він мешкає в Дарнассусі, що досить далеко, але я впевнений, що він буде дуже вдячний, дізнавшись про те, чого я навчився.",
    O = "Віднесіть нотатки Фурена до Матіель.",
    P = "Вітаю вас, $C.",
    C = "Це цікаво, справді дуже цікаво. Мій колега-карлик Фурен зробив справді грандіозне відкриття!$B$BДякую, $N. Для мене буде честю застосувати його нові методи у моїх власних ремеслах.",
},

[1704] = {
    en = "Klockmort Spannerspan",
    T = "Клокморт Спаннерспан",
    D = "Я зробив копію своїх нотаток про техніки, які освоїв під час виготовлення твоїх обладунків, і мені потрібен хтось, хто б доставив їх Клокморту Спаннерспану. Він — гном-коваль у Центрі відновлення Гномерегана, і коли він дізнається про те, чого я навчився… Готовий побитися об заклад, що він від радості вирве собі бороду.",
    O = "Віднесіть «Нотатки Фурена» Клокморту Спаннерспану.",
    P = "Доброго дня, або доброго ранку, або доброго вечора. Звідси, знизу, мені важко це визначити. Тож, у вас є до мене якась справа?",
    C = "Ой-ой! Ці ноти просто неймовірні! І що ще... вони неймовірні, вони приголомшливі, і від них у мене аж коліна тремтять!$B$BФурен зробив прорив! Справжній прорив! Не можу дочекатися, щоб випробувати його нову техніку!",
},

[1705] = {
    en = "Burning Blood",
    T = "«Палаюча кров»",
    D = "Мені не хочеться визнавати, що Фурен, можливо, справді щось відкрив. Але щоб переконатися, мені доведеться випробувати його методи на новому елементі обладунків. Якщо ти допоможеш мені з матеріалами, $N, то ці обладунки будуть твоїми.$B$BЩоб виготовити цю броню, мені потрібні зразки палаючої крові та палаючого каменю.$B$BЄдине місце, де їх можна дістати, — це Сутінковий ліс. Воргени «Нічного прокляття», що базуються в шахті «Роландська загибель», мають палаючу кров, а їхній ватажок Гутспілл — камінь.$B$BНехай удача дарує тобі швидкість, $N.",
    O = "Принесіть 20 флаконів «Палаючої крові» та 1 «Палаючий камінь» Гріманду Елмору в Штормграді.",
    P = "$N, у тебе є «палаюча кров» і «камінь»? Вони мені знадобляться, щоб завершити створення обладунків.",
    C = "Гарна робота! А тепер, якщо ви мене вибачите, мені самому треба трохи попрацювати...",
},

