[1998] = {
    en = "Fenwick Thatros",
    T = "Фенвік Татрос",
    D = "Лорд Варіматрас щойно надіслав мені повідомлення про загрозу для Забутих, яку необхідно негайно усунути. Його ім’я — Фенвік Татрос, і лорд Варіматрас вважає його ватажком нежиті, яка оселилася в Сріблястому лісі.$B$BЯ одразу згадав про тебе, $n. Я настільки впевнений у твоїх здібностях, що ти бездоганно виконаєш цю місію.$B$BОстанні звіти від «Смертошукачів» у Срібному Лісі свідчать, що Татроса можна знайти поблизу занедбаного причалу на озері Лордамер.",
    O = "Вбийте Фенвіка Татроса і принесіть його голову Меннету Каркаду в «Квартал розбійників» у Підмісті.",
    P = "Я поклав на тебе найповнішу довіру щодо виконання цієї служби для лорда Варіматраса.",
    C = "Ти добре впорався, $N. Мені здається, що ти зробив багато корисного для «Смертошукачів», довівши свою цінність, і, можливо, настав час продовжити твоє навчання мистецтву тіней.",
},

[1999] = {
    en = "Tools of the Trade",
    T = "Інструменти професії",
    D = "Чарівники Кірін-Тор в Амберміллі сховали важливі документи, що стосуються поточного стану Даларана. Про це нам стало відомо зі зізнань одного з наших полонених. Лорд Варіматрас доручив «Смертошукачам» завдання їх повернути.$B$BЦе завдання покладається на тебе, $n. Однак тобі знадобиться деяке спорядження та навички відмикання замків. Поговори з Естель Гендрі, нашою постачальницею спорядження, і попроси її надати тобі набір інструментів, перш ніж вирушати в дорогу.",
    O = "Знайдіть «Звіт про стан справ у Даларані» та поверніть його Меннету Каркаду в «Кварталі розбійників» у Підмісті.",
    P = "Ви вже знайшли документи, $N?",
    C = "Дуже добре, $N! Ти чудово опанував мистецтво відмикання замків, і набагато швидше, ніж я міг би очікувати. $B$BБачу, я не помилився, довірившись тобі. Повір мені, хлопче, я передбачаю, що ти далеко зайдеш у цій справі.",
},

[2038] = {
    en = "Bingles' Missing Supplies",
    T = "Зниклі запаси у Бінглза",
    D = "Ніби падіння в озеро не було достатньою бідою, так ще й троги з сусіднього острова напали на мене та вкрали мої інструменти й спеціальні вибухові речовини «Бластенхаймер Бластенкаппер». Без гірокоптера та вибухівки у руху немає жодних шансів!$B$BПоверни мої інструменти та знайди мої вибухівки «Бластенкаппер», $N. За Гномереган!",
    O = "Знайдіть і поверніть інструменти Бінглза: $B$B гайковий ключ Бінглза, викрутку Бінглза, молоток Бінглза та відбійний молоток Бінглза.",
