},

[2039] = {
    en = "Find Bingles",
    T = "Знайти Bingles",
    D = "Ми втратили зв'язок із Бінглсом! Його відправили на розвідувальну місію над Гномереганом, і він не виходив на зв'язок уже понад тиждень. Я просто впевнений, що він загинув, підірвавши себе.$B$BВостаннє його бачили, коли він пролітав над озером. Можливо, ти зможеш це розслідувати, $N.",
    O = "Знайдіть Бінглза Бластенхаймера в Лох-Модані.",
    P = "",
    C = "Тож Гноарн не довіряє моїм розвідувальним здібностям? Цікаво, чому...$B$BТа нехай це буде, мені потрібна твоя допомога! Ні! Руху потрібна твоя допомога!",
},

[2040] = {
    en = "Underground Assault",
    T = "Підземний штурм",
    D = "Гномереган потрапив під контроль тих підлих трогів! Ситуація серйозна, але, можливо, ти зможеш допомогти, $N.$B$BГлибоко в Мертвих копальнях знаходиться справний гоблінський подрібнювач. Знайди цей подрібнювач і принеси назад неушкоджений блок живлення. За допомогою блоку живлення подрібнювача ми зможемо забезпечити наші гіродрильматичні екскаватори енергією, необхідною для пробиття скелястих підземних кордонів Гномерегана, відкривши шлях для штурму гномів!",
    O = "Знайдіть «Гноамський Спреклспрокет» у «Мертвих копальнях» і поверніть його Шоні Шиленту в Штормграді.",
    P = "Ти вже знайшов Гноама Спреклспрокета, $N?",
    C = "Молодець, $N. Завдяки тобі Гномереган на крок наблизився до дня свого визволення!",
},

[2041] = {
    en = "Speak with Shoni",
    T = "Поговоріть із Шоні",
    D = "Можливо... Можливо, ти зможеш допомогти нам у битві за Гномереган.$B$BУ Штормграді ти знайдеш командира нашої підпільної штурмової групи — Шоні Тиху. Шоні потрібна допомога з її гіродрильматичними екскаваторами.$B$BВи, ймовірно, знайдете її серед гномів у Штормграді.$B$BУдачі, $N.",
    O = "Поговоріть із Шоні Мовчазним у Штормвінд.",
    P = "",
