[2078] = {
    en = "Gyromast's Revenge",
    T = "Помста Гіромаста",
    D = "Сухопутний, тобі треба знайти мого першого помічника.$B$BВізьми цей ключ, засунь його йому в горло і приведи його сюди, щоб він служив капітану.$B$BТі мурлоки та їхній вождь не будуть надто раді, коли мій перший помічник їх дістане!",
    O = "Знайдіть першого помічника Гелкака — «Тресваконатор 4100» — і приведіть його назад до Гелкака.",
    P = "Де ж мій перший помічник, $N? Якщо не поквапишся, тебе незабаром чекають кайдани й акули!",
    C = "Яррр... Ти доводиш, що ти не просто боягузливий морський вовк, сухопутний матрос.$B$BЯкщо так і далі триватиме, капітан може підвищити тебе до матроса на кормовій палубі...",
},

[2098] = {
    en = "Gyromast's Retrieval",
    T = "Повернення «Гіромаста»",
    D = "Життя пірата — нелегке, сухопутний. Це не тільки грабунки та випивка! На жаль, мій корабель затонув неподалік від берега через цих набридливих трешадонів.$B$BМені конче потрібен мій перший помічник у робочому стані!$B$BКоли я виплив на берег, ключ від мого першого помічника зламався об скелі, а його розкрали звірі з Темного берега. Краєм ока я побачив, як кілька «Лютьових повзунів», «Свирепих лісових мандрівників» та мурлоків порпаються в уламках...",
    O = "Знайдіть три частини ключа Гелкака та поверніть їх Гелкаку Гіромасту.",
    P = "Ти, сухопутний, знайшов, що у мене зламався ключ?",
    C = "Гей, ти, мерзенний морський пес! Ти це зробив! Незабаром мій перший помічник знову буде в боєготовності, і ті тварюки навіть не зрозуміють, що на них навалилося!$B$BГм, ти, бува, не бачив мого першого помічника?",
},

[2118] = {
    en = "Plagued Lands",
    T = "Заражені землі",
    D = "По Темному Березі поширюється хвороба, що охоплює розум і тіло кожного, кого вона торкається.$B$BНайбільше від цієї чуми постраждали Бур’янові Ведмеді. Ці колись благородні звірі тепер стали знаряддям руйнування — скажені й несамовиті. Можливо, у мене є ліки від цієї недуги.$B$BВіднеси цю пастку до лісу й постав її на землю. Будь-який скажений «Чортолобовий ведмідь», що перетне світло, на короткий час стане покірним. Коли ведмідь заспокоїться, він піде за тобою. Приведи його сюди, $N.",
    O = "Зловіть живого скаженого чортополохового ведмедя та приведіть його до Тарнаріуна.$B$BЯкщо вам не вдасться зловити скаженого чортополохового ведмедя і ви втратите пастку, поверніться до Тарнаріуна-Доглядача дерев і попросіть ще одну пастку.",
    P = "Ти приніс мені хвору тварину, $N?$B$BЯкщо тобі не вдасться розчепірити пастку, не переймайся — Надія Тарнаріуна вічна. Якщо тобі знадобиться ще одна пастка, покинь це завдання й повернися до мене.",
    C = "Наша робота тільки-но розпочалася, $N. Чи готові ви до наступного завдання?",
},

[2138] = {
    en = "Cleansing of the Infected",
    T = "Очищення інфікованих",
    D = "Як я й побоювався, ліки не допомагають.$B$BМені дуже прикро наказувати вбити будь-яку тварину, створену природою, але хворих і заражених будякових ведмедів необхідно приспати.$B$BПовернися до лісу й знищ 20 скажених чортополохових ведмедів, $N. Це, звісно, не покладе край епідемії, але на деякий час сповільнить шкоду, яку ці тварини завдають нашому лісу та його мешканцям.",
    O = "Знищте в лісі 20 скажених чортополохових ведмедів і поверніться до Тарнаріуна, доглядача дерев, у Темному березі.",
    P = "Ви вже виконали завдання?",
    C = "Ти зробив велику послугу Аубердіну, $N, але твоє завдання ще не виконано.",
},

[2139] = {
    en = "Tharnariun's Hope",
    T = "Надія Тарнаріуна",
    D = "Виживання нашого народу та наших земель супроводжується сумними втратами, $N.$B$BВи пролили кров слуг природи; ви вбили багато хворих тварин. Мешканці Аубердіна в боргу перед вами, бо біль лісу полегшився — хай навіть лише на мить.$B$BУ мене є для вас останнє завдання, але майте на увазі: вам доведеться знову вбивати. Я сподіваюся, що це буде останній раз, коли я звертаюся до тебе, $N.$B$BУ печері на північному сході, поблизу Башал'Арана, мешкає Мати Лігва. Вбий її.",
    O = "Знайди та вбий «Матір лігва».",
    P = "Після того як заражена «Мати-щур» була вбита, кількість скажених чортополохових ведмедів, що проникають на нашу територію, зменшилася. Не гай часу, $N.",
    C = "Ти відважно й з честю боровся за Аубердін, $N. На наших розтерзаних війною землях смерть і відчай — звичне явище. Багато хто не наважиться прийняти виклик життя в нашій новій батьківщині, воліючи замість цього ховатися у своїх домівках або втікати до краще укріплених земель Альянсу.$B$BДякую, $N. Можливо, вже незабаром ми будемо битися пліч-о-пліч як товариші проти іншого ворога.",
},

[2158] = {
    en = "Rest and Relaxation",
    T = "Відпочинок та релаксація",
    D = "Кожен мандрівник повинен відпочити, коли настає виснаження — і немає кращого місця для відпочинку та розслаблення, ніж корчма «Гордість Лева»!$B$B«Гордість Лева» веде мій найкращий друг, корчмар Фарлі. Якщо ви скажете йому, що я вас направив, він, можливо, надасть вам спеціальні знижки на їжу та напої.$B$BЩоб знайти готель «Лев’яча гордість», рухайтеся звідси на південь вздовж дороги — ви його точно не пропустите!",
    O = "Поговоріть із господарем готелю «Гордість Лева» Фарлі.",
    P = "",
    C = "Відпочинок і розслаблення для тих, хто втомився і замерз — ось наше гасло! Будь ласка, сідайте біля каміна й дайте відпочинок своїм втомленим кісткам.$B$BЧи не хотіли б ви скуштувати дещо з наших вишуканих страв та напоїв?",
},

[2159] = {
    en = "Dolanaar Delivery",
    T = "Доставка Dolanaar",
    D = "Вітаю, юний $c. Чи не міг би ти мені допомогти? У мене є пакунок з травами, який я мушу доставити до міста Доланаар. Але я ще маю справи з друїдами Тіньової Долини і поки що не можу вирушити в дорогу.$B$BЧи не могли б ви доставити цю посилку за мене? Її треба передати трактирнику Келдаміру в таверні Доланаара. Вона розташована вздовж дороги, на південь.",
    O = "Віднесіть «Доставку Доланаара» до трактирника Келдамира.",
    P = "Чим я можу тобі допомогти, юний друже? Ти завітав сюди, щоб відпочити в корчмі? Тобі потрібен камінний камінь?",
    C = "Ах так, доставка трав із Шейдоуглену. Шкода, що Портанніус не зміг привезти їх сам, адже нам із ним є про що поговорити. Але я все одно радий отримати ці трави, і радий, що ти завітав.$B$BПоки ти тут, будь ласка, відпочинь. Герої повинні зберігати сили та бадьорість духу, а також знаходити відпочинок і розраду, коли тільки можуть. Адже нехтувати спокоєм тіла й душі — це прямий шлях до поразки.$B$BТож… відпочивай.",
},

[2160] = {
    en = "Supplies to Tannok",
    T = "Постачання до Таннока",
    D = "Гей! Ти виглядаєш на справжнього мандрівника. Якщо ти збираєшся подолати перевал, чи не міг би ти заодно доставити посилку до готелю в Хараносі?$B$BТи ж планував зупинитися в тому готелі, правда? Якщо ти пройдеш через перевал, то там точно захочеш трохи перепочити.$B$BУ будь-якому разі, віднеси це Танноку Фростхаммеру, помічнику господаря корчми. Я сам не можу пройти через перевал, а до прибуття супроводу альпіністів ще кілька днів!",
    O = "Доставте ящик з припасами для заїжджого двору Танноку Фростхаммеру в Хараносі.",
    P = "Привіт! Заходьте, сідайте біля каміна та зігрійтеся кухлем елю.",
    C = "Ах, нарешті, постачання від «Хендс»! Я вже почав хвилюватися, адже з Анвілмара майже не було звісток, відколи троги захопили перевал.$B$BДякую, що приніс це мені, $N. І, будь ласка, влаштовуйся зручніше. Ти, мабуть, втомився після подорожі.",
},

[2161] = {
    en = "A Peon's Burden",
    T = "Тягар наймита",
    D = "Вибачте? Ви можете мені допомогти?$B$BУ мене тут ціла купа їжі. Я йшов дорогою, перемагаючи скорпідів, павуків та ще гірших тварюк! Я приніс цю їжу до Долини Випробувань, бо подумав, що вона їм потрібна, та й я люблю допомагати. Але їм їжа не потрібна! Тепер мені доведеться віднести її назад на Гору Бритви, а я боюся всіх тих звірів, що зустрінуться на шляху...$B$BЧи не могли б ви віднести її за мене? Я лише простий робітник, а ви — герой. Ви нічого не боїтеся!$B$BВіднесіть її корчмареві Гроску в корчмі на Горі Бритви. Дякую!",
    O = "Віднесіть «Тягар Укора» до трактирника Гроска в Разор-Хіллі.",
    P = "Ласкаво просимо до «Рейзор-Хілл»!",
    C = "А, це ж їжа, яку Укор приніс до Долини Випробувань. Їм вона не знадобилася? Ну, мабуть, вони люблять морити голодом вас, героїв-стажерів. Кажуть, це загартовує дух!$B$BДякую, що повернули їжу. Я покладу її назад на полиці… але спочатку дозвольте мені запропонувати вам щось підкріпитися!$B$BІ не забудьте відпочити тут, у корчмі. Можливо, ти й хоробрий $C, готовий підкорити світ, але якщо твоя енергія вичерпається, ти не принесеш користі ані собі, ані Орді.",
},

[2178] = {
    en = "Easy Strider Living",
    T = "«Easy Strider Living»",
    D = "Чи відчуваєте цей чудовий аромат? Це мій секретний рецепт, $N — рагу зі свіжих страйдерів. Смакота!$B$BМоже, тобі цікаво дізнатися цей рецепт?$B$BПерш ніж я навчу тебе готувати, тобі доведеться довести, що ти впораєшся з цими тваринами.$B$BЗвісно, я не очікую, що ви підете, приручите одного і привезете його до мене верхи, але якщо ви зможете вбити кількох і принести трохи їхнього соковитого м’яса, я, можливо, погоджуся показати вам, як готувати рагу зі страйдерів.",
    O = "Принесіть 5 шматків м’яса страйдера Аланндаріану Найтсонгу в Аубердіні.",
    P = "Каструля порожня, а я голодний! Чому ти так довго?",
    C = "Чудово! Спробуй і скажи, що думаєш, $N!",
},

[2198] = {
    en = "The Shattered Necklace",
    T = "Розбите намисто",
    D = "Ви знайшли потемніле намисто, хоча за цим потемнінням ховається витончена й чарівна майстерність. Намисто розбилося, і, судячи з усього, в оправі бракує трьох дорогоцінних каменів. На зворотному боці намиста видно ледь помітний відбиток міської печатки Айронфорджа. Під печаткою викарбувано три крихітні літери: «TdK».$B$BЯкщо з цього намиста можна щось висновувати, вам доведеться дізнатися про його походження. Можливо, печатка та ініціали стануть відправною точкою...",
    O = "Знайдіть того, хто спочатку створив розбите намисто, щоб дізнатися про його можливу цінність.",
    P = "Ти помилився гномом, друже! Мене там ніколи не було! Ти нічого не зможеш довести!$B$BЗачекай-но... а ти хто такий? Що за... де ти знайшов цей кулон?",
    C = "Так... Я — ювелір, який виготовив це намисто. Я також не займаюся тим, щоб роздавати інформацію, ніби вона безкоштовна. Інформація ніколи не буває безкоштовною, друже. Якщо я маю тобі допомогти, то спочатку ти повинен допомогти МЕНІ.",
},

[2199] = {
    en = "Lore for a Price",
    T = "Знання за певну ціну",
    D = "Я — ювелір, який користується великою славою тут, в Айронфорзі! Ну, принаймні, раніше користувався... Я потрапив у скрутне становище через підступність конкурента! Погана репутація в цій справі означає фінансову катастрофу. У результаті я залишився без жодної мідяки, хоча моє ім’я й досі залишається добрим, хоч і заплямованим.$B$BЯ хочу, щоб ти дістав для мене п’ять срібних злитків, щоб я міг виконати замовлення, яке отримав — перше за, здається, цілу вічність.$B$BДістань мені ці п’ять срібних злитків, і я відповім на твої запитання щодо намиста.",
    O = "Принесіть п’ять срібних злитків Талвашу дель Кісселю в Айронфорджі.",
    P = "Ти вже дістав ті п’ять срібних злитків, про які я просив? Я розповім тобі свою сумну історію про намисто, яке зараз у тебе є… але тільки після того, як отримаю ці злитки! Будь ласка, допоможи гному, добре?",
    C = "На мою думку, ти в порядку; мені байдуже, що про це говорять інші... Жартую, жартую! А якщо серйозно, дякую, друже.$B$BТепер щодо твого намиста: це одне з моїх найкращих творінь, але в ньому бракує трьох самоцвітів, які допомагають прив’язати до нього магічну силу. Я виготовив його для паладина деякий час тому. Він самовільно вирушив на місію, щоб очистити від «злої скверни» місце розкопок у Пустках під назвою Улдаман.$B$BНу... той паладин загинув в Улдамані, і це був лише початок моїх бід.",
},

[2200] = {
    en = "Back to Uldaman",
    T = "Назад до Улдамана",
    D = "Один із моїх конкурентів поширив чутку, нібито моє намисто наклало прокляття на паладина. Зрозуміло, що ніхто не хоче купувати прокляті речі у ювеліра.$B$B$N, давай домовимося — знайди дорогоцінні камені, а я зберу намисто, за умови, що ти будеш розголошувати, що я НЕ виготовляю прокляті предмети!$B$BСпробуйте пошукати підказки в Ульдамані; можливо, там лежить тіло паладина, адже саме він, як ми знаємо, мав його останнім! Коли знайдете самоцвіти, скористайтеся цим; це дозволить вам зв’язатися зі мною тут, в Айронфорзі.",
    O = "Шукайте в Улдамані підказки щодо того, де зараз перебуває намисто Талваша. Убитий паладин, про якого він згадував, був останньою людиною, у якої воно було.",
    P = "",
    C = "Останки паладина: З щоденника стає відомо, що після тривалих зусиль паладин встановив місцезнаходження всіх трьох зниклих самоцвітів:$B$BКарлики з Тіньової Кузні сховали рубін у своїй укріпленій зоні під час битви з трогогами за контроль над Улдаманом.$B$BТроги сховали топаз в урні, що знаходилася поблизу незвичайних мешканців Улдамана — карликів Альянсу!$B$BНарешті, сам старійшина трогів привласнив собі сапфір.",
},

[2201] = {
    en = "Find the Gems",
    T = "Знайди коштовності",
    D = "Щоденник паладина, мабуть, є єдиним джерелом підказок, які Улдаман може надати щодо місцезнаходження самоцвітів намиста. Якщо записи паладина виявляться точними, то доведеться розібратися з карликами з Тіньової Кузні та трогогами, які змагаються за контроль над місцем розкопок.$B$BОзброївшись цими знаннями, можна серйозно взятися за пошуки самоцвітів. Коли всі самоцвіти будуть зібрані, слід повідомити про це Талваша в Айронфорзі за допомогою «Флакона пророцтва», згідно з його інструкціями.",
    O = "Знайдіть рубін, сапфір і топаз, розкидані по всьому Улдаману. Знайшовши їх, зв’яжіться з Талвашем дель Кісселем дистанційно, скориставшись «Флаконом пророцтва», який він раніше вам дав.$B$BЗ щоденника ви знаєте...$B* Рубін заховано в забаррикадованій зоні Тіньової Кузні.$B* Топаз заховано в урні в одній із зон трогів, поблизу карликів Альянсу.$B$B* Сапфір захопив Грімлок, ватажок трогів.",
    P = "З вод чарівної чаші вирисовується образ Талваша.$B$B«Ого, ти ще живий! Тобі вдалося знайти самоцвіти? Ти справді той рятівник моєї репутації, на якого я сподівалася? Будь ласка, скажи, що ти не витратив заряд на флакончик лише для того, щоб поговорити; ці речі НЕ дешеві, а я й так уже в скрутному фінансовому становищі.",
    C = "Так, це дійсно ті три самоцвіти. Молодець! На жаль, твоя робота ще не зовсім закінчена.$B$BНі, я не намагаюся тебе обдурити, дурнику $C. Йдеться про створення магічних прикрас — прикрас рівня якості «Талваш дель Кіссель»! Тобі знадобиться потужне джерело енергії, щоб надати їм трохи енергії. Ну, у цього намиста вже не залишилося енергії, яку можна було б передати.",
},

[2202] = {
    en = "Uldaman Reagent Run",
    T = "Завдання з збирання реагентів в Улдамані",
    D = "Я чув про нещодавно відкриту рослину під назвою «магентові грибні капелюшки». Вони ростуть купками глибоко в розкопках Улдамана; можливо, вони є й деінде, але наразі це єдине місце, де, наскільки мені відомо, їх можна знайти. Я хочу дослідити їхнє потенційне застосування в алхімії, і саме тут ти мені знадобишся.$B$BЗнайди скупчення магентових грибів і принеси мені десяток грибів. Майте на увазі: якщо їх потримати, скупчення можуть випустити отруйні спори.$B$BЗробіть це для мене, і я приготую для вас партію одного зі своїх знаменитих відновлювальних еліксирів!",
    O = "Принесіть 12 капсул магентового гриба Яркалу Моссмелду в Каргаті.",
    P = "Ви вже дістали ті магентові грибні капелюшки, які мені потрібні для моїх алхімічних дослідів? Немає капелюшків — немає нагороди!",
    C = "Молодець, $N, ти ще раз довів свою цінність! Ці капсули стануть цікавим предметом дослідження, будь певен.$B$BА тепер, як і обіцяв, спробуй один із моїх найпотужніших відновлювальних напоїв із мого особистого запасу...$B$BЯкщо ти досвідчений алхімік, то, можливо, у нас з’явиться ще одна справа, яку варто обговорити. У будь-якому разі, дякую тобі за допомогу!",
},

[2203] = {
    en = "Badlands Reagent Run II",
    T = "«Похід за реагентами в Бедлендс II»",
    D = "Ти дуже мені допоміг, $c. Я б нагородив тебе саме тим рецептом зілля, яке дав тобі раніше... але мені доведеться доручити тобі завдання, яке є досить небезпечним. Вислухай моє прохання.$B$BЦей скринька містить три порожні тауматургічні посудини; вони наділені аурою налаштування, яка висмоктуватиме кров спаленого дракона-охоронця. Використання навіть одного з них на звірі сильно розлютить його, тож будьте обережні. Як тільки ви наповните всі три, принесіть їх мені.$B$BЗробіть це — і рецепт стане вашим.",
    O = "Використовуйте порожні посудини для тауматургії, знайдені на обпалених драконах-охоронцях у Пустках. Коли ви їх наповните, віднесіть їх до Джаркала Моссмелда в Каргаті.",
    P = "Ти скористався судинами, щоб дістати для мене кров обпаленого дракона-охоронця, яка мені потрібна? Так, я знаю, що це небезпечне завдання... але рецепт мого цілющого зілля залежить від твого успіху. Ризик і нагорода, друже мій... ризик і нагорода...",
    C = "Від одного алхіміка до іншого — вітаю тебе. Ось, візьми цей рецепт і закарбуй його у своїй пам’яті. Нехай він принесе тобі той самий успіх і нагороди, які приніс мені протягом багатьох років.",
},

[2204] = {
    en = "Restoring the Necklace",
    T = "Відновлення намиста",
    D = "Тобі знадобиться додати цьому намисту трохи «потужності», і, мабуть, Улдаман — найкраще місце для цього. Гадаю, там бігає чимало конструктів, так? Що ж, знищ найбільшого й найнебезпечнішого конструкта в цьому місці та заберіть його джерело енергії! Я майже впевнений, що зможу вбудувати це джерело в намисто.$B$BБез цього джерела енергії полагодити намисто буде неможливо. Поверніться до мене сюди, в Айронфордж, коли його отримаєте, і ми все для вас полагодимо!",
    O = "Здобудьте джерело енергії у найпотужнішого конструкта, якого зможете знайти в Улдамані, і доставте його Талвашу дель Кісселю в Айронфорджі.",
    P = "Ти навіть не зупинився, щоб привести себе до ладу після того, як покинув Улдаман, чи не так? Ти просто прийшов сюди прямо, не зважаючи на затяжний запах підземелля. Ну що ж, сподіваймося, що цей візит буде лише запашним, а не марним на додачу.$B$BУ тебе є джерело живлення для намиста?",
    C = "Ого! Я справді рада бачити тебе і це джерело енергії цілими й неушкодженими. Мені знадобиться хвилинка, щоб магічним чином з’єднати джерело енергії з намистом, тепер, коли самоцвіти знову повернулися до нього. Але як тільки це буде зроблено, намисто стане твоїм!$B$BТи ж з нетерпінням чекаєш, правда? Усе тілесно тремтить від передчуття? А де ж я поклав той фокус для заклинань...",
},

[2205] = {
    en = "Seek out SI: 7",
    T = "Знайдіть SI: 7",
    D = "Значок? Та ні, це дрібниця, рибко — нічого такого, з чим ти не впорався б. Судячи з твого вигляду, я б сказав, що Матіас, швидше за все, помилково прийме тебе за хлопця $g, який доставляє сир, а не за справжнього розбійника. У будь-якому разі, мені доручили завдання, і я пообіцяв його виконати.$B$BДо речі, передай цю посилку Матіасу, і він, можливо, доручить тобі одне-два невеликих завдання.$B$BБеріться до справи. $B",
    O = "Доставте посилку Керін Сильвіус майстру Матіасу Шоу в казарми Штормграда.",
    P = "Чим можу допомогти, $C?",
    C = "Ти мене знайшов — і, судячи з твого вигляду, я б сказав, що втеча та подальші пошуки, мабуть, стали для тебе великим навантаженням, як фізичним, так і психічним.$B$BХочеш, щоб Рензік показав тобі дорогу до готелю, чи ти готовий трохи попрацювати?",
},

[2206] = {
    en = "Snatch and Grab",
    T = "«Вирви та схопи»",
    D = "Наші агенти на місці повідомляють про іншу активність Дефіасів на південь від Голдшира. Згідно з повідомленнями, Дефіаси захопили Джеродс-Лендінг і зараз використовують це місце для контрабанди великих партій товарів з Редріджа до Вестфолла.$B$BМені потрібно, щоб ти проник у будинок на причалі й дістав для мене той графік відправлень, $N. Ймовірно, ти знайдеш його глибоко в кишенях начальника причалу.$B$B...і $N, якщо тебе викриють, SI:7 заперечить будь-яку обізнаність про твоє існування.",
    O = "Знайдіть начальника причалу Дефіаса та поверніть графік відправлень капітана Матіаса Шоу.$B",
    P = "Твоя тривалість життя скорочується з кожною миттю, яку ти марнуєш, байдикуючи в казармах, $C.",
    C = "Я вражений... Вражений тим, що Керін нарешті знайшла новобранця, який, можливо, має задатки справжнього $C. Візьми цей меч, $N. Настане день, коли тебе знову покличуть служити SI:7. Відточуй свої навички, будь пильним і тримай цей меч гострим.$B$BТи не побачиш, як ми наблизимося, але відчуєш, коли ми дістанемося місця...",
},

[2218] = {
    en = "Road to Salvation",
    T = "Шлях до спасіння",
    D = "Ще одна загублена душа, яка шукає настанови, еге ж? Мабуть, ти хочеш знайти мету — свою мету. Я бачив це тисячі разів: ще один герой, який шукає роботу.$B$BЩо ж, сьогодні твій щасливий день, друже. У Хограла є ліки від твоєї недуги.$B$BОсь що тобі треба зробити: йди цією дорогою до Айронфорджа і прямуй до Печери Загублених. Коли дійдеш туди, знайди гільдію злодіїв і поговори з Хульфданом Чорнобородим. Він вкаже тобі шлях до спасіння.$B",
    O = "Поговоріть з Хульфданом Чорнобородим в Айронфорджі.",
    P = "",
    C = "То ти вважаєш себе справжнім негідником? Призначеним стати одним із небагатьох обраних Чорнобородим — офіцером «Прихованого кола»?$B$BЛише нікчемний шахрай міг би так високо про себе думати.$B$BСаме такого ми й шукаємо! Ласкаво просимо на борт, $N!",
},

[2238] = {
    en = "Simple Subterfugin'",
    T = "«Проста хитрість»",
    D = "Розумієте, король веде відкриту розробку кар’єру в пошуках руди та дорогоцінних каменів. Там більше багатств, ніж будь-який гном міг би побачити за десять життів.$B$B«Приховане коло» має свої цінності, $N. Ми цінуємо коштовності. Ви розумієте?$B$BМи вважаємо, що король мав би поділитися частиною цієї здобичі, але не хочемо, щоб старий «Смердюча Борода» дізнався, що він ділиться — якщо ви розумієте, про що я.$B$BНам потрібно, щоб ти поговорив з Оніном МакХаммаром поблизу Гномерегана й приніс звідти звіт. Цей хитрий карлик сховався серед прокажених. Будь обережним.",
    O = "Знайдіть Оніна МакХаммара біля Гномерегана.",
    P = "",
    C = "Тссс! Тихіше, ти, дурню. Вони нас почують.",
},

[2239] = {
    en = "Onin's Report",
    T = "Звіт Оніна",
    D = "Кар'єр? Ага, я майже щодня бачу, як ці монструозні броньовані парові цистерни проїжджають повз цей пост.$B$BМої контакти на сході повідомляють, що танк вирушає з Айронфорджа, забирає вантаж у кар’єрі Гол’Болар, зупиняється в Хараносі для дозаправки, а потім, з якихось клятих причин, їде довгим об’їздом повз Гномереган, перш ніж дістатися до Айронфорджа, щоб здати вантаж.$B$BУсе це є у звіті, $r. Віднеси його Хульфану, щоб він міг спланувати наступний крок.$B",
    O = "Віднесіть звіт Оніна Хульфану в Айронфорджі.",
    P = "Вам сподобався сморід гном-прокаженого? Я питаю лише тому, що у вас на обличчі така божевільна посмішка.$B$BЯкі новини ви привезли з Оніна?",
    C = "Довгий шлях? Заради моєї власної бороди!$B$BТи впорався добре, $N. Візьми цей кинджал і йди собі. «Коло» знову покличе тебе, коли третій крок буде готовий до реалізації.$B$BЩо за третій крок? Він йде одразу після другого — я всаджу тобі мого чобота в зад.$B$BЦікаво?",
},

[2240] = {
    en = "The Hidden Chamber",
    T = "Прихована кімната",
    D = "А тепер перейдемо до поточного завдання.$B$BЄ таємна кімната — Кімната Хаз’мула, яку потрібно дослідити. Проблема в тому, що вона знаходиться за величезними зачиненими дверима! На щастя, я знаю, як їх відчинити.$B$BЯ все описав у своєму щоденнику, який лежить тут, на столі. Моя група та я наразі застрягли тут... тож ти, $N, мусиш знайти для нас Пам'ятку Хаз'мула!$B$BПрочитай мій щоденник, досліди Пам'ятку, а потім доповідай про це Проспектору Стормпайку в Лізі Дослідників у Айронфорзі.",
    O = "Прочитайте щоденник Белога, дослідіть приховану кімнату, а потім зверніться до золотошукача Стормпайка.",
    P = "Чи є у вас інформація, про яку слід повідомити?",
    C = "Ви бачили Палату Хаз’мула? Неймовірно! Белог був упевнений, що вона існує, але мушу зізнатися, що я мав свої сумніви.$B$BДякую, $N. Якщо пощастить, твоє відкриття спонукає наших лідерів поновити зусилля з відвоювання Улдамана. І якщо він колись знову опиниться під контролем Айронфорджа, то таємниці Палати Хаз'мула стануть нашими!",
},

[2241] = {
    en = "The Apple Falls",
    T = "«Падіння яблука»",
    D = "Кажуть, я «закоханий до нестями», що б це не означало.$B$BЗвісно, я кожну мить, коли не сплю, думаю про Сюрну. Звісно, мій дім повний картин і малюнків Сюрни. Звісно, я часто тижнями не їм, не сплю й не п’ю, сумуючи за коханням, яке могло б у нас бути. Хіба це так погано?$B$BА тепер вона навіть не хоче мене бачити! МЕНЕ! Я намагався надсилати їй повідомлення, але вона навіть не розмовляє з іншими людьми, якщо тільки це не розбійник.$B$BЧи не могли б ви передати їй цю квітку? Не забудьте сказати їй, що це від Джаннока.",
    O = "Віднесіть «Троянду Яннока» Сюрні в Дарнассі.",
    P = "О, хіба це не чудово. Ти приніс квіти на власні похорони.",
    C = "Якби я зберегла кожну квітку, яку мені надсилав той дурень Яннок, у мене були б кошти, щоб відкрити крамницю. У будь-якому разі, схоже, що останній кур’єр від Яннока може виявитися корисним. Хочеш трохи попрацювати, $C?",
},

[2242] = {
    en = "Destiny Calls",
    T = "Поклик долі",
    D = "Ми вважаємо, що існує одна істота, яка, можливо, допоможе нам зрозуміти, що відбувається з лісами Телдрасіля. На жаль, спроби залучити цю істоту до співпраці виявилися катастрофічними.$B$BВона ховається на гілці на околиці Галявини Оракула. Усі, хто досі намагався наблизитися до сатира — чи то силою, чи то дипломатією — зазнали загибелі. Можливо, вихід — у скритності, $N.$B$BЗ’ясуйте, що Сетір Стародавній носить у своїх рюкзаках, і доповістіть мені.$B",
    O = "Знайдіть Стародавнього Сетіра і принесіть Сиурні всі підказки, які вам вдасться знайти.$B",
    P = "Чи є у тебе якісь новини з Стародавнього Сетіра, $N?",
    C = "Це сумна новина, $N. Схоже, хвороба, яка охопила ліси та річки Темного Берега, почала поширюватися й на нашу батьківщину.$B$BТи добре нам служив, але тут ти вже нічого не можеш зробити. Візьми цей меч як нагороду за твою службу Телдрасілу.",
},

[2258] = {
    en = "Badlands Reagent Run",
    T = "Похід за реагентами в Бадлендс",
    D = "$N, якщо ти готовий, мені б знадобилася твоя допомога. Я — досить відомий алхімік, і мені потрібна твоя допомога в пошуках деяких реагентів, які можна знайти в Пустках.$B$BМені потрібні такі предмети, щоб поповнити свої запаси: п’ять шлунків грифа, десять іклів скельного койота та п’ять осколків кам’яного елементаля. Звісно, ти можеш дістати їх у самих звірів; якщо ти не любиш битися, то знайди друзів, які це вміють.$B$BЗдобудь ці предмети для мене, і ти отримаєш за це трохи грошей. Що скажеш?",
    O = "Принесіть 5 шлунків кані, 10 іклів скельного койота та 5 осколків скельного елементаля до Яркала Мосмелда в Каргаті, Пустошах.",
    P = "Ти вже приніс те, що мені потрібно? Ти не отримаєш гроші, якщо не принесеш мені ці реактиви.",
    C = "Ах, молодець! Цього мені, принаймні, на деякий час вистачить. Ось твоя винагорода, як і обіцяв.$B$BЯкщо тобі цікаво, у мене є ще кілька реагентів, які мені знадобилися б. Однак їх можна знайти лише в глибинах розкопок Улдамана. Дістати їх буде нелегко, але я зроблю так, щоб це було варте твоїх зусиль, якщо ти захочеш знову мені допомогти.$B$BМоже, щось більше, ніж кілька блискучих монет, так?",
},

[2259] = {
    en = "Erion Shadewhisper",
    T = "Еріон Шепот Тіні",
    D = "Не хвилюйся, $N, я не відправляю тебе до Сюрни. Еріон потребує твоєї присутності в Енклаві Сенаріону. Поспішай!",
    O = "Зверніться до Еріона Шедевіспера в Дарнассусі.$B",
