[2260] = {
    en = "Erion's Behest",
    T = "Наказ Еріона",
    D = "Звістка про твої подвиги рознеслася далеко й широко, $N. Настільки далеко, що розвідка Штормвінда звернулася саме до тебе.$B$BПодорож буде виснажливою й не позбавленою небезпек, але можливість пройти навчання в SI:7 не варто сприймати легковажно.$B$BНа тебе чекає новий світ, $N. Звернися до Старого міста у Штормвіні та поговори з Рензіком «Шивом» у штаб-квартирі SI:7.$B",
    O = "Відправляйся до міста Штормвінд і проконсультуйся з Рензіком «Шивом».$B",
    P = "",
    C = "Ти відгукнувся на заклик SI:7, $N, і прибув з далеких країв, щоб приєднатися до наших лав, однак тобі ще багато чого треба навчитися.",
},

[2278] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Центральними елементами цієї скарбниці є чотири величезні платинові диски, кожен з яких прикрашений численними символами невідомого походження. При дотику до них у руці відчувається поколювання. Одразу після дотику до дисків з’являється обличчя великого кам’яного вартового.$B$B«Вітаю. Я — хранитель знань. Синтез Земних, здійснений Творцями, було зафіксовано та збережено для цього світу на Дисках Норганнона».$B$BВи відкрили для себе багатий, раніше невідомий світ знань!",
    O = "Поговоріть із «Кам’яним спостерігачем» і дізнайтеся, які стародавні знання він зберігає. Дізнавшись, якими знаннями він володіє, активуйте «Диски Норганнона».",
    P = "Здається, голос кам’яного спостерігача відлунює у вашій найпотаємнішій сутності:$B$B«Спочатку ви повинні виконати попередню умову щодо асиміляції даних «Дисків Норганнона»; щойно ви виконаєте цю вимогу, вам буде дозволено отримати портативну версію збережених даних. Будь ласка, переконайтеся, що ви спочатку повністю вивчили інформацію, що міститься в цьому сховищі».",
    C = "Дотримуючись вказівок кам’яного сторожа, ви знову отримуєте доступ до Дисків Норганнона, оскільки вже дізналися про історію Землян, трогів та гномів. Зсередини дисків лунає слабке, коротке гудіння. Тоді кам'яний спостерігач промовляє:$B$B«Диски вже синтезовано. Знову відкрийте Диски Норганнона, щоб отримати свою особисту копію».",
},

[2279] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Коли ти знову торкаєшся Дисків Норганнона, у руці з’являється поколювання. Однак цього разу зсередини дисків лунає дивний скреготливий звук.$B$BТвій рюкзак раптом стає важчим, ніж був раніше. Усередині ти виявляєш мініатюрну версію дисків!$B$BБез сумніву, такий предмет буде безцінним для тих, хто цікавиться стародавньою історією Азерота. Ліга дослідників в Айронфорзі — саме така група, відома в усьому Альянсі; можливо, вони зможуть знайти йому гідне застосування.",
    O = "Віднесіть мініатюрну версію «Дисків Норганнона» до «Ліги дослідників» в Айронфорзі.",
    P = "Так, чим можу допомогти? Запевняю вас, що зараз я дуже зайнятий. Однак, якщо це має серйозне значення для Ліги дослідників, то я готовий вислухати!",
    C = "Що це у тебе там... ой-ой. Де ти це знайшов?$B$BНі, серйозно?$B$BЗ ким ти розмовляв і про що?$B$BНІ, СЕРЙОЗНО?!$B$BМій дорогий $C, ти, можливо, щойно зробив археологічну знахідку року! Боги, кого я обманюю — знахідка століття! Якщо ці диски є тим, чим я їх вважаю, то це може бути саме той ключ, який ми шукали! Це може раз і назавжди довести справжність зачарованого творіння гномів!",
},

[2280] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Коли ти знову торкаєшся Дисків Норганнона, у руці знову відчувається поколювання. Однак цього разу зсередини дисків доноситься дивний скрегочучий звук.$B$BТвій рюкзак раптом стає важчим, ніж був раніше. Усередині ти виявляєш мініатюрну версію дисків!$B$BБез сумніву, такий предмет став би безцінним для тих, хто цікавиться стародавньою історією Азерота. Мудреці з Громового Уступу — саме такі історики, відомі всій Орді; можливо, вони зможуть знайти йому гідне застосування.",
    O = "Віднесіть мініатюрну версію «Дисків Норганнона» одному з мудреців у Громовому Утвірі.",
    P = "Так, юний друже, я бачу, як ти крокуєш до мого намету — з енергією в кроках… і рішучістю у намірах. Ти звертаєшся до мене за порадою щодо якоїсь справи, що має велике значення для Орди? Можливо, ти бажаєш, щоб тобі відкрили якусь таємницю Всесвіту?",
    C = "А що це тут таке?$B$BВражаюче, юний друже! У цих дисках я відчуваю таємниці, які земля ретельно приховувала протягом багатьох років. Ти вчинив дуже мудро, принісши їх сюди до мене.",
},

[2281] = {
    en = "Redridge Rendezvous",
    T = "«Редрідж Рандеву»",
    D = "Відправляти тебе зараз у поле — це було б самогубством. Рензіку не потрібний ще один мертвий розбійник на совісті. Але не хвилюйся, $N — Рензік введе тебе в курс справи.$B$BПрямуйте до Червоних гір і поговоріть із співробітником SI:7 на ім’я Люціус. Ви знайдете його біля доків Лейкширу в компанії інших підозрілих нероб.",
    O = "Відправляйтеся до Лейкширу в Горах Редрідж і поговоріть з Люціусом.$B",
    P = "",
    C = "Ага, то у тебе пальці трохи товсті, так? Не хвилюйся, $N, я перетворив на досвідчених розбійників навіть гірших за тебе злодіїв.",
},

[2282] = {
    en = "Alther's Mill",
    T = "Млин Альтера",
    D = "Ми вже роками готуємо тут злодіїв! Адже не кожен шахрай народжується з такою грацією та витонченістю, як старий Люціус.$B$BТрохи вище від дороги ти знайдеш млин Альтера. Там у мене є скриня, а в ній — щось важливе. Знайди її для мене! Принеси цей жетон, і ти отримаєш свій «Сертифікат злодія»!",
    O = "Відкрийте скриньку Люціуса, знайдіть «Знак крадіжки» та поверніть його Люціусу в Лейкширі.",
    P = "Чи я забув згадати про орків?$B$BКажуть, вони нишпорять десь біля млина.",
    C = "Ти його зламав, так? Молодець, $N.$B$BЯкщо ти зараз загинеш, ми зможемо спати спокійно, знаючи, що це сталося через твою власну дурість, а не через недосвідченість.",
},

[2283] = {
    en = "Necklace Recovery",
    T = "Відновлення намиста",
    D = "У нас є для тебе завдання — якщо, звичайно, ти наважишся його виконати!$B$BГлибоко в Пустках розташоване місце розкопок Улдаман. Ми чули історію про якогось дурного паладина, який нещодавно там загинув. Нас це цікавить лише тому, що на ньому був дуже цінний намисто. Кажуть, що в ньому є три великі дорогоцінні камені: рубін, сапфір і топаз.$B$BМи хочемо цей кулон і готові заплатити за нього ВЕЛИЧЕЗНУ СРІБНУ СУМУ. Можливо, він пошкоджений, але це не має значення — ми усунемо будь-які подряпини на ньому.",
    O = "Знайдіть цінне намисто на місці розкопок в Улдамані та принесіть його Драну Дрофферсу в Оргримарі. Намисто може бути пошкоджене.",
    P = "Ну, то в тебе є той кулон? Якщо його немає, то від нас ти ні копійки не отримаєш!",
    C = "Мммм, знахідка! Я навіть звідси відчуваю запах цього намиста. А тепер давай подивимося на цю красу...$B$BГей, що ти тут намагаєшся зробити? У цьому намисті бракує дорогоцінних каменів! Думаєш, ми цього не помітимо? Навіть Мальтон бачить, що самоцвітів немає.$B$BНу, може, ти їх і не вкрав... але без цих самоцвітів це намисто нічого не варте! Твоя робота тут ще далеко не закінчена!",
},

[2284] = {
    en = "Necklace Recovery, Take 2",
    T = "Пошук намиста, частина 2",
    D = "Так само, як Мальтон — повний дурень, так і ті самоцвіти досі десь в Улдамані. Тобі доведеться повернутися туди й пошукати їх.$B$BЯк я вже казав, якщо інформація, яку ми маємо, правильна, то до намиста належать рубін, сапфір і топаз. Знайдіть їх і вставте в намисто.$B$BА де саме знаходяться ці самоцвіти — хто знає? Можливо, вам пощастить і ви знайдете труп паладина. Якщо його ще не обчистили дочиста, то, можливо, самоцвіти все ще при ньому.",
    O = "Знайдіть підказку щодо місця знаходження дорогоцінних каменів у глибинах Улдамана.",
    P = "",
    C = "Схоже, ти знайшов останки паладина, про якого раніше згадував Дран. Оглядаючи останки, ти виявляєш те, що, судячи з усього, є його щоденником. Книга в поганому стані: більшу частину тексту заплямувала засохла кров. Однак те, що ви можете прочитати, — це нісенітниця; наскільки вам відомо, це написано рідною мовою людей.$B$BЩоб витягти з неї хоч якусь корисну інформацію, вам знадобиться переклад цієї книги.",
},

[2298] = {
    en = "Kingly Shakedown",
    T = "Королівська рекетирська операція",
    D = "Отож, ми саме збиралися приступити до планування третьої фази, як раптом сюди ввалилося кілька тупоголових з Магні, розказуючи про якесь пограбування та арешт членів «Прихованого кола».$B$BНу, ніхто ж не посадить старого Чорнобородого за ґрати! Суперечка розгорілася, і якось твоє ім’я випадково пролунало!$B$BМоя порада? Сідай на перший «Грифон», що вилітає з Айронфорджа, і лети до Штормвінда. Дійди до Старого міста, а коли дійдеш, поговори з моїм старим другом на ім’я Рензік «Шив».",
    O = "Відправляйся до Штормвінда й знайди Рензіка «Шива».",
    P = "",
    C = "Завжди приємно мати у своїх лавах одного з розбійників Хульфдана!",
},

[2299] = {
    en = "To Hulfdan!",
    T = "За Хульфдана!",
    D = "Де ти був, $N? Хульфдан тебе всюди шукав. Ми думали, що король, можливо, посадив тебе в кайдани.$B$BЯкнайшвидше вирушай до Айронфорджа й поговори з Хульфданом!",
    O = "Відправляйтеся до Айронфорджа і поговоріть з Хульфданом Чорнобородим.",
    P = "",
    C = "Говори тихіше, $N, охоронці можуть тебе почути.",
},

[2300] = {
    en = "SI:7",
    T = "SI:7",
    D = "Рензік тебе шукав, рибко.$B$BНа твоєму місці я б не змушував заступника Матіаса чекати.$B",
    O = "Відправляйся до Штормграда та знайди Рензіка «Шива».$B",
    P = "",
    C = "Ти готовий взятися за роботу чи тобі треба трохи подрімати, перш ніж ми почнемо?",
},

[2318] = {
    en = "Translating the Journal",
    T = "Переклад журналу",
    D = "Опинившись у своєрідному глухому куті, ви розумієте, що вам знадобиться переклад цієї книги на мову, яку ви розумієте. У світі, безперечно, є чимало людей, які могли б це зробити; однак найближче місце, де, можливо, знайдеться хтось, хто зможе це зробити, — це аванпост Каргат у Пустках. Можливо, це гарне місце для початку.$B",
    O = "Знайдіть когось, хто зможе перекласти щоденник паладина. Найближче місце, де можна знайти таку людину, — це Каргат у Пустках.",
    P = "",
    C = "Могутній $C, я знаю, що ти робиш тут, у Пустках. Я знаю, що ти прагнеш отримати мій дар мов. Ти шукаєш деталі того намиста, яке знайшов в Ульдамані.$B$BЗдивований? Не варто — це моя робота, знати такі речі. Натомість давай обговоримо, що ти зробиш за переклад щоденника. Повір мені — я єдиний, хто зможе його перекласти.$B$BА ще краще — дозволь мені зробити тобі пропозицію, кращу за ту, що запропонував Дран Дрофферс, і ти все одно зможеш укласти угоду з ними. Тепер зацікавився, так?",
},

[2338] = {
    en = "Translating the Journal",
    T = "Переклад журналу",
    D = "«Droffers and Son Salvage» не настільки кмітливі, щоб відновити магію в намисті, але я — так. Все, чого я хочу, — це дослідити намисто, щоб навчитися виготовляти такі самостійно. Для цього мені знадобиться твоє намисто. Дай мені його на деякий час, і в обмін на час, який я витрачу на його вивчення, я перекладу для тебе щоденник. Поки ти шукатимеш дорогоцінні камені, у мене буде достатньо часу, щоб дізнатися все необхідне.$B$BЦе проста угода, і ніхто про це не дізнається. Що скажеш?",
    O = "Дозвольте Яркалу позичити намисто. Натомість він перекладе для вас щоденник.",
    P = "Ти вже обдумав це, так? Ти поступиш розумно, $C, якщо погодишся на цю угоду — ми з тобою отримаємо те, чого хочемо, а «Дрофферс і Син Сальведж» будуть думати, що отримують те, чого хочуть.",
    C = "Хорошу угоду впізнаєш, коли її бачиш — я знав, що можу на тебе розраховувати.$B$BЗачекай хвилинку, я промовлю заклинання, щоб швидко перекласти людську мову на мову, яку ти зрозумієш. Я — троль, який дотримується свого слова; запитайте будь-кого в Орді про Яркала Мосмелда. А тепер давайте почнемо...",
},

[2339] = {
    en = "Find the Gems and Power Source",
    T = "Знайдіть самоцвіти та джерело енергії",
    D = "Ось цей щоденник, перекладений для вас, щоб ви могли прочитати його самостійно. Суть полягає в тому, що гноми сховали рубін, троги — топаз, а сапфір у трога на ім’я Грімлок.$B$BПослухайте — вам знадобиться джерело енергії, щоб намисто знову запрацювало. Дран Дрофферс про це не знає. Щоб його знайти, я б зробив так: спустився б якнайглибше в Улдаман і вбив найпотужнішого з усіх конструктів, які там є. Без сумніву, саме він його має.$B$BКоли зберете все необхідне, повертайтеся сюди!",
    O = "Знайдіть в Улдамані всі три самоцвіти та джерело енергії для намиста, а потім віднесіть їх до Джаркала Моссмелда в Каргаті. Джакал вважає, що джерело енергії можна знайти на найпотужнішому конструкті, який є в Улдамані.$B$BЗ щоденника ви знаєте...$B* Рубін заховано в забарикадованій зоні Тіньової Кузні.$B* Топаз сховано в урні в одній із зон трогів, поблизу карликів Альянсу.$B* Сапфір захопив Грімлок, ватажок трогів.",
    P = "Якщо у вас немає самоцвітів та джерела енергії, здатного спрямувати магічну силу назад у намисто, вам доведеться знову вирушити в глибини Улдаману.$B$BТи повернеш самоцвіти, щоб передати їх найманцям в Оргримарі; джерело енергії залишу собі, адже саме воно і забезпечить роботу намиста...",
    C = "Дуже добре, $C. Тепер плоди наших зусиль з перенаправлення принесуть нам чималу винагороду. Я завершив роботу над самим намистом і впевнений, що зможу послідовно відтворювати процес його виготовлення.$B$BАле спершу я використаю спеціально підготовлене заклинання, щоб швидко проаналізувати ці самоцвіти, перш ніж ти віднесеш їх разом із намистом до Оргримара. Це займе лише мить.",
},

[2340] = {
    en = "Deliver the Gems",
    T = "Доставте дорогоцінні камені",
    D = "Підійде будь-яка оправа для намиста та будь-який самоцвіт, головне, щоб вони були з одного матеріалу. Саме це джерело енергії, однак, і поверне магію намисту... Сподіваюся.$B$BЯ з радістю надам самоцвіти, необхідні для твоєї версії намиста, за умови, що джерело енергії справді працює.$B$BРушай до Оргриммара й виконай свою частину угоди з компанією «Дрофферс і Син — утилізація». Просто нікому не розказуйте про нашу угоду, і коли ви повернетеся, я, можливо, підготую для вас чудовий сюрприз.",
    O = "Передайте намисто та зібрані самоцвіти Драну Дрофферсу в Оргримарі.",
    P = "О, дивись-но, хто це! Бачу, не поспішав сюди. Сподіваймося, це не буде марною тратою мого часу! Ти не отримаєш грошей, якщо не принесеш усе, про що я просив. І повір мені — ми все перевіримо двічі, а то й тричі!",
    C = "Ага, все тут. Скажи, а можна нам і сумку залишити? Ні? Дякую, дуже вдячні! Ха!$B$BЦей намисто стане нашою найкращою знахідкою! Але не переймайся надто — я впевнений, що воно тобі все одно не підійде. Ха-ха, знову!$B$BДомовленість є домовленістю, тож ось твоя винагорода за врятовані речі. Наразі наші справи тут завершені; заглянь пізніше, щоб дізнатися, чи є у нас ще робота. А до того часу — забирайся геть!",
},

[2341] = {
    en = "Necklace Recovery, Take 3",
    T = "Пошук намиста, спроба № 3",
    D = "Поки Дран і Мальтон Дроффери починають сваритися через свою нову знахідку, половина угоди вже виконана. Тепер потрібно вирушити до Бедлендів, щоб довести справу до кінця, адже Яркал Моссмельд у Каргаті, можливо, приготував для вас там особливу нагороду.",
    O = "Завітайте до Яркала Мосмельда в Каргаті, щоб дізнатися, чи йому це вдалося.",
    P = "",
    C = "Джерело енергії, яке ти мені дав, перевершило всі мої очікування. Мені вдалося виготовити намиста і для тебе, і для себе, а ще залишилося достатньо, щоб зробити щонайменше три додаткові. За них можна буде отримати чималу суму, і компанія «Дрофферс і Син Салведж» навіть не здогадається.$B$BОсь, друже мій. Я дякую тобі за чудову роботу... і дарую тобі щось зовсім особливе за твої клопоти.",
},

[2342] = {
    en = "Reclaimed Treasures",
    T = "Відновлені скарби",
    D = "Підмітати вольєри для кажанів цією мітлою — це не гідно Гаррета! Я заробив трохи грошей на цій проклятій роботі і готовий витратити їх на тебе, щоб поліпшити своє становище.$B$BРодинна зброя Гарретів зберігається у нашому скрині в Південній загальній залі Улдамана — з тих часів, коли ми, Гаррети, працювали там копачами. Без неї я назавжди застрягну тут — у буквальному сенсі — підмітаючи за цими пекельними кажанами.$B$BЗнайди скарб моєї родини та принеси його мені! Допоможи мені повернути те, що мені належить за правом народження!",
    O = "Візьміть сімейну реліквію Патріка Гарретта з родинного скрині в Південному загальному залі Улдамана та принесіть її йому в Андерсіті.",
    P = "Прибирання ніколи не закінчується... Ці кажани безперестанку глузують з мене та моєї мітли. Будь ласка, скажи, що ти повернув скарб моєї родини! Я запропонувала тобі своє срібло — хіба цього недостатньо?!",
    C = "Нарешті — мітла, гідна Гаррета. Ти, чорт забирай, варта кожного срібного, який я на тебе витратив, кажу я!$B$BЧи чуєте мене, мерзенні кажани? Тепер я володію улюбленою зброєю родини Гарретів! Тремтіть, кажани, тремтіть!!",
},

[2358] = {
    en = "Horns of Nez'ra",
    T = "Роги Нез'ри",
    D = "Багато років тому «Роги Нез'ри» були викрадені з маєтку Рейвенхолдт. Я шукав їх по всьому світу, перетинаючи континенти й океани, але зрештою виявив, що ці нікчемні тварюки весь цей час тримали їх у себе.$B$BВбивай кожного орка з племені Чорної Скелі, якого зустрінеш, доки не знайдеш Роги Нез'ри. Якщо тобі вдасться їх знайти, знайди мене в Лейкширі.$B$BЗроби це для мене, і твоє ім'я стане відомим у Равенхолдті, $N.",
    O = "Поверніть Роги Нез'ри «Тіні Арантіра» в Лейкширі.",
    P = "У тебе є роги принца демонів?",
    C = "Відмовити Равенхолдту в артефакті — це все одно, що заперечити власне існування. Молодець, розбійнику. Ти ще можеш приєднатися до ряду вбивць Равенхолдта.$B$BЩе в юності, мандруючи Темним Берегом, я відкрив для себе чай, що відновлює сили під час бою. Він добре служив мені протягом багатьох років, і тепер я передаю тобі смак чаю з чортополоху. Випий його, коли втомишся, $N, і знову бийся з новою силою!",
},

[2359] = {
    en = "Klaven's Tower",
    T = "Вежа Клавена",
    D = "Я вже кілька тижнів стежу за цією вежею, $N. Нещодавно з Сутінкового лісу прибула велика партія вантажу, а разом із нею — ті охоронці.$B$BЩо це за істоти? Я знаю не більше за тебе. Одне можу сказати напевно — вони не люди.$B$BУ будь-якому разі, у вантажі був скриня — і я припускаю, що саме її охороняють ці потвори. Зомбі зі шипами тримає ключ, який нам знадобиться.$B$BЗнайди цей ключ, проникни у вежу й з’ясуй, що саме знаходиться в тому скрині. Поверни свої знахідки Матіасу.",
    O = "Викрадіть ключ від Вежі Дефіас, проникніть у Вежу Дефіас і дізнайтеся, що міститься у скрині з Сутінкового лісу. Поверніться з усією знайденою інформацією до Матіаса Шоу у Штормграді. Прочитайте щоденник Кернена, щоб дізнатися більше про вежу.$B",
    P = "Є якісь новини від агента Кернена?",
    C = "Це могло б пояснити появу дронів Дефіаса, яких ви з Керненом бачили біля вежі, $N. Це також могло б пояснити зв’язок «Компанії Венчур» з Дефіасом та дивні вантажі, що вивозяться з Сутінкового лісу.$B$BЗгідно з цією книгою, тролі Занзіл у Странглторні відкрили спосіб воскрешати мертвих за допомогою зілля... а точніше — отрути.$B$BТи не будеш корисним для SI:7 без ґрунтовних знань про отрути, $N — особливо коли рецепт створення нежиті у нас під рукою.",
},

[2360] = {
    en = "Mathias and the Defias",
    T = "Матіас і Дефіаси",
    D = "Саме вчасно, $N. Розвідка SI:7 повідомляє про надзвичайно активну діяльність Дефіасів у Вестфолі.$B$BСхоже, що «Дефіас» захопили покинуту сторожову вежу Альянсу на південний схід від Сентинел-Гілл і використовують її як оперативну базу для контрабанди товарів з маршруту постачання Редрідж.$B$BВідправляйтеся до Вестфолла та зв’яжіться з агентом Кернен для отримання інструкцій. Ви знайдете її, сховану поблизу вежі.$B$B...і $N, якщо вас викриють, SI:7 заперечить будь-яку обізнаність про ваше існування.",
    O = "Відправляйтеся до Вестфолла та знайдіть агента Кернена, щоб пройти підбиття підсумків.",
    P = "",
    C = "Матіас нарешті відправив ще одного агента, щоб підстрахувати мене, так? Ну, сподіваюся, він готовий почути кілька поганих новин.",
},

[2361] = {
    en = "Restoring the Necklace",
    T = "Відновлення намиста",
    D = "",
    O = "",
    P = "",
    C = "Я з радістю дарую тобі це намисто, могутній $C. Ти зробив для мене неоціненну послугу, і за це я тобі дякую. Носи його з гордістю і не забудь голосно та неодноразово розповідати, хто його для тебе виготовив!$B$BА ще, якщо ти зможеш додати, що воно насправді не прокляте, це було б чудово.",
},

[2378] = {
    en = "Find the Shattered Hand",
    T = "Знайдіть «Розбиту руку»",
    D = "Ти добре служив «Смертошукачам», $N, але, можливо, настав час тобі вийти за межі їхнього табору. Хоча ти й проявив здібності до скритності та обману, тобі все ще потрібно багато тренуватися.$B$BУ «Смертошукачів» є союзники серед «Розбитої Руки». Знайди тих, хто готовий нам допомогти — знайди Шентула в Оргримарі.$B",
    O = "Відправляйтеся до Оргримара і поговоріть із Шентулом у «Тріщині Тіні».$B",
    P = "",
    C = "То ти й є той, кого наші могутні союзники послали до Шентула? Як же це нудно...",
},

[2379] = {
    en = "Zando'zan",
    T = "Зандозан",
    D = "Однієї лише вашої рішучості недостатньо, щоб подолати перешкоди, що стоять перед нами.$B$BПоговоріть із Зандозаном, щоб розпочати навчання на агента «Розбитої Руки».$B$BЛише опанувавши мистецтво скритності та крадіжки, ти зможеш зробити наступний крок назустріч своїй долі.$B",
    O = "Поговоріть із Зандозаном у «Тріщині тіні».",
    P = "",
    C = "Можливо, Зандо'зан помилявся. Зандо'зан просить вибачення.",
},

[2380] = {
    en = "To Orgrimmar!",
    T = "До Оргримара!",
    D = "Ти, звичайно, не майстер скритності та обману, але все це може змінитися — і зміниться. Ти, очевидно, вразив керівництво своїми скромними навичками, оскільки великий Шентул особисто попросив тебе приїхати.$B$BРушай дорогою на північ від цього місця до Оргримара і поговори з Шентулом у «Тріщині Тіні».$B",
    O = "Поговоріть із Шентулом у «Тріщині тіні» в Оргримарі.",
    P = "",
    C = "Важливо, щоб «Розбита Рука» залишалася пильною перед обличчям змін, які Тралл прагне внести в Орду. Однієї лише чисельності нам не вистачить, щоб подолати його владу — ми маємо досконало оволодіти мистецтвом скритності та обману.",
},

[2381] = {
    en = "Plundering the Plunderers",
    T = "Грабуючи грабіжників",
    D = "Я не хочу тебе лякати, $N, але останні п’ять злодіїв, яких я відправив викрасти скарб Південного моря, повернулися до мене у шматках.$B$BНа південь уздовж узбережжя ти знайдеш «Тіде Рейзор» — корабель піратів Південного моря. У трюмі корабля захована нагорода — скарб Південного моря. На другому рівні цього корабля розташована піратська лігва — місце, де вони навчають усіх своїх злодіїв.$B$BПідніміться на борт цього корабля, вкрадіть скарб і принесіть його мені. Якщо тобі потрібно потренуватися у крадіжках, скористайся піратським лігвом, але будь обережним!$B",
    O = "Поверніть «Скарб Саутсі» Врениксу Нещасному в Ратчеті. Не забудьте забрати E.C.A.C. та «Злодійські інструменти» з «Гізмотронічного апарату» Вреникса. Ці два предмети знадобляться вам для виконання місії.$B$BЯкщо на вас нападуть якісь надзвичайно ворожі папуги, використовуйте свій E.C.A.C.!$B$B",
    P = "Ну, принаймні у тебе ще всі частини тіла на місці. Ти знайшов скарб?$B$B",
    C = "Неймовірно! Неймовірне! Просто дивовижно! У тебе талант, Вейр. Або це, або ти — найщасливіша людина на світі!$B$BОсь твоя частка від угоди. Я впевнений, що ти зможеш краще використати цей матеріал, ніж я.$B$B",
},

[2382] = {
    en = "Wrenix of Ratchet",
    T = "Вренікс із Ратчета",
    D = "Зандо'зан це бачив! Так, той день наближається! Смерть Тралла... кинджал у його спині, отрута, що просочується в кожну його вену... Зандо'зан сказав занадто багато.$B$B$N! У Зандо'зана є завдання для $N! $N має вирушити до Ратчета, що на схід від Перехрестя, і поговорити з Реніксом Нещасним. Вперед!$B",
    O = "Відправляйся до Ратчета і поговори з Реніксом Нещасним.",
    P = "",
    C = "Ще один? Останні п’ять, які мені надіслав той божевільний троль, стали їжею для акул. Сподіваймося, що тобі пощастить трохи більше, га?$B$B",
},

[2383] = {
    en = "Simple Parchment",
    T = "Простий пергамент",
    D = "Ах, поки тебе не було, тобі прийшов пергамент, $N.$B$BПрочитай його, коли буде час. Якщо я не помиляюся, його надіслав інструктор-воїн Френг. Він хотів би з тобою поговорити, коли ти будеш готовий. Ти знайдеш його біля «Лігва», він ховається в тіні.",
    O = "Прочитайте «Простий пергамент» і поговоріть із Франгом у Долині Випробувань.",
    P = "Що це у тебе там? Пергамент? Сподіваюся, ти ж не вчений...",
    C = "А, це ж мій пергамент. Я чув, що ти збираєшся приїхати до Долини, $N. Радий, що ти дістався сюди — сподіваймося, що ти витримаєш випробування, які чекають на тебе. Як я вже казав, коли ти наберешся сили, приходь до мене — я зроблю все, що зможу, щоб навчити тебе шляхам $C.$B$BУдачі тобі, $N, і повертайся до мене, коли відчуєш, що готовий.",
},

[2398] = {
    en = "The Lost Dwarves",
    T = "Загублені гноми",
    D = "Місце розкопок в Улдамані не завжди було заполонене ворогами. Ми, гноми з Айронфорджа, колись контролювали цю територію, але… це було до того, як з’явилися троги. Вони навалилися так швидко й у такій кількості, що навіть сила гномів не змогла їх зупинити!$B$BНасправді їхній напад був настільки раптовим, що я побоююся: частина наших людей могла опинитися в пастці за лінією фронту.$B$BМій друг Белог очолював невеликий загін гномів, який заглибився в надра родовища незадовго до появи трогів. Якщо він і його загін вижили, то я хочу, щоб ти їх знайшов.",
    O = "Знайдіть Баелога в Улдамані.",
    P = "",
    C = "Нарешті ти з’явився! Мені вже загрожувала поразка у парі з Олафом!$B$BВін побився об заклад, що його борода відросте до колін, перш ніж він побачить ще одну живу людину $R. Ось ти й тут, і, як бачиш, бороді Олафа ще кілька дюймів до коліна.$B$BДякую, $N. Я поділюся з тобою виграшем.",
},

[2399] = {
    en = "The Sprouted Fronds",
    T = "Пророслі листки",
    D = "",
    O = "",
    P = "",
    C = "Листя, яке Деналан посадив у своєму саду, проросло й підросло. Воно тремтить, чекаючи, коли його зірвуть...",
},

[2418] = {
    en = "Power Stones",
    T = "Камені сили",
    D = "Нещодавно у мене трапився інцидент із карликами з «Тіньової кузні». Вони привели мене до фортеці Ангор, щоб я дослідив два види дивних каменів з Улдаману. Я виявив, що ці камені, за умови правильного поводження, є надійними та стабільними джерелами енергії. Дивовижно, що можна знайти на тому старому місці розкопок!$B$BУ будь-якому разі, після того як я розповів їм секрет каменів, вони вигнали мене з фортеці Ангор і почали копати в Улдамані, щоб знайти ще.$B$BЯ хочу ці камені собі! Принесіть мені обидва види, і я добре вам заплачу!",
    O = "Принесіть 8 каменів сили «Дентріум» та 8 каменів сили «Ан'Аллеум» Рігглфузу в Пустці.",
    P = "У тебе є камені сили, $N? У мене є робот-гризун, якому потрібне джерело живлення...",
    C = "Це чудово, ти їх знайшов! Дуже дякую, $N. Ти — найнадійніший $r, якого я коли-небудь зустрічав!$B$BНе можу дочекатися, щоб випробувати їх на пристроях, над якими я зараз працюю. Готовий побитися об заклад, що за відповідних умов пристрої, що живляться цими каменями, працюватимуть, працюватимуть і працюватимуть...",
},

[2438] = {
    en = "The Emerald Dreamcatcher",
    T = "Смарагдовий ловчик снів",
    D = "Колись я отримав смарагдовий ловець снів від Гаероласа Талветена, наглядача друїдів у «Лігві курганів Бан’етіл». Цей потужний амулет здатний витягувати енергію зі «Смарагдового Сну», даруючи удачу тим, хто його носить.$B$BНа жаль, мені не вдалося дістати його зі своєї комоди в селі Старбріз... Хоча Старбріз колись був спокійним місцем, тепер він піддався розтлінням з боку фурболгів, які там мешкають.$B$BМожливо, ти зможеш повернути мій ловець снів, $c?",
    O = "Принесіть смарагдовий ловчик снів Таллонкаю Свіфтруту в Доланаар.",
    P = "Будь ласка, покваптеся. Залишається тільки сподіватися, що мій смарагдовий ловчик снів не постраждав від рук фурболга.$B$BВи вже його знайшли, $N?",
    C = "Мій смарагдовий ловчик снів має для мене велике значення. Це подарунок, який дарують лише небагатьом. Дякую, що повернув його, $N.",
},

[2439] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Цей предмет — неймовірна знахідка. Стародавні Титани, або «Творці», як їх називають на цих дисках, є ланкою, що зв’язує нас із нашим чарівним творінням — якщо вірити переказам, що тут збережені! Нам потрібно присвятити цьому якомога більше часу на дослідження.$B$BА тобі, героїчний $c, віднеси цей ваучер Дініті Стоунмантл у сховище. Він надасть тобі те, що, на мою думку, є гідною винагородою за таку надзвичайну знахідку!$B$BПовертайся до мене, коли будеш готовий; у Лізі Дослідників ще багато чого потрібно зробити!",
    O = "Віднесіть свій ваучер на винагороду Дініті Стоунмантл у Скарбниці Айронфорджа.",
    P = "Ласкаво просимо до Скарбниці Айронфорджа, $N. Чим можу вам допомогти сьогодні?",
    C = "Так, це ваучер від Ліги дослідників... і, дозвольте зауважити, досить цінний.$B$BЛіга дослідників наділила мене повноваженнями запропонувати вам на вибір винагороду безпосередньо з їхнього сховища. Ви отримаєте цей предмет і зможете вибрати в якості нагороди п’ять елітних лікувальних зілля або п’ять сильних зілля мани.",
},

[2440] = {
    en = "The Platinum Discs",
    T = "Платинові диски",
    D = "Я зосереджу свої зусилля на цих дисках; з часом вони розкриють мені свої справжні механізми дії.$B$BЩо стосується тебе $N, то я зараз винагороджу тебе за старанність, з якою ти звернув мою увагу на це. Віднеси цей ваучер Бені Вінтерхуф, інструкторці з алхімії в Громовому Утворі. Вона дасть тобі особливий предмет, який, як я вважаю, тобі сподобається, а також надасть на вибір зілля з мого особистого запасу.$B$BПовертайся до мене якнайшвидше, бо я відчуваю, що нас чекає ще багато роботи, пов’язаної з цією знахідкою.",
    O = "Віднесіть ваучер на винагороду Бені Вінтерхуф у Грім-Блаф.",
    P = "Вітаю, $C! Ти прийшов сюди, щоб навчитися алхімії, чи, можливо, з іншої причини?",
    C = "Ну що ж, $N, ти, мабуть, дуже порадував Мудреця-Шукача Істини, якщо він подарував тобі цей предмет. Ти також отримаєш подарунок із його запасів зілля; як нагороду ти можеш вибрати 5 зілля вищого рівня для відновлення здоров’я або 5 зілля вищого рівня для відновлення мани.",
},

[2458] = {
    en = "Deep Cover",
    T = "«Глибоке прикриття»",
    D = "Компанія «Venture»... Можливо, ви про них чули?$B$BПротягом року ми працювали над тим, щоб заслати агента глибоко в їхні ряди. Завдяки наполегливій праці та ретельному плануванню нам це вдалося.$B$BНещодавно ми отримали інформацію, що «Venture Co.» планує щось грандіозне. Прямуйте на північ від Болота Сладжу до вежі «Venture Co.» і зв’яжіться з нашим таємним агентом, Таскмастером Фізулом.$B$BКоли знайдете вежу, скористайтеся цим сигнальним пістолетом, а потім підійдіть до Фізула й покажіть йому салют «Розбитої Руки».$B",
    O = "Відправляйтеся до вежі «Venture Co.», що на північ від Болота Сладжу, і зв’яжіться з таємним агентом «Розбитої Руки» — Наглядачем Фіззулом.$B$BКоли вежа з’явиться в полі зору, скористайтеся сигнальним пістолетом, щоб повідомити Наглядача Фіззула про своє прибуття. Вистріліть ДВІ сигнальні ракети, а потім підійдіть до Таскмастера Фізула й виконайте «Салют Розбитої Руки».$B$BЦі дії необхідно виконувати в правильному порядку, оскільки Фізул атакує й знищить будь-яку особу, яку він не впізнає.",
    P = "",
    C = "Приємно бачити в цих краях ще одного агента «Розбитої Руки», хоча сигнальна ракета, мабуть, була трохи зайвою!$B$BНаступного разу, коли тобі знадобиться зі мною поговорити, двічі подуй у цей свисток — і я зрозумію, що ти мій союзник.",
},

[2459] = {
    en = "Ferocitas the Dream Eater",
    T = "Феросітас — Пожирач Снів",
    D = "Смарагд... Він зник! Мій ловчик снів пошкоджено!$B$BНа північ від Старбріз знаходиться група містиків з Гнарпайну. Я чула, що їхній ватажок, Феросітас, Пожирач Снів, носить намисто, яке вночі світиться зеленим світлом. Тепер, побачивши свій ловчик снів, я впевнена, що саме він вкрав мій смарагд... Він ніколи не зрозуміє, що його сила для нього марна.$B$BЗнайди цей зниклий самоцвіт, $N. І, поки ти там, розправся також із деякими зіпсованими містиками.",
    O = "Таллонкай Свіфтрут у Доланаарі просить вас вбити 7 містиків Гнарпайн і знайти зниклий самоцвіт.",
    P = "Феросітас і містики Гнарпайн повинні повернути те, що належить мені. Будь ласка, знайдіть смарагд, щоб я міг полагодити свій смарагдовий ловець снів.",
    C = "Тепер я можу полагодити свій ловчик снів. Дякую, $N.",
},

[2460] = {
    en = "The Shattered Salute",
    T = "«Розбитий салют»",
    D = "Як розбійник з угруповання «Розбита Рука», тобі обов’язково слід опанувати «Привіт Розбитої Руки». Це єдиний спосіб безпомилково впізнати іншого члена угруповання.$B$BДивись, вчись, повторюй.",
    O = "Виконайте «Розбитий салют» на Шентулі.",
    P = "Тренуйтеся!",
    C = "Молодець, $N. Тепер ти готовий продовжувати.",
},

[2478] = {
    en = "Mission: Possible But Not Probable",
    T = "Місія: можлива, але малоймовірна",
    D = "Вам потрібно викрасти ключ від вежі у бригадира Сіліксіза, $N. Коли ключ опиниться у вас, не віддавайте його — він може мені знадобитися пізніше.$B$BПам’ятайте: отрута ослабила все, що є в цій вежі. Використовуйте свої здібності, щоб посіяти хаос і руйнування серед її мешканців. Вбийте їх усіх — не проявляйте жалю!$B$BКоли все всередині перетвориться на криваву купу, зламайте скриньку Галлівікса та викрадіть звідти запас суміші Занзіла. Віднесіть і голову Галлівікса, і суміш до Шентула в Оргримарі.",
    O = "Викрадіть ключ від вежі Сіліксіза у бригадира Сіліксіза, а потім вбийте двох мутованих дронів «Venture Co.», двох патрульних «Venture Co.» та двох дозорців «Venture Co.».$B$BВбийте головного бригадира Галлівікса та візьміть його голову, а потім відімкніть сейф Галлівікса та викрадіть схованку зі зміненою сумішшю Занзіла. Віднесіть схованку та голову Галлівікса до Шентула в Оргримарі для отримання подальших вказівок.$B",
    P = "Що ти можеш повідомити, $N?",
    C = "Бідний Фізул, він був хорошим агентом — одним із наших найкращих. На жаль, це ціна, яку ми платимо, $N. Робота польового агента «Розбитої Руки» — справа небезпечна.$B$BТи добре виконав свій обов’язок, $C. Було б шкода, якби ти не дожив до того, щоб знову служити нам.",
},

[2479] = {
    en = "Hinott's Assistance",
    T = "Допомога від Хінотта",
    D = "Віднесіть зразок суміші Сержу Хінотту в Таррен-Мілл.$B$BЯкщо хтось і може вас вилікувати, то це Серж. Проживіть достатньо довго, і Серж навчить вас, як створювати та застосовувати отрути.",
    O = "Відправляйтеся до Таррен-Мілл у передгір’ях Хіллсбрада та передайте «Зразок суміші Занзіла» Сержу Хінотту.$B$BЩоб дістатися до Таррен-Мілл, сідайте на цепелін до Андерсіті та рухайтеся дорогою на південь через Сільверпайн у напрямку Хіллсбрада. Слідуйте за вказівниками!$B$B",
    P = "Що це таке???",
    C = "Ти виглядаєш чудово блідо, $C. А що це за огидний запах від тебе йде? Я мушу це дізнатися!",
},

[2480] = {
    en = "Hinott's Assistance",
    T = "Допомога від Хінотта",
    D = "Я ще ніколи не бачив таких дивовижних результатів від отрути! Занзіл, кажеш? Ніколи про нього не чув, проте мушу віддати йому належне за створення цього зілля.$B$BОтже, я маю вилікувати тебе від цього, а потім навчити, як користуватися цією отрутою?$B$BДай мені кілька хвилин, щоб дослідити токсин, $N.",
    O = "Дочекайтеся, поки Серж Хінотт завершить лікування.",
    P = "",
    C = "Ліки готові! Випий цей антитоксин — і повзуче божевілля припиниться, але з запахом я, на жаль, нічого вдіяти не зможу.",
},

[2498] = {
    en = "Return to Denalan",
    T = "Повернутися до Деналана",
    D = "Мені щойно повідомили, що Деналан біля озера Аль-Амет виявив те, що, можливо, є причиною пухлин, які вражають молодих лісовиків. Будь ласка, поговоріть з ним і скажіть, що я вас надіслав.$B$BПоспішайте, $N; йому потрібна наша допомога.",
    O = "Релліан Грінспайр хоче, щоб ви поговорили з Деналаном біля озера Аль-Амет.",
    P = "",
    C = "А, тож Релліан відправив тебе, щоб ти мені допоміг. Я радий, що ти так швидко сюди дістався.$B$BЯ виявив щось дуже тривожне!",
},

[2499] = {
    en = "Oakenscowl",
    T = "Оукенскоул",
    D = "У печері на південному березі озера істота на ім’я Окенскоул поширює гниль серед усіх істот, які мешкають на озері Аль-Амет.$B$BЯ не наважився підійти надто близько, але навіть здалеку очевидно: Окенскоул отруєний найбільшою пухлиною, яку я коли-небудь бачив... Я б навіть назвав її гігантською.$B$B$N, ти вже багато зробив, щоб допомогти мені, але я прошу тебе виконати ще одне завдання. Вистеж Окенскоула й заберіть пухлину; усуньте це джерело розтління з моєї домівки.",
    O = "Деналан біля озера Аль-Амет просить вас дістати «Гігантську пухлину» в Оукенскоулі.",
    P = "Ти вже знайшов Окенскоул, $R?",
    C = "Я знав, що ти цілком здатний позбавити озеро від того жахливого чудовиська.$B$BЦе сумна ситуація; Оукенскоул колись був величним ватажком серед своїх... але розбещення не робить різниці між низькими й благородними.$B$BРозмір цієї пухлини досить тривожний, але я мушу її дослідити, щоб дізнатися більше про хворобу, яка вражає популяцію деревожителів.$B$BДякую, $N.",
},

[2500] = {
    en = "Badlands Reagent Run",
    T = "Похід за реагентами в Бедлендс",
    D = "$C, я хотів би скористатися вашими послугами. Я — досить відомий алхімік і прошу вашої допомоги в отриманні деяких реагентів, які можна знайти в Пустках.$B$BМені потрібні такі предмети, щоб поповнити свої запаси: п’ять шлунків канюка, десять іклів скельного койота та п’ять осколків скельного елементаля. Звісно, ви можете дістати їх у самих звірів; якщо ви не з тих, хто любить битися, то знайдіть друзів, які це вміють.$B$BЗдобудьте для мене ці предмети, і ви отримаєте за це трохи грошей.$B$BНу, що скажете?",
    O = "Знайдіть у Пустках реагенти, які потрібні Гаку Хелтучу, а потім поверніться до нього в Телсамарі.",
    P = "Ти вже приніс те, що мені потрібно? Ти не отримаєш грошей, якщо не принесеш мені ці реактиви.",
    C = "Ах, молодець, $N. Цього мені вистачить хоча б на деякий час. Ось твоя плата, як і обіцяв.$B$BЯкщо тобі цікаво, у мене є ще кілька реагентів, які мені знадобляться. Однак їх можна знайти лише в глибинах розкопок Улдамана. Дістати їх буде нелегко, але я винагороджу тебе гідно, якщо ти захочеш знову мені допомогти.$B$BМоже, чимось більшим, ніж просто блискучі монети, так?",
},

[2501] = {
    en = "Badlands Reagent Run II",
    T = "«Похід за реактивами в Бедлендс II»",
    D = "Ти дуже мені допоміг, $N. Я хотів би винагородити тебе саме тим рецептом зілля, яке дав тобі раніше, але мушу попросити тебе про послугу, яка є досить небезпечною.$B$BУ цьому сейфі лежать три порожні тауматургічні посудини; вони наділені аурою налаштування, яка висмокче кров спаленого дракона-охоронця. Використання однієї з них на звірі сильно розлютить його, тож будьте обережні. Як тільки ви наповните всі три, принесіть їх мені.$B$BЗробіть це, і рецепт стане вашим.",
    O = "Використовуйте порожні посудини для тауматургії, знайдені на обпалених драконах-охоронцях у Пустках. Коли ви їх наповните, віднесіть їх до Гака Хілтауча в Телсамарі.",
    P = "Ти скористався судинами, щоб дістати для мене кров обпаленого дракона-охоронця, яка мені потрібна? Так, я знаю, що це небезпечне завдання... але рецепт мого цілющого зілля залежить від твого успіху. Ризик і нагорода, мій друже... ризик і нагорода...",
    C = "Від одного алхіміка до іншого — вітаю тебе. Ось, візьми цей рецепт і закарбуй його у своїй пам’яті. Нехай він принесе тобі той самий успіх і нагороди, які приніс мені протягом багатьох років!",
},

[2518] = {
    en = "Tears of the Moon",
    T = "Сльози Місяця",
    D = "Колись леді Сатра була улюбленицею Елуни. Витончена й чиста, павучиха плела свої срібні нитки у місячному світлі, вловлюючи вечірній туман. Срібляста роса мала потужну цілющу силу і зберігалася тут, у храмі.$B$BАле останнім часом Сатра поринула у божевілля. Тепер під загрозою опинилися й її майбутні покоління.$B$BЗнайди леді Сатру, $N, і поклади край її стражданням. Вона мешкає на північних околицях Телдрасіля, поблизу озера Веллспринг. Збери її сріблясті павутинні залози й принеси їх мені.",
    O = "Жриця А'мура в Храмі Місяця в Дарнассусі просить вас принести їй «Сріблясті павутиння» леді Сатри.",
    P = "Я шкодую, що доручив тобі це завдання, але леді Сатра вже не врятувати.$B$BМи сподіваємося принести Елуні жертву у вигляді павутинних залоз. Завдяки цій жертві Елуна благословить Сатру, щоб вона змогла відродитися й знайти спокій.",
    C = "Ліс оплакує леді Сатру, але це було необхідно.$B$BДякую, $N.",
},

[2519] = {
    en = "The Temple of the Moon",
    T = "Храм Місяця",
    D = "Колись велична лісова істота потребує допомоги, $r.$B$BПотрібно виконати складне завдання.$B$BЗверніться до жриці А’мури; вона все вам пояснить. Знайдіть її на південний схід від цього місця, у Храмі Місяця.",
    O = "Сестра Акінне просить вас поговорити зі жрицею А'мурою в Храмі Місяця.",
    P = "",
    C = "Тож, це сестра Аквінне вас прислала?",
},

[2520] = {
    en = "Sathrah's Sacrifice",
    T = "Жертва Сатри",
    D = "Тепер ти повинен завершити завдання, яке тобі доручили. Візьми павутиння та принеси Елуні жертву від імені леді Сатри; поховай великого павука.$B$BУсередині цього храму знайди центральний фонтан. Саме там ви зможете залишити жертву. Священна вода очистить і змиє ту порчу, яка звела Сатру з розуму.$B$BКоли ви це зробите, поверніться до мене.",
    O = "Жриця А'мура просить вас помістити сріблясті павутинні залози леді Сатри до фонтану всередині храму, а потім повернутися до неї.",
    P = "Ти поклав жертву біля фонтану, $n?",
    C = "Втрата леді Сатри — це велике горе, але лише таким чином вона зможе відродитися з оновленим духом.$B$BНехай Елуна з радістю прийме жертву, яку ти їй приніс.",
},

[2521] = {
    en = "To Serve Kum'isha",
    T = "На службі Куміші",
    D = "$R, чи здатний твій крихітний мозок усвідомити, наскільки рідкісною є бездоганна куля з драенетисту? Драени витрачали цілі життя на пошуки хоча б одного такого кристала, але їх чекала жахлива доля, і їхня мета так і залишилася нездійсненою.$B$BТож ти стоїш перед Кумішею, знаючи, про що вона просила, і все одно бажаєш допомогти? Добре, $r... Якщо під час своїх мандрів цими землями ти знайдеш бездоганну кулю з дренетисту, поверни її мені, і я винагороджу тебе багатствами, про які ти навіть не мріяв.",
    O = "Якщо під час ваших мандрівок по Зруйнованих Землях вам трапиться Бездоганна сфера з драенетисту, віднесіть цей предмет до Куміші, Колекціонера.$B$BМайте на увазі: цей самоцвіт — один із найрідкісніших кристалів у всьому Азероті. Будь-яка істота на цих землях може мати при собі бездоганну сферу з дренетисту.$B$BВи отримаєте нагороду за кожну зібрану бездоганну сферу з дренетисту.",
    P = "Я присвятив своє життя пошукам бездоганних сфер із драенетисту. Ціле життя, $R!",
    C = "Чи не обманюють мене очі? Неможливо! Звідки ти... Як...$B$BМожливо, тепер вдасться відкрити прохід, який поверне нас на батьківщину.",
},

[2522] = {
    en = "Kum'isha's Endeavors",
    T = "Починання Куміші",
    D = "Хоча заклинання для створення порталу закінчилося невдачею, я все ще сподіваюся, що моя наступна спроба буде успішною.$B$BНадія драені така ж палка, як і твоя жадібність до дрібничок, $r. Повертайся на ці прокляті землі й знайди ще одну бездоганну сферу з драенетисту.$B$BЗвісно, рішення взятися за це завдання повністю залишається за тобою *усмішка*.",
    O = "Знайдіть і поверніть бездоганну сферу з дренетисту колекціонеру Куміші.",
    P = "Ти знайшов ще одну бездоганну сферу з дренетисту?",
    C = "Просто дивовижно. Я сумнівався, що ти зможеш знайти ще одну кулю, а ось вона — пульсує в моїх руках.$B$BМолодець, $N!$B$BЯкщо ти знайдеш ще такі — хоча я вважаю це неможливим — поверни їх мені, і я знову винагороджу тебе.",
},

[2523] = {
    en = "Corrupted Songflower",
    T = "Зіпсована пісенна квітка",
    D = "",
    O = "",
    P = "Ви знайшли хвору, пошкоджену рослину, схожу на пісенну квітку. Від неї виходить різкий, неприємний запах. Щоб повернути її до нормального стану, їй терміново потрібна якась допомога.",
    C = "Ви наносите на пісенну квітку трохи мазі з рослин Сенаріону. Вона одразу ж починає позбуватися своєї спотвореної форми, перетворюючись на яскраву й здорову рослину.",
},

[2541] = {
    en = "The Sleeping Druid",
    T = "«Сплячий друїд»",
    D = "Шамани Гнарпайн, які мешкають у цьому місці, відкрили спосіб відокремити дух сплячого друїда від фізичного тіла. Фурболги оживили моє фізичне тіло і використовують його для нападу на всіх, хто намагається дослідити Лігво курганів Бан’етіл. Зараз я ув’язнений у Смарагдовому Сні й не маю сил це зупинити.$B$BТи мусиш мені допомогти. Шамани Гнарпайн носять із собою дивний амулет, який використовується для проведення цього ритуалу, і я хотів би його дослідити. Будь ласка, $N, принеси мені один.",
    O = "Принесіть амулет шамана-вуду Обену Рейгклоу в лігві «Курган Бан'етіл».",
    P = "Якщо я зможу оглянути амулет, то, можливо, мені вдасться з’ясувати, як зняти закляття. Ти вже знайшов такий?",
    C = "Дякую, $N.$B$BЯка дивна дрібничка... Я відчуваю, як від неї випромінюється зловісна аура; це дуже потужне зачарування.",
},

[2561] = {
    en = "Druid of the Claw",
    T = "Друїд Кігтя",
    D = "Оглянувши цей амулет, $N, я тепер розумію, що треба зробити. Будь ласка, візьми його і зроби так, як я прошу.$B$BТобі належить дослідити найглибші куточки лігва «Банетіл Барроу». Там ти знайдеш моє бездушне тіло... Хоча мені прикро те, що я збираюся вам сказати, я не бачу іншого способу звільнитися від контролю Гнарлпайн.$B$BЩоб я зміг втекти від них, ви повинні знищити мою фізичну оболонку. Як тільки це буде зроблено, застосуйте амулет вуду до мого мертвого тіла. Після виконання цього завдання, будь ласка, поверніться до мене.",
    O = "Обен Рагеклоу хоче, щоб ти знищив його бездушне тіло, а потім застосував «Амулет вуду».",
    P = "$N, будьте обережні, наближаючись до моєї фізичної форми; закляття, під дією якого вона перебуває, є досить потужним.",
    C = "Нарешті я звільнився від влади Гнарлпайна. Дякую тобі, $N.$B$BТепер моя душа зможе назавжди спочивати з миром у Смарагдовій Мрії.$B$BМожливо, одного дня ми знову зустрінемося, юний $C. А поки що, будь ласка, прийми цю нагороду як знак моєї вдячності.",
},

[2581] = {
    en = "Snickerfang Jowls",
    T = "Щічки Снікерфанга",
    D = "Загальновідомо, що гієни мають надзвичайну силу щелеп, але чи здатні вони розгризти три дюйми торієвої сталі? Неможливо, малоймовірно, і все ж я бачив це на власні очі.$B$BВідправляйся у Спустошені Землі й принеси мені три щелепи сміхозуба. Під час пошуків сміхозуба пильнуй за кабанами та скорпоками: для завершення початкового аналізу також потрібні дві легені спустошеного кабана та одна клешня скорпока.",
    O = "Принесіть три щелепи Снікерфанга, дві легені підірваного кабана та одну клешню Скорпока до кровомага Дразіала.",
    P = "Від тебе неприємно пахне, $N. Ти що, по селах із сірчаними родовищами блукав? І де мої деталі?!",
    C = "Як ти себе почуваєш, $N? Ти просто випромінюєш ауру снікерфанга — твою силу, якій немає рівних серед смертних!$B$BНа жаль, з тих інгредієнтів, які ти приніс мені, я зміг приготувати розчину лише на одну таблетку. Мені знадобляться додаткові інгредієнти, якщо тобі знадобиться ще одна таблетка.",
},

[2582] = {
    en = "Rage of Ages",
    T = "Гнів століть",
    D = "Ах, $N, з поверненням. Схоже, тобі сподобався ефект потужного, дієвого зачарування, отриманого зі снікерфанга. Але майте на увазі: хоча безпосереднім ефектом є титанічний сплеск сили, довгострокові наслідки для вашого духу та інтелекту можуть виявитися небезпечними.$B$BЗ огляду на це, чи потрібно тобі ще? Якщо так, принеси мені ще три щелепи снікерфанга, дві легені підірваного кабана та одну клешню скорпока.",
    O = "Принесіть три щелепи Снікерфанга, дві легені підірваного кабана та одну клешню Скорпока до Кровомага Дразіала.",
    P = "У вас є органи звіра?",
    C = "Ось, будь ласка! Пам’ятайте, користуйтеся ним економно. Якщо вам знадобиться ще один, завітайте до мене, коли використаєте той, що зараз у вас є.",
},

[2583] = {
    en = "A Boar's Vitality",
    T = "Життєва сила кабана",
    D = "На цих проклятих землях мешкають два види кабанів: кабан із попелястою гривою та гельбоар.$B$BСхоже, що витривалість цих тварин робить їх майже невразливими, оскільки іншим тваринам надто важко їх вбити, а отже, це не вартує зусиль.$B$BНам потрібно провести додатковий аналіз, $N. Якщо ти принесеш мені три легені проклятого кабана, дві клешні скорпока та один мозок василіска, я створю божественний еліксир із залишків аналізу. Ти станеш моїм першим піддослідним!",
    O = "Принесіть три легені підірваного кабана, дві клешні скорпока та один мозок василіска до кровомага Дразіала.$B",
    P = "Де ж ці органи, $N!?",
    C = "Дух кабана осяює твоє єство, $N! Цікаво, чи вважаєш ти себе таким же невразливим, як ці звірі?$B",
},

[2584] = {
    en = "Spirit of the Boar",
    T = "Дух кабана",
    D = "Коли я вперше дав тобі еліксир, $N, я відразу зрозумів, що одного-двох прийомів тобі не вистачить, щоб вгамувати апетит. Навіть зараз я бачу голод у твоїх очах. Цей мікстур має властивості, що викликають звикання, і, здається, навіть найсильніші духом не можуть йому протистояти.$B$BХай буде так! Якщо тобі знадобиться ще цього коктейлю з легеневого соку, вирушай назад у пустку й знайди для мене три легені проклятого кабана, дві щипці скорпока та один мозок василіска.",
    O = "Принесіть три легені підірваного кабана, дві клешні скорпока та один мозок василіска до кровомага Дразіала.$B",
    P = "Де ж ці органи, $N!?",
    C = "Мушу попередити тебе, $N, не намагайся змішувати створені мною суміші. Хімічні властивості тієї суміші, яку ти щойно проковтнув, завжди матимуть перевагу над попередніми зачаруваннями, що, відповідно, зведе нанівець дію іншої суміші.",
},

[2585] = {
    en = "The Decisive Striker",
    T = "Вирішальний нападник",
    D = "Ти коли-небудь спостерігав за ними в бою, $N? Я маю на увазі скорпоків. Чи бачили ви коли-небудь, з якою грацією та спритністю вони рухаються? Як рішуче вони завдають ударів?$B$BЯкби тільки ми могли якось виділити цю спритність і увібрати її в капсулу, ми б стали багатіми понад наші... Тобто… це було б справжнім благом для наукової спільноти.$B$BДопоможи мені, $N, і я дозволю тобі взяти зразок для аналізу.$B$BЩоб створити стабільний зразок, мені знадобляться три клешні скорпока, два шлунки грифа та одне прокляте легеня кабана.",
    O = "Принесіть три клешні скорпока, дві шлунки грифа та одне легеню підірваного кабана магу крові Дразіалу.$B",
    P = "Де органи, $N!?$B",
    C = "Цікаво. Це був найскладніший для аналізу зразок із усіх.$B$BВізьміть щіпку цієї залишкової солі та покладіть її під язик. Ви повинні відчути легке відчуття ейфорії, за яким настане стан безпрецедентної спритності та швидкості.",
},

[2586] = {
    en = "Salt of the Scorpok",
    T = "Сіль Скорпока",
    D = "Ти живий! Це справді гарна новина. Припускаю, ти повернувся, щоб продовжити дослідження скорпока?$B$BГаразд, $N, повертайся на пустку і не повертайся, доки не збереш три клешні скорпока, дві шлунки грифа та одне прокляте легене дикого кабана.",
    O = "Принесіть три «Клешні Скорпока», два «Жлубки грифа» та одне «Легене підірваного кабана» магу крові Дразіалу.",
    P = "Де ж ці органи, $N!?",
    C = "Чудова робота, $N. Ось один зразок препарату для тебе, а решта дев’ять підуть на мої дослідження.$B$BЯкщо тобі знадобиться ще подрібненого препарату скорпока, звернися до мене, і ми домовимося.",
},

[2601] = {
    en = "The Basilisk's Bite",
    T = "Укус василіска",
    D = "Ці пустки кишать базилісками з червоного каменю, $N. Ці базиліски пристосувалися до умов і процвітають тут більше, ніж будь-які інші дикі тварини в цьому регіоні.$B$BЯ спостерігав здалеку, як вони полюють і займаються своїми повсякденними справами — ці звірі демонструють мислення, складніше навіть за деяких гуманоїдів.$B$BЯ мушу дослідити їхні мізки!$B$BЗдобудь для мене десять їхніх мізків, $N. Однак суміш не буде повноцінною без двох шлунків грифів, які стануть основою розчину.",
    O = "Принесіть десять мізків базиліска та дві шлунки грифа до маг-кровожерки Ліннор.$B",
    P = "Ви вже повернулися із необхідними органами?",
    C = "Це дивовижно, $N! Я пропоную тобі ознайомитися з внутрішнім механізмом роботи редстоунського василіска.$B$BЯкщо ця суміш тобі сподобається, її завжди можна виготовити ще... за певну ціну.",
},

[2602] = {
    en = "Infallible Mind",
    T = "Безпомилковий розум",
    D = "Твоя зосередженість так швидко зникла? Потрібно провести більше досліджень!$B$BАх так, ціна залишається незмінною, $N. Рушай у спустошені землі й повернися до мене з десятьма мізками з червоного каменю та двома шлунками грифів.$B",
    O = "Принесіть десять мізків базиліска та дві шлунки грифа до кровомаги Ліннор.",
    P = "Ви вже повернулися із необхідними органами?",
    C = "Так, так, дай мені хвилинку — і ще трохи цього препарату буде готове до вживання, $N.$B$BПрийми його... і $N, не намагайся вживати ці експериментальні суміші одну за одною. Наслідки можуть бути катастрофічними.",
},

[2603] = {
    en = "Vulture's Vigor",
    T = "Сила грифа",
    D = "Смерть справді має крила на цих проклятих землях, $r. Я бачив, як чорні вбивці та кісткозбирачі ласували трупами багатьох загиблих мандрівників — іноді харчуючись найогиднішими й найзараженішими тушами. Тож дивно, як їхні внутрішні системи долають ту чуму, що охопила ці землі.$B$BДопоможи мені в моїх дослідженнях, $N! Мені потрібні шлунки! Також для основи зілля знадобляться дві щелепи сміхозуба.$B$BЗа твої зусилля ти отримаєш подвійну винагороду.",
    O = "Принесіть десять шлунків грифа та дві щелепи Снікерфанга до магині крові Ліннор.$B",
    P = "Не марнуй мій час, $N. Нам немає про що говорити, якщо ти не повернув речі, які я просив.",
    C = "Чудово! Я негайно візьмуся за роботу. Можливо, вдасться знайти ліки від багатьох недуг цього світу!$B$BАх так, щодо вашої винагороди — звичайно, якщо вам знадобиться ще гумки, поверніться до мене, і я доручу вам ще одне завдання.",
},

[2604] = {
    en = "Spiritual Domination",
    T = "Духовне панування",
    D = "Бачу, що внутрішній вогонь згас. Ти б сказав, що духовна ейфорія тривала годину?$B$BЯкщо ти хочеш ще жуйки з шлунків, то мені знадобиться ще шлунків. Повертайся на пустки, $N. Не повертайся, доки не знайдеш десять шлунків і дві щелепи.",
    O = "Принесіть десять шлунків грифа та дві щелепи снікерфанга до магині крові Ліннор.$B",
    P = "Не марнуй мій час, $N. Нам немає про що говорити, якщо ти не повернув речі, про які я просив.",
    C = "Можливо, одного дня мені вдасться виділити активні ферменти цього тесту й отримати набагато ефективніший препарат. На жаль, вам доведеться задовольнитися тим, що я можу виготовити на даний момент. Зверніться до мене, якщо вам знадобиться ще гумки з м’язової частини шлунка.",
},

[2605] = {
    en = "The Thirsty Goblin",
    T = "«Спраглий гоблін»",
    D = "У мене є ідея, бачиш. Я чув про дивних істот, яких називають «збирачами роси», що мешкають на південному заході... і що вони здатні накопичувати воду в спеціальних залозах.$B$BГадаю, якби мені вдалося дістати одну з цих залоз, я міг би створити напій, який втамував би мою страшенну спрагу! Як думаєш, ти міг би мені допомогти, $N?$B$BШукай кактусовий сад, $N; саме там ти знайдеш «збирачів роси».",
    O = "Зберіть «Наповнену росову залозу» і віднесіть її Маріну Ногенфоггеру в Гаджетзані.",
    P = "Будь ласка, скажи, що ти знайшов збирачі роси?",
    C = "О, чудово! Дай-но сюди — дай мені випити!",
},

[2606] = {
    en = "In Good Taste",
    T = "З гарним смаком",
    D = "Фу! Це жахливо на смак! Ось і вся ця ідея...$B$BСтривай, а що це? О, я знаю, я знаю, ти вважаєш, що мені не варто відмовлятися від цього. Ну, тоді гаразд.$B$BУууу, у мене є ідея! Геніальна! Віднеси цю росу моїй подрузі Спрінкл — вона чудова кухарка. Розкажи їй, що ми тут робимо, і що хочемо, щоб це трохи легше ковталося.$B$BТобто, якщо воно вже так погано смакує, то хоча б мало якийсь присмак... А я просто не відчуваю його...",
    O = "Марін Ноггенфоггер хоче, щоб ви поговорили зі Спрінклом у Гаджетзані.",
    P = "То старий Марін знову за своє, еге ж? З чого ж зроблена ця суміш?",
    C = "Марін — хороший хлопець, не зрозумійте мене неправильно — просто трохи… ексцентричний, я б сказав.$B$BІ, звісно, йому знову потрібна моя допомога.",
},

[2607] = {
    en = "The Touch of Zanzil",
    T = "«Дотик Занзіла»",
    D = "Схоже, ти приніс навіть більше інформації, ніж я очікував. Це, безперечно, дивний поворот подій, $N.$B$BЛіки? Гм... Спустися до підвалу й поговори з доктором Міксілпіксілом — можливо, він зможе допомогти.",
    O = "Поговоріть з Доком Міксілпіксілом у підвалі казарм.",
    P = "",
    C = "Нарешті! Просто поклади сир на стіл і змивайся. Осборн розрахується з тобою, коли ти будеш виходити.",
},

[2608] = {
    en = "The Touch of Zanzil",
    T = "«Дотик Занзіла»",
    D = "Ой, ти виглядаєш, наче сама смерть. Виправлюся — я бачив смерть, а ти виглядаєш гірше за неї. Ти, $g пане/пані, — це те, що смерть виплюнула під час свого останнього медичного огляду.$B$BХа! Ти це чув, Ноарм? Запиши це!$B$B*Кашель* Гм, так, щоб я міг тобі допомогти, мені доведеться взяти трохи крові. Не хвилюйся, боляче буде лише перші кілька… п’ятдесят разів або близько того… /лягай, коли будеш готовий до процедури, $N.",
    O = "/Ляж, щоб доктор Міксілпіксіл тебе оглянув. Як він зможе знайти ліки, якщо не знайде причину?$B",
    P = "Коли ви будете готові до обстеження, /ляжте на підлогу, і я почну забір крові.",
    C = "Дайте мені хвилинку, щоб порадитися з колегами, $N. Докторе Монтгомері, пане Ноарм, давайте порадимося!",
},

[2609] = {
    en = "The Touch of Zanzil",
    T = "«Дотик Занзіла»",
    D = "Рішення одностайне, $N. У тебе «ітіс».$B$BНа щастя, у мене є ліки від «ітісу».$B$BОсь що мені потрібно: Один букет простих польових квітів, одну свинцеву колбу, одну бронзову трубку і, нарешті, що не менш важливо, одну котушку світло-зеленої шовкової нитки. Стара Емма залишила для мене таку котушку в крамниці «Найкраща нитка». Ти знайдеш цю крамницю вздовж каналів.$B$BПоспішай, $N, і постарайся нікого не торкатися, доки не вилікуєшся. А ще доктор Монтгомері каже, що тобі треба прийняти душ — це його слова, не мої.",
    O = "Принеси доктору Міксіліпсілу один пучок простих польових квітів, одну свинцеву колбу, одну бронзову трубку та одну котушку світло-зеленої шовкової нитки. «Ітіс» сам собою не проходить, молодий $g хлопче:дівчино;.",
    P = "Якщо ти хочеш вилікуватися від «ітісу», тобі доведеться докласти більше зусиль, $n. Де реактиви для лікування?",
    C = "Що я роблю? А на що це схоже? Я розробляю ліки від твого «-іту»! Не обурюйся на мене, $n!$B$BЩе кілька секунд. Ось! Просто розпороши на себе це, е-е, ліки з фантастичним запахом, і ти будеш як новий.",
},

[2621] = {
    en = "The Disgraced One",
    T = "Зганьблений",
    D = "Жаль. Це все, що у мене залишилося. Одне неправильне рішення призвело до кількох жахливих наслідків. Якби ж я дочекався тих наказів! Можливо, у них би детально описувалися ті жахи, що чекали на нас у тих проклятих краях! Можливо, нас мали перенаправити до іншого загону? Зрештою, це була моя вина. Усе це — моя вина.$B$BОтож я стою тут, чекаючи на накази. Я мушу знати. Я мушу отримати ті накази.$B$BКомандир диспетчерської служби Руаг перебуває у Стонарді. Знайди його й дізнайся, що сталося з тими наказами.$B",
    O = "Поговоріть із начальником диспетчерської служби Руагом у Стонарді.",
    P = "",
    C = "«Хватка Тролла»... Ця історія досі свіжа в моїй пам'яті.$B$B<Командир Руаг хитає головою>$B$BСтрашна річ сталася з тим полком. Орда втратила деяких зі своїх найкращих воїнів, коли той батальйон був знищений.",
},

[2622] = {
    en = "The Missing Orders",
    T = "Зниклі замовлення",
    D = "Накази? Навіщо тобі взагалі потрібні ці накази?$B$BНа що ти натякаєш, $N? Звісно, я передав ці накази! Солдати, яким я доручив доставити накази, потрапили в засідку й були жорстоко побиті мурлоками. Вижив лише один, якщо це взагалі можна назвати виживанням. Він ледве може говорити, не може ходити, і його доводиться годувати через зонд. Якщо хочеш дізнатися, що сталося з тими наказами, поговори з Бенгором. Я впевнений, що він десь тут поруч... і, $N, будь обережним, у що сунеш свого носа — його можуть відкусити.",
    O = "Поговоріть з Бенгором.",
    P = "",
    C = "Болотний бала... бала... балакун...$B$B",
},

[2623] = {
    en = "The Swamp Talker",
    T = "«Болотний оповідач»",
    D = "Накази віддавав командир диспетчерської служби. Ми виконували… виконували накази. По дорозі до Проклятих земель потрапили в засідку.$B$BМурлоки… Багато мурлоків… Один із них називався «Болотний Говоритель». Отримав наказ від моїх рук, коли спис встромився мені в череп. На схід... печера....$B$B<Бенгор втрачає свідомість.>$B",
    O = "Знайдіть накази Вождя війни та поверніть їх Загиблому герою Орди.",
    P = "Очікую на вказівки.",
    C = "Все набагато гірше, ніж я уявляв. Дев’ятнадцять моїх людей можна було врятувати від тих мук, які їм довелося пережити. Якби тільки я не вчинив так нерозважливо.$B$BТи мусиш їм допомогти, $N! Я безсилий щось зробити.",
},

[2641] = {
    en = "Sprinkle's Secret Ingredient",
    T = "Секретний інгредієнт «Sprinkle»",
    D = "Коли я був дитиною, моя сестра завжди готувала їжу. Це було жахливо! Деякі з її кулінарних витворів я ледь міг з’їсти — аж поки не знайшов те, що я люблю називати своїм «секретним» інгредієнтом! Додай його до будь-чого, і… ВАУ! Смакує просто чудово!$B$BЩо це, запитаєш ти? Це гриб під назвою «Фіолетовий траган». Якщо хочете, щоб я допоміг вам перетворити цю огидну на смак мішанину на щось їстівне, вирушайте до Глибин і знайдіть там невелике озеро.$B$BО, і пам’ятайте: фіолетовий траган можна знайти лише під водою.",
    O = "Спрінкл із Гаджетзана просить тебе знайти Фіолетового Трагана та повернути його їй.",
    P = "Під водою того озера — це єдине місце, де можна зустріти Фіолетового Трагана. Сподіваюся, ти вмієш добре затримувати подих!",
    C = "Оце так, $N!$B$BВиглядає так смачно, що я, мабуть, просто... Ха-ха, попався!",
},

[2661] = {
    en = "Delivery for Marin",
    T = "Доставка в Марін",
    D = "Ось «Фіолетовий порошок», $N. Віднеси його Маріну і скажи йому, що він у мене в боргу!",
    O = "Спрінкл хоче, щоб ви віднесли фіолетовий порошок Марін Ногенфоггер у Гаджетзані.",
    P = "О, $N, ти нарешті повернувся. Що ти приніс?",
    C = "«Фіолетовий порошок», так? Давай спробуємо — гірше від цього точно не стане, це точно!",
