[2662] = {
    en = "Noggenfogger Elixir",
    T = "Еліксир «Ноггенфоггер»",
    D = "А тепер треба змішати цей порошок з росою.$B$BПовернися і поговори зі мною через хвилинку... коли я доводжу до досконалості цей чудовий еліксир «Ноггенфоггер»!",
    O = "Марін Ноггенфоггер хоче, щоб ви знову з ним поговорили після того, як він приготує свій еліксир.",
    P = "",
    C = "Випий це! Це просто чудово!!!$B$BЯ знав, що в мене це вийде... О, ще раз дякую, $N, за допомогу, але, будь ласка, відійди трохи вбік, гаразд? Ти заважаєш мені працювати! Я зароблю мільйони на чудовому еліксирі «Ноггенфоггер», мільйони!$B$BЩо це? Спрінкл каже, що я їй винен послугу? О, ця Спрінкл, така жартівниця!",
},

[2681] = {
    en = "The Stones That Bind Us",
    T = "Камені, що нас єднають",
    D = "Щоб перемогти сили Разеліха та його підлеглих, одних твоїх сил буде замало.$B$BЗбери відповідну групу шукачів пригод і звільни моїх людей від вічних мук! Ви повинні розбити вісімнадцять каменів.$B$BБийтеся відважно і помріть з честю, $N.",
    O = "Звільніть дев’ять Слуг Разеліха, трьох Слуг Севіна, трьох Слуг Алістаржа та трьох Слуг Грола. Поверніться до «Падшого героя», коли виконаєте завдання. Ви повинні залишатися в безпосередній близькості від каменів, інакше процес завершиться невдачею.",
    P = "Це нелегке завдання, $N. Не здавайся!",
    C = "Ти це зробив, $N! Бідні, змучені душі нарешті зможуть спочивати.$B$BНаша робота ще не закінчена, $N. Нам є про що поговорити, і ще багато чого потрібно зробити.",
},

