[2882] = {
    en = "Cuergo's Gold",
    T = "«Золото Куерго»",
    D = "На цій карті зображено ділянку пляжу, що виходить на південь. Під картою — слова, виписані витонченим почерком...$B$BНа південь від Уідла$BНа південь від дому$BЗнайди щоглу, прапор і кістки$BКопай там, якщо ти сміливий$BКопай і заволодій золотом Куерго!$BТобі знадобиться ключ, і ти побачиш ключ$BЛюди, з якими ти зіткнешся, беруть кров як плату.",
    O = "Знайдіть золото Куерго!",
    P = "Цей скринька замкнена!",
    C = "На вас чекає прихований скарб капітана Куерго!",
},

[2902] = {
    en = "Woodpaw Investigation",
    T = "Розслідування «Вудпоу»",
    D = "Гноли не відзначаються особливою кмітливістю, але, без сумніву, у них має бути якась задокументована стратегія щодо їхніх останніх дій. Якщо нам вдасться знайти ці плани, ми отримаємо чіткіше уявлення про те, що саме їх так розбурхує.$B$BЯ хочу, щоб ти повернувся до «Вудпоу» і знайшов усе, що може нагадувати їхні бойові плани. У них має щось бути; їхні атаки були надто злагодженими, щоб здійснюватися без таких планів. Знайди їх і повернися до мене, коли знайдеш.",
    O = "Знайдіть бойові плани гнолів десь у таборах гнолів на південь від табору Моджаче.",
    P = "",
    C = "При детальному розгляді карти стає зрозуміло, що це саме ті бойові плани, які шукає Хадокен Свіфтстрайдер. На карті намальовано безліч стрілок, які, ймовірно, позначають переміщення військ, хоча більшість із них, здається, спрямовані на південь, а не на північ, де розташований табір Моджаче.$B$BНа іншій частині карти зображено те, що, на вашу думку, є якимось великим комахою, а під ним — різні позначки. Судячи з вигляду гнолів, це, можливо, відображає їхні втрати у боях проти невідомих комах...",
},

[2903] = {
    en = "The Battle Plans",
    T = "Бойові плани",
    D = "Оскільки бойові плани гнолів виявлено, тепер залишається лише доставити їх Хадокену Свіфтстрайдеру в табір Моджаче. Можливо, він або хтось із тамтешніх зможе розібратися, що саме замишляють гноли.",
    O = "Віднесіть «Бойові плани Вудпоу» Хадокену Свіфтстрайдеру в табір Моджаче.",
    P = "З поверненням, $N — чи вдалося тобі знайти якісь конкретні докази щодо планів гнолів?",
    C = "Ах, це саме те, що нам було потрібно. Хоча я не надто вправний у розшифровці більшості тих каракулів на цій карті, я бачив у своєму житті достатньо бойових планів, щоб зрозуміти, що відбувається з гнолами. Схоже, вони зараз ведуть війну на два фронти. На одному з них — проти нас... але, здається, основні сили вони кинули на ворога, що знаходиться на півдні від них.$B$BТут приховано більше, ніж видно на перший погляд. Можливо, настав час з’ясувати, хто насправді є цей інший ворог, з яким вони стикаються.",
},

[2904] = {
    en = "A Fine Mess",
    T = "Непроста ситуація",
    D = "<Кернобі стогне.> Що… Що сталося?$B$BОстаннє, що я пам’ятаю, — це те, що мене захопила група темнозалізних гномів, побили до півсмерті, а потім кинули сюди разом із цими брудними трогами.$B$BВитягни мене звідси, $N!$B$BОсь план: Відведи мене до виходу; якщо ми виберемося звідси живими, ти підеш до Буті-Бей і повідомиш Скуті, що я поїхав до Ратчета, щоб попередити Тінкервіза про причетність темнозалізних до створення тієї суперплатформи.$B$BПоїхали!",
    O = "Супроводи Кернобі до виходу з «Клокверк-Ран», а потім звернися до Скуті в Буті-Бей.",
    P = "Що? Кернобі живий??",
    C = "Гадаю, тебе слід винагородити за те, що ти повернув нам Кернобі цілим і неушкодженим, $N. Якщо ти повернешся до Гномерегана, ці речі можуть стати тобі у нагоді в боротьбі з тим нікчемним зрадником, Мекгініром Термаплаггом.",
},

[2922] = {
    en = "Save Techbot's Brain!",
    T = "Врятуйте мозок Techbot!",
    D = "Коли впало наше улюблене місто Гномереган, мабуть, якась блукаюча іскра вразила моє бідне творіння — Техбота. Колись він допомагав мені та моїм колегам своїми незліченними пристосуваннями та безмежним запасом інформації, але його позитронний мозок зазнав поляризації. Тепер він негатронний… і поведінка Техбота змінилася на протилежну. Він у несамовитості блукає Гномереганом!$B$BАле, можливо, його ще можна врятувати. Можливо, якщо ти зможеш дістати ядро пам’яті Техбота й принести його мені, я зможу з’ясувати причину поляризації та полагодити мого бідолашного Техбота.$B$B",
    O = "Принесіть «Ядро пам’яті» Techbot до Тінкмастера Оверспарка у Центрі відновлення Гномерегана.",
    P = "Ви знайшли Techbot? Ви вилучили його ядро пам’яті??",
    C = "О, це чудово! Дякую, $N! Я одразу ж візьмуся за роботу!!$B$BБідний, бідний Техбот... Не переймайся. Ми тебе полагодимо.$B$BА де ж я поклав ту вилку для мого гідравлічного поворотного гайкового ключа...",
},

[2923] = {
    en = "Tinkmaster Overspark",
    T = "Tinkmaster Overspark",
    D = "Майстер-швейцар Оверспарк дуже засмучений долею свого механічного творіння — Текбота. Я пам’ятаю Текбота як добрий і корисний помічник для гномів, але Оверспарк каже, що той вийшов з ладу.$B$BДуже сумно. Але, можливо, з трохи везіння його вдасться полагодити!$B$BПоговоріть із Тінкмастером Оверспарком у Центрі відновлення Гномерегана в Дун-Морозі. Він буде радий вашій допомозі.",
    O = "Поговоріть із Тінкмастером Оверспарком у Центрі відновлення Гномерегана в Дун-Морозі.",
    P = "",
    C = "Так, це правда. Techbot зник $C! Будь ласка, допоможіть мені!",
},

[2924] = {
    en = "Essential Artificials",
    T = "Необхідні штучні приманки",
    D = "Майже універсальний механічний компонент — незамінний штучний пристрій — був надзвичайно корисним для майстрів-ремісників та ковалів Гномерегана. Але під час панічного виходу з нашого міста ніхто не згадав взяти з собою жодного з цих пристроїв! А мені потрібен великий запас таких пристроїв для роботи, яку я незабаром розпочну.$B$BБудь ласка, зайдіть до Гномерегана й принесіть мені кілька важливих штучних пристроїв. Ви знайдете їх у глибинних районах нашого міста, у контейнерах, що називаються штучними екстраполяторами.$B$BДякую, $N, і, будь ласка, поспішіть!",
    O = "Принесіть 12 необхідних штучних предметів до Клокморта Спаннерспана на об’єкті з відновлення Гномерегана.",
    P = "Чи є у вас необхідні штучні приманки?",
    C = "Ти їх дістав! Тепер я можу розпочати свої нові експерименти!$B$BЯ не знаю, як тобі віддячити, $N! Твоя хоробрість зробила гігантський стрибок у розвитку гномських досліджень!",
},

[2925] = {
    en = "Klockmort's Essentials",
    T = "Основні принципи Клокморта",
    D = "Мій друг-гном, Клокморт Спаннерспан, надіслав мені повідомлення з Айронфорджа. Він каже, що йому потрібна допомога в небезпечній, але надзвичайно важливій місії в Гномерегані — колись величному місті гномів, яке тепер забруднене й заповнене божевільними гномами та їхніми винаходами.$B$BЯ мушу залишитися тут, але моє серце болить від бажання допомогти другові. Якщо ти зможеш піти замість мене, я буду тобі дуже вдячний.$B$BТи можеш знайти Клокморта в Центрі відновлення Гномерегана, що в Дун-Морозі.",
    O = "Поговоріть із Клокморт Спаннерспаном у Центрі відновлення Гномерегана в Дун-Морозі.",
    P = "",
    C = "Так! Мені дійсно потрібна допомога з квестом у Гномерегані. І ти — саме та людина $C, яка може це зробити!",
},

[2926] = {
    en = "Gnogaine",
    T = "Гногейн",
    D = "З часу нещасного випадку Гноарн тільки й думає, й говорить про те, щоб очистити Гномереган від навали трогів та знайти ліки від хвороби, яка його вразила, $N.$B$BНа щастя, Раззл і я вже близькі до відкриття якогось ліків — або цього, або рецепта справді потужного рому. Ми не дізнаємося, поки не перевіримо! Звісно, щоб перевірити нашу теорію, нам знадобиться дещо, а саме — радіоактивні осади від опромінених трогів у Гномерегані. Наповни цю колбу зеленим сяйвом і принеси її назад!",
    O = "Використовуйте порожню свинцеву флакон для збору радіоактивного осаду на «Опромінених загарбниках» або «Опромінених мародерах». Коли флакон наповниться, поверніть його Оззі Тогглвольту в Хараносі.",
    P = "Хіба ти не бачиш, що ми тут намагаємося вилікувати цілий вид гномів??! Нам потрібно більше цього зеленого сяйва!",
    C = "Чудова робота! Настав час випробувати нову формулу. Якщо це спрацює, то не тільки той полонений гном-прокажений вилікується, але й у мене з’явиться густа шевелюра! Відійдіть!",
},

[2927] = {
    en = "The Day After",
    T = "Наступного дня",
    D = "Ви ж не думаєте, що я завжди був лисим, правда? Ні, $g пане/пані! Саме витік радіації в Гномерегані став причиною цієї трагічної втрати волосся. До того дня я мав єдину гномську зачіску в усьому Азероті.$B$B<Гноарн злісно стискає кулак у повітрі.>$B$BХай прокляті ті брудні троги — хай прокляті всі вони!!$B$BМожливо, ще не пізно, $N. Ми, можливо, ще зможемо врятувати його — я маю на увазі місто! Поговоріть з Оззі Тогглволтом у Хараносі. Він і його напарник Раззл працюють над рішенням.",
    O = "Поговоріть з Оззі Тогглволтом у Хараносі.",
    P = "",
    C = "Я думав, що втрата тієї чудової шевелюри точно стане для нього фатальною, але він вижив!$B$BЯ стояв прямо поруч із ним, коли його вразив радіаційний заряд. Ті чудові каштанові пасма волосся сипалися на підлогу цілими жмутами! Жмутами! Жах від усього цього лише посилився, коли Гноарн повністю злякався! О так, я кажу — злякався! Гноарн з недовірою доторкнувся до своєї лисої голови, а його погляд кричав про помсту, $N! Потім він спрямував свій гнів на трогів!$B$B<Оззі здригається.>",
},

[2928] = {
    en = "Gyrodrillmatic Excavationators",
    T = "Екскаватори «Gyrodrillmatic»",
    D = "Це жахливо, $N. У нас не вистачить запчастин, щоб доправити наш парк гіродрильматичних екскаваторів до Дун-Морога.$B$BНам потрібні запасні частини, $N. А де ще краще дістати запасні частини для наших машин, як не в Гномерегані? Я чув, що роботи та механічні машини бродять там, наче худоба на відкритих пасовищах.$B$BЯ хочу, щоб ти відправився до Гномерегана й розібрав тих роботів на частини. Принеси мені їхні внутрішні деталі. Двох десятків має вистачити.$B",
    O = "Принесіть двадцять чотири «Робомеханічні нутрощі» Шоні в Штормвінд.",
    P = "Якби це були перегони, ти б уже програв.",
    C = "Це підійде, $N. Один гіродрильматичний екскаватор відремонтовано; залишилося ще 398.",
},

[2929] = {
    en = "The Grand Betrayal",
    T = "Велика зрада",
    D = "Я довіряв Термаплаггу, $r. Ніколи не очікував, що він зрадить мене та весь народ гномів. І заради чого? Заради влади? Багатства? Усе це він би отримав з часом. А тепер нас вигнали з рідного дому, а цей божевільний стоїть біля керма. Король ніщо...$B$BМи відвоюємо Гномереган, $N. Ми не зупинимося, доки місто не повернеться під наш контроль. Якщо ти бажаєш приєднатися до нашої боротьби, я прошу тебе виконати одне просте завдання: вбий зрадника. Знищ Мекгінера Термаплагга.",
    O = "Відправляйтеся до Гномерегана і вбийте Мекгінера Термаплагга. Після виконання завдання поверніться до Головного майстра Меккаторка.",
    P = "Чи виконано завдання? Чи благав він про поблажливість? Про милосердя??",
    C = "Мені подобається думати, що останнє, що спало йому на думку, коли він впав на землю, — це твоя нога, $R. Тепер, коли Термаплагг мертвий, наші плани щодо відвоювання Гномерегана стали на крок ближчими до втілення.",
},

[2930] = {
    en = "Data Rescue",
    T = "Відновлення даних",
    D = "Коли ми втекли з Гномерегана, ми залишили там стільки даних! Надзвичайно важливих даних!$B$BМені потрібні дані з призматичної перфокарти, отримані з терміналу підвищеної безпеки «Matrix Punchograph 3005-D», що знаходиться в глибині Гномерегана. Ти повинен отримати доступ до терміналу, але для цього тобі спочатку потрібен допуск… а щоб його отримати, ти повинен отримати доступ до терміналів нижчого рівня безпеки — моделей -A, -B та -C. А для ЦЬОГО тобі потрібні перфокарти безпеки, починаючи з білої… а ми залишили всі перфокарти в місті.$B$BЦе катастрофа! Чи можете ви допомогти?",
    O = "Принесіть «Призматичну перфокартку» майстру-механіку Кастпайпу на Завод з переробки відходів Гномерегана в Дун-Морозі.",
    P = "У вас є призматична перфокартка??",
    C = "Ти це зробив! Ти знайшов призматичну перфокартку й відновив втрачені дані! Дані, що мають життєво важливе, вирішальне, неоціненне значення, без яких ми не змогли б прожити й миті!$B$BТвоя послуга гномам надовго залишиться в пам’яті, $N.",
},

[2931] = {
    en = "Castpipe's Task",
    T = "Завдання Castpipe",
    D = "Майстер-механік Кастпайп із Центру відновлення Гномерегана потребує допомоги шукачів пригод! Він формує загони для повторного проникнення до Гномерегана з метою виконання надсекретної та надзвичайно важливої місії з вилучення даних.$B$BКастпайп, можливо, і не є членом Просвітницької Асамблеї арканології, алхімії та інженерних наук, як я, але він все одно розумний гном, тож якщо він вважає це важливим, то, за моїми розрахунками, ймовірність того, що це справді важливо, становить вісімдесят чотири відсотки!$B$BЦе непогані шанси!",
    O = "Поговоріть із майстром-механіком Кастпайпом у Центрі відновлення Гномерегана в Дун-Морозі.",
    P = "",
    C = "Я організовую операції зі збору даних у Гномерегані. Якщо ви тут саме з цією метою, то слухайте уважно!",
},

[2932] = {
    en = "Grim Message",
    T = "Похмуре повідомлення",
    D = "Тролі Вітербарк колись були союзниками Орди, але вони зрадили Тралла... і за це їх треба покарати!$B$BОсь, візьми мою піку й вирушай до Замежжя, що лежить далеко на півночі. Ти знайдеш його на північний схід від Таррен-Мілл — селища, яке утримують наші союзники, Покинуті.$B$BКоли ти потрапиш у Глибинні землі, полюй на тролів Вітербарк. Зберіть їхні черепи та вбий мою піку в землю в одному з їхніх менших селищ — Хірі'вата або Зун'вата.$B$BПокажи їм, що їхні підлі вчинки мають наслідки!",
    O = "Зберіть черепи з Вітербарка та покладіть їх на спис Німбої. Покладіть «Навантажений спис Німбої» в одному з селищ Вітербарка в Глибинках, а потім поверніться до Німбої в Странглторні.",
    P = "Ти не виконав моє завдання, $N.",
    C = "До мене дійшла звістка про твій вчинок. Суворий вчинок, але гідний поваги. Сподіваймося, що Вітербарки прислухаються до твого послання.",
},

[2933] = {
    en = "Venom Bottles",
    T = "Пляшки «Веном»",
    D = "У цих пляшках міститься огидна зелена отрута.$B$BЗ огляду на кількість пляшок у цьому селі, Вітербарки, мабуть, вважають це дуже важливим. Можливо, аптекар із сусіднього Таррен-Мілл захоче отримати зразок.",
    O = "Віднесіть пляшку з отрутою до аптекаря в Таррен-Міллі.",
    P = "Привіт, шановний $C. День видався довгим, і жоден експеримент не вдався... Сподіваюся, ти принесеш мені гарні новини.",
    C = "А, а що це таке? Схоже, це отрута… від якоїсь павукоподібної істоти, як мені здається. А де ти її взяв?",
},

[2934] = {
    en = "Undamaged Venom Sac",
    T = "Непошкоджений отруйний мішок",
    D = "Мені потрібен свіжий зразок отрути, яку ти мені приніс. Павуки, з яких її було зібрано, напевно мешкають у Глибинних землях — полюй на них, доки не знайдеш неушкоджений отрутний мішок, і принеси його мені. Ви знайдете багато павуків поблизу міста тролів Шадра'Алор.$B$BНе зволікайте, $N, адже мішечок з отрутою має бути свіжим, коли ви його принесете.",
    O = "Принесіть неушкоджений отруйний мішок аптекарю Лайдону в Таррен-Міллі.",
    P = "У тебе є неушкоджений отруйний мішок, $N? Я дуже хочу провести експерименти зі свіжою отрутою і вже замовив колекцію маленьких, неймовірно милих тварин, на яких можна її випробувати!",
    C = "О, чудово! Отрута зовсім свіжа, і я впевнений, що вона дуже смертоносна. Дякую!",
},

[2935] = {
    en = "Consult Master Gadrin",
    T = "Зверніться до майстра Гадріна",
    D = "Отрута від охоронців виводку виявилася не такою сильною, як та, яку ти приніс спочатку. Мабуть, вона походила від іншого павука.$B$BМені потрібен свіжий зразок цієї отрути. Щоб з'ясувати, звідки він походить, тобі слід порадитися з тролем, який добре знає «В'янучу кору» — майстром Гадріном у селі Сен'джин. Подорожуй до Дуротара й поговори з Гадріном. Якщо пощастить, він знатиме, звідки «В'януча кора» бере свою отруту.",
    O = "Поговоріть із майстром Гадріном у селі Сен'джин.",
    P = "",
    C = "А, то ти хочеш свіжої отрути від павука з Вітербарків, так? Ну, сідай... тобі не сподобається те, що я тобі скажу.",
},

[2936] = {
    en = "The Spider God",
    T = "Бог-павук",
    D = "Вітербарки поклоняються богині-павуку, і саме від неї вони отримують найпотужнішу отруту. Тож якщо ти хочеш отримати отруту, тобі доведеться прикликати їхнього бога!$B$BДля цього тобі потрібно знати її справжнє ім'я, яке записано на табличці, похованій у Танарісі, у місті тролів Зул'Фаррак, у гробниці, яку охороняє мученик Тека.$B$BПереможіть Теку, знайдіть і прочитайте його табличку, щоб дізнатися ім’я богині-павука. Коли ви його дізнаєтеся, поверніться до мене.",
    O = "Прочитайте «Скрижаль Теки», щоб дізнатися ім’я бога-павука Вітербарка, а потім поверніться до майстра Гадріна.",
    P = "Чи знаєте ви, як звати бога-павука?",
    C = "Ах, Елорта-но-Шадра… вимовляй це ім’я лише пошепки, бо його проголошення має велику силу у царствах духу.$B$BЯ запишу його на пергаменті й створю для тебе заклинання на виклик…",
},

[2937] = {
    en = "Summoning Shadra",
    T = "Виклик Шадри",
    D = "Візьми його пергамент і прочитай його біля вівтаря Шадра’Алора, що знаходиться в глибині Царства В’ялої Кори в Замежжя. Це викличе Шадра — бога-павука.",
    O = "Переможіть Шадру біля вівтаря Шадра’Алора, а потім віднесіть її отруту аптекарю Лайдону в Таррен-Міллі.",
    P = "Ти взяв отруту?",
    C = "Супер, ти впорався!",
},

[2938] = {
    en = "Venom to the Undercity",
    T = "«Веном» у Підмісті",
    D = "Отрута, яку ти зібрав у павукового бога Вітербарка, — справжня знахідка! Мені вдалося вбити майже два десятки кроликів лише однією краплею цієї речовини. Звісно, деякі з тих кроликів були дуже молодими й такими маленькими, що вміщалися на долоні, тож я впевнений, що їхня стійкість до токсинів була низькою, але не можна заперечувати, що ця отрута є потужною!$B$BЯ хотів би, щоб зразок було надіслано моєму начальнику, аптекарю Фаранеллу в Аптекаріумі Підміста. Я впевнений, що він захоче випробувати його самостійно.",
    O = "Віднесіть посилку Фаранелла майстру-аптекареві Фаранеллу в Підмісті.",
    P = "Мені повідомили про твій приїзд, $N. У тебе для мене посилка?",
    C = "А, чудово. Лайдон згадав, що отрута в цій посилці — найпотужніша з тих, з якими йому доводилося мати справу, і зараз він активно працює над новими способами її застосування.$B$BЯкщо пощастить, ми знайдемо багато таких.$B$BДякую, $N. Ваша заслуга перед Королівським товариством аптекарів незаперечна.",
},

[2939] = {
    en = "In Search of Knowledge",
    T = "У пошуках знань",
    D = "Хоча руїни Фераласа можуть бути досить небезпечними, вони можуть багато розповісти про те, що тут сталося.$B$BКілька днів тому, обшукуючи уламки на півдні, я знайшов предмет, який, на перший погляд, схожий на звичайну палицю. Однак я ніяк не можу позбутися відчуття, що за цим стоїть щось більше. Ми з Анжелою ретельно вивчали наші книги, але нічого про це не знайшли.$B$BУ мене є колега в Дарнассі, яка, можливо, зможе пояснити нам, що це таке, $N. Чому б тобі не піти поговорити з нею і не дізнатися, чи зможе вона нам допомогти?",
    O = "Поговоріть з Дарином Лайтвіндом у селі Рут'теран.",
    P = "",
    C = "О, то Трояс Мунбріз тебе прислав?$B$B<бурмоче>...постійно набридає мені своїми дикими вигадками про те, що він знайшов щось важливе...$B$BСлухай, $N, скажу прямо. Трояс завжди вважає, що знайшов щось важливе в тих руїнах. Правда в тому, що все, що було справді цінним, ймовірно, вже давно приховали огри чи гарпії, які зараз там мешкають.$B$BМожеш, звичайно, оглянутись, але не знаю, чи знайдеш тут якісь книги, що тобі допоможуть.",
},

[2940] = {
    en = "Feralas: A History",
    T = "Фералас: Історія",
    D = "Схоже, цю книгу вже досить давно ніхто не відкривав. Обкладинка її досить зношена, а сторінки пожовклі, але, придивившись уважніше, ви помічаєте, що це, можливо, саме те, що шукає Трояс.$B$BВи берете її в руки, але розумієте, що, мабуть, слід спершу запитати дозволу, перш ніж позичати її.",
    O = "Запитайте Дарін Лайтвінд, чи можна у неї позичити книгу.",
    P = "",
    C = "Отже, ти хочеш взяти напрокат книгу «Фералас: Історія»?$B$BДай-но подумати...$B$BЯ дозволю тобі взяти цю книгу, $N, але тільки якщо ти спершу зробиш для мене одну послугу.",
},

[2941] = {
    en = "The Borrower",
    T = "Позичальник",
    D = "За своє життя я вивчав багато різних предметів, а останнім часом мене зацікавили «сніпджоу», які мешкають на пляжі в Гінтерленді. Є один екземпляр, якого я особливо хотів би побачити — гігантський «сніпджоу» на ім’я Гаммеріта. Я б із задоволенням поїхав туди сам, але мої дослідження тримають мене тут. Гадаю, її фотографія — це найкращий варіант після особистої зустрічі.$B$BВіднеси цей лист Кергл Кранкльхоп у Танарісі. Вона створила для мене пристрій, який дозволяє робити знімки. Гадаю, вона назвала його «знімком»...",
    O = "Віднесіть лист до Кергла Кранклхопа в Танарісі.",
    P = "Лист — для мене?",
    C = "Ти ще один із стажерів Дарін? Вона дуже обізнана історикиня, $N. Тобі слід бути вдячним за те, що ти навчаєшся під її керівництвом.$B$BА тепер дай-но я візьму «Super Snapper FX». Тобі це неодмінно сподобається!",
},

[2942] = {
    en = "The Morrow Stone",
    T = "Камінь Морроу",
    D = "У ту мить, коли артефакт виймають із Моноліту, ти відчуваєш, як енергія в Посоху Еквінекса починає згасати.",
    O = "Поверніть «Сяючий камінь» та «Посох Еквінекса» Троясу Мунбрізу в фортеці «Фетермун».",
    P = "Я радий, що ти повернувся, $N. З нетерпінням чекаю на твої висновки.",
    C = "Я читав, відколи ти пішов, $N. Цей камінь, який ти знайшов, називається «Каменем Морроу». Хоча я ще не до кінця впевнений, яке він має призначення, ти можеш бути впевнений, що це щось дуже важливе, якщо його так ретельно сховали всередині моноліту Еквінекс.$B$BЯ продовжуватиму свої дослідження і сподіваюся, що в майбутньому зможу розраховувати на тебе, $N. Дякую тобі за всю допомогу.",
},

[2943] = {
    en = "Return to Troyas",
    T = "Повернутися до Трояса",
    D = "Ось вона, $N. Будь ласка, подбай про мою книгу.$B$BА тепер поспішай. Я впевнений, що Трояс з нетерпінням чекає на твоє повернення.",
    O = "Передайте книгу Троясу Мунбрізу в фортеці Фетермун.",
    P = "Привіт, $N. Ти бував у Дарнассусі?",
    C = "Ти приніс із собою книжку. Чудово!",
},

[2944] = {
    en = "The Super Snapper FX",
    T = "Super Snapper FX",
    D = "Ось перший погляд на мій новий винахід, $N. Все, що тобі потрібно зробити, — це навести об’єктив на те, що хочеш сфотографувати, і натиснути кнопку.$B$BА що це за істота з Гінтерленду, про яку ти згадував? Гаммеріта? Ну, удачі вам у її пошуках. Я впевнений, що Дарін буде дуже задоволена знімком, який ви їй принесете.$B$BУ будь-якому разі, ось вам «Супер-Снапер». Бажаю приємного використання!",
    O = "Скористайтеся «Super Snapper FX», щоб зробити знімок Гаммеріти, а потім поверніться до Дарин Лайтвінд у селі Рут’теран.",
    P = "Отже, ти нарешті повернувся, $N. І приніс той пристрій, який Кергл збудував для мене — чудово.",
    C = "Ну що ж! Винахід Кергла виправдав всі сподівання.$B$BНе надто радійте, але знайте, що я задоволений вашою роботою, $N.$B$BА тепер, де ж я залишив ту книгу...",
},

[2945] = {
    en = "Grime-Encrusted Ring",
    T = "Обляпане брудом кільце",
    D = "Ви виявили на тілі одного з гномів Темного Заліза предмет, схожий на перстень. Однак важко визначити, що це за перстень: він повністю вкритий брудом і затверділими відкладеннями, що унеможливлює його носіння. Вам здається, що під нальотом ви розрізняєте легкий блиск дорогоцінного металу і, можливо, навіть відблиск дорогоцінного каменю.$B$BЯкщо ви збираєтеся скористатися цим перснем, вам доведеться знайти щось, щоб видалити з нього затверділий наліт.",
    O = "Придумайте спосіб, як очистити від бруду кільце, вкрите нальотом.",
    P = "На гномському пристрої, що стоїть перед вами, висить табличка з написом «Sparklematic 5200». Суть роботи машини, судячи з інструкції під табличкою, полягає в тому, щоб відчистити предмет від бруду. Машина має отвір для монет, який приймає три срібні монети для запуску процесу після того, як предмет буде поміщений всередину.$B$BЗдається, що обляпане брудом кільце, яке ви знайшли раніше, — саме те, що треба випробувати в цій машині!",
    C = "Ви кладете кільце всередину «Sparklematic 5200» і вкидаєте срібну монету в щілину.$B$BЗ машини лунають болісні скрегочучі звуки, і вона починає різко трястися. Можна лише здогадуватися, що відбувається з кільцем усередині машини...$B$BМашина раптово зупиняється, сповіщаючи про це простим «Дінг!» Відсік для предметів відкривається, і в ньому з’являється маленька коробочка, акуратно обв’язана червоною стрічкою. Схоже, Sparklematic 5200 ще й упаковує подарунки!",
},

[2946] = {
    en = "Seeing What Happens",
    T = "Подивитися, що буде далі",
    D = "Ми хочемо, щоб ви віднесли знайдені мініатюрні диски до запечатаних воріт Ульдума. Ми... ми не впевнені, що станеться, коли ви це зробите.$B$BЗвісно, це звучить ризиковано, ми це визнаємо. Однак, можливо, нічого й не станеться. Можливо, вам доведеться застосувати диски до чогось. Можливо, ворота відчиняться, коли диски опиняться у вашому розпорядженні. Будьте готові спробувати будь-що і до будь-яких поворотів подій.$B$BКоли ви з’ясуєте, що відбувається, поверніться до Айронфорджа. Коли ви закінчите, нам буде що проаналізувати!",
    O = "Віднесіть мініатюрні платинові диски до воріт Ульдума в Танарісі та пошукайте підказки щодо зв’язку між ними.",
    P = "Цей знайомий на вигляд п'єдестал стирчить із гарячого піску. Можливо, його присутність тут має якесь значення...",
    C = "Як тільки ти торкаєшся п’єдесталу, мініатюрні диски з Улдамана починають гудіти й світитися у твоєму рюкзаку. Звичне відчуття мурашок пробігає по твоїх руках, коли перед воротами Улдума оживає образ ще одного Кам’яного Спостерігача.$B$B«Вітаю. Я — охоронець входу. У дисках, які ви використовували для доступу, бракує необхідних для входу дисків — Плиток Ульдума. Будь ласка, вставте ці плитки у структуру дисків і повторіть послідовність доступу. Дякую.»",
},

[2947] = {
    en = "Return of the Ring",
    T = "Повернення Персня",
    D = "Відкривши коробку, виготовлену на Sparklematic 5200, ви побачите те, що й припускали, — блискучу обручку! Одягнувши обручку, ви відчуєте, як магічна сила пронизує ваше тіло.$B$BЗсередини обручки видно невеликий, але все ж чіткий відбиток печатки Айронфорджа. Поруч з ним вигравірувані три маленькі ініціали: «TdK». Це можуть бути ініціали попереднього власника або, можливо, ініціали майстра, який виготовив перстень. Зберегти перстень… чи повернути його цій людині. Вибір, вибір…",
    O = "Ви можете або залишити обручку собі, або знайти особу, відповідальну за відбиток та гравіювання на внутрішній стороні обручки.",
    P = "Гей, спокійніше, друже — я дуже важливий бізнесмен! Я впевнений, що кур’єр просто запізнюється з доставкою орендної плати... зачекай... ти ж не мій орендодавець.$B$BНу, звісно, що ні — який я дурний! Ти прийшов до мене, шукаючи найкращого ювеліра в усьому Айронфорджі, такого, який НЕ виготовляє ПРОКЛЯТІ предмети! Так!$B$BЕ-е-е… що тобі потрібно?",
    C = "Кажеш, перстень? Давай подивимося... так, це я його зробив, хай йому грець.$B$BДо того, як Гномереган був зруйнований, у мене там була невеличка крамниця. Можливо, це той, який я залишив, коли тікав у гори; він простий за дизайном, і я зробив кілька таких. Може, це від когось, хто не встиг втекти.$B$BЦе було у карликів Темного Заліза? Ну, це додає ще один шар змови до тих дев’яти, що вже ходять у повітрі. Може, владі було б цікаво про це дізнатися; для таких, як я, це марна трата часу.$B$BА тепер повернемося до персня...",
},

[2948] = {
    en = "Gnome Improvement",
    T = "Удосконалення Gnome",
    D = "Послухай $n, цей перстень, звісно, твій... але я можу зробити тобі кращий! Цей дизайн, як я вже казав, справді простий. Зараз я набагато вправніший, і за скромну плату в тридцять срібних монет я його для тебе прикрашу! Ну, насправді трохи більше, ніж тридцять... $B$BЯ зараз у скрутному становищі; у мене зовсім закінчилися матеріали. Якщо ти принесеш мені срібний зливок і моховий агат, я додам до персня срібну та агатову решітку, яка додасть йому трохи більше шарму! $B$BПовір мені!",
    O = "Принесіть блискуче золоте кільце, срібний зливок, моховий агат та 30 срібних монет Талвашу дель Кісселю в Айронфорджі.",
    P = "У вас є ті матеріали, які мені потрібні? Я б не просив вас про них, якби мені не пощастило...",
    C = "Ах, саме те, що мені було потрібно! Одного дня, коли я виберуся з цієї ями, в яку мене несправедливо закинули, я зроблю для тебе, для ВСІХ — найкращі прикраси в усьому Азероті! А до того часу — дякую, що так терпляче поставився до питання з реагентами. Зазвичай я беру вдесятеро більше, ніж я взяв з тебе за перстень такої якості... $B$BДо речі, про персні — ось твій новий!",
},

[2949] = {
    en = "Return of the Ring",
    T = "Повернення Персня",
    D = "Відкривши коробку, виготовлену на Sparklematic 5200, ви побачите блискуче кільце! Одягнувши кільце, ви відчуєте, як магічна сила пронизує ваше тіло.$B$BНа внутрішній стороні обідка є невеликий, але все ж помітний відбиток печатки Оргримара. Поруч вигравірувані літери, але навіть після очищення виразно видно лише перші три: «NOG...»$B$BЦе можуть бути або ініціали попереднього власника, або, можливо, ініціали майстра, який виготовив перстень. Зберегти перстень... чи знайти «NOG» — вибір, вибір...",
    O = "Ви можете або залишити обручку собі, або знайти особу, відповідальну за відбиток та гравіювання на внутрішній стороні обручки.",
    P = "Можна було б подумати, що ми самі знайдемо спосіб перевершити тих брудних маленьких гномів. Я навіть готовий побитися об заклад, що вони спочатку вкрали цю установку у нас! Фу, ці жирні, брудні... е-е-е, так? Тобі щось потрібно?",
    C = "Кільце з Гномерегана? Подивимося… Не моє, але цікаво.$B$BЦя історія з Гномереганом — кращої групи тупих голів для цього й не можна було б знайти. Роками вони були посміховиськом, а тепер майже за одну ніч роблять кращу екіпіровку, ніж ми?$B$BУ карликів Темного Заліза був той перстень? Це ще цікавіше! Знаєш, може, гноми вкрали їхні божевільні плани щодо големів і модифікували їх. Ті Темнозалізні — вони точно захочуть серйозної помсти. Це, безперечно, варто розслідувати.$B$BЗнаєш, щодо того кільця...",
},

[2950] = {
    en = "Nogg's Ring Redo",
    T = "Переробка кільця Ногга",
    D = "Ні, ні, ні — я ж не кажу, що це кільце раптом стало моїм. Зазвичай я так не роблю, але твоя інформація про Темних Залізних виявилася дуже корисною. Я вдосконалю твоє кільце — краще, ніж це міг би зробити той, хто виготовив цю просту дрібничку. Мабуть, якийсь гном...$B$BЯкщо ти принесеш мені срібний зливок, моховий агат і тридцять срібних монет за мою працю, я додам до кільця срібну та агатову решітку, яка посилить магію всередині нього. Цікаво?",
    O = "Принесіть «Блискуче золоте кільце», срібний зливок, моховий агат і 30 срібних монет Ноггу в Оргримарі.",
    P = "У вас є матеріали, які мені потрібні? Я не зможу вдосконалити цей дизайн, не маючи всього, про що я просив.",
    C = "Ось твоє кільце — воно краще, ніж раніше. Ще раз дякую за інформацію про тих карликів з племені Темного Заліза. Це здається цілком правдоподібною версією того, як ті гноми раптом надихнулися гоблінами.",
},

[2951] = {
    en = "The Sparklematic 5200!",
    T = "Sparklematic 5200!",
    D = "Цей пристрій виділяється серед гномів, які чинять опір божевіллю за межами кімнати. На невеликій табличці на пристрої написано «Sparklematic 5200», а далі йде текст: $B$B «Бруд і наліт псують ваші блискучі речі? Sparklematic 5200 поверне вашим коштовностям їхній блиск! Вставте предмет, який хочете почистити, та вкиньте три срібні монети у монетний отвір. Дайте Sparklematic 5200 трохи часу на роботу — і ось! Ваші коштовності вийдуть чистими та блискучими!»",
    O = "Вставте забруднений предмет у «Sparklematic 5200» і не забудьте підготувати три срібні монети, щоб запустити пристрій.",
    P = "Схоже, що для роботи цього пристрою потрібний якийсь забруднений предмет, який потрібно очистити, та три срібні монети, щоб запустити цей пристрій. Якщо обидва ці елементи є, Sparklematic 5200 має працювати...",
    C = "Ви вставляєте заляпаний брудом предмет і три срібні монети в «Sparklematic 5200». Машина оживає, шалено намагаючись очистити невідомий предмет від бруду. З самого серця машини доносяться гучні, бурхливі звуки перемішування. Металевий каркас цієї «бестії» скрипить і стогне, коли вона хитається з боку в бік...",
},

[2952] = {
    en = "The Sparklematic 5200!",
    T = "Sparklematic 5200!",
    D = "",
    O = "",
    P = "",
    C = "Так само раптово, як і запустилася, машина «Sparklematic 5200» різко зупиняється. З машини лунає простий «дзвін», і її отвір спірально піднімається вгору. Усередині «Sparklematic 5200» лежить маленька коробка, обв’язана маленьким бантиком. Схоже, машина спочатку очищає предмет від бруду, а потім обгортає його. Навіть якщо машина не спрацювала, принаймні предмет тепер загорнутий у гарну коробку.$B$BЩо ж, є один спосіб дізнатися, чи очистила вона предмет, чи ні...",
},

[2953] = {
    en = "More Sparklematic Action",
    T = "Ще більше пригод зі Sparklematic",
    D = "",
    O = "",
    P = "Sparklematic 5200 порожній — чекає на забруднений предмет, який потрібно почистити, та три срібні монети, щоб запустити його!",
    C = "«Sparklematic 5200» оживає, хитаючись туди-сюди. Всередині безпорадна бруд, що в’ївся в предмет, поміщений у машину, подрібнюється гномівським миючим засобом.$B$B«Sparklematic 5200» зупиняється, про що сповіщає знайомий звук «дінг!». Відсік для предметів машини відкривається спіральним рухом, відкриваючи огляд на акуратно загорнуту коробку.",
},

[2954] = {
    en = "The Stone Watcher",
    T = "Кам’яний спостерігач",
    D = "«Вітаю. Я — охоронець входу. Якщо ви ще не інтегрували «Пластини Улдума» у свій набір дисків, я не дозволю вам увійти на територію Улдума».$B$BПоява Кам’яного Стража Норганнона, мабуть, і є тією реакцією, на яку розраховували, відправляючи вас із платиновими дисками в пустелю Танаріс. Згідно з інструкціями, вам потрібно з’ясувати, яка історія стоїть за Кам’яним Стражем, перш ніж рухатися далі.",
    O = "Дізнайтеся про призначення «Кам’яного сторожа Норганнона», а потім взаємодійте з «П’єдесталом Улдума» в пустелі Танаріс.",
    P = "Перш ніж продовжувати, слід дізнатися, у чому полягає мета «кам’яного спостерігача»...",
    C = "Голос кам’яного сторожа лунає потужно й владно:$B$B«Ваші диски будуть повернуті вам, щойно ви отримаєте доступ до п’єдесталу. Коли ви отримаєте Плити Ульдума та включите їх до свого існуючого набору дисків, ви зможете увійти до комплексу».",
},

[2962] = {
    en = "The Only Cure is More Green Glow",
    T = "Єдиний засіб — це ще більше зеленого сяйва",
    D = "Ваш зразок був не тільки недостатнім за кількістю, але й нечистим.$B$BНам потрібно більше зеленого світіння. Троги, очевидно, недостатньо опромінені, щоб задовольнити наші потреби. Вам доведеться зайти до Гномерегана й принести трохи радіоактивного осаду — прямо з джерела. Я маю на увазі опромінених слимаків, причаїльників та жахів. Майте на увазі: утримати цей тип осаду досить складно. Можливо, вам доведеться зробити кілька спроб із флаконом, поки не вдасться отримати придатний зразок.",
    O = "Відправляйтеся до Гномерегана та принесіть звідти високоактивний радіоактивний осад. Майте на увазі: осад нестабільний і досить швидко розсиплеться.$B$BПісля виконання завдання Оззі також попросить вас надати флакон із колекцією важкого свинцю.$B",
    P = "Хм, ти не світишся. Це хороший знак.",
    C = "<Оззі оглядає тебе.> Вражаюче, у тебе ще всі кінцівки на місці. А тепер час подивитися, на що здатна ця штука!",
},

[2963] = {
    en = "Portents of Uldum",
    T = "Ознаки Улдума",
    D = "Ще раз вітаю, $n! Твоє відкриття в Улдамані викликало справжній ажіотаж у Лізі дослідників. Ліга активно працює над розгадкою таємниць мініатюрних платинових дисків, які ти знайшов. Ваше щасливе прибуття сюди, до Залу, дає мені змогу повідомити вам, що, цілком ймовірно, ми натрапили на щось важливе!$B$BІсторик Карнік виявив кілька важливих підказок щодо справжнього походження Долини Спостерігачів у пустелі Танаріс. Він хотів би поговорити з вами якомога швидше!",
    O = "Поговоріть з істориком Карніком у Залі дослідників у Айронфорзі.",
    P = "",
    C = "Я радий, що ти й досі цікавишся дослідженнями, $N! З твоїм природним талантом і сміливістю ми зможемо розкрити таємниці, про які раніше навіть не мріяли!$B$BДиски Норганнона в Улдамані були сховищем величезного обсягу інформації; тобі було дозволено отримати доступ лише до, так би мовити, верхніх шарів інформації, що там зберігалася. Ходили чутки, що Творці мають ще більше сховищ, розташованих по всьому Азероту. Це приводить нас до Улдума...",
},

[2964] = {
    en = "A Future Task",
    T = "Завдання на майбутнє",
    D = "Ну, $n... схоже, ми тимчасово зайшли в глухий кут. Ми знаємо, що нам потрібно — Плити Ульдума — але не маємо уявлення, де вони можуть бути. Нам доведеться докласти чимало зусиль, щоб розробити надійний план дій. У мене є кілька ідей, з чого почати пошуки; я дуже сподіваюся, що незабаром ми попросимо тебе вирушити на пошуки й повернути їх.$B$BПро це потрібно повідомити Верховного Дослідника, $n; без сумніву, він також захоче особисто подякувати вам за те, що ви вкотре допомогли Лізі.",
    O = "Поговоріть із Великим мандрівником Магелласом в Айронфорзі.",
    P = "",
    C = "Тож ми всі згодні — найкращий план дій — це відкласти цю справу, доки ми не зможемо звузити коло пошуку місць, де ці пластини можуть бути заховані. Ти привів нас аж сюди $n, і я сподіваюся, що саме ти повернешся на місце подій, щоб відкрити Улдум для нас усіх!$B$BДозвольте мені тим часом виплатити тобі гонорар; цього має вистачити на покриття всіх витрат, які ти поніс, допомагаючи нам, а також на невеличку надбавку. Обов’язково незабаром зв’яжися з нами… Ульдум кличе!",
},

[2965] = {
    en = "Portents of Uldum",
    T = "Ознаки Ульдума",
    D = "Ах, $n, як добре, що ти знову завітав до мене. Твої відкриття на місці розкопок в Улдамані, безперечно, дали нам, мудрецям, чимало приводів для обговорення. Я саме це й робив разом з однією з друїдів, Нарою Вайлдмейн, коли до мене дійшло, що її минулі пригоди можуть мати велике значення для наступного кроку, який нам потрібно зробити.$B$BЯ хотів би, щоб ти поговорив з нею про її подорожі до Долини Спостерігачів у пустелі Танаріс. Вона чекає на тебе на Скелі Старших.",
    O = "Поговоріть з Нарою Вайлдмейн на Пагорбі Старших у Громовому Утворі.",
    P = "",
    C = "Глибоко в пустелі Танаріс є місце, яке називається Долиною Спостерігачів. На дисках, які ви знайшли... у перекладі їхніх символів згадується місце під назвою Улдум. Більшість вважає це місце міфом.$B$BЯ знаю, що це неправда; Ульдум існує. Я там був. Ну... принаймні, зовні.$B$BСуть у тому, $N: ми вважаємо, що між дисками та Ульдумом існує зв’язок, і хочемо, щоб ти поїхав туди.",
},

[2966] = {
    en = "Seeing What Happens",
    T = "Подивитися, що буде далі",
    D = "Мудрий Шукач Істини та я хотіли б, щоб ви віднесли знайдені мініатюрні диски до запечатаних воріт Улдума. Ми… ми не впевнені, що станеться, коли ви це зробите.$B$BЗвісно, це звучить ризиковано, і ми це визнаємо. Однак, можливо, нічого й не станеться. Можливо, вам доведеться застосувати ці диски до чогось. Можливо, ворота відчиняться, коли диски опиняться у вашому володінні. Будьте готові спробувати будь-що і будьте готові до будь-яких подій.$B$BДізнайтеся все, що зможете, а потім поверніться до мене. Нам буде про що поговорити.",
    O = "Віднесіть мініатюрні платинові диски до воріт Ульдума в Танарісі та пошукайте підказки щодо зв’язку між ними.",
    P = "Цей знайомий на вигляд п'єдестал стирчить із гарячого піску. Можливо, його присутність тут має якесь значення...",
    C = "Як тільки ти торкаєшся п'єдесталу, мініатюрні диски з Улдаману починають гудіти й світитися у твоєму рюкзаку. Знайоме відчуття поколювання охоплює твої руки, а перед воротами Улдума оживає образ ще одного Кам'яного Стража.$B$B«Вітаю. Я — охоронець входу. У наборі дисків, які ви використовували для входу, бракує необхідних дисків — Плит Ульдума. Будь ласка, вставте ці плити в систему дисків і повторіть послідовність дій для входу. Дякую.»",
},

[2967] = {
    en = "Return to Thunder Bluff",
    T = "Повернутися до Громового Утюгу",
    D = "Ви знову підходите до п'єдесталу; платинові диски раптово знову з'являються у вашому рюкзаку.$B$BОтримавши знання від кам'яного спостерігача та повернув диски у своє володіння, настав час повернутися до Громового Утвору та повідомити Нару Вайлдмейна про ваше відкриття.",
    O = "Поговоріть з Нарою Вайлдмейн у Громовому Утворі.",
    P = "З поверненням, $N. Тобі вдалося використати диски на свою користь, чи все виявилося марним?",
    C = "У вас не вистачало кількох дисків? Цікаво, що, судячи з усього, диски Норганнона — це лише частини повного набору, як, скажімо, ключі на кільці для ключів.$B$BЯкщо нам вдасться знайти Плити Улдума, то ми зможемо отримати доступ до самого комплексу Улдума. Не знаю, чи радіти цій перспективі, чи жахатися.$B$BМожливо, нам доведеться ризикнути всім, щоб ті таємниці, які зберігає земля і які можуть знищити нас усіх, залишилися саме тим — таємницями.",
},

[2968] = {
    en = "A Future Task",
    T = "Завдання на майбутнє",
    D = "Ну що ж, $n... схоже, ми опинилися в неприємному глухому куті. Ми знаємо, що нам потрібно — Плити Ульдума — але не маємо жодного уявлення, де вони можуть бути. Ми дослідимо це питання, а потім розробимо надійний план дій. У мене є кілька ідей, з чого почати пошуки; Я дуже сподіваюся, що незабаром ми попросимо тебе знову приєднатися до наших зусиль з пошуку істини.$B$BПро це потрібно повідомити Мудреця-Шукача Істини, $n; без сумніву, він також хоче особисто подякувати тобі за те, що ти вкотре відгукнувся на заклик.",
    O = "Поговоріть із Сейджем Трутсікером у Громовому Утвірі.",
    P = "",
    C = "Тож ми всі згодні — найкращий варіант — це почекати, доки ми зможемо звузити коло пошуку місць, де ці пластини можуть бути заховані. Ти привів нас аж сюди $N, і я сподіваюся, що саме ти повернешся на місце подій, щоб розгадати таємниці Ульдума.$B$BА поки що дозволь мені вручити тобі цю винагороду; вона має покрити всі витрати, які ти поніс, допомагаючи нам, а також стати невеликим додатковим бонусом. Не забудь незабаром зв’язатися з нами… Улдум кличе нас усіх, юний друже.",
},

[2969] = {
    en = "Freedom for All Creatures",
    T = "Свобода для всіх істот",
    D = "Мерзенний клан Грімтотем викрадає феєричних драконів, $N. Джер’кай і я не маємо уявлення, що вони збираються з ними робити, але очевидно, що вони замишляють щось недобре.$B$BМи не достатньо сильні, щоб прорватися до табору й звільнити полонених драконів, але, можливо, з вашою допомогою...$B$BЯкщо ти готовий і маєш сильних друзів, випусти цих істот із клітки за допомогою цього ключа та подбай, щоб вони втекли живими. Я весь час буду поруч із тобою. Джер’кай залишиться тут.",
    O = "За допомогою «Ключа від бамбукової клітки» звільніть «Спрайт-Дартерів» із загону в таборі «Грімтотем». Повинно вижити щонайменше 6 «Спрайт-Дартерів» та Кіндал Місячний Ткач.$B$BУ вас є 6 хвилин, перш ніж Кіндал вирішить, що настав час відступати, і ви провалите квест.",
    P = "Ми не можемо дозволити клану Грімтотем знищити цих прекрасних істот. Їх треба звільнити з полону!",
    C = "Дякую Елуні, $N! Ти — велике благословення для нас і для драконів, яких ти врятувала. Ми з Джер'каєм ніколи б не змогли самостійно допомогти драконам — ми завжди пам'ятатимемо твоє втручання у справи «Грімтотемів».$B$BПоговори з Джер'каєм зараз... Мені треба підготуватися до нашої помсти. Те, що феєричні дракони звільнилися, ще не означає, що вони залишаться на волі. Тепер ми з Джер'каєм перейдемо в наступ.",
},

[2970] = {
    en = "Doling Justice",
    T = "Відправлення правосуддя",
    D = "Як вона вам уже казала, Кіндал і я тепер візьмемося за Грімтотемів. Разом нам все ще вдасться знищити частину тауренів, не наражаючись на велику небезпеку, але ми були б раді допомозі, якщо ви готові й маєте таку можливість.$B$BВи бачили табір під нами, але на сході є ще й інші. Використовуючи власну тактику, завдайте тауренам якомога більше шкоди. Ми всі зможемо зустрітися тут знову, коли вони відчують на собі силу стріл Кіндал та вашої зброї.",
    O = "Вбийте 12 натуралістів «Грімтотем», 10 нападників «Грімтотем» та 6 шаманів «Грімтотем», а потім поверніться до Джер’каї Міунвівер у Фераласі.",
    P = "Кіндалу потрібен час на підготовку, але ми вже вбили десятки супротивників. Клан «Грімтотем» чудово знає про нашу присутність у цьому районі й вистежує нас, наче гадюки.$B$BВони зроблять усе, що в їхніх силах, аби відрубати нам голови. Тобі слід бути насторожі… тепер, коли ти втрутився, вони прийдуть і за тобою.",
    C = "Кіндал мав рацію щодо тебе, $N — у тебе справді є хист до цього. Ти досвідченіший мандрівник, ніж ми обоє, і за це ми тобі вдячні.$B$B Клан Грімтотем набагато ворожіший, ніж більшість тауренів... Цікаво, чи їхні ж родичі засуджують їхні вчинки. Я б не здивувався. Як ти, мабуть, знаєш, багато рас в Азероті мають зв’язки з менш доброзичливими представниками своїх видів.$B$BАле це тема для іншої розмови.",
},

[2972] = {
    en = "Doling Justice",
    T = "Відправлення правосуддя",
    D = "Тут, у дикій місцевості, у нас з Кіндалом мало що є, щоб віддячити тобі за допомогу, але ми не хочемо, щоб ти відчував себе недооціненим. Візьми мій перстень із печаткою. Якщо колись опинишся серед гілок Телдрасіля, зазирни до Храму Місяця в самому серці Дарнасуса. Там ти зустрінеш мою Верховну Жрицю Тиранду Шепот Вітру. Перстень дасть їй знати, що ми в порядку, і підтвердить правдивість твоєї розповіді.$B$BМи обоє дякуємо тобі, $N.",
    O = "Віднесіть перстень з печаткою Джер'каї верховній жриці Тиранді Шепотвітру в Дарнассусі.",
    P = "Привіт, дитино. Ми раді, що до нашого храму завітали ще сильніші мандрівники. Якщо у тебе є час, чи не могла б ти розповісти молодшим мандрівникам одну-дві історії? Я знаю, що багатьом із них твоя мудрість стане у нагоді.$B$BВибач, поглянь, яка я нечемна. Ти прийшов до Храму, шукаючи нашої допомоги, а я наважився на тебе налягати. Будь ласка, пробач мені. Скажи, чим слуги Світла можуть тобі допомогти.",
    C = "Це дивовижна історія, $N. Нам приємно, що ти допоміг не лише драконам, а й одній із наших жриць. Джер’кай мав рацію, відправивши тебе до мене. Я подбаю, щоб їй повернули перстень — мої розвідники незабаром вирушать у бік Фераласа. Це буде ще одне завдання, яке вони зможуть виконати під час своєї місії.$B$BЩе раз дякую, і, будь ласка, почувайся тут як вдома.",
},

[2973] = {
    en = "A New Cloak's Sheen",
    T = "Блиск нового плаща",
    D = "Радий бачити тебе, $c. Я разом зі своїми супутниками вирушив до Фераласу з дорученням від наших господарів з Оргримара.$B$BМоя супутниця життя Коррін дуже любить новий одяг, тож я маю намір зшити їй новий плащ, прикрашений тонким, як павутинка, крилами феєричних драконів. Чи не могли б ви мені допомогти? Спрайтові стрільці з чудовими крилами, які мені потрібні, мешкають на захід від табору Моджаче.",
    O = "Принесіть 10 крил райдужного спритного дартера Крюгу Скаллспліттеру в таборі Моджаче.",
    P = "Спрайт-дартери можуть бути небезпечними створіннями, якщо їх спровокувати. Будьте обережні у спілкуванні з ними, $C. І будьте ще обережнішими щодо нічних ельфів, які можуть бути в цій місцевості. Ці набридливі дурні також зазвичай ховаються в лісах.$B$BКоли ти назбираєш достатньо крил, дай мені знати — я обов'язково щедро тебе винагороджу!",
    C = "Чудово, $C! Це якраз те, що треба. Тут вистачить, щоб зшити плащ для Корріна, а може, навіть і більше! Дякую.$B$BСподіваюся, подорож не була надто небезпечною? Околиці Фераласу не славляться своєю гостинністю, але ти, очевидно, впорався досить добре.$B$BЩе раз дякую, $C.",
},

[2974] = {
    en = "A Grim Discovery",
    T = "Жахливе відкриття",
    D = "Що!? Ти натрапив на тауренів у цих краях? Ти жартуєш! Як вони виглядали!?$B$BКлан Грімтотем! Ти знайшов декого з них? Белгром, один із наших повелителів, цікавиться їхнім родом... він навіть оголосив на них нагороду.$B$BТи мусиш повернутися, $c. Повертайся і принеси мені їхні роги... цілу купу, якщо зможеш. З «Грімтотемами» не можна жартувати чи недооцінювати їх. Повертайся і знищ їх; нехай річки у Фераласі забарвляться в червоний колір їхньою темною кров’ю.",
    O = "Принесіть 20 рогів Грімтотема Крюгу Черепорозбивачу в табір Моджаче.",
    P = "Повір мені на слово, $C, клан Грімтотем — це зло. Якщо ти з’ясував, де вони перебувають, то саме тобі належить повернутися й завдати першого удару по їхньому клану… перш ніж вони вторгнуться на наші землі, спалять наші села чи розграбують наші володіння.",
    C = "Це чудові роги, $C. Молодець. Я візьму їх у тебе і обов’язково передам Бельгрому, щойно ми повернемося до Оргримара. Ти вже двічі мені допоміг, і за це отримуєш мій знак. Можливо, колись я зможу допомогти тобі! Бажаю тобі удачі.",
},

[2975] = {
    en = "The Ogres of Feralas",
    T = "Огри Фераласа",
    D = "Вплив племені огрів Гордунні навряд чи можна не помітити в цій місцевості. Поглянь навколо, $N; сама їхня присутність залишає шрами на цій землі. Ми мусимо відкинути їх назад, перш ніж вони ще більше просунуться вглиб Фераласу.$B$BЙди вздовж річки на північ, і ти знайдеш їхній аванпост. Зменш їхню чисельність, $N. Ми мусимо показати їм, що їх тут не чекають.",
    O = "Рок Орхан у таборі Моджаче просить вас вбити 10 гордюннських огрів, 10 гордюннських огрів-магів та 5 гордюннських брутів.",
    P = "Дій швидко, $N. Чи, може, завдання, яке я тобі доручив, виявилося занадто складним?",
    C = "Чудово, $N. З часом земля відновиться. Ми не повинні здаватися.",
},

[2976] = {
    en = "A Grim Discovery",
    T = "Жахливе відкриття",
    D = "Що?!$B$BА, так я ж згадував про винагороду, чи не так? Ну що ж, це мені буде уроком, щоб не розпускати язика, чи не так?$B$BТи виконав роботу, тож, гадаю, цілком справедливо, що саме ти отримаєш за це найбільшу винагороду. Забирай роги, я накажу покласти їх у ящик для тебе. Знайди Белгрома Рокмаула в Долині Честі — він захоче дізнатися, що ти бачив, і винагородить тебе за твою важку працю.$B$BБудь здоровий, $c, і ще раз дякую за все, що ти зробив.",
    O = "Віднесіть ящик з рогами Грімтотема до Белгрома Рокмаула в Оргримарі.",
    P = "Поспішай, $C, мені сьогодні ще багато чого треба встигнути.",
    C = "Грімтотем!? Цікаво. Ти кажеш, що натрапив на них під час полювання у Фераласі? Справді?$B$BМої товариші захочуть почути твої новини, $C. Розкажи мені докладніше, а я тим часом відрахую тобі гроші.$B$BІ перш ніж ти підеш, знай, що я вдячний тобі за інформацію, яку ти мені сьогодні передав.",
},

[2977] = {
    en = "Return to Ironforge",
    T = "Повернутися до Айронфорджа",
    D = "Ви знову підходите до п'єдесталу; платинові диски раптово знову з'являються у вашому рюкзаку.$B$BОтримавши знання від кам'яного спостерігача та повернув диски у своє володіння, настав час повернутися до Айронфорджа та повідомити Лігу дослідників про ваше відкриття.",
    O = "Поговоріть з істориком Карніком у Айронфорджі.",
    P = "З поверненням, $n. Тобі вдалося використати диски на свою користь, чи це виявилося марною тратою часу?",
    C = "У вас не вистачало кількох дисків? Цікаво, що, судячи з усього, диски Норганнона — це лише частини повного набору, як, скажімо, ключі на кільці для ключів.$B$BЯкщо нам вдасться знайти Плити Улдума, то ми зможемо отримати доступ до самого комплексу Улдума! Уявіть собі, що ви зможете дослідити місце, де працювали Творці, не беручи з собою величезну лопату!$B$BНе те щоб у лопатах було щось погане… або в копанні…",
},

[2978] = {
    en = "The Gordunni Scroll",
    T = "Сувій Гордунні",
    D = "Піднявши забруднений сувій, ти помічаєш, що на ньому, схоже, зображено якусь зустріч чи церемонію. Рок Орхан зацікавився б цим сувоєм і тим, що він може означати для Гордунні.",
    O = "Принесіть сувій Гордунні Року Орхану в табір Моджаче.",
    P = "Що це таке?",
    C = "Цей сувій... Ти знайшов його на аванпості Гордунні?",
},

[2979] = {
    en = "Dark Ceremony",
    T = "Темна церемонія",
    D = "Схоже, це плани якогось темного обряду, $N. З того, що я можу зрозуміти, цей ритуал проводять маги-лорди Гордунні.$B$BЗнайдіть одного з цих магів-лордів і візьміть у нього кулю.$B$BКуля мага містить велику силу і допоможе нам дізнатися більше про цей обряд та магію, якою володіють Гордунні.",
    O = "Рок Орхан у таборі Моджаче просить вас знайти Сферу Гордунні.",
    P = "Ми маємо дізнатися більше про те, чому Гордунні опинилися тут, $N.",
    C = "Ця куля надасть нам більше інформації про Гордунні... яку ми потім використаємо для планування їхньої поразки, $N.",
},

[2980] = {
    en = "The Ogres of Feralas",
    T = "Огри Фераласа",
    D = "Тепер, коли ти довів, що є справжнім бійцем, я вірю, що в тебе вистачить мужності продовжити виконання поставленого завдання.$B$BВідправляйся до Високої Пустелі, що на південний захід від цього місця. Там, на землі, яка колись належала нічним ельфам, розташовані кілька покинутих і зруйнованих споруд. Шукай ці руїни, і коли побачиш засохлі дерева та сплюндровану місцевість, ти знайдеш Гордунні. Відкинь їх назад.$B$BЦі огри набагато сильніші за тих, з якими ти стикався раніше, $N. Будь обережним.",
    O = "Рок Орхан у таборі Мохаче просить вас вбити 10 шаманів Гордунні, 10 чаклунів Гордунні та 5 розбійників Гордунні.",
    P = "Ти вже знайшов руїни, $N?",
    C = "Ти довів, що є надійним і вірним союзником, $N.",
},

[2981] = {
    en = "A Threat in Feralas",
    T = "Загроза у Фераласі",
    D = "Фералас — ідеальне місце для досвідченого $c, щоб довести свою $Ghimself:herself;. Плем’я огрів під назвою Гордунні є там головною військовою силою, і їхня чисельність постійно зростає. Їх потрібно зупинити, перш ніж вони стануть загрозою для нашої присутності у Фераласі.$B$BУ таборі Моджаче у Фераласі мешкає воїн на ім’я Рок Орхан, якого я знаю; зверніться до неї. Вона розповість вам більше про ситуацію, коли ви прибудете.",
    O = "Бельгром Рокмаул просить вас поговорити з Роком Орханом у таборі Моджаче.",
    P = "",
    C = "Отже, тебе прислав Белгром. Ти прийшов якраз вчасно, $R.$B$BДозволь мені пояснити ситуацію, а потім ти зможеш вирішити, чи готовий ти прийняти цей виклик... Але якщо тебе прислав Белгром, я впевнений, що твоя хоробрість не підлягає сумніву.",
},

[2982] = {
    en = "The High Wilderness",
    T = "Висока пустеля",
    D = "Хоча це небезпечно, ми з Троясом досліджуємо руїни, що вкривають ліси Фераласу.$B$BОднак останнім часом Трояс самотужки вирушає до Високої Пустелі, і я дуже за нього хвилююся. Цю місцевість захопили огри Гордунні, і вони не дуже прихильно ставляться до тих, хто заходить на їхню територію.$B$BЯ сподівався, що ти, можливо, погодишся вирушити до руїн на південному сході й вигнати звідти частину огрів. Зроби це місце трохи безпечнішим для мого Трояса, і я буду тобі надзвичайно вдячний.",
    O = "Анджела Мунбріз просить вас вбити 8 чаклунів Гордунні, 8 шаманів Гордунні та 8 брутів Гордунні.",
    P = "Будьте обережні поблизу Гордунні, $N. Здається, їхня магія завдає руйнівного впливу на саму землю, на якій вони стоять.",
    C = "Я дуже вдячний, що ти зміг це для мене зробити.$B$BА тепер, будь ласка, ні слова про це Троясу...",
},

[2983] = {
    en = "Call of Fire",
    T = "Поклик вогню",
    D = "Минуло вже деякий час з моменту твого останнього випробування, $N. Досі ти терпляче навчався, але настав час дізнатися про більші сили… настав час пізнати справжню силу. Стихія вогню стане твоєю, якщо ти готовий заплатити за неї.$B$BЗнайди Кранала Фісса в Пустках. Він мешкає у невеличкій хатинці на північ від Перехрестя, але май на увазі: якщо ти дістався до спустошених земель нічних ельфів, то зайшов надто далеко.",
    O = "Знайдіть Кранал Фісс у Пустошах.",
    P = "",
    C = "Хм, Сварт відправив тебе до мене, так?$B$BНу що ж, Сварту завжди можна довіряти, тож це, мабуть, означає, що ти готовий взяти участь у наступному сапті — сапті вогню.$B$BЯ вже бачу це в твоїх очах — той вогонь, те прагнення. Ти вже скуштував сили, і тепер прагнеш ще більше. Терпіння, $N. Пам’ятай, чого навчила тебе Земля. Сила й руйнування прийдуть легко, але ти все одно повинен знати, коли слід стримати руку.",
},

[2984] = {
    en = "Call of Fire",
    T = "Поклик вогню",
    D = "Минуло чимало часу з моменту твого останнього випробування, $N. Досі ти виявляв терпіння у своїх заняттях, але настав час дізнатися більше. Настав час дізнатися про руйнування... і хаос. Елемент вогню відкриється тобі для розуміння, якщо ти готовий заплатити за це.$B$BЗнайди Кранала Фісса в Пустках. Він мешкає у невеличкій хатинці на північ від Перехрестя, але пам’ятай: якщо ти дістався до земель нічних ельфів, значить, ти зайшов занадто далеко.",
    O = "Знайдіть Кранал Фісса в Пустках.",
    P = "",
    C = "Хм, Нарм відправив тебе до мене, так?$B$BЩо ж, Нарму завжди можна довіряти, тож це означає, що ти готовий взяти участь у наступній сапті — сапті вогню.$B$BЯ вже бачу це в твоїх очах — той вогонь, те прагнення. Ти скуштував силу, і тепер готовий до ще більшого. Терпіння, $N. Пам’ятай, чого навчила тебе земля. Сила й руйнування прийдуть легко, але ти все одно повинен знати, коли слід стримати руку.",
},

[2985] = {
    en = "Call of Water",
    T = "Поклик води",
    D = "Здається, ти готовий до наступного випробування, $N. Ти терпляче навчався, але настав час дізнатися більше. Настав час дізнатися про чистоту води.$B$BЗнайди Іслен Водоглядачку в Пустках. Вона перебуває вздовж східного узбережжя, на південь від річки Саутфурі та міста Ратчет. Ти знайдеш її там, у її рибальській хатинці. Удачі тобі, $N.",
    O = "Знайдіть Іслена Водобача в Пустошах.",
    P = "",
    C = "Вітер стрімко насувається на тебе з горизонту; земля міцно тримає тебе під ногами; а твій дух уже зігрітий вогнем — я б сказав, що настав час тобі дізнатися про чистоту води.$B$BТвій шлях привів тебе аж сюди, і твоя душа дасть тобі сили йти далі. Але перший крок ти маєш зробити сам.",
},

[2986] = {
    en = "Call of Water",
    T = "Поклик води",
    D = "Минуло чимало часу з моменту твого останнього іспиту, $N. Досі ти проявляв терпіння у навчанні, але настав час дізнатися більше. Настав час дізнатися про чистоту води.$B$BЗнайди Іслен Водобачительку в Пустках. Вона перебуває вздовж східного узбережжя, на південь від річки Саутф'юрі та міста Ратчет. Ти знайдеш її там, у її рибальській хатинці. Удачі тобі, $N.",
    O = "Знайдіть Іслена Водобача в Пустошах.",
    P = "",
    C = "",
},

[2987] = {
    en = "Gordunni Cobalt",
    T = "«Гордунні Кобальт»",
    D = "Я щойно прибув сюди, до Фераласу, і чув, що у гордуннських огрів, які мешкають у місцевих диких лісах, є якісь цікаві мінерали. Хто знає, що вони там замишляють, але вони точно ретельно охороняють ці копалини! Вони не залишають їх просто так валятися; ні, вони закопують їх, щоб такі, як я, не змогли їх дістати.$B$BЯкщо ти не проти, я дам тобі свою лопату. Зайди до застави Гордунні на північ відсюди й викопай для мене трохи кобальту Гордунні. Шукай синє світіння, а потім починай копати!",
    O = "Орвін Гізмік із табору Мохаче хоче отримати 12 зразків кобальту «Гордунні».",
    P = "Підіймайся туди і починай копати!$B$BМені треба ще кудись зайти і з кимось зустрітися — час — гроші!",
    C = "Чудово! Я візьму їх із собою, продовжуючи свою подорож, $N. Я впевнений, що знайду когось, хто заплатить чималу суму за цей кобальт.$B$BОсь, візьми це за твої клопоти.",
},

[2988] = {
    en = "Witherbark Cages",
    T = "Клітки «Вітербарк»",
    D = "Син нашого наймогутнішого грифона зник! Спадкоємець Швидкокрила, Гостридзьоб, зник кілька днів тому під час полювання разом із батьками, і ми вважаємо, що його викрали тролі.$B$BВи мусите нам допомогти! Перевірте клітки у двох селах тролів Вітербарк, щоб дізнатися, чи немає там Шарпбіка.",
    O = "Перевірте клітки у двох селах Вітербарк, а потім поверніться до майстра грифонів Талонакса.",
    P = "Ти вже обшукав клітки, $N? Ми мусимо знайти Шарпбіка!",
    C = "Шарпбік не був у селах? Гм... це сумна новина. Цьому грифону судилося очолити наступне покоління грифонів. Якщо його втратити, то сила й дух нашого флоту зазнають величезних втрат.",
},

[2989] = {
    en = "The Altar of Zul",
    T = "Вівтар Зула",
    D = "Шарпбік не був разом із тролями Вітербарка. Можливо, його викрали тролі з Вайлбранча. Відправляйся до Вівтаря Зула на західному краю території Вайлбранча й пошукай дитинча грифона.",
    O = "Оглянь верхню частину Вівтаря Зула, а потім повернися до майстра грифонів Талонакса.",
    P = "Поспішай, $N! Якщо тролі з Вайлбранча захопили Шарпбіка, хто знає, що вони можуть з ним зробити!",
    C = "Шарпбік там не був? Це й погана новина, й водночас хороша...$B$BДобре, що його не було біля Вівтаря Зула, адже тролі з Вілбранча відомі тим, що влаштовують жертвоприношення.$B$BЯ дякую вам за всю вашу допомогу, але, на жаль, попереду на мене чекає ще важче завдання.",
},

[2990] = {
    en = "Thadius Grimshade",
    T = "Тадіус Грімшейд",
    D = "Віднесіть це пір’я провидцю Тадіусу Грімшеду. Він покинув Пік Орлиного Гнізда багато років тому, щоб здобути темні знання, але в душі він досі залишається Диким Молотом!$B$BІ, можливо, його здібності допоможуть нам знайти Шарпбіка.$B$BЦе пір'я взято з гнізда, де спить дитинча грифона. Якщо ти віддаси його Тадіусу, то, якщо пощастить, він зможе за допомогою своєї магії пророцтва знайти Шарпбіка.$B$BУдачі, $N. Ти знайдеш Тадіуса у Спустошених Землях, у вежі магів фортеці Нетергард.",
    O = "Принесіть пір'їну Шарпбіка Тадіусу Грімшейду в Спустошені землі.",
    P = "$N, ти прийшов із подарунком?",
    C = "А, так. Це перо належить чудовому грифону. Йому судилося звершити великі подвиги... якщо він зможе без ушкоджень дожити до дорослого віку.$B$BТи хочеш його знайти? Тоді слухай уважно, хоробрий $C...",
},

[2991] = {
    en = "Nekrum's Medallion",
    T = "Медальйон Некрума",
    D = "Я з’ясую, де твій грифон, але спершу ти маєш щось для мене зробити. У Зул’Фарраку живе троль на ім’я Некрум Гутчевер, у якого є медальйон, який я дуже хотів би дослідити. Принеси мені цей медальйон, і я використаю свої сили, щоб знайти Шарпбіка.$B$BЗул'Фаррак розташований на захід від нас, за океаном, у пустелі Танаріс.",
    O = "Принесіть медальйон Некрума Тадіусу Грімшейду в Спустошені землі.",
    P = "Чи є у тебе медальйон Некрума, $N? У ньому приховані сили, які я дуже хочу розкрити.",
    C = "Ах, медальйон Некрума. Ходять чутки, що він наділив троля надприродно довгим життям, але за певну ціну. Я сподіваюся знайти спосіб скористатися силою медальйона, уникнувши при цьому його… неприємних побічних ефектів.$B$BТи зробив мені послугу, $N. Тепер я виконаю свою частину угоди.",
},

[2992] = {
    en = "The Divination",
    T = "Ворожіння",
    D = "Дайте мені трохи простору, поки я проведу ритуал ворожіння. Я знайду зв’язок між пір’їнкою, яку ви мені принесли, та її власником, і простежу цей зв’язок аж до самого Шарпбіка.$B$BТобто... Я це зроблю, якщо все піде за планом. Якщо ж ні, то... тобі краще заплющити очі.",
    O = "Зачекайте, поки Грімшейд проведе ритуал ворожіння.",
    P = "",
    C = "Ритуал пройшов успішно. Я бачив Шарпбіка і можу розповісти тобі, як його знайти.",
},

[2993] = {
    en = "Return to the Hinterlands",
    T = "Повернення до глибинки",
    D = "Шарпбік утримується в клітці, високо на скелі на вершині Джинта'Алор у Замежжя. Ключ від цієї клітки має верховна жриця тролів Вілбранч, Злісна Жриця Гекс.$B$BОсь так. Я зробив свою справу. Бажаю тобі успіху у твоєму походженні, $N.",
    O = "Поговоріть із майстром грифонів Талонаксом.",
    P = "",
    C = "Ти розмовляв із Грімшедом? Що він сказав?$B$B...Що? Тролі з Вайлбранча захопили Шарпбіка? Це нестерпно! Ми мусимо зібрати загін, щоб його повернути!",
},

[2994] = {
    en = "Saving Sharpbeak",
    T = "Рятуючи Шарпбіка",
    D = "Ми мусимо врятувати Шарпбіка!$B$BПробийтеся до вершини Джинта'Алора в самому серці території Вайлбранч, заберіть ключ від клітки Шарпбіка у підлої жриці Гекс, а потім знайдіть і врятуйте Шарпбіка!",
    O = "Пробийтеся на вершину Джинта'Алора, вбийте Злу жрицю Гекс, щоб отримати ключ від клітки Шарпбіка, і врятуйте Шарпбіка.",
    P = "Врятуйте Шарпбіка!",
    C = "Свіфтвінд і Кінклоу щойно повернулися зі своєю дитиною і тепер піклуються про неї, наче новоспечені батьки. Лише один погляд на них разом — і навіть у цього старого гнома на очах з’являється сльоза...$B$BМи не зможемо достатньо віддячити тобі за те, що ти зробив, $N. Грифони з вершини Ері та їхні вершники ще дуже-дуже довго співатимуть про тебе.",
},

[2995] = {
    en = "Lines of Communication",
    T = "Канали зв’язку",
    D = "Ложа Кель'Даніл є центром комунікації для високих ельфів Гінтерленду. Їхні посли працюють над налагодженням відносин з іншими расами, з якими вони діляться своїми знаннями про тролів Вітербарк, що мешкають у південній частині Гінтерленду. Усі документи, що стосуються цих контактів, зберігаються в ложі.$B$BНам не потрібно, щоб Хайвейл укладав союзи з іншими, $N.$B$BЗнищте документи Хайвейла. Нам потрібно спалити їхні канали зв’язку… у буквальному сенсі.",
    O = "Оран Снейквайт із Підміста просить вас вирушити до Глибинних земель і спалити «Архів Хайвейла», «Звіт Хайвейла» та «Нотатки Хайвейла».",
    P = "Головне — тримати ельфів з Хайвейла в ізоляції. Ти вже знайшов хатину?",
    C = "Чудово, $N. Поки у Хайвейлі працюють над відновленням втраченої інформації, ми зможемо ще більше перекрити канали зв’язку...",
},

[2996] = {
    en = "Seeking Strahad",
    T = "У пошуках Страхада",
    D = "Раніше я навчав тебе майстерності, але настав час, щоб тебе навчав хтось інший. Він перебуває в Ратчеті, і його звуть Страхад. Він — людина, але нехай це не вводить тебе в оману: не думай, що він слабкий. Він могутній, хоч і невеликий на зріст. Він може навчити вас ще потужнішим заклинанням — я відчуваю, що ви готові. Ідіть до нього зараз. Він у Ратчеті... над портовим містом, поруч зі своєю вежею.",
    O = "Поговоріть зі Страхадом Фарсаном у Ратчеті.",
    P = "",
    C = "У Ратчеті сьогодні жвавий день, чи не так? Як же мені подобається спостерігати за метушнею портового міста. Стільки таємниць, стільки пригод... стільки невігластва.$B$BЧи це ненависть я бачу в твоїх очах, $N? Добре, ми це з користю використаємо.",
},

[2997] = {
    en = "Tome of Divinity",
    T = "«Трактат про божественність»",
    D = "Привіт, $N. Я знаю, що ти зайнятий допомогою мешканцям Дун-Морога, але коли у тебе з’явиться час, тобі варто завітати до Айронфорджа, щоб поговорити з однією з найшанованіших представниць нашого кола — Тізою Батлфордж. Саме до неї звертаються молоді паладини, коли настає час дізнатися більше про Світло та про те, чого від вас очікують.$B$BВи знайдете її нагорі, у Залі Таємниць. Якщо ви там ще ніколи не були, то він розташований у Містичному кварталі. Удачі тобі, $N.",
    O = "Поговоріть із Тізою Баттлфордж у Айронфорджі.",
    P = "",
    C = "Радий зустрічі, $N. Сподіваюся, що Світло вкаже тобі справжній шлях і захистить тебе від зла.",
},

[2998] = {
    en = "Tome of Divinity",
    T = "«Трактат про божественність»",
    D = "Вітаю, $Gbrother:sister;. Дуторіан Ралл, один із наших найвпливовіших паладинів, нещодавно згадував про тебе. Я випадково почув, як він говорив, що тобі вже час пройти певне випробування… а також висловлював дуже схвальні відгуки про те, як добре ти показав себе досі.$B$BНа твоєму місці я б поїхав до Штормвінда й поговорив з ним, коли буде час. Я впевнений, що він у Соборі Світла — саме там він проводить більшу частину свого часу.",
    O = "Поговоріть із Дуторіаном Раллом у Штормграді.",
    P = "",
    C = "У Штормвінді так гарно, чи не так?$B$BТи, справді, не міг би прийти в більш вдалий момент, $N.",
},

[2999] = {
    en = "Tome of Divinity",
    T = "«Трактат про божественність»",
    D = "Привіт, $N. Я знаю, що ти зайнятий допомогою мешканцям Дун-Морога, але коли у тебе з’явиться час, тобі варто піднятися нагору й поговорити з однією з найшанованіших представниць нашого ордену — Тізою Батлфордж. Саме до неї звертаються молоді паладини, коли настає час дізнатися більше про Світло та про те, чого від них очікують.",
    O = "Поговоріть із Тізою Баттлфордж у Айронфорджі",
    P = "",
    C = "Радий зустрічі, $N. Сподіваюся, що Світло вкаже тобі справжній шлях і захистить тебе від зла.",
},

[3000] = {
    en = "Tome of Divinity",
    T = "«Трактат про божественність»",
    D = "Привіт, $N. Я знаю, що ти зайнятий допомогою мешканцям Азерота, але коли у тебе з’явиться час, тобі варто повернутися до Айронфорджа й поговорити з однією з найшанованіших паладинів твого рідного міста — Тізою Батлфордж. Саме до неї звертаються молоді паладини-гноми, коли настає час дізнатися більше про Світло та про те, чого очікують від нас усіх.$B$BТи знайдеш її нагорі в Залі Таємниць, що розташований у Містичному кварталі.",
    O = "Поговоріть із Тізою Баттлфордж у Айронфорджі.",
    P = "",
    C = "Вітаю вас і радо вітаю, $N.",
},

[3001] = {
    en = "Seeking Strahad",
    T = "У пошуках Страхада",
    D = "Раніше я навчав тебе певним навичкам, але настав час, щоб тебе навчав хтось інший. Він перебуває в Ратчеті, і його звати Страхад. Він — людина, але нехай це не вводить тебе в оману: не думай, що він слабкий, і він не є твоїм ворогом… принаймні поки що. Він могутній і заслуговує на повагу. Він може навчити вас більш потужним заклинанням — таким, до яких, як я відчуваю, ви вже готові. Ідіть до нього зараз.$B$BВи знайдете його в Ратчеті... над портовим містечком, поруч із вежею.",
    O = "Знайдіть Страхада Фарсана в Ратчеті.",
    P = "",
    C = "У Ратчеті сьогодні жвавий день, чи не так? Як же мені подобається спостерігати за метушнею портового міста. Стільки таємниць, стільки пригод... стільки невігластва.$B$BЧи це ненависть я бачу в твоїх очах, $N? Добре, ми це з користю використаємо.",
},

[3002] = {
    en = "The Gordunni Orb",
    T = "Сфера Гордунні",
    D = "Хоча я добре знаю свого ворога, я — воїн, $N. Я навіть не можу уявити, на що здатна ця куля.$B$BЯ знаю одного мага в Оргримарі, який зможе розповісти нам більше про цю кулю. Віднесіть її йому.",
    O = "Принесіть Сферу Гордунні Утель'нею в «Хаті Темного Терну» в Оргримарі.",
    P = "Що ти мені приніс, $R?",
    C = "Цікаво, $N...$B$BЦя куля дуже потужна, але й дуже небезпечна.",
},

[3022] = {
    en = "Handle With Care",
    T = "Поводьтеся обережно",
    D = "$N, я бачу, що ти прагнеш присвятити себе моїй благородній справі. Так, звичайно, ти можеш щось для мене зробити!$B$BВіднеси цю скриню з яйцями Ереласу Амберскі. Він — друїд, який опікується цими яйцями, допомагає їм вилупитися, а потім дресирує молодих гіпогрифів. Ти знайдеш його в Телдрасілі, у невеличкому селі на півдні під назвою Рут'теран.",
    O = "Віднесіть ретельно упаковану скриню Ереласу Амберскі в селі Рут'теран.",
    P = "Ще одна партія від «Curgle», як я припускаю?",
    C = "Дякую за допомогу, $N. Популяція гіппогрифів просто не могла б процвітати, якби не ми. Ах, але я впевнений, що ти це чудово розумієш, адже сам подорожував до Фераласу й бачив там руйнування, спричинені Гордунні.$B$BНу, як бачите, я тут наполегливо працюю, тож вам краще вже йти.$B$BЩе раз дякую, $N.",
},

[3042] = {
    en = "Troll Temper",
    T = "Трольський характер",
    D = "Тролі «Піщаної люті» із Зул’Фаррака виготовляють загартовувальний засіб із пісковиків, і я можу використовувати його для загартовування речей, які я створюю, так, можу! Цей засіб дуже цінується знавцями, тож якщо ти принесеш мені достатній запас цього загартовувача, я щедро винагороджу тебе.$B$BЗул'Фаррак розташований на північний захід від Гаджетзана. Удачі.",
    O = "Принесіть 20 флаконів «Трольського гніву» Трентону Лайтхаммеру в Гаджетзані.",
    P = "Ти приніс мені цей настрій, $N?",
    C = "О, це справді чудовий настрій! І його стільки! Мені знадобиться кілька днів роботи, щоб його все витратити!$B$BДякую, $N. Будь ласка, прийми це як оплату.",
},

[3062] = {
    en = "Dark Heart",
    T = "«Темне серце»",
    D = "Едана Хатеталон — королева гарпій Нортспринга, які мешкають у руїнах на заході. Вона — втілення чистого зла; я чув, що її серце — кришталеве. Вона позбавлена будь-яких емоцій, окрім ненависті, яку відчуває до всіх інших. Ти повинен зіткнутися з Еданою та принести мені її темне серце.$B$BЯ чув про ріг, який носять гарпії — якщо протрубити в нього біля каменів Хатеталон, що в північній частині руїн, це викличе королеву.$B$BУяви її здивування, коли виявиться, що її кличе не її рідня, а сама смерть.",
    O = "Тало Торнхуф у таборі Моджаче хоче отримати «Темне серце» Едани Хатеталон.",
    P = "Необхідно покласти край ненависті, яку Едана поширює по всій країні.",
    C = "Тепер я знаю, що Едана справді померла. Це серце я збережу на згадку про те, що вона для мене зробила, $N. Дякую.",
},

[3063] = {
    en = "Vengeance on the Northspring",
    T = "Помста в Нортспрингу",
    D = "У ті часи я був досвідченим мисливцем. Не було жодної істоти, якої б я боявся. Доки...$B$BЯ був у лісі, точив свій меч після важкої битви, коли на мене напали з засідки. Мене оточили гарпії, і я ледь встиг вибратися в безпечне місце.$B$BНавіть зараз я все ще чую, як лунають їхні крики...$B$BПісля того я вже ніколи не був таким, як раніше. Але ненависть кипить у мені — я мушу помститися, після стількох років.$B$BГарпії Північного Джерела мешкають на захід від цього місця. $N, помстись за мене.",
    O = "Тало Торнхуф хоче, щоб ви вбили 4 гарпій Північного Джерела, 4 «Непокірних пір’я» Північного Джерела, 4 «Покликувачів вітру» Північного Джерела та 4 «Вбивць» Північного Джерела.",
    P = "Крила гарпій Нортспринг чорні, як ніч; не відводьте від них погляду, інакше вони зникнуть у темряві.",
    C = "Дякую, $N. Ти заспокоїв душу старого таурена.",
},

[3065] = {
    en = "Simple Tablet",
    T = "Простий планшет",
    D = "Ах, поки тебе не було, тобі прийшов пергамент, $N.$B$BПрочитай його, коли буде час. Якщо я не помиляюся, його надіслав інструктор воїнів Френг. Він хотів би поговорити з тобою, коли ти будеш готовий. Ти знайдеш його біля «Лігва», він ховається в тіні.",
    O = "Прочитайте «Простий планшет» і поговоріть із Френгом у Долині Випробувань.",
    P = "Ще один $R для поповнення лав. Мені цього вистачить.$B$BТобі, мабуть, буде важко підняти таку потужну зброю, як сокира, але спис підійде не гірше за будь-що інше.$B$BЛаскаво просимо до Долини Випробувань.",
    C = "Це місце стане для тебе ідеальним, коли ти продовжиш навчатися за методами $C. Якщо у тебе виникнуть запитання, сміливо звертайся до будь-кого з присутніх, а коли відчуєш, що готовий, повертайся до мене для навчання. Я опанував стільки ж, скільки й будь-який $C тут, у Долині, і можу передати ці знання тобі… за певну плату.",
},

[3082] = {
    en = "Etched Tablet",
    T = "Гравюрована табличка",
    D = "А, поки тебе не було, тобі прийшла записка, $N.$B$BПрочитай її, коли буде час. Якщо я не помиляюся, її надіслала інструкторка мисливців Джен’шан. Вона хотіла б поговорити з тобою, коли ти будеш готовий.",
    O = "Поговоріть із Дженшаном у Долині Випробувань.",
    P = "Дженшан бачить перед собою могутнього $C, і духи схвалюють це.$B$BШлях $C — один із найдавніших наших життєвих шляхів. Орда звернулася до нас, коли вони ледь боролися за виживання в Азероті, і попросила нас навчити їх, відкрити їм таємниці багатьох речей. Вони вже були сильними: сильними в $C; сильними в $C. Але шлях $C не був їхнім шляхом... тоді.",
    C = "Тепер ми навчаємо їх цим речам, а вони навчають нас іншим. Ми стаємо однією расою… майже. Ми вже давно є союзниками. Тож не забувай допомагати їм. І Джен'шан не забуває допомагати вам.$B$BДжен'шан навчає вас шляхам $C — навчає вас добре. Ви ніколи не забувайте, що $C користується великою повагою серед племені. У майбутньому тобі відведена важлива роль... ніколи про це не забувай.$B$BКоли відчуєш у цьому потребу, звертайся до Джен'шан. Вона навчить тебе всьому, на що здатен, коли відчує, що ти готовий.",
},

[3083] = {
    en = "Encrypted Tablet",
    T = "Зашифрований планшет",
    D = "Ах, поки тебе не було, тобі прийшла записка, $N.$B$BПрочитай її, коли буде час. Якщо я не помиляюся, її надіслав тренер-розбійник Рваг. Він хотів би з тобою поговорити, коли ти будеш готовий.",
    O = "Прочитайте зашифровану табличку та поговоріть з Рвагом у Долині Випробувань.",
    P = "Ласкаво просимо до Долини Випробувань, $N. Ти б не опинився тут, якби не отримав мій планшет, тож перейду відразу до справи.$B$BЯ — Рваг, і я відповідаю за навчання розбійників, злодіїв та кишенькових злодіїв тут, у Долині. Саме до мене звернеться «Рука», якщо ти не будеш готовий до того, що на тебе чекає. Але не хвилюйся, «Рука» не контролюватиме кожний твій крок, проте було б розумно співпрацювати з нею, якщо твої таланти знадобляться.",
    C = "Доки не настане цей час, ти будеш під моїм наставництвом. Я навчу тебе азам, як кажуть деякі. Коли відчуєш, що готовий, прийди до мене, і я подумаю, як тебе навчити далі. А до того часу відточуй свої навички й тримай їх гострими, як лезо бритви. Ніколи не знаєш, коли знадобиться навіть найнезначніша навичка.",
},

[3084] = {
    en = "Rune-Inscribed Tablet",
    T = "Плита з рунічним написом",
    D = "А, поки тебе не було, тобі прийшла записка, $N.$B$BПрочитай її, коли буде час. Якщо я не помиляюся, її надіслала інструкторка-шаманка Шикрік. Вона хотіла б поговорити з тобою, коли ти будеш готовий.",
    O = "Поговоріть із Шикриком у Долині Випробувань.",
    P = "Ах, ласкаво просимо, $N. Я радий, що ти приїхав. Мої дні стали довгими й навіть напруженими через те, що мені доводиться навчати так багато учнів, але приїзд когось із твого кола дарує мені велике почуття задоволення — я пам’ятаю ті часи, коли мене навчав один із ваших шаманів.",
    C = "Як ви, мабуть, знаєте, елементи дають нам силу. Вогонь, земля, вода та повітря — це наші знаряддя.$B$BНаша сила походить від духів наших предків. Ми — вожді нашого народу. Як Трал для Орди, так і ми будемо для сіл і міст, які відвідуємо. Вони звертатимуться до нас за мудрістю та захистом. Щоб бути краще підготовленими, ви мусите часто тренуватися. Коли відчуєте, що набралися більше сили, приходьте до мене, і я навчу вас усього, на що здатний.",
},

[3085] = {
    en = "Hallowed Tablet",
    T = "Священна табличка",
    D = "А, поки тебе не було, тобі прийшла записка, $N.$B$BПрочитай її, коли буде час. Якщо я не помиляюся, її надіслав інструктор-священик Кен’джай. Він хотів би з тобою поговорити, коли ти будеш готовий.",
    O = "Прочитайте «Священну табличку» і поговоріть із Кенджаєм біля входу до Лігва у Долині Випробувань.",
    P = "Отже, ти дістався сюди… чудово, чудово! Духи сказали мені, що ти незабаром прийдеш до Кенджая. Дозволь мені бути одним із перших, хто привітає тебе в Долині Випробувань. Це місце не надовго стане твоїм домом, але поки це так, чому б тобі не отримати від нього максимум користі?",
    C = "Коли ви будете випробовувати себе, то побачите, що все краще й краще керуєте духами — ви будете звертатися до них за дедалі більшими речами… Ось тут і з’являється старий Кен’джай. Прийди поговорити зі старим Кен'джаєм, коли відчуєш, що готовий. Якщо духи погодяться, тоді ми подивимося, чи можна навчити тебе більш потужним здібностям... але тільки якщо духи погодяться.$B$BА тепер іди, поговори з рештою мешканців Долини. Повернися до мене пізніше.",
},

[3086] = {
    en = "Glyphic Tablet",
    T = "Гліфічна табличка",
    D = "А, поки тебе не було, тобі надійшла записка, $N.$B$BПрочитай її, коли буде час. Якщо я не помиляюся, її надіслала інструкторка-маг Май’а. Вона хотіла б поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитайте «Гліфічну табличку» та поговоріть з Майа біля входу до Лігва у Долині Випробувань.",
    P = "Ти, здається, вже намагаєшся догодити Май’ї, $N. Це добре. Якщо ти проявиш повагу до Май’ї, вона, можливо, відповість тобі тим самим. Але досить про це, ти тут, щоб навчитися магії, а не слухати розмови Майї.$B$BЄ лише одна річ, якої Майя не може навчити тебе в магії, $N, — це як зупинити спотворення.",
    C = "Ти — одне з наймогутніших істот на цій планеті, $N... з цим ніхто не сперечається. І всі це знають... знають дуже добре!$B$BАле ти мусиш бути обережним! Бо боятися треба не орків, ельфів чи гномів... а тих речей, яких ти не бачиш. Магія — це велика сила. Вона змушує тебе робити те, чого ти, можливо, не хочеш. Змушує думати, що ти сильніший, ніж є насправді. Будьте терплячі. Будьте розумні.$B$BКоли вважатимете, що готові до навчання, повертайтеся до Май’ї. Вона навчить вас того, до чого ви готові, без жодних проблем.",
},

[3087] = {
    en = "Etched Parchment",
    T = "Гравюра на пергаменті",
    D = "Ах, поки тебе не було, тобі прийшов пергамент, $N.$B$BПрочитай його, коли буде час. Якщо я не помиляюся, його надіслала інструкторка мисливців Джен’шан. Вона хотіла б поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитайте «Вигравіруваний пергамент» і поговоріть з Дженшаном у Долині Випробувань.",
    P = "А, отже, ти нарешті прийшов. Добре. Джен’шан чекає на тебе.$B$BБагато хто вважає, що це легкий шлях, але Джен’шан скаже тобі, що це неправда. Опанувати звірів Дуротара та інших країв вимагає не менше майстерності, ніж опанувати таємні мистецтва чи спілкуватися з нашими предками.$B$BСтрільба з лука чи рушниці, можливо, не така небезпечна для тебе, як заклинання, але для твого ворога вона, безперечно, така сама небезпечна.",
    C = "Коли ми закінчимо розмову, тобі слід поговорити з іншими мешканцями Долини. Вони попросять тебе зробити для них дещо… те, що випробує твої вміння та навчить тебе деяким небезпекам цієї землі.$B$BКоли ти набудеш досвіду та мудрості, тобі знадобиться Дженшан, щоб він показав тобі кращі техніки та навички. Частіше повертайся до Дженшана. Я дам тобі знати, чому можу тебе навчити.",
},

[3088] = {
    en = "Encrypted Parchment",
    T = "Зашифрований пергамент",
    D = "А, поки тебе не було, для тебе прийшов пергамент, $N.$B$BПрочитай його, коли буде час. Якщо я не помиляюся, його надіслав тренер розбійників Рваг. Він хотів би з тобою поговорити, коли ти будеш готовий.",
    O = "Прочитайте зашифрований пергамент і поговоріть з Рвагом у Долині Випробувань.",
    P = "Тсс, не так голосно. Я не довіряю тому Нартоку. З тим, хто змушений ховатися в печері ще глибше, ніж я, краще не жартувати.$B$BСподіваюся, ти без проблем зорієнтувався тут?",
    C = "Тепер, коли ти вже знаєш, де я перебуваю, маю тобі сказати: «Розбита Рука» попросила мене піклуватися про тебе. Вони хочуть, щоб я навчив тебе й тримав тебе в курсі всього, що їм може знадобитися. Навіть якщо ти поки що не зацікавлений у тому, щоб допомагати їм — а було б дурістю не бути зацікавленим — я зроблю все, що зможу, аби навчити тебе… за невелику плату. Повертайся до мене, коли вважатимеш, що готовий, і ми подивимося, чого ти готовий навчитися.",
},

[3089] = {
    en = "Rune-Inscribed Parchment",
    T = "Пергамент з рунічними написами",
    D = "А, поки тебе не було, тобі прийшов пергамент, $N.$B$BПрочитай його, коли буде час. Якщо я не помиляюся, його надіслала наставниця шаманів Шикрик. Вона хотіла б поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитайте пергамент із рунічним написом і поговоріть із Шикріком у Долині Випробувань.",
    P = "Отже, ти прибув. Я вже почав замислюватися, коли ж ти з’явишся. Я надіслав пергамент деякий час тому — не був упевнений, чи він дійшов.$B$BАле досить балачок… ти тут, бо тебе обрали — обрали, щоб керувати духовним життям нашого народу.",
    C = "Ти станеш посередником, через якого спілкуватимуться наші предки. Сила стихій буде у твоєму розпорядженні. Знищення ворогів стане для тебе дитячою грою, а зцілення союзників — таким же простим, як дихання. Пам’ятай про це, коли стикатимешся з новими викликами, і повертайся до мене так часто, як забажаєш. Я залишатимуся тут, щоб навчати тебе новим заклинанням і направляти тебе на правильний шлях, коли ти будеш готовий.",
},

[3090] = {
    en = "Tainted Parchment",
    T = "Зіпсований пергамент",
    D = "Ах, поки тебе не було, тобі прийшов пергамент, $N.$B$BЗазвичай я намагаюся не мати справ із чаклунами, якщо це можливо, але, гадаю, тобі варто його прочитати, коли буде час. Якщо я не помиляюся, його надіслав твій новопризначений наставник Нарток. Він хотів би поговорити з тобою, коли ти будеш готовий.",
    O = "Прочитайте «Зіпсований пергамент» і поговоріть з Нартоком у «Лігві» в Долині Випробувань.",
    P = "Нарешті ти прибув... до того ж непомітно. Добре.$B$BНаш світ сповнений дурнів, $N. Навіть могутній Трал має більші вади, ніж більшість може побачити. Він відвертається від сили, необхідної для того, щоб ця земля повністю стала нашою! Ми вже не ті люди, якими маніпулювали й якими користувалися істоти з Нетера. Ми — самостійний народ. Ми горді... і ми сильні.",
    C = "І ось тепер ти теж приєднався до наших лав. Не зрозумій мене неправильно, $N. Те, що ти маєш доступ до сили, якій багато хто заздрить, ще не означає, що тебе легко приймуть. Тралл допускає нас до Оргримара, бо ми все ще його родичі — він не може відвернутися від нас, інакше ми стали б такими ж жалюгідними, як люди, які його поневолили. Я хочу сказати: будь обережним. Ти можеш бути могутнім, але якщо будеш нерозумним, то тобі краще вже померти.$B$BЯкщо тобі потрібне навчання чарам, то повертайся до мене.",
},

[3091] = {
    en = "Simple Note",
    T = "Проста примітка",
    D = "Щойно до тебе приходила посланниця, $N. Гадаю, її прислав тренер-воїн Харутт. Якщо ця записка від Харутта, я б не зволікав із її прочитанням.$B",
    O = "Прочитайте «Просту записку» та поговоріть з Харуттом Громорогом у таборі Нараче.",
    P = "Ах, нарешті ти прибув, $c. Я не збрехав у своїй записці, $N. Ми теж особливий народ, не на відміну від друїдів чи шаманів нашого племені. Ти так само важливий. Саме нас покликано захищати наші кордони, полювати на кентаврів і йти на війну.",
    C = "Кожен із нас відіграє певну роль у нашому племені. Кожен із нас також повинен пройти всі ті самі обряди. Ніколи не дозволяй своїй гордості переконати тебе в іншому.$B$BЯ залишаюся тут, щоб навчати нових воїнів, які прагнуть слави в бою та слідують шляхам наших найдавніших предків. Коли відчуєш, що готовий, повертайся до мене, і я зроблю все, що в моїх силах, щоб навчити тебе далі. Іди з благословенням племені, $N.",
},

[3092] = {
    en = "Etched Note",
    T = "Нотатка, вигравірувана на металі",
    D = "Щойно до тебе приходила посланниця, $N. Гадаю, її прислала тренерка мисливців Ланка. Якщо ця записка від Ланки, я б не зволікав із її прочитанням.$B",
    O = "Прочитайте «Вигравірувану записку» та поговоріть із Ланкою Фаршот у Ред-Клауд-Меса.",
    P = "Ласкаво просимо до табору Нараче, $N. Я чув про тебе багато хорошого. Ти походиш із сильного роду, і багато старших вже вважають тебе досвідченим. Але це ми ще перевіримо.$B$BРівнини Мулгора деякий час стануть твоїм домом — тобі слід докласти всіх зусиль, щоб добре їх вивчити. Одного дня ти вирушиш у незнайомі землі, щоб опанувати ще вищі навички. Ти маєш бути готовим.",
    C = "І моє завдання — подбати про те, щоб ти був готовий, навчивши тебе основам нашої професії: як приручити свого вихованця, як стріляти з рушниці та багатьом іншим навичкам, які стануть тобі необхідними.$B$BМисливці — це важлива частина наших традицій та історії, $N. Вам варто пам’ятати, наскільки ви важливі для племені. Якщо ви добре служитимете нашому народу, вас поважатимуть і шануватимуть.",
},

[3093] = {
    en = "Rune-Inscribed Note",
    T = "Записка з рунічними знаками",
    D = "Щойно до тебе приходила посланниця, $N. Гадаю, її прислала тренерка-шаманка Міла. Якщо ця записка від Міли, я б не зволікав із її прочитанням.$B",
    O = "Прочитайте записку з рунічним написом і поговоріть з Мілою Доунстрайдер у таборі Нараче.",
    P = "Так само швидко, як вода падає з неба, ти вже стоїш переді мною. Мені приємно, що ти так поспішив. Це означає, що ти усвідомлюєш і важливість нашої зустрічі, і те, що ти тут. Я не є вождем, але розумію стихії і можу спілкуватися з духами нашого народу. Я навчу тебе робити те саме.",
    C = "У найближчі дні ми ще не раз зустрінемося. Сподіваюся, що кожного разу, залишаючи мою компанію, ти ставатимеш трохи сильнішим… трохи краще підготовленим. Як Вічне Полум’я, твій дух палатиме яскраво й гаряче.$B$BА тепер іди, $N. Іди й випробуй себе. Я буду тут для тебе, коли тобі це знадобиться.",
},

[3094] = {
    en = "Verdant Note",
    T = "«Зелена нота»",
    D = "Щойно до тебе приходила посланниця, $N. Гадаю, її прислав інструктор-друїд Гарт. Якщо ця записка від Гарта, я б не зволікав із її прочитанням.$B",
    O = "Прочитайте «Зелену записку» та поговоріть із Гартом Містрраннером у таборі Нараче.",
    P = "Ти прибув. Це добре. Духи наших предків стали неспокійними в усьому Мулгорі та за його межами, але я не можу пояснити, чому. Твоє вічне завдання — навчитися прислухатися до духів природи та діяти як їхній представник. Пам’ятай про це.",
    C = "Хоча нас пов’язує спільна доля, не сподівайся на теплий прийом з боку нічних ельфів. Їхня гордість досі затуманює їм розум, але це не наша справа. Тобі слід турбуватися лише про вчення Матері-Землі, і я навчатиму тебе всьому, що знаю, у міру того, як ти набуватимеш мудрості.$B$BЧасто повертайся до мене, $N. Ти переконаєшся, що Мати-Земля дарує неймовірні здібності тим, хто найвідданіший їй.",
},

[3095] = {
    en = "Simple Scroll",
    T = "Простий прокрут",
    D = "Ах, поки ти був зайнятий боротьбою з бездумним Плетью, тобі надійшов цей сувій. Думаю, це щось важливе, оскільки, судячи з усього, на ньому стоїть печатка інструктора-воїна Даннала. Я б приділив трохи часу, щоб прочитати його, перш ніж знову вирушати в дорогу.",
    O = "Прочитайте «Простий свиток» і поговоріть з Данналом Стерном у Дескнеллі.",
    P = "А, отже, ти прибув. Добре. Я чула, що ще декому вдалося врятуватися від «смерті» і що вони прямують до міста. Можливо, ця стійкість принесе плоди й у майбутньому.$B$BЗа свою свободу — свободу духу й тіла — ти можеш подякувати Сильвані... Хоча тебе й досі мучить чума та її наслідки, тепер ти вільний приходити й йти, як вважаєш за потрібне.",
    C = "Я буду тут, щоб навчати тебе, поки ти набуватимеш досвіду… звертайся до мене так часто, як забажаєш. Я беру мінімальну плату, але ти переконаєшся, що все, чого я можу тебе навчити, того варте.$B$BА тепер іди й випробуй свої вміння. З набуттям досвіду ти дізнаєшся ще багато чого, про деякі речі я не можу говорити з тобою тут. Просто знай, що в майбутньому Сильваніс потребуватиме воїнів із такою силою, як у тебе. Ти станеш основою нашого спасіння. Не забувай про це.",
},

[3096] = {
    en = "Encrypted Scroll",
    T = "Зашифрований свиток",
    D = "Ага, поки ти був зайнятий боротьбою з бездумним «Скоржем», тобі надійшов цей сувій. Гадаю, це щось важливе, оскільки, судячи з усього, на ньому стоїть печатка інструктора розбійників Девіда Тріаса. Я б на твоєму місці знайшов час, щоб прочитати його, перш ніж знову вирушати в дорогу.",
    O = "Прочитайте зашифрований сувій і поговоріть з Девідом Тріасом у Дескнелі.",
    P = "То ти впорався? Добре, з часом нам знадобиться ще більше розбійників. «Тіньові мисливці», мабуть, знайдуть тебе, коли вважатимуть за потрібне, тож не роби ніяких помилок і не роби нічого, про що потім можеш пошкодувати. Їм потрібні талановиті агенти... а не кишенькові злодії та дурні.",
    C = "Я проводжу більшу частину часу тут, у таверні, придивляючись до нових облич і стежачи за перспективними новачками. Не встрягай у неприємності, і я зроблю все, що зможу, щоб навчити тебе дечому. Просто повертайся до мене, коли захочеш, і ми подивимося, чи готовий ти опанувати одну-дві нові навички.",
},

[3097] = {
    en = "Hallowed Scroll",
    T = "Священний сувій",
    D = "Ах, поки ти був зайнятий боротьбою з бездумним Плетью, тобі надійшов цей сувій. Думаю, це щось важливе, оскільки, судячи з усього, на ньому стоїть печатка інструктора-священика Дуестена. Я б приділив трохи часу, щоб прочитати його, перш ніж знову вирушати в дорогу.",
    O = "Прочитайте Священний сувій і поговоріть із Темним кліриком Дюстеном у церкві в Дескнелі.",
    P = "Ага, отже, серед пожеж, епідемій, заворушень і набагато гірших подій до моїх дверей приходить ще один із «віруючих». Що ж, дозволь мені привітати тебе, $C. І дай мені хвилинку, щоб пояснити дещо, перш ніж ти вирішиш, що настав час шукати те, що рухає тебе вперед: Святе Світло тебе більше не стосується, духи твоїх предків — це казки, а істоти з Нетера тебе не хочуть.$B$BТи мене досі розумієш?",
    C = "Тобі потрібно знати лише одне: ми вижили виключно завдяки силі волі. Саме віра в себе відрізняє нас від інших, і завдяки нашим здібностям ми спричинемо великі зміни в усьому Азероті. Слабкі будуть покладатися на тебе. Прокажені називатимуть вас Господом. А неосвічені звертатимуться до вас за порадою. Мій обов’язок — забезпечити вас усім необхідним, щоб, коли настане час, ви були готові. Здобуваючи досвід, звертайтеся до мене. Я навчу вас ще більшим силам, якщо ви будете готові.",
},

[3098] = {
    en = "Glyphic Scroll",
    T = "Гліфічний сувій",
    D = "Ах, поки ти був зайнятий боротьбою з бездумним Плетью, тобі надійшов цей сувій. Гадаю, це щось важливе, бо, судячи з усього, на ньому стоїть печатка інструкторки-магічки Ізабелли. Я б на твоєму місці знайшов час, щоб прочитати його, перш ніж знову вирушати в дорогу.",
    O = "Прочитайте «Гліфічний сувій» і поговоріть з Ізабеллою в церкві в Дескнеллі.",
    P = "Я знав, що ти прийдеш до мене, $N. Не тому, що тобі бракує волі йти своїм шляхом, а тому, що ми — споріднені душі. Ми обоє відчували біль. Ми обоє страждали. І тепер ми прагнемо сили, щоб повернути те, що, як ми знаємо, належить нам: цю землю, наші життя, наші долі. Але тобі ще багато чого треба навчитися.",
    C = "Ти повинен часто повертатися до мене, якщо хочеш стати достатньо могутнім, щоб знищити тих, хто протистоїть нам. Правила магії й надалі діють щодо тебе, $N. Ти й надалі відчуватимеш, що розпад переслідує тебе, наче голодні вовки вночі. Ти побачиш, що її ласки схожі на залежність, на старого коханця, який досі прагне бути поруч із тобою. Але ці речі можна відігнати. Вони контролюватимуть тебе лише тоді, коли ти їм це дозволиш.$B$BІди зараз, повертайся до мене, коли станеш сильнішим.",
},

[3099] = {
    en = "Tainted Scroll",
    T = "Зіпсований сувій",
    D = "Ах, поки ти був зайнятий боротьбою з бездумним Плетищем, тобі надійшов цей сувій. Гадаю, це щось важливе, оскільки, судячи з усього, на ньому стоїть печатка інструктора чаклунів Максиміліона. Я б приділив трохи часу, щоб прочитати його, перш ніж знову вирушати в дорогу.",
    O = "Прочитайте «Заражений сувій» і поговоріть із Максиміліоном у Дескнелі.",
    P = "Вітаю тебе, $gbrother:sister;. Я знав, що ти прийдеш. Це було лише питанням часу.$B$BТе, що я сказав, зацікавило тебе, чи не так? Я зачепив за живе… щось у тобі підказало, що те, про що я говорив, — правда. Добре.$B$BАле знай: я не зрадник Сильвани. Навпаки, вона б оцінила мої слова, зважаючи на те, що саме її власні переконання привели Забутих до того становища, в якому вони перебувають зараз.",
    C = "Я згадував, що раб залишається рабом, незалежно від господаря. Пам’ятаєш? Ми обоє знаємо, що саме такий тип контролю — така влада — зараз рухає нами. Ми прагнемо, щоб істоти служили нам. Ми знаємо, що ми сильніші й заслуговуємо на більшу повагу, ніж нам виявляють інші… і тому тепер ми прагнемо її здобути.$B$BЯ буду твоїм союзником у цій боротьбі — боротьбі за нашу власну свободу. Свободу самостійно обирати, кому бути відданим. Коли відчуєш, що готовий, повернися до мене, і я навчу тебе всьому, що знаю.",
},

[3100] = {
    en = "Simple Letter",
    T = "Простий лист",
    D = "Мене попросили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Схоже, це лист, запечатаний гербом Ллейна, нашого місцевого інструктора з бойових мистецтв. Я б не зволікав і прочитав його, перш ніж братися за будь-які інші справи тут, в Абатстві.",
    O = "Прочитайте «Простий лист» і поговоріть з Ллейном Бешером в абатстві Нортшир.",
    P = "А, ти отримав мій лист, $N... добре.$B$BОстаннім часом до Елвіна хлинув потік воїнів — це добре для Штормвінда, але погано для коболдів і Дефіасів у цій місцевості.",
    C = "Приведіть себе до ладу, вивчіть околиці та повертайтеся до мене, коли вам знадобиться тренування. Я буду тут і вдень, і вночі.$B$BЛицарі Срібної Руки добре попрацювали, щоб зробити це місце досить безпечним, але, коли ти познайомишся з іншими мешканцями, думаю, ти побачиш, що в усіх них є проблеми, з якими їм потрібна допомога — допомога, яку $C може їм надати. Удачі.",
},

[3101] = {
    en = "Consecrated Letter",
    T = "Освячений лист",
    D = "Мене попросили звернути твою увагу на це, щойно ти повернешся з таборів коболдів, $N. Схоже, це лист, запечатаний гербом брата Самуеля, нашого місцевого інструктора-паладина. Я б не вагався прочитати його, перш ніж ти візьмешся за будь-які інші справи тут, в Абатстві.",
    O = "Прочитайте Посвячений лист і поговоріть із братом Саммуелем в абатстві Нортшир.",
    P = "Нарешті! Ми зустрілися віч-на-віч, брате $gbrother:sister;. Ласкаво прошу до Нортширу. Це буде твій тимчасовий притулок, поки ти освоїш усі тонкощі того, як тут все влаштовано, але знай: Штормвінд недалеко, і рано чи пізно твій шлях приведе тебе туди. А доти — наберися терпіння... Лицар Срібної Руки.",
    C = "Тим часом тобі слід знати ще одну-дві речі. Ти є символом для багатьох на цій землі — поводься відповідно. Святе Світло сяє в тобі, і це буде очевидно як для твоїх союзників, так і для ворогів.$B$BКрім того, у міру набуття мудрості та сили тобі знадобиться тренуватися, щоб опанувати нові вміння. Ось тут я й приходжу на допомогу. Коли відчуєш, що набув певного досвіду тут, у Нортширі, повернися до мене, і я навчу тебе того, до чого, на мою думку, ти вже готовий. Удачі... $c!",
},

[3102] = {
    en = "Encrypted Letter",
    T = "Зашифрований лист",
    D = "Мене попросили звернути вашу увагу на це, щойно ви повернетеся з таборів коболдів, $N. Схоже, це лист, запечатаний гербом Йоріка, одного з наших місцевих інструкторів. Я б не вагався прочитати його, перш ніж ви візьметеся за будь-які інші справи тут, в Абатстві.",
    O = "Прочитайте зашифрований лист і поговоріть з Йоріком Керріданом у стайні за абатством Нортшир.",
    P = "Ти дістався сюди цілим і неушкодженим, і, схоже, тебе не бачило багато людей. Мені цього достатньо. Я не люблю, коли тут, у глибині, до мене привертають занадто багато уваги... краще тихо й спокійно. Впевнений, ти мене розумієш.$B$BУ тебе вже були якісь неприємності? Радий чути, що ні. Але це скоро зміниться.",
    C = "Ти переконаєшся, що є чимало угруповань, які зацікавляться нашими навичками, $N. Пригодники, SI:7... чорт забирай, навіть Братство Дефіаса не відмовилося б від одного-двох шпигунів у Штормвінд. Але пам’ятай: ти сам собі господар. Не дозволяй нікому змушувати тебе робити те, чого ти не хочеш! До того ж, усі козирі у нас на руках… принаймні, доки гра не закінчилася. Розумієш, про що я? $B$B У будь-якому разі, просто хотів представитися й повідомити, що я тут, якщо тобі знадобиться тренування. Заходь у будь-який час.",
},

[3103] = {
    en = "Hallowed Letter",
    T = "Священний лист",
    D = "Мене попросили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Схоже, це лист, запечатаний гербом жриці Анетти, нашої місцевої інструкторки-жриці. Я б не вагався прочитати його, перш ніж ти візьмешся за будь-які інші справи тут, в абатстві.",
    O = "Прочитайте «Священний лист» і поговоріть із жрицею Анеттою в абатстві Нортшир.",
    P = "Ах, нарешті ти прийшов. Я знав, що ти знайдеш дорогу до мене. Святе Світло осяює тебе і шлях, який ти обрав. Ці часи важкі — Палкий Легіон досі присутній в Азероті, весь Калімдор шукає нові способи захиститися від власних випробувань, і саме тобі належить допомогти якомога більшій кількості людей.",
    C = "Коли ти набудеш більше досвіду, повертайся до мене, і я зроблю все, що в моїх силах, щоб поділитися з тобою своїми знаннями. А до того часу йди з милосердям у серці, і нехай мудрість буде твоїм провідником. Пам’ятай: світ стане кращим лише тоді, коли ти сам цього досягнеш.",
},

[3104] = {
    en = "Glyphic Letter",
    T = "Гліфічна літера",
    D = "Мене попросили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Схоже, це лист, запечатаний гербом Келдена, нашого місцевого наставника-мага. Я б не вагався прочитати його, перш ніж ти візьмешся за будь-які інші справи тут, в Абатстві.",
    O = "Прочитайте «Гліфічний лист» і поговоріть з Келденом Бременом у абатстві Нортшир.",
    P = "Привіт, $N. Мене звати Кхелден. Чим можу допомогти?",
    C = "Ха-ха, я знав, що моя записка не відверне тебе від обраного шляху. Тож ти готовий, так? Готовий прийняти свою долю? Готовий кинути виклик богам та будь-яким іншим силам, що стануть на твоєму шляху у прагненні до знань і влади?$B$BНе буду брехати, $N, тебе будуть не тільки поважати, а й боятися. Але знай також: я буду поруч, коли тобі знадобиться тренування. Просто звернися до мене, коли станеш сильнішим.",
},

[3105] = {
    en = "Tainted Letter",
    T = "Зкомпрометований лист",
    D = "Мене попросили звернути твою увагу на це, щойно ти повернешся з таборів кобольдів, $N. Судячи з усього, це лист, запечатаний гербом Друзілли, однієї з наших місцевих інструкторок. Я б не зволікав і прочитав його, перш ніж братися за будь-які інші справи тут, в Абатстві.",
    O = "Прочитайте «Заражений лист» і поговоріть із Друзіллою Ла Салль, яка знаходиться поруч з абатством Нортшир.",
    P = "Ага, отже, ти приїхав, і якраз вчасно, $N. Щойно тут були деякі охоронці і кидали на мене цікаві погляди… жалюгідні смертні.",
    C = "У міру того, як ти набиратимешся сили, на тебе чекатимуть спокуси — ти повинен завжди пам’ятати про те, щоб тримати себе в руках. Я не буду брехати — корупція може зачепити будь-якого практикуючого таємні мистецтва; особливо того, хто має справу зі створіннями з Викрученого Потойбіччя. Будьте терплячі й обережні... але не дозволяйте цьому придушувати ваші амбіції.$B$BКоли ви станете могутнішими, поверніться до мене, і я навчу вас більше про наші традиції.",
},

[3106] = {
    en = "Simple Rune",
    T = "Проста руна",
    D = "Поки ти мені допомагав, мені передали цю руну, щоб я передав її тобі. Коли буде нагода, знайди час, щоб її прочитати. Думаю, її надіслав інструктор воїнів Тран. Поглянь на неї і, коли буде можливість, знайди його в Анвілмарі.",
    O = "Прочитайте «Просту руну» та поговоріть із Траном Корманом у Долині Колдрідж.",
    P = "Чорт, сьогодні ж холодно, чи не так? Схоже, сніг ніколи не тане, $N.$B$BВи, мабуть, вже помітили, але в нашому місті тепер живуть гноми. Це тому, що їх просто винесло з власного дому вибухом. Не розказуйте про це нікому, але я їх майже не можу засуджувати — гадаю, я б теж вдався до вибухівки, якби Айронфордж заполонили Темні Залізні чи хтось подібний.",
    C = "Ще дещо, що ти, мабуть, також побачиш — просто щоб ти був у курсі: гноми, які в бою використовують магію замість рушниці. Дехто з нас почав поклонятися Святому Світлу, як деякі люди, і, нарешті, троги. Пізніше ти дізнаєшся про них більше, але зараз тобі достатньо знати, що я тут, щоб допомогти тобі.$B$BЯ тут, щоб навчити тебе, як стати справжнім $C. Коли вважатимеш, що тобі потрібне додаткове навчання, повертайся до мене, і я подивлюся, що зможу зробити.",
},

[3107] = {
    en = "Consecrated Rune",
    T = "Освячена руна",
    D = "Поки ти мені допомагав, мені передали цю руну, щоб я передав її тобі. Знайди час, щоб прочитати її, коли буде нагода. Гадаю, вона від інструктора-паладина Бромоса. Поглянь на неї і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Освячену руну» та поговоріть із Бромосом Грумнером у Долині Колдрідж.",
    P = "Отже, ти це зробив! І якраз вчасно. У Долині Колдрідж та за її межами ще багато чого потрібно зробити. Мені знадобиться твоя допомога так само, як і тобі — моя!$B$BТепер ти — лицар Срібної Руки, тож будь готовий виконувати свої обов’язки.",
    C = "Люди багато чого навчили нас про Святе Світло та про те, наскільки важливим є для них їхній орден… і для захисту всього Азерота. Ми глибоко поважаємо те, наскільки він просякнутий традиціями, і те, як одна-єдина постать, одна жертва, може стати вирішальною межею між стражданням і спасінням.$B$BНам з тобою доведеться деякий час працювати разом. Коли вважатимеш, що готовий, повертайся до мене, і ми подивимося, як організувати для тебе навчання. Адже не можна ж відправляти тебе у світ непідготовленим, чи не так?",
},

[3108] = {
    en = "Etched Rune",
    T = "Вигравірувана руна",
    D = "Поки ти мені допомагав, мені передали цю руну, щоб я передав її тобі. Знайди час і прочитай її, коли буде нагода. Думаю, її надіслав інструктор мисливців Торгас. Ознайомся з нею і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Вигравірувану руну» та поговоріть із Торгасом Грімсоном у Долині Колдрідж.",
    P = "Ти впорався! Радий це чути! Готовий побитися об заклад, що тобі навіть не довелося мене вистежувати, щоб знайти це місце. Ха-ха!$B$BНаша професія досить глибоко вкорінена в традиціях, $N. Навчитися орієнтуватися на місцевості. Навчитися вистежувати ведмедя в горах. Навіть просто вижити, покладаючись лише на кмітливість, вимагає неабиякої сміливості та хитрості. Гадаєш, ти на це здатний?",
    C = "Одне, про що ти завжди повинен пам’ятати, — це те, що ти мусиш поважати світ, у якому живеш. Звірі, які вирішили битися пліч-о-пліч з тобою; блиск твоєї зброї; вага твоїх боєприпасів; укус різкого вітру — усі ці речі ти повинен знати до найдрібніших подробиць.$B$BЯ зроблю все, що зможу, щоб допомогти тобі, але більша частина роботи — за тобою. Коли вважатимеш, що готовий, повертайся і поговори зі мною. Я буду тренувати тебе, коли зможу.",
},

[3109] = {
    en = "Encrypted Rune",
    T = "Зашифрована руна",
    D = "Поки ти мені допомагав, мені передали цю руну, щоб я передав її тобі. Коли буде нагода, знайди час, щоб її прочитати. Гадаю, вона від тренера розбійників Солма. Поглянь на неї і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Зашифровану руну» та поговоріть із Солмом Харгріном у Долині Колдрідж.",
    P = "Ти це зробив! Чудово!$B$BОстаннім часом у нас спостерігається сплеск активності, тож я радий, що до наших лав приєднався ще один член клану Айронфордж. На мій погляд, занадто багато з нас звертаються до магії та божественного. Я нічого не маю проти них та їхніх переконань, але немає нічого кращого, ніж холодне лезо в руці та тінь, що приховує тебе від світла, розумієш, про що я?",
    C = "У будь-якому разі, коли ти почнеш роздивлятися околиці Колдріджа, то, мабуть, рано чи пізно тобі знадобиться тренування. Просто повертайся до мене, коли відчуєш у цьому потребу, і я навчу тебе всьому, що знаю — то тут якийсь трюк, то там якийсь маневр. Знаєш, те, що допоможе тобі вижити й заробити трохи додаткових монет.$B$BНе забувай також про наших друзів-гномів... їм трохи не пощастило, зважаючи на те, що Гномереган... зруйновано. Їм знадобиться наша допомога, щоб почуватися тут як вдома.",
},

[3110] = {
    en = "Hallowed Rune",
    T = "Священна руна",
    D = "Поки ти мені допомагав, мені передали цю руну, щоб я передав її тобі. Знайди час, щоб прочитати її, коли буде нагода. Думаю, її надіслав інструктор-священик Брансток. Поглянь на неї і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Священну руну» та поговоріть із Бранстоком Халдером в Анвілмарі.",
    P = "Ой! Ти встигла, $N! Чудово!$B$BЯ саме хотів сказати, що вже майже втратив надію, що ти взагалі з’явишся… Розумієш, «втратив надію»? Це жарт, дівчинко… Ех, та нічого. Ти ж все одно не заради моїх поганих жартів сюди прийшла.",
    C = "Саме я можу навчити тебе, поки ти починаєш освоюватися в Долині Колдрідж. Коли відчуєш, що готовий, повертайся до мене, і ми подивимося, чи не навчити тебе одного-двох нових заклинань, щоб захистити долину від цих клятих трогів.$B$BСвітло на твоєму боці, як і весь Айронфордж, $N... тож не відчувай тиску, ніби ти мусиш стати кимось особливим.",
},

[3111] = {
    en = "Glyphic Rune",
    T = "Гліфічна руна",
    D = "Поки ти мені допомагав, мені передали цей меморандум, щоб я передав його тобі. Знайди час, щоб прочитати його, коли буде нагода. Гадаю, його надіслав інструктор магів Маррек. Ознайомся з ним і, коли буде можливість, знайди його в Анвілмарі.",
    O = "Поговоріть з Марреком Стромнуром в Анвілмарі.",
    P = "Так, що там? Говоріть голосніше, якщо не заперечуєте. Після кількох келихів елю я вже не дуже добре чую.",
    C = "Ось що тобі потрібно знати: не вплутуйся в надто великі неприємності. Заощадь трохи грошей, щоб купити мені елю... або будь-які заклинання, які тобі заманеться. Я буду тут, якщо я тобі знадоблюся або ти захочеш потренуватися... чи що завгодно.",
},

[3112] = {
    en = "Simple Memorandum",
    T = "Короткий меморандум",
    D = "Поки ти мені допомагав, мені передали цей меморандум, щоб я передав його тобі. Знайди час, щоб прочитати його, коли буде нагода. Гадаю, його надіслав інструктор-воїн Тран. Ознайомся з ним і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Простий меморандум» і поговоріть із Траном Хорманом у Долині Колдрідж.",
    P = "Ах, ну що ж, ще одна записка від $R, який виконує завдання... чи не кумедно? $B$BНі-ні, я тебе не дражню, малятко. Треба віддати належне твоїй наполегливості, це точно. Я б теж розлютився, якби Айронфордж захопили карлики Темного Заліза, тож не думай, що я не співчуваю твоїм стражданням...",
    C = "Ну, з огляду на те, що це твоя головна задача, чи як ти це там зараз називаєш, я дав слово, що зроблю все, що в моїх силах, аби ти та твої люди були готові повернути собі свій дім… і саме це я й збираюся зробити.$B$BКоли вважатимеш, що готовий, повертайся до старого доброго Трана, і я з радістю поділюся з тобою своїми знаннями. Твоє навчання обійдеться мені в певну суму, але це не буде надто дорого. Удачі.",
},

[3113] = {
    en = "Encrypted Memorandum",
    T = "Зашифрований меморандум",
    D = "Поки ти мені допомагав, мені передали цю записку, щоб я передав її тобі. Знайди час, щоб прочитати її, коли буде нагода. Гадаю, вона від того недобросовісного тренера Солма. Поглянь на неї і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте зашифрований меморандум і поговоріть із Солмом Харгріном у Долині Колдрідж.",
    P = "Радий, що ти отримав мою записку і завітав до мене. Вибач, що прикинувся, ніби це була службова записка від твоїх керівників… не хотів тебе образити. Просто я знав, що ми з тобою, разом з іншими нашими, маємо триматися разом.$B$BНе багато хто вважає, що найкраще на світі — це коли твої та мої люди затиснуті в одному місті, але я думаю, що ми зможемо все владнати. А ти що думаєш?",
    C = "Я тут в основному тримаюся осторонь, щоб нас не звинувачували у зникненні речей, але якщо тобі щось знадобиться — тренування чи ще щось — просто повертайся в будь-який час.$B$BМи з тобою домовилися. Ми знаємо, що в скрутну хвилину можна довіряти лише родині… і саме це у нас тут і є, чи не так? Незважаючи на те, що Гномереган… захоплено, і що б там не трапилося, ми маємо одне одного, щоб підтримати один одного. Правда ж?",
},

[3114] = {
    en = "Glyphic Memorandum",
    T = "Меморандум про гліфи",
    D = "Поки ти мені допомагав, мені передали цей меморандум, щоб я передав його тобі. Знайди час, щоб прочитати його, коли буде нагода. Гадаю, його надіслав інструктор магів Маррик. Ознайомся з ним і, коли буде нагода, знайди його в Анвілмарі.",
    O = "Прочитайте «Гліфічний меморандум» і поговоріть з Марріком Нуррібітом у місті Анвілмар, що розташоване над Долиною Колдрідж.",
    P = "Так, що ти сказав, $R? Говори голосніше, якщо не заперечуєш. Після кількох келихів елю я вже не дуже добре чую.",
    C = "О, так! Таємні мистецтва... звичайно ж.$B$BОсь що тобі потрібно знати, $N: не вплутуйся в надто великі неприємності. Заощадь трохи монет, щоб купити мені елю... або будь-які заклинання, які тобі можуть знадобитися. І тримайся подалі від Гномерегана. А в іншому — гарного тобі дня! Я буду тут, якщо тобі знадобиться моя допомога, якщо захочеш потренуватися... чи що завгодно.",
},

[3115] = {
    en = "Tainted Memorandum",
    T = "Скомпрометований меморандум",
    D = "Поки ти мені допомагав, мені передали цей меморандум, щоб я передав його тобі. Знайди час, щоб прочитати його, коли буде нагода. Гадаю, його надіслав інструктор чаклунів Аламар. Проглянь його і, коли буде нагода, знайди його в Анвілмарі.$B$BІ будь обережним, $N, твоїм не дуже довіряють у цих краях.",
    O = "Прочитайте «Зражену записку» та поговоріть з Аламаром Гріммом у місті Анвілмар, що розташоване над Долиною Колдрідж.",
    P = "Чудово! Ти, очевидно, отримав мою записку.$B$BНе звертай уваги на дурнів навколо тебе, $N. Святе Світло?! Меч і щит?! Це не шляхи для таких відкритих людей, як ми. Поглянь, що «звичайна» магія зробила з нашою батьківщиною. У поєднанні з тими проклятими майстрами наша раса ледь не вимерла. А тепер ми змушені покладатися на карликів — вони воліють витрачати час на союз із людьми, ніж допомагати нам відбудувати нашу власну батьківщину. Ми — ніби громадяни другого сорту. Ти бачив, як вони на нас дивляться?",
    C = "Але це все не має значення. Важливо те, що ти побачив своє власне Святе Світло! Ти знаєш, звідки насправді береться сила. Ти усвідомлюєш, що мати власних союзників набагато... розсудливіше. Особливих союзників. Союзники, які, незалежно від завдання, будуть слухатися до останнього подиху.$B$BІ саме тут я вступаю в гру, $N. Я можу навчити тебе основам цих особливих здібностей. Частіше звертайся до мене, і я зроблю все, що в моїх силах, щоб навчити тебе більшій кількості заклинань.",
},

[3116] = {
    en = "Simple Sigil",
    T = "Простий символ",
    D = "Цей символ мені передав посланець від нашої інструкторки з бойових мистецтв, Алісії. Схоже, Алісія хотіла б поговорити з тобою, коли у тебе з’явиться вільна хвилинка. Прочитай його, а потім віднеси їй.",
    O = "Прочитайте «Простий сигіл» і поговоріть з Алісією в Тіньовій Долині.",
    P = "Ти це зробив. Я так рада.$B$BЗа останні кілька років сталося багато чого, $N: створення Телдрасілу, спотворення багатьох лісових істот тут і за межами лісу, відкриття земель, які ми вважали втраченими для нас, таких як Фералас... стільки всього за такий короткий час.$B$BАле це лише деякі з причин, чому ми тут; найголовніша з них — захистити наш вид від подальшого зла.",
    C = "Незабаром ти побачиш на гілках нашого дому представників інших рас — нехай це не породжує в тобі жодних упереджень. Ми раді їх бачити. Вони допомагатимуть нам, коли зможуть. Не всі з них будуть альтруїстами, але їм слід надати певну дозу довіри.$B$BАле зараз це все не має значення. Зараз ми маємо зосередитися на тобі та на тому, як ти можеш допомогти нашому народу. Я тут саме з цією метою. Я навчу тебе мистецтву $C, коли ти станеш сильнішим. Повертайся до мене, коли забажаєш, і я зроблю все, що зможу, щоб допомогти тобі.",
},

[3117] = {
    en = "Etched Sigil",
    T = "Вигравіруваний символ",
    D = "Цей символ мені передав посланець від нашої тренерки мисливців, Аянни. Схоже, Аянна хотіла б поговорити з тобою, коли у тебе з’явиться вільна хвилинка. Прочитай його, а потім віднеси їй.",
    O = "Прочитайте «Вигравіруваний символ» і поговоріть з Аянною Еверстрайд на вершині Альдрасіла в Тіньовій Долині.",
    P = "Ти прибув, і якраз вчасно, $N. Ласкаво просимо до Шейдоуглену.$B$BСподіваюся, мій символ застав тебе в доброму настрої та здоровим?$B$BЯк я вже казав раніше, я тут, щоб навчити тебе бути $C; приручати звірів, які допомагатимуть тобі в бою; стріляти з лука з бездоганною влучністю; поважати землі, які ми називаємо домівкою, а також землі за їх межами.",
    C = "Коли ти пізнаєш те, чого може навчити тебе Шейдоуглен, завітай до мене — я допоможу тобі краще зрозуміти твою роль як $C і те, на що ти здатний.$B$BЦе небезпечні часи, $N, не недооцінюйте вміння своїх вихованців — у цьому світі є речі, небезпечніші, ніж ви можете собі уявити. Ідіть з Елуною і поверніться до мене знову.",
},

[3118] = {
    en = "Encrypted Sigil",
    T = "Зашифрований печатний знак",
    D = "Цей символ мені передав посланець від нашого тренера-розбійника Фрахуна. Схоже, Фрахун хотів би з тобою поговорити, коли у тебе з’явиться вільна хвилинка. Прочитай його, а потім віднеси йому.",
    O = "Прочитайте «Зашифрований печат» і поговоріть із Фрахуном Тіньовим Шепотом у Тіньовій Долині.",
    P = "Привіт, $N. Радий, що ти мене знайшов. Я подумав, що, можливо, ти заблукав по дорозі сюди.$B$BЗ тих пір, як я надіслав тобі свій символ, у Шейдоуглені нічого особливо нового не сталося, але збір інформації я залишаю на твій розсуд. Якщо хочеш, поговори з іншими людьми навколо Алдрасіля.",
    C = "А до того часу пам’ятай: у ці непевні часи такі, як ми, потрібні більше, ніж будь-коли. Мир з іншими расами може зруйнуватися в будь-яку мить, і ходять чутки, що деякі члени Орди прагнуть посіяти ще більше насіння недовіри. Пам’ятайте про це.$B$BКоли ви наберетеся сили й відчуєте, що готові, поверніться до мене сюди, і я подбаю про те, щоб ви пройшли відповідне навчання. Важливо, щоб ви, серед іншого, вміли поводитися зі своєю зброєю.",
},

[3119] = {
    en = "Hallowed Sigil",
    T = "Священний символ",
    D = "Цей символ мені передав посланець від нашої наставниці-жриці Шанди. Схоже, Шанда хотіла б з тобою поговорити, коли у тебе з’явиться вільна хвилинка. Прочитай це, а потім віднеси їй.",
    O = "Прочитайте «Священний символ» і поговоріть із Шандою в Алдрасілі.",
    P = "Мені приємно бачити, що ти прибув так швидко, $N. Ласкаво просимо.$B$BЯк ви, мабуть, вже чули, весь Телдрасіл вирує від приїздів і від’їздів мандрівників. Навіть членам Альянсу дозволили піднятися на гілки Телдрасіла, щоб зустрітися з іншими калдореями, які готуються до майбутніх пригод.",
    C = "Поки що не переймайся тим, що відбувається у світі під Телдрасілом. Для цього ще буде час пізніше. А зараз іди й поговори з іншими мешканцями Тіньової Долини — вони зможуть розповісти тобі більше про те, що сталося. Допоможи їм, як тільки зможеш, а коли відчуєш, що тобі потрібне додаткове навчання, повертайся до мене, і я навчу тебе всьому, на що здатний.",
},

[3120] = {
    en = "Verdant Sigil",
    T = "Зелена Печатка",
    D = "Цей символ мені передав посланець від нашого наставника-друїда, Марданта. Схоже, Мардант хотів би з тобою поговорити, коли у тебе з’явиться вільна хвилинка. Прочитай це, а потім віднеси йому.",
    O = "Прочитайте «Зелену печатку» та поговоріть з Мардантом Стронгоком у дереві Альдрасіл у Тіньовій Долині.",
    P = "Ах, юний $C. Бачу, ти з нетерпінням прагнеш продовжити навчання. Добре.$B$BЦікаво, чи ти вже провів багато часу в Смарагдовому Сні? Можливо, ти ще не готовий до цього... Згодом, я впевнений.$B$BАле до того часу нам слід обговорити інші питання.",
    C = "Поки що я буду твоїм наставником і провідником. Мій обов’язок — навчити тебе розшифровувати не лише те, що духи передають нам, а й усі тонкощі та таємниці Смарагдового Сну.$B$BУ міру того, як ти будеш навчатися й набирати сили, ти дізнаватимешся все більше про наш сонний транс. Але до того часу повертайся до мене так часто, як забажаєш, і я навчу тебе всьому, що можу, про звичаї нашого роду.",
},

[3121] = {
    en = "A Strange Request",
    T = "Дивне прохання",
    D = "У Неру Фаєрблейда в Оргримарі є те, що мені потрібно, щоб розпочати справу! Він приготував зілля, яке мені знадобиться для мого… ну, ти сам побачиш.$B$BА тепер біжи — до Оргримара. Ось, візьми це з собою. Це зменшена голова, яку я пообіцяв Неру в обмін на трави. Це голова якогось бідолашного гнома, на якого я натрапив у лісі. Я впевнений, що Нееру буде задоволений.$B$BТи знайдеш Нееру в «Тріщині Тіні».",
    O = "Віднесіть «Зменшену голову» до Неру Фаєрблейда в Оргримарі.",
    P = "Так?",
    C = "Я чекав, поки Узер’ї принесе це... $B$BДозвольте мені дати вам ту суміш трав, яку я приготував для його... ну, експериментів...",
},

[3122] = {
    en = "Return to Witch Doctor Uzer'i",
    T = "Повернутися до чаклуна Узер'ї",
    D = "Ось трави, $N. Віднеси їх до знахаря Узер’ї.$B$BБудь ласка, передай йому, що я задоволений зменшеною головою.",
    O = "Доставте мішечок із травами Неру до знахаря Узер'ї у Фераласі.",
    P = "Ти вже розмовляв з Неру?",
    C = "Це саме те, що мені потрібно для підготовки посудини муїсек, $N. Незабаром ми побачимо, чи виявляться мої останні заклинання такими ж потужними, як я сподівався.$B$BБудь ласка, зачекайте хвилинку. Я мушу провести ритуал і нанести трави.",
},

[3123] = {
    en = "Testing the Vessel",
    T = "Випробування судна",
    D = "Це буде випробуванням — як для ритуалу, який я провів, так і для твоїх здібностей. Візьміть цю посудину, $N. З її допомогою ви зможете зменшувати та утримувати в ній істот.$B$BВідправляйтеся в Глибинки та шукайте істот, відомих як «Дикі», які колись були улюбленцями богині нічних ельфів Елуни. Твоїми цілями є люті, примітивні або дикі совині звірі, $N. Вбий 10 таких істот і, скориставшись посудиною Муїсека, зменш їх та захопи, перш ніж їхні душі встигнуть втекти.",
    O = "Відправляйтеся в Глибинки та знайдіть Диких. Вбийте 10 з них, а потім за допомогою Посудини Муїсека зменшіть і захопіть убитих Диких.$B$BПринесіть 10 Муїсеків Диких та Посудину Муїсека до знахаря Узер’ї у Фераласі.",
    P = "Чи вдалося вам спіймати дикого звіра?$B$BЯкщо вам це вдасться, ми будемо готові зменшити розміри та спіймати муісеків — істот з Фераласу.",
    C = "У разі насильницької смерті муісек істоти може втекти й прагнути помсти. Зменшення істот, як ти це зробив, $N, не дає муісеку втекти. Тепер ми можемо використовувати його як завгодно!",
},

[3124] = {
    en = "Hippogryph Muisek",
    T = "Гіппогриф Муісек",
    D = "Оскільки ти довів, що є надійним і наділений здатністю користуватися посудиною «Муісек», я тепер хочу, щоб ти спіймав ще одну істоту.$B$BГіпогрифи вже багато років є вірними супутниками нічних ельфів; їхні душі віддані й непохитні.$B$BВаше завдання — вбити 10 гіпогрифів «Фрейфезер», і зробити це швидко, зменшити їх розміри та захопити за допомогою посудини, щоб зберегти їхній муісек. Ви знайдете гіпогрифів у Високій Пустелі, на південь від цього місця.",
    O = "Вбийте 10 гіпогрифів Фрейфезер будь-якого типу, а потім скористайтеся «Посудиною Муісека», щоб зменшити їх і захопити.",
    P = "Вам вдалося зловити гіппогрифів?",
    C = "Якщо після вбивства тварини ми дозволимо муісеку втекти, він може прийняти вигляд ще більшої істоти. Ми ніколи не будемо в безпеці від його помсти.$B$BЯ доручив тобі небезпечне завдання, $N. І знову ти впорався з ним на відмінно.",
},

[3125] = {
    en = "Faerie Dragon Muisek",
    T = "Феєчний дракон Муісек",
    D = "$N, далі я хочу, щоб ви зловили істоту, яка зовні може здаватися досить тендітною, але нас насправді цікавить саме її могутній дух. Феєричні дракони, про яких я говорю, слугували нічним ельфам як союзники. Ми мусимо захопити одного з них, щоб Орда також змогла скористатися цією силою духу.$B$BОсь муісек, $N. Вбий 8 ельфів-стрільців або ельфів-драконів і захопи їхніх муісеків. Їх можна знайти на захід від цього місця.",
    O = "Знищте 8 спрайт-дартерів або спрайт-драконів. Використовуйте «Посудину Муїсека», щоб зменшити розмір і захопити впольованих феєричних драконів.",
    P = "Чи вдалося вам вловити «муісек» феєричних драконів?",
    C = "Дякую, $N. Тепер ми зможемо скористатися духовними силами феєричного дракона.$B$BСподіваюся, ти готовий виконати для мене ще одне завдання.",
},

[3126] = {
    en = "Treant Muisek",
    T = "Треант Муїсек",
    D = "Наша наступна ціль — блукаючі лісові мандрівники, яких можна зустріти, блукаючи лісом, $N. Нічні ельфи залучили треантів як союзників у боротьбі проти Орди. Хоча вони й рухаються повільно, їхня роль як захисників незаперечна.$B$BНезабаром ми зможемо використати цю силу на свою користь.$B$BЗнайдіть 3 блукаючих лісових мандрівників; вбийте їх і за допомогою посудини муісек зменшіть та захопіть їх.",
    O = "Вбийте 3 блукаючих лісових мандрівників. Використовуйте «Посудину Муїсека», щоб зменшити та захопити повалених треантів.",
    P = "Чи вдалося вам сфотографувати блукаючих лісових мандрівників?",
    C = "Дякую, $N. Наша колекція muisek майже повна.",
},

[3127] = {
    en = "Mountain Giant Muisek",
    T = "Гірський велетень Муїсек",
    D = "Останнє завдання, яке я доручу тобі, — вирушити на північний захід і знайти останнього ворога.$B$BГірські велетні залишили гори, щоб допомогти нічним ельфам, коли у світі з’явився Палаючий Легіон. Ви впізнаєте їх за їхніми величезними розмірами та за тим, як земля починає тремтіти, коли ви рухаєтеся по їхній скелястій місцевості.$B$BЯ дуже хочу опанувати таку величезну силу. Вбийте 7 гірських велетнів, а потім за допомогою судна «Муїсек» захопіть їхнього могутнього муїсека.",
    O = "Знищте 7 сухопутних мандрівників або скельних велетнів. Використовуйте «Судно Муїсек», щоб зменшити та захопити в полон повалених гірських велетнів.",
    P = "Чи вдалося вам сфотографувати гірських гігантів?",
    C = "Тільки уявіть собі, які можливості відкриваються перед нами завдяки тому, що ми зараз маємо, $N. Разом із матеріалами, які ви зібрали, я зможу назавжди ув’язнити муїсек цих істот у будь-чому, що забажаю.",
},

[3128] = {
    en = "Natural Materials",
    T = "Натуральні матеріали",
    D = "Мені знадобляться певні матеріали, щоб завершити мою справу... Ти можеш зайнятися цим паралельно з іншими завданнями, які я тобі доручу.$B$BМені знадобиться розколоте поліно від треанта з Фераласу. Мінерали з нальотом — їх можна знайти на гірських велетнях та феєричних драконах на заході. Також знайдіть мені міцні сухожилля від совиних звірів з Глибин або гіпогрифів з Фераласу. Нарешті, мені знадобиться велика кількість металевих уламків від будь-якої з цих істот, про які я згадав.",
    O = "Принесіть 2 розколоті поліна, 6 вкритих нальотом мінералів, 20 шматків міцної сухожилля та 40 металевих уламків чаклуну Узер’ї в таборі Моджаче.",
    P = "Чи вдалося вам зібрати матеріали, які мені потрібні?",
    C = "Чудово! Ці матеріали в поєднанні з «муісеком» повинні дати саме ті результати, яких ми так прагнули.",
},

[3129] = {
    en = "Weapons of Spirit",
    T = "Зброя духу",
    D = "Наділення зброї «муісеком» — складний процес. Тепер, коли у мене є всі необхідні матеріали та «муісек» тих істот, яких ти спіймав, я можу розпочати. Будь ласка, зачекай; я повернуся за хвилину.",
    O = "Шаман Узер'ї просить вас зачекати хвилинку, поки він готує зброю.",
    P = "",
    C = "Як і обіцяно, ти можеш вибрати, $N. Муісек цих істот назавжди увічнено в силі цієї зброї.$B$BТепер ти можеш користуватися їхньою енергією як власною. Використовуй її з розумом.",
},

[3130] = {
    en = "Against the Hatecrest",
    T = "Проти «Hatecrest»",
    D = "На цьому етапі я переадресую вас до мого заступника, Латроніка. До цього часу він пильно стежив за військами нагів. Я оціню загальну ситуацію тут щодо нагів; хоч як би я хотів кинути проти них всі сили, залишити фортецю відкритою для прямого нападу Орди — або ще гірше — видається далеко не оптимальним варіантом.$B$BУ будь-якому разі, Латронікус чекає. Поки що ти добре попрацював, $n. Продовжуй у тому ж дусі.$B$BТи вільний.",
    O = "Зверніться до Латроніка Мунспіра у фортеці Фетермун.",
    P = "",
    C = "Чудово, $N — я ціную позитивне ставлення до справи у тих, з ким працюю.$B$BГенерал Фезермун доручив мені безпосередньо звернутися до нагів. У мене є два плани: по-перше, ми ослабимо їхні сили як чисельно, так і в плані командування; по-друге, ми з’ясуємо, що вони затівають у руїнах. З вашою допомогою ми протидіємо присутності нагів, не ставлячи під загрозу загальну безпеку фортеці.",
},

[3141] = {
    en = "Loramus",
    T = "Loramus",
    D = "То ти хочеш боротися з демонами? Тоді тобі варто вислухати мою історію.",
    O = "Послухайте, як Лорамус Таліпедес розповідає свою історію.",
    P = "Не перебивай мене, $r.",
    C = "Хай буде так...",
},

[3161] = {
    en = "Gahz'ridian",
    T = "Газ'рідіан",
    D = "$N, я — науковець, але в душі — ще й мисливець за скарбами!$B$BДавним-давно, коли ці землі ще заселяли тролі, вони створили велику кількість прикрас, зліплених за подобою Газ’рілли — гідри, яку вони шанували як богиню. Ці прикраси витесані з елемента, який я називаю «Газ'рідіан» на честь бога-гідри.$B$BЯ сам знайшов кілька таких, але хотів би мати ще більше для дослідження — може, ти зможеш їх знайти?$B$BЯ навіть винайшов детектор, завдяки якому знайти газ'рідіан — це простіше простого! Просто одягніть його — і пошук розпочнеться!",
    O = "Марвон Ріветсікер у Танарісі просить вас зібрати 30 газ'рідійських прикрас.",
    P = "У вас виникли якісь проблеми?$B$BГаз'рідіана можна зустріти практично будь-де в Танарісі, $N, тож продовжуйте шукати!",
    C = "Чудово; ці прикраси ідеально підходять для моїх занять. Дуже дякую за допомогу, $N.$B$BО, а можна мені повернути мій шолом?",
},

[3181] = {
    en = "The Horn of the Beast",
    T = "Ріг Звіра",
    D = "На гігантському розі є численні подряпини та тріщини. У шорстку поверхню встряг незвичайний металевий предмет.$B$BПри детальнішому огляді ви помічаєте, що цей метал — насправді зламана головка сокири. На металі викарбувано такі слова:$B$BВласність альпініста Пебблбітті.$B$BКоли ви намагаєтеся витягнути зламане лезо сокири, воно розлітається на мільйон шматочків.$B$BОй!",
    O = "Віднесіть «Гігантський ріг Маргола» альпіністу Пебблбітті.$B",
    P = "Ні, я не відкриватиму ворота.",
    C = "Що це у тебе там? Очевидно, підробка!$B$BЯ бачила Маргол на власні очі і точно знаю, що її ріг принаймні у вісім разів більший за той, що ти тримаєш у руках, $N. Ти, мабуть, відірвав його у штормоноса в Пустках. Ні, пані, Пебблбітті не обдуриш!",
},

[3182] = {
    en = "Proof of Deed",
    T = "Свідоцтво про право власності",
    D = "Ти хочеш, щоб я повірив у таку історію? У справжньому розі все ще застрягла б моя зламана сокирна головка.$B$BСлухай, віднеси цю очевидну підробку куратору Торіусу в Айронфорджі. Якщо він підтвердить твої слова, ти отримаєш доказ виконання завдання. Принеси мені цей доказ, і я дам тобі ключ від Палючої ущелини.$B$BРушай!",
    O = "Віднесіть «Гігантський ріг Маргола» куратору Торіусу в Айронфорджі.",
    P = "О, привіт, юний друже. Хочеш, щоб я провів тобі екскурсію по нашому музею?",
    C = "Що це таке?$B$BОй, я не вірю! Ти усвідомлюєш, що це у тебе тут, $R? Це ріг Маргола Гнівного! Маргол — бич усіх археологів, які коли-небудь ступали на землю Палючої ущелини.$B$BМожна мені його залишити?",
},

[3201] = {
    en = "At Last!",
    T = "Нарешті!",
    D = "Не можу повірити, що Пебблбітті засумнівалася в справжності рогу. Між нами кажучи, я думаю, вона просто заздрить. Я знаю, що вона дуже хотіла сама вбити ту тварину, з огляду на той «інцидент» і все таке.$B$BТо тобі потрібен доказ? Після того, як ти щойно зробив пожертву музею, це не буде проблемою.$B$B<Куратор Торіус починає заповнювати великий документ.>$B$BОсь і все! Можеш віднести це Пебблбітті.",
    O = "Поверніть «Доказ укладення угоди» альпіністу Пебблбітті.",
    P = "Я в це не вірю.",
    C = "Не знаю, як такий слабкий, як ти, зміг перемогти Маргола, але угода є угода. Ось ключ.$B$BЯкщо після цього з тобою щось трапиться, це буде тільки твоя вина.",
},

[3221] = {
    en = "Speak with Renferrel",
    T = "Зверніться до Renferrel",
    D = "Поки ти був у відрядженні, допомагаючи нашим «мисливцям за смертю», аптекар Ренферел надіслав тобі повістку. Він не розповів мені подробиць, але хотів поговорити з тобою про вовчі серця, які ти йому передав.",
    O = "Поговоріть з аптекарем Ренферрелом у «Гробниці».",
