},

[3261] = {
    en = "Jorn Skyseer",
    T = "Йорн Скайсір",
    D = "Твій час зі мною добіг кінця, $N. Щоб дізнатися більше, тобі слід вирушити до табору Таурахо на півдні й поговорити з Йорном Скайсіром. Він продовжить наставляти тебе.",
