    C = "",
},

[3367] = {
    en = "Suntara Stones",
    T = "Камені Сунтара",
    D = "<Доріус стогне.>$B$BЯ важко поранений, $r. У мене... паморочиться в голові... Світ крутиться... У мене... внутрішня кровотеча.$B$BЯ мушу повернутися до Айронфорджа. Допоможи мені, $N.$B",
