[3661] = {
    en = "Favored of Elune?",
    T = "Обранець Елуни?",
    D = "Вайлдкіни — досить непередбачувані істоти, $N. Хоча вони здатні на неймовірну лагідність, ці істоти проявляють надзвичайну лютість, якщо щось, що вони вважають важливим, опиняється під загрозою.$B$BХодять чутки, що цих звірів створила Елуна, і мені цікаво з’ясувати, чи це справді так.$B$BНещодавно я почув про популяцію вайлдкінів, що мешкають у Глибинних землях, — це люті, примітивні й дикі совині звірі. Їх можна знайти серед місцевої дикої природи. Чи не могли б ви зібрати для мене кілька пір’їн вайлдкінів?",
    O = "Зберіть 15 пір'їн диких звірів у Замежжя для Ерелас Амберскі в селі Рут'теран.",
    P = "Постарайся їх уникати, якщо це можливо, $N. «Вайлдкіни» можуть помилково сприйняти твій інтерес як намір заподіяти їм шкоду...",
    C = "Дякую, що приніс мені це, $N.$B$BЩо ти дізнався про Диких?$B$BМожливо, ці пір’я розкажуть нам більше. Люті монстри чи просто збиті з пантелику домашні улюбленці? Якось я хотів би дізнатися правду...$B$BЯ продовжуватиму свої дослідження — будь ласка, повернись і поговори зі мною ще раз, коли мине трохи часу.",
},

[3681] = {
    en = "Tome of Divinity",
    T = "«Трактат про божественність»",
    D = "Вибач, що перериваю твою подорож, $r, але я подумав, що тобі варто знати: нещодавно зі Штормвінда надійшло повідомлення з проханням, щоб паладини з’явилися там для проходження навчання.$B$BЯкби я не знав краще, то сказав би, що ти вже майже досягнув особливого моменту, і настав час почати вивчати Томів.$B$BШукай Дуторіана Ралла у Штормграді. Зазвичай він навчає паладинів у Соборі Світла.",
    O = "Поговоріть із Дуторіаном Раллом у Штормграді.",
    P = "",
    C = "Ласкаво просимо до Кафедрального собору Світла, $C.",
},

[3701] = {
    en = "The Smoldering Ruins of Thaurissan",
    T = "Тліючі руїни Тауріссана",
    D = "Відправляйтеся до тліючих руїн Тауріссана на Палаючих степах і зберіть якомога більше інформації.$B$BКажуть, що руїни усіяні таємничими реліквіями. Можливо, вам варто почати пошуки саме звідти, $N. Остерігайтеся охоронців Тауріссана: це вбивці, які охороняють руїни, захищаючи будь-які таємниці, що, можливо, досі там поховані.",
    O = "Відправляйтеся до руїн Тауріссана на Палаючих степах і зберіть інформацію з реліквій Тауріссана. Після того як ви зберете інформацію, поверніться до королівського історика Арчесонуса.",
    P = "Ви надаєте нову інформацію?",
