[3721] = {
    en = "An OOX of Your Own",
    T = "Ваш власний OOX",
    D = "",
    O = "",
    P = "",
    C = "Ти знайшов трьох моїх самонавідних роботів OOX! Ти зробив набагато більше, ніж від тебе вимагалося, тому я подарую тобі щось особливе в подяку за твою допомогу. Це мініатюрна версія того самого робота, якого ти вже встиг пізнати й полюбити — OOX!$B$BЗазвичай я б нікому не дозволив мати такий потенційно смертоносний пристрій, але ти мені дуже допоміг. До того ж — бойові механізми та логіка наведення в цьому екземплярі вимкнені.$B$BА в іншому — це, чорт забирай, справжній OOX!",
},

[3741] = {
    en = "Hilary's Necklace",
    T = "Намисто Хіларі",
    D = "Моя подруга Хіларі загубила своє намисто, і ми не можемо його знайти. Ми цілий день ловили рибу саме тут і вже обшукали цю місцевість. Єдине, що спадає мені на думку, — це те, що воно впало в озеро. Наші батьки не хочуть, щоб ми купалися в озері... моя мама каже, що під водою живуть якісь страшні істоти, але ти, здається, не боїшся страшних істот.$B$BЧи не міг би ти, будь ласка, знайти його для неї?",
    O = "Знайдіть намисто Хіларі та поверніть його Хіларі в Лейкширі.",
    P = "Привіт. Я сумую за своїм намистом. Мені його подарував тато. Тато каже, що в озері живуть монстри. Ти когось із монстрів побив?",
    C = "Дякую, що знайшли моє намисто, пане $C... Ви дуже добрі! Моя кішечка теж вам дякує — правда ж, Ефсі?",
},

[3761] = {
    en = "Un'Goro Soil",
    T = "Ґрунт Ун'Горо",
    D = "Як повідомляється, ґрунт кратера Ун’Горо наділений потужними магічними властивостями. «Коло Сенаріона» прагне дослідити цей ґрунт у великих кількостях; вирушайте в дикі землі Ун’Горо та здобуйте його достатню кількість для продовження наших досліджень.$B$BЦей багатий ґрунт час від часу видніється купами, а на деяких звірах можуть бути придатні для використання зразки. Віднесіть їх усі Геде; просто шукайте купи ґрунту та таурена, який викрикує накази. Він має добрі наміри, але краще не дратуйте його!",
    O = "Принесіть 20 зразків ґрунту Ун'Горо Геде на Старій Горі в Грім-Скелі.",
    P = "На відпочинок, рядовий. Якщо ти тут, щоб вивантажити землю з Ун’Горо — чудово! Інакше — забирайся геть.",
    C = "Ах, так, рядовий $N, навіть не намагайся допомогти мені пересипати цей ґрунт на ті купи! Якби Великі Духи хотіли, щоб це було зроблено, вони б дивом перенесли його туди, чи не так?!$B$BАрхідруїд Рунетотем хоче знову з тобою поговорити, але для виконання його наступного завдання тобі знадобиться рівень знань з травництва, як у підмайстра. Хоча, навіть якщо ти цього не знаєш, він все одно знайде тобі застосування.",
},

[3762] = {
    en = "Assisting Arch Druid Runetotem",
    T = "Допомога верховному друїду Рунетотему",
    D = "Вибачте, $c, але я хотів би попросити у вас трохи часу, якщо це можливо.$B$B«Коло Сенаріонів» у Громовому Утвірі дуже зацікавлене у допомозі досвідчених мандрівників, таких як ви, у важливому дослідницькому проєкті. Хоча я не знаю подробиць, можу повідомити, що очолює це дослідження ніхто інший, як сам Хамуул Рунетотем.$B$BБудь ласка, якщо ви зацікавлені, поговоріть з ним безпосередньо на Скелі Старших у самому Громовому Утворі.",
    O = "Поговоріть з верховним друїдом Хамуулом Рунетотемом у Громовому Утворі.",
    P = "",
    C = "Вітаю, $C; я радий, що ти зацікавився участю в нашому дослідженні. Роботи багато, і я б зробив тобі ведмежу послугу, якби сказав, що ця робота не є небезпечною. Сподіваюся, це вас не відлякає... але, судячи з вашого вигляду, я припускаю, що ви вже стикалися з небезпекою раніше.",
},

[3763] = {
    en = "Assisting Arch Druid Staghelm",
    T = "Допомога верховному друїду Стагхельму",
    D = "Вибачте, $c, але я хотів би попросити у вас трохи часу, якщо це можливо.$B$B«Коло Сенаріону» у Дарнассусі шукає досвідчених мандрівників, таких як ви, щоб вони допомогли їм у надзвичайно важливому науковому проекті. Хоча я не знаю подробиць, можу повідомити, що очолює це дослідження ніхто інший, як сам архідруїд Фандрал Стагхельм.$B$BБудь ласка, якщо ви зацікавлені, поговоріть з ним безпосередньо в Енклаві Сенаріону, що знаходиться в самому Дарнассі.",
    O = "Поговоріть з верховним друїдом Фандралом Стагхельмом у Дарнассусі.",
    P = "",
    C = "Ну що ж, $c... оскільки тобі повідомили, що я сам очолюю це дослідження, ти, очевидно, приїхав так швидко, як тільки міг.$B$BТепер, коли ти вже тут, обов’язково слухай уважно, коли я вперше розповім тобі про деталі; я не маю бажання повторюватися.",
},

[3764] = {
    en = "Un'Goro Soil",
    T = "Ґрунт Ун’Горо",
    D = "Як повідомляється, ґрунт кратера Ун'Горо наділений потужними магічними властивостями. Я хочу відрізнити факти від вигадок; вирушай у дикі землі Ун'Горо й здобуй достатню кількість якісних зразків ґрунту для наших подальших досліджень.$B$BМожливо, ти вважаєш, що завдання зі збору зразків не гідні тебе; така поведінка не додає тобі симпатій ані в моїх очах, ані в очах Кола Сенаріона. Принеси зразки Дженалу, який, без сумніву, марнує час зовні, за цим деревом; просто шукай купки землі. Він займеться логістикою — а не я.",
    O = "Принесіть 20 зразків ґрунту Ун'Горо Дженалу в «Енклаві Сенаріону» у Дарнассі.",
    P = "Ах так, земля. Архідруїд вимагає по двадцять вантажів на кожного мандрівника, і двадцять вантажів він отримає. Нехай ті, хто змовився проти нас, залишаться на узбіччі!",
    C = "Вивантажте тут свій дорогоцінний вантаж, благородний $c. Це, мабуть, було чималим тягарем… подібним до того, який несу я, будучи провидцем. Ось винагорода за вашу працю, згідно з вказівкою самого Архідруїда.$B$BАрхідруїд Стагхельм хоче знову поговорити з тобою $N, але для виконання його наступного завдання тобі знадобиться хоча б базове розуміння травництва. Однак навіть якщо ти цього не знаєш, ти все одно зможеш допомогти Колу!",
},

[3765] = {
    en = "The Corruption Abroad",
    T = "Корупція за кордоном",
    D = "Штормвінд — такий жвавий центр життя.$B$BЯ прибув здалеку, щоб попросити про допомогу. Часто чути, що цими міськими вулицями бродять відважні мандрівники.$B$BМій брат, Гершала, потребує допомоги в Темному березі. Він мешкає в приморському містечку Обердін.$B$BПодорож довга й епічна. Саме тому я прошу допомоги у досвідченого $c, такого як ви.",
    O = "Відправляйтеся до Гершали Найтвіспер в Аубердіні.",
    P = "",
    C = "А, то це мій брат Аргос тебе прислав? Я розумію, що ти, мабуть, втомився від подорожі. Але нам є про що поговорити.",
},

[3781] = {
    en = "Morrowgrain Research",
    T = "Дослідження «Морроугрейн»",
    D = "За допомогою так званого «Вічнозеленого мішечка» ми виростили насіння Тарлендріса в ґрунті з кратера Ун’Горо. Це насіння дало порожні, потужні трави, що з’являються у випадковому порядку. Одним із результатів є «зерно завтрашнього дня» — таємнича трава, про яку ми мало що знаємо; я маю намір розгадати цю таємницю.$B$BВіднесіть це Матренгілу, що знаходиться внизу, і він дасть вам трохи насіння, щоб ви могли розпочати роботу. Якщо воно закінчиться, вам доведеться придбати у нього ще.",
    O = "Віднесіть ваучер на «Насіння верховного друїда» до Матренгіла Беарвокера в Енклаві Сенаріону в Дарнассусі.",
    P = "Нехай тобі супроводжують мир і спокій, друже. Ти тут у справах від самого Верховного друїда, чи не так?",
    C = "Так, цей ваучер дає право на двадцять пачок насіння. Якщо вони закінчаться, ми можемо надати ще. На жаль, виробництво насіння Тарлендріса у великих обсягах є досить дорогим. Саме тому «Коло Сенаріона» просить тих, хто нам допомагає, взяти на себе частину витрат.$B$BТі, хто повертається з зерном завтрашнього дня, переконуються, що винагорода, яку пропонує Архідруїд, з лишком компенсує витрати.",
},

[3782] = {
    en = "Morrowgrain Research",
    T = "Дослідження «Морроугрейн»",
    D = "За допомогою так званого «вічнозеленого мішечка» ми виростили насіння тарлендрісу в ґрунті з кратера Ун'Горо. З цього насіння виросло безліч різноманітних, випадкових, але потужних трав. Однією з них є «зерно завтрашнього дня» — таємнича трава, про яку ми мало що знаємо; я дуже сподіваюся розгадати цю таємницю для Кола.$B$BВіднесіть цей талон моїй дочці Башані, і вона дасть вам насіння, щоб ви могли нам допомогти. Якщо воно закінчиться, вам доведеться придбати у неї ще.",
    O = "Віднесіть ваучер на насіння Башані Рунетотему в Грім-Скелі.",
    P = "Нехай супроводжують тебе мир і спокій, друже. Ти тут у справах від самого Верховного друїда, чи не так?",
    C = "Так, цей ваучер дає право на двадцять пачок насіння. Якщо вони закінчаться, ми можемо надати ще. На жаль, виробництво насіння Тарлендріса у великих обсягах є досить дорогим. Саме тому «Коло Сенаріону» просить тих, хто нам допомагає, взяти на себе частину витрат.$B$BТі, хто повертається з «зерном завтрашнього дня», переконуються, що винагорода, яку пропонує Архідруїд, з лишком компенсує витрати.",
},

[3783] = {
    en = "Are We There, Yeti?",
    T = "Ми вже приїхали, Єті?",
    D = "Мої друзі завжди придумують чудові ідеї. Я ніколи не відчував, що можу з ними зрівнятися... аж до сьогодні! Я щойно склав креслення чогось неймовірного! Якщо ти пообіцяєш нікому не казати, я відкрию тобі секрет... $B$BЯ збираюся створити механічного єті! Мої друзі не тільки напевно злякаються, коли його побачать, але, коли оговтаються, я впевнений, що вони будуть вражені!$B$BДля початку мені потрібна густа шерсть єті з льодового чортополоху. Допоможеш? Ти знайдеш їх на південному сході.",
    O = "Зберіть 10 шматків густого хутра єті для Умі Румплснікер у Еверлуку.",
    P = "Мені тут є чим зайнятися. Будь ласка, принесіть мені ті хутра якомога швидше!",
    C = "Ці хутра просто ідеальні, $N. Ми чудово розпочали!",
},

[3784] = {
    en = "Assisting Arch Druid Runetotem",
    T = "Допомога верховному друїду Рунетотему",
    D = "Вибачте, $c, але я хотів би зайняти у вас лише хвилинку, якщо це можливо.$B$B«Коло Сенаріона» у Громовому Утворі дуже зацікавлене у досвідчених мандрівниках, таких як ви, які могли б допомогти їм у надзвичайно важливому дослідницькому проєкті. Хоча я не знаю подробиць, можу повідомити, що очолює це дослідження ніхто інший, як сам Хамуул Рунетотем.$B$BБудь ласка, якщо ви зацікавлені, поговоріть з ним безпосередньо на Скелі Старших у самому Громовому Утворі.",
    O = "Поговоріть з верховним друїдом Хамуулом Рунетотемом у Громовому Утісі.",
    P = "",
    C = "Вітаю, $C; я радий, що ти зацікавився участю в нашому дослідженні. Роботи багато, і я б зробив тобі ведмежу послугу, якби сказав, що ця робота не є небезпечною. Сподіваюся, це вас не відлякає... але, судячи з вашого вигляду, я припускаю, що ви вже стикалися з небезпекою раніше.",
},

[3785] = {
    en = "Morrowgrain Research",
    T = "Дослідження «Морроугрейн»",
    D = "Ось ваш «Вічнозелений мішечок», який знадобиться вам для використання насіння Тарлендіса. Також вам потрібно мати під рукою зразки ґрунту з Ун’Горо, щоб використовувати їх як добриво для насіння. Просто скористайтеся мішечком, коли все буде готово; мішечок подбає про решту.$B$BКоли у вас буде достатньо «зерна завтрашнього дня», принесіть його мені сюди, в анклав. Будь ласка, не турбуйте Архідруїда; він дуже зайнята людина, і йому не потрібно, щоб його відволікали щоразу, коли хтось повертається з черговою партією «зерна завтрашнього дня»!",
    O = "Візьміть мішечок «Евергрін» із пакетиком насіння «Тарлендіс» та двома зразками ґрунту «Ун’Горо», щоб спробувати виростити зразки «Моррограну».$B$BПринесіть 10 одиниць «Моррограну» Матренгілу Беарвокеру в Дарнассусі.",
    P = "Так, $N, чи виростив ти трохи зерна «завтра» для важливих досліджень Верховного друїда? Завдяки твоїй допомозі таємничі властивості кратера Ун'Горо стають дедалі зрозумілішими з кожним днем.",
    C = "Молодець, $N! Я обов’язково передам це самому Архідруїду, коли вони йому знадобляться. А поки що, будь ласка, прийми це як знак вдячності від Кола Сенаріона.$B$BНаша потреба в морові-зерні, поки що, залишається постійною; якщо ти бажаєш і надалі допомагати нам, то, будь ласка, повертайся, коли виростиш його ще більше.",
},

[3786] = {
    en = "Morrowgrain Research",
    T = "Дослідження «Морроугрейн»",
    D = "Ось ваш «Вічнозелений мішечок», який знадобиться вам для використання насіння Тарлендіса. Також у вас мають бути під рукою зразки ґрунту з Ун'Горо, які знадобляться як добриво для насіння. Просто скористайтеся мішечком, коли все буде готово; мішечок подбає про решту.$B$BКоли у вас буде достатньо зерна завтрашнього дня, принесіть його мені сюди, на Старшу Гору. Будь ласка, не турбуйте Архідруїда; він буде дуже зайнятий дослідженнями, а також безліччю інших турбот!",
    O = "Візьміть мішечок «Евергрін» із пакетиком насіння «Тарлендіс» та двома зразками ґрунту з Ун’Горо, щоб спробувати виростити зразки «Зерна Морроу».$B$BПринесіть 10 «Зерна Морроу» Башані Рунетотем у Грім-Скелі.",
    P = "Так, $N, чи виростив ти трохи зерна завтрашнього дня для важливих досліджень Верховного друїда? Завдяки твоїй допомозі таємничі властивості кратера Ун’Горо стають дедалі зрозумілішими з кожним днем.",
    C = "Молодець, $N, я обов’язково передам це самому Архідруїду, коли він цього потребуватиме. А поки що, будь ласка, прийми це як знак вдячності від Кола Сенаріона. $B$BНаша потреба в «зерні завтрашнього дня» наразі залишається постійною; якщо ти бажаєш і надалі допомагати нам, то, будь ласка, повертайся, коли виростиш його ще більше.",
},

[3787] = {
    en = "Jonespyre's Request",
    T = "Прохання від Джонспайра",
    D = "Вибачте, друже...$B$BМій колега хотів би поговорити з вами про дослідження, яке ви проводите спільно з Колом Сенаріона. Це друїд на ім’я Квінтіс Джонспайр, який мешкає у Твердині Фетермун у Фераласі. Він хотів би обговорити з вами питання щодо «зерна завтрашнього дня»... і дуже просить вас не розголошувати нашу розмову перед Верховним друїдом.$B$BЯкщо вас це цікавить, поговоріть з ним; без сумніву, все стане зрозумілим, щойно ви це зробите.",
    O = "Поговоріть із Квінтісом Джонспайром у фортеці Фезермун.",
    P = "",
    C = "Дякую, що завітав, втомлений мандрівнику! Дозволь представитися — я Квінтіс Джонспайр, друїд і скромний слуга Малфуріона та Кола Сенаріона. Мої колеги (генерал Шандріс Фетермун та Протекторат — можливо, ти про нас чув) і я хотіли б поговорити з тобою про роботу, яку ти виконуєш для Фандрала Стагхелма в Дарнассусі.$B$BПерш ніж ми підемо далі, я хотів би попросити, щоб наша розмова залишилася між нами. Якщо ти не маєш нічого проти, то можемо продовжувати.",
},

[3788] = {
    en = "Jonespyre's Request",
    T = "Прохання від Jonespyre",
    D = "Вибачте, друже...$B$BМій колега хотів би поговорити з вами про дослідження, яке ви проводите спільно з Колом Сенаріона. Це друїд на ім’я Квінтіс Джонспайр, і він мешкає тут, у Твердині Фетермун. Він хотів би обговорити з вами питання щодо «зерна завтрашнього дня»... і дуже просить вас не розголошувати нашу розмову перед Верховним друїдом.$B$BЯкщо вас це цікавить, поговоріть з ним; без сумніву, все стане зрозуміло, щойно ви це зробите.",
