[4001] = {
    en = "What Is Going On?",
    T = "Що відбувається?",
    D = "Поки що моє спілкування з карликом Хараном, який перебуває у камері навпроти, було обмеженим. Проте мені вдалося переконати його, що я, а точніше — ми — не маємо наміру заподіяти йому шкоди.$B$BПідійди до нього й дізнайся якомога більше про принцесу та її викрадачів. Передай цю інформацію вождю.$B$BТралл не хоче, щоб принцесі заподіяли шкоду, натомість він має якийсь грандіозний план, що передбачає її безпечне повернення до Айронфорджа. Харан уже все це знає... Іди!$B",
    O = "Поговоріть із Хараном Майтхаммером і з’ясуйте подробиці викрадення принцеси Мойри Бронзобороди. Передайте цю інформацію Тралу в Оргримарі.$B$BВи пригадуєте, що Гор’шак згадував, що Харан утримується в сусідній камері.$B",
    P = "Що привело вас на цю священну землю?",
    C = "Це шанс для Орди назавжди змінити політичну ситуацію у нашому розірваному війною світі. Слухай уважно, $N.$B$BНевдача цієї місії — не варіант.",
},

[4002] = {
    en = "The Eastern Kingdoms",
    T = "Східні Королівства",
    D = "Ти надав чудову інформацію, $N.$B$BЯк Вождь, я зобов’язаний робити те, що найкраще для Орди. Щоб майбутні покоління не були приречені на безнадійне існування.$B$BНам випала спільна нагода сформувати наші майбутні союзи. Допомога карликам може значно зміцнити наші відносини зі Східними Королівствами. Ось чому ти не маєш права на провал!$B$BТи готовий?",
    O = "Поговоріть із Тролом, якщо ви готові взятися за завдання, яке він підготував.",
    P = "",
    C = "З цього моменту назад дороги немає, $N.",
},

[4003] = {
    en = "The Royal Rescue",
    T = "Королівська рятувальна операція",
    D = "Цей удар по карликам Темного Заліза, якщо він буде успішним, викличе шокову хвилю в усьому їхньому королівстві.$B$BПринцеса Бронзоборода перебуває під контролем імператора Тауріссана. Щоб звільнити її, ви повинні вбити імператора. Майте на увазі: ваше завдання вдвічі небезпечніше, оскільки Бронзоборода, перебуваючи під контролем імператора, без вагань нападе на вас.$B$BНЕ ЗАВДАВАЙТЕ ЇЙ ШКОДИ!",
    O = "Знищте імператора Даграна Тауріссана та звільніть принцесу Мойру Бронзобороду від його злого закляття. $B",
    P = "<Принцеса Мойра тремтить від страху.>",
    C = "Що ти наробив!",
},

[4004] = {
    en = "The Princess Saved?",
    T = "Принцесу врятували?",
    D = "Ти вбив мого чоловіка, $r! Моя дитина з’явиться на світ без батька.$B$B<Принцеса Мойра вказує прямо на тебе.>$B$BЗапевняю тебе, ця дитина стане наступним правителем королівства Айронфордж. Тебе та таких, як ти, будуть переслідувати до кінця світу за цей злочин.$B$B<Ви вважаєте, що принцеса Мойра, можливо, страждає від залишкових ефектів заклинання Тауріссана.>$B$BЗалиште мене в спокої, $r. Я впевнена, що ваш вождь з нетерпінням чекатиме на результати свого втручання.$B",
    O = "Повернись до Тролла!$B",
    P = "",
    C = "<Трал здивований інформацією, яку ти йому повідомив.>$B$BНа горизонті замаячила нова загроза. З наближенням кінця життя Магні відкриється шлях для того, щоб цей ще ненароджений нащадок Темного Заліза став правителем Айронфорджа.$B$BТи виконав те, про що я тебе просив, і за це ти отримаєш нагороду.$B$BА тепер залиш мене, $N! Мені треба порадитися з Сильваною та Кейрном.",
},

[4005] = {
    en = "Aquementas",
    T = "Аквементас",
    D = "Візьміть цей мішок із припасами з собою до Танарісу. Подорожуйте до Загубленої бухти Ріггера і знайдіть коло з каменів.$B$BНайсхідніший півострів — це таємниця...$B$BЛише в цьому колі прочитайте з книги Аквора; викличте єдину істоту, яка може перетворити зібрані вами предмети на тотем для боротьби з Блейзерраннером.$B$BАквементас не буде радий, що його розбудили, але пам’ятайте: ви мусите залишатися в колі, щоб він міг перетворити предмети.",
    O = "Віднесіть «Книгу Аквора», «Срібні Кігті» та «Серце Залізного Дерева» до Танаріса.$B$BВикористовуйте «Книгу Аквора», щоб викликати Аквементаса.$B$BОтримавши готовий тотем, віднесіть його до Дж. Д. Коллі в Притулку Маршала.",
    P = "То ти повернувся, так? Хм... Дай-но я на це погляну, $N.",
    C = "«Блейзерраннер», кажеш...$B$BТак, я знаю, що в обвугленому центрі кратера мешкає могутній елементаль. Ми всі тримаємося на відстані; нікому ще не вдалося проникнути крізь потужну ауру, що оточує його. Багатьох, хто намагався протистояти йому, зіштовхнуло зі скелястих стежок на землю внизу.",
},

[4021] = {
    en = "Counterattack!",
    T = "Контратака!",
    D = "Орда високо оцінює ваші успіхи у боротьбі з колькарами, але самі колькари впали в сказ. Мені надійшли повідомлення, що загін колькарів вирушив до Пусток зі своєї батьківщини в Десоласі, щоб помститися. Згідно з моїм останнім повідомленням, навіть зараз вони наступають на ці бункери із заходу!$B$BЗустріньте нападників-колкарів і покладіть край їхній загрозі в Баренсах. Вбивайте їх, доки не з’явиться їхній ватажок, воєначальник Кром’зар. Переможіть його та принесіть мені шматок його прапора як доказ.$B$BМи розраховуємо на вас, $N.",
    O = "Принесіть шматок прапора Кром'зара Регтару Десгейту, що на захід від Перехрестя.",
    P = "У вас є цей банер?",
    C = "Ти це зробив! Ти переміг Колкара!$B$BЯ подбаю, щоб Трал дізнався про твої подвиги тут, $N.$B$BГордо тримай голову. Ти зробив честь собі та Орді.",
},

