[4024] = {
    en = "A Taste of Flame",
    T = "«Смак полум’я»",
    D = "Я прагну відчути на собі пекуче полум’я гори вогню. Щоб розплавлене полум'я Чорної Скелі прокотилося по всьому моєму єству. Ця суть, це пекуче тепло — саме цього я прагну.$B$BБель'Гар мешкає в Глибинах Чорної Скелі: істота з чистого полум'я, народжена з вогнів Рагнароса. Вбий Бель'Гара і принеси мені з його тліючих останків шматочок його внутрішнього вогню.$B$BВикористовуй розплав на його останках, щоб безпечно витягти внутрішнє полум'я.$B$BДосягни успіху — і отримай нагороду.",
    O = "Відправляйся до Глибин Чорної Скелі та вбий Бель'Гара.$B$BТи знаєш лише те, що велетень перебуває всередині Глибин Чорної Скелі. Не забудьте застосувати «Змінену линьку Чорного драконячого полку» до останків Бель'Гара, щоб здобути «Вогняну есенцію».$B$BПоверніть «Упаковану вогняну есенцію» Кірусу Терпентусу.$B",
    P = "Чи було повалено велетня?",
    C = "<Сайрус вириває з твоїх рук вогняну сутність.>$B$BТАК!$B$BЗабирай свою нагороду й зникай. Негайно зникни з моїх очей!",
},

[4041] = {
    en = "The Videre Elixir",
    T = "Еліксир «Відере»",
    D = "",
    O = "",
    P = "Принеси мені «Еворут», і, звичайно, я зможу приготувати тобі той еліксир «Відере».$B$BЯ знаю багато чого про трави та алхімію... О, давай я розповім тобі історію про те, як я перетворив на золото сир, який збирався з’їсти на обід... Гей... Куди ти йдеш?",
    C = "То ти, виходить, розіграв старого Міблона, так?",
},

[4061] = {
    en = "The Rise of the Machines",
    T = "Повстання машин",
    D = "Ми вперше помітили ці машини під час наших перших вилазок у Палючу ущелину. Після ретельнішого розслідування ми з’ясували, що їх ввозили з Палючих степів, можливо, з Глибин Чорної Скелі. Ось для чого ти нам потрібен, $N.$B$BТвоє перше завдання — вирушити до Палких степів і зібрати осколки стихій з кам’яних автоматів та дрібних кам’яних створінь цього регіону. Зібравши достатню кількість, повернися до мене, і я з’ясую їхнє походження.$B",
    O = "Відправляйтеся до Палаючих степів і знайдіть 10 розбитих осколків елементалів для ієрофантки Теодори Мулваданії.$B$BВи пригадуєте, що Теодора згадувала, ніби големи та елементалі цього регіону є джерелом цих осколків.",
    P = "Не ставтеся до цього завдання легковажно, $N!",
    C = "<Теодора розкладає уламки перед собою.>$B$B<Теодора уважно розглядає уламки через величезний монокль.>$B$BЦікаво. На структурній основі кожного з цих уламків викарбувані... ініціали.$B$B",
},

[4062] = {
    en = "The Rise of the Machines",
    T = "Повстання машин",
    D = "G.L.A.$B$BЦе «ініціали», викарбувані на осколках стихій. Під ініціалами знаходиться якесь позначення рангу. Механізми, які ви знищили в Палаючих степах, мали «Ранг IV». Припускаю, що це досить низький ранг.$B$BВіднесіть цей зразок уламка Лотвілу Вератіусу в табір на сході. Він — досить відомий вчений у галузі елементарних наук. Можливо, він зможе допомогти нам у наших пошуках.",
    O = "Віднесіть зразок осколка стихії Лотвілу Вератіусу.$B$BВи пригадуєте, що Теодора казала, ніби Лотвіл перебував у таборі на сході.$B",
    P = "Що це у тебе там, $R?",
    C = "<Обличчя Лотвіла зблідло.>$B$BЯ... Я впізнаю ці знаки.",
},

[4063] = {
    en = "The Rise of the Machines",
    T = "Повстання машин",
    D = "Це не може бути Аргелмах! Аргелмаха вбили десять років тому. Як я можу бути впевнений? Адже це я його вбив.$B$BВін був огидним карликом, який за всяку ціну прагнув спотворити справу мого життя, щоб задовольнити свої диявольські потреби. Схоже, що лиходії завжди знаходять спосіб уникнути правосуддя.$B$BЯкщо це справа рук Аргелмаха, то його треба знищити. Мені знадобляться зразки його останніх творінь. Маючи відповідні зразки, я, можливо, зможу зупинити це повстання. Ці творіння охороняють Аргелмаха в Глибинах Чорної Скелі.",
    O = "Знайдіть і вбийте Володаря големів Аргелмаха. Поверніть його голову Лотвілу. Вам також потрібно зібрати 10 неушкоджених елементальних ядер у големів «Роздирачів» та конструктів «Носіїв війни», які захищають Аргелмаха. Ви це знаєте, бо володієте екстрасенсорними здібностями.",
    P = "Чи це був він? Чи він справді був живий?",
    C = "Що це таке?!? Ця голова не з плоті. Це якесь творіння з темного заліза: Тінь Аргелмаха — ЩЕ ОДНА машина! Я підозрюю, що ваше знищення Аргелмаха буде недовготривалим, оскільки незабаром з’явиться інша, яка займе «його» місце.",
},

[4081] = {
    en = "KILL ON SIGHT: Dark Iron Dwarves",
    T = "ЗНИЩИТИ БЕЗ ПОПЕРЕДЖЕННЯ: Карлики Темного Заліза",
    D = "За наказом воєначальника Горезуба, командувача Експедиційного корпусу Каргата:$B$BУсі без винятку війська генерала Енгерфорджа, що знаходяться в Глибинах Чорної Скелі, мають бути знищені.$B$BВоїни Енгерфорджа — безжальні вбивці, винні у масовому вбивстві 109-ї дивізії Експедиційного корпусу Каргата. Героям рекомендується проявляти надзвичайну обережність під час зіткнень із цими нелюдами.$B$BКожен, хто знищить першу лінію військ генерала Енгерфорджа в Глибинах Чорної Скелі, отримає нагороду.",
    O = "Відправляйся в Глибини Блекрока та знищ огидних нападників!$B$BВоєначальник Гортус хоче, щоб ти вбив 15 гвардійців Анвілрейджа, 10 вартових Анвілрейджа та 5 піхотинців Анвілрейджа. Поверніться до нього, коли виконаєте завдання.$B",
    P = "Що таке, $r? Хіба ти не бачиш, що мені треба командувати взводом?$B$B",
    C = "Цей перший удар мав би змусити Ангерфорджа здригнутися. А тепер рухайся далі, солдате. Мені треба завершити роботу, спланувати битви, розгромити ворогів!$B$BПереглянь оголошення про розшук, щоб знайти ще роботу.",
},

[4082] = {
    en = "KILL ON SIGHT: High Ranking Dark Iron Officials",
    T = "ЗНИЩИТИ БЕЗ ПОПЕРЕДЖЕННЯ: Високопоставлені чиновники «Темного заліза»",
    D = "За наказом воєначальника Гортута, командувача Експедиційного корпусу Каргата:$B$BКерівник розвідувального підрозділу Е.К.К., Великий Майстер Лекслорт, повернувся з інформацією про місцеперебування високопоставлених чиновників «Темного заліза». За зачиненими воротами, неподалік від самого серця міста, вони готують свої війська, щоб знищити наших бійців. Рушайте до Глибин Чорної Скелі та знищіть їх!$B$BЗа виконання цієї місії ви отримаєте винагороду.$B",
    O = "Відправляйтеся в Глибини Блекрока та знищіть огидних нападників!$B$BПолководець Горезуб хоче, щоб ви вбили 10 медиків «Анвілрейдж», 10 солдатів «Анвілрейдж» та 10 офіцерів «Анвілрейдж». Поверніться до нього, коли виконаєте завдання.",
    P = "Знову ти? Треба віддати тобі належне, $N, ти справді наполегливий.",
    C = "«Ангерфордж», безсумнівно,… розлючений. Повертайся до мене, коли отримаєш третю данину, і ми приступимо до операції «Смерть Ангерфорджу». Я не можу вдаватися в подробиці того, що це означає, але будь впевнений: хтось загине.",
},

[4083] = {
    en = "The Spectral Chalice",
    T = "«Спектральний келих»",
    D = "",
    O = "",
    P = "Коштовні камені не видають жодного звуку, коли падають у глибину чаші...",
