},

[4084] = {
    en = "Silver Heart",
    T = "Срібне серце",
    D = "Я не знаю того, про кого ти говориш, $N.$B$BАле не хвилюйся; якщо твій друг вирушив у подорож, щоб знайти мене, я знаю, чого саме він прагнув.$B$BУ самому серці кратера Ун'Горо мешкає зло у найчистішій формі. Це зло приймає вигляд елементаля на ім'я Блейзерраннер... захищеного аурою, яку ніхто не може розвіяти...$B$BНіхто.... крім тих, хто має достатньо сили, щоб це зробити. Я можу навчити тебе цій силі, $N.$B$BСпочатку зроби те, про що я прошу. Збери 11 Сріблястих Кігтів та 1 Серце Залізного Дерева у істот у Фелвуді, а потім повернися.",
    O = "Зберіть 11 «Сріблястих кігтів» та 1 «Серце Залізного дерева» для Ерідана Блувінда у Фелвуді.",
    P = "Я можу розповісти тобі більше про силу, необхідну для перемоги над Блейзерраннером, але спершу тобі треба зібрати те, що мені потрібно.",
    C = "Гаразд, $N. Бачу, ти справді хочеш допомогти своєму другові.",
},

[4101] = {
    en = "Cleansing Felwood",
    T = "Очищення Фелвуда",
    D = "Рослини дарують життя Фелвуду, проте навіть вони страждають від скверни розтління. Я знаю способи їх очищення, але не можу ділитися цими знаннями з тими, кого не знаю або кому не довіряю. Доведіть мені, що ви справді допоможете справі Кола Сенаріона!$B$BНа півночі розкинулися Печери Залізного Дерева. Елементалів Варпвуду, що мешкають там, вже неможливо очистити. Я прошу тебе принести мені їхній сік — його називають «кров’яним бурштином» — щоб я міг дослідити його в надії врятувати інші форми життя в цих краях.",
    O = "Принесіть 15 одиниць «Кривавого бурштину» Аратандісу Сільверскі у Фелвуді.",
    P = "Я знаю, що Фелвуд страждає, $N — я страждаю разом із ним! Я мушу залишатися непохитним у своїх переконаннях; якби знання, якими я володію, потрапили в чужі руки, це означало б катастрофу для всього Фелвуда.$B$BПринесіть мені кривавий бурштин, видобутий із убитих елементалів Варпвуда, і я довірюся вам настільки, щоб ви допомогли мені знайти спосіб боротьби з розпадом.",
    C = "Цей кривавий бурштин знадобиться, щоб знайти спосіб подолати розтління, яке панує у Фелвуді. Ти довів мені, що готовий зробити все, що потрібно, заради Кола Сенаріона. Тепер я тобі довіряю, друже.$B$BМоже здатися дивним, що вбивство елементалів стало для мене доказом твоєї відданості, але мета — врятувати незліченну кількість розумних істот — виправдовує будь-які засоби. Тепер ми з тобою можемо зосередитися на збереженні життя за допомогою мазей, які я можу виготовити.$B$B$N, настав час очистити Фелвуд.",
},

[4102] = {
    en = "Cleansing Felwood",
    T = "Очищення Фелвуда",
    D = "Рослини дарують життя Фелвуду, проте навіть вони зазнають впливу скверни. Я знаю способи їх очищення, але не можу ділитися цими знаннями з тими, кого не знаю або кому не довіряю. Доведіть мені, що ви справді допоможете справі Кола Сенаріона!$B$BНа півночі розкинулися Печери Залізного Дерева. Елементалів Варпвуду, що мешкають там, вже неможливо очистити. Я прошу тебе принести мені їхній сік — його називають «кров’яним бурштином» — щоб я міг дослідити його в надії врятувати інші форми життя тут.",
    O = "Принесіть 15 одиниць «Кривавого бурштину» Мейбес Рівербріз у Фелвуді.",
    P = "Я знаю, що Фелвуд страждає, $N — я страждаю разом із ним! Я мушу залишатися непохитним у своїх переконаннях; якби знання, якими я володію, потрапили в чужі руки, це означало б катастрофу для всього Фелвуда.$B$BПринесіть мені кривавий бурштин, видобутий із убитих елементалів Варпвуда, і я довірюся вам настільки, щоб ви допомогли мені знайти спосіб боротися з розтлінням.",
    C = "Цей кривавий бурштин знадобиться, щоб знайти спосіб перемогти розтління, яке панує у Фелвуді. Ти довів мені, що готовий зробити все, що потрібно, заради Кола Сенаріона. Тепер я тобі довіряю, друже.$B$BМоже здатися дивним, що вбивство елементалів довело мені твою відданість, але мета — врятувати незліченну кількість розумних істот — виправдовує засоби, до яких ми вдаємося. Тепер ми з тобою можемо зосередитися на збереженні життя за допомогою мазей, які я можу виготовити.$B$B$N, настав час очистити Фелвуд.",
},

[4103] = {
    en = "Salve via Hunting",
    T = "Salve через Hunting",
    D = "",
    O = "",
    P = "Наявність маяка Сенаріону дозволяє бачити осколки спотворених душ на тих заражених звірах, яких знищують заради загального блага. Я перемелюю осколки на придатний для використання реагент, який використовується для виготовлення мазі з рослин Сенаріону. Ми будемо використовувати цю мазь, щоб знову перетворити спотворені рослини на здорові.$B$BВ обмін на ці осколки я дам вам трохи мазі з рослин Сенаріону, яку я вже приготував.",
    C = "Гаразд, ось ваші мазі з рослин Сенаріону. Прочешіть Фелвуд у пошуках спотворених рослин, $N! Де б вони не були, використовуйте мазь, яку я вам дав, щоб їх очистити.",
},

[4104] = {
    en = "Salve via Mining",
    T = "Salve через майнінг",
    D = "",
    O = "",
    P = "Якщо під час видобутку корисних копалин у Фелвуді у вас буде при собі маяк Сенаріону, ви зможете побачити заражений вітріол, який спотворює жилу сировини. Я знаю, як очистити цей вітріол і перетворити його на реагент, необхідний для виготовлення мазі з рослин Сенаріону. Потім ви зможете нанести цю мазь на рослини, які знайдете в дикій природі й які потребують порятунку.$B$BЯкщо ви зібрали заражену сірку, я дам вам трохи мазі для рослин Сенаріону, яку я вже приготував.",
    C = "Гаразд, ось тобі мазь із рослин Сенаріону. Якщо під час видобутку в Фелвуді знайдеш ще вітріолу, не забудь залишити її для мене! Чим більше її знайдеш, тим більше мазі я зможу приготувати.",
},

[4105] = {
    en = "Salve via Gathering",
    T = "Salve через Gathering",
    D = "У мене на думці є щось інше, ніж демони, друже. Моє плем’я, мої люди. Загублені у божевіллі злого, дуже злого вуду. Одного дня Лоа відвідали нашого Промовця у його сні. Лоа попросили створити потужне моджо — Моджо Снів.$B$BДля такого потужного моджо потрібна була освячена вода, освячена Драконами. Тож я вирушив до великого зеленого порталу. Там я зустрів демонів і забруднив руки їхньою кров’ю, а Говоритель втік! Коли я повернувся додому, мої власні люди з ворожістю посміхалися мені. Вигнали мене. «Ти не належиш до Тіньошкрябачів», — сказали вони.$B$BПогане, дуже погане вуду опанувало їхні розуми, друже. Але щоб виправити погане вуду, тобі доведеться заплатити кров’ю та добрим моджо. І ціну крові, і ціну магії можна сплатити в Зул’Хаті. Там ти знайдеш Оратора Ган’хоту з його «Магією Снів». Неподалік ти знайдеш Воєначальника Ханзенто, чию кров тобі треба пролити. Він — причина цієї дурості, і це — єдиний правильний спосіб навести лад!",
    O = "",
    P = "Маяк Сенаріону дозволяє досвідченому травнику виявляти підступний фел-порост — згубний породження зіпсованості Фелвуда. Моя робота тут дала мені знання про те, як очистити фел-порост і перетворити його на очищувальний реагент… який використовується в тому, що ми зараз називаємо «Сенаріонською рослинною маззю».$B$BЗбираючи трави у Фелвуді, ви натрапите на фель-порость, якщо матимете при собі маяк. В обмін на те, що ви принесете мені, я дам вам готову «Трав'яну мазь Сенаріону».",
    C = "Чудова робота, $n — кожна її частинка, щойно ми її очистимо, допоможе нам повернути Фелвуд. Ось, візьми кілька доз ценаріонської рослинної мазі й вирушай у ліс. Відновлення земель, уражених спотворенням, не терпить зволікань, $r!",
},

[4106] = {
    en = "Salve via Skinning",
    T = "Salve через Skinning",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволить досвідченому шкуроделу виявляти шматки зараженої шкіри серед здобичі, зібраної у Фелвуді. Я перетворюю ці, на перший погляд, марні шматки на густу пасту, яка слугує прискорювачем дії рослинної мазі Сенаріону. Коли ви зніматимете шкури зі своїх уловів тут, у Фелвуді, обов’язково майте при собі маяк!$B$BЗібравши заражені ділянки шкіри, принесіть їх мені, і я дам вам трохи рослинних мазей Сенаріону, які я вже приготував.",
    C = "Це саме те, що мені потрібно. Ось — візьми ці рослинні мазі й використай їх, щоб визволити Фелвуд від спотворення. Ми мусимо не здаватися, $n!",
},

[4107] = {
    en = "Salve via Disenchanting",
    T = "«Salve» через «Disenchanting»",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета проявляється через есенцію, яку він створює. Я придумав спосіб перетворити сиру есенцію, яку використовують чарівники, на реагент, придатний для створення ценаріонської рослинної мазі. Для цього не потрібен маяк Сенаріону; підійде будь-який відповідний розчарований предмет, з якого можна отримати меншу есенцію Нетера.$B$BМені потрібна лише одна менша есенція Нетера; натомість я дам вам мазі з рослин Сенаріону. Ця есенція надзвичайно потужна — навіть невеликої кількості вистачить надовго!",
    C = "Ось кілька мазей з рослин Сенаріону — для цього мені знадобиться лише одна мала есенція Нетера, $n. Есенція — це, безперечно, найдієвіший засіб, який я можу використати, щоб, так би мовити, перетворити мечі на плуги. Якщо тобі знадобиться ще мазі, то знайди мене тут!",
},

[4108] = {
    en = "Salve via Hunting",
    T = "Salve через Hunting",
    D = "",
    O = "",
    P = "Маючи Маяк Сенаріону, можна побачити уламок спотвореної душі на тих заражених звірах, яких знищують заради загального блага. Я перемелюю осколки на придатний для використання реагент, який використовується для виготовлення мазі «Ценаріонська рослина». Ми будемо використовувати цю мазь, щоб знову перетворити зіпсовані рослини на здорові.$B$BВ обмін на ці осколки я дам вам трохи мазі «Ценаріонська рослина», яку я вже приготував.",
    C = "Гаразд, ось твої мазі з рослин Сенаріону. Прочеши Фелвуд у пошуках спотворених рослин, $n! Де б вони не були, використовуй мазь, яку я тобі дав, щоб їх очистити.",
},

[4109] = {
    en = "Salve via Mining",
    T = "Salve через майнінг",
    D = "",
    O = "",
    P = "Якщо під час видобутку корисних копалин у Фелвуді у вас буде маяк Сенаріону, ви зможете побачити заражений вітріол, який роз’їдає жилу сировини. Я знаю, як очистити цей вітріол і перетворити його на реагент, необхідний для виготовлення мазі з рослин Сенаріону. Потім ви зможете нанести цю мазь на рослини, які знайдете в дикій природі й які потребують порятунку.$B$BЯкщо ви зібрали трохи зараженого вітріолу, я дам вам трохи мазі для рослин Сенаріону, яку я вже приготував.",
    C = "Гаразд, ось тобі мазь із рослин Сенаріону. Якщо під час видобутку в Фелвуді знайдеш ще вітріолу, не забудь залишити її для мене! Чим більше її знайдеш, тим більше мазі я зможу приготувати.",
},

[4110] = {
    en = "Salve via Gathering",
    T = "Salve через Gathering",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволяє досвідченому травнику виявляти підступний фел-порост — згубний продукт зіпсуття Фелвуда. Моя робота тут навчила мене, як переробляти фел-порост на очищувальний реагент… який використовується у тому, що ми зараз називаємо «маззю Сенаріону».$B$BЗбираючи трави у Фелвуді, ви натрапите на фель-порость, якщо матимете при собі маяк. В обмін на те, що ви принесете мені, я дам вам готову «Трав’яну мазь Сенаріону».",
    C = "Чудова робота, $n — кожна частинка цього, щойно ми її очистимо, допоможе нам повернути Фелвуд. Ось, візьми кілька доз мазі з рослин Сенаріону й вирушай у ліс. Відновлення цих земель від спотворення не терпить зволікань, $r!",
},

[4111] = {
    en = "Salve via Skinning",
    T = "Salve через Skinning",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволить досвідченому шкуроделу виявляти шматки зараженої шкіри серед здобичі, зібраної у Фелвуді. Я перетворюю ці, на перший погляд, непотрібні шматки на густу пасту, яка слугує прискорювачем дії рослинної мазі Сенаріону. Коли ви зніматимете шкури з вбитих тут, у Фелвуді, обов’язково майте при собі маяк!$B$BЗібравши заражені ділянки, принесіть їх мені, і я дам вам трохи рослинної мазі «Сенаріон», яку я вже приготував.",
    C = "Це саме те, що мені потрібно. Ось — візьми ці рослинні мазі й використай їх, щоб звільнити Фелвуд від спотворення. Ми мусимо не здаватися, $n!",
},

[4112] = {
    en = "Salve via Disenchanting",
    T = "«Salve» через «Disenchanting»",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета відчувається завдяки есенції, яку він створює. Я придумав спосіб перетворити сиру есенцію, яку використовують чарівники, на відповідний реагент для створення ценаріонської рослинної мазі. Для цього вам не потрібен маяк Сенаріону; підійде будь-який відповідний розчарований предмет, який дає нижчі есенції Нетера.$B$BМені потрібна лише одна нижча есенція Нетера; натомість я дам вам мазі з рослин Сенаріону. Ця есенція надзвичайно потужна — навіть невеликої кількості вистачить надовго!",
    C = "Ось кілька мазей з рослин Ценаріону — для цього мені знадобиться лише одна менша есенція Нетера, $n. Есенція — це, безперечно, найдієвіший засіб, який я можу використати, щоб, так би мовити, перетворити мечі на плуги. Якщо тобі знадобиться ще мазі, то знайди мене тут!",
},

[4113] = {
    en = "Corrupted Songflower",
    T = "Зіпсована пісенна квітка",
    D = "",
    O = "",
    P = "Ви знайшли хвору, пошкоджену рослину, яка, судячи з усього, є пісенною квіткою. Від рослини виходить різкий, неприємний запах. Щоб повернути її до нормального стану, їй терміново потрібна якась допомога.",
    C = "Ви наносите на пісенну квітку трохи мазі з рослин Сенаріону. Вона одразу ж починає позбуватися своєї спотвореної форми, перетворюючись на яскраву й здорову рослину.",
},

[4114] = {
    en = "Corrupted Songflower",
    T = "Зіпсована пісенна квітка",
    D = "",
    O = "",
    P = "Ви знайшли хвору, пошкоджену рослину, схожу на пісенну квітку. Від неї виходить різкий, неприємний запах. Щоб повернути її до нормального стану, їй терміново потрібна якась допомога.",
    C = "Ви наносите на пісенну квітку трохи мазі з рослин Сенаріону. Вона одразу ж починає позбуватися своєї спотвореної форми, перетворюючись на яскраву й здорову рослину.",
},

[4115] = {
    en = "Corrupted Windblossom",
    T = "Зіпсована Вітроквітка",
    D = "",
    O = "",
