[4223] = {
    en = "The True Masters",
    T = "Справжні майстри",
    D = "<Магістрат Соломон зітхає.>$B$BТи повинен повернутися до Палаючих степів, $N. Як представник Штормвінда, ти повинен будеш звітувати перед маршалом Максвеллом. Удачі.",
    O = "Поговоріть із маршалом Максвеллом у Палаючих степах.",
