},

[4224] = {
    en = "The True Masters",
    T = "Справжні майстри",
    D = "Що? Ти думав, що ти перший? Скільки ще солдатів ми маємо втратити, перш ніж Штормвінд вживе заходів?$B$BМи зібрали величезний обсяг розвідувальних даних щодо загрози з боку Чорної Скелі, перш ніж втратили нашого командира, маршала Віндзора. Разом із маршалом Віндзором зникла вся наша цінна інформація.$B$BНам потрібні саме ці документи. Поговоріть із Раггедом Джоном, $N. Він був разом із Віндзором, коли на них напав рейдовий загін «Чорної скелі». Востаннє його бачили в печері на півночі.",
    O = "Поговоріть із Раггедом Джоном, щоб дізнатися про долю маршала Віндзора, а після виконання цього завдання поверніться до маршала Максвелла.$B$BВи пригадуєте, що маршал Максвелл сказав вам шукати його в печері на півночі.",
    P = "Ти вже поговорив з Джоном?",
    C = "Я міг би попередити тебе, але яка в цьому цікавість?",
},

[4241] = {
    en = "Marshal Windsor",
    T = "Маршал Віндзор",
    D = "То цей нікчемний боягуз каже, що Віндзор живий, так?$B$BОдягайся, заступнику, ти йдеш туди, щоб знайти його. Якщо Віндзор живий, ти маєш привести його назад. Якщо він мертвий, я хочу доказів.$B$B<Максвелл сміється.>$B$BБ’юся об заклад, тобі вже набридло це чути, чи не так?",
    O = "Відправляйтеся до гори Блекрок на північному заході та зайдіть у Блекрокські глибини. Дізнайтеся, що сталося з маршалом Віндзором.$B$BВи пригадуєте, як Рейггед Джон розповідав, що Віндзора відвели до в’язниці.",
    P = "",
    C = "Де він! Я його вб'ю!",
},

[4242] = {
    en = "Abandoned Hope",
    T = "Втрачена надія",
    D = "Болвар — дурень. Я збирав його дорогоцінні «докази», щоб потім засунути їх йому в горло.$B$BВін — сліпий блазень. Докази лежать за два фути від нього, а він їх не бачить.$B$BЩо стосується моїх даних, то вони втрачені. Зникли. Невідновні.$B$BЯкщо я колись знайду Айронфоу і виберуся з цього лабіринту, моєю першою зупинкою буде Штормвінд, щоб всадити свій молот між очей того плазуна.$B$BЗалиш мене, $N.",
    O = "Передайте маршалу Максвеллу погані новини.",
    P = "",
    C = "Схоже, він збожеволів.$B$B<Максвелл схиляє голову в знак скорботи.>$B$BДуже прикро, що колись гордий і благородний воїн перетворився на повного божевільного. МАБУТЬ, ми зайшли в глухий кут...$B$BЯ мушу винагородити тебе за твої зусилля до цього моменту, $N.",
},

[4243] = {
    en = "Chasing A-Me 01",
    T = "У гонитві за A-Me 01",
    D = "На жаль, з одним із моїх найвидатніших винаходів щось сталося. Ви ж бачили механічних білок, правда? Що ж, щоб наблизитися до мавп кратера Ун'Горо, я створив механічну мавпу, яка б не виділялася серед них — я назвав її А-Ме 01.$B$BВона має пророчі самоцвіти замість очей, тож я міг бачити все, що бачила вона. Вона дісталася до Грибної Скелі — лігва мавп — трохи на схід відсюди, і саме тоді я втратив з нею зв’язок. Останнє, що я побачив, — це одного з їхніх альфа-самців, який кинувся до неї, щоб привітатися!$B$BЧи можете ви допомогти мені її знайти?",
    O = "Знайдіть A-Me 01 у кратері Ун'Горо.",
    P = "",
    C = "Оглядаючи A-Me 01, ви помічаєте дві величезні вм'ятини, які псують вигляд того, що, на думку Карни, є безперечно майстерно виконаним інженерним творінням. Одна вм'ятина прикрашає плече A-Me 01, інша — її голову.$B$BПри детальнішому огляді стає зрозуміло, що її компоненти, схоже, не отримують живлення.",
},

[4244] = {
    en = "Chasing A-Me 01",
    T = "У гонитві за A-Me 01",
    D = "Трохи докладніше оглянувши, ви помічаєте панель, що відсувається. Над електропроводкою чітко написано: «Замініть мітріловий кожух, вимкніть, а потім увімкніть живлення».$B$BПриділивши хвилину, щоб замінити панель, ти замислюєшся, чи справді так просто буде полагодити A-Me 01 і повернути її до Карна Ремтревел поблизу Притулку Маршалла.$B$BЦе можна дізнатися, лише спробувавши.",
    O = "Знайдіть мітріловий футляр і поверніться до А-Ме 01 у кратері Ун’Горо.",
    P = "Відсік, у який вставляється мітріловий кожух, досі щільно закритий. Решта A-Me 01 залишається неактивною.",
    C = "Ви знову знімаєте панель з задньої частини A-Me 01 і обережно виймаєте старий мітріловий кожух, який, судячи з усього, згорів. Новий кожух легко вставляється на місце. Єдине, що залишається зробити, якщо проблема була саме в мітріловому кожусі, — це перевести перемикач у положення «Вимкнено», а потім знову у положення «Увімкнено».",
},

[4245] = {
    en = "Chasing A-Me 01",
    T = "У гонитві за A-Me 01",
    D = "Щоб перевірити, чи готові ви відвести A-Me 01 назад до Карна Ремтревел, ви перемикаєте перемикач у положення «Вимкнено». Ще раз озирнувшись, щоб переконатися, що жодна з горил не наближається, ви готуєтеся побачити, що станеться, коли ви знову переведете перемикач у положення «Увімкнено».$B$BЦе ваш останній шанс... Ви впевнені, що саме цього хочете?",
    O = "Супроводити A-Me 01 назад до «Карна Ремтревел» у кратері Ун'Горо.",
    P = "Тобі вдалося допомогти А-Ме? Те, що ти згадав про пошкоджений мітріловий корпус, було влучним припущенням щодо причини несправності. Я впевнений, що якщо ти його заміниш, вона знову запрацює і зможе повернутися додому.",
    C = "О, ти це зробив! Чудово! Дякую, $N.$B$BО, моя бідна А-Ме. Подивись на всі ці вм'ятини. Трохи попрацюємо — і вона знову запрацює як нова.$B$BЩе раз дякую, $N. Я це дуже ціную.",
},

[4261] = {
    en = "Ancient Spirit",
    T = "Стародавній дух",
    D = "Колись Фелвуд був мирною та спокійною землею... Доки Легіон не захопив її. Пекельні істоти, руйнування, хаос...$B$BЧереп Гул'дана гарантував, що тут ніхто не уникнув долі. Усі піддалися спотворенню.$B$BНавіть зараз, ставши духом, я все ще перебуваю в пастці, несучи на собі страждання цієї землі. Допоможи мені знайти шлях додому. Будь ласка, $N, скажи, що ти виведеш стародавнього духа звідси, де я нарешті зможу спочивати.$B$BКоли я звільнюся, знайди Кейнета Стілвінда — друїда, який мешкає у Лісовій Пісні, на сході.",
    O = "Супроводи Арея в безпечне місце, а потім поговори з Кейнетом Стілвіндом у «Лісовій пісні», що на сході Попелястої долини.",
    P = "Що ти бачив на цій розбещеній землі?",
    C = "Так, $N. Фелвуд пережив чимало випробувань. Дякую тобі за те, що ти зробив.$B$BМожливо, одного дня нам вдасться звільнити Фелвуд від розтління; кожен добрий вчинок має значення.",
},

[4262] = {
    en = "Overmaster Pyron",
    T = "Верховний володар Пірон",
    D = "Останні п’ятеро моїх магів, які пішли нишпорити в Чорноскельну Гору, повернулися вкрай підсмаженими, з постійною помаранчевою гном’ячою зачіскою — або й гірше.$B$B<Джалінда підбирає з землі трохи попелу й розвіює його в повітря.>$B$BОдин особливо підступний тип, Верховий Майстер Пірон, здається, завдає чимало клопоту. Нам потрібно знищити цього елементаля, щоб наша експедиція змогла пробратися в Глибини Чорної Скелі!$B$BВін охороняє вхід до Кар’єру Чорної Скелі.",
    O = "Знищте надмайстра Пірона та поверніться до Джалінди Спріг.$B$BВи пригадуєте, як Джалінда згадувала, що Пірон охороняє кар’єр. Можливо, варто пошукати його саме там?",
    P = "<Схоже, Джалінда дивиться тобі прямо на голову.>",
    C = "Інсендіус? Ой-ой...",
},

[4263] = {
    en = "Incendius!",
    T = "Інсендіус!",
    D = "Ти впевнений, що Пірон сказав «Інсендіус», коли помер?$B$B<Джалінда з трудом ковтає слину.>$B$BКажуть, що лорд Інсендіус — посіпака Рагнароса! Ой-ой, ой-ой... що ж нам тепер робити?$B$BЯк гадаєш, чи впораєшся з ще одним завданням? Мені більше нікого відправити, $N!$B$BМи ніколи не зможемо проникнути туди, якщо Інсендіус і далі буде воскрешати Пірона з попелу.$B$BТобі доведеться знайти й знищити лорда Інсендіуса!$B",
    O = "Знайдіть лорда Інсендіуса в Глибинах Чорної Скелі та знищіть його!",
    P = "Той негідник помер??",
    C = "Ой! Ти впевнений, що Інсендіус сказав «Рагнарос»?$B$B<Джалінда подає тобі щось і погладжує тебе по зап’ястку, занурившись у глибокі роздуми.>",
},

[4264] = {
    en = "A Crumpled Up Note",
    T = "Зім'ята записка",
    D = "Поверхня записки вкрита плямами. Текст ледь розбірливий, але ви розпізнаєте таке:$B$B...солодка іронія...$B$B...падіння розбитого Альянсу...$B$B...якби не старанність генерала Енгерфорджа, ми, можливо, ніколи б не розгадали схему шифрування...$B$B...Аргелмах майже завершив розшифрування записок Віндзора.$B$BНаш володар підніметься з глибин і розтрощить усіх, хто залишився...$B$B— Імператор Дагран Тауріссан.$B",
    O = "Можливо, ви щойно натрапили на щось, що зацікавило б маршала Віндзора. Можливо, все-таки є надія.",
    P = "<Маршал Віндзор дивиться на записку у вашій руці.>$B$BЩо це у вас там, $N?",
    C = "<Маршал Віндзор бере записку і починає читати.>",
},

[4265] = {
    en = "Freed from the Hive",
    T = "Звільнений з «Улья»",
    D = "Коли ти торкаєшся капсули, вона трохи розсувається, відкриваючи чоловіка-нічного ельфа, який, на диво, все ще живий. Він, здається, у доброму здоров’ї, хоча й глибоко приголомшений. Коли ти допомагаєш йому вибратися з капсули, він приходить до тями.$B$B«Слава Елуні — ти врятував мене, друже! Я... Я — Рашал, і я прокинувся паралізованим усередині цього капсули після того, як ці комахи мене переповнили. Тебе послала Твердиня?»$B$BСхоже, ти знайшов зниклого кур'єра!",
    O = "Визволіть Рашала з вулика Зуккаша.$B$BПоверніться до Гінро Херткіндла у фортеці Фетермун і повідомте йому, що Рашал живий і здоровий.",
    P = "У вас є про що повідомити, $n?",
    C = "Ласкаво просимо додому, $N. Рашал щойно зв’язався зі мною і розповів, що сталося.$B$BЯ… ні, вся «Фортеця» навіть не знає, як подякувати тобі за твій величний вчинок; Без твоєї своєчасної допомоги Рашал загинула б, а ти надав її нам, навіть не зажадавши ні найменшої винагороди найманця. Ти — справжній герой. Знай, що в Гінро Герткіндлі ти завжди матимеш друга.",
},

[4266] = {
    en = "A Hero's Welcome",
    T = "Героїчний прийом",
    D = "$N, генерал Шандріс Фезермун хотіла б поговорити з вами особисто. Без сумніву, вона хоче подякувати вам за службу на користь Твердині, але я знаю, що вона також хоче поговорити з вами про комахоподібних істот, з якими ви та Рашал зіткнулися на півдні Фераласу. Звіти про тих комах-зук'ашів... щонайменше, жахають.$B$BГенерал Фезермун чекає на вас у головному комплексі.",
    O = "Поговоріть із Шандріс Фезермун у фортеці Фезермун.",
    P = "",
    C = "$N, я висловлюю вам свою найщирішу подяку за допомогу, яку ви нам надали. Ваша хоробрість у боротьбі з переважаючими силами заслуговує на нагороду, яка в тисячу разів перевищує її вартість. Проте я сподіваюся, що ви приймете це від імені всієї Твердині.$B$BА тепер, якщо дозволите... Я хотів би ще раз попросити вас про допомогу. З огляду на виявлення вулика Зуккаш тут, у Фераласі, я вважаю, що ви — найкращий вибір для цієї місії.",
},

[4267] = {
    en = "Rise of the Silithid",
    T = "Повстання силітидів",
    D = "Я доручаю вам копію звіту, який підготував Рашал щодо зараження південно-східної частини Фераласу. Поки основний звіт подається до Дарнассуса, я хочу, щоб ви передали цю копію одному зі співробітників Протекторату. Її звати Грасіна Спірітмайт; вона — жриця, яка мешкає у Храмі Місяця в Дарнассусі. Вона має глибокі знання про таких істот, і отримання нею цього звіту піде на користь нам усім.$B$BВи вільні — удачі, $N; нехай Елуна береже нас усіх.",
    O = "Віднесіть звіт Рашала до Грасіни Спірітмайт у Дарнассусі.",
    P = "Ласкаво просимо до цього благословенного храму, друже. Мені було передбачено, що ти прибудеш сюди з фортеці Фетермун. Чи є у тебе звіт, який Шандріс Фетермун попросила тебе принести?",
    C = "Ми, нічні ельфи, знаємо про жах, описаний у цьому звіті. Шандріс мудро вчинила, надіславши мені цей звіт і тебе.$B$BЦі істоти швидко поглинуть Фералас; вони є однією з найбільших загроз, з якими нам усім коли-небудь доведеться зіткнутися. Комахи, з якими зіткнулися ти та кур'єр, відомі як силітиди. Вони — лише знаряддя однієї з найбільших загроз, з якими коли-небудь зіткнуться як Орда, так і Альянс.$B$BЯ молюся, щоб ми мали рішучість перемогти їх, перш ніж вони знищать нас.",
},

[4281] = {
    en = "Thalanaar Delivery",
    T = "Доставка в Таланаар",
    D = "Цю посилку з товарами, яку ви знайшли в таборах гнолів Вудпоу, слід було доставити до невеликої проміжної станції Таланаар на південному сході Фераласу. Незалежно від долі зниклого кур'єра, завдання щодо доставки посилки залишається незавершеним.$B$BПри детальному огляді посилки на зовнішній стороні упаковки видно написане від руки ім'я «Фальфіндел Вейвардер». Можливо, це і є кінцевий одержувач посилки.",
    O = "Віднесіть недоставлену посилку Фальфінделу Вейвардеру в Таланаар.",
    P = "Ласкаво просимо до Таланаара, $C. Вам потрібна якась допомога?",
    C = "Слава Елуні, нарешті надійшла посилка з Твердині Фетермун!$B$BТе, що ти тут, наводить мене на думку, що, можливо, з нашим постійним кур’єром Рашалом сталося щось недобре. Сподіваюся, все владнається. Я знаю, що останнім часом «Дерев’яні Лапи» дуже схвильовані через якісь події на півдні. Можливо, він загинув у тих диких краях; я б на твоєму місці був обережним, друже.$B$BУ будь-якому разі, ще раз дякую. Ось винагорода за доставку цієї посилки.",
},

[4282] = {
    en = "A Shred of Hope",
    T = "Крихта надії",
    D = "<Маршал Віндзор схвильовано махає запискою.>$B$BТи усвідомлюєш, що це означає, $N?$B$BМожливо, ще не все втрачено! З того, що мені вдалося з’ясувати, ця інформація знаходиться у двох карликів Темного Заліза: генерала Енгерфорджа та володаря големів Аргелмаха. У мене таке відчуття, що вони не просто так віддадуть інформацію, якщо ми їх ввічливо попросимо.$B$BСподіваюся, ти готовий до бою.$B$BРушай у дорогу й знайди цих двох лиходіїв! Знищ їх і поверни мою втрачену інформацію.",
    O = "Поверніть втрачену інформацію маршала Віндзора.$B$BМаршал Віндзор вважає, що ця інформація перебуває у володінні лорда-голема Аргелмаха та генерала Енгерфорджа.",
    P = "Незабаром ця грандіозна інсценізація закінчиться.",
    C = "<Маршал Віндзор вихоплює дві таблички з ваших рук.>$B$BНам треба звідси тікати!",
},

[4283] = {
    en = "FIFTY! YEP!",
    T = "П’ЯТДЕСЯТ! ТАК!",
    D = "Я відкрию тобі маленький секрет, солдате. Підійди трохи ближче.$B$BЯ ТУТ ЄДИНИЙ НОРМАЛЬНИЙ!$B$BПоглянь на цих людей! Ти повіриш, що вони всі божевільні!? Так, вони такі! БОЖЕВІЛЬНІ! СХОЖІ НА ГОЛОВУ!$B$B<Ораліус знижує голос.>$B$BНехай це залишиться між мною, тобою та моїм приятелем капітаном Вінкі.$B$B<Ораліус хапає повітря і стискає його.>$B$BУ будь-якому разі... Я збираю значки, щоб доповнити свою колекцію вух огів. Сьогодні на черзі орки. П’ятдесят. Вперед!$B$B<Ораліус дує в ріг.>$B$BВІДПРАВЛЯЙТЕ!",
    O = "Ораліус хоче 50 медальйонів «Чорної скелі». Імовірність того, що ці медальйони можна знайти у орків на Палаючих степах, досить висока.",
    P = "<Ораліус розмовляє у досить велике відрізане вухо огра.>$B$B«Палаючі степи», прийміть зв’язок, вислухайте мене.",
    C = "Ти це зробив! Твоя нагорода: ПОГЛАДЬ МЕНЕ ПО ЧЕРЕВУ! ДАВАЙ! ПОГЛАДЬ!",
},

[4284] = {
    en = "Crystals of Power",
    T = "Кристали сили",
    D = "Я впевнений, ти їх помітив, $N. Вони всюди!$B$BПро що я говорю? Та про кристали, звичайно ж!$B$BКристали... Вони розкидані по всьому кратеру. Більшість людей їх ігнорує, але в мене є дивне відчуття, що вони приховують у собі якусь силу. Я вже деякий час проводжу тут з ними експерименти, але ніяк не можу нічого виявити. Принаймні, поки що не вдалося.$B$BСлухай, у мене трохи закінчуються кристали, що я тут маю — як думаєш, ти міг би зібрати для мене ще трохи?",
    O = "Зберіть по 7 кристалів сили кожного кольору: червоного, синього, жовтого та зеленого. Віднесіть їх до Дж. Д. Коллі в «Притулку Маршала».",
    P = "Я просто знаю, що тут я натрапив на щось важливе, $N!",
    C = "Тепер я продовжуватиму свої експерименти! Дякую, $N.",
},

[4285] = {
    en = "The Northern Pylon",
    T = "Північний пілон",
    D = "Для чого вони можуть бути? Я ніяк не можу викинути цю думку з голови!$B$BЦе зводить мене з розуму — що чутки, які я чув про кришталеві стовпи, — всі правдиві. Може, я й наївний, але зазвичай вірю в усе, що мені кажуть.$B$BУ будь-якому разі, я чув, що одна з кришталевих веж знаходиться досить близько. Десь на півночі... Будь ласка, знайди її, $N. Я просто знаю, що вони існують.",
    O = "Дізнайтеся, де розташована Північна кришталева вежа в кратері Ун’Горо.",
    P = "Ви вже відвідали пілон, $N?",
    C = "Я знаю, що ці історії справжні, $N.",
},

[4286] = {
    en = "The Good Stuff",
    T = "Найцікавіше",
    D = "Капітан Вінкі каже, що «Темні Залізні» у Глибинах заволоділи всім найкращим. Хіба не так, Вінкі?$B$B<Ораліус якнайкраще імітує пірата.>$B$BАРРР, ТОВАРИШУ! ПРАВИЛЬНО!$B$BРозумієш, про що я? Тобі треба туди залазити й принести мені кілька зразків того кращого.$B$BЗалазь туди й потруси своїм «грошовим деревом»!$B",
    O = "Відправляйтеся до Глибин Чорної Скелі та знайдіть 20 поясних сумок «Дарк-Айрон». Поверніться до Ораліуса, коли виконаєте це завдання. Ви припускаєте, що карлики «Дарк-Айрон» у Глибинах Чорної Скелі носять із собою ці дивні «поясні сумки».$B",
    P = "Зараз мені не до цього, $N. Нам з Вінкі треба йти на зустріч.",
    C = "<Ораліус починає порпатися в величезній купі поясних сумок.>$B$BО, ЧУДОВО!$B$B<Ораліус засовує свій великий ніс у купу й вдихає аромат.>$B$BЯК ПРИЄМНО ПАХНЕ! Поглянь на всі ці смаколики!$B$BВізьми собі один, $N. Усіх вистачить.",
},

[4287] = {
    en = "The Eastern Pylon",
    T = "Східний пілон",
    D = "Під час мого перебування тут я чув дивні чутки про таємничі опори, що нібито існують десь у пустелі кратера, $N. Я припускаю, що вони досить великі, а їхнє внутрішнє приміщення вистелене кристалами.$B$BХоча я ніколи їх не бачив, не можу позбутися думки, що чутки правдиві — і що ці пілони якось пов’язані з усіма кристалами, які ми знайшли$B$BТож чому б тобі не допомогти мені вгамувати мою цікавість? Кажуть, що один із них знаходиться у східній частині кратера. Як гадаєш, чи зможеш ти його знайти?",
    O = "Дізнайтеся, де розташований Східний кришталевий пілон у кратері Ун'Горо.",
    P = "Ви вже відвідали пілон, $N?",
    C = "Ун'Горо — таке дивне місце, $N. Коли потрапляєш у кратер, здається, ніби ти опинився в зовсім іншому світі...",
},

[4288] = {
    en = "The Western Pylon",
    T = "Західний пілон",
    D = "Мої експерименти поки що не дали жодних позитивних результатів, $N. Я не можу не сподіватися, що ти зможеш знайти рішення, розшукавши одну з опор, про існування яких я чув. $B$BМожливо, якщо ми поєднаємо на них певні кольори... але я забігаю наперед. Давайте спочатку їх знайдемо!$B$B$N, обшукай західну частину кратера; кажуть, що десь у цій місцевості знаходиться пілон.",
    O = "Дізнайтеся, де розташований Західний кришталевий пілон.",
    P = "Ви вже відвідали пілон, $N?",
    C = "Уздовж країв кратера є чимало прихованих ділянок. Спробуйте обстежити звивисті стежки, якщо вам більше нікуди шукати, $N.",
},

[4289] = {
    en = "The Apes of Un'Goro",
    T = "Мавпи Ун'Горо",
    D = "У цьому кратері мешкає безліч дивних істот — вони здаються більш благородними версіями тих істот, яких можна зустріти на всій території моєї батьківщини та за її межами. Я не можу цього пояснити, але це місце наче промовляє про Матір-Землю. Я віддаю їй шану щоразу, коли слідую за однією з її прекрасних істот по всій цій улоговині.$B$BЯкщо ти теж бажаєш відчути просвітлення, яке супроводжує такий великий подвиг, то рушай на північ. Там ти знайдеш великі мавпи, які стануть випробуванням сили для будь-якого смертного. Принеси мені їхні шкури… доведи свою силу.",
    O = "Принесіть 2 шкури горили з Ун'Горо, 2 шкури стомпера з Ун'Горо та 2 шкури громовержця з Ун'Горо до Торви-розвідника біля входу в кратер Ун'Горо.",
    P = "Чи ці істоти вже взяли над тобою гору, $N?$B$BНе здавайся так легко. Вистежити й перемогти мавп Ун’Горо — завдання не з легких, навіть для великого мисливця.",
    C = "Отже, ти довів свою силу — достатню, щоб перемогти великих мавп Ун'Горо — це добре. Це випробування було невеликим порівняно з Лар'корві, але я не заберу у тебе цю велику перемогу.$B$BЗ цих шкур вийде чудовий одяг для мого племені. Ти допоміг мені й довів свою гідність.$B$BПерш ніж ти вирушиш виконувати наступне завдання, давай віддаймо шану Матері-Землі та подякуємо духам тих мавп, яких ти вбив — вони мають знати, що їхня смерть не буде марною.",
},

[4290] = {
    en = "The Fare of Lar'korwi",
    T = "Страви Лар'корві",
    D = "Колись, дуже давно, один із моїх братів взяв трохи м’яса з улову Лар’корві. Він тоді про це не знав, але Лар’корві бачив його з лісу. Лар’корві переслідував мого брата кілька днів, знищуючи все, до чого той торкався. Мій брат, наляканий, врешті-решт вирішив втекти з Кратера й залишити Лар'корві позаду.$B$BЛар'корві вбив його неподалік від цього місця.$B$BЯкщо хочеш спровокувати Лар’корві, знайди його свіжу здобич і візьми з неї трохи м’яса.$B$BПотім повернися до мене.",
    O = "Знайдіть тушу останньої здобичі Лар'корві та заберіть шматок туші Трешадона, а потім поверніться до Торви-Слідопита в кратері Ун'Горо.",
    P = "Не став до моїх слів легковажно, $N. Якщо ти справді хочеш зіткнутися з цією істотою, то мусиш бути обережним… і кмітливим. Щоб виманити Лар’корві та перемогти його, знадобиться чимало сили та проникливості.",
    C = "Це підійде чудово, $N. Схоже, Лар'корві останнім часом добре харчується. Хоча цікаво, де він знайшов тресхадона в цих краях. Дивно.$B$BУ будь-якому разі, я збережу це, доки ти не будеш готовий до сутички з цією bestією. Не хвилюйся за мою безпеку — я впевнений, що ти розлютив Лар’корві настільки, що він не вб’є мене, доки не скуштує твого м’яса.",
},

[4291] = {
    en = "The Scent of Lar'korwi",
    T = "Аромат Лар'корві",
    D = "Я, чесно кажучи, здивований, що він ще не прийшов за тобою, $N. Але все гаразд, адже у мене є остаточний план, який приведе цього монстра до нас.$B$BСтатус домінуючого самця дає Лар'корві право спаровуватися з будь-якою самкою на свій вибір — і він обирає їх багато. На захід від цього місця ти знайдеш багато яєць равазаврів. Підійди до них ближче — це має спровокувати атаку його самок. Самки виділяють огидний запах із залози на голові, що дозволяє самцям зрозуміти, що вони готові до спарювання. Принеси мені дві такі залози.",
    O = "Принесіть 2 феромонні залози равазавра Торві-розвіднику біля входу до кратера Ун'Горо.",
    P = "Будь обережним, $N. Наближення до будь-якого гнізда з яйцями неодмінно спровокує матерів... навіть якщо ти вже здобув залозу від однієї з них. Матері можуть бути не менш смертоносними, ніж сам Лар'корві, коли вони борються за захист своїх дитинчат. Але якщо тобі це вдасться, ми отримаємо надійний спосіб виманити Лар'корві з укриття.",
    C = "О, чудові екземпляри, $N. Ці два шматки, які ти знайшов, мають ідеально підійти для того, щоб виманити Лар’корві на відкрите місце. Не можу дочекатися, щоб побачити, чим закінчиться твоя сутичка з цим монстром. Це величезна істота з пазурами, гострими, як найкращі мечі. Ти поглянеш йому в очі — і пізнаєш смерть.",
},

[4292] = {
    en = "The Bait for Lar'korwi",
    T = "Приманка для Лар'корві",
    D = "Це буде найскладніша частина, оскільки план має певну складність. На північ від цього місця ви знайдете невелику стежку, що веде в гори. Саме тут я востаннє бачив Лар’корві. Ви зрозумієте, що опинилися в потрібному місці, побачивши безліч кісток величезних істот, які колись блукали цими краями. Візьміть м’ясо, яке ви знайшли, і покладіть його туди. Потім натріть м’ясо цією сумішшю, яку я приготував. Якщо навіть ці дві принади разом не приведуть Лар’корві до вас, то я не знаю, що ще може це зробити.",
    O = "Використовуючи вміст мішечка Торви, приклич Лар'корві та переможи його. Потім віднеси голову Лар'корві до Торви-Слідопита, що знаходиться біля входу до кратера Ун'Горо.",
    P = "Не дай страху взяти над тобою гору, $N. Страх — це великий зрадник... ти повинен залишатися сильним!$B$BВізьми м'ясо, поклади його в маленьку долину, а потім застосуй до нього залозу. Тільки тоді смерть прийде за тобою.",
    C = "Слава Матері-Землі! Ти це зробив! Ти заслужив повагу, $N. Ти довів, що сам по собі є чудовим мисливцем. Твій дух сильний. Твоя хоробрість не має рівних. А твоя сила ще більше зміцніла. Я схиляюся перед твоїми вміннями.$B$BЛише найвеличніші з моїх предків могли б досягти чогось настільки неймовірного. Вітаю.",
},

[4293] = {
    en = "A Sample of Slime...",
    T = "Зразок слизу...",
    D = "Фелвуд — це ліс, що розташований далеко на північ від Пусток, навіть далі, ніж Попеляста долина. Там слизи мешкають навколо водойм, благословенних дотиком Фелу. Плеть спустошила цю місцевість атаками інферналів та іншої демонічної магії — вважається, що слизи виповзли з-під землі саме під час цих атак.$B$BЗберіть зразки слизу з Фелвуда, і ми використаємо обладнання для аналізу, що стоїть поруч зі мною, щоб створити контрольну групу для порівняння з іншими зразками, які ви зберете.",
    O = "Зберіть зразки слизу Фелвуда з будь-якого слизу в Фелвуді. Потім, скориставшись випробувальним обладнанням поруч із хіміком Фуелі в Андерсіті, перевірте, які з ваших зразків є найбільш зіпсованими. Принесіть хіміку Фуелі 5 знайдених вами зіпсованих зразків слизу Фелвуда.",
    P = "Мені знадобиться щонайменше п’ять зіпсованих зразків для нашої контрольної групи, $N. Продовжуй збирати зразки слизу з Фелвуда, доки не зможеш надати мені те, що нам потрібно. Так наказала леді Сильвана...",
    C = "А, чудово. Ці зразки підійдуть якнайкраще. Дякую вам за допомогу.$B$BКоли ми зберемо всі зразки слизу, зможемо з’ясувати більше. Я починаю підозрювати, що передчуття леді Сильвани були не тільки правильними, але й глибшими, ніж вона сама могла передбачити. Ці зразки дуже цікаві. Досить лише подивитися, як вони реагували на мої сполуки... хм, так, нам точно потрібно дослідити це далі.",
},

[4294] = {
    en = "... and a Batch of Ooze",
    T = "... і партія слизу",
    D = "Ти чув про кратер Ун'Горо, $N? Він розташований неподалік від пустелі Танаріс, і це чудове місце: пишне, яскраве, сповнене тварин і рослинності.$B$BСаме туди тобі й треба вирушити. До мене дійшли чутки, що це місце, здається, зовсім не зачеплене зовнішнім втручанням. Дослідники лише зараз відкривають його таємниці.$B$BЯ хотів би дослідити там слизових або мулових істот. Якщо це правда — що вони не зіпсовані — то я хотів би побачити, як еволюціонували такі істоти.",
    O = "Зберіть зразки слизу Ун'Горо з будь-якого слизу в кратері Ун'Горо. Потім, скориставшись випробувальним обладнанням поруч із хіміком Фуелі в Андерсіті, з'ясуйте, які з ваших зразків є найчистішими. Принесіть хіміку Фуелі 5 найчистіших зразків Ун'Горо, які ви знайдете.",
    P = "Так, $N? Як просувається пошук?",
    C = "Справді дивовижно, $N. Цей кратер Ун'Горо приховує набагато більше таємниць, ніж я очікував. Цікаво, що ще ми відкриємо під час подальших досліджень.$B$BПросто дивовижно... погляньте на чистоту цих зразків. Хм, цікаво, що це може означати. Здається, вони мають елементальну природу, але... є в них щось більше. Вони нагадують мені... Старих Богів. Ми знаходили їхні сліди по всьому Азероту, і тепер я замислююся, чи не пов’язані ці істоти з ними якимось чином.$B$BНам доведеться провести додаткові дослідження.",
},

[4295] = {
    en = "Rocknot's Ale",
    T = "Ель від Rocknot",
    D = "",
    O = "",
    P = "О, ель! Я б усе віддав за трохи елю «Темного заліза»!! Швидше, я вже протверезнюю! Я це розумію, бо від тверезості в мене затуманюється зір… і через це ти виглядаєш як той $r, якого я вбив минулого тижня!",
    C = "Що це? Ах! Пахне елем «Темна залізна руда»! Від напою в мене затуманився зір, але я бачу, що ти, $gsir:my пані, — справжня подруга!",
},

[4296] = {
    en = "Tablet of the Seven",
    T = "Таблиця Семи",
    D = "Я прибув до Палаючих степів, слідуючи легендам про Сімох. Це були гноми, що володіли великими знаннями та силою, а якщо ти маєш знання та силу, то багатство неодмінно прийде за ними.$B$BОсь чого я прагну. Багатство!$B$BЯкщо нам вдасться дізнатися більше про Сімох, то, можливо, ми зможемо разом розбагатіти. Подейкують, що в руїнах Тауріссана зберігається Таблиця Сімох, яка містить знання древніх гномів. Знайдіть цю таблицю, скопіюйте її текст і принесіть його мені. Давайте разом розкриємо її таємниці!",
    O = "Віднесіть табличку з текстом Максворту Уберглінту в Палаючі степи.",
    P = "Чи є у тебе писання «Сім’ї», $N? Чи дізнався ти про таємниці з їхньої таблички?",
    C = "А, ти знайшов табличку! І твоя транскрипція просто чудова! Ти впевнений, що ти $c, а не писар?$B$BОсь, тримай, $N. Ось обіцяна тобі винагорода.",
},

[4297] = {
    en = "Food for Baby",
    T = "Харчування для немовлят",
    D = "Спрайт-дартери — всеїдні, тобто харчуються як м’ясом, так і рослинністю. Якщо це яйце вилупиться, нам краще бути готовими. Ось що подобається цим крихіткам: шматочки м’яса — сирі та соковиті, хоч як це дивно. Мені так і не вдалося з’ясувати, чому, але це якось пов’язано з планом Елуни щодо ельфів… можливо, вони мали стати захисниками чи щось таке, не знаю.$B$BЯ поки що подбаю про яйце, а ти принеси мені кілька гарних боків сріблястогривого стелсера, щоб вони могли поїсти, коли він вилупиться.",
    O = "Принесіть 5 бокових частин «Срібногривого переслідувача» Агнару Звірокуру в Замежжя.",
    P = "Ти вже знайшов те м'ясо, $N? Твоє маленьке яйце ось-ось вилупиться. Якщо він не отримає достатньо поживного першого прийому їжі, то може не дожити до кінця першого тижня, а мені б дуже не хотілося, щоб так сталося.$B$BНе можу тебе обманювати, $N. Я заздрю тобі, що ти взагалі отримав це яйце. Не змушуй мене шкодувати, що я тобі так допоміг.",
    C = "Ці підійдуть чудово, і, якщо я не помиляюся, твоє маленьке яйце вже майже готове вилупитися. Які відчуття? Ну, знаєш, ти ось-ось станеш $gfather:mother;? Ха-ха, не думав, що тобі доведеться брати на себе таку відповідальність, правда ж?",
},

[4298] = {
    en = "Becoming a Parent",
    T = "Стати батьками",
    D = "Ого, все виявилося набагато готовішим, ніж я думав...",
    O = "Поговоріть з Агнаром Бестамером у Замежжя.",
    P = "",
    C = "Ось, візьми яйце... краще нехай воно буде у тебе, щоб воно прив’язалося до тебе і вважало тебе своїм $gdadda:momma;.$B$BВітаю, $N. Ти став батьком... так би мовити.",
},

[4300] = {
    en = "Bone-Bladed Weapons",
    T = "Зброя з кістяними лезами",
    D = "Хм, може, є щось, чим ти міг би допомогти «Руці», якщо добре подумати. Так, Джес’римону твоя допомога точно знадобиться.$B$BУ кратері Ун’Горо мешкають раптори зі смертоносними кігтями. Деякі з цих рапторів іноді мають білі кігті замість чорних, як смерть. У «Руки» є… клієнти… які полюбляють зброю, виготовлену з цих кігтів. Принеси мені багато таких білих кігтів, і я добре тобі заплачу. Зроби це достатньо швидко, і, можливо, я допоможу тобі й в інших справах.",
    O = "Принесіть 8 білих кігтів равазавра Джес'рімону в Оргримарі.",
    P = "Мої клієнти не надто терплячі, $N. Ти вже отримав хоч якісь кігті?",
    C = "О, ці підійдуть чудово. Дякую, $N. І ти з’явився тут задовго до того, як вони знадобилися… це добре. $B$BМоже, у нас є зброя, виготовлена для тебе з цих пазурів. Що скажеш?",
},

[4301] = {
    en = "The Mighty U'cha",
    T = "Могутній У'ча",
    D = "Поки ти досліджував Ун’Горо, я побачив інші речі, які сподобалися б такому могутньому мисливцеві, як ти. Однією з таких знахідок була величезна мавпа серед інших горил на півночі. Ти вже бував у тій печері раніше, але цього разу я сумніваюся, чи виживеш ти після зустрічі, якщо приймеш моє завдання.$B$BЯ називаю його У'ча, і він — один із найвеличніших синів Матері-Землі, у цьому ти можеш бути впевнений. Переможи У'ча та принеси мені його шкуру. Зроби це, і я захищу твоє право називати себе великим мисливцем.",
    O = "Принесіть шкуру У'ча Торві Патфайндеру біля входу до кратера Ун'Горо.",
    P = "У'ча... ця тварина була величною. Величезна й руда, з зубами розміром з кинджали. Її лапи були товсті, як стовбури дерев, а швидкість — не поступалася жодній гірській левиці, яку я коли-небудь бачив. Тобі пощастило, що ти натрапив на таке випробування на хоробрість — мій народ міг би прожити цілі покоління, так і не побачивши такої істоти.",
    C = "Молодець, $N. Я задоволений. Ти сьогодні зробив тут чудову справу.$B$BУ'ча був одним із найвеличніших мавп, яких я коли-небудь бачив. Те, що ти перевершив його в силі, свідчить про твою власну силу... і мужність.$B$BБуде цілком доречно, якщо я подарую тобі це на знак поваги. Ти це заслужив.",
},

[4321] = {
    en = "Making Sense of It",
    T = "Як у цьому розібратися",
    D = "Інформація, яку ви мені надали щодо опор, дуже цікава... $B$BДайте мені хвилинку, щоб провести деякі розрахунки, $N. Зв’яжіться зі мною ще раз через хвилину, і я зможу надати вам відповідь, яку ми шукали.",
    O = "Згодом поговоріть з Дж. Д. Коллі.",
    P = "",
    C = "Гаразд, $N. Це надзвичайно цікаво... Залишається тільки сподіватися, що мої схеми правильні! Я зібрав усе в цьому посібнику, який ти можеш взяти собі.$B$BГадаю, тепер я зможу відповісти на будь-які твої запитання щодо кристалів, $N.",
},

[4322] = {
    en = "Jail Break!",
    T = "Втеча з в’язниці!",
    D = "Нам треба вибратися звідси, $N. Допоможи мені забрати моє спорядження зі складу та звільнити моїх друзів. Якщо нам вдасться вибратися звідси, ти повинен вирушити до «Морган’с Вігіл» і поговорити з маршалом Максвеллом. Він дасть тобі подальші вказівки.",
    O = "Допоможіть маршалу Віндзору повернути своє спорядження та звільнити своїх друзів. Якщо вам це вдасться, поверніться до маршала Максвелла.",
    P = "Ти виглядаєш втомленим, $n. Можливо, тобі варто присісти біля вогнища і відпочити.",
    C = "Неймовірно, $N. Просто неймовірно. Віндзор промчав тут не більше п’яти хвилин тому. Він висуває грандіозні твердження, але стверджує, що вони підкріплені його доказами. Зараз він прямує до Штормграда, щоб зустрітися з Болваром і… леді Престор.$B",
},

[4324] = {
    en = "Yuka Screwspigot",
    T = "Гвинтовий патрубок «Юка»",
    D = "Хоча мій молодший брат Рібблі все життя був ні на що не придатний, я думаю, що нарешті він став чимось цінним! Але... нам, можливо, знадобиться ваша допомога, щоб скористатися новою цінністю Рібблі.$B$BМоя сестра Юка шукала його кілька тижнів і вистежила його в Палаючих степах. Вона надіслала мені повідомлення з проханням про допомогу.$B$BТож, що скажете? Хочете допомогти? Якщо так, то поговоріть із моєю сестрою. Ви знайдете її у «Полум’яному гребені» — печері на північний захід від Скелі Дредмаул.",
    O = "Поговоріть з Юкою Скруспігот у Палаючих степах.",
    P = "",
    C = "Так, я шукаю свого брата. Ми мусимо його знайти й повернути, нехай йому Бог дасть здоров’я.$B$BАле якщо не вдасться привести його цілим... то й його голови буде достатньо.",
},

[4341] = {
    en = "Kharan Mighthammer",
    T = "Харан Майтхаммер",
    D = "Ви бували на тліючих руїнах Тауріссана? Чи не трапилося вам зустріти жалюгідного грубіяна на ім’я Харан Майтхаммер? Цього карлика, який, як стверджувалося, мав піклуватися про мою донечку!$B$B<Король ридає.>$B$BА тепер її немає, $N!$B$BЯ наказав своїм людям перевернути Степи з ніг на голову. Єдина зачіпка щодо місцезнаходження моєї доньки — це те, що вона, можливо, перебуває в Глибинах. З того, що я знаю, вона може бути мертвою!$B$BКаран, нібито, утримується там у полоні... знайдіть його! Я хочу відповідей!",
    O = "Відправляйся до Глибин Блекрока і знайди Харана Майтхаммера.$B$BКороль згадував, що Харана там утримують у полоні — можливо, тобі варто спробувати пошукати в’язницю.",
    P = "",
    C = "Будь ласка, дозвольте мені пояснити.",
},

[4342] = {
    en = "Kharan's Tale",
    T = "«Казка про Харана»",
    D = "Будь ласка, вислухайте мене, перш ніж робити висновки!$B",
    O = "Послухайте, як Харан Майтхаммер розповідає свою історію.",
    P = "Дозвольте мені до кінця розповісти свою історію.",
    C = "Як бачите, я нічим не міг допомогти.",
},

[4343] = {
    en = "Corrupted Windblossom",
    T = "Зіпсована Вітряна Квітка",
    D = "",
    O = "",
