[4362] = {
    en = "The Fate of the Kingdom",
    T = "Доля королівства",
    D = "Схоже, мій давній супротивник, Дагран Тауріссан, тримає мене та королівство Айронфордж у своїх руках.$B$BТи, можливо, — моя остання надія, $N. Ти мусиш врятувати мою дорогу доньку, Мойру!$B$BЄ лише один спосіб переконатися, що закляття, яке Тауріссан наклав на Мойру, буде знято: вбити його.$B$BІ $N, не завдавай їй шкоди! Пам’ятай, вона перебуває під контролем Тауріссана! Те, що вона може зробити чи сказати, — це наслідок злого закляття Тауріссана!",
    O = "Поверніться до Глибин Блекрока та врятуйте принцесу Мойру Бронзобороду з лап злого імператора Даграна Тауріссана.$B",
    P = "",
    C = "<Принцеса Бронзбеард оплакує смерть імператора Даграна Тауріссана.>$B$BЧому???",
},

[4363] = {
    en = "The Princess's Surprise",
    T = "Сюрприз принцеси",
    D = "Тауріссан був великим і благородним гномом. Ти зруйнував моє життя і життя моєї ще ненародженої дитини!$B$B<Ти вважаєш, що принцеса Бронзоборода, можливо, досі страждає від залишкових наслідків заклинання Імператора.>$B$BПовернися до Айронфорджа й скажи моєму батькові, що спадкоємцем Королівства Айронфордж стане карлик з племені Темного Заліза.$B$BНезалежно від того, чи схвалить він це, чи ні, так і буде.",
    O = "Поверніться до Айронфорджа та поговоріть із королем Магні Бронзобородим.",
    P = "",
    C = "<Король Магні Бронзобородий явно засмучений.>$B$BСхоже, навіть після смерті Тауріссан здобув перемогу.$B$BТи вільний, $N. Перш ніж піти, ти можеш вибрати собі нагороду з королівської скарбниці.$B$B<Король Бронзобородий опускається на трон, щоб обміркувати цей дивний поворот подій.>",
},

