[4621] = {
    en = "Avast Ye, Admiral!",
    T = "Зверніть увагу, адмірале!",
    D = "Слухай уважно, морський псе... Саме влада Буті-Бей заважає нам, «Кривавим вітрилам», плавати куди заманеться і брати все, що забажаємо, як наше право на грабіж. Якби ти встромив ніж у спину флотського майстра Сіхорна, ми б ніколи не зіткнулися з кораблем Буті-Бей. Якби ти встромив ніж у спину барона Ревілгаза, ми б ніколи не мали справу з законом на їхніх умовах.$B$BЯкщо ти хочеш стати почесним адміралом серед нас — так, АДМІРАЛОМ, — ти вб’єш їх обох, як я й казав. Іди ж зараз $g хлопче : дівчино;, і повертайся до мене, щойно виконаєш ці справи.",
    O = "Знищте командувача флоту Сіхорна та барона Ревілгаза з Буті-Бей, а потім поверніться до командувача флоту Фіраллона на борту корабля «Багряна завіса», що стоїть біля узбережжя Долини Странглторн.",
    P = "Ти вже повернувся, ти, клятий шмаркач! Виконав те, що я наказав? Якщо підведеш нас, то підеш по дошці.$B$BАрррр...",
    C = "Гей, ви... Адмірале $N! Ти — пірат серед піратів, дівчино!$B$BМені від душі радісно подарувати тобі цей капелюх. Такої ти ніде не знайдеш, і всі, хто погляне на тебе, побачать, що ти — адмірал «Кривавопарусного флоту»!",
},

[4641] = {
    en = "Your Place In The World",
    T = "Твоє місце у світі",
    D = "Нарешті ти досяг повноліття, $N... повноліття, щоб битися в ім’я Орди. Щоб завойовувати заради слави Вождя.$B$BТак...$B$B<Калтунк оглядає тебе.>$B$BТи чудово впораєшся.$B$BБез сумніву, ти мрієш знайти великого дракона чи демона й задушити його голими руками, але, мабуть, розумніше було б почати з чогось менш... небезпечного.$B$B<Калтунк сміється.>$B$BЗвернися до Горнека, він зможе доручити тобі завдання, яке краще підійде молодому $c. Ти знайдеш Горнека в Лігві, на заході.$B",
    O = "Поговоріть із Горнеком. Ви пригадуєте, що Калтунк позначив на вашій карті місце, де він перебував, і згадав, що Горнек мешкав у «Лігві» — будівлі, розташованій на заході. $B$B",
    P = "",
    C = "Ще один з рекрутів Калтунка, так?$B$BЯкщо це найкраще, на що здатна Орда, то ми опинилися в жалюгідному становищі. Неважливо. До того часу, як ми вирішимо, що ти готовий покинути Долину, ти станеш гордим $C Орди.",
},

[4642] = {
    en = "Melding of Influences",
    T = "Поєднання різних впливів",
    D = "Ось трохи мулу в контейнері, отриманого із зразків з Фелвуда, які ти зібрав. Віднеси цей контейнер до кратера Ун’Горо і знайди чистий мул… підійде будь-який первинний вид. Коли підійдете достатньо близько, випустіть слиз із контейнера й дайте нам подивитися, що ці два зразки думають одне про одного.$B$BПісля завершення експерименту принесіть мені зразок того, що залишилося. Я чекатиму на вас тут, в Апотекаріумі.",
    O = "Принесіть зразок злитої слизу хіміку Фуелі в Підмісті.",
    P = "Як просувається експеримент, $N? Я продовжуватиму досліджувати зразки, які ти для мене зібрав — я починаю розуміти, чому леді Сильвана так цікавиться цими істотами. Якщо вони справді є частиною Старих Богів, то хто знає, як це можна використати на нашу користь.",
    C = "О, чудово, $N. Це просто чудово.$B$BЯка історія. Хто б міг подумати, що ці двоє будуть взаємодіяти між собою саме так... Мені доведеться приділити більше часу вивченню екологічних проблем, що спричиняють зміни в цих істотах.$B$BПоки що я продовжуватиму свої дослідження. Можливо, ми незабаром знову поговоримо. До того часу бажаю тобі всього найкращого.",
},

[4661] = {
    en = "Testing for Corruption - Felwood",
    T = "Перевірка на наявність корупції — Фелвуд",
    D = "",
    O = "",
    P = "Ти береш зразок слизу з Фелвуда і розливаєш його по різних пробірках та мензурках, що стоять на столі. Коли рідина починає кипіти й бризкати, слиз змінює колір. Коли процес сповільнюється і рідина заспокоюється, ти бачиш невелику чашку Петрі, в якій знаходяться твої змінені зразки слизу з Фелвуда разом із деякими іншими залишками.",
    C = "Ви берете чашку Петрі зі зразком слизу. Єдиний спосіб перевірити, чи зразок достатньо чистий, — це відкрити її й самостійно оглянути вміст. У ідеальному випадку ви знайдете зразок, який відповідає критеріям хіміка Фуелі.",
},

[4681] = {
    en = "Washed Ashore",
    T = "Викинуті на берег",
    D = "Ця істота, що викинулася на берег, — не поодинокий випадок тут, у Темному Березі. На узбережжі та навіть у воді їх є ще більше. Я хотів би, щоб ви дослідили ще одну істоту, про яку нам відомо; за повідомленнями, вона перебуває у воді прямо на захід від Аубердіна, неподалік від затонулого судна. Поверніться до мене з усім, що ви зможете знайти і що допоможе нашим дослідженням.$B$BТакож під час ваших подорожей ви можете натрапити на інших істот. Якщо ви щось виявите, будь ласка, обов’язково повідомте нам про це!",
    O = "Зберіть останки морської черепахи зі скелета морської черепахи у водах на захід від Аубердіна, а потім поговоріть із Гвенніт Блай-Леггонд у самому Аубердіні.",
    P = "Як тільки ти дослідиш останки цієї істоти у воді на захід від цього місця, я зможу подати належний звіт до Храму Місяця в Дарнассусі. Можливо, тоді ми наблизимося до розгадки того, чому ці нещасні істоти вирішують покінчити з життям, викинувшись на берег Темного Берега.",
    C = "Ви сьогодні дуже допомогли нам; тепер у нас з’явився реальний шанс розгадати таємницю, чому ці істоти вирішують виходити на берег у районі Темного Берега. Думка про те, що вони, можливо, втікають з околиць Телдрасіля, викликає занепокоєння. Якщо під час своїх подорожей ви натрапите на інших таких істот, будь ласка, повідомте мені. Наші дослідження тут лише на початковій стадії.$B$BВід імені Храму Місяця прийміть це як подяку за ваші зусилля. Дякую, $N!",
},

[4701] = {
    en = "Put Her Down",
    T = "Поклади її",
    D = "Ви, без сумніву, бачили воргів, якими командують орки з Блекрока.$B$BЦікаво — скільки б ми їх не знищували, їхня чисельність ніколи не зменшується. Мої розвідники повідомили, що воргів розводять, дресирують і, зрештою, експортують із Чорноскельної Вежі — столиці орків Чорноскельної. Ви повинні вирушити до Чорноскельної Вежі й виявити джерело цієї загрози. Знайдіть... і знищіть.$B$BУдачі, $N. Нехай Сенаріус захищає вас...$B",
    O = "Відправляйся до Шпиля Блекрок і знищ джерело загрози з боку воргів. Коли ти залишав Гелендіса, він вигукнув ім’я: «Галікон». Саме так орки називають воргів.",
    P = "Чи вдалося вам виявити та усунути джерело загрози з боку воргів?",
    C = "Не зациклюйся на її стражданнях, $N. Звір був спотвореним — плодом темної магії. Ти зробив Альянсу велику послугу, і тебе нагородять.",
},

[4721] = {
    en = "Wild Guardians",
    T = "Дикі охоронці",
    D = "Гонці повернулися з Вінтерспринга з повідомленнями про те, що в південній частині Вінтерспринга розташована низка невеликих печер. Схоже, що в околицях цих печер мешкають дикі люди. Якщо вони охороняють щось цінне, я вважаю, що саме тут ми це знайдемо.$B$BВи побачите, що ці супротивники стануть для вас більшим викликом, ніж попередні типи, $N. Схоже, ці істоти збожеволіли від впливу саме того, що вони так наполегливо намагаються захистити.",
    O = "Трулл Фейлбейн у Фелвуді просить вас вполювати 10 berserk-сови-звірів у Вінтерспрингу.",
    P = "Ти знаєш свої накази, $N.",
    C = "Я дуже поважаю наполегливу працю, $N. Тепер ми можемо продовжувати реалізовувати наші плани щодо Вінтерспринга.",
},

[4722] = {
    en = "Beached Sea Turtle",
    T = "Морська черепаха, що викинулася на берег",
    D = "Ви знаходите труп морської черепахи, яка деякий час тому викинулася на берег у Даркшорі. Його розгризли мурлоки, які розбили табір навколо останків тварини. Проте, схоже, на останках тварини залишилися деякі придатні зразки, які Гвенніт Блі-Легонде в Аубердіні, можливо, зможе використати.",
    O = "Віднесіть останки морської черепахи Гвенніт Блі-Леггонді в Аубердіні.",
    P = "Привіт, $N — чи є у тебе якісь знахідки щодо істот, що винесло на берег, про які можна повідомити?",
    C = "Ще одне відкриття, яке нам належить дослідити — молодець, $N! Ці останки будуть ретельно вивчені, щойно їх доставлять до Дарнасуса. Будь ласка, прийміть цей невеликий гонорар у подяку за останки, які ви надали для нашого дослідження.",
},

[4723] = {
    en = "Beached Sea Creature",
    T = "Викинута на берег морська істота",
    D = "На узбережжі Краю Туману лежать останки гігантського косатка — набагато більшого, ніж той, якого можна було б очікувати побачити на Темному Березі. Як ця істота опинилася тут — невідомо; група мурлоків, яка зараз ласує її тушею, здається надто слабкою, навіть у великій кількості, щоб змогти здолати цю тварину. $B$BХоча частину туші вже обгризли, її залишилося достатньо, щоб взяти зразок для дослідження Гвенніт Блай-Легонді в Аубердіні.",
    O = "Віднесіть кістки морських істот до Гвенніт Блі'Легонді в Аубердіні.",
    P = "Знову вітаю, $N! Ти прийшов повідомити про чергове відкриття?",
    C = "Кістки, які у вас є, належать мирним морським ссавцям, які, як відомо, мешкають у водах навколо підніжжя Телдрасіля. Про них ніколи не було відомо, щоб вони насильно виходили на берег, як це робили косарі. Цікаво, чому ці істоти могли б так чинити? Ну, можливо, дослідження їхніх останків принесе ті плоди знань, яких ми прагнемо.$B$BЩе раз дякую за вашу допомогу. Будь ласка, прийміть цей гонорар від Храму Місяця.",
},

[4724] = {
    en = "The Pack Mistress",
    T = "Господиня зграї",
    D = "Дехто стверджує, що ворги, якими керують орки з Чорної Скелі, є творінням надприродної сили. Інші кажуть, що це не справжні ворги, а порода демонічних псів, подарована оркам занепалим володарем пекла.$B$BПравда набагато менш вигадана, але не менш жахлива. Ворги з Чорної Скелі походять від Галікон та її партнера. Галікон — це гігантська матір-вожак воргів. А її партнер? Ніхто ще не дожив до того, щоб розповісти про нього.$B$BВдарте у саме серце воргів. Знищте Галікон… і $N, стережіться ззаду.",
    O = "Вбий Халікон, ватажку зграї воргів «Кривава сокира».",
    P = "Тепер, коли ватажка зграї вбито, ми можемо почати зменшувати чисельність воргів-вартових у Шпилі й зрештою просунутися вглиб міста.",
    C = "Скажені цуценята? Гізрул-Славенер? І ти вижив, щоб розповісти про це?! Неймовірно! Ти цілком заслужив цю шану!",
},

[4725] = {
    en = "Beached Sea Turtle",
    T = "Морська черепаха, що викинулася на берег",
    D = "Уздовж узбережжя лежать ще останки морських черепах. До панцира цієї черепахи прикріплена покинута карета. Можливо, цю істоту вигнали на берег невідомі істоти, а не те, що вона сама випливла на берег, як можна було б припустити, дивлячись на інші останки. Зараз у останках цієї істоти оселилися мурлоки Сірого Туману, які ласують падаллю.$B$BУ кареті ви знайдете скриньку з дивними знаками; можливо, Гвенніт Блай-Легонде в Аубердіні зможе розшифрувати їх.",
    O = "Віднесіть коробку з дивними позначками до Гвенніт Блі’Легонді в Аубердіні.",
    P = "Радий знову бачити тебе, $N. Ми досягаємо значних успіхів у розгадці таємниці, чому величні морські істоти викидаються на берег узбережжя Темного берега, але, здається, на кожне питання, на яке ми знаходимо відповідь, виникають ще два.$B$BВи тут, щоб запропонувати нам подальшу допомогу в наших дослідженнях?",
    C = "Я чув про такі візки, які були на спині черепахи, яку ти знайшов. Я вважаю, що це візки нага, які вони використовують як у бою, так і для перевезення своїх припасів на сушу. Знаки на скриньці, яку ви знайшли, належать нагам; це пояснює їхнє вторгнення на крайню північ Темного Берега.$B$BЯ надішлю цю скриньку до Дарнассуса разом з рештою ваших знахідок. Це для вас — ще раз дякую за допомогу.",
},

[4726] = {
    en = "Broodling Essence",
    T = "Есенція «Брудлінг»",
    D = "Я вже кілька тижнів вивчаю драконів з Палаючих степів і, здається, нарешті зробив прорив! Я створив пристрій — назвав його «Draco Incarcinatrix 900». Воно здатне уловлювати есенцію дитинчат драконів!$B$BПринаймні, я так вважаю.$B$BОсь, візьми цей пристрій і вистріли ним у дитинча на Палких Степах. Поки воно перебуває під дією пристрою, знищте дитинча, і його сутність має вивільнитися.$B$BЯкщо так, то чудово! Принесіть мені зразки, щоб я міг їх дослідити!",
    O = "Принесіть 8 одиниць «Есенції молодняка» та «Драко-Інкарцинатрікс 900» Тінкі Стімбоіл у «Полум’яному гребені» на «Палаючих степах».",
    P = "У тебе є есенція личинки, $N? Я вже не можу дочекатися, щоб її дослідити.$B$BА крім того... мій покровитель — не та людина, яку варто розчаровувати.",
    C = "Це спрацювало! Ти вловив суть! Молодець, $N! Молодець!$B$BЦя суть стане безцінною для моїх досліджень. Сподіваюся, що колись я навчуся ловити живих драконячих дитинчат або, можливо, їхні яйця. Якби я зміг знайти спосіб це зробити, то мені заздрили б дослідники драконів у всьому світі!$B$BМій роботодавець також був би задоволений, а, як я вже казав, це людина, яку варто тримати в доброму настрої...",
},

[4727] = {
    en = "Beached Sea Turtle",
    T = "Морська черепаха, що викинулася на берег",
    D = "На піску північних пляжів Темного берега лежать скелетні останки морської черепахи. Мурлоки Сірого Туману або не знайшли цей труп, або, можливо, знайшли, але з якоїсь невідомої причини тримаються від нього подалі. У будь-якому разі, від черепахи залишилося достатньо, щоб віднести зразок до Гвенніт Блі-Легонде в Аубердіні для дослідження в Храмі Місяця.",
    O = "Віднесіть останки морської черепахи до Гвенніт Блай-Легонді в Аубердіні.",
    P = "Знову привіт, $N! Ти прийшов, щоб розповісти про ще одне відкриття?",
    C = "Кістки, які ви маєте, належать лагідним морським ссавцям, які, як відомо, мешкають у водах навколо підніжжя Телдрасіля. Про них ніколи не було відомо, щоб вони насильно викидалися на берег, як це робили косарі. Цікаво, чому ці істоти могли б так чинити? Ну, можливо, дослідження їхніх рештків принесе ті плоди знань, яких ми прагнемо.$B$BЩе раз дякую за вашу допомогу. Будь ласка, прийміть цей гонорар від Храму Місяця.",
},

[4728] = {
    en = "Beached Sea Creature",
    T = "Викинута на берег морська істота",
    D = "На пляжі лежить частково випотрошене тіло істоти, що, судячи з усього, є якимось гігантським морським ссавцем. Біля цього величезного морського створіння, що викинулося на берег, лежать покинута тачка та різноманітні інструменти, ніби раніше хтось намагався його дослідити. Хоча мурлоки вже обгризли цю тварину, її залишилося достатньо, щоб зібрати відповідний зразок для Гвенніт Блі-Легонді в Аубердіні.",
    O = "Віднесіть кістки морських істот до Гвенніт Блі-Легонде в Аубердіні.",
    P = "Ще раз вітаю, $N! Що привело тебе знову до Обердіна? Може, ти тут, щоб повідомити про чергову знахідку?",
    C = "Ага, здається, ви знайшли ту істоту, яку спочатку досліджувала «Ліга дослідників». Вони мають своє представництво тут, у Темному березі, і згадували, що вивчали одну з викинутих на берег істот, поки їх не прогнали мурлоки. Схоже, вам вдалося те, чого не вдалося нам обом. Будь ласка, прийміть цей гонорар від імені Храму Місяця.",
},

[4729] = {
    en = "Kibler's Exotic Pets",
    T = "«Екзотичні домашні тварини Кіблера»",
    D = "Ви, мабуть, дивуєтеся, що я тут роблю. Погляньте на клітки! Хіба це не очевидно?$B$BЯ, перш за все, любитель тварин, але за професією — продавець. Я розшукую екзотичних тварин для багатих і знаменитих та приручаю цих звірів, щоб вони поводилися як справжні домашні улюбленці.$B$BТепер ви, мабуть, запитуєте: «Чим я можу тобі допомогти, Кіблере?» Відповідь проста: візьми цю клітку для звірів і знайди мені кілька цуценят ворга. За це я приручу для тебе ворга!$B",
    O = "Відправляйтеся до Шпиля Блекрок і знайдіть цуценят воргів «Кривава сокира». Використовуйте клітку, щоб перенести цих лютих маленьких звірів. Принесіть Кіблеру цуценя ворга в клітці.",
    P = "<Кіблер зараз сперечається з Опусом.>$B",
    C = "Ти їх підібрав у ідеальний момент, $N. Трохи пізніше — і їх уже не вдалося б приручити! Дай мені хвилинку — і я підготую цього малюка, щоб ти міг забрати його додому.",
},

[4730] = {
    en = "Beached Sea Creature",
    T = "Викинута на берег морська істота",
    D = "На пляжі лежить наполовину з’їдене тіло того, що, ймовірно, було гігантським морським ссавцем. Навколо загиблої істоти оселилася зграя мурлоків, сильніших за тих, що мешкають ближче до Аубердіна. Від істоти залишилося достатньо, щоб доставити відповідний зразок її кісток Гвенніт Блі-Легонді в Аубердіні.",
    O = "Віднесіть кістки морських істот до Гвенніт Блі’Легонде в Аубердіні.",
    P = "Знову вітаю, $N! Ти прийшов, щоб розповісти про чергове відкриття?",
    C = "Кістки, які ви маєте, належать лагідним морським ссавцям, які, як відомо, мешкають у водах навколо підніжжя Телдрасіля. Раніше не було відомо, щоб вони насильно викидалися на берег, на відміну від косарів. Цікаво, чому ці істоти могли б це робити? Ну, можливо, дослідження їхніх рештків принесе ті знання, яких ми прагнемо.$B$BЩе раз дякую за вашу допомогу. Будь ласка, прийміть цей гонорар від Храму Місяця.",
},

[4731] = {
    en = "Beached Sea Turtle",
    T = "Морська черепаха, що викинулася на берег",
    D = "Ще одна група останків морської черепахи лежить на березі. До панцира цієї черепахи прикріплена покинута карета, наполовину затиснута ним. Можливо, цю істоту вигнали на берег невідомі істоти, а не вона сама випливла на берег, як можна було б припустити, дивлячись на інші останки. Потужні мурлоки з «Сірого туману» зробили тушу цієї істоти своїм тимчасовим притулком.$B$BУ візку ви знайдете скриньку з дивними знаками; можливо, Гвенніт Блай-Легонде в Аубердіні зможе розшифрувати їх.",
    O = "Віднесіть коробку з дивними позначками до Гвенніт Блі’Легонді в Аубердіні.",
    P = "Знову вітаю, $N. Робота, яку ти виконав на користь Храму Місяця, була надзвичайною. Чи будемо ми мати честь і надалі розраховувати на твої зусилля на нашу користь?",
    C = "Я чув про такі візки, які стоять на спині тієї черепахи. Гадаю, це візки нагів, які вони використовують як у бою, так і для перевезення своїх припасів на сушу. Знаки на скриньці, яку ви знайшли, належать нагам; можливо, істота, яку ви виявили, була вбита, коли прямувала далі на південь… можливо, до Ешенвелю?$B$BЯ обов’язково надішлю цю скриньку до Дарнасуса разом з рештою ваших знахідок. Це для вас — ще раз дякую за допомогу.",
},

[4732] = {
    en = "Beached Sea Turtle",
    T = "Морська черепаха, що викинулася на берег",
    D = "Ви знаходите труп морської черепахи, яка деякий час тому викинулася на берег у Даркшорі. Його майже повністю обгризли мурлоки Сірого Туману — ті самі, які зараз розбили табір навколо останків тварини. Проте, здається, на останках тварини все ще залишилися деякі придатні зразки, які Гвенніт Блай-Легонде в Аубердіні, можливо, зможе використати.",
    O = "Віднесіть останки морської черепахи до Гвенніт Блі'Легонді в Аубердіні.",
    P = "Ще раз вітаю, $N — чи є у тебе ще якісь відкриття, про які можна повідомити Храму Місяця?",
    C = "Ви знайшли ще більше викинутих на берег істот, $N? До руйнування Нордрасіля морські черепахи часто бавилися біля його підніжжя. Однак із появою Телдрасіля цих істот стали бачити дедалі рідше. Як ми з’ясували, деякі з них з невідомих причин закінчують своє життя саме тут.$B$BМожливо, ваша допомога дозволить розгадати цю таємницю. Будь ласка, прийміть це на знак подяки за останки, які ви надали для наших досліджень.",
},

[4733] = {
    en = "Beached Sea Creature",
    T = "Викинута на берег морська істота",
    D = "На скелястій бухті Сутінкового берега винесло на берег останки істоти, схожої на гігантського мечохвоста. Цей мечохвіст у кілька разів більший за будь-якого іншого мечохвоста, якого бачили в цих краях. Звідки б він не походив, ця істота, судячи з усього, не була корінною мешканкою Темного берега.$B$BХоча тіло істоти місцями розірване на шматки, його залишилося достатньо, щоб зібрати відповідний зразок для Гвенніт Блі-Легонді в Аубердіні.",
    O = "Віднесіть кістки морських істот до Гвенніт Блі’Легонді в Аубердіні.",
    P = "Слава Елуні — радий знову тебе бачити, дорогий $N. Храм Місяця продовжує дослідження дивних випадків викидання на берег тут, у Темному Березі. Може, ти маєш для нас якусь додаткову інформацію?",
    C = "Розміри молотильника, про якого ви згадуєте, просто вражають уяву. Навіть найбільші з молотильників у цьому регіоні досягають лише частки тих розмірів. Хоча відомо, що поблизу Телдрасіля траплялися й більші екземпляри, їхня чисельність постійно зменшується. Я не можу не замислитися, чи не пов’язані якось із цим ті істоти, що викидаються на берег саме тут.$B$BПоки ми аналізуємо кістки, які ви нам принесли, будь ласка, прийміть це від імені Храму Місяця. Дякую, $N.",
},

[4734] = {
    en = "Egg Freezing",
    T = "Заморожування яйцеклітин",
    D = "$N, я наполегливо працював над новим пристроєм — «яйцескопом»! Воно призначене для того, щоб вистрілити струменем холодної енергії в яйце чорного дракона... і заморозити його намертво! Чи не могли б ви випробувати його для мене?$B$BЯ чув, що високо в Шпилі Чорної Скелі у драконів є гніздо, де вони висиджують свої яйця. Саме туди тобі й треба вирушити, щоб випробувати «яйцескоп», а потім розповісти мені, як все пройшло!$B$BІ не хвилюйся. Заморожені яйця драконів мають бути нешкідливими. А ось про незаморожені — ось про них і треба турбуватися!",
    O = "Використовуйте прототип «Еггсілоскопа» на яйці в «Рукері».",
    P = "$N, ти перевірив «яйцескоп»?",
    C = "Зробилося? Чудово! Я знав, що так буде!$B$BПоки тебе не було, я працював над новою версією яєццилоскопа. Цей має набагато більший радіус дії.$B$BОсь, візьми собі один на випадок, якщо повернешся до Шпиля Чорної Скелі.",
},

[4735] = {
    en = "Egg Collection",
    T = "Забір яйцеклітин",
    D = "$N, я нарешті готовий до збору справжніх зразків драконячих яєць! Ось, візьми цей електронний модуль для збору. Він призначений для вилучення драконячого яйця та підготовки його до транспортування. Повернися до Гнізда і використовуй модуль, щоб зібрати яйця.$B$BІ не забудь спочатку заморозити їх, інакше вони можуть вилупитися, перш ніж ти встигнеш їх зібрати!$B$BКоли збереш достатньо яєць, принеси їх мені!",
    O = "Принесіть 8 зібраних драконячих яєць та модуль «Collectronic» до Тінкі Стімбоїла у «Полум’яному гребені» на «Палаючих степах».",
    P = "У тебе є яйця, $N? Мій покровитель почув, що ти збираєш їх для мене, і дуже хоче їх дістати!",
    C = "Ого, ти їх дістав! Електронний модуль спрацював! Я — геній!$B$BДякую, $N. Мій меценат буде дуже задоволений, отримавши ці яйця...",
},

[4736] = {
    en = "In Search of Menara Voidrender",
    T = "У пошуках Менари Войдрендера",
    D = "А, привіт, $N. Ти добре просуваєшся у навчанні. Настільки добре, що, на мою думку, тебе слід винагородити за твою наполегливу працю — і за те, що ти ще не піддався впливу темних сил.$B$BЯкщо тебе це цікавить, знайди Менару Войдрендер у Ратчеті. Зараз вона перебуває у вежі Страхада Фарсана, звідки відкривається вид на місто.$B$BВона не дуже привітна, $N, тож не чекай від неї похвали. Але якщо ти будеш старанно працювати, вона подбає про те, щоб тебе не залишили без уваги.",
    O = "Поговоріть з Менарою Войдрендером у Пустках.",
    P = "",
    C = "А, тебе прислав Бріарторн. Добре. Отже, чутки поширюються достатньо далеко, щоб знаходити майбутніх учнів. Це мене тішить.$B$BДля нашого роду, $N, характерно об’єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.$B$BЯ відчуваю, що ти навчився дуже багато чого, і якщо ти готовий, я допоможу тобі створити інструменти, які доповнять твої навички.",
},

[4737] = {
    en = "In Search of Menara Voidrender",
    T = "У пошуках Менари Войдрендер",
    D = "Хм, ти й досі прагнеш стати могутнішим. Я кажу: це лише питання часу, коли розбещеність і залежність опанують тебе, і ти станеш рабом того, над чим прагнеш здобути владу.$B$BПфа! Ти дурень! Час доведе мою правоту — і нічого іншого... лише час.$B$BАле, здається, не всі погоджуються із Зевростом. Схоже, Менара створила б для тебе засоби, щоб ти став могутнішим і зміг опанувати свою силу. Якщо тебе це цікавить, то йди до Ратчет у Пустках. Вона там, звідки відкривається вид на місто.",
    O = "Поговоріть з Менарою Войдрендер у Пустках.",
    P = "",
    C = "А, тебе прислав Зеврост. Добре. Отже, чутки поширюються достатньо далеко, щоб знаходити майбутніх учнів. Це мене тішить.$B$BДля нашого роду, $N, характерно об’єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють, на кого спрямована їхня злоба, якщо нам не вдається їх заспокоїти або належним чином контролювати.$B$BЯ відчуваю, що ти навчився дуже багато чого, і якщо ти готовий, я допоможу тобі створити знаряддя, які доповнять твої вміння.",
},

[4738] = {
    en = "In Search of Menara Voidrender",
    T = "У пошуках Менари Войдрендера",
    D = "Давайте чітко визначимося з одним питанням, $N: я не вважаю, що ти готовий до таких обов’язків. Я не вважаю, що допомога у створенні будь-якого предмета сили — це те, до чого повинен бути причетний новачок; особливо такий, що ще не пройшов випробувань.$B$BАле це не мені вирішувати. Вирішувати це мають ті, хто при владі, або принаймні ті, хто бажає наділити тебе такими дарами.$B$BЯкщо ти хочеш дізнатися більше, раджу звернутися до Менари Войдрендер у Ратчеті. Зазвичай вона перебуває у вежі над портовим містом.",
    O = "Поговоріть із Менарою Войдрендер у Пустошах.",
    P = "",
    C = "А, тебе прислав Демісетт. Добре. Отже, чутки поширюються достатньо далеко, щоб знаходити майбутніх учнів. Це мене тішить.$B$BДля нашого роду, $N, характерно об’єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють у своїй злобі, якщо ми не зможемо їх заспокоїти або належним чином контролювати.$B$BЯ відчуваю, що ти навчився дуже багато чого, і якщо ти готовий, я допоможу тобі створити знаряддя, які доповнять твої вміння.",
},

[4739] = {
    en = "In Search of Menara Voidrender",
    T = "У пошуках Менари Войдрендер",
    D = "$C! Так, саме ти!$B$BУ тебе ще немає всього необхідного спорядження, але одразу видно, що ти готовий — повітря навколо тебе випромінює більшу впевненість. Так, тепер я це бачу.$B$BМенара Войдрендер навчить тебе дечому, якщо ти відчуваєш, що готовий. Вона присвячує свій час навчанню молодших учнів магії. Вона навіть дарує подарунки тим, хто проходить її випробування.$B$BЯкщо тобі цікаво, вирушай до Ратчета в Пустках. Вона перебуває над містом, у вежі Страхада.",
    O = "Поговоріть із Менарою Войдрендером у Пустках.",
    P = "",
    C = "А, тебе прислав Каал. Добре. Отже, чутки поширюються достатньо далеко, щоб знаходити майбутніх учнів. Це мене тішить.$B$BДля нашого роду, $N, характерно об’єднуватися, незалежно від раси. Це особливо важливо, оскільки ті, з ким ми маємо справу найчастіше, не розрізняють у своїй злобі, якщо нам не вдається їх заспокоїти або належним чином контролювати.$B$BЯ відчуваю, що ти навчився дуже багато чого, і якщо ти готовий, я допоможу тобі створити інструменти, які доповнять твої навички.",
},

[4740] = {
    en = "WANTED: Murkdeep!",
    T = "РОЗШУКУЄТЬСЯ: Муркдіп!",
    D = "Увага!$B$BЗа вбивство мурлока «Муркдіпа» призначено винагороду. Ця огидна потвора, як відомо, причетна до загибелі щонайменше одного Вартового, а також підозрюється у затопленні щонайменше двох вантажних суден у водах поблизу Темного Берега!$B$BВ останній раз «Муркдіпа» бачили в таборі мурлоків із хатин на південь від Аубердіна, і вважається, що він охороняє тамтешні хатини. Заявку на отримання винагороди за це завдання слід подати до вартової Глінди Нал’Шеї в Аубердіні.$B$BРада села Аубердін",
    O = "Знайдіть і вбийте мурлока на ім'я Муркдіп. Вважається, що ця істота захищає хатини мурлоків, розташовані на південь від Аубердіна вздовж берега.$B$BПовідомте про загибель Муркдіпа вартовій Гліндě Нал'Шеї в Аубердіні.",
    P = "Вітаємо, $c — чим «Сентинели» можуть вам допомогти сьогодні? Можливо, ви завітали сюди, щоб дізнатися про нагороду за Муркдіпа?",
    C = "Що ж, схоже, ти прийшов сюди не просто поцікавитися! Мешканці будуть раді дізнатися, що сьогодні вночі вони спатимуть трохи спокійніше й безпечніше.$B$BСьогодні ти виступив у ролі виконавця правосуддя для жителів Аубердіна, $N. За це я хотів би подарувати тобі ось це як гідну нагороду... для справжнього героя народу Аубердіна.",
},

[4741] = {
    en = "Wild Guardians",
    T = "Дикі охоронці",
    D = "У північних районах Вінтерспринга дикі істоти стають ще більш лютими. Ми мусимо продовжувати наші заходи в цьому регіоні.$B$BПолюйте на зачарованих місяцем сови-звірів у Вінтерспрингу та досліджуйте територію, де вони мешкають.$B$BЦе небезпечна місцевість, але я знаю, що ти впораєшся з цим викликом. Повернися до мене, коли вб’єш 13 диких істот.",
    O = "Трулл Фейлбейн у Фелвуді просить вас вполювати 13 «Місячних совиних звірів».",
    P = "Тільки не кажи мені, що ти занадто боїшся! Рушай вже!",
    C = "Мені здається, що вам подобається ваша робота. І я вірю, що ми тут натрапили на щось цікаве.",
},

[4742] = {
    en = "Seal of Ascension",
    T = "Печатка Вознесіння",
    D = "Як бачите, на простій печатці є три порожні гнізда. Кожне з цих гнізд потрібно заповнити дорогоцінним каменем, що символізує наказ керівництва. Нарешті, верховний володар Вірмталак, володар нижньої цитаделі, повинен викувати печатку у полум’ї Чорного Драконячого Польоту.$B$BЗрозумій це, смертний: ймовірність того, що один із трьох генералів нижньої цитаделі матиме при собі дорогоцінний камінь у будь-який момент, є дуже низькою. Ти повинен бути пильним під час свого квесту. Залишайся рішучим!",
    O = "Знайдіть три самоцвіти влади: Самоцвіт Смолдерторна, Самоцвіт Спірстоуна та Самоцвіт Блад-Акса. Поверніть їх, разом із «Неприкрашеною Печаткою Вознесіння», Ваелану.$B$BГенерали, про яких вам розповів Ваелан, — це: воєначальник Вун із Смолдерторна; верховний лорд Омокк із Спірстоуна; та верховний лорд Вірмталак із Бладакса.",
    P = "Насамперед — мужність і терпіння, $N!",
    C = "<Образ Ваелана на мить розмивається.>$B$B<Уламки, які ти зібрав, зникли.>$B$BНевикувана Печатка Вознесіння тепер готова. Настав час для останнього кроку.",
},

[4743] = {
    en = "Seal of Ascension",
    T = "Печатка Вознесіння",
    D = "Лише небагато представників роду чорних драконів, окрім тих, що мешкають у верхній цитаделі, здатні створити печатку своїм полум’яним подихом. Вірмталак — один із таких драконів, але його воля незламна.$B$BВам слід вирушити до Вирмбогу в Болоті Дастволл. Саме там ви знайдете стародавнього дракона на ім’я Емберстрайф. Ви повинні зламати його волю, $N. Зламайте її та застосуйте цю кулю до його ослабленого тіла. У вас буде лише кілька секунд, щоб контролювати його розум і розпалити полум’я, яке створить печатку.",
    O = "Відправляйтеся до Вирмбогу в Болоті Дастволлоу. Знайдіть стародавнього дракона Емберстріфа і безжально бийте його, доки його воля не буде зламана.$B$BСаме в цей момент ви повинні покласти Невикуту Печатку Вознесіння перед великим звіром. Потім вам слід швидко застосувати «Сферу драконівської енергії» до його ослабленого тіла та заволодіти його розумовими здібностями. Опануйте звіра та спрямуйте «Полум’я Чорного драконячого полку» на «Невикувану печатку вознесіння»!",
    P = "Не гай часу, $N. Нефаріан гарячково готується випустити своє зло на наш світ.",
    C = "Стойте нерухомо, поки я промовляю останнє заклинання захисту.$B$B<Очі Ваелана перетворюються на дві вогняні кулі.>$B$B«Печатка Вознесіння» завершена...$B$BЗнайте: я наділив цей артефакт потужними захисними заклинаннями. У найчорнішу годину, коли все здаватиметься втраченим, сила Червоного зграї буде у вашому розпорядженні.",
},

[4761] = {
    en = "Thundris Windweaver",
    T = "Тандріс Віндвівер",
    D = "Інформацію, яку ви зібрали під час розвідки табору фурболгів, слід довести до відома Тундріса Віндвевера. Він з гідністю виконує обов’язки старійшини Аубердіна, мудро та справедливо керуючи повсякденними справами селища. Будь ласка, поділіться з ним своїми поточними висновками щодо ситуації з фурборгами.$B$BГадаю, він має власні думки щодо причин їхнього спотворення. Можливо, ви зможете разом з ним розробити план відновлення природної рівноваги в цих краях!",
    O = "Поговоріть із Тандрісом Віндвівером в Аубердіні.",
    P = "",
    C = "Радий бачити вас, $c. Ваше розвідування ситуації з фурболгами відбулося для нас в Аубердіні дуже вчасно. Вже деякий час ми маємо справу не лише з мешканцями лісу, які тепер відкрито вороже ставляться до нашої присутності, а й із відвертою деградацією самого лісу. Сподіваємося, що ти зможеш надати Аубердіну допомогу в ці неспокійні часи.",
},

[4762] = {
    en = "The Cliffspring River",
    T = "Річка Кліфспринг",
    D = "Річка Кліфспринг почала забруднюватися й псуватися. Вона впадає в «Краєчок Туману», і я побоююся, що незабаром це вплине на Аубердін. Я підозрюю, що причиною забруднення є фурболги з Блеквуда, які мешкають вище за течією, але також підозрюю, що вони не є справжньою причиною цього.$B$BВізьміть цю пробірку для відбору проб і вирушайте до гирла річки на північ від нас. Просувайтеся вглиб суші до першого водоспаду й візьміть пробу з водою з того басейну. Ви побачите міст над головою. Зібравши пробу, поверніться до мене в Обердін.",
    O = "Подорожуйте на північ від Аубердіна до першого водоспаду вздовж річки Кліфспринг і візьміть зразок з водойми, що там знаходиться.$B$BПоверніться до Тандріса Віндвевера в Аубердіні зі зразком з річки Кліфспринг.",
    P = "Забруднення річки Кліфспринг — це лише початок тривожної тенденції тут, у Темному Березі. Зразок, який ви надасте, допоможе нам розробити план… план атаки, як мені починає здаватися.",
    C = "Не дивно, що ця вода така забруднена, але тільки погляньте, якою смердючою вона стає! Здається, потрібно діяти якомога швидше, еге ж, $N?$B$BНа схід від нас лежить Фелвуд; саме він є справжнім джерелом цієї порчі, яку я бачив у минулому. Я передбачаю, що цей зразок це підтвердить. Можливо, нам вдасться знайти тут ліки від цього, але щоб навіть спробувати, нам знадобиться допомога. Коли настане той час $N, сподіваюся, ви зможете надати нам необхідну допомогу.",
},

[4763] = {
    en = "The Blackwood Corrupted",
    T = "«Блеквуд: Спотворений»",
    D = "Ми дізналися, що одним із джерел спотворення фурболгів є сатир. Вони панують за допомогою талісманів, через які спрямовують магію. Якщо у фурболгів є шанс на спасіння, ми мусимо виманити сатира-спотворювача й забрати той талісман!$B$BНаповніть цю чашу біля нашого місячного джерела та візьміть зразки їжі фурболгів з їхнього північного табору. Змішайте їх і поставте біля багаття біля річки; будь-який фурборг, який з’їсть цю суміш, буде очищений на достатній час, щоб виманити сатира-спокусника... якого ви потім повинні вбити!",
    O = "Наповніть порожню очищувальну чашу біля Місячного колодязя в Аубердіні.$B$BЗберіть зразки фруктів, горіхів та зерна з північних таборів фурболгів у Чорному лісі.$B$BЗмішайте вміст чаші та поставте її біля багаття, найближчого до річки Кліфспринг у північному таборі, щоб викликати сатира-розбещувача.$B$BВізьміть Талісман розбещення та віднесіть його до Тандріса Віндвевера в Аубердіні.",
    P = "«Талісман розбещення» — це зловісний пристрій, який служить лише для того, щоб порушити рівновагу природи. Коли ти здобудеш цей предмет у того сатира, який мучить фурболгів, і принесеш його мені для знищення, ми здобудемо сьогодні велику перемогу!",
    C = "Ми щойно розпочали цю війну, щоб відвоювати наш ліс у сил корупції, але сьогоднішню битву вже виграно! $N, мешканці Обердіна мають перед тобою борг вдячності, який ніколи не вдасться легко відплатити. Будь ласка, прийми це разом із нашою подякою. Те, що ми дізналися тут сьогодні, може одного дня назавжди звільнити наших друзів-фурболгів від кайданів мук.",
},

[4764] = {
    en = "Doomrigger's Clasp",
    T = "Застібка Думріггера",
    D = "Високо в Шпилі Чорної Скелі є зала, яку колись називали Залою Долі. Саме там гноми Темного Заліза зберігали свої реліквії, трофеї та витвори мистецтва.$B$BЦе було давно. Кажуть, що зала обвалилася і тепер використовується для… не надто приємних справ. Але я вірю, що там ще можна знайти деякі старі реліквії гномів.$B$BОднією з таких реліквій є застібка Думріггера, поверхня якої настільки інкрустована рідкісними самоцвітами, що, як кажуть, кожен гном, який на неї погляне, не може стримати сліз.$B$BЦя застібка, $N, — ваша мета.",
    O = "Принесіть «Застібку Думріггера» Маярі Брайтвінг у «Палаючих степах».",
    P = "У вас є застібка, $N? Мій замовник готовий заплатити за неї дуже щедро.",
    C = "Ви знайшли її! Тож чутки виявилися правдивими!$B$BДякую, $N. Мій меценат, граф Ремінгтон Ріджвелл, буде дуже радий побачити це поповнення у своїй колекції.",
},

[4765] = {
    en = "Delivery to Ridgewell",
    T = "Доставка до Ріджвелла",
    D = "Я спакував «Застібку Дуумріггера» у ящик, придатний для відправки до Штормвінда. $N, ти дуже мені допоміг — чи можу я попросити тебе про останню послугу?$B$BДостав цей ящик графу Ремінгтону Ріджвелу. Ви знайдете його у фортеці Штормвінда. Я впевнений, що він буде дуже радий побачити, що ви для нього принесли.",
    O = "Принесіть ящик Ріджвелла Ремінгтону Ріджвеллу в Штормвінд.",
    P = "Мені сказали, що прийде посланець. Той, що принесе дар із Шпиля Чорної Скелі.$B$BЦе ти?",
    C = "А, то це ти! Я тобі вдячний, $N. І... якщо ти ще не знав... вдячність аристократа з роду Ріджвелл варта майже королівського викупу.",
},

[4766] = {
    en = "Mayara Brightwing",
    T = "Маяра Брайтвінг",
    D = "Мою агентку, Маяру Брайтвінг, відправили до Палаючих степів, щоб вона розвідала зруйноване місто Тауріссан. У цьому зруйнованому місті гномів Темного Заліза можуть ховатися предмети великої цінності... предмети, які чудово пасуватимуть до нашого родинного музею.$B$BМаяра каже, що знайшла щось і їй знадобиться допомога, щоб це дістати, але це не в Тауріссані. Натомість доведеться вирушити до Шпиля Чорної Скелі.$B$BЯ не знаю подробиць, але якщо вас це зацікавило, поговоріть із Маярою на Палаючих степах.",
    O = "Поговоріть з Маярою Брайтвінг у Палаючих степах.",
    P = "",
    C = "Ти приїхав зі Штормвінда? Чудово — я знаю один витвір мистецтва, за який Ремінгтон готовий був би вбити, аби тільки отримати його у свій музей, але дістати його буде нелегко.$B$BОсь тут і знадобиться твоя допомога.",
},

[4767] = {
    en = "Wind Rider",
    T = "«Вершник вітру»",
    D = "Мені доручили набрати більше вивернів для майстрів-вітровершників. Їхня кількість зростає, і я сам сподіваюся одного дня стати вітровершником. Однак ми не встигаємо витренувати достатню кількість вивернів, щоб задовольнити попит. Можливо, ти зможеш мені допомогти, $N.$B$BМені потрібно, щоб ти вирушив до Хайперча, щоб зібрати кілька яєць виверн. Звідси рухайся на північний захід уздовж стін каньйону до схилу, який приведе тебе до Хайперча. Будь обережним: виверни дуже ревно захищають свої яйця і не будуть ласкавими до вторгників.",
    O = "Принесіть 10 яєць виверни «Хайперч» Елу в «Фрівінд-Пост».",
    P = "$N, ти вже знайшов ті яйця віверн, які я шукаю? Мені вже не терпиться розпочати навчання на вершника вітрів!",
    C = "Чудово! Сподіваюся, що завдяки цим яйцям я зможу зробити наступний крок на шляху до того, щоб стати вершником вітру. Ось невеликий знак моєї вдячності; нехай удача у полюванні завжди супроводжує тебе, $C.",
},

[4768] = {
    en = "The Darkstone Tablet",
    T = "Табличка з темного каменю",
    D = "На табличці «Даркстоун» збереглися записи давно померлого гнома Урхельда Даркстоуна. Будучи алхіміком великої майстерності, він вважався своїми сучасниками божевільним і тому не ділився результатами своїх досліджень.$B$BПроте він викарбував їх на табличках, і я вважаю, що одна з таких табличок лежить у Шпилі Чорної Скелі, у залі, що колись називалася Залом Долі. Я не знаю, як вона називається зараз, адже мало хто заходить у Чорнокам’яну Вежу й повертається звідти.$B$BАле якщо ти готовий кинути виклик небезпекам і повернутися до мене з табличкою, твоя нагорода буде великою.",
    O = "Віднесіть Табличку з темного каменю тіньовій магіні Вівіан Лаграв у Каргаті.",
    P = "Ти вже знайшов Таблетку, $N? Я дуже хочу розгадати її таємниці.",
    C = "Чудово. Розшифровка формул, вигравіруваних на цій табличці, займе кілька днів досліджень, але я впевнений, що ці дослідження принесуть чудові результати.$B$BДякую, $N. Ви надали нам неоціненну допомогу.",
},

[4769] = {
    en = "Vivian Lagrave and the Darkstone Tablet",
    T = "Вівіан Лаграв і «Табличка з темного каменю»",
    D = "Вівіан Лаграв надіслала мені повідомлення з Каргата, що в Пустках. На основі своїх досліджень вона вважає, що в Шпилі Чорної Скелі зберігається стародавній текст, який може бути корисним для наших досліджень. Щоб підтвердити це, їй знадобиться хтось, хто зможе дістати цей текст із вежі. Це нелегке завдання.$B$BЯкщо ви зацікавлені, поговоріть із Вівіан у Каргаті.",
    O = "Поговоріть із тіньовою магією Вівіан Лаграв.",
    P = "",
    C = "Це правда. Я вважаю, що у «Шпилі Блекрок» зберігається табличка, на якій записані стародавні алхімічні рецепти. Я радий, що ви тут, адже мені потрібна допомога, щоб дістати цю табличку.$B$BВлаштовуйтеся зручніше, і я все детальніше поясню.",
},

[4770] = {
    en = "Homeward Bound",
    T = "Назад додому",
    D = "Будь ласка, допоможи мені, $c! Я вже деякий час ховаюся тут, у Хайперчі, і вже кілька днів не бачив жодного дружнього обличчя. Я приїхав сюди, щоб вивчити виверн, і, здається, підійшов до них занадто близько. Після того, як мене прогнали з одного з гнізд, я заблукав.$B$BМені потрібно повернутися до поста «Вайтріч»! Мотега не знає, що я зникла, і буде в люті, дізнавшись, що я сама відважилася зайти в Хайперч.$B$BПост «Вайтріч» знаходиться трохи на схід відсюди… будь ласка, відведи мене туди!",
    O = "Супроводи Пао'ка Свіфтмаунтен з Хайперча, а потім поговори з Мотегою Файрмейном у Поштовому пункті Вайтрейч.",
    P = "",
    C = "Що!? Якби я знав, що Пао’ка Свіфтмаунтін збирається нишпорити по Хайперчу, я б прикував його ланцюгом до тотема! Його батько неохоче дозволив йому поїхати зі мною до Тисячі Голків. Ми приїхали сюди, щоб вивчити різних істот, які населяють ці прекрасні землі.$B$BЯ вдячний тобі за допомогу, яку ти надав Пао'ці. Сподіваюся, це компенсує всі неприємності, яких тобі завдала ця справа.",
},

[4771] = {
    en = "Dawn's Gambit",
    T = "«Гамбіт Доун»",
    D = "Я поклав «Гамбіт Доун» у контейнер, який ти приніс нам, той самий, у якому були драконячі яйця. Твоє завдання — донести його вглиб Шоломанса.$B$BМаг-нежить Вектус очолює групу вчених Плеті... поклади «Гамбіт Світанку» у їхню кімнату, яку називають «кімнатою спостереження». Тоді він вступить у взаємодію з неживими, що там знаходяться, і, якщо пощастить, знищить їх!$B$BПісля цього перемогти Вектуса не повинно скласти труднощів. Правда ж?",
    O = "Покладіть «Гамбіт Світанку» у Залі огляду в Шоломансі. Переможіть Вектуса, а потім поверніться до Бетіни Бігглзінк.",
    P = "Пам’ятайте, $N — ми маємо бути толерантними, але водночас непохитними у своїх переконаннях!",
    C = "Чудово, $N! Роки розвідки пішли нанівець! «Скарлетний хрестовий похід» неодмінно відчує цей удар у найближчі тижні.",
},

[4781] = {
    en = "Components for the Enchanted Gold Bloodrobe",
    T = "Компоненти для «Зачарованої золотої мантії крові»",
    D = "Твоє наступне завдання таке ж просте, як і перше, але для його виконання тобі доведеться звернутися по допомогу.$B$BМені потрібна золота нитка для вишивки плаща, але її нелегко дістати, і лише небагато хто знає, як її виготовляти. На щастя, один із тих, хто відданий нашій справі, знає її таємниці й готовий допомогти тим, хто піднімається в наших лавах.$B$BПринесіть золотий зливок до Ксізка Гудстіча в Буті-Бей. Він — майстер-кравець і з радістю випряде для вас нитку. Золоті злитки виплавляють досвідчені гірники. Попросіть гірника про допомогу.",
    O = "Принесіть золотий злиток до Ксізка Гудстітча в Долині Странглторн.",
    P = "Золоті злитки, так... так. Принеси мені один, і ми подивимося, що можна зробити, щоб виткати для тебе трохи нитки. А до того часу раджу тобі зосередити свої зусилля на тому, щоб стати сильнішим. Найважчі випробування ще попереду. І повір мені... ти будеш шкодувати, що не підготувався краще, незалежно від того, наскільки сильним ти себе вважаєш.",
    C = "Чудово, $N. Радий, що тобі вдалося так швидко знайти майнера, який тобі допоміг. Або ти сам це зробив? У будь-якому разі, ти впорався на відмінно. Це ідеально підійде для цієї теми.$B$BСтворення цього займе трохи часу, тож тобі доведеться завітати сюди пізніше — насправді я відправляю це до якоїсь принцеси, яку ми ув’язнили у вежі, і чиє єдине завдання — прясти золоту нитку… ні, серйозно. Я справді так думаю… гаразд, не зовсім.",
},

[4782] = {
    en = "Components for the Enchanted Gold Bloodrobe",
    T = "Компоненти для «Зачарованої золотої мантії крові»",
    D = "Повернися до Менари, скажи їй, що це займе трохи часу, але я обов’язково виконаю обіцянку — як для неї, так і для тебе. Скажи їй, щоб дозволила тобі дозбирати решту компонентів — до того часу я вже маю закінчити нитку. Тоді ти зможеш повернутися й забрати її.$B$BУдачі, $N. А, і передай від мене привіт Страхаду, коли будеш там. Той старий дивак... поставив вежу прямо поруч із Ратчетом... божевілля.",
    O = "Поверніться до Менари Войдрендера в Пустках.",
    P = "",
    C = "Добре, ти повернувся, $N. А де ж нитка?$B$BА, розумію. Це прийнятно. Гоблін і його брат ще не підвели нас — мабуть, цілком зрозуміло, що він не встиг підготувати це саме в той момент. Хай буде так... тим часом у нас є інші справи, якими можна зайнятися.$B$BТи готовий до наступного кроку?",
},

[4783] = {
    en = "Components for the Enchanted Gold Bloodrobe",
    T = "Компоненти для «Зачарованої золотої мантії крові»",
    D = "Наступні компоненти можна знайти в Десоласі, що розташований далеко на захід від Пусток і навіть від Гір Стоунталон.$B$BТам після Великого Розколу досі панує хаос. Там на випробування будуть поставлені як ваша сила, так і ваша хитрість — вам доведеться зіткнутися з істотами, сповненими ненависті, а також із представниками Палкого Легіону.$B$BПринесіть мені кров сатира «Ненависної люті», що мешкає на північному сході. А від менших інферналів у «Ковені Маннорока» принесіть мені камінь меншого інфернала.$B$BМи використаємо обидва ці матеріали для виготовлення вашої мантії.",
    O = "Принесіть 10 флаконів крові «Ненависної люті» та 1 малий пекельний камінь Менарі Пустотвірці в Пустошах.",
    P = "Десолейс — не найбезпечніше місце: наги, велетні, сатири, Палкий Легіон… Усі вони, а також ворогуючі клани кентаврів роблять цю місцевість небезпечною, якщо не бути обережним.$B$BЯк я вже казав раніше, це випробує не лише вашу силу та кмітливість, а й терпіння. Будьте обережні на цих землях, $N.",
    C = "Чудово, $N. Вони підійдуть якнайкраще. Я зараз їх підготую, а ти тим часом перейди до двох останніх компонентів. Ти готовий?",
},

[4784] = {
    en = "Components for the Enchanted Gold Bloodrobe",
    T = "Компоненти для «Зачарованої золотої мантії крові»",
    D = "Зараз мені потрібно лише три речі, $N, і тоді ми зможемо завершити твою мантію.$B$BПо-перше, тоненька золота нитка, яку для тебе виготовляє Ксізк. Повернися до нього в Буті-Бей і забери її.$B$BПо-друге, принеси мені два тліючі вуглинки від вогняних елементалів на Аратських височинах. Якщо я правильно пам'ятаю, вони знаходяться на заході, поблизу Стіни Торадіна.$B$BІ нарешті — осколок душі, створений тобою.$B$BКоли ти збереш усі компоненти, повернися сюди, до вежі, і я завершу для тебе мантію.",
    O = "Принесіть трохи тонкої золотої нитки, 2 тліючі вуглинки та осколок душі Менарі Пустотирці в Пустошах.",
    P = "Незабаром, $N. Обіцяю тобі. Ця мантія цілком задовольнить твої потреби і, безсумнівно, дасть тобі перевагу над суперниками.",
    C = "Чудово, $N! Усі компоненти зібрано, і ми готові.$B$BСподіваюся, ви будете задоволені.",
},

[4785] = {
    en = "Fine Gold Thread",
    T = "Тонка золота нитка",
    D = "",
    O = "",
    P = "",
    C = "Ось, будь ласка, $N. І, будь ласка, передай Менарі від нас привіт.$B$BМи покладаємо на тебе великі надії. Можливо, коли Легіон впаде на коліна, твоє ім’я прозвучить уголос, і всі будуть вихваляти твою силу. Не можу дочекатися!",
},

[4786] = {
    en = "The Completed Robe",
    T = "Готова мантія",
    D = "Я зараз зшию для вас халат. Це займе всього кілька хвилин. Не відходьте далеко.",
    O = "Дочекайтеся, поки Менара Войдрендер завершить пошиття вашої мантії, а потім знову поговоріть з нею.",
    P = "Хвилинку, $n...",
    C = "Готово, $N. Ось, тримай. Носи це з гордістю.$B$BТи наполегливо працював, і я бачу велике майбутнє перед тобою. Пам’ятай: щоб протистояти корупції, яка супроводжує наш шлях, потрібні велика воля та сила духу. Доки твоя воля залишатиметься твоєю власною, ти досягнеш великого успіху.",
},

[4787] = {
    en = "The Ancient Egg",
    T = "Стародавнє яйце",
    D = "Пророцтво Мошару згадує про стародавнє яйце. Це реліквія тих часів, коли тролі правили величезними імперіями, і воно має силу утримувати сутність Хаккара. Можливо, це єдиний спосіб захистити наш світ від його зла.$B$BПринеси мені стародавнє яйце, $N. Кажуть, що воно заховане глибоко в Джинта'Алорі в Замежжя, у печері за амфітеатром на вершині міста.",
    O = "Віднесіть Стародавнє яйце до Єх'кіньї в Танарісі.",
    P = "Чи є у вас стародавнє яйце? Я відчуваю, як пробуджуються великі сили, і боюся, що часу залишається все менше.",
    C = "Ага, яйце у тебе! Я схиляюся перед тобою, $N. Твоя сила та хоробрість надовго залишаться в пам’яті.",
},

[4788] = {
    en = "The Final Tablets",
    T = "Останні таблички",
    D = "Поки я переглядатиму третю та четверту скрижалі Мошару, ти повинен знайти п’яту та шосту! Це буде нелегко, адже їх тримають тролі Смолдерторн у Шпилі Чорної Скелі. Шпиль — це темна вогняна гора між Палаючими степами та Палючим ущелиною.$B$BУдачі, $N. Шпиль Чорної Скелі — не місце для порядних людей...",
    O = "Принесіть п'яту та шосту скрижалі Мошару до золотошукача Айронбута в Танарісі.",
    P = "Ти вже побував на шпилі, $N? У тебе є п’ята та шоста таблиці?",
    C = "Неймовірно! Ти їх знайшов! Ти справді герой, $N!$B$BІ це добре, бо я вже прочитав ті таблички, які ти мені приніс, і з того, що я зрозумів... нам знадобиться герой, щоб зупинити те, що насувається...",
},

