[4807] = {
    en = "Wildkin E'ko",
    T = "Wildkin E'ko",
    D = "",
    O = "",
    P = "У Вінтерспрингу вам доведеться битися з могутніми істотами, які, здається, володіють вродженими магічними здібностями. Ці дикі істоти можуть застосовувати потужну магію. Якщо ви бажаєте підвищити свій інтелект, принесіть мені Е'ко, яке ви знайдете у будь-якої із совиних істот, що мешкають там.$B$BПам'ятайте: щоб полювати на «Е'ко», у вашому інвентарі має бути «Схованка Мау'арі».$B$B",
    C = "Мауарі може створити «да джуджу» для $N... Використовуйте «Кеш Мауарі», щоб застосувати це на себе або на своїх союзників.",
},

[4808] = {
    en = "Felnok Steelspring",
    T = "Фельнок «Стілспрінг»",
    D = "Я хотів би попросити тебе ще про одну послугу.$B$BМоє попереднє дослідження зібраної тобою есенції показує, що, можливо, яйця драконячих дитинчат можна заморозити й зберегти! Я хочу перевірити цю гіпотезу, але спершу мені потрібні спеціально виготовлені інженерні компоненти. Мій колега, Фелнок Стілспрінг, може їх виготовити.$B$BОсь, віднесіть цей лист Фелноку. У ньому написано, що мені потрібно. Ви знайдете Фелнока у Вінтерспрингу, у містечку Еверлук.",
    O = "Передайте лист Тінкі Фелноку Стілспрингу.",
    P = "Тут нагорі холодно! Сподіваюся, ти приніс мені ковдру!",
    C = "Це ж не ковдра! Але що це у нас тут? Лист від Тінкі? Цікаво, що вона пише...$B$BАга, вона навчається в Палаючих степах. Це логічно — там багато драконів. О, але поглянь! Тут написано, що їй потрібні деталі для пристрою, який вона хоче створити. Мабуть, тут і з’являюся я, еге ж?",
},

[4809] = {
    en = "Chillwind Horns",
    T = "Роги «Чілвінд»",
    D = "У мене є майже все, що потрібно Тінкі, але не вистачає одного важливого компонента — рогів холодного вітру. Роги хімери холодного вітру у Вінтерспрингу — це концентроване джерело холоду, але підійдуть лише незаплямовані, цілі роги! Мені знадобиться запас таких рогів, щоб виконати замовлення Тінкі.$B$BПринесіть мені цілосні роги холодного вітру, і я підготую посилку для Тінкі.",
    O = "Принесіть 8 цілих рогів «Холодного вітру» Фелноку Стілспрингу.",
    P = "У тебе є роги «Чілвінд», $N?",
    C = "Це чудові екземпляри. Вони просто промерзли наскрізь! Дайте-но я надягну рукавички, а потім спакую їх разом з іншими речами, які потрібні Тінкі...",
},

[4810] = {
    en = "Return to Tinkee",
    T = "Повернутися до Tinkee",
    D = "Гаразд, усе підготовлено, спаковано й готове до транспортування! Удачі в дорозі, і не забудьте передати Тінкі, що вона мені винна!",
    O = "Віднесіть посилку Фелнока Тінкі Стімбоіл у «Палаючих степах».",
    P = "$N! Ти розмовляв із Фелноком? Ти приніс ті деталі, які мені потрібні?",
    C = "Ти їх приніс! Чудово! Я відразу ж візьмуся за роботу! Дуже дякую, $N!$B$BТи мені так допоміг, що, можливо, пізніше мені знадобиться твоя допомога у ще важливіших справах...",
},

[4811] = {
    en = "The Red Crystal",
    T = "Червоний кристал",
    D = "На схід від нас бродять все чисельніші групи ворожих місячних кінів. Колись їх вважали лагідними, майже містичними істотами. Хоча дехто й досі ставиться до них з повагою, турбота про безпеку Аубердіна змушує мене дотримуватися більш реалістичного погляду.$B$BЯ отримав повідомлення, що лунних кінів приваблює великий червоний кристал, розташований у східному гірському хребті Темного Берега. Ніхто не має уявлення, що це за кристал, і навіть чи існує він насправді. Я хочу, щоб ви знайшли його там і повідомили мені про свої знахідки.",
    O = "Подорожуйте на схід від Аубердіна та знайдіть великий червоний кристал уздовж східного гірського хребта Темного Берега. Повідомте про свої знахідки вартовій Гліндě Нал’Шеа в Аубердіні.",
    P = "Що ти можеш розповісти про той червоний кристал? Чи існує він взагалі?",
    C = "Тож кристал існує, $N? Цікаво... У будь-якому разі, ти чудово впорався зі своїм завданням; молодець!$B$BЩо саме це за кристал? Це лише одне питання серед безлічі інших. Ще одне питання, яке спадає на думку: чому місячний кіт так притягується до цього об’єкта? Чи є кристал доброзичливим за своєю природою, чи, може, він приховує якусь зловісну мету?$B$BУ мене є ще багато питань, але щоб отримати відповіді, нам доведеться ретельно дослідити цей кристал.",
},

[4812] = {
    en = "As Water Cascades",
    T = "Як вода падає каскадом",
    D = "Візьміть цю порожню колбу й наповніть її водою з Місячного джерела тут, в Аубердіні. Така потужна магія має дати підказку щодо складу кристала. Для цього вам потрібно вилити рідину на кристал; решту він зробить сам.$B$BХоча я не очікую, що з вами трапиться щось погане, все ж хочу, щоб ви були обережні. На схід від нас розташований Фелвуд; якщо цей кристал пов'язаний із тим місцем, як я підозрюю, то він може виявитися дуже небезпечним.",
    O = "Наповніть порожню водяну трубу біля місячного колодязя в Аубердіні, а потім обстежте червоний кристал, що знаходиться вздовж східного гірського схилу Темного берега.",
    P = "Кристал виглядає дуже незвично на тлі лісистого пейзажу Темного берега. Тобі здається, ніби з його глибин доноситься ледь чутне гудіння.",
    C = "Ти знову дістався до таємничого кристала. Знявши пробку з пробірки з місячною водою, ти обережно виливаєш її вміст на кристал. Коли вода струмком стікає по його гратках, ти бачиш, як непрозора поверхня стає прозорою...",
},

[4813] = {
    en = "The Fragments Within",
    T = "«Внутрішні фрагменти»",
    D = "Аналіз води з місячного колодязя показав, що всередині кристала знаходяться кілька невеликих уламків кісток, а також половина щелепи. Щелепа, судячи з усього, належить гуманоїду, але остаточно це з’ясувати можна лише розбивши кристал — а це завдання, яке навіть найпотужніша магія вважатиме майже нездійсненним.$B$BЗавдання виконано, залишилося лише доповісти про це вартовій Гліндě Нал’Шеї в Аубердіні.",
    O = "Повідомте про свої знахідки Сентинелу Глінда Нал'Шеа в Аубердіні.",
    P = "",
    C = "Що ж, схоже, що хоч ми й дізналися більше про цей кристал, у результаті з’явилося ще більше питань, на які немає відповідей!$B$BЯ передам інформацію, яку ти зібрав, раді тут, в Аубердіні. Можливо, вони знатимуть, як діяти далі щодо цього кристала. Ну, якщо, звичайно, такі дії взагалі потрібні; поки що загроза залишається достатньо далеко на сході, щоб не становити для нас небезпеки.$B$BА тобі, будь ласка, візьми це. Вважай це нагородою за добре виконану роботу, $N.",
},

[4821] = {
    en = "Alien Egg",
    T = "Яйце інопланетянина",
    D = "У «Тисячі Голках» поширилися чутки про інопланетне яйце. Ті, хто стверджує, що бачив це яйце, не змогли навіть наблизитися до нього настільки, щоб детально його оглянути. Змії охороняють яйце, ніби це одне з їхніх власних.$B$BЯ хочу, щоб ти знайшов це інопланетне яйце й приніс його мені, щоб я міг його дослідити. За повідомленнями, яйце знаходиться в лігві змій, але вздовж підніжжя скельних стін на південь і північний схід від Посту «Вільний Вітер» розташовано кілька таких лігв.",
    O = "Поверніть яйце інопланетянина Хагару Блискавичній Копиті у Фрівінд-Пост.",
    P = "Я мушу дізнатися більше про це загадкове яйце — хто знає, що з нього вилупиться.",
    C = "Так, нарешті... це таємниче яйце нарешті мені доставили. А тепер давайте я на нього уважніше придивлятимуся... Що...! Що це таке..?$B",
},

[4822] = {
    en = "You Scream, I Scream...",
    T = "Ти кричиш, я кричу...",
    D = "МОРОЗИВО! О, будь ласка, будь ласка, будь ласка, чи не могли б ви купити мені трохи морозива?! Полуничний — мій улюблений смак, і в світі немає кращого полуничного морозива, ніж полуничне морозиво від «Тігуле і Форора»! Це моє улюблене морозиво у всьому світі!$B$BЯ пробувала його колись давно, коли була на іподромі «Шіммерінг Флетс», але чула, що зараз його, можливо, продають у місті! Будь ласка? Дуже прошу? З полуничним морозивом від Tigule and Foror зверху??!?!",
    O = "Принеси трохи полуничного морозива для свого підопічного. Схоже, хлопець віддає перевагу морозиву марки «Тігуле і Форор».",
    P = "Хотілося б, щоб випускали більше смаків морозива, крім полуничного, але, мабуть, мені пощастило, що полуничний — мій улюблений!",
    C = "Мммммммм! Я обожнюю їхнє полуничне морозиво! Якщо є щось, на що Тігуле і Форор справді знаються, то це приготування морозива!$B$BДуже дякую $N — це найкращий десерт у світі!",
},

[4841] = {
    en = "Pacify the Centaur",
    T = "Утихомирити кентавра",
    D = "$N, благаю тебе — вистеж цих кентаврів. Вони відчують на собі гнів нашої помсти. Напади на табір кентаврів на північ від застави «Вільний вітер»! Нехай гнів керує твоєю рукою!$B",
    O = "Знищте 12 розвідників Галака, 10 ковбоїв Галака та 6 мисливців за вітром Галака, а потім поверніться до Кліффвотчера Лонгхорна у форті «Вільний вітер».",
    P = "Ну ж бо, $N, я знаю, що ти ще не вбив свою частку. Вистеж їх, і я дам тобі нагороду на знак вдячності.$B",
    C = "На знак вдячності — це для тебе, $n.",
},

[4842] = {
    en = "Strange Sources",
    T = "Дивні джерела",
    D = "Чесно кажучи, хоча тут, у Вінтерспрингу, немає вулканів, я вважаю, що існують набагато загрозливіші причини появи цих гарячих джерел...$B$BНу, гадаю, вам варто побачити це на власні очі. Вам доведеться пройти Вінтерспринг вздовж і впоперек і рушити на сам південь. Коли повітря стане густим і задушливим, а небо потемніє, ви знайдете те, що, на мою думку, є джерелом гарячих джерел.$B$BПогляньте. Я впевнений, що після повернення у вас виникне багато запитань.",
    O = "Виконайте вказівки Донови Сноуден, а потім повідомте про результати.",
    P = "Здається, вода в джерелах має якісь дуже дивні властивості... Я досі не впевнений, що це означає...",
    C = "Так, демони, що мешкають у Ущелині Темного Шепоту; я вважаю, що саме їхня присутність так впливає на цю місцевість. Я продовжую спостерігати за гарячими джерелами тут і подивлюся, чи вдасться мені дізнатися щось ще.$B$BЯ б почекав, поки ти трохи зміцнієш, якщо маєш намір заглибитися далі в ущелину Темного Шепоту.",
},

[4861] = {
    en = "Enraged Wildkin",
    T = "Розлючені дикі люди",
    D = "Привіт, $Glad:lass;! Мене вигнали з мого табору на півдні Вінтерспринга якісь кровожерливі дикі! Ну, мабуть, я занадто наблизився до чогось, що охороняли дикі.$B$BМені ледь вдалося врятуватися, але боюся, що моєму приятелеві не пощастило так само. Чи не могли б ви кинути виклик диким істотам і вирушити до табору? Мені дуже потрібні мої припаси, а ще я хотів би забрати амулет, який вчора відкопав на місці розкопок.",
    O = "Знайдіть зруйнований табір Джарона Стоуншейпера та його запаси на півдні Вінтерспринга.",
    P = "",
    C = "Серед решти знищених речей у таборі особливо виділяється сильно пошкоджена скриня...",
},

[4862] = {
    en = "En-Ay-Es-Tee-Why",
    T = "Ен-Ей-Ес-Ті-Вай",
    D = "Вірте чи ні, але є люди, готові платити за найогидніших із одомашнених звірів!$B$BЯ відправив Біжу до Шпиля, щоб вона спробувала зібрати кілька яєць шпилевих павуків, але вже кілька тижнів від неї немає жодних звісток. Може, ти зможеш мені допомогти?$B$BОсь що я тобі скажу, $N. Зійди до Шпиля Чорної Скелі й збери для мене кілька яєць шпилевих павуків. Принеси їх сюди, і я не тільки дам тобі трохи грошей, а й навіть приручу для тебе одного!",
    O = "Відправляйся до Шпиля Блекрока та збери для Кіблера 15 яєць шпильових павуків.$B$BСудячи з усього, ці яйця можна знайти поблизу павуків.$B",
    P = "Це яйця павуків у твоєму рюкзаку, чи ти просто радий мене бачити?",
    C = "Скільки ж їх! Тобто, погляньте тільки на всі ці яйця! За них можна непогано заробити золота.$B$BЯк і обіцяв, ось твоя власна маленька тваринка. Тільки не дай їй себе вкусити!",
},

[4863] = {
    en = "Enraged Wildkin",
    T = "Розлючені дикі істоти",
    D = "Оглядаючись навколо, ви не бачите тут нічого, що могло б зацікавити Джарона. Однак ви помічаєте, що ящик, який ви знайшли, розбитий, ніби саме його й шукали дикі...$B$BПоглянувши на схід, ви ледь розрізняєте покинутий візок. Можливо, там ти знайдеш речі Джарона. Варто подивитися.",
    O = "Знайдіть розбиту підводу Джарона Стоуншейпера.",
    P = "",
    C = "Підійшовши до воза, здається, що для Джарона тут більше нічого цікавого немає. Але, оглянувши землю, ти помічаєш кілька ящиків, які виглядають цілими, незважаючи на те, що вони наполовину засипані снігом.",
},

[4864] = {
    en = "Enraged Wildkin",
    T = "Розлючені дикі істоти",
    D = "Оглянувши вміст скриньки, ви вирішуєте, що Джарону можуть знадобитися інструменти та інші предмети, що там знаходяться. Однак амулета ніде не видно.$B$BСхоже, що дикі істоти мешкають на землях на півночі та сході від цього місця, тож ви вирішуєте, що наступним кроком буде зіткнутися з цими істотами та відібрати в них амулет.",
    O = "Підніміть з снігу речі Джарона, а потім знайдіть дикого звіра, який вкрав амулет, про який розповідав Джарон.$B$BПринесіть речі Джарона та амулет із синім пір’ям Джарону Стоуншеперу в хатині у Вінтерспрингу.",
    P = "Так... Розкажи мені новини.",
    C = "Ну, я й очікував такого, $Glad:lass;. Я так і думав, що ці скажені звірі знищили всі мої речі...$B$BАле ти ж знайшов мої інструменти, а головне — амулет! Цікаво, чому дикі істоти так запекло захищали цю річ... У будь-якому разі, я двічі подумаю, перш ніж знову вирушати в їхній бік!",
},

[4865] = {
    en = "Serpent Wild",
    T = "«Змія-вайлд»",
    D = "Якби я не побачив це на власні очі, ніколи б не повірив, що це правда. Помста прийшла до Тисячі Голків!$B$B<Хагар витирає піт з чола.>$B$B$N, ти мусиш діяти швидко! Іди негайно й знайди Мотегу Фаєрмейна; він перебуває у форті «Білий Досяг», що розташований на північний захід від форту «Вільний Вітер», вздовж дороги. Він знатиме, що робити!",
    O = "Повідомте про свої висновки Мотезі Файрмейну.",
    P = "",
    C = "Помста! Отже, легенда про Арікару — правда. Дійсно, це проблема, яку треба негайно вирішити.",
},

[4866] = {
    en = "Mother's Milk",
    T = "Материнське молоко",
    D = "Це, мабуть, одна з найпотужніших отрут у світі, $r!$B$BПід час моїх мандрівок до Шпиля я випадково почув, як Чорнокаменці говорили про її смертоносність. Вони називають його «Материнським молоком» — на честь Матері Смолдервеб, великого огидного павука з печери Скіттервеб.$B$BОсь що мені від тебе потрібно: живий зразок цього молока, яке тече у ТВОЇХ жилах. Просто принести мені залозу — недостатньо! Змусь її отруїти тебе і повертайся до мене!$B$BТоді... я зможу видоїти тебе!$B$B<З нетерпінням потирає руки.>",
    O = "У самому серці Блекрок-Спайр ви знайдете Матір Смолдервеб. Вступите з нею в бій і змусьте її отруїти вас. Швидше за все, вам доведеться вбити й її. Поверніться до Раггеда Джона, коли ви будете отруєні, щоб він міг вас «доїти».",
    P = "<Раггед Джон щипає тебе.>",
    C = "З цього вийде найкраще ель, яке я коли-небудь робив!$B$BЕх, а на що, по-твоєму, я це збирався використовувати? На отруту чи що??$B$BБожевільні дітлахи...",
},

[4867] = {
    en = "Urok Doomhowl",
    T = "Урок «Доумхаул»",
    D = "Ааа! Так важко говорити!$B$BЗапиши це! Поверни мені мою енергію!",
    O = "Прочитайте сувій Вароша. Принесіть Варошу його талісман.",
    P = "Ах! Може, моє «моджо» у тебе?",
    C = "Ага! Я вже відчуваю, як до мене повертаються сили. І мій розум більше не мучить прокляття Урока.$B$BДякую, $N! Смиренність — це не для мене, але я мушу визнати твою допомогу.$B$BІ бажаю тобі удачі у твоїх мандрівках Чорнокам’яною Вежею. Ти дурень, якщо думаєш, що зможеш дістатися до вершини, але твоя хоробрість поза сумнівом.",
},

[4881] = {
    en = "Assassination Plot",
    T = "Справа про замах на вбивство",
    D = "Таурен Канаті Грейклауд наважився розбити мисливський табір у Тисячі Голках. Ми мусимо вбити його, щоб знищити цей табір і всіх, хто може піти за ним. Зберемося біля невеликого посту на південний захід від Великого Ліфта.$B",
    O = "Попередьте Канаті Грейклауда у «Вайтреч Пост» про замах на його життя.",
    P = "",
    C = "Вони прийшли, щоб мене вбити? Я покажу їм, як б’ється таурен!",
},

[4882] = {
    en = "Guarding Secrets",
    T = "Збереження таємниць",
    D = "Ви не впевнені у значенні намиста, яке впало з шиї нещодавно вбитого дикого. Воно яскраво світиться, повільно з’являючись і зникаючи.$B$BТрулл Фейлбейн, можливо, зможе розповісти вам більше, оскільки його знання про диких, здається, досить глибокі. Можливо, вам варто запитати його про це.",
    O = "Віднесіть «Намисто з блакитним пір’ям» Труллу Фейлбейну в Пост «Кров’яний отрута».",
    P = "Звітуєте про виконання іншого завдання?",
    C = "Важливе відкриття?",
},

[4883] = {
    en = "Guarding Secrets",
    T = "Збереження таємниць",
    D = "Хоча я й маю чимало знань про совиних звірів, яких ви перемогли у Вінтерспрингу, я не дуже обізнаний у питанні магії, якою вони володіють. Але, гадаю, я знаю одну людину, яка змогла б дослідити намисто і, найімовірніше, пояснити вам, що це таке.$B$BНара Вайлдмейн у Громовому Утвірі — експертка в цій галузі; зверніться до неї. Удачі, $N.",
    O = "Віднесіть «Намисто з блакитним пір’ям» Нарі Вайлдмейн.",
    P = "Чим можу вам допомогти, $N?",
    C = "Енергія цього намиста, $N. Я вірю, що вона має лише одне джерело.$B$B<Нара заплющує очі й на мить замовкає.>$B$BДикі істоти, які зараз збилися зі шляху й заплуталися, колись такими не були. Колись у них була мета, і їх направляли на служіння. Богиня нічних ельфів Елуна створила цих істот, щоб вони охороняли її найсвятіші місця.$B$BХоча цей факт може здатися малозначущим, я закликаю тебе зазирнути глибше.$B$BЗ часом ти все зрозумієш. Дякую, що приніс це мені, $N.",
},

[4901] = {
    en = "Guardians of the Altar",
    T = "Охоронці вівтаря",
    D = "На самій вершині хребта розташований, як я вважаю, вівтар богині Елуни. З того, що я розумію, нам потрібно запалити п'ять смолоскипів у кожній печері, і тоді ми зможемо потрапити безпосередньо до вівтаря.$B$BЯ переписав кілька заклинань, викарбуваних на камені в стародавніх руїнах Кель'Теріла, які, як я вважаю, є секретом, що дозволяє активувати вівтар. Мені знадобиться ваша допомога, щоб запалити кожен факел, поки я промовлятиму заклинання.$B$BЯкщо нам це вдасться, ви зможете повідомити про наші знахідки Ереласу!",
    O = "Захистіть Раншаллу, поки вона намагається знову активувати Вівтар Елуни. Повідомте про свої висновки Ерелас Амберскі у селищі Рут’теран.",
    P = "",
    C = "Ти зустрічався з Раншаллою?",
},

[4902] = {
    en = "Wildkin of Elune",
    T = "Вайлдкін Елуни",
    D = "Це захоплююче!$B$BЯ завжди цікавився, як все насправді... Що ж, ти обов’язково маєш поділитися цими знаннями! Негайно йди до верховного друїда Фандрала Стагхелма — ти знайдеш його в Дарнассусі, у «Крузі Сенаріону». Розкажи йому, що сталося, так само, як ти розповідав мені. Я впевнений, що йому це буде не менш цікаво!$B$BЦе важлива інформація, $N!",
    O = "Поговоріть з верховним друїдом Фандралом Стагхельмом у Дарнассусі.",
    P = "",
    C = "Не вагайся; скажи мені, чому ти прийшов.$B$BО, так? Хм. Ну що ж.$B$BДякую, що звернувся безпосередньо до мене; завжди краще звертатися безпосередньо до верхівки... Але... Так. Друїди Кола Сенаріону вже деякий час знають про Диких. Про те, що вони — улюбленці Елуни і були обрані для охорони найсвятіших місць.$B$BТож хоча це й не новина, я безумовно вітаю вас із вашими зусиллями. Ось, візьміть це — це те, що, здається, підходить для такого подвигу.",
},

[4903] = {
    en = "Warlord's Command",
    T = "Наказ воєначальника",
    D = "За наказом воєначальника Горезуба необхідно знищити таких мешканців Шпиля Чорної Скелі:$B$BКруглолицю загрозу — верховного лорда Омока.$B$BЖорстокого й безжального троля — воєнного майстра Вуна.$B$BВерховний лорд Вірмталак, наглядач за роботою у нижньому місті.$B$BВам також потрібно буде повернути всі важливі документи, які ви знайдете.$B$BВиконайте завдання — і вас чекає слава.$B$BЯкщо зазнаєте поразки — вас забудуть.",
    O = "Знищте Верховного лорда Омока, Воєначальника Вуна та Верхового лорда Вірмталака. Знайдіть важливі документи Чорної Скелі. Після виконання завдання поверніться до воєначальника Горубокого в Каргаті.",
    P = "<Воєначальник Гортус віддає честь.>",
    C = "<Шарваріт Горезуб на мить втрачає свій тьмяно-зелений колір шкіри, і його обличчя стає блідо-білим.>",
},

[4904] = {
    en = "Free at Last",
    T = "Нарешті вільні",
    D = "Арнак думає, що ми одружимося... але після того, як я відхилила його пропозицію, він повернувся тієї ночі й викрав мене. Мій брат намагався його зупинити, але Арнак був занадто сильний. Він... він вбив мого брата, а потім привів мене сюди. Мій бідний брат... $B$B$N, чи не могли б ви провести мене з Вершини Темної Хмари? Будь ласка... Мені треба повернутися до Талії! Вона, мабуть, дуже за мене хвилюється.",
    O = "Супроводи Лакоту Віндсонг від Вершини Темної Хмари, а потім поговори з Талією Амберхайд у Посту «Вільний Вітер».",
    P = "Талія Амберхайд:",
    C = "Дякую, $N. У глибині душі я знав, що вона знайде шлях до мене. Вона розповіла мені про твою хоробрість і про те, як ти допоміг їй втекти. Ці речі належали її братові. Я знаю, що вона хотіла б, щоб ти їх взяв.",
},

[4906] = {
    en = "Further Corruption",
    T = "Подальша корупція",
    D = "Другий табір сатирів, очолюваний жорстоким Ксаваріком, загрожує землям Фелвуда на півночі. Ці підлі зрадники й шахраї живляться зіпсованою енергією місцевих істот Фелвуда.$B$BКсаватрас і його поплічники були лише частиною більшого плану — виростити зіпсований місячний колодязь, а потім передати здобич Ксаваріку.$B$BТепер, коли Ксаватрас усунутий, заверши це завдання, $N. Рушай на північ і переможи Ксаваріка.",
    O = "Ерідан Блювінд у Фелвуді просить вас вбити 8 «Пекельних заклиначів Нефритового вогню», 8 «Зрадників Нефритового вогню», 8 «Шахраїв Нефритового вогню» та Ксаваріка. Поверніться до Ерідана після виконання завдання.",
    P = "Будь ласка, покладіть край стражданням істот Фелвуда.",
    C = "Дякую тобі за все, що ти зробив, $N. Нехай Елуна захищає тебе і веде тебе по шляху, що лежить попереду.",
},

[4907] = {
    en = "Tinkee Steamboil",
    T = "Тінкі Стімбоіл",
    D = "Привіт, $N. Пам’ятаєш Тінкі Стімбойл? Ну, вона тебе пам’ятає! Вона надіслала мені повідомлення, щоб я тримав тебе на очах, бо… їй знову потрібна твоя допомога. Гадаю, це якось пов’язано з її дослідженнями драконів.$B$BТобі слід поговорити з нею на Палаючих степах, у «Полум’яному гребені».",
    O = "Поговоріть з Тінкі Стімбойл.",
    P = "",
    C = "Фельнок мав рацію! Мені знову потрібна твоя допомога, і цього разу... це буде справді небезпечно.$B$BТи готовий??",
},

[4921] = {
    en = "Lost in Battle",
    T = "Загиблі в бою",
    D = "Ми билися в невеликому таборі тауренів, коли нас роз’єднало — вона самотужки стримувала трьох Брістлбеків. Але переважаюча чисельність ворогів почала нас пригнічувати. Я відвів частину супротивників, але потім побачив, як її завалили новоприбулі. У гніві я обернувся, щоб зіткнутися з ворогами, але вони легко мене звалили завдяки своїй чисельній перевазі.$B$BЯ прокинувся, коли таурен-друїд перев’язував мої рани — він натрапив на мене на Золотій дорозі, коли я впав.$B$BБудь ласка, $c, знайди хоч якусь згадку про мою дружину.",
    O = "Знайдіть дружину Манкрика, а потім поверніться до нього на Роздоріжжі.",
    P = "Ви знайшли хоч якісь сліди її перебування? Біль у грудях підказує мені, що сталося найгірше, але я сподіваюся, що ви знайдете її цілою та неушкодженою.",
    C = "Я розумію. Дякую, $c.",
},

[4941] = {
    en = "Eitrigg's Wisdom",
    T = "Мудрість Ейтрігга",
    D = "Ренд живий?$B$BНеможливо!$B$BРаніше вважалося, що Ренд загинув кілька десятиліть тому.$B$BЗверніться за порадою до Ейтрігга, $N. Ніхто не знає про таємниці Чорної Скелі краще за нього, і якщо те, що тут написано, відповідає дійсності, Ейтріггу слід про це повідомити. Нікому не можна відмовляти у праві на помсту.$B$BТи знайдеш його в Оргримарі.$B$BПісля розмови з Ейтріггом порадися з Воєначальником, щоб дізнатися, що він має намір зробити з цією проблемою.",
    O = "Поговоріть з Ейтріггом в Оргримарі. Після того як ви обговорите всі питання з Ейтріггом, зверніться за порадою до Тралла.$B$BВи пригадуєте, що бачили Ейтрігга в покоях Тралла.",
    P = "Хіба ти не бачиш, що мені не можна перебивати?",
    C = "<Трал виглядає засмученим через новини, які ти приніс.>",
},

[4961] = {
    en = "Cleansing of the Orb of Orahil",
    T = "Очищення Сфери Орахіла",
    D = "Ага, куля прикликача — мабуть, саме звідси й походить це прокляття. Щоб ти міг нею скористатися, ми мусимо вигнати демона, що в ній сидить. Це я зроблю без проблем.$B$BА тобі дістанеться найважча робота. Ти повинен убити демона, щойно я його випущу.$B$BІ тобі доведеться діяти швидко. Якщо ти затягнеш, він повернеться до кулі, і нам доведеться починати все спочатку!$B$BТож готуйся, $N. Підготуй свої найпотужніші заклинання, тримай зілля під рукою і, якщо є, візьми з собою друга. Бо це буде неприємно.",
    O = "Знищте Демона Сфери, а потім поговоріть із Табетою.",
    P = "Щоб назавжди позбутися цього демона в кулі, $N, тобі доведеться його вбити.",
    C = "Молодець, $N! Ти дав тому демону урок, який він не скоро забуде. Ти продемонстрував велику силу та майстерність. Гадаю, настав час повернутися до Менари зі своєю очищеною кулею, щоб ти міг її з користю застосувати.$B$BУдачі, $C. Можливо, наші шляхи ще перетнуться.",
},

[4962] = {
    en = "Shard of a Felhound",
    T = "Осколок фелхаунда",
    D = "Отже, ти вирішив захопити душу фелхаунда — чудово.$B$BВізьміть цей рубін — з його допомогою ви зможете захопити душу цієї істоти. Він діє дуже схоже на заклинання, які ви вже знаєте: коли істота буде на межі смерті, використайте самоцвіт, і він зробить решту роботи за вас.$B$BЯ б порадив вирушити до Десоласу й спробувати свої сили на будь-якому з тамтешніх фелхаундів. Вони чудово підійдуть.$B$BПісля успіху віднесіть і захоплену душу, і свій рубін до Менари.",
    O = "Візьміть «Рубін Фелхаса» і застосуйте його до одного з фелхаундів, яких можна знайти в Десоласі. Після успішного виконання завдання поверніть «Рубін Фелхаса» та «Ув’язнений дух фелхаунда» Менарі Войдрендер у Баренсі.",
    P = "Так, $N? Ти вже обрав? Пекельний чи фелхаунд?$B$BКожен вибір є особистим і повинен відображати твої сильні та слабкі сторони. Нерідко трапляється, що $C вирішує ще більше вдосконалити свої сильні сторони, замість того щоб надолужувати прогалини. Іноді повне подолання ворога є не менш ефективною тактикою, ніж становлення більш збалансованим чарівником.",
    C = "Ах, дух фелхаунда. Молодець, $N.$B$BКоли у мене будуть і дух, і очищена куля, я об’єднаю їх для тебе, але не раніше.",
},

[4963] = {
    en = "Shard of an Infernal",
    T = "Осколок пекельного створіння",
    D = "Отже, ти вирішив захопити душу пекельної істоти — добре.$B$BВізьміть цей смарагд — з його допомогою ви зможете захопити душу істоти. Він діє дуже схоже на заклинання, які ви вже знаєте: коли істота буде на межі смерті, використайте самоцвіт, і він зробить решту роботи за вас.$B$BЯ б порадив вирушити до Десоласу й спробувати свої сили на будь-якому з тамтешніх пекельників. Вони повинні чудово підійти.$B$BПісля того як вам це вдасться, віднесіть і захоплену душу, і свій смарагд до Менари.",
    O = "Візьміть «Смарагд Інфуса» та застосуйте його до одного з інферналів, яких можна знайти в Десоласі. Після успішного виконання завдання поверніть «Смарагд Інфуса» та «Ув’язненого духа інфернала» Менарі Войдрендер у Барренах.",
    P = "Так, $N? Ви вже визначилися? Пекельний чи фелхаунд?$B$BКожен вибір є особистим і має відображати ваші сильні та слабкі сторони. Нерідко трапляється, що $C вирішує ще більше вдосконалити свої сильні сторони, замість того щоб компенсувати свої недоліки. Іноді повне подолання ворога є не менш ефективною тактикою, ніж ставати більш збалансованим чарівником.",
    C = "Ага, дух пекельного створіння. Молодець, $N.$B$BКоли у мене будуть і дух, і очищена куля, я об’єднаю їх для тебе, але не раніше.",
},

[4964] = {
    en = "The Completed Orb of Dar'Orahil",
    T = "Завершена Сфера Дар'Орахіла",
    D = "Я негайно візьмуся за виготовлення вашої кулі та втілення у неї вашого нового демона. Коли все буде готово, ви зможете вибрати, чи бажаєте ви, щоб вона мала вигляд посоха чи кулі. Я завжди вважав важливим враховувати обрану зброю чаклуна… Не бачу жодних причин, щоб не продовжувати цю традицію.",
    O = "Дочекайтеся, поки Менара Войдрендер завершить створення Сфери Дар'Орахіла, а потім знову поговоріть з нею.",
    P = "",
    C = "Готово, $N. Просто скажи мені, що тобі більше до вподоби: посох, для використання якого знадобляться обидві руки, чи куля, щоб ти міг використовувати як зброю кинджал або меч.$B$BПобороти фелхаунда — це був великий подвиг з твого боку. Я впевнений, що цей предмет стане тобі в нагоді в майбутньому. Продовжуй старанно вдосконалюватися в бойових мистецтвах, $N. Я чекатиму на подробиці твоїх подвигів.",
},

[4965] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орахіла",
    D = "Ну-ну-ну... Приємно бачити, що ти набираєш сили, $N. Готовий побитися об заклад, що ти вже майже готовий поговорити з Менарою Войдрендер у Пустках. Якщо ти ще не розмовляв з нею, то дозволь мені сказати: я не думаю, що коли-небудь зустрічав іншого майстра у створенні предметів — а саме куль — здатних так легко ув’язнити навіть демона, щоб той служив нашій волі.$B$BЯкщо тобі цікаво, вона перебуває у вежі Страхада над Ратчетом у Пустках.",
    O = "Поговоріть з Менарою Войдрендером у Пустках.",
    P = "",
    C = "Ага, ти справді прагнеш чогось більш... суттєвого. Я можу тобі допомогти, якщо ти справді готовий.$B$BПриємно бачити, що хтось із наших прагне більшої сили не лише у вигляді знань.$B$BТож, ти вважаєш, що готовий, $N?",
},

[4966] = {
    en = "Protect Kanati Greycloud",
    T = "Захистіть Канаті Грейклауд",
    D = "Але, можливо, кентаврів більше, ніж я думав, тому я прошу тебе, $n, битися разом зі мною проти цих підлих вбивць.",
    O = "Захистіть Канаті Грейклауд від нападу кентаврів.",
    P = "",
    C = "Дякую за допомогу, $n. Без тебе я б не зміг їх відбитися.",
},

[4967] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орахіла",
    D = "Ти й досі дурень і досі прагнеш атрибутів смертних. Так, я звертаюся до тебе з гордовитістю. Я бачу тебе перед собою і сміюся. Ти жалюгідний!$B$BАле не має значення, що думаю я. Має значення лише те, що думають ті, хто готовий мати з тобою справу! І в цьому випадку, всупереч моєму здоровому глузду, ті, хто має хоч якусь владу, вважають, що ти заслуговуєш на більше.$B$BЯкщо це те, до чого ти прагнеш, то тобі слід поговорити з Менарою Войдрендер у вежі над Ратчетом. Гадаю, ти вже зустрічався з нею деякий час тому.",
    O = "Поговоріть із Менарою Войдрендером у Пустках.",
    P = "",
    C = "Ага, ти справді шукаєш чогось більш... суттєвого. Я можу тобі допомогти, якщо ти справді готовий.$B$BПриємно бачити, що хтось із наших прагне більшої сили не лише у вигляді знань.$B$BТож, ти відчуваєш, що готовий, $N?",
},

[4968] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орахіла",
    D = "Хм, ти дійшов аж сюди… справді вражаюче. Я б подумав, що розтління, пов’язане з керуванням таємними силами, вже давно проникло в саму твою душу і довело тебе до божевілля. Тож як щодо того, щоб спробувати підштовхнути тебе ще далі?$B$BЯкщо хочеш випробувати свої вміння, знайди Менару Войдрендер над Ратчетом у вежі Страхада. Вона тебе наставлятиме.",
    O = "Поговоріть із Менарою Войдрендером у Пустках.",
    P = "",
    C = "Ага, ти справді прагнеш чогось більш… суттєвого. Я можу тобі допомогти, якщо ти справді готовий.$B$BПриємно бачити, що хтось із наших прагне більшої сили не лише у вигляді знань.$B$BТож, ти відчуваєш, що готовий, $N?",
},

[4969] = {
    en = "Knowledge of the Orb of Orahil",
    T = "Знання про Сферу Орахіла",
    D = "Ха-ха! Ти чудово справляєшся, юний $c.$B$BЗгодом інфернали та лорди жаху схиляться перед тобою!$B$BАле доки цей час не настане, тобі доведеться покладатися на зброю, викувану руками смертних рас.$B$BЗдається, ти готовий до створення ще одного такого витвору, і якщо ти згоден, Менара Войдрендер хотіла б поговорити з тобою! Вона перебуває поблизу вежі Страхада, з якої відкривається вид на портове місто Ратчет. Зайди туди, коли будеш готовий.",
    O = "Поговоріть з Менарою Войдрендер у Пустках.",
    P = "",
    C = "Ага, ти справді прагнеш чогось більш... суттєвого. Я можу тобі допомогти, якщо ти справді готовий.$B$BПриємно бачити, що хтось із наших прагне більшої сили не лише у вигляді знань.$B$BТож, ти відчуваєш, що готовий, $N?",
},

[4970] = {
    en = "Frostsaber Provisions",
    T = "«Фростсейбер» — продукти харчування",
    D = "Якщо ти хочеш проявити себе, можеш почати з виконання дуже простого, але дуже важливого завдання.$B$BЗбери м’ясо хімери та зубастих ведмедів у цій місцевості. Принеси його мені, щоб я міг нагодувати ним морозомечів, яких зараз тренують.",
    O = "Зберіть 5 шматків м’яса «Осколкозуба» та 5 шматків м’яса «Холодного вітру» для Ріверна Фроствуїнда у Вінтерспрингу.",
    P = "Дисципліна та рішучість — це ваші цілі. Я можу попросити вас виконати просте завдання багато разів; щоразу ви повинні виконувати його якнайкраще.",
    C = "Дякую за допомогу, $N. З кожним днем моя повага до тебе зростає.",
},

[4971] = {
    en = "A Matter of Time",
    T = "Питання часу",
    D = "В Андорхалі сталося втручання у хід часу з боку зловісної сили — найімовірніше, «Скорбі»! Я можу спробувати зберегти тут безперебійний плин часу та відновити те, що було пошкоджено, але для цього мені знадобиться ваша допомога, щоб я міг працювати без перешкод.$B$BЧасові паразити — падаль, що живиться нитками зміненого потоку часу — тепер заполонили силоси Андорхала. Єдиною видимою ознакою їхньої присутності є блакитний імпульс спотворення. Вони уповільнюють мої пророцтва; будь ласка, $N, допоможіть мені, використовуючи цей часовий переміщувач, щоб викорінити цих паразитів.",
    O = "Використайте «Часовий переміщувач» поблизу одного з силосів Андорхала та знайдіть «Часових паразитів».$B$BЗнищіть 15 «Часових паразитів», а потім поверніть «Часовий переміщувач» Хромі в таверні Андорхала, що у Західних Землях Чуми.",
    P = "Часові паразити — це поширене явище, яке зустрічається скрізь, де в хід часу втручалися. Я відчуваю, що їх тут багато, і це мене турбує.$B$BВикорінення всіх, кого ви зможете знайти, допоможе мені краще впоратися з погіршенням часової ситуації тут. Я зможу відчути, коли це буде досягнуто.",
    C = "Зараз здається, що час легше відновити, дякую $N. Хоча ти, можливо, не до кінця розумієш наслідки розриву часової лінії, я вдячний, що ти усвідомлюєш нагальність протидії тому, що, як я дедалі більше підозрюю, є зловмисним вчинком, спричиненим «Скажем».$B$BЯ не бачу нічого поганого в тому, щоб винагородити тебе за допомогу, смертний. Твої найбільші подвиги ще попереду, і нагорода у вигляді дрібнички, безсумнівно, не змінить твоєї майбутньої долі. Однак твоя подальша допомога — це те, що знадобиться мені та драконячому зграї...",
},

[4972] = {
    en = "Counting Out Time",
    T = "Відлік часу",
    D = "Мені потрібно, щоб ти зазирнув у світ за межами цієї кімнати, $N. Дозволь мені пояснити.$B$BТи бачиш, чим ця кімната відрізняється від решти Андорхалу. Мій драконячий загін діє по-різному та в різних часових лініях. Щоб відновити пошкодження Андорхала, я зараз дію з іншої часової лінії, щоб не занадто забруднити його. Однак, щоб продовжити це, мені потрібні часові артефакти — ті, що застрягли в часі, коли спалахнула чума. Знайдіть їх у зачинених скриньках, що знаходяться в зруйнованих будівлях, які колись складали це горде місто.",
    O = "Знайдіть 5 годинників «Андорхал», які лежать у сейфах серед руїн міста. Поверніться з ними до Хромі в таверні «Андорхал» у Західних Землях Чуми.",
    P = "Ті «часові дрібнички», які я шукаю, — це прості пристрої. Здебільшого це годинники, стрілки яких назавжди зупинилися, коли чума вперше спустошила Андорхал.$B$BЧас не має кінця, і годинники, які ти приносиш мені, неминуче повертатимуться до своїх домівок… принаймні доти, доки тут триватимуть ці заворушення.",
    C = "Це саме те, що мені потрібно, $N. Дякую.$B$BДозвольте мені належним чином винагородити вас цим. Можливо, ви не розумієте, навіщо вам може знадобитися такий пристрій. Можливо, ви навіть не до кінця уявляєте, що це насправді таке. На жаль, я не можу сказати, коли це стане для вас найкориснішим; просто знайте, що в якийсь момент у майбутньому ви можете виявити, що цей предмет має надзвичайну користь і функціональність після його використання. Чи вирішите ви зберегти його до того часу, чи ні... це, мій друже, залежить від вас.",
},

[4973] = {
    en = "Counting Out Time",
    T = "Відлік часу",
    D = "Якщо ви готові ще раз допомогти, ваша допомога мені, безперечно, знадобиться. Я з радістю візьму ще кілька годинників, які ви, можливо, знайдете серед руїн Андорхалу. Вони, безперечно, допомагають мені підтримувати рівновагу проти тієї злої сили, яка втручається у хід подій тут.$B$BВ обмін на ці годинники я дам вам інший предмет, який, як я підозрюю, у майбутньому стане вам дуже в нагоді.",
    O = "Знайдіть 5 годинників «Андорхал» серед руїн міста та поверніться з ними до Хромі в таверні «Андорхал» у Західних Землях Чуми.",
    P = "Годинники Андорхала, подібно до великого годинника на руїнах ратуші, всі зупинилися на третій годині. Саме тоді повна сила чуми вперше охопила місто, висмоктуючи з нього життя.$B$BХоч як би ми всі не шкодували про те, що сталося того дня, це визначило плин часу, яким його сприймаєте ви, смертні. Бронзовий драконячий загін повинен наполегливо захищати часову лінію!",
    C = "Ще раз дякую вам за допомогу. Будь ласка, прийміть цей подарунок. Хоча ви, можливо, ще не знаєте, коли вам знадобиться така річ, але, можливо, з часом вам відкриються її справжні наміри. Можна сказати, що я бачив, як це сталося з вами, $N.",
},

[4974] = {
    en = "For The Horde!",
    T = "За Орду!",
    D = "Ренд наважується висловлювати такі грандіозні заяви завдяки захисту, який йому надає Чорний полк.$B$BТи, $N, знайдеш спосіб пройти через Зали Вознесіння. Потім ти знайдеш «Вождя» Ренда Чорнорукого і знищиш його — ЗА РАДИ ОРДИ!$B$B<Трал з силою б’є кулаком по трону.>$B$BНаступного разу, коли ти повернешся до моїх покоїв, ти з піднятою головою, у знаку тріумфу, принесеш її своєму Вождю. Зроби це — і тебе вшанують як героя Орди.",
    O = "Відправляйся до Шпиля Блекрока та вбий вождя Ренда Блекхенда. Візьми його голову та повернися до Оргримара.",
    P = "<Тралл хрипить.>",
    C = "Ти завдав нищівного удару силам Чорної Скелі, $N. Зі смертю свого вождя легіон Чорної Скелі знову опинився у вирії хаосу.$B$BНа честь твоїх героїчних подвигів жителі Калімдору отримають нагороду!",
},

[4975] = {
    en = "The Completed Orb of Noh'Orahil",
    T = "Завершена Сфера Но-Орахіла",
    D = "Я негайно візьмуся за виготовлення вашої кулі та втілення у неї вашого нового демона. Коли все буде готово, ви зможете вибрати, у якій формі вона буде — у вигляді посоха чи кулі. Я завжди вважав важливим враховувати вибір зброї чаклуна… Не бачу жодних причин відмовлятися від цієї практики.",
    O = "Дочекайтеся, поки Менара Войдрендер завершить створення Сфери Но-Орахіл, а потім знову поговоріть з нею.",
    P = "",
    C = "Готово, $N. Просто скажи мені, що тобі більше до вподоби: посох, для якого знадобляться обидві руки, чи куля, щоб ти міг використовувати кинджал або меч як зброю.$B$BПодолання пекельного створіння було великим подвигом з твого боку, і ця нагорода чудово тобі підійде. Бажаю тобі подальших успіхів у мистецтві, $N.",
},

[4976] = {
    en = "Returning the Cleansed Orb",
    T = "Повернення очищеної кулі",
    D = "Віднеси очищену кулю Менарі в Ратчеті, $N. Передай їй мої вітання та бережи себе. Я щиро сподіваюся, що ти зможеш встояти перед спокусами та розбещенням, які неминуче зустрінуться тобі на твоєму шляху.$B$BУдачі.",
    O = "Поверніть очищену пекельну кулю Менарі Войдрендер у Пустках.",
    P = "Як просуваються твої пошуки Табети та кулі, $N?$B$BТабета виявилася надзвичайно корисною у питаннях, пов’язаних з магією. Я впевнений, що вона з радістю тобі допоможе, якщо ти зможеш її знайти.",
    C = "Молодець, $N. Це підійде чудово.$B$BЗалишилося лише вирішити, якого демона ти хочеш, щоб я ув’язнив у очищеній кулі. Зроби це — і ти отримаєш чудовий новий предмет, яким зможеш користуватися.",
},

[4981] = {
    en = "Operative Bijou",
    T = "Оперативна «Біжу»",
    D = "Ніколи не вір гоблінам. Ось до чого все зводиться, $N.$B$BЇї звати Біжу — це одна з наших найхитріших агенток. Я дізнався, що вона працювала на якогось підозрілого торговця екзотичними тваринами з Палаючих степів на ім’я Кіблер, тобто, по суті, зраджувала нас. Що ще гірше, вона використовувала кошти Орди для фінансування своїх операцій.$B$BЯ хочу, щоб її привели сюди живою.$B$BВостаннє її бачили, коли вона заходила до Шпиля Чорної Скелі. Знайдіть її й приведіть сюди.$B$BІ $N, не дайте їй обдурити вас своїми солодкими словами.",
    O = "Відправляйся до Шпиля Блекрок і з’ясуй, що сталося з Біджу.",
    P = "",
    C = "Я не буду тобі брехати, $r. Мені потрібні були гроші! Кіблер платить дуже, дуже добре — набагато краще, ніж це коли-небудь могла б зробити K.E.F.$B$BАле не сумнівайся в моїй відданості! Як ти думаєш, чому я тут? Щоб дістати для того божевільного гобліна яйця екзотичних тварин чи щось настільки ж безглузде? Ні, тільки справжній дурень приїхав би до Чорноскельної Вежі, щоб збирати домашніх улюбленців. Так, не думаю, що в цьому світі є багато таких людей.$B$B<Біжу сміється.>$B$BОстаннє, що нам потрібно, — це щоб такі люди розмножувалися.",
},

[4982] = {
    en = "Bijou's Belongings",
    T = "Речі Біжу",
    D = "Вночі, коли охорона тут не така пильна, я крадуся містом, роблячи нотатки та записуючи все, що бачу і що може мати стратегічне значення для К.Е.Ф.$B$BОднак минулої ночі все пішло жахливо не так. Я натрапив на розтяжку і спрацював сигнал тривоги. Я сховав своє розвідувальне спорядження та кинувся шукати укриття! На жаль, я не можу повернутися за тим спорядженням. Патрулювання посилили удвічі, а то й утричі! Уся та інформація втрачена.$B$BПоверніть мені мої речі, і я мирно повернуся до К.Е.Ф.",
    O = "Знайдіть речі Біжу та поверніть їх їй. Ви пригадуєте, що вона згадувала, ніби сховала їх на найнижчому поверсі міста.$B",
    P = "Як справи?",
    C = "Ти це зробив! Як тільки Лекслорт отримає ці плани, він забуде про всі ті жахливі речі, які хотів зі мною зробити.$B$B$N, ти — мій герой!$B",
},

[4983] = {
    en = "Bijou's Reconnaissance Report",
    T = "Розвідувальний звіт Біжу",
    D = "Віднеси цей звіт Лекслорту. Він відновить мою репутацію і, безсумнівно, надасть К.Е.Ф. стратегічну перевагу у боротьбі з цими орками.$B$BПіти з тобою? У мене занадто багато роботи. Швидше вирушай, їм ці звіти потрібні якомога швидше!$B",
    O = "Віднесіть розвідувальний звіт Біжу до Великого майстра Лекслорта в Каргаті.$B",
    P = "Де ж той гоблін???",
    C = "Треба віддати їй належне: їй знову вдалося викрутитися з ще однієї скрутної ситуації! Ці звіти стануть безцінним надбанням у наших стосунках з орками з Блекрока.$B$BЗвісно, ти отримаєш нагороду за свою наполегливу працю.",
},

[4984] = {
    en = "The Wildlife Suffers Too",
    T = "Дика природа теж страждає",
    D = "Хоча самотужки я мало що міг зробити, аби зупинити Пошесть, я все ж приїхав у ці краї, щоб спробувати відновити шкоду, завдану природі. Тварини страждають від чуми, яка й досі душить ці землі, не маючи змоги знайти милосердя та спокій. Я прошу вас продовжити те, чого я не зміг тут завершити.$B$BДля страждаючих тварин немає іншого спасіння, окрім милосердного і лагідного визволення. Знайдіть поблизу хворих вовків і прикінчіть їх. Будь ласка, $N, покладіть край їхнім мукам — це, безсумнівно, заспокоїть і мої.",
    O = "Знищте 8 хворих вовків, а потім поверніться до Мулгріса Діпрівера у «Місці корчів» на Західних Землях Чуми.$B$B",
    P = "Вовків, уражених чумою, необхідно приспати, $N. Хворобу, яку вони переносять, вилікувати неможливо. Я намагався... Я намагався, доки сам не піддався чумі.",
    C = "Я... Я відчуваю, що душі тих вовків, яких ти вбив, тепер знайшли спокій. Вони — і я — дякуємо тобі за милосердне звільнення.$B$BВовки не єдині, хто страждає у цьому проклятому місці, $N. Будь ласка, мені знову потрібна ваша допомога.",
},

[4985] = {
    en = "The Wildlife Suffers Too",
    T = "Дика природа теж страждає",
    D = "На схід від того місця, де ми зараз перебуваємо, неподалік від початку Східних Земль Чуми, колись цими краями бродили горді й величні грізлі. Чума, поширена «Покаранням», знищила й цих звірів. Вони блукають краєм, мучаючись від заклякання м’язів та гниття шерсті й тіла.$B$BЯ прошу вас покласти край і їхнім мукам. Єдиним ліком від їхніх страждань є швидка смерть, яку має принести ваша рука.",
    O = "Знищте 8 хворих грізлі, а потім поверніться до Мулгріса Діпрівера в «Місці мук», що у Західних Землях Чуми.",
    P = "Я чую твої кроки, $N. Я втратив зір, але все ще здатний відчувати те, що відбувається навколо мене. Ти поклав край стражданням хворих на гризлі?",
    C = "«Я знаю, що грізлі було приспано, їхні муки закінчилися. Я… У мене є ще одне доручення для тебе. Я записав це на… на цій гілці, відчувши, що мій час у цьому світі добіг кінця.$B$BСправді… Я наближаюся до кінця. Ще раз дякую, друже… істоти цієї проклятої землі можуть спочивати… і тепер я теж».$B$BСказавши це, друїд важко зітхнув, а потім пролунало щось схоже на передсмертне хрипіння. Його тіло лежить нерухомо на підлозі хатини.",
},

[4986] = {
    en = "Glyphed Oaken Branch",
    T = "Гліфічна дубова гілка",
    D = "Безживна рука друїда-таурена стискає дубову гілку, яка виглядає напрочуд здоровою. При ближчому огляді на корі гілки виявляються викарбувані друїдські гліфи.$B$BКоли ви берете гілку в руки, ви помічаєте, що вона тепла на дотик — навіть більше, ніж слід було б. У вашій свідомості спливає образ дерева Телдрасіл — а саме, у Дарнасусі — і слова «Коло Сенаріона» вириваються з ваших вуст. Схоже, що підказка щодо того, куди слід віднести гілку, була закладена саме в ній.",
    O = "З огляду на магію, вкладену в «Дубову гілку з гліфами», наступним кроком, якого прагнув друїд-таурен, було доставити її до Кола Сенаріону в Дарнассусі. Зверніться за допомогою до одного з друїдів, які там перебувають.",
    P = "Від імені Кола Сенаріону вітаю вас у цій анклаві, $c. Яка у вас до нас справа?",
    C = "Це... це досить дивно. Цей друїд — причому саме таурен-друїд — довірив тобі чимало цінної інформації про масштаби епідемії, яку поширює Плеть. Мене дивує, що таурен міг би надати $r таку інформацію, до того ж добровільно, якщо те, що ти кажеш, є правдою. Ми обов’язково це використаємо, обіцяю тобі. Можливо, таурени не так далеко відійшли від Сенаріуса, як вважає Фандрал...$B$BЕ-е-е, у будь-якому разі, будь ласка — прийми це як знак подяки від Кола Сенаріона.",
