[5061] = {
    en = "Aquatic Form",
    T = "Водна форма",
    D = "Ти пройшов усі необхідні уроки, які проходять усі молоді друїди, перш ніж вони зможуть прийняти водний аспект. Тепер повертайся до свого наставника, Матренгіла Беарвокера, у Дарнассусі. Покажи йому свій кулон і доведи, що ти готовий навчитися тому, чого він тебе навчить. Він завершить ваше навчання, що дозволить вам стати єдиним цілим із водою.$B$BДо побачення, юний друїде. Ми ще поговоримо.",
    O = "Поверніться до Дарнассуса та покажіть Матренгілу Ведмедоходу кулон морського лева.",
    P = "Твоє повернення до Дарнассуса не залишилося непоміченим, хоча мені знадобиться доказ того, що ти засвоїв уроки, отримані в Місячній галявині, перш ніж я навчу тебе приймати водну форму.$B$BЧи є у тебе кулон морського лева?",
    C = "Дуже вражаюче, $N. Ти готовий опанувати свою водну форму, і я з радістю навчу тебе цьому.$B$BКрім того, на знак визнання твоїх досягнень під час двох випробувань я дарую тобі цей предмет. Сподіваюся, він стане для тебе цінним доповненням до спорядження як захисника природи та охоронця рівноваги.",
},

[5062] = {
    en = "Sacred Fire",
    T = "Священний вогонь",
    D = "Арікара — смертоносна істота, з якою треба швидко розправитися. Щоб її вистежити, вам доведеться розпалити священний вогонь життя — це викличе Арікару.$B$BІдіть зараз і зберіть рідкісну рослину агаву «Інсендія». Зібравши достатню кількість агави, зверніться за порадою до Магати Грімтотем на Старій Горі в Громовому Утворі. Вона — могутня шаманка, яка може зачарувати агаву, щоб створити порошок, необхідний для розпалювання вогню.$B$BПрямуйте на північний схід до Киплячого Басейну та зберіть агаву «Інсендія».",
    O = "Зберіть 10 бушелів агави «Інсендія», а потім зверніться до Магати Грімтотем на Елдер-Райз у Громовому Утворі.",
    P = "Отже, Мотега Файрмейн надіслав звістку про Арікару... що ж, це справді серйозна новина.$B$B<Магата озирається.>$B$BАрікара — це смертоносна істота, покликана лише для того, щоб мститися тим, хто вчинив жахливі злочини.$B$B<Магата посміхається.>",
