    P = "",
    C = "У казані вирує гнила речовина з огидним запахом...",
},

[5085] = {
    en = "Mystery Goo",
    T = "Таємнича субстанція",
    D = "Зеленувата речовина всередині казана, схоже, подібна до тієї, яку ти знайшов у колбі. Ця дивна липка субстанція може бути настільки ж зіпсованою, як і фурборг, що її створив...$B$BЯкщо фурболги з Вінтерфолла використовують її, чи означає це, що незабаром вони стануть такими ж зіпсованими, як плем’я Дедвуд?$B$BНайкраще буде доповісти Донові про ваші знахідки, а також передати їй зразок рідини з казана.",
    O = "Повідомте Донову Сноудену про свої висновки.",
