},

[5673] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Ти знаєш, що можеш звернутися до будь-якого з наших наставників у будь-який час, $N, але є деякі речі, які ми не можемо тобі передати. Одне з таких — це вчення вашої богині Елуни. Вона дарує особливі здібності своїм вірним, і, якщо я не помиляюся, настав час вам повернутися додому, до Храму Місяця, щоб пройти випробування.$B$BПоверніться туди, коли зможете, і поговоріть із жрицею Алатеєю.",
    O = "Поговоріть із жрицею Алатеєю в Дарнассусі.",
