[5674] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Настав чудовий день, $N. Ти досяг того віку, коли наших $gpriests:priestesses; навчають навичкам, відомим лише нічним ельфам. Але навчати тебе — не моя справа. Як тільки ти завершиш свої справи тут, тобі слід повернутися до Храму Місяця й поговорити з жрицею Алатеєю. Вона перевірить тебе, щоб переконатися, що ти готовий, і лише тоді навчить тебе «Благодаті Елуни».",
    O = "Поговоріть із жрицею Алатеєю в Дарнассусі.",
    P = "",
    C = "Присвятивши себе Елуні та нашому народу, ти досягнув стану, якого не всім з нас вдається досягти. За традицією, за твою відданість тобі мають бути передані ще більші здібності. Чи погоджуєшся ти?",
},

[5675] = {
    en = "Elune's Grace",
    T = "Благодать Елуни",
    D = "Час не чекає, $glad:lass;. Настав час повертатися додому, у Дарнассус. Жриця Алатея надіслала повідомлення, що ти маєш повернутися туди для навчання. Схоже, вони вважають, що ти готовий пройти випробування, подібні до тих, що проходять ті, хто служить Світлу. Тобі слід вирушати, щойно з’явиться можливість. У повідомленні Алатеї сказано, що вона чекатиме на тебе в Храмі Місяця. Удачі.",
    O = "Поговоріть із жрицею Алатеєю в Дарнасусі.",
    P = "",
    C = "Нехай Елуна благословить тебе за те, що ти так швидко повернувся до нас. Це важливий етап у твоєму навчанні, і всі члени нашого ордену ставляться до нього дуже серйозно. Коли ти відпочинеш після подорожі, будь ласка, дай мені знати. Тоді ми зможемо обговорити подальше навчання та те, куди тебе приведе твій шлях.",
},

[5676] = {
    en = "Arcane Feedback",
    T = "Відгуки про «Arcane»",
    D = "",
    O = "",
    P = "",
    C = "Ми були змушені опанувати деякі магічні вміння, щоб захиститися від того, що зазвичай називають нашим найбільшим ворогом: таємних сил.$B$BЯ навчу тебе заклинанню, яке допоможе тобі захистити себе та своїх товаришів від тих, хто володіє такою силою.",
},

[5677] = {
    en = "Arcane Feedback",
    T = "Відгуки про «Arcane»",
    D = "Хоч як би я хотів показати тобі наші особливі вчення Світла, це не наша справа. Твоє місце — у Штормвінд, серед своїх, $N… поки що. Повір мені, я не хочу тебе образити. Коли ти повернешся до верховної жриці Лаурени в Соборі Світла, ти зрозумієш, про що я говорю — настав час, щоб твоя раса підготувала тебе до майбутнього; щоб ти відокремився від інших, які йдуть схожим шляхом.",
    O = "Поговоріть з Верховним жрицею Лауреною у Штормграді.",
    P = "",
    C = "Ах, ти з’явився якраз вчасно, $n. Я вже почав замислюватися, чи всі мої посланці досягли успіху. Радий бачити, що так і сталося, інакше, мабуть, ти досі б мандрував світом, дізнаючись більше про всі загрози, що існують для нашого народу.$B$BТи готовий? Маю на увазі, готовий до подальшого навчання. Твоя сила зростає дедалі швидше, і я відчуваю, що ти готовий дізнатися більше про нашу віру.",
},

[5678] = {
    en = "Arcane Feedback",
    T = "Відгуки про «Arcane»",
    D = "Настав час тобі повернутися до Штормвінда, юний друже. Твої начальники там викликали тебе назад для подальшого навчання. І хоча це мене дещо турбує, твоя раса і моя — союзники, і я не збираюся зраджувати цю союзницьку присягу.$B$BЯ не хочу здаватися тобі надто ухильним — моя недовіра до таємної магії, натхненної божественним чи ні, досі сильна в мені.$B$BТи зрозумієш, про що я говорю, коли повернешся до свого Собору Світла. По прибутті звернися до Верховного Жерця Лаурени.",
    O = "Поговоріть із Верховним жрицею Лауреною у Штормграді.",
    P = "",
    C = "Ах, ти з’явився якраз вчасно, $n. Я вже почав сумніватися, чи всі мої посланці досягли успіху. Радий бачити, що так і сталося, інакше, я б побився об заклад, ти досі б мандрував світом, дізнаючись більше про всі загрози, що існують для нашого народу.$B$BТи готовий? Маю на увазі, готовий до подальшого навчання. Твоя сила зростає дедалі швидше, і я відчуваю, що ти готовий дізнатися більше про нашу віру.",
},

[5679] = {
    en = "Devouring Plague",
    T = "Пожираюча чума",
    D = "",
    O = "",
    P = "",
    C = "Я навчу тебе заклинання «Пожираюча чума», якщо ти вважаєш, що готовий, $N. Це заклинання неабиякої сили, і воно стане тобі в нагоді в майбутніх боях. Потренуйся з ним — пізніше будуть випробування.",
},

[5680] = {
    en = "Shadowguard",
    T = "Тіньова гвардія",
    D = "",
    O = "",
    P = "",
    C = "Твої обряди настануть досить скоро. А поки що я навчу тебе заклинанню, яке стане тобі у великій нагоді під час битви з ворогами.",
},

[5713] = {
    en = "One Shot.  One Kill.",
    T = "Один постріл. Одне вбивство.",
    D = "Я прямував до Аубердіна з важливим повідомленням, коли на мене напав фурболг Марош та його слідопити. Під час нападу мене отруїли, і я ледь міг стояти на ногах. Я можу приготувати протиотруту, але на це знадобиться час.$B$BПрошу вас захищати мене, доки я не зможу застосувати протиотруту. Я допоможу вам зі свого лука, як тільки зможу.$B$BЯкщо ми виживемо, я зможу доставити своє повідомлення до Аубердіна, а ви — поговорити з Онаєєю в Посту Маестри, щоб повідомити їй про цей інцидент.",
    O = "Захистіть Сентинела Айнашу, а потім поговоріть з Онаєєю в «Посту Маестри» в Попеліній долині.",
    P = "Ви не бачили на дорозі Сентинел Айнашу? Вона вирушила на важливе завдання, але ще не повернулася.",
    C = "Ти приніс дуже радісну новину $C. Приємно чути, що Айнаша жива й здорова завдяки тобі. Сподіваюся, ти приймеш нагороду за свою хоробрість. Нехай Елуна береже тебе й освітлює твій шлях.",
},

[5721] = {
    en = "The Battle of Darrowshire",
    T = "Битва при Дарроуширі",
    D = "Тепер, $N, ти візьмеш участь у битві за Дарроушир і врятуєш Джозефа Редпата.$B$BПоклади цей зв’язок реліквій на міській площі Дарроушира, і духи Дарроушира прокинуться. Приєднайся до їхньої битви та подбай про те, щоб сталися дві речі: Давіл повинен вижити після смерті Хоргуса, а Редпат — вижити, щоб спочатку бути спокушеним, а потім — переможеним.$B$BПісля перемоги над спокушеним Редпатом його дух буде врятований. Поговоріть із ним, а потім поверніться до його доньки Памели.",
    O = "Покладіть «Зв'язку реліквій» на міській площі Дарроуширу.$B$BНе допустіть смерті Девіла Лайтфайра до смерті Хоргуса.$B$BНе допустіть смерті капітана Редпата до появи «Редпата Скаженого».$B$BПереможіть «Зіпсованого Редпата».$B$BПоговоріть із духом Джозефа Редпата, коли він з’явиться на міській площі, а потім поговоріть із Памелою в її будинку.",
    P = "Мені здається, я почув на вулиці привидів. Вони шепочуть мені щось страшне...",
    C = "Бійка закінчилася! Я почула, як тато прошепотів мені. Він прогнав усіх привидів і каже, що повертається додому! Я така щаслива!$B$BВін також сказав, що я маю тебе привітати, якщо ти завітаєш до нас додому, тож я заварила чай!$B$BСподіваюся, ти любиш багато цукру!",
},

[5722] = {
    en = "Searching for the Lost Satchel",
    T = "У пошуках загубленої сумки",
    D = "Троги — не єдине, що зацікавило Магату в Ущелині Лютого Вогню. До неї дійшли чутки, що один із її слуг, Маур Грімтотем, знайшов у Ущелині щось дивне, але так і не зміг вибратися звідти, щоб показати їй, що саме. Вона хотіла б, щоб було знайдено тіло Маура — якщо воно ще існує — та будь-які сліди того, що він виявив, намагаючись поговорити з трогами.$B$BПоверніть Магаті всі предмети, що можуть її зацікавити, і я впевнений, що вона щедро винагородить вас.$B$BЗнову ж таки, шукайте Ущелину в найтемніших куточках Оргримара.",
    O = "Прошу обшукати ущелину Рейджфайр, щоб знайти тіло Маура Грімтотема, та перевірити його на наявність будь-яких цінних предметів.",
    P = "",
    C = "Тіло має сліди сильного побиття палицями або кулаками, але більша частина одягу та спорядження трупа, здається, залишилася на місці. Схоже, троги не надто переймаються матеріальними благами.$B$BВи починаєте обшукувати тіло в пошуках чогось цікавого, що могло б допомогти Магаті.",
},

[5723] = {
    en = "Testing an Enemy's Strength",
    T = "Випробування сили супротивника",
    D = "Під містом Оргримар з глибин тунелів, заповнених лавою, на поверхню почали виходити кремезні істоти, відомі як троги. Магата, як завжди доброзичлива, спробувала укласти мир з цими істотами, але вони напали на її дипломатів і вбили їх. Вона не дозволить такого ставлення до народу тауренів і тепер вважає цих істот загрозою для всієї Орди.$B$BВона просить вас покласти край цій загрозі з боку трогів, перш ніж вони заполонять Орду з-під землі. Знайдіть Ущелину Лютого Вогню та знищіть їх усіх.",
    O = "Знайдіть у Оргримарі Ущелину Лютьвого Вогню, а потім знищіть 8 трогів Лютвого Вогню та 8 шаманів Лютвого Вогню, після чого поверніться до Рахауро в Громовому Утворі.",
    P = "Як просувається твій пошук «Ущелини»? А як щодо трогів?$B$BНе можна допустити, щоб ця загроза зберігалася — якщо вона триватиме, це лише завдасть шкоди нашим братам-оркам.",
    C = "Я радий, що ти серйозно поставився до завдання Магати. Дякую, $N. Я впевнений, що трогам буде набагато важче вийти на поверхню, оскільки їхня чисельність так сильно зменшилася.$B$BМожливо, в майбутньому ми зможемо знайти час, щоб з'ясувати, звідки взялися ці істоти і чого вони насправді хочуть.",
},

[5724] = {
    en = "Returning the Lost Satchel",
    T = "Повернення загубленої сумки",
    D = "Під тілом таурена ви знаходите сумку. Він досі міцно стискає її в руках, ніби намагався захистити її під час нападу трогів.$B$BВирвавши сумку з його залізного хвату, ви складаєте її до свого спорядження й готуєтеся вибратися з тунелів та повернутися до Рахауро в Громовому Утворі.",
    O = "Віднесіть сумку «Грімтотем» Рахауро в Грім-Блафф.",
    P = "Тобі вдалося щось дізнатися, $N? Будь-які підказки щодо того, чому один із членів її клану мав безпідставно загинути, були б дуже корисними.",
    C = "Чудово, $N. Дякую.$B$BМагата сказала мені, що якщо тобі вдасться знайти її одноплемінника, тобі передадуть це. Будь ласка, прийми це на знак подяки.",
},

[5725] = {
    en = "The Power to Destroy...",
    T = "Сила руйнувати...",
    D = "Як вам, мабуть, відомо, багато мешканців Легіону дарують подарунки своїм послідовникам. Темна Леді вважає, що деякі з цих дарів краще зберігати в її руках, ніж у руках тих, хто має... менш проникливий погляд.$B$BЯскравим прикладом цього є секта Ради Тіней, що ховається в печерах під Оргримаром і відома як «Палюче Лезо». Пані розповіла мені, що члени «Палаючого меча» заволоділи двома потужними книгами заклинань — вона хотіла б «позичити» ці книги у них. Ви повинні дістати їх для неї.",
    O = "Принесіть книги «Заклинання тіні» та «Заклинання з Потойбіччя» Варіматрасу в Андерсіті.",
    P = "На мене чекає ще з сотню інших справ, $c. У тебе є книги?",
    C = "Добре, $c. Ти добре послужив Темній Пані. Твоя незламна наполегливість і амбіції стануть у нагоді підданим Пані. Повертайся до мене знову в майбутньому. Можливо, у мене будуть для тебе інші завдання, які допоможуть Темній Леді в її спробах перемогти Короля Ліча та остаточно звільнити Плеть.",
},

[5726] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Єдина річ, яку я не терпітиму, — це зрадники серед нас, $N. Але я був би дурнем, якби розкрив свої карти так рано — це не дозволило б повністю викорінити корупцію з наших земель, а лише призвело б до подальшого поширення цієї зарази.$B$BАле ти, молодий мандрівник, міг би дістатися туди, куди не змогли б мої агенти… міг би дізнатися правду… міг би знайти справжнього ватажка цієї bestii.$B$BЯкщо ти достатньо сміливий, то зайди до Скелі Черепа на схід від Оргримара, знайди там значок лейтенанта на одному з воїнів «Палаючого Меча» і повернися до мене.",
    O = "Принесіть значок лейтенанта Тралу в Оргримарі.",
    P = "Ти вже отримав значок, $N?$B$BВін стане незамінним інструментом для проникнення в те, що, на мою думку, є найбільшою загрозою для Орди, і для того, щоб нарешті знайти спокій у нашій новій батьківщині.$B$BТи дізнаєшся, яку хитромудру павутину можуть сплести як люди, так і орки, коли їх рухають жага до наживи та влади. Приховані мотиви, корупція — все це стане зрозумілим. Ти опинишся в епіцентрі війни, про існування якої навіть не підозрював.",
    C = "Чудово, $N! Слава духам, можливо, саме ти той, хто нарешті розвіє мої найбільші побоювання! Хто б міг подумати, що хтось такий молодий і такий хоробрий підніметься й стане захисником нашої справи? Ти нагадуєш мені мене самого, коли я був молодшим. Я подбаю, щоб ти отримав справедливу винагороду за свої зусилля, якщо ми обоє переживемо майбутню бурю.$B$BАле похвали ще буде час пізніше. Ти ще нічого не досягнув порівняно з тим, що тобі доведеться пережити... але це гарний початок.",
},

[5727] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "А тепер давайте подивимося, чи варта ця значка, яку ти знайшов, витрачених зусиль.$B$BУ місті є чаклун, який вважає, що користується моєю довірою. Він не знає, що я усвідомлюю, кому насправді віддана його вірність. Насправді він — ватажок «Палаючого Меча». Але не поспішайте вступати з ним у бій; у нього є своя мета, і ми використаємо його проти наших ворогів.$B$BВіднесіть цей знак до нього в «Тріщину Тіні» тут, в Оргримарі, поговоріть з ним і перевірте, чи вважає він вас одним зі своїх, а потім поверніться до мене сюди.",
    O = "Віднесіть значок лейтенанта до Неру Фаєрблейда і поговоріть з ним. З’ясуйте, чи вважає він вас членом «Палаючого меча», а потім поверніться до Тралла в Оргримарі.",
    P = "Ну, $c? Чи повірив він у нашу хитрість, чи ситуація гірша, ніж я спочатку припускав?$B$BЯкщо ми доведемо свою цінність для Неру, це значно полегшить нам проникнення до Ради Тіней. У нього буде чимало інформації, яку ми зможемо використати, щоб викрити тих, хто прагне знищити все, що ми побудували в Дуротарі.",
    C = "Чудово! Просто чудово, $c!$B$BТе, що ти зробив сьогодні, — це лише перший крок у створенні набагато ширшого фундаменту — фундаменту, на якому ми раз і назавжди зруйнуємо Раду Тіней.$B$BРозкажи мені все, що він сказав... і не пропусти жодного слова — це може виявитися важливішим, ніж ти уявляєш.",
},

[5728] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Хм, ватажки «Палаючого Меча»... це мене турбує найбільше. Якщо саме вони мають цінність для Неру, то саме на них ми маємо націлитися в першу чергу. Цей сатир... Баззалан та інший, про якого згадував Неру — хто він був, чаклун? — мають бути вбиті.$B$BПоверніться до «Тріщини Тіні» та увійдіть у «Ущелину Лютого Вогню», $N. Знайдіть цих двох ватажків «Палаючого меча» і вбийте їх. Але будьте обережні, щоб Неру не дізнався, що це зробили саме ви. Ви повинні зберегти свою репутацію як одного з його $gbrothers:sisters; соратників.",
    O = "Вбийте Баззалана та Джергоша-Заклинателя, а потім поверніться до Тролла в Оргримарі.",
    P = "Ти вже їх знайшов, $N? Лідерів «Палючого Клинка».$B$BЯ знав, що Рада Тіней прагне відібрати в мене Оргримар і всю Орду, але не усвідомлював, як швидко їм вдалося проникнути в місто. У цієї потвори стільки рук… Ми можемо відрубувати їх, доки вона не вичерпається, але ми не просунемося далі, ніж були спочатку. Мені доведеться змусити своїх шпигунів подвоїти зусилля.",
    C = "Я радий, що ти повернувся, $N. Деякі з моїх вірних одразу ж повідомили, що в печерах під Оргримаром запанував хаос після того, як їхніх ватажків було вбито. Я навіть чув, що Неру був дуже схвильований. Схоже, ми завдали йому серйозного удару. Не можу сказати, що я незадоволений… навіть такою незначною перемогою.",
},

[5729] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Гадаю, нашим наступним кроком має бути те, щоб тебе розмістили поруч із Неру. Якщо він справді такий схвильований, як свідчать звіти, то ми зможемо досягти двох цілей. По-перше, ти, можливо, зможеш дізнатися більше про Раду або, принаймні, про «Палаюче Лезо», а по-друге, він може почати довіряти тобі настільки, що попросить тебе допомогти йому. Цілком імовірно, що він сприйме тебе як людину, здатну заповнити порожнечу, що утворилася через хаос у керівництві.$B$BПовернися до Ущелини й поговори з ним ще раз, але не будь надто відвертим.",
    O = "Поговоріть з Неру Фаєрблейд в Оргримарі.",
    P = "",
    C = "Що це таке?! О, ти, $c... пробач. Мій гнів не поступається гніву скаженого бика-кодо... але, можливо, це моя власна вина. Відправляючи мандрівників у Ущелину Лютого Вогню, я мав передбачити, що це може призвести до лиха. Схоже, і Баззалан, і Джергош були захоплені зненацька й убиті якимись «доброчинцями» Тралла. Найневідповідніший момент, але тепер уже нічого не вдієш.",
},

[5730] = {
    en = "Hidden Enemies",
    T = "Приховані вороги",
    D = "Ти — один із моїх лейтенантів! Готуйся, $c. Я незабаром звернуся до тебе.$B$BМожливо, час, який я присвятив «Палючому мечу», тепер практично змарновано, але це не означає, що плани Ради Тіней в інших місцях мають постраждати. Я зроблю все, що зможу, аби мінімізувати збитки тут, у «Ущелині Лютьвогню». Тим часом мої агенти в «Пустошах» та «Попеліній долині» почнуть працювати над нашим новим планом. Повертайся до мене якнайшвидше.",
    O = "Поговоріть із Тролом в Оргримарі та розкажіть йому про те, що ви дізналися.",
    P = "",
    C = "Ашенвейл? Хм, я не чув про присутність Ради чи «Палаючого меча» в Ашенвейлі. Мої шпигуни розберуться з цим, $N. Ти добре впорався.$B$BА поки що відпочинь і займися іншими справами. Я незабаром знову звернуся до тебе.$B$BЛок-Тар Огар!",
},

[5741] = {
    en = "Sceptre of Light",
    T = "Скіпетр Світла",
    D = "Ходять чутки, що «Палаюче Лезо» у фортеці «Громовий Сокира», що на сході, здобуло Скіпетр Світла у нагів. Легенда розповідає, що цей скіпетр здатний занурити цілі міста під великі моря. Не можна допустити, щоб «Палаюче Лезо» заволоділо такою силою.$B$BТому ви повинні самостійно відібрати скіпетр! Його зберігає провидець «Палаючого Леза», який вивчає скіпетр, сидячи на вершині однієї з сторожових веж «Громового Сокири».$B",
    O = "Знайдіть Скіпетр Світла, а потім поверніть його Азору Алдаморту у вежі в Етель-Ретор.$B",
    P = "У вас є Скіпетр Світла?$B",
    C = "Недосяжний Скіпетр Світла! Те, що ти його здобув, усунуло серйозну загрозу для світу. Молодець, $c, молодець.$B",
},

[5742] = {
    en = "Redemption",
    T = "Спокута",
    D = "Ти добре попрацював, друже. Дай своїм втомленим кісткам відпочити, а я тим часом дозволь мені як слід представитися.$B",
    O = "Послухайте, що має сказати Тіріон Фордрінг.",
    P = "Будь ласка, друже, сідай і вислухай мою історію.",
    C = "Повернення Фордрінга стане складним завданням. Ви готові?",
},

[5761] = {
    en = "Slaying the Beast",
    T = "Знищення Звіра",
    D = "Головне завдання, яке поставив переді мною наш великий Вождь, — це викорінити істот, винних у тому, що велике місто нашого володаря заполонило демонічне впливом. «Палаюче Лезо» — це одна з загроз, але є й інші; наприклад, «Пекуче Лезо», яке оселилося в Ущелині Лютого Вогню й таємно намагається звести з правильного шляху невинних членів Орди.$B$BЩоб зупинити їх, треба вбити їхнього ватажка — фель-охоронця на ім’я Тарагаман Голодний.$B$BВбийте його, і його серце заспокоїть Тралла — у цьому я впевнений.",
    O = "Увійдіть до Ущелини «Рейджфайр» і вбийте Тарагамана Голодного, а потім принесіть його серце Нееру Фаєрблейду в Оргримарі.",
    P = "Ти вбив ту потвору? Це, безперечно, лідер «Палючого меча» в Ущелині Лютьвогню.",
    C = "Ха! Ти це зробив! Трал буде дуже задоволений.$B$BЯ подбаю, щоб про це серце належним чином подбали.$B$BА поки що ти повинен відсвяткувати свою перемогу. Я повідомлю Тралла про твій успіх.$B$BДякую за допомогу, $c.",
},

[5762] = {
    en = "Hemet Nesingwary",
    T = "Хемет Несінгварі",
    D = "У мене є посилка для мого давнього клієнта, карлика на ім’я Хемет Несінгварі. Посилка йшла кілька тижнів, а Хемет уже давно поїхав. Він казав, що їде до Странглторна полювати на тамтешніх звірів, але залишив мені трохи грошей, щоб я відправив йому посилку, коли зможу. $B$BХемет — багатий гном, а підтримувати стосунки з багатіями — це ж добре, чи не так? Тож... ти хочеш доставити цю посилку за мене?$B$BЯ чув, що у Хемета є табір у Странглторні, на північ від Гром’гола.",
    O = "Віднесіть ящик Кравела Хемету Несінгварі в Стренглторні.",
    P = "Це пустельний пил на твоєму комірі?$B$BГм... якщо мій нюх мене не підводить, то я б сказав, що це не пустельний пил, а пустельна сіль! Ти, мабуть, був на Мерехтливих рівнинах, чи не так?",
    C = "Супер, моя посилка від Коалбірда! Дякую, $N. У цій скриньці — патрони нестандартного калібру, вони нам дуже знадобляться в джунглях!$B$BОсь твоя плата, а тепер скажи, як там поживає старий буркотун Кравел? Готовий побитися об заклад, що він, як і раніше, замишляє щось недобре...",
},

[5763] = {
    en = "Hunting in Stranglethorn",
    T = "Полювання в Стренглторні",
    D = "Давним-давно на цю землю прибув гном. Його звали Хемет, і він мріяв полювати на величезних звірів. Він мав надзвичайну вправність у стрільбі з рушниці, і ми провели багато днів, полюючи разом. Навіть ворожнеча між нашими народами відійшла на другий план.$B$BКоли він покинув Десолас і вирушив до Странглторна, я пообіцяв собі, що одного дня зустріну його, щоб ми знову могли полювати разом. Тепер настав той час.$B$BВіднеси цей ріг кодо Хемету. Він зрозуміє, що це від мене. Ти знайдеш його у Странглторні, на північ від базового табору Гром'гол.",
    O = "Принесіть ріг Кодо з Руна Хемету Несінгварі в Странглторні.",
    P = "Сідай, $c. Незабаром ти знову вирушиш у джунглі.",
    C = "Ах, цей ріг належить таурену, Руну Вайлдмейну. Ми з ним чудово провели час, полюючи на звірів у Десоласі. Тож Рун знову запрошує мене, так?$B$BЗараз ми по самі вуха в джунглях, але дякую, $N. Можливо, моя наступна експедиція знову приведе мене до Десоласу, країни кентаврів.",
},

[5781] = {
    en = "Of Forgotten Memories",
    T = "Про забуті спогади",
    D = "Щоб допомогти Таелану повернути те, що він втратив, ти повинен зібрати предмети з його минулого.$B$BПерший із таких предметів — іграшка, яку я подарував йому на 7-й день народження. Це була його найдорожча річ: мініатюрний бойовий молот — точна копія мого власного.$B$BПісля того, як мене було заслано за зраду, його мати сказала йому, що я загинув. Його відвели до моєї фальшивої могили в Підземеллі, де він поховав молот разом із пам’яттю про мене — назавжди.$B$BТи повинен відправитися до Підземелля й повернути молот Таелана.",
    O = "Відправляйтеся до «Підземелля» — у найпівденнішу частину Східних Земель Чуми — і знайдіть Молот Таелана. Після виконання завдання поверніться до Тіріона Фордрінга.",
    P = "Його треба спасти.",
    C = "<Тіріон мружить очі, намагаючись стримати сльози.>$B$BНаша зустріч була долею, $N. Ти обдарував мене своєю добротою.$B",
},

[5801] = {
    en = "Fire Plume Forged",
    T = "«Вогняний стовп»",
    D = "Щоб викувати стрижень ключа, тобі знадобляться два бруски торію та надзвичайно гаряче джерело тепла. З торієм тобі доведеться розібратися самому, але я можу допомогти з теплом.$B$BНа захід від нас, у кратері Ун’Горо, розташований хребет «Вогняний стовп» — діючий вулкан. Лавове озеро на вершині достатньо гаряче, щоб з'єднати торій і кістку. За своє золото ви придбали форму, яку потрібно просто занурити в озеро на вершині; про решту подбає лава.$B$BЗ мого боку це все. Щоб завершити створення ключа, вам потрібно знову поговорити з Арбінгтоном.",
    O = "Віднесіть форму для скелетного ключа та 2 злитки торію на вершину хребта «Вогняний шлейф» у кратері Ун’Горо. Використайте форму «Універсального ключа» біля лавового озера, щоб викувати «Незавершений універсальний ключ».$B$BВіднесіть «Незавершений універсальний ключ» алхіміку Арбінгтону в «Холодновітровій мисі», що у Західних Землях Чуми.",
    P = "Ти вже завершив роботу над хвостовиком скелетного ключа? Мені справді шкода, що тобі довелося взяти на себе основну частину витрат на придбання форми, але ми всі маємо докласти зусиль, щоб протистояти Плеті. Як тільки ти передасиш мені незавершений ключ, ти отримаєш останній елемент, необхідний для завершення його виготовлення.$B$BЦе буде зовсім нелегко, але робота, яку ти проробив досі, готуючись до штурму Андорхала, тепер почне окупатися. Ти сам побачиш.",
    C = "У нас тут вийшов досить дорогий універсальний ключ, чи не так $N? Проте він досі незавершений; настав час приділити нашому творінню належну увагу. З цією метою тобі доведеться зіткнутися з наймогутнішим ворогом, до зустрічі з яким ми готувалися в Андорхалі... істотою, яка керує всім, що відбувається в руїнах міста.$B$BЯ маю на увазі Араджа Заклинателя — ліча, одного з наймогутніших створінь, які належать до лав Плеті.[/PH2][/PH1]",
},

[5802] = {
    en = "Fire Plume Forged",
    T = "«Вогняний шлейф» — коване",
    D = "Щоб викувати стрижень ключа, тобі знадобляться дві бруски торію та надзвичайно гаряче джерело тепла. З торієм тобі доведеться розібратися самому, але я можу допомогти з теплом.$B$BНа захід від нас, у кратері Ун’Горо, розташований хребет «Вогняний стовп» — вулкан, що кипить. Лавове озеро на вершині достатньо гаряче, щоб з'єднати торій і кістку. За своє золото ви придбали форму, яку потрібно лише занурити в озеро на вершині; про решту подбає лава.$B$BЗ мого боку все. Щоб завершити створення ключа, вам потрібно знову поговорити з Дітерсом.",
    O = "Віднесіть форму для скелетного ключа та 2 бруски торію на вершину хребта «Вогняний стовп» у кратері Ун’Горо. Використовуйте форму «Універсального ключа» біля лавового озера, щоб викувати «Незавершений універсальний ключ».$B$BВіднесіть «Незавершений універсальний ключ» до аптекаря Дітерса в «Балварку», що у Західних Землях Чуми.",
    P = "Ти вже закінчив виготовляти держак скелетного ключа? Мені справді шкода, що тобі довелося взяти на себе основну частину витрат на придбання форми, але ми всі маємо докласти зусиль, щоб протистояти Поразі. Як тільки ти передасиш мені незавершений ключ, ти отримаєш останній елемент, необхідний для завершення його виготовлення.$B$BЦе буде зовсім нелегко, але робота, яку ти провів досі, готуючись до штурму Андорхала, тепер почне приносити плоди. Ти сам побачиш.",
    C = "У нас тут вийшов досить дорогий універсальний ключ, чи не так $N? Проте він досі незавершений; настав час приділити нашому творінню належну увагу. Для цього тобі доведеться зіткнутися з найстрашнішим ворогом, до зустрічі з яким ми готувалися в Андорхалі... істотою, яка керує всім, що відбувається в руїнах міста.$B$BЯ маю на увазі Араджа Заклинателя — ліча, одного з наймогутніших створінь, що належать до лав Плеті.",
},

[5803] = {
    en = "Araj's Scarab",
    T = "Скарабей Араджа",
    D = "Арадж-Заклинатель панує над Андорхалом із самого серця зруйнованого міста. Ми знаємо, що він був колишнім лідером Шоломанса, перш ніж захопив місто. Щоб завершити створення ключа, нам знадобиться його печатка — так званий скарабей — яку слід встановити на кінці ключа.$B$BПробийтеся до самого серця Андорхала й покладіть край його пануванню над містом, поки він перебуває на відкритому просторі. Знищивши його, заберіть його скарабея з його поваленого філактерія!$B$BКлюч до Шоломанса чекає на вас, $N!",
    O = "Знищте Араджа-заклинателя та принесіть скарабея Араджа алхіміку Арбінгтону в Місце Холодного Вітру, що у Західних Землях Чуми.",
    P = "Ти вже дійшов аж сюди $N — лише знищення фізичної форми Араджа-Заклинателя дасть нам можливість завершити створення ключа. За будь-яку ціну дістань скарабея Араджа і принеси його мені — я прикріплю його як головку ключа.",
    C = "Так, саме це! Я… знову я абсолютно вражений глибиною твоєї хитрості та хоробрості. Просто вражає, на що ти готовий піти заради перемоги.$B$BДозволь мені тепер внести свій невеликий вклад у це. Я підготував спеціальний розчинник, який має дозволити мені закріпити скарабея на кінці ключа, наділивши його силою, здатною прорвати зачинені двері Шоломанса.$B$BЦе займе лише мить...",
},

[5804] = {
    en = "Araj's Scarab",
    T = "Скарабей Араджа",
    D = "Арадж-Прикликач панує над Андорхалом із самого серця зруйнованого міста. Ми знаємо, що він був колишнім лідером Шоломанса, перш ніж захопив місто. Щоб завершити створення ключа, нам знадобиться його печатка — так званий скарабей — яку слід встановити на кінці ключа.$B$BПробийтеся до самого серця Андорхала й покладіть край його пануванню над містом, поки він висунувся на відкрите місце. Знищивши його, заберіть його скарабея з його поваленого філактерію!$B$BКлюч до Шоломанса чекає на вас, $N!",
    O = "Знищте Араджа-заклинателя та принесіть скарабея Араджа аптекарю Дітерсу в «Булварк», що у Західних Землях Чуми.",
    P = "Ти вже дійшов аж сюди $N — лише знищення фізичної форми Араджа-Прикликача дасть нам можливість завершити створення ключа. Здобудь скарабея Араджа будь-якими засобами і принеси його мені — я вмонтую його як головку ключа.",
    C = "Так, саме це! Я… знову я абсолютно вражений глибиною твоєї хитрості та хоробрості. Просто вражає, на що ти готовий піти, аби здобути перемогу.$B$BДозволь мені тепер внести свій невеликий вклад у цю справу. Я підготував спеціальний розчинник, який має дозволити мені закріпити скарабея на кінці ключа, наділивши його силою, здатною прорвати зачинені двері Шоломанса.$B$BЦе займе лише мить...",
},

[5821] = {
    en = "Bodyguard for Hire ",
    T = "Охоронець на замовлення",
    D = "За звичайних обставин ми з Ріггером вели б нашого кодо повз кентавра з Колкара. Час від часу ми чуємо бойові барабани кентавра, і коли їх чуємо, ми зупиняємося. Померти — це погано для бізнесу!$B$BСкажу тобі так, $c, якщо ти захистиш нас, поки ми проїдемо повз село Колкар, ми винагородимо тебе.$B$BВідстань невелика, тобі потрібно лише зберегти караван цілим, і ти зможеш забрати свою винагороду у Сміда Скрабблскрю — він трохи далі по дорозі. Ми трохи ведемо спільні справи.",
    O = "Супроводи караван Гізелтона повз село кентаврів Колкар. Поговори зі Смідом у таборі Скрабблскрю, щоб отримати нагороду.",
    P = "Чому я, власне, чекаю на цей клятий караван?$B$B<Смід виглядає так, ніби щось зрозумів.>$B$BА, так, адже вони оплачують рахунки. Ти їх бачив?",
    C = "Знаєш, не дуже вигідно, мабуть, платити таким, як ти, за охорону каравану «Гізелтон». $C, якби я був трохи вищим, то міг би влаштуватися на другу роботу — сидіти верхи на кодо з найбільшою зброєю, яку тільки змогли б утримати мої руки… і показав би цим клятим кентаврам, хто тут головний.",
},

[5845] = {
    en = "Of Lost Honor",
    T = "Про втрачену честь",
    D = "Орден Срібної Руки зазнав повного розгрому після загибелі Утера.$B$BХлопець тримався, скільки міг. Відтіснений до розтрощеного війною селища Нортдейл, він вступив у останній бій.$B$BЧи залишився хтось із Ордену живим, — подумав він, — і чи мало це значення?$B$BСаме з цією думкою Телан кинув прапор Ордену й зрікся всього, що знав. Його честь залишилася на просоченій кров’ю землі Нортдейла.$B$BТи повинен вирушити до Нортдейла й повернути цей символ втраченої честі.",
    O = "Відправляйтеся до Нортдейла, що розташований у північно-східній частині Східних Земель Чуми, і знайдіть «Символ втраченої честі». Після виконання завдання поверніться до Тіріона Фордрінга.",
    P = "Моя віра буде твоїм дороговказом, $N. Світло не знає меж.",
    C = "Вона й зараз — навіть у своєму пошарпаному стані — така ж велична, як і того дня, коли я вперше побачив її й склав присягу на вірність.$B$BНастає його спокута, і, можливо, разом із нею — й моя...",
},

[5846] = {
    en = "Of Love and Family",
    T = "Про кохання та сім’ю",
    D = "Коли Таелан був дитиною, ми часто відвідували Каер-Дарроу під час сімейних поїздок. Під час останнього візиту художник на ім’я Ренфрей намалював наш портрет, коли ми стояли на березі моря. Це моє найдорожче спогад про Телана та Карандру. Адже саме в той момент, тримаючи дружину та сина в обіймах, я відчув ту любов та сімейну єдність, яких більше ніколи не знатиму.$B$BЯкщо ця картина ще існує, ти мусиш її знайти.$B$BПодорожуй до занепалого острова Каер-Дарроу й перевір, чи залишилися там картина або художник.",
    O = "Відправляйтеся на острів Каер-Дарроу, що розташований у південно-центральній частині Заражених земель, і пошукайте будь-які підказки щодо місця перебування картини.",
    P = "",
    C = "Як я міг забути? Багато духів на цьому острові приречені знову і знову переживати своє останнє щасливе спогад перед тим, як їх спіткала трагічна доля.$B$BЯ теж проклятий, але не так, як вони — я один із небагатьох, хто пам’ятає все...$B$BМожливо, саме те, про що ти мене запитуєш, і є причиною, чому я блукаю цими руїнами. Можливо, те, що я тобі розповім, звільнить мене.",
},

[5848] = {
    en = "Of Love and Family",
    T = "Про кохання та сім’ю",
    D = "Ця картина... Вона роками висіла на стіні моєї майстерні — у казармах Ордену.$B$BПісля завершення суду над Тіріоном я зрозумів, що більше не можу залишати цю картину на видному місці. Я сховав її в місці, де ніхто б ніколи не подумав шукати.$B$BВідправляйся до Стратхолма й проникни вглиб того, що зараз називається «Скарлет-Бастіон», і знайди там картину з зображенням наших близнюкових місяців. Зчищайте фарбу, доки не відкриєте мій шедевр «Про кохання та родину».$B$BНехай Світло направляє ваші дії.",
    O = "Відправляйтеся до Стратхолма, що у північній частині Землі Чуми. Саме в Скарлатному Бастіоні ви знайдете картину «Про кохання та родину», заховану за іншою картиною, на якій зображені подвійні місяці нашого світу.$B$BПоверніть картину Тіріону Фордрінгу.",
    P = "Картина, $N. У вас є ця картина?",
    C = "<Тіріон ледь не зомлів, побачивши картину.>$B$B<Він почав ридати майже несамовито.>",
},

[5861] = {
    en = "Find Myranda",
    T = "Знайти Міранду",
    D = "$N, ти виконав усе, про що я просив до цього моменту. У твоєму шляху до спокути залишився лише один крок.$B$BТи повинен передати зібрані предмети Таелану. На жаль, Таелан і його «Скарлатні хрестоносці» нападуть на тебе, щойно побачать.$B$BЄ лише один спосіб передати моє послання — це обман.$B$BНа півдні ти знайдеш гробницю Утера. Там зараз мешкає моя давня й надійна довірена особа, Міранда — знайдіть її. Покажіть їй предмети, і вона допоможе вам.",
    O = "Відправляйтеся до Гробниці Утера, що розташована на півдні Заражених земель. Покажіть відьмі Міранді «Дар Тіріона».",
    P = "Я знав, що цей день настане.",
    C = "Я був найдовіренішим радником Тіріона, коли той обіймав посаду лорда Марденхолда. Я відкрито висловив незгоду з вироком, винесеним Орденом Срібної Руки, і був вигнаний за свою зухвалість.$B$BУ своєму житті він пережив чимало душевних страждань і розчарувань, $R. Чи готові ви виправити кривди, завдані роду Фордрінгів?",
},

[5862] = {
    en = "Scarlet Subterfuge",
    T = "«Скарлетна хитрість»",
    D = "Я — те, що ви б назвали ілюзіоністом. Хоча я й можу створити ілюзію, яка дозволить вам потрапити до Гертглена, майте на увазі: мої сили мають свої обмеження.$B$BЯкщо ви віддалитися занадто далеко від цих земель, дія ілюзії припиниться. Саме заклинання вимагає від мене величезної концентрації та сили, тому я можу підтримувати його дію лише протягом короткого часу.$B$BЗверніться до мене знову, коли будете готові.",
    O = "Поговоріть з Мірандою, щоб отримати «Багряну ілюзію». Подорожуйте до Хартглена, перебуваючи під дією «Багряної ілюзії», і передайте «Дар Тіріона» верховному лорду Таелану Фордрінгу.$B$BХартглен розташований на півночі, а Таелан має перебувати всередині фортеці Марденхолд.",
    P = "Ви — підкріплення з «Руки Тира»?",
    C = "Що це таке, солдате?$B$B<Таелан відкриває скриньку й починає оглядати її вміст.>$B$BЦе... це не може бути правдою. Але все, що ти мені показав...$B$B<Телан опускається на одне коліно, його серце б’ється швидше. На це місто ось-ось обрушиться гнів століть.>",
},

[5863] = {
    en = "The Dunemaul Compound",
    T = "Комплекс «Дунемаул»",
    D = "Зовсім недавно до Танарісу прибула велика група кочових огрів. На південь від цього місця вони захопили велику територію пустелі та облаштували там табір. Кілька менших загонів наразі блукають пустелею, а деякі з них вторглися до старих руїн тролів.$B$BТабір Дунемаул необхідно знищити! Ми не можемо дозволити цим ограм зібрати військо.$B$BВатажком цієї групи є Гор'марок Руйнівник; я вважаю, що покінчити з його владою стане початком кінця для огрів.",
    O = "Енді Лінн у Гаджетзані просить вас знищити базу «Дунемаул», вбивши 10 брутів «Дунемаул», 10 виконавців «Дунемаул» та Гор'марока Руйнівника.",
    P = "Я так хвилююся! Будь ласка, будь обережним!",
    C = "Я так рада, що ти зміг це для мене зробити, $N! Дякую за допомогу!",
},

[5881] = {
    en = "Calling in the Reserves",
    T = "Мобілізація резервістів",
    D = "Орда чудово дбає про те, щоб наші війська залишалися боєздатними… З часів Великої війни ми процвітаємо тут, у Калімдорі.$B$BМені потрібна твоя допомога: у мене є хлопець на ім’я Гріш Лонграннер, який охороняє Великий Ліфт у південних Пустошах. Передайте йому цей лист; з нього він дізнається, що я відправляю запасного воїна, який замінить його на службі, щоб він міг відвідати свою родину. Він просив про це ще деякий час тому і буде радий почути цю новину.",
    O = "Маггран просить вас передати листа Грішу Лонграннеру біля Великого ліфта в Пустках.",
    P = "У вас є новини від Магграна Землеплететеля?",
    C = "Це чудова новина; я вже занадто довго сидів тут, охороняючи цей шматок дерева. Тепер я зможу провести трохи часу з родиною... Ура!",
},

[5882] = {
    en = "Salve via Hunting",
    T = "Salve через Hunting",
    D = "",
    O = "",
    P = "Наявність маяка Сенаріону дозволяє бачити осколки спотворених душ на тих заражених звірах, яких знищують заради загального блага. Я перемелюю осколки на придатний для використання реагент, який використовується для виготовлення мазі з рослин Сенаріону. Ми будемо використовувати цю мазь, щоб знову перетворити зіпсовані рослини на здорові.$B$BВ обмін на ці осколки я дам вам трохи мазі з рослин Сенаріону, яку я вже підготував.",
    C = "Гаразд, ось ваші рослинні мазі Сенаріону. Прочешіть Фелвуд у пошуках спотворених рослин, $N! Де б вони не були, використовуйте мазь, яку я вам дав, щоб їх очистити.",
},

[5883] = {
    en = "Salve via Mining",
    T = "Salve через майнінг",
    D = "",
    O = "",
    P = "Якщо під час видобутку корисних копалин у Фелвуді у вас буде маяк Сенаріону, ви зможете побачити заражений вітріол, який псує жилу сировини. Я знаю, як очистити цей вітріол і перетворити його на реагент, необхідний для виготовлення мазі з рослин Сенаріону. Потім ви зможете використовувати цю мазь для рослин, які ви знайдете в дикій природі й які потребують порятунку.$B$BЯкщо ви зібрали забруднену сірку, я дам вам трохи мазі для рослин Сенаріону, яку я вже приготував.",
    C = "Гаразд, ось тобі мазь із рослин Сенаріону. Якщо під час видобутку в Фелвуді знайдеш ще вітріолу, не забудь залишити її для мене! Чим більше її знайдеш, тим більше мазі я зможу приготувати.",
},

[5884] = {
    en = "Salve via Gathering",
    T = "Salve через Gathering",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволяє досвідченому травнику виявляти підступну фельську поросль — злоякісний породження зіпсованості Фелвуда. Моя робота тут навчила мене, як очищати фельську поросль і перетворювати її на очищувальний реагент… який використовується у тому, що ми зараз називаємо «маззю з рослин Сенаріону».$B$BЗбираючи трави у Фелвуді, ви натрапите на фель-порость, якщо матимете при собі маяк. В обмін на те, що ви принесете мені, я дам вам готову мазь з рослин Сенаріону.",
    C = "Чудова робота, $n — кожна частинка цього, після очищення, допоможе нам повернути Фелвуд. Ось, візьми кілька доз мазі з рослин Сенаріону й вирушай у ліс. Відновлення земель, уражених спотворенням, не чекає ні на кого, $r!",
},

[5885] = {
    en = "Salve via Skinning",
    T = "Salve через Skinning",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволить досвідченому шкірянику виявляти шматки зараженої шкіри серед трофеїв, зібраних у Фелвуді. Я перетворюю ці, на перший погляд, марні шматки на густу пасту, яка слугує прискорювачем дії рослинної мазі Сенаріону. Коли ви зніматимете шкури з вбитих тут, у Фелвуді, обов’язково майте при собі маяк!$B$BЗібравши заражені ділянки шкіри, принесіть їх мені, і я дам вам трохи рослинної мазі Сенаріону, яку я вже приготував.",
    C = "Це саме те, що мені потрібно. Ось — візьми ці рослинні мазі й використай їх, щоб звільнити Фелвуд від спотворення. Ми мусимо не здаватися, $n!",
},

[5886] = {
    en = "Salve via Disenchanting",
    T = "«Salve» через «Disenchanting»",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета відчувається завдяки есенції, яку він створює. Я придумав спосіб перетворити сиру есенцію, яку використовують чарівники, на відповідний реагент для створення ценаріонської рослинної мазі. Для цього не потрібен маяк Сенаріону; підійде будь-який відповідний розчарований предмет, який дає меншу есенцію Нетера.$B$BМені потрібна лише одна менша есенція Нетера; натомість я дам вам мазі з рослин Сенаріону. Ця есенція надзвичайно потужна — навіть невеликої кількості вистачить надовго!",
    C = "Ось кілька мазей із рослин Сенаріону — для цього мені знадобиться лише одна менша есенція Нетера, $n. Есенція — це, безперечно, найдієвіший засіб, який я можу використати, щоб, так би мовити, перетворити мечі на плуги. Якщо тобі знадобиться ще мазі, то шукай мене тут!",
},

[5887] = {
    en = "Salve via Hunting",
    T = "Salve через Hunting",
    D = "",
    O = "",
    P = "Маючи Маяк Сенаріону, можна побачити осколок спотвореної душі на тих заражених звірах, яких знищують заради загального блага. Я перетираю осколки на придатний для використання реагент, який використовується для виготовлення мазі з рослин Сенаріону. Ми будемо використовувати цю мазь, щоб знову перетворити спотворені рослини на здорові.$B$BВ обмін на ці осколки я дам вам трохи мазі з рослин Сенаріону, яку я вже підготував.",
    C = "Гаразд, ось ваші мазі з рослин Сенаріону. Прочешіть Фелвуд у пошуках спотворених рослин, $n! Де б вони не були, використовуйте мазь, яку я вам дав, щоб їх очистити.",
},

[5888] = {
    en = "Salve via Mining",
    T = "Salve через майнінг",
    D = "",
    O = "",
    P = "Якщо під час видобутку корисних копалин у Фелвуді у вас буде маяк Сенаріону, ви зможете побачити заражений вітріол, який псує жилу сировини. Я знаю, як очистити цей вітріол і перетворити його на реагент, необхідний для виготовлення мазі з рослин Сенаріону. Потім ви зможете використовувати цю мазь на рослинах, які знайдете в дикій природі й які потребують порятунку.$B$BЯкщо ви зібрали трохи зараженої сірчаної кислоти, я дам вам трохи мазі для рослин Сенаріону, яку я вже приготував.",
    C = "Гаразд, ось тобі мазь із рослин Сенаріону. Якщо під час видобутку в Фелвуді знайдеш ще вітріолу, не забудь залишити її для мене! Чим більше її знайдеш, тим більше мазі я зможу приготувати.",
},

[5889] = {
    en = "Salve via Gathering",
    T = "Salve через Gathering",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволяє досвідченому травнику виявляти підступний фел-порост — злоякісний продукт зіпсуття Фелвуда. Моя робота тут навчила мене, як очищати фел-порост і перетворювати його на очищувальний реагент… який використовується у тому, що ми зараз називаємо «маззю з рослин Сенаріону».$B$BЗбираючи трави у Фелвуді, ви натрапите на фель-порость, якщо матимете при собі маяк. В обмін на те, що ви принесете мені, я дам вам готову «Трав’яну мазь Сенаріону».",
    C = "Чудова робота, $n — кожна частинка цього, щойно ми її очистимо, допоможе нам повернути Фелвуд. Ось, візьми кілька доз мазі з рослин Сенаріону й вирушай у ліс. Відновлення земель, уражених спотворенням, не терпить зволікань, $r!",
},

[5890] = {
    en = "Salve via Skinning",
    T = "Salve через Skinning",
    D = "",
    O = "",
    P = "Маяк Сенаріону дозволить досвідченому шкуроделу виявляти шматки зараженої шкіри серед здобичі, зібраної у Фелвуді. Я перетворюю ці, на перший погляд, непотрібні шматки на густу пасту, яка слугує прискорювачем дії рослинної мазі Сенаріону. Коли ви знімаєте шкури з вбитих тут, у Фелвуді, обов’язково майте при собі маяк!$B$BЗібравши заражені ділянки шкіри, принесіть їх мені, і я дам вам трохи рослинних мазей «Сенаріон», які я вже приготував.",
    C = "Це саме те, що мені потрібно. Ось — візьми ці рослинні мазі й використай їх, щоб звільнити Фелвуд від спотворення. Ми мусимо не здаватися, $n!",
},

[5891] = {
    en = "Salve via Disenchanting",
    T = "«Salve» через «Disenchanting»",
    D = "",
    O = "",
    P = "Сила розчарованого магічного предмета проявляється у сутності, яку він створює. Я придумав спосіб перетворити необроблену сутність, яку використовують чарівники, на реагент, придатний для створення ценаріонської рослинної мазі. Для цього не потрібен маяк Сенаріону; підійде будь-який відповідний розчарований предмет, з якого можна отримати меншу есенцію Нетера.$B$BМені потрібна лише одна менша есенція Нетера; натомість я дам вам мазі з рослин Сенаріону. Ця есенція надзвичайно потужна — навіть невеликої кількості вистачить надовго!",
    C = "Ось кілька мазей з рослин Сенаріону — для цього мені знадобиться лише одна менша есенція Нетера, $n. Есенція — це, безперечно, найдієвіший засіб, який я можу використати, щоб, так би мовити, перетворити мечі на плуги. Якщо тобі знадобиться ще мазі, то знайди мене тут!",
},

[5892] = {
    en = "Irondeep Supplies",
    T = "«Irondeep Supplies»",
    D = "До початку бойових дій ми зберігали припаси для Дун-Балдара в шахті «Залізний глибокий». Троги, які з’являлися там на поверхні, не становили великої проблеми, коли у нас були вільні війська для охорони шахти, але тепер, коли ми воюємо з Ордою, ми не можемо утримувати контроль над «Залізним глибоким».$B$BНам потрібні запаси з «Залізної глибини», $N. Зайдіть у шахту й принесіть мені частину цих запасів.",
    O = "Принесіть 10 одиниць припасів «Айрондіп» інтенданту Альянсу в Дун-Балдарі.",
    P = "У тебе є запаси, $N? Їх ніколи не буває забагато!",
    C = "Молодець! Я обов’язково знаходжу цим речам корисне застосування! Дякую, $N!",
},

[5893] = {
    en = "Coldtooth Supplies",
    T = "«Coldtooth Supplies»",
    D = "Шахта «Холодний Зуб» на півночі колись була ідеальним місцем для зберігання запасів, але тепер, коли бої зі «Штормпіками» стають дедалі запеклішими, у нас не завжди є вільні воїни, щоб розмістити їх у шахті та захищати її. Тому контроль над шахтою часто переходить до Альянсу або до підземних мешканців...$B$BАле нам все одно потрібні наші запаси, $N! Відправляйся до шахти «Холодний Зуб» і принеси мені їх. І будь обережним з ворогами по дорозі; хід бою в тому місці швидко змінюється...",
    O = "Принесіть 10 предметів спорядження «Холодний зуб» інтенданту Орди у фортеці «Морозний вовк».",
    P = "Ти бував у шахті «Холодний Зуб», $N? У тебе є ті припаси, про які я просив?",
    C = "А, ти їх дістав. Молодець, $N! Ці припаси трохи запліснявіли від того, що так довго пролежали в тій темній шахті, але ми все одно їх використаємо.$B$BДякую, $N. Твої вчинки мають вирішальне значення для підтримання боєздатності наших військ.",
},

[5901] = {
    en = "A Plague Upon Thee",
    T = "Хай на тебе впаде чума!",
    D = "Отже, щоб завдати «Скарлет-хрестовому походу» болю та страждань, я хочу відібрати у них їхню дорогоцінну лісопильню. Я впевнений, що втрата такого ресурсу завдасть їм значної шкоди у захисті та відбудові міста з їхніх власних міркувань. Чи допоможеш ти мені, $N?$B$BДля початку віднеси цю банку до Плейгвуда у Східних Землях Чуми. Наповни її термітами, яких знайдеш у їхніх купах по всьому лісі. Повертайся, коли набереш достатньо.",
    O = "Використайте порожню банку для термітів на термітниках у Східних Землях Чуми. Зібравши 100 термітів із Земль Чуми, поверніться до Міккі Левіна в «Булварку» на Полях Тірісфала.",
    P = "У тебе вже з'явилися терміти, $N? Я впевнений, що для такого розумного $C, як ти, це очевидно.$B$BЯк тільки їх стане достатньо, ми подбаємо про те, щоб ніхто більше ніколи не зміг скористатися лісопилкою!",
    C = "Ці підійдуть чудово, $N. Дякую.$B$BЯкщо ви готові, можемо переходити до наступного кроку.",
},

[5902] = {
    en = "A Plague Upon Thee",
    T = "Хай на тебе прокляття",
    D = "Тепер, коли у нас є чимало термітів, віднесіть цю сталеву бочку на лісопильню «Нортрідж», що на південь від Хартглена — ви знайдете її на захід від дороги, яка веде до міста.$B$BПрибувши туди, поставте бочку в центрі лісопильні; десь високо, наприклад, на ящику чи чомусь подібному.$B$BПісля того, як ви її відкриєте, решта відбудеться сама собою. Просто поверніться сюди, і я винагороджу вас за допомогу.",
    O = "Знайдіть у центрі лісопильні Нортрідж у Західних Землях Чуми підходяще місце, щоб розмістити бочку з термітами Землі Чуми.",
    P = "",
    C = "Очевидно, терміти починають нервувати, коли ви ставите бочку зверху на ящик.",
},

[5903] = {
    en = "A Plague Upon Thee",
    T = "Хай на тебе впаде чума!",
    D = "Я вже багато разів намагався вигнати «Скарлетний хрестовий похід» суто силою, але марно. Тож, як альтернативу, я вирішив ускладнити їм життя.$B$BЯкщо ти готовий допомогти, я хочу заразити той лісопильний завод найжахливішим видом термітів, який коли-небудь зустрічався.$B$BУ Плейгвуді, неподалік від колись величного Стратхолма, мешкає вид, який вижив і після чуми, і після навали Плеті. Знайдіть їхні мурашині купки та наповніть ними цю банку, щоб ми могли підготувати їх до випуску проти «Скарлетного хрестового походу».",
    O = "Використайте порожню банку для термітів на термітниках у Східних Землях Чуми. Зібравши 100 термітів із Земль Чуми, поверніться до Натаніеля Дума в таборі «Холодний Вітер» у Західних Землях Чуми.",
    P = "Ти знайшов термітники, $N? Я чув, що вони розкидані по всьому Плейгвуду.",
    C = "Ці підійдуть чудово, $N. Дякую. Тільки погляньте на них... стільки їх, всі так тісно стиснулися. Мені майже шкода «Хрестовий похід», але з іншого боку, це ж ніколи не була їхня млин, чи не так?",
},

[5904] = {
    en = "A Plague Upon Thee",
    T = "Хай на тебе спаде чума!",
    D = "Тепер, коли у нас є терміти, віднесіть цю сталеву бочку на лісопильню «Нортрідж», що на південь від Хартглена — ви знайдете її на захід від дороги, яка веде до міста.$B$BДобравшись туди, поставте бочку в центрі лісопильні; знайдіть підходяще місце, наприклад, на ящику, а потім відкрийте її. Терміти повинні зробити свою справу звідти і зробити лісопильню непридатною для Хрестового походу.",
    O = "Знайдіть у центрі лісопильні «Нортрідж» у Західних Землях Чуми підходяще місце для розміщення «Бочки з термітами Землі Чуми».",
    P = "",
    C = "Очевидно, терміти починають нервувати, коли ви ставите бочку на ящик.",
},

[5921] = {
    en = "Moonglade",
    T = "Місячна галявина",
    D = "Усі друїди ласкаво запрошуються на священні землі Місячної галявини, незважаючи на нинішні напружені стосунки в Колові Сенаріона між архідруїдом Стагхельмом та Хранителем Ремулосом — охоронцем Місячної галявини. Тепер, коли ти вивчаєш шляхи «Кігтя», я навчу тебе заклинанню, яке дозволить тобі перенестися туди. Використовуй його, коли тобі знадобляться знання чи розрада Місячної галявини.$B$BЩодо твого першого уроку: вирушай до Місячної галявини й поговори з Дендрітом Старблейзом у Нічному притулку про шлях, яким ти зараз йдеш. Удачі тобі, юний друїде.",
    O = "Використайте заклинання «Телепортація: Місячна галявина», щоб перенестися до Місячної галявини. Прибувши туди, поговоріть із Дендрітом Старблейзом у селі Найтхевен.",
    P = "",
    C = "«Ось і почалося. Отче Сенаріус. Ось і почалося».$B$BДендрит робить швидкий, невидимий жест у повітрі над собою. На нього опускається легка аура сили.$B$B«Перша перспектива природи, до якої ти повинен пристосуватися, — це перспектива ведмедя. Я наставлю тебе на шлях до розуміння цього аспекту життя друїда, але саме ти повинен прийняти його й поширювати — тепер і назавжди!»",
},

[5922] = {
    en = "Moonglade",
    T = "Місячна галявина",
    D = "Усі друїди — як таурени, так і нічні ельфи — ласкаво запрошуються до священних земель Місячної галявини. Хранитель Ремулос — охоронець Місячної галявини — пильнує за всіма друїдами, які впадають там у зимову сплячку. Тепер, коли ти вивчаєш шляхи Кігтя, я навчу тебе заклинанню, яке дозволить тобі переміститися туди. Застосовуйте його, коли вам знадобляться знання чи розрада Місячної галявини.$B$BА для першого уроку вирушайте до Місячної галявини й поговоріть із Дендритом Зоряним Полум’ям у Нічному притулку про шлях, яким ви зараз йдете. Удачі, юний друїде.",
    O = "Використайте заклинання «Телепортація: Місячна галявина», щоб дістатися до Місячної галявини. Прибувши туди, поговоріть із Дендрітом Старблейзом у селі Найтхевен.",
    P = "",
    C = "«Отже, все починається. Отче Сенаріусе. Отже, все починається.»$B$BДендрит робить швидкий, невидимий жест у повітрі над собою. На нього опускається легка аура сили.$B$B«Перша перспектива природи, до якої ти повинен пристосуватися, — це перспектива ведмедя. Я наставлю тебе на шлях до розуміння цього аспекту життя друїда, але саме ти повинен прийняти його та поширювати — зараз і назавжди!»",
},

[5923] = {
    en = "Heeding the Call",
    T = "Відгукнувшись на заклик",
    D = "Вибачте, друже...$B$BДо мого відома дійшла інформація, що Матренгіл Беарвокер повідомив, що бажає поговорити з вами. Схоже, ваше навчання на друїда незабаром набуде нового змісту, і він буде навчати вас особисто. Матренгіл є безпосереднім помічником самого Верховного друїда і одним із наймудріших та найповажніших друїдів у Телдрасілі.$B$BЙого можна знайти в Енклаві Сенаріону в Дарнасусі, на другому поверсі дерева Фандрала Стагхелма.",
    O = "Поговоріть з Матренгілом Беарвокером в «Енклаві Сенаріону» у Дарнассусі.",
    P = "",
    C = "Я радий, що ти сьогодні знайшов дорогу сюди, юний $C. Настав час тобі зробити великий крок у набагато ширший світ.$B$BУ кожному з дітей Сенаріуса живе покликання служити природі. Тварини й рослини — наші друзі, а також ті, за кого ми відповідаємо. Ми вирішили присвятити своє життя збереженню рівноваги як заради них, так і заради нас самих. Твоїм першим кроком у цьому світі стане пізнання звичаїв ведмедя та набуття сили тіла й духу.$B$BГотуйся!",
},

[5924] = {
    en = "Heeding the Call",
    T = "Відгукнувшись на заклик",
    D = "Вибачте, друже...$B$BМені стало відомо, що Матренгіл Беарвокер повідомив, що бажає поговорити з вами. Схоже, ваше навчання на друїда незабаром набуде нового змісту, і він буде навчати вас особисто. Матренгіл є безпосереднім помічником самого Верховного друїда і одним із наймудріших та найповажніших друїдів у Телдрасілі.$B$BЙого можна знайти в анклаві Сенаріону в Дарнассусі, на другому поверсі дерева Фандрала Стагхелма.",
    O = "Поговоріть із Матренгілом Беарвокером в Енклаві Сенаріону, у Дарнассусі.",
    P = "",
    C = "Я радий, що ти сьогодні знайшов дорогу сюди, юний $C. Настав час тобі зробити великий крок у набагато ширший світ.$B$BУ серці кожного з дітей Сенаріуса живе покликання служити природі. Тварини й рослини — наші друзі, а також ті, за кого ми відповідаємо. Ми вирішили присвятити своє життя збереженню рівноваги заради них, а також заради нас самих. Твоє перше завдання у цьому світі — пізнати звичаї ведмедя та набути сили тіла й духу.$B$BГотуйся!",
},

