[6761] = {
    en = "The New Frontier",
    T = "Нова межа",
    D = "Я відрядив свого заступника, Матренгіла Беарвокера, щоб він розібрався з проханням про допомогу з Місячної галявини. Поговоріть з ним з цього приводу — НЕ зі мною.$B$BДозвольте дати вам кілька… дружніх… порад. Саме я вивів нас із темряви — НЕ «Коло Сенаріона» у Місячному гаї — коли для нашої раси все було втрачено. Телдрасіл дарує нам усім нове життя! Вони хочуть, щоб ти вірив у протилежне, але вірити їхній пропаганді — справа дурня.$B$BЯ залишу за тобою право вирішити, дурень ти чи ні.",
    O = "Поговоріть з Матренгілом Беарвокером у «Енклаві Сенаріону» в Дарнассі.",
    P = "",
    C = "Так, $c, дякую, що завітав. Прошу вибачення за непорозуміння... У повітрі витає атмосфера недовіри між місцевим Архідруїдом та Хранителем Ремулосом у Місячному гаї. Кожен підозрює іншого у махінаціях, а той факт, що дивні спотворення Телдрасілу тривають безперервно, досі залишається проблемою тут. Це аж ніяк не сприяє подоланню недовіри.$B$BПроте наш обов’язок перед Колом Сенаріона залишається незмінним... навіть якщо ті, хто ним керує, можуть не погоджуватися один з одним.",
},

[6762] = {
    en = "Rabine Saturna",
    T = "Рабіне Сатурна",
    D = "Для виконання цього завдання майордом Хранителя Ремулоса в Місячній галявині — Рабін Сатурна — просить допомоги у дослідженні безкрайніх пусток, що лежать далеко на захід від Танарісу… і ще далі на захід від Ун’Горо. Ви знайдете його в Нічному притулку — головному селі Місячної галявини.$B$BХоча ваша робота, без сумніву, принесе величезну користь нам усім, раджу вам діяти обережно. Між Дарнасусом і Місячною галявиною існують напружені стосунки... які з часом можуть посилитися.",
    O = "Поговоріть із Рабіном Сатурною в селі Найтхевен, що в Місячній гаї. Місячна гай розташована між Фелвудом і Вінтерспрингом; дістатися туди можна стежкою, що веде від фортеці Тімбермоу.",
    P = "",
    C = "Я — Рабін Сатурна, і від імені Хранителя Ремулоса та всіх мешканців цієї священної галявини вітаю вас.$B$BЯ ціную ваш інтерес та бажання допомогти Колу Сенаріону. Я також знаю, що Верховний друїд Дарнассуса висловив вам своє невдоволення тим, що ви надаєте нам допомогу. Будьте впевнені: це робиться заради загального блага, і ви будете в безпеці від будь-яких необґрунтованих наслідків, на які ви можете наразитися.$B$BТут ви серед друзів, $N.",
},

[6781] = {
    en = "More Armor Scraps",
    T = "Більше уламків броні",
    D = "",
    O = "",
    P = "$N, нам потрібно більше уламків броні для забезпечення наших військ!",
    C = "Це чудові предмети, $N. Я можу використати їх для виготовлення нового спорядження для наших військ.$B$BЯкщо рівень моїх запасів стане достатньо високим, то, можливо, наші досвідчені бойові підрозділи вийдуть на поле бою!",
},

[6801] = {
    en = "Lokholar the Ice Lord",
    T = "Лоххолар, Володар льоду",
    D = "",
    O = "",
    P = "Я родом із Громового Утвіру, $r. Сам Кейрн домігся, щоб я допомагав клану Морозних Вовків у ці тяжкі часи.$B$BАле не будемо більше марнувати час. Ти повинен знищити наших ворогів і принести мені їхню кров. Коли буде зібрано достатньо крові, можна буде розпочати ритуал виклику.$B$BПеремога буде гарантована, коли володар стихій буде насланий на армію Штормпайка.",
    C = "Кров наших ворогів пролита. Я змішаю цю кров із рештою зібраної крові. Як тільки жертвопринесення завершиться, Лорд Льоду покаже цим псам із «Штормпайка» весь гнів клану «Морозних Вовків»!",
},

[6804] = {
    en = "Poisoned Water",
    T = "Отруєна вода",
    D = "До східних заражених земель Лордаерона було відправлено загін розвідників-елементалів, і хвороба того краю спотворила та заразила їх. Водяні володарі не можуть допустити такого образи нашої чистоти!$B$BВізьміть цю ампулу. У ній міститься певна кількість одного з аспектів Нептулона. Якщо застосувати її до уражених чумою елементалів, вона поборе отруту в їхніх тілах і вилікує їх! Але їхній внутрішній конфлікт штовхне їх у вируючий божевілля.$B$BПереможіть ці суперечливі хвилі та принесіть мені їхні браслети, що зв’язують.",
    O = "Використовуйте «Аспект Нептулона» на отруєних елементалях Східних Земель Чуми. Принесіть 12 «Браслетів розбрату» та «Аспект Нептулона» герцогу Гідраксісу в Азшарі.",
    P = "У тебе є нарукавники?",
    C = "Ти добре впорався, $C. Зіпсовані елементалі, яких ти вилікував, були образою для всіх водойм. Наша сила — у нашій чистоті, і якщо ми хочемо перемогти в війні з іншими, ми мусимо залишатися сильними.",
},

[6805] = {
    en = "Stormers and Rumblers",
    T = "«Стормерс» і «Рамблерс»",
    D = "Ми, елементалі води, ведемо війну з істотами нижчих стихій. Якщо ти справді наш союзник у цьому конфлікті, то доведи мені свою відданість!$B$BДалеко на півдні, у пустельній землі Сілітус, слуги повітря та землі метушаться у скелястому куточку під назвою Кришталева Долина. Вони захищають магічні артефакти від дрібніших істот — смертних, і хоча я не знаю, чому вони це роблять, я хочу зірвати їхні плани.$B$BВідправляйся до Кришталевої долини в Сілітусі, переможи наших ворогів, а потім повернися до мене.",
    O = "Знищте 15 «Пилових штормістів» і 15 «Пустельних гуркотів», а потім поверніться до герцога Гідраксіса в Азшарі.",
    P = "Ми не поважаємо боягузтво, $c. Відправляйся до Сілітуса й доведи свою хоробрість.",
    C = "Твоя хоробрість вже доведена, як і твоя цінність для нас. Можливо, у майбутньому я матиму для тебе завдання, які більше відповідають статусу цінного союзника Володарів Води.",
},

[6821] = {
    en = "Eye of the Emberseer",
    T = "Око Вогняного Провидця",
    D = "Ти довів мені, що здатний перемогти наших ворогів і виконувати завдання на благо справи Володарів Води. Але досі ти стикався лише з другорядними супротивниками… Чи зможеш ти перемогти, якщо зіткнешся з могутнім ворогом?$B$BОсь твоє нове завдання.$B$BВисоко в Шпилі Чорної Скелі орки полонили слугу вогню — пірогвардійця Емберсіра. Знайди місце його ув’язнення, знищ його викрадачів, а потім убий самого Емберсіра. Принеси мені його око — це доведе мені твою цінність.",
    O = "Принесіть «Око Емберсіра» герцогу Гідраксісу в Азшарі.",
    P = "Чи є у тебе «Око», $C? Чи вистачить тобі сил увійти до Шпиля Чорної Скелі?",
    C = "Ага, виходить, у вас все-таки є сила. І хитрість теж, адже «Шпиль Чорної Скелі» — це не те, з чим можна впоратися лише за допомогою грубої сили.$B$BДійсно $N, можливо, ви ще станете для нас цінним союзником...",
},

[6822] = {
    en = "The Molten Core",
    T = "Розплавлене ядро",
    D = "$n, мабуть, настав час піддати тебе справжньому випробуванню. Ти готовий?$B$BНа дні Глибин Чорної Скелі знаходиться прохід до Розплавленого Ядра. Це цитадель нашого ворога, яку охороняють наймогутніші слуги вогню у цьому світі.$B$BВідправляйся до Розплавленого Ядра, $N. Доведи мені, що ти маєш силу й волю, щоб перемогти те, що там знайдеш.$B$BА якщо серед твого народу є союзники, то збери їх. Лише ціла армія може сподіватися увійти до Розплавленого Ядра й вижити.",
    O = "Вбийте 1 Володаря Вогню, 1 Розплавленого велетня, 1 Стародавнього ядерного пса та 1 Лавового буревія, а потім поверніться до герцога Гідраксіса в Азшарі.",
    P = "На тебе чекає успіх у «Розплавленому ядрі», $N.",
    C = "Ти зробив те, що більшість представників твого виду вважали б неможливим. Ти зіткнувся з істотами Розплавленого Ядра і здобув перемогу!$B$BДля такої крихітної істоти ти проявив неабияку кмітливість.$B$BМожливо, одного дня нам вдасться укласти справжній союз між твоїм родом і Володарями Води.",
},

[6823] = {
    en = "Agent of Hydraxis",
    T = "Агент «Гідраксіс»",
    D = "Якщо ти справді бажаєш приєднатися до нас, то я запрошую тебе вести війну проти наших ворогів — слуг повітря, землі та вогню. Кожна поразка, яку ти завдаси їм, послабить їхні позиції тут і ще раз підтвердить твою відданість нашій справі.$B$BКампанія буде довгою, але якщо ви не здастеся, то ваша слава й честь будуть великими.",
    O = "Заробіть статус «Почесного члена фракції» у фракції «Гідраксійських Володарів Води», а потім поговоріть із герцогом Гідраксісом в Азшарі.",
    P = "Твоя кампанія ще не завершена, $n. Вирушай і переможи наших ворогів — слуг повітря, землі та вогню, — і, можливо, одного дня ти заслужиш місце в залі Володарів Води.",
    C = "Твої подвиги у боротьбі з нашими ворогами лунають у залах Володарів Води, $N. Дехто вважав, що ти занадто маленький і тендітний, щоб брати участь у нашій війні, але ти досягнув значних успіхів. Ти заслужив повагу серед нас — це неймовірне досягнення.",
},

[6824] = {
    en = "Hands of the Enemy",
    T = "Руки ворога",
    D = "$N, ваші послуги для нас надзвичайно цінні, тому ми не хочемо відправляти вас на цю останню місію, адже не бажаємо втратити такого корисного агента.$B$BОднак її успіх значно сприятиме нашим військовим зусиллям і... було вирішено, що варто ризикнути вами.$B$BМи хочемо знищити цих капітанів у Розплавленому ядрі: Люцифрона, Сульфурона, Геенну та Шаззра. Вбий їх і принеси мені їхні руки!$B$BЦе завдання забере всі ваші сили, $N, але якщо ви зможете це зробити, то Володарям Вогню буде завдано страшного удару.",
    O = "Принесіть руки Люцифрона, Сульфурона, Геенни та Шаззи до герцога Гідраксіса в Азшарі.",
    P = "Ти вже переміг Люцифрона та інших, $N? У тебе є руки ворога?",
    C = "У тебе є талант! Ти переміг капітанів вогню! Я б ніколи не повірив у це, якби не знав тебе і не знав, на що ти здатний.$B$B$N, твої подвиги незліченні, але звістка про цей останній подвиг викличе резонанс серед Володарів Води. Твоє ім’я, можливо, одного дня стане для нас легендою.$B$BПоговори зі мною ще раз, $N. Можливо, у мене є ще одне завдання...",
},

[6825] = {
    en = "Call of Air - Guse's Fleet",
    T = "«Поклик повітря» — Флот Гузе",
    D = "",
    O = "",
    P = "Ми мусимо підготувати новий загін «Воєнних вершників», $r! Мої вершники готуються до удару на центральному полі бою; але спершу я мушу розпалити їхній запал — підготувати їх до штурму.$B$BМені потрібно достатньо плоті солдатів «Штормпайк», щоб нагодувати флот! Сотні фунтів! Ти ж, безперечно, впораєшся з цим, так? Вперед!",
    C = "Флот живиться їхнім тілом. Він поглинає ворога.$B$BПоліт розпочнеться незабаром!",
},

[6826] = {
    en = "Call of Air - Jeztor's Fleet",
    T = "«Поклик повітря» — Флот Джезтора",
    D = "",
    O = "",
    P = "Ти добре попрацював, $n, але ми лише розпочали!$B$BМої «Військові вершники» повинні скуштувати плоть своїх цілей. Це забезпечить хірургічну точність удару по наших ворогах!$B$BМій флот — другий за потужністю в нашому повітряному командуванні. Отже, він завдаватиме ударів по найпотужніших із наших супротивників. Для цього їм потрібні тіла лейтенантів «Штормпайк».$B$BПоспішай, солдате!",
    C = "Ще! Ще! Принесіть ще, бо вони скоро будуть готові!",
},

[6827] = {
    en = "Call of Air - Mulverick's Fleet",
    T = "«Поклик повітря» — Флот Мулверіка",
    D = "",
    O = "",
    P = "Я кілька днів просидів у карликовій пекельній дірі. Повірте, я прагну помсти!$B$BМи мусимо ретельно все спланувати.$B$BПо-перше, моїм бойовим вершникам потрібні цілі, на які можна націлитися — цілі найвищого пріоритету. Мені доведеться нагодувати їх плоттю командирів «Штормпайк». На жаль, ці маленькі гади закріпилися глибоко за лінією фронту! У тебе, безперечно, буде чимало роботи.",
    C = "Мало! Я б очікував такого рівня роботи від новачка, але ти, $N? Давай, солдате! ШВИДШЕ! Потрібно більше плоті!",
},

[6844] = {
    en = "Umber, Archivist",
    T = "Умбер, архівіст",
    D = "Тут ще є чим зайнятися, але, на мою думку, головне — передати це до «Кола» для аналізу. Повір мені — робота нікуди не дінеться, коли все це закінчиться. Якщо всередині цього липкого хітину є щоденник, то «Коло» нарешті отримає вікно в минуле!$B$BВіднеси це до архівіста «Кола» в Найтхевені. Його звати Умбер, і він — геніальний. Звісно, трохи несповна розуму, але все одно геніальний! Умбер рятував фоліанти в набагато гіршому стані, ніж цей. Якщо його можна врятувати, він це зробить.",
    O = "Віднесіть об’єкт із силітидом, вкритий нальотом, до Умбера — архіваріуса Кола Сенаріону — у селищі Найтхевен, що в Місячній гаї.",
    P = "О, привіт! Хм...$B$BДозволь мені бути з тобою відвертим, друже... від тебе трохи неприємно пахне. Можна сказати, що ти трохи смердиш. Я, звичайно, не маю наміру ображати тебе особисто. Просто кажу... у майбутньому тобі, можливо, варто трохи освіжитися після повернення з поля. Це зробить перше враження трохи позитивнішим!$B$BУ будь-якому разі... чим можу тобі допомогти?",
    C = "Ну й диво, мавпячі жаби! Що це у тебе тут? Схоже на книжку, напевно... Спробую розбити цю оболонку.$B$BЛайо прислав тебе до мене з Сілітуса? Я чув лише дуже приглушені чутки — хоча, якщо подумати, вони, мабуть, не такі вже й приглушені — про жахи, що там кояться. Додай до цього мою нелюбов до всього, що схоже на комах, — і ось тобі рецепт того, чому мені краще залишитися тут, серед книг!",
},

[6845] = {
    en = "Uncovering Past Secrets",
    T = "Розкриття таємниць минулого",
    D = "У будь-якому разі, тобі варто зв’язатися зі мною незабаром… якщо, звичайно, ти хочеш дізнатися, що тут було. Як тільки я з’ясую, що це таке, і якщо це справді книга, я з радістю поділюся цією інформацією з тобою.$B$BА тим часом я б порадив тобі зазирнути до керівниці цього маленького ведмежого табору, Рабіни. Без сумніву, вона захоче дізнатися, які божевільні витівки ти витворяв. Ніколи не змушуйте керівницю табору чекати, $N... тобто, якщо тільки ви не хочете, щоб вас облили медом.$B$BТаке траплялося, повірте мені.",
    O = "Поговоріть із Рабіном Сатурною в селі Найтхевен, що в Місячній гаї.",
    P = "",
    C = "Ах, $N — я сподівався, що ти завітаєш. Радий бачити, що у тебе все гаразд.$B$BМені повідомили, що ти повернешся з польової місії, і я хотів особисто висловити вдячність Кола Сенаріона за допомогу, яку ти нам надав до цього часу. Без сумніву, у Сілітусі ще є таємниці, які варто розкрити; те, що ти доставив до Умбера, має виявитися надзвичайно цікавим, коли про нього стане відомо. Будь ласка, прийми це як знак нашої постійної вдячності за твою допомогу.$B$BДякую, щедрий $C.",
},

[6846] = {
    en = "Begin the Attack!",
    T = "Почніть атаку!",
    D = "",
    O = "",
    P = "Мої війська забезпечені провіантом і готові до штурму. Нам залишилося лише отримати наказ від Норега Стормпайка — і я відправлю їх у бій!",
    C = "Ах, ці накази! У них сказано, що я маю атакувати, коли забажаю, а моя воля каже… зараз!",
},

[6847] = {
    en = "Master Ryson's All Seeing Eye",
    T = "«Всевидне око» майстра Райсона",
    D = "Ваша війна в самому серці Альтерака нічого не означає для Синдикату, $c. Ми будемо діяти так, як завжди: чекатимемо, поки з попелу та уламків цього божевілля не з’явиться явний переможець, а потім завдамо удару.$B$BОднак це не та причина, через яку ми зараз тут. «Всебачаче Око» загубилося — його забрали тролі з племені Вінтеракс, що мешкають у цьому регіоні.$B$BЗнайдіть Око, і ми будемо до ваших послуг — доти, доки ваша сторона ще триматиметься.$B$BПоверніться до мене, щойно здобудете Око, щоб я міг вас оглянути.$B$B<Майстер Райсон посміхається.>",
    O = "Знайдіть «Всевидяче око» майстра Райсона в печерах Вінтеракс і поверніть його майстру Райсону.$B$BБудьте обережні: кажуть, що «Всевидяче око» майстра Райсона несе в собі страшне прокляття!",
    P = "«Око», дурню. У тебе є «Око»?",
    C = "<Майстер Райсон оглядає Око.>$B$BТепер ти станеш свідком грандіозної сили Всевидного Ока!",
},

[6848] = {
    en = "Master Ryson's All Seeing Eye",
    T = "«Всевидне око» майстра Райсона",
    D = "Ваша війна в самому серці Альтерака нічого не означає для Синдикату, $c. Ми будемо діяти так, як завжди: чекатимемо, поки з попелу та уламків цього божевілля не постане явний переможець, а потім завдамо удару.$B$BОднак це не та причина, через яку ми зараз тут. «Всевидне Око» зникло — його викрали тролі з племені Вінтеракс, що мешкають у цьому регіоні.$B$BЗнайдіть Око, і ми будемо до ваших послуг — доти, доки ваша сторона ще протримається.$B$BПоверніться до мене, щойно здобудете Око, щоб я міг вас перевірити.$B$B<Майстер Райсон посміхається.>",
    O = "Знайдіть «Всевидне око» майстра Райсона в печерах Вінтеракс і поверніть його майстру Райсону.$B$BАле будьте обережні: кажуть, що «Всевидне око» майстра Райсона несе в собі страшне прокляття!",
    P = "«Око», дурню. У тебе є «Око»?",
    C = "<Майстер Райсон оглядає Око.>$B$BТепер ти станеш свідком грандіозної сили Всебачачого Ока!",
},

[6861] = {
    en = "Zinfizzlex's Portable Shredder Unit",
    T = "Портативний подрібнювач від Zinfizzlex",
    D = "",
    O = "",
    P = "Я так само не можу дочекатися, як і ви, щоб випробувати свій портативний подрібнювач, $r, але перш ніж я зможу зібрати цей комплект, мені знадобляться матеріали — дуже багато матеріалів! $B$BЯкщо бути точним, мені знадобиться гора торію, мітрілу та заліза. Також знадобиться по одній паровій пилі на кожну одиницю. Їх вам доведеться дістати на лісопильні. $B$BКоли я тут роздивлявся (ще до того, як мене схопили), я помітив купу парових пилок у лісозаготівельному таборі «Штормпайк». $B$BМайстер-інженер Зінфіззлекс хоче, щоб ви принесли йому наступне:",
    C = "",
},

[6862] = {
    en = "Zinfizzlex's Portable Shredder Unit",
    T = "Портативний подрібнювач від Zinfizzlex",
    D = "",
    O = "",
    P = "Я так само не можу дочекатися, як і ви, щоб випробувати свій портативний подрібнювач $r, але перш ніж я зможу зібрати цей комплект, мені знадобляться матеріали — дуже багато матеріалів! $B$BЯкщо бути точним, мені знадобиться гора торію, мітрілу та заліза. Також знадобиться по одній паровій пилці на кожну одиницю. Їх вам доведеться дістати на лісопильні. $B$BКоли я тут роздивлявся (ще до того, як мене схопили), я помітив купу парових пилок у лісозаготівельному таборі «Штормпайк». $B$BМайстер-інженер Зінфіззлекс хоче, щоб ви принесли йому наступне:",
    C = "",
},

[6881] = {
    en = "Ivus the Forest Lord",
    T = "Івус, Володар Лісу",
    D = "",
    O = "",
    P = "Клан «Морозних Вовків» захищений прокляттям елементальної енергії. Їхні шамани маніпулюють силами, які, безсумнівно, знищать нас усіх, якщо їх не зупинити.$B$BЗбитки стали надто великими, щоб «Коло» могло їх контролювати! Треба покликати Івуса на допомогу.$B$BСолдати «Морозних вовків» носять з собою елементальні амулети, які називаються кристалами бурі. Ми можемо використати ці амулети, щоб викликати Івуса. Рушайте вперед і захопіть кристали, $n!",
    C = "Молодець, $N. Я використаю силу цього амулета, щоб підсилити магію, яка вже була зібрана. Коли буде накопичено достатньо сили, я зосереджу зібрані енергії та звернуся до Володаря Лісу з проханням підтримати нашу справу.",
},

[6901] = {
    en = "Launch the Attack!",
    T = "Почніть атаку!",
    D = "",
    O = "",
    P = "Мої війська забезпечені провіантом і готові до штурму. Нам залишилося лише отримати наказ від інтенданта «Фроствольф», і я відправлю їх у бій!",
    C = "Нарешті! Тепер ми зможемо показати Альянсу, якою дурістю було приїжджати до Долини Альтерак!",
},

[6921] = {
    en = "Amongst the Ruins",
    T = "Серед руїн",
    D = "«Молот Сутінків» проник до руїн Місячного святилища в Чорноглибинних безоднях. Їхня присутність може лише змусити стихії діяти проти нас. Якщо не вжити заходів, цей регіон назавжди перейде до них.$B$B$N, вирушайте до Чорноглибин і знайдіть камінь «фатом» у руїнах; він має бути десь неподалік у воді. У ньому знаходиться «ядро фатома» — пристрій, який, якщо його правильно розшифрувати, розповість історію всієї діяльності стихій. Якщо я його отримаю, ми з «Земним Кільцем» зможемо, можливо, щось зробити, щоб зупинити їх!",
    O = "Віднесіть «Ядро Фатхом» до Дже'неу Санкреа на аванпості Зорам'гар у Попелястій долині.",
    P = "Чи вдалося вам знайти ядро «Фатхом»? Без нього ми не матимемо уявлення, чим саме займається «Молот Сутінків» там, внизу.",
    C = "Це саме те, що мені потрібно! Ядро «Фатхом» — це неймовірне джерело інформації, з якого ми зможемо черпати чимало корисного. Що б там не замишляв «Молот Сутінків» — і повірте мені, це нічого доброго — ми з товаришами тепер це розкриємо.$B$BТи сьогодні добре попрацював; «Земне Кільце» з вдячністю ставиться до тебе за допомогу. Ти також допоміг Орді в цілому, і цим тобі слід пишатися.",
},

[6922] = {
    en = "Baron Aquanis",
    T = "Барон Акваніс",
    D = "Переможений водяний елементаль залишив після себе дивну водяну кулю. Ви припускаєте, що цей предмет якимось чином живив звіра енергією. Усередині кулі хлюпається вода, що має гнильний вигляд. Сама куля, здається, непідвладна жодній фізичній силі.$B$BЯкщо хтось і зможе розібратися в цьому предметі, то це, мабуть, Дже'неу Санкреа з «Земляного кільця». Його можна знайти на форпості Орди «Зорам'гар» у Попеліній долині.",
    O = "Принесіть «Дивний водяний глобус» до Дже’неу Санкреа в аванпості Зорам’гар, що в Попелястій долині.",
    P = "А, привіт знову, $N. Я просто спостерігав за морськими хвилями, як завжди. Що привело тебе до цього форпосту?",
    C = "Це... це справді чудова знахідка, $N.$B$BТи кажеш, що отримав це від барона Акваніса в Блекфатомі? Барона Акваніса вже давно вважають спотвореною елементальною силою; цей глобус доведе, що саме спотворило його. Хоча не буде дивно, якщо виявиться, що це справа рук «Молота Сутінків», наші дослідження також покажуть, як саме вони це зробили.$B$BТи добре вчинив, принісши це мені. Будь ласка, візьми це разом із найтеплішими вітаннями від «Земляного Кільця».",
},

[6941] = {
    en = "Call of Air - Vipore's Fleet",
    T = "«Поклик повітря» — флот Віпора",
    D = "",
    O = "",
    P = "З елітними підрозділами «Морозних вовків», які охороняють лінію фронту, треба розібратися, солдате! Я доручаю тобі прорідити це стадо дикунів. Повертайся до мене з медалями їхніх лейтенантів і легіонерів. Коли я вважатиму, що з цією наволоччю впоралися достатньо, я розпочну повітряний удар.",
    C = "Політ незабаром розпочнеться. Продовжуйте працювати!",
},

[6942] = {
    en = "Call of Air - Slidore's Fleet",
    T = "«Поклик повітря» — флот Слідора",
    D = "",
    O = "",
    P = "Мої грифони готові завдати удару на передовій, але не можуть розпочати атаку, доки ряди ворога не порідшають.$B$BВоїни «Морозних вовків», яким доручено утримувати передову, з гордістю носять на грудях медалі за заслуги. Зірвіть ці медалі з їхніх гнилих трупів і принесіть їх сюди.$B$BЯк тільки лінія фронту достатньо прорідшиться, я дам сигнал до повітряного удару! Смерть з небес!",
    C = "Продовжуй, солдате! Грифони з Аері будуть готові до атаки в одну мить!",
},

[6943] = {
    en = "Call of Air - Ichman's Fleet",
    T = "«Поклик повітря» — Флот Ічмана",
    D = "",
    O = "",
    P = "У них падає бойовий дух, солдате. Після нашого останнього невдалого повітряного удару проти Орди вони відмовляються літати! Тільки тобі підняти їхній бойовий дух.$B$BПовертайся на поле бою й завдай удару по самому серцю командування «Морозних Вовків». Знищ їхніх командирів та охоронців. Повернися до мене з якомога більшою кількістю їхніх медалей, скільки зможеш вмістити у свій рюкзак! Обіцяю тобі: коли мої грифони побачать цю здобич і відчують запах крові наших ворогів, вони знову полетять! Рушай негайно!",
    C = "Ти це бачиш? Поглянь на них, солдате! Вони наближаються... Незабаром ескадрилья Ічмана знову завдасть удару по самому серцю долини! «Штормпайк» запанує в небі!",
},

[6961] = {
    en = "Great-father Winter is Here!",
    T = "Дід Мороз уже тут!",
    D = "Бажаємо тобі чудового Зимового свята, друже! Не забудь привітатися з Великим Батьком Зимою! Якщо ти поводився добре цього року, у день Зимового свята ти отримаєш чудові подарунки. Обов’язково розкажи йому, що ти мрієш отримати цього року!$B$BТакож не забудьте запастися смаколиками, щоб подарувати їх тим, хто цього року поводився добре. У нас є чудовий вибір. Свіже з нашої ферми на твій стіл — це корисні та смачні продукти від Smokywood Pastures!",
    O = "Поговоріть із Великим Батьком Зимою; він знаходиться поблизу торгової зони «Смоківуд Пастурес» в Оргримарі.",
    P = "",
    C = "Хо-хо, привіт. Я — Великий Дід Зима, і я — завдяки чудовим людям із «Смоківуд Пастурес»... «Прямо з нашої ферми на ваш стіл — корисні та смачні продукти від «Смоківуд Пастурес» — хотів би побажати вам чудового Свята Зимової Завіси.$B$BЯкщо ви цього року поводилися добре, можливо, ви отримаєте смаколики від «Смоківуд Пастурес» як подарунок до Свята Зимової Завіси. Ура!",
},

[6962] = {
    en = "Treats for Great-father Winter",
    T = "Смаколики для Дідуся Зими",
    D = "Гей, а ти не міг би зробити послугу Великому Батькові Зимі, е-е, маленький $g хлопчик : дівчинка;?$B$BНе хочу даремно говорити про себе у третій особі, але Великий Батько Зима займався цим цілий день, і йому самому не завадило б щось смачненьке. Трохи імбирних пряників і крижаного молока, щоб їх запити, — це було б саме те, що треба. Можеш бути добрим другом Великого Батька і принести мені трохи?",
    O = "Принесіть 5 імбирних печивок та склянку крижаного молока Великому Діду Зимі в Оргримарі.",
    P = "Від усіх цих розмов про ласощі я сама захотіла чогось смачненького. Мммм... імбирні пряники та молоко...",
    C = "Ти справді чудово допомагаєш старому Діду Морозу, $N. Бажаю тобі чудового Свята Зимової Завіси.$B$BОсь тобі невеличкий подарунок… ну, знаєш, за твої зусилля.",
},

[6963] = {
    en = "Stolen Winter Veil Treats",
    T = "Вкрадені ласощі на Зимову завісу",
    D = "Послухайте... не хочу руйнувати чарівність цього сезону, але «Смоківуд Пастерс» зараз дуже потрібна допомога — саме така, яку, як відомо, надають такі авантюристи, як ви.$B$BМи втратили важливу партію ласощів, якою мали поповнити запаси до сезону, а тепер ще й зник агент «Смоківуд Пастерз», якого ми відправили на місце, щоб знайти її! Будь ласка — востаннє про вантаж повідомляли в горах Альтерак, і саме туди наш агент вирушив на пошуки.$B$BПеревірте, чи обоє там, цілі й неушкоджені!",
    O = "Знайдіть слідчого з «Смоківуд Пастерс», який зник у засніжених районах Альтеракських гір.",
    P = "",
    C = "Т-т-ти мене чу-чу-чуєш! С-с-дякую небесам!$B$BЯ насправді не с-с-сніговик — мене з-з-звуть Сакс, і я р-р-працюю в Оргримарському філіалі компанії «Смоківуд Пастерс»... Ме-ме-мене відправили сюди шукати з-з-зниклу посилку, коли на мене напала т-т-тварина, якої я н-н-ніколи раніше не бачив!$B$BТ-т-так холодно...",
},

[6964] = {
    en = "The Reason for the Season",
    T = "Сенс цього свята",
    D = "Подарунки, ласощі, презенти... Та годі вже!$B$BЦі гобліни спотворюють справжній зміст цього свята — Зимової Завіси. Це час оновлення; земля дрімає під ковдрою снігу, яку приніс Великий Батько Зима, який НЕ є тим незграбним дурнем у червоному костюмі!$B$BЯкщо вам цікаво дізнатися, що ж таке це Свято, запитайте Сагорна Крестстрайдера. Я впевнений, він буде здивований, що хтось цікавиться історією, а не лише подарунками.",
    O = "Поговоріть із Сагорном Крестстрайдером у Долині Мудрості в Оргримарі про Свято Зимової Завіси.",
    P = "",
    C = "Свято Зимової Завіси, кажете? На жаль, колись воно мало для нас, тауренів, набагато глибше значення. Сьогодні ж здається, ніби інші перетворили легенду про цю пору відродження на щось, що допомагає продавати цукерки та подарунки.$B$BНе дивно, що Фурмунд з гіркотою ставиться до таких змін. Він та інші таурени, подібні до нього, тримаються за наше минуле, немов за бойовий прапор. Хоча я вважаю, що невелике святкування — це завжди добре, важливо пам’ятати про походження цього Свята.",
},

[6981] = {
    en = "The Glowing Shard",
    T = "Сяючий осколок",
    D = "Осколок має яскраво-зелений колір, і, хоча він твердий, під його поверхнею витають щось схоже на дим. Неможливо не зазирнути в глибину кристала; водночас ти розумієш, що в ньому є щось дуже тривожне.$B$BМожливо, тобі варто дізнатися, чи є в Ратчеті хтось, хто міг би розповісти більше про цей дивний осколок.",
    O = "Відправляйтеся до Ратчета, щоб знайти людину, яка зможе розповісти вам більше про світиться осколок.$B$BПотім доставте осколок, як вам вкажуть.",
    P = "Привіт, $r. Чим можу допомогти?",
    C = "О... Я ще ніколи такого не бачив...",
},

[6982] = {
    en = "Coldtooth Supplies",
    T = "«Coldtooth Supplies»",
    D = "Шахта «Холодний Зуб» — це склад запасів Орди. Мені не до вподоби їжа, якою вони годують своїх солдатів, а стан їхньої зброї та обладунків просто жахливий! Але... у такі часи, коли припаси мають таке важливе значення, ми можемо скористатися тим, що у них є.$B$BЗайди в шахту «Холодний Зуб» і принеси мені їхні припаси. Це допоможе Альянсу залишатися в бойовій готовності, а також позбавить воїнів Орди вкрай необхідного спорядження.$B$BУдачі, $N. Шахта розташована далеко на півдні, глибоко на території Орди.",
    O = "Принесіть 10 одиниць припасів «Холодних зубів» інтенданту Альянсу в Дун-Балдарі.",
    P = "Ти був у шахті «Колдтут», $N? У тебе є ті припаси, про які я просив?",
    C = "А, ти їх знайшов. Молодець, $N! Ці припаси трохи запріли від того, що так довго пролежали в тій темній шахті, але ми все одно їх використаємо.$B$BДякую, $N. Твої вчинки мають вирішальне значення для підтримання боєздатності наших збройних сил.",
},

[6983] = {
    en = "You're a Mean One...",
    T = "Ти — справжній лиходій...",
    D = "С-с-істота на ім’я «Огидний Грінч» — це той, хто в-в-вкрав нашу партію с-с-солодощів, $N. Але будьте об-об-обережні! Саме він п-п-перетворив мене на цю с-с-сніжну купу!$B$BТобі знадобиться т-т-трохи допомоги, щоб з-з-з ним впоратися. Я бачив, як він б-б-блукав по тих місцях, де живуть й-й-єті; він, б-б-безумовно, десь т-т-тут! З-з-знайдіть ласощі $N, віднесіть їх д-д-до «Смоківуд Пастурес» в Оргримарі та с-с-скажіть їм, що мене т-т-треба розморозити!",
    O = "Знайдіть і поверніть «Вкрадені ласощі» Кеймарду Копперпінчу в Оргримарі. Останнє, що про них відомо, — вони перебували у володінні Огидного Грінча, якого можна знайти десь у засніжених районах Альтеракських гір.",
    P = "$N — без цих ласощів, які треба поповнити, наше свято «Зимової завіси» буде зіпсоване! Сам Граку не зможе поділитися своїми смачними м’ясними пиріжками з усіма слухняними хлопчиками та дівчатками цього сезону...",
    C = "Ви знайшли його! Ви врятували «Свято Зимової завіси» на пасовищі Смоківуд!$B$BБідний Сакс... Ми обов'язково надішлемо туди команду, щоб знайти спосіб розморозити його. Сподіваємося, він встигне повернутися до дня Свята; хоча йому доведеться відпрацювати пропущений час. Та все ж, без вас це було б неможливо!",
},

[6984] = {
    en = "A Smokywood Pastures Thank You!",
    T = "Подяка від Smokywood Pastures!",
    D = "Ми, у «Смоківуд Пастурес», вдячні за повернення вкрадених ласощів, $N. За це ми хотіли б подарувати вам особливий подарунок... від самого Великого батька Зими!$B$BБудь ласка, зверніться до Великого батька Зими, і він вручить вам подарунок до Свята Зимової завіси від нас, Smokywood Pastures. Від нашої ферми до вашої тарілки — це завжди корисні та смачні продукти від Smokywood Pastures... звичайно ж, завдяки вам!",
    O = "Поговоріть із Дідом Зимою в Оргримарі.",
    P = "",
    C = "Гей-гей, привіт, мандрівнику!$B$BГобліни розповіли мені, що ти заслужив особливий подарунок у цей святковий сезон, і я з радістю його тобі вручаю. Ось, тримай — бажаю тобі чудового Свята Зимової Завіси цього року та в усіх наступних сезонах.",
},

[6985] = {
    en = "Irondeep Supplies",
    T = "«Irondeep Supplies»",
    D = "Карлики «Штормпайк» використовують шахту «Залізна глибина» як склад. Я хочу, щоб ти здійснив напад на цю шахту та приніс мені її запаси. Це послабить зусилля «Штормпайків» у Долині Альтерака та забезпечить нас необхідним спорядженням!$B$BБудь обережним, $N. Шахта «Залізна глибина» розташована глибоко на території Альянсу, а контроль над нею мінливий, як сніги Альтерака.",
    O = "Принесіть «10 предметів спорядження «Айрондіп»» до інтенданта Орди у фортеці «Фростволф».",
    P = "Ти зайшов у шахту «Айрондіп», $N? Ти розграбував її запаси?",
    C = "Ти їх дістав! Молодець, $N! І сподіваюся, ти побачив кількох гномів під час свого рейду та пролив їхню кров за «Морозних вовків»!",
},

[7001] = {
    en = "Empty Stables",
    T = "Порожні стайні",
    D = "Війна в долині завдала важких втрат нашим воїнам. Ми мусимо відновити наші сили!$B$BЯкщо нам вдасться заповнити стайні, Вовчі вершники знову зможуть виїхати на поле бою.$B$BВізьми цей намордник і відшукай морозних вовків, що мешкають у сусідньому лісі. Як тільки знайдете вовка, використовуйте намордник, щоб приручити звіра. Приведіть прирученого звіра до мене, щоб я міг помістити його у стайню.$B$BКоли у стайні буде достатньо вовків, «Вовчі вершники» знову приєднаються до патрулювання на наших передових позиціях.",
    O = "Знайдіть морозного вовка в Долині Альтерак. Коли ви опинитеся поруч із морозним вовком, скористайтеся «Намордником для морозного вовка», щоб «приручити» тварину. Після приручення морозний вовк піде за вами до конюха морозних вовків. Поговоріть із конюхом морозних вовків, щоб отримати винагороду за його полон.",
    P = "Без вашої допомоги вершники з клану «Морозних вовків» не мали б коней, на яких можна було б вирушати в бій. Ви робите нам велику послугу!",
    C = "Мені залишається лише сподіватися, що ті, хто відповідає за збір шкур баранів, такі ж рішучі, як і ти, $N.$B$BТакими темпами наші стайні заповняться вже за кілька годин!",
},

[7002] = {
    en = "Ram Hide Harnesses",
    T = "Ремені з овечої шкіри",
    D = "Поки частина наших воїнів зайнята виловом вовків для управителя стайні, інші повинні забезпечити найнеобхідніше для верхової їзди. Я, звісно, маю на увазі збрую для верхової їзди.$B$BВи повинні полювати на місцевих баранів цього регіону. Ті самі барани, яких кавалерія «Штормпік» використовує як верхових тварин!$B$BУбийте їх і поверніться до мене зі шкірами. Як тільки ми зберемо достатньо шкір, ми виготовимо з них збрую для вершників. Вершники «Морозних вовків» знову виїдуть у сідло!",
    O = "null",
    P = "Вбийте їх і поверніться до мене з їхніми шкурами. Це ті самі барани, яких кавалерія «Штормпайк» використовує як верхових тварин!",
    C = "Молодець, солдате. Я повідомлю тебе, коли назбираю достатню кількість шкур.$B$BПродовжуй!",
},

[7003] = {
    en = "Zapped Giants",
    T = "«Заппед Джайнтс»",
    D = "Якщо я залишуся тут, мені доведеться щось робити з цими велетнями! Вони, безперечно, не сприяють бізнесу, чи не так?$B$BЯ працюю над модифікацією гномського променя зменшення, але у його конструкції використовую передові технологічні досягнення гоблінів! Щоб уникнути для себе таких неприємностей, як смерть, я хотів би, щоб ти випробував його на будь-якому з велетнів у Фераласі. Після зменшення на них мають залишитися сліди мініатюризації — принеси мені трохи!",
    O = "Використовуйте «Ультра-зменшувач» Зорбіна, щоб зменшити будь-якого гіганта, якого можна зустріти у Фераласі, до більш зручного розміру. Принесіть 15 «Залишків мініатюризації», які можна знайти на зменшених версіях цих гігантів, до Зорбіна Фандазла на причалах Забутого узбережжя у Фераласі.",
    P = "Залишки мініатюризації, запевняю вас, — це цінний ресурс, коли йдеться про інженерію! Ну, це цінно тим, що допомагає мені переконатися, що «заппер» не зробить чогось такого прикрого, як вибухнути в руках користувача.$B$BО, я маю на увазі «заппери», крім того, який я вам дав. Безумовно!",
    C = "Чудово! Я не тільки радий, що ти повернувся з залишками, а й що всі твої основні кінцівки цілі! Тобто, ну, адже у використанні «Ультра-зменшувача» ніколи не було ніякої небезпеки, чи не так!$B$BЯ дуже ціную твої зусилля заради мене, $N. Ти справді друг усіх гоблінів. Прийми це як знак моєї вдячності!",
},

[7021] = {
    en = "Great-father Winter is Here!",
    T = "Дід Мороз уже тут!",
    D = "Бажаємо тобі чудового Зимового свята, друже! Не забудь привітатися з Великим Батьком Зимою, який зараз перебуває в Оргримарі! Якщо ти поводився добре цього року, у день Зимового свята ти отримаєш чудові подарунки. Обов’язково розкажи йому, що ти мрієш отримати цього року!$B$BТакож не забудь запастися смаколиками, щоб подарувати їх тим, хто цього року поводився добре. У нас є чудовий вибір. Прямо з нашої ферми на ваш стіл — це корисні та смачні продукти від Smokywood Pastures!",
    O = "Поговоріть із Великим Батьком Зимою; він знаходиться поблизу зони торговців «Смоківуд Пастурес» в Оргримарі.",
    P = "",
    C = "Хо-хо, привіт. Я — Великий Дід Зима, і я — завдяки люб’язності чудових людей із «Смоківуд Пастурес»… «Прямо з нашої ферми на ваш стіл — корисні та смачні продукти від «Смоківуд Пастурес»» — хотів би побажати вам фантастичного Свята Зимової Завіси.$B$BЯкщо ви цього року поводилися добре, можливо, ви отримаєте смаколики від «Смоківуд Пастурес» як подарунок на Свято Зимової Завіси. Ура!",
},

[7022] = {
    en = "Greatfather Winter is Here!",
    T = "Прийшла зима!",
    D = "Бажаємо тобі чудового Зимового свята, друже! Не забудь привітатися з Великим Батьком Зимою! Якщо ти поводився добре цього року, у день Зимового свята ти отримаєш чудові подарунки. Обов’язково розкажи йому, що ти хочеш отримати цього року!$B$BТакож не забудь запастися смаколиками, щоб подарувати їх тим, хто цього року поводився добре. У нас є чудовий вибір. Прямо з нашої ферми на твій стіл — це корисні та смачні продукти від Smokywood Pastures!",
    O = "Поговоріть із Великим Батьком Зимою; він знаходиться поблизу зони торговців «Смоківуд Пастерс» в Айронфорджі.",
    P = "",
    C = "Хо-хо, привіт. Я — Великий Дід Зима, і я — завдяки люб’язності чудових людей із «Смоківуд Пастурес»… «Прямо з нашої ферми на ваш стіл — корисні та смачні продукти від «Смоківуд Пастурес» — хотів би побажати вам чудового Свята Зимової Завіси.$B$BЯкщо ви цього року поводилися добре, можливо, ви отримаєте подарунки від «Смоківуд Пастурес» на честь Свята Зимової Завіси. Ура!",
},

[7023] = {
    en = "Greatfather Winter is Here!",
    T = "Прийшла зима!",
    D = "Бажаємо тобі чудового Зимового Свята, друже! Обов’язково привітайся з Великим Батьком Зимою, який зараз перебуває в Айронфорджі! Якщо ти поводився добре цього року, то в день Зимового Свята отримаєш чудові подарунки. Обов’язково розкажи йому, що ти мрієш отримати цього року!$B$BТакож не забудьте запастися смаколиками, щоб подарувати їх тим, хто цього року поводився добре. У нас є чудовий вибір. Прямо з нашої ферми на твій стіл — це корисні та смачні продукти від «Смоківуд Пастурес»!",
    O = "Поговоріть із Великим Батьком Зимою; він знаходиться поблизу зони торговців «Смоківуд Пастурес» в Айронфорджі.",
    P = "",
    C = "Хо-хо, привіт. Я — Великий Дід Зима, і я — завдяки люб’язності чудових людей із «Смоківуд Пастурес»… «Прямо з нашої ферми на ваш стіл — корисні та смачні продукти від «Смоківуд Пастурес»» — хотів би побажати вам чудового Свята Зимової Завіси.$B$BЯкщо ви цього року поводилися добре, можливо, ви отримаєте смаколики від «Смоківуд Пастурес» як подарунок до Свята Зимової завіси. Ура!",
},

[7024] = {
    en = "Great-father Winter is Here!",
    T = "Дід Мороз уже тут!",
    D = "Бажаємо тобі чудового Зимового свята, друже! Не забудь привітатися з Великим Батьком Зимою, який зараз перебуває в Оргримарі! Якщо ти поводився добре цього року, у день Зимового свята ти отримаєш чудові подарунки. Обов’язково скажи йому, що ти сподіваєшся отримати цього року!$B$BТакож не забудь запастися смаколиками, щоб поділитися з тими, хто поводився добре цього року. У нас є чудовий вибір. Прямо з нашої ферми на ваш стіл — це корисні та смачні продукти від Smokywood Pastures!",
    O = "Поговоріть із Великим Батьком Зимою; він знаходиться поблизу зони торговців «Смоківуд Пастурес» в Оргримарі.",
    P = "",
    C = "Хо-хо, привіт. Я — Великий Дід Зима, і я — завдяки люб’язності чудових людей із «Смоківуд Пастурес»… «Прямо з нашої ферми на ваш стіл — корисні та смачні продукти від «Смоківуд Пастурес» — хотів би побажати вам чудового Свята Зимової Завіси.$B$BЯкщо ви цього року поводилися добре, можливо, ви отримаєте смаколики від «Смоківуд Пастурес» як подарунок до Свята Зимової Завіси. Ура!",
},

[7025] = {
    en = "Treats for Greatfather Winter",
    T = "Смаколики для Дідуся Зими",
    D = "Гей, а ти не міг би зробити послугу Великому Батькові Зимі, е-е, маленький $g хлопчик : дівчинка;?$B$BНе хочу даремно говорити про себе у третій особі, але Великий Батько Зима займався цим цілий день, і йому самому не завадило б щось смачненьке. Трохи імбирних пряників і крижаного молока, щоб їх запити, — це було б просто те, що треба. Можеш бути добрим другом Великого Батька і принести мені трохи?",
    O = "Принесіть 5 імбирних печивок та склянку крижаного молока Великому Діду Зимі в Айронфорзі.",
    P = "Від усіх цих розмов про ласощі я сама почала їх хотіти. Мммм... імбирні печива та молоко...",
    C = "Ти справді чудово допомагаєш старому Діду Зимі, $N. Бажаю тобі чудового Свята Зимової Завіси.$B$BОсь тобі невеличкий подарунок… ну, знаєш, за твої зусилля.",
},

[7026] = {
    en = "Ram Riding Harnesses",
    T = "Упряж для верхової їзди на баранах",
    D = "",
    O = "null",
    P = "Бригада «Штормпайк» не може кидатися в бій без сідла! Нам потрібні збрую для наших верхових тварин — зрештою, ми ж не дикуни.$B$BХоча ми могли б легко вбити баранів, що бродять поблизу нашої бази, щоб дістати шкіру, необхідну для виготовлення збруї, це було б дурістю. Ці барани нам потрібні як верхові тварини.$B$BТи повинен напасти на базу нашого ворога, вбити морозних вовків, яких вони використовують як верхових тварин, і забрати їхні шкури. Принесіть мені їхні шкури, щоб можна було виготовити збрую для кавалерії. Вперед!$B$BВбийте морозних вовків, яких вони використовують як верхових тварин, і принесіть мені їхні шкури.",
    C = "Молодець, солдате. Я повідомлю тебе, коли назбираю достатню кількість шкур.$B$BПродовжуй!",
},

[7027] = {
    en = "Empty Stables",
    T = "Порожні стайні",
    D = "Тільки поглянь на стайні, $N! Вони порожні! У Бригаді «Штормпайк» немає баранів для верхової їзди — кавалерія припинила своє існування.$B$BТи повинен нам допомогти, солдате. Візьміть цей тренувальний нашийник і вирушайте в дикі ліси цієї долини. Знайдіть альтерацьких баранів, які бродять по цій місцевості, і за допомогою нашийника спіймайте одного з них. Коли ти зловиш барана, поверни його мені, і я поміщу його в нашу стайню.$B$BКоли у нас буде достатньо баранів, про це повідомлять командира вершників на баранах. З твоєю допомогою кавалерія відродиться!",
    O = "Знайдіть альтерацького барана в Долині Альтерак. Коли опинитеся поруч з альтерацьким бараном, використовуйте «Нашийник для дресирування Штормпайка», щоб «приручити» тварину. Після приручення альтерацький баран піде за вами до майстра стайні. Поговоріть з майстром стайні, щоб отримати нагороду за упіймання.$B",
    P = "Без вашої допомоги вершники «Штормпайк Рам Райдерс» не мали б коней, на яких можна було б вирушати в бій. Ви робите нам велику послугу!",
    C = "Конюшня заповниться в одну мить. Продовжуйте в тому ж дусі!",
},

[7028] = {
    en = "Twisted Evils",
    T = "Зло, що закрутилося",
    D = "Кришталеві печери Террамока розташовані на заході, глибоко в надрах Мараудона... Це стародавнє місце з багатою історією. І я хочу дістати частину цієї історії, $c. За величезними дверима приховані реліквії старих богів.$B$BЯкщо ти готовий кинути виклик спотвореним силам зла, що мешкають у Мараудоні, я впевнений, що зможу винагородити тебе за твої зусилля. Зберіть терадричні кришталеві різьблення, які знайдете, і поверніть їх мені.$B$BЯк тільки я отримаю ці різьблення, я зможу... дослідити їх. Ці сили занадто довго перебували в спокої...",
    O = "Зберіть 25 терадрійських кристальних різьблень для Віллоу в Десоласі.",
    P = "Не задавай питань!$B$BТи отримав моє прохання.",
    C = "Ха-ха-ха! Я знала, що ти повернешся.$B$B<Віллоу бурмоче>$B$B...Таку легко переконати.$B$B...Зробить що завгодно за відповідну ціну. Хе-хе-хе...",
},

[7029] = {
    en = "Vyletongue Corruption",
    T = "Корупція у Вилетонгу",
    D = "Сатир на ім’я Вайлетонг зіпсував печери Мараудона, загальмувавши ріст багатьох рослин усередині них.$B$BВізьми цю колбу, $N. Наповни її біля помаранчевого кришталевого басейну, що знаходиться всередині печер; покриття всередині флакона нейтралізує токсини, перетворивши рідину на цілющий засіб.$B$BЗнайди лози «Вілестем» у помаранчевих печерах і використай на них очищену рідину. З рослини буде вигнано порчу, але майте на увазі, що Вайлетунг і надалі контролюватиме її. Він може використати її проти вас...",
    O = "Наповніть «Покриту блакитну колбу» біля помаранчевого кришталевого басейну в Мараудоні.$B$BВикористайте «Наповнену блакитну колбу» на ліанах Вайлестема, щоб змусити з’явитися спотвореного «Шкідливого нащадка».$B$BЗціліть 8 рослин, знищивши ці «Шкідливі відростки», а потім поверніться до Варка Баттлскара в селі Шейдоупрей.",
    P = "Якщо вам вдасться вилікувати рослину, вона знову почне рости. Ми повинні зробити все, що в наших силах, $N...",
    C = "Дякую, що повернув це, $N. Завдяки тій рідині, що в тебе залишилася і яку ти приніс мені, я зможу продовжити свої дослідження.$B$BХоча попереду ще багато роботи, ти допоміг виправити частину тієї розтління, яку Вилетонг поширив у Мараудоні. Прийми це на знак моєї вдячності.",
},

[7041] = {
    en = "Vyletongue Corruption",
    T = "Корупція у Вилетонгу",
    D = "Сатир на ім’я Вайлетонг заразив печери Мараудона, що загальмувало ріст багатьох рослин усередині них.$B$BВізьми цю ампулу, $N. Наповни її з зараженого помаранчевого водоймища, яке знаходиться всередині печер; покриття всередині флакона нейтралізує токсини, перетворюючи рідину на цілющий засіб.$B$BЗнайди лози «Вилестем» у помаранчевих печерах і використай на них очищену рідину. З рослини буде вигнано спотворення, але майте на увазі, що Вайлетонг все одно контролюватиме її. Він може використати її проти вас...",
    O = "Наповніть «Покриту блакитну колбу» біля помаранчевого кришталевого басейну в Мараудоні.$B$BВикористайте «Наповнену блакитну колбу» на лозах Вилестема, щоб змусити з’явитися спотвореного «Отруйного нащадка».$B$BВилікуйте 8 рослин, знищивши цих «Шкідливих нащадків», а потім поверніться до Талендрії в Ніджелс-Пойнт.",
    P = "Якщо вам вдасться вилікувати рослину, вона знову почне рости. Ми повинні зробити все, що в наших силах, $N...",
    C = "Дякую, що повернув це, $N. Завдяки тій рідині, що у тебе залишилася і яку ти приніс мені, я зможу продовжити свої дослідження.$B$BХоча попереду ще багато роботи, ти допоміг виправити частину тієї розпусти, яку Вилетонг поширив у Мараудоні. Прийми це на знак моєї вдячності.",
},

[7042] = {
    en = "Stolen Winter Veil Treats",
    T = "Вкрадені ласощі на Зимову завісу",
    D = "Послухайте... не хочу руйнувати чарівність цього сезону, але «Смоківуд Пастурес» зараз дуже потрібна допомога — саме така, яку зазвичай надають такі авантюристи, як ви.$B$BМи втратили важливу партію ласощів, яка мала поповнити наші запаси на цей сезон, а тепер ще й зник агент «Смоківуд Пастерс», якого ми відправили на пошуки! Будь ласка — востаннє про вантаж повідомляли в горах Альтерак, і саме туди наш агент вирушив на пошуки.$B$BПеревірте, чи обоє там, живі й здорові!",
    O = "Знайдіть слідчого з «Смоківуд Пастерс», який зник у засніжених районах Альтеракських гір.",
    P = "",
    C = "Т-т-ти мене чу-чу-чуєш! С-с-дякую Богу!$B$BЯ насправді не с-с-сніговик — мене з-з-звуть Сакс, і я п-п-працюю у філії «Смоківуд Пастурес» у Айронфорджі... Мене п-п-послали сюди шукати з-з-зниклу посилку, коли на мене напала т-т-тварина, якої я н-н-ніколи раніше не бачив!$B$BТ-т-так холодно...",
},

[7043] = {
    en = "You're a Mean One...",
    T = "Ти такий злий...",
    D = "С-с-істота на ім’я «Огидний Грінч» — це саме той, хто в-в-вкрав нашу партію с-с-солодощів, $N. Але будьте об-об-обережні! Саме він п-п-перетворив мене на цю с-с-сніжну купу!$B$BТобі знадобиться т-т-допомога, щоб з-з-зіткнутися з ним. Я бачив, як він б-б-блукав по тих місцях, де живуть й-й-єті; він, б-б-безумовно, десь тут! З-з-знайди ласощі $N, віднеси їх д-д-до «Смоківуд Пастурес» в Айронфорзі та с-с-скажи їм, що мене т-т-треба розморозити!",
    O = "Знайдіть і поверніть «Вкрадені ласощі» Вулморту Джинглпокету в Айронфорзі. Останнє, що про них відомо, — це те, що вони перебували у володінні Огидного Грінча, якого можна знайти десь у засніжених районах Альтеракських гір.$B",
    P = "$N — без цих ласощів, якими треба поповнити запаси, наше Свято Зимової Завіси буде зіпсоване! Сам Граку не зможе поділитися своїми смачними м’ясними пирогами з усіма слухняними хлопчиками та дівчатками цього сезону...",
    C = "Ви знайшли його! Ви врятували «Свято Зимової завіси» у Смоківуд-Пастурі!$B$BБідний Сакс… Ми обов’язково надішлемо туди команду, щоб знайти спосіб розморозити його. Сподіваємося, він встигне повернутися до дня Свята; хоча йому доведеться відпрацювати пропущений час. Та все одно це було б неможливо, якби не ти!",
},

[7044] = {
    en = "Legends of Maraudon",
    T = "Легенди Мараудона",
    D = "Темний сатир на ім’я Лорд Вайлетонг поширював своє зло цими звивистими печерами, отруюючи розуми всіх, хто перебував усередині. Він і досі мешкає за фіолетовими кристалами.$B$BВайлетонг також створив живий символ своєї розбещеності на ім’я Ноксіон, який мешкає за помаранчевими кристалами. Разом вони викрали дві частини скіпетра мого брата. Селебрас, мій брат... він сліпо блукає всередині, проклятий зіпсованістю.$B$BТи мусиш йому допомогти! Знайди ці частини і поговори з моїм братом... будь-яким чином.",
    O = "Знайдіть дві частини Скіпетра Селебраса: Палицю Селебрії та Алмаз Селебрії.$B$BЗнайдіть спосіб поспілкуватися з Селебрасом.",
    P = "Я прокинувся від кошмару, який, здавалося, ніколи не закінчиться...",
    C = "Тепер, коли ти віднайшов обидві частини мого скіпетра, я сподіваюся, що Мараудон колись зможе позбутися спотворення Віле.",
},

[7045] = {
    en = "A Smokywood Pastures Thank You!",
    T = "Подяка від Smokywood Pastures!",
    D = "Ми, у «Смоківуд Пастурес», вдячні за повернення вкрадених ласощів, $N. За це ми хотіли б подарувати вам особливий подарунок... від самого Великого Батька Зими!$B$BБудь ласка, зверніться до Великого батька Зими, і він вручить вам подарунок до Свята Зимової Завіси від нас, Smokywood Pastures. Від нашої ферми до вашої тарілки — це завжди корисні та смачні продукти від Smokywood Pastures... звичайно ж, завдяки вам!",
    O = "Поговоріть із Великим Батьком Зимою в Айронфорджі.",
    P = "",
    C = "Гі-гі, привіт, мандрівнику!$B$BГобліни розповіли мені, що ти заслужив особливий подарунок у цей святковий сезон, і я з радістю його тобі вручаю. Ось, будь ласка — бажаю тобі чудового Свята Зимової Завіси цього року та в усі наступні сезони.",
},

[7046] = {
    en = "The Scepter of Celebras",
    T = "Скіпетр Целебраса",
    D = "Колись моє скіпетр було для мене джерелом надії. Його сила давала мені свободу швидко подорожувати цими печерами. Я сподівався принести спокій душі мого дядька... Це завдання я тепер передаю тобі.$B$BЩоб дві частини знову стали єдиним цілим, мені знадобиться ваша допомога у проведенні ритуалу. Будь ласка, йдіть за мною і слухайте мої вказівки, поки я спрямовую енергію, необхідну для возз’єднання жезла з діамантом.$B$BРазом ми знову створимо Скіпетр Селебраса!",
    O = "Допоможіть Селебрасу, «Викупленому», у створенні Скіпетра Селебраса.$B$BПоговоріть з ним, коли ритуал завершиться.",
    P = "Якщо ви бажаєте розпочати ритуал заново, будь ласка, відмовтеся від нашої першої спроби, а потім знову зверніться до мене.",
    C = "Будь ласка, візьміть це і пам’ятайте: сила, яку вам тепер надано, має бути використана на благо. Продовжуй свою подорож печерами, і, сподіваюся, ти знайдеш останки мого дядька. На тебе чекає чимало небезпек, $N.$B$BЯкщо виникне потреба, звернися до мене знову.",
},

[7061] = {
    en = "The Feast of Winter Veil",
    T = "Свято Зимової завіси",
    D = "Ось — якщо вам цікаво дізнатися більше про Свято Зимової Завіси, прочитайте цю книгу. Хоча я вважаю, що наше трактування легенди є правильним, я достатньо добре знаюсь на легендах, щоб оцінити збір усієї інформації в одному джерелі.$B$BКоли закінчите, віднесіть книгу до Кейрна Кровавого Копита в Громовому Утворі. Я точно знаю, що йому буде цікаво дізнатися, що й інші зацікавилися історією нашого народу.",
    O = "Не соромтеся прочитати книгу «Свято Зимової завіси», щоб дізнатися більше про це свято. Коли ви прочитаєте книгу, передайте її Кейрну Кровавому Копиту в Громовому Утворі.",
    P = "Вітаю тебе в Мулгорі та в нашій скромній громаді Тандер-Блаффа, друже. Я завжди цікавлюся тими, хто виявляє інтерес до королівства, його мешканців та його історії. Чи саме тому ти стоїш переді мною?",
    C = "Легенди та перекази, пов’язані із Зимовою Завісою, з роками відійшли на другий план у суспільній свідомості. Так, я знаю, що гобліни допомагають відродити це свято, переслідуючи власні цілі, але сам факт, що наш народ хоча б у певній мірі згадує про нього, сприяє збереженню цих переказів.$B$BТвоє прагнення вийти за межі матеріального та дізнатися про наше минуле — це гідна поваги риса, юний $c. Я віддаю шану твоїй мудрості.",
},

[7062] = {
    en = "The Reason for the Season",
    T = "Сенс цього свята",
    D = "Подарунки, ласощі, подарунки... та годі вже!$B$BЦі гобліни спотворюють справжній сенс цього свята — Зимової завіси. Це час оновлення; земля дрімає під ковдрою снігу, яку приніс Великий Батько Зима, який НЕ є тим незграбним дурнем у червоному костюмі, що стоїть он там!$B$BЯкщо вам цікаво дізнатися, що ж таке це Свято, зверніться до історика Карніка з Ліги Дослідників. Я впевнений, він буде здивований, що хтось цікавиться історією, а не подарунками.",
    O = "Поговоріть з істориком Карніком у «Лізі дослідників» в Айронфорзі про Свято Зимової завіси.",
    P = "",
    C = "Свято Зимової завіси, кажете? На жаль, у минулі часи воно мало для нас, гномів, набагато глибше значення. Сьогодні ж здається, ніби інші перетворили легенду про Великого Батька Зиму на щось, що допомагає продавати цукерки та подарунки.$B$BНе дивно, що Голі з гіркотою ставиться до таких змін. Він та інші гноми, подібні до нього, тримаються за наше минуле, наче за бойовий прапор. Хоча я вважаю, що невелике святкування — це завжди добре, важливо пам’ятати про походження цього свята.",
},

[7063] = {
    en = "The Feast of Winter Veil",
    T = "Свято Зимової завіси",
    D = "Ось — якщо вам цікаво дізнатися більше про Свято Зимової Завіси, прочитайте цю книгу. Хоча я вважаю, що наше тлумачення легенди є правильним, я достатньо обізнаний, щоб оцінити збір усієї інформації в одному джерелі.$B$BКоли закінчите, віднесіть книгу королю Магні Бронзобородому. Я точно знаю, що йому буде цікаво дізнатися, що й інші зацікавилися давніми легендами.",
    O = "Не соромтеся прочитати книгу «Свято Зимової завіси», щоб дізнатися більше про це свято. Коли ви прочитаєте книгу, передайте її королю Магні Бронзобородому в Айронфорзі.",
    P = "Вітаю тебе в Королівстві Айронфордж, друже. Мені завжди цікаві ті, хто виявляє інтерес до королівства, його мешканців та його історії. Чи саме тому ти стоїш переді мною?",
    C = "Легенди та перекази, пов’язані із Зимовою завісою, з роками відійшли на другий план у суспільній свідомості. Хоча я усвідомлюю, що гобліни допомагають відродити це свято заради власних цілей, сам факт, що мешканці міста хоча б у певній мірі згадують про нього, сприяє збереженню цих переказів.$B$BТвоє прагнення вийти за межі матеріального та дізнатися про наше минуле — це гідна поваги риса, юний $C. Я віддаю шану твоїй ерудиції.",
},

[7064] = {
    en = "Corruption of Earth and Seed",
    T = "Знищення землі та насіння",
    D = "У глибинах Мараудона мешкає злісна істота хаосу — принцеса Терадрас, елементальна сила землі, пов’язана зі Старими Богами. Багато століть тому вона та Заетар, старший син Сенаріуса, почали стосунки. Нащадки їхнього союзу стали відомі мешканцям Калімдору як кентаври. Будучи вічно вдячними істотами, кентаври вбили Заетара і тепер зберігають його останки. Моє завдання тут — знайти тих, хто достатньо сильний, щоб вбити Терадрас, щоб ми могли повернути останки Заетара, перш ніж повернутися до Стоунталона.",
    O = "Знищ принцесу Тедрас і повернися до Селендри, що поблизу села Шейдоупрей у Десоласі.",
    P = "Я б волів би вести цю битву самостійно, але в нас не залишилося інших варіантів — нам потрібні ті, хто сильніший, і раси Азерота безсумнівно довели, що здатні подолати такі випробування, коли об’єднуються. Тож саме до вас ми звертаємося по допомогу.$B$BЯ лише сподіваюся, що цього вистачить.$B$BЗаетар, брат Ремулоса, приніс цьому світу багато страждань, і зрештою це призвело до його власної смерті. Я лише сподіваюся, що, попросивши вас про допомогу, я не спричинив ще більше смертей.",
    C = "Це просто чудова новина, $N! Дякую!$B$BЯ поговорю з Марандісом і попрошу його поради щодо останків Заетара, але ти, принаймні, впорався з найскладнішим завданням.$B$BМені сказали, що якщо ми успішно виконаємо місію, я матиму право нагородити тих, хто нам допомагав. Мені передали ці предмети як знаки вдячності від нашого народу — ти можеш вибрати один із них.",
},

[7065] = {
    en = "Corruption of Earth and Seed",
    T = "Знищення землі та насіння",
    D = "У глибинах Мараудона мешкає істота хаосу й зла, $N. Принцеса Терадрас — це стихійна сила землі, яка якимось чином пов’язана зі Старими Богами. Багато століть тому її розшукав Заетар, старший син Сенаріуса. Плодом їхніх... стосунків стали істоти, відомі як кентаври. Кентаври, завжди вдячні за це, вбили Заетара, а тепер Терадрас зберігає його останки. Моє завдання тут — знайти тих, хто достатньо сильний, щоб убити Терадрас, щоб ми могли повернути останки Заетара, перш ніж повернутися до Стоунталона.",
    O = "Знищте принцесу Терадрас і поверніться до Хранителя Марандіса на Мисі Ніджела в Десоласі.",
    P = "Я відчуваю тягар відповідальності, накладаючи це прохання на смертні раси, але у нас не залишилося інших варіантів. Раси Азерота безсумнівно довели, що здатні подолати такі випробування, коли діють спільно, тож саме до них я звертаюся по допомогу.$B$BЯ лише сподіваюся, що цього вистачить.$B$BЗаетар, брат Ремулоса, приніс цьому світу багато страждань, і зрештою це призвело до його власної смерті. У цьому є урок для всіх нас, якщо ми будемо достатньо мудрими, щоб його побачити.",
    C = "Це просто чудова новина, $N! Дякую!$B$BХоча мене турбує, що тобі не вдалося привезти останки Заетара, але хто я такий, щоб ставити під сумнів волю первістка Сенаріуса. Можливо, тепер воля кентаврів зламається, а їхня жага крові зменшиться — нам залишається лише сподіватися.$B$BНа випадок успіху нашої місії мені доручили передати ці предмети як нагороду всім, хто нам допомагав. Ви можете вибрати один із них на знак подяки.",
},

[7066] = {
    en = "Seed of Life",
    T = "Насіння життя",
    D = "Ці нещасні кентаври — мої сини й дочки — потребують свого батька.$B$BПогляньте навколо — це місце просякнуте надією та всім тим, що проповідує мій батько Сенаріус. Воно походить від мене! І я не можу цього в них відібрати… навіть за їхні злочини проти мене.$B$BАле є одна річ, про яку я хотів би вас попросити, щоб заспокоїти душу мого брата. Візьміть це… це перше насіння, що впало з життя, яке живили мої останки. Скажіть йому, що мій дух залишається тут і що я продовжую жити. Я впевнений, що він зрозуміє.",
    O = "Знайдіть Ремулоса в Місячній галявині та передайте йому Насіння життя.",
    P = "Від тебе віє запахом корупції, $N... як і від багатьох сучасних мандрівників. Але в тобі є щось особливе. Ти прийшов до мене, щоб про щось поговорити? Від тебе виходить якась аура, що здається мені знайомою, але я не можу згадати, звідки.$B$BБудь ласка, благаю тебе, скажи мені, чому ти попросив про аудієнцію зі мною.",
    C = "Тож мій брат нарешті знайшов спокій? Я пишаюся тим, що дожив до цього дня. З огляду на всю його зарозумілість і гнів, я справді думав, що ми його втратили, але це… цей символ його самопожертви лише доводить, що він не втрачений — він просто відродився. Він займає своє місце в природі, як і належало.$B$BДякую, $N. Принісши це мені, ти подарував мені краплину надії, яку я вважав уже втраченою. Це насіння колись стане важливим для людей цієї розтерзаної війною землі… Я це відчуваю.",
},

[7067] = {
    en = "The Pariah's Instructions",
    T = "Настанови Парії",
    D = "Хоча мене вигнали як єретика, мої переконання й досі залишаються істинними — саме це й спонукає мене йти вперед. Але щоб моя доля здійснилася, мені потрібна допомога чужинця… того, хто не належить до жодного племені кентаврів.$B$BЦе завдання вимагає, щоб хтось увійшов до священних залів Мараудона — гробниці, яку охороняє мій народ, і куди допускаються лише найпобожніші.$B$BЯкщо ти згоден допомогти мені, тобі достатньо лише кивнути головою. Я передам тобі пергамент із моїми вказівками. Прочитай його й обміркуй мої слова.",
    O = "Ознайомтеся з інструкціями ізгоя. Після цього дістаньте Амулет єдності в Мараудоні та поверніть його кентавру-ізгою на півдні Десоласу.",
    P = "Що ти вирішив, $N? Чи зможеш ти мені допомогти? Чи ступиш ти на святу землю, щоб допомогти мені створити одне велике плем’я кентаврів!?",
    C = "Ось і все, $R! Ось і все! Тепер я можу приступити до великого завдання — об’єднання племен. Дякую.$B$BОсь вам, будь ласка, за ваші зусилля. Сподіваюся, наступна наша зустріч відбудеться в зовсім інших обставинах.",
},

[7068] = {
    en = "Shadowshard Fragments",
    T = "Фрагменти Тіньового Уламка",
    D = "У святині кентаврів... у святині Мараудона... можна знайти потужну магію. Племена кентаврів з Десоласу захищають це місце ціною власного життя, але вони не зможуть завадити нам забрати те, що нам потрібно.$B$BТи ж вирушай до цього Мараудона й знайди там скельних істот, створених із тіньових осколків. Принеси мені фіолетові кристали, і Утель'ней зробить тобі щось за твою працю.$B$BЦе місце небезпечне, тож, можливо, тобі варто взяти з собою друзів.",
    O = "Зберіть 10 уламків Тіньового осколка в Мараудоні та поверніть їх Утель'нею в Оргримарі.",
    P = "Ти вже знайшов кристали? Ритуали сили, заклинання великої потужності — ці уламки тіні можуть виявитися дуже корисними у всіх видах таємної магії.",
    C = "Ах, ці чарівні речі — саме те, що мені потрібно. Ось, візьми одну з цих дрібничок і йди собі… Мені ще багато чого треба вивчити.",
},

[7070] = {
    en = "Shadowshard Fragments",
    T = "Фрагменти Тіньового Осколка",
    D = "Нещодавно я почав досліджувати різні кристали та їхні таємничі властивості. Леді Праудмур дозволила мені попросити мандрівників, які прямують до Десоласу, розшукати місце під назвою Мараудон. У руїнах храму мешкають величезні елементалі, утворені з фіолетових каменів, які я назвав «тіньовими осколками».$B$BЯкщо ви вирішите вирушити в той бік і знайти кілька таких кристалів, я буду вам дуже вдячний. Я навіть можу виготовити для вас прикрасу з них, якщо ви цього забажаєте.",
    O = "Зберіть 10 уламків Тіньового осколка в Мараудоні та поверніть їх архімагу Тервошу в Тераморі, що на узбережжі Болота Дастволл.",
    P = "Ти вже здійснив цю подорож? Я розумію, що це було б досить небезпечно, але якби тобі це вдалося, то це було б того варте.",
    C = "Вони просто чудові, $N. Насправді до мене повернулися й інші мандрівники звідти, і завдяки їм я зміг виготовити ось ці... будь ласка, візьми один — це винагорода за твою важку працю. І ще раз дякую за додаткові зразки для вивчення.",
},

[7081] = {
    en = "Alterac Valley Graveyards",
    T = "Кладовища в Долині Альтерак",
    D = "Кладовища в Долині Альтерак — це стратегічно важливі території. І Орда, і Альянс запекло борються за ці священні землі. Чи готовий ти, $N, приєднатися до цієї битви?$B$BЯ хочу, щоб ти здійснив напад на вороже кладовище. Знайди кладовище, посеред якого стоїть прапор Орди, і вирви його з землі! Зроби це — і твоє завдання буде виконано....$B$BАле якщо тобі вдасться утримати кладовище протягом кількох хвилин, наші війська незабаром прийдуть, щоб замінити тебе.",
    O = "Здійсніть напад на кладовище, а потім поверніться до сержанта Дургена Стормпайка в горах Альтерак.",
    P = "$N, ти ще не напав на кладовище. Повертайся до мене, коли виконаєш це завдання!",
    C = "Молодець! Кладовища відіграють вирішальну роль у нашому контролі над Долиною Альтерак. Захопивши одне з них, ти допомагаєш забезпечити суверенітет Альянсу в цьому регіоні.$B$BРушай, $N. Повертайся в бій, і якщо побачиш кладовище, що перебуває під контролем Орди... ти знаєш, що робити!",
},

[7082] = {
    en = "The Graveyards of Alterac",
    T = "Кладовища Альтерака",
    D = "Лінії фронту в Долині Альтерака постійно змінюються. Території переходять з рук в руки, коли ми стикаємося з супротивниками у смертельних боях. А на кладовищах, $N, битви точаться найзапекліше.$B$BЯ хочу, щоб ти атакував кладовище, яке утримує Альянс! Знайдіть кладовище, посеред якого стоїть прапор Альянсу, і вирвіть його з землі.$B$BЗробіть це — і ваше завдання для мене буде виконано, але... якщо ви утримаєте кладовище протягом кількох хвилин, воно стане нашим, і на зміну вам прийдуть підкріплення.",
    O = "Здійсніть напад на кладовище, а потім поверніться до капрала Тіки Бладснарл у горах Альтерак.",
    P = "Здійсніть напад на кладовище, яке утримує Альянс!",
    C = "Молодець, $N! З кожним кладовищем, що переходить під наш контроль, духи наших ворогів будуть блукати все більш розгублено й безцільно.",
},

[7101] = {
    en = "Towers and Bunkers",
    T = "Вежі та бункери",
    D = "Вежі та бункери — це важливі позиції, і ми маємо захопити та утримати їх усі! Тож для цього я хочу, щоб ви атакували бункер, який контролюється ворогом.$B$BЩоб це зробити, зайдіть у бункер із прапором Альянсу. Всередині ви побачите інший прапор. Витягніть цей прапор, і на його місці з’явиться білий прапор Орди. Молодці!$B$BНа цьому ваше завдання для мене буде виконано, але якщо ви утримаєте цю позицію достатньо довго, і якщо Альянс не відвоює її, то вона буде знищена!",
    O = "Захопіть ворожу вежу, а потім поверніться до капрала Тіки Бладснарл у горах Альтерак.",
    P = "Ти ще не штурмував бункер, $N! Чи чекаєш, поки інші заберуть твою славу?",
    C = "Я чув про успіх вашої місії! Це мене тішить...$B$BТепер наші війська можуть безперешкодно рухатися вперед і показати Альянсу, що Долина Альтерака — не місце для них!",
},

[7102] = {
    en = "Towers and Bunkers",
    T = "Вежі та бункери",
    D = "Вежі та бункери — це ключові оборонні позиції, тому ми мусимо утримати якомога більше з них! Я хочу, щоб ви атакували вежу або бункер у Долині Альтерак.$B$BДля цього зайдіть у вежу, на вершині якої майорить прапор Орди. Всередині ви побачите інший ворожий прапор. Витягніть цей прапор, і на його місці з’явиться білий прапор Альянсу. Молодці!$B$BНа цьому ваше завдання для мене буде виконано, але утримуйте цю територію достатньо довго, і якщо Орда не відвоює її, то вона буде знищена!",
    O = "Знищте прапор біля ворожої вежі або бункера, а потім поверніться до сержанта Дургена Штормпайка в горах Альтерака.",
    P = "Ти ще не штурмував вежу, $N! На що ти чекаєш?",
    C = "Я отримав бойовий звіт, у якому зазначено, що ти допоміг захопити ворожий прапор. Молодець, $N! Тепер, коли їхні стрілецькі підрозділи виведені з позицій, ми можемо просунути лінію фронту вперед!",
},

[7121] = {
    en = "The Quartermaster",
    T = "Квартирмейстер",
    D = "$N, наш інтендант доручив мені направляти до нього новобранців. Йому потрібні припаси зі схованок, що зберігаються в шахтах Альтерака, і, ймовірно, він відправить вас за ними.$B$BЙдіть дорогою. Наш інтендант знаходиться на заході.",
    O = "Поговоріть з інтендантом «Штормпайка».",
    P = "",
    C = "Приємно бачити тут нових бійців, $N, але, якщо пощастить, ви потрапите в бій і вже незабаром перестанете бути новачками!$B$BЗверніться до мене ще раз. У мене є завдання, які я мушу з вами обговорити...",
},

[7122] = {
    en = "Capture a Mine",
    T = "Захопити шахту",
    D = "У шахтах Долини Альтерак є не лише корисні копалини. І «Морозні Вовки», і «Штормпайк» сховали надлишки запасів у шахтах «Залізна Глибина» та «Холодний Зуб»… Це непогана ідея, якби тільки нам вдалося утримати над ними контроль!$B$BЗахопіть шахту, а потім поверніться до мене. Щоб захопити шахту, зайдіть у ту, яку ми не контролюємо, і вбийте її ватажка. Коли ви це зробите, шахта стане нашою, і ми надішлемо війська, щоб її захистити!",
    O = "Захопіть шахту, яка не перебуває під контролем «Штормпіків», а потім поверніться до сержанта Дургена Штормпіка в горах Альтерак.",
    P = "Ти ще не захопив шахту, $N!$B$BПісля того, як ми візьмемо шахту під контроль, збирати з неї корисні копалини та ресурси стане набагато простіше.",
    C = "Ти це зробив! Молодець, $N!$B$BКоли ми контролюємо шахту і розміщуємо там війська, збирати з неї корисні копалини та припаси стає набагато простіше.",
},

[7123] = {
    en = "Speak with our Quartermaster",
    T = "Зверніться до нашого інтенданта",
    D = "$N, інтендант «Морозних вовків», шукає новобранців для виконання завдань у шахтах Долини Альтерак. Поговоріть з ним — він розповість вам більше.$B$BЙдіть дорогою на захід до бункера, потім вийдіть через західний вихід — там ви знайдете нашого інтенданта.",
    O = "Поговоріть з інтендантом «Фростволф».",
    P = "",
    C = "Вітаю, $N! Приємно бачити такого $C, як ти, який прагне зробити свій внесок у справу Орди. Поговори зі мною ще раз, бо у мене для тебе є надзвичайно важливі завдання...",
},

[7124] = {
    en = "Capture a Mine",
    T = "Захопити шахту",
    D = "Поки на просторах Долини Альтерак вирує битва, вона також розгорається у шахтах «Холодний Зуб» та «Залізна Глибина». Обидві є багатими джерелами корисних копалин і використовуються для зберігання припасів; не дивно, що їх так високо цінують!$B$BДопоможіть нам у війні, $N! Захопіть одну з шахт для Орди! Щоб захопити шахту, увійдіть у ту, яку ми ще не контролюємо, і вбийте її ватажка. Коли це буде зроблено, шахта стане нашою, і ми надішлемо війська, щоб її захистити!",
    O = "Захопіть шахту, а потім поверніться до капрала Тіки Бладснарл у горах Альтерак.",
    P = "Ти ще не захопив жодної шахти, $N! Знайди ту, яку ми не контролюємо, і переможи її керівника!",
    C = "Ви захопили шахту! Тепер, коли її охороняють наші воїни, видобувати корисні копалини з її надр або збирати запаси, що там сховані, стане набагато простіше.$B$BМолодець, $N>. Те, що ти зробив, — велика допомога в наших бойових зусиллях.",
},

[7141] = {
    en = "The Battle of Alterac",
    T = "Битва при Альтераку",
    D = "Ліга Дослідників вважає, що в Долині Альтерак знаходяться артефакти, але орки з клану «Морозних Вовків» не дозволяють нам проводити там дослідження. Ми не можемо дозволити Орді перешкоджати нашим науковим пошукам! Знищте генерала «Морозних вовків» Дрек'Тара. З його смертю орки втратять свою перевагу.$B$BДрек'Тар перебуває у фортеці «Морозних вовків», на півдні Долини Альтерак. Знищте його, а потім поверніться до мене.",
    O = "Зайдіть у Долину Альтерак, переможіть генерала Орди Дрек’тара, а потім поверніться до старателя Стоунхьюера в Горах Альтерак.",
    P = "Вперед, $N! Відправляйся до Долини Альтерак і переможи генерала орків!",
    C = "Молодець, $N! Тепер, коли Орда зазнала поразки після загибелі свого полководця, у нас з’явиться необхідний простір для маневру, щоб продовжити дослідження!",
},

[7142] = {
    en = "The Battle for Alterac",
    T = "Битва за Альтерак",
    D = "Карлики Штормпайк та їхні союзники вторглися в Долину Альтерак, і ми мусимо вигнати їх! Щоб виграти битву за Альтерак, ми маємо перемогти їхнього генерала, Ванндара Штормпайка!$B$BВи знайдете Ванндара в Дун-Балдарі, на півночі Долини Альтерака.$B$BЗнищте його, $N, а потім поверніться до мене.",
    O = "Увійдіть до Долини Альтерак і переможіть генерала гномів Ванндара Штормпайка. Потім поверніться до Вогга Смертельного Хвату в Горах Альтерак.",
    P = "Ми не допустимо, щоб карлики оселилися в нашому домі! Накиньтеся на наших ворогів і переможіть їхнього ватажка, генерала Штормпайка!",
    C = "Молодець, $N! У «Штормпіків» немає жодних шансів у цьому безглуздому вторгненні.$B$BХа! Поки що єдине, чого вони досягли, — це загибель свого генерала!",
},

[7161] = {
    en = "Proving Grounds",
    T = "Випробувальні полігони",
    D = "Вітаю, $c. Давно вже ми не мали нагоди відповісти на заклик до бою. Старі почуття прокидаються повільно, але, прокинувшись, кров у жилах закипає. Бойовий запал повертається...$B$BУсі новачки в Долині спочатку повинні пройти бойовий обряд.$B$BГлибоко в печері гнолів Диких Лап знаходиться прапор Морозного Вовка. Рушайте туди й поверніть прапор. Принесіть його мені, і я нагороджу вас знаком новачка Морозного Вовка.",
    O = "Відправляйтеся до печери Вайлдпоу, що розташована на південний схід від головної бази в Долині Альтерак, і знайдіть прапор «Морозних вовків». Поверніть прапор «Морозних вовків» воєначальнику Лаггронду.",
    P = "Прокинься! Прокинься, $N! Це не сон. Ти справді опинився в самому епіцентрі запеклої битви!",
    C = "Те пекуче відчуття, яке ти відчуваєш, — це пробудження твоєї душі. Ваш дух прийняв заклик до зброї.$B$BТепер ви — один із «Морозних Вовків», $N. Вітаю.$B$BЗавжди носіть цю емблему з собою. У міру того, як ти будеш просуватися по службових щаблях «Морозних вовків», я заміню цей знак на інші, більш могутні знаки.$B$BМожливо, одного дня ти здобудеш високе становище в клані «Морозних вовків». Якщо цей день колись настане, тобі буде даровано «Око командування».",
},

[7162] = {
    en = "Proving Grounds",
    T = "Випробувальні полігони",
    D = "Ти прибув якраз вчасно, $c. Ці дикуни з племені «Морозних Вовків» ніяк не хочуть здаватися! Ми мусимо показати їм міць «Штормпіку». Вони мають схилитися перед нашою перевагою.$B$BПерш ніж вирушати на поле бою, тобі слід приєднатися до лав «Штормпіку».$B$BНа південний захід від Дун-Балдара ти знайдеш Печери Крижаного Крила. Глибоко в печерах стоїть прапор «Штормпайка». Рушай туди й віднайди цей прапор. Поверни його мені, і ти отримаєш знак новачка «Штормпайка».",
    O = "Відправляйтеся до печер Айсвінг, розташованих на південний захід від Дун-Балдара в Долині Альтерак, і знайдіть прапор «Штормпайк». Поверніть прапор «Штормпайк» лейтенанту Хаггердіну в горах Альтерак.",
    P = "Остерігайтеся гарпій цього краю, $c. Вони, не задумуючись, розірвуть вам горло!",
    C = "Візьми цю відзнаку та носи її з гордістю, $N. У міру того, як ти підніматимешся по службових сходах у «Штормпайку», відзнака також буде вдосконалюватися. Повертайся до мене, коли здобудеш честь у «Штормпайку», і я заміню твій знак на інші, більш могутні знаки.$B$BМожливо, одного дня ти станеш легендою на цьому полі бою. Якщо цей день колись настане, тобі буде даровано «Око командування».",
},

[7163] = {
    en = "Rise and Be Recognized",
    T = "Зростай і здобувай визнання",
    D = "",
    O = "",
    P = "<Військовий магістр Лагронд вітає тебе.>$B$BНастав твій час, $N. Ти багато зробив для клану «Морозних вовків» і завдяки цьому заслужив місце не лише як воїн «Морозних вовків», а й як друг.$B$BМолодець! Покажи свій знак новачка.$B",
    C = "Ця нова відзнака символізує твоє звання серед «Морозних вовків». Завжди нось її з собою.$B$BІ $C... Помри з честю!",
},

[7164] = {
    en = "Honored Amongst the Clan",
    T = "Визнаний серед клану",
    D = "",
    O = "",
    P = "Радий знову тебе бачити, $C. Я не сподівався, що ти повернешся. На жаль, ти довів, що є хоробрим і чесним воїном «Морозних вовків».$B$BТвій час знову настав, $N. Ти заслужив нове звання, а отже, і нову відзнаку, що символізує це підвищення.$B$BПокажи свою відзнаку.",
    C = "<Військовий магістр Лаггронд віддає честь.>$B$BВперед, $N! Продовжуйте захищати «Морозних вовків». Цю війну треба виграти! За Дрек’Тара! За Вождя!",
},

[7165] = {
    en = "Earned Reverence",
    T = "Заслужена повага",
    D = "",
    O = "",
    P = "Стільки загиблих. Поля залиті кров’ю. Та... Ти вижив... Ти вистояв. Ти привів наші війська до багатьох перемог. Тож за це, солдате, ти заслужив нове звання.$B$BПокажи свої знаки розрізнення.",
    C = "<Військовий магістр Лаггронд реве.>$B$BПро твої подвиги вже почали розповідати, солдате. «Штормпайк» тремтить від страху, щойно згадують твоє ім’я. Продовжуй!",
},

[7166] = {
    en = "Legendary Heroes",
    T = "Легендарні герої",
    D = "",
    O = "",
    P = "Ти випромінюєш владу й силу, $C. Ти шанований у очах «Морозного Вовка» — вороги тремтять від однієї згадки твого імені.$B$BВстань, Герою «Морозного Вовка». Встань і прийми почесті!$B$BПокажи свої знаки розрізнення.",
    C = "Незабаром усе, що відбуватиметься на полі бою, опиниться під вашим пильним наглядом. Командування Долиною та її військами перейде до ваших рук!",
},

[7167] = {
    en = "The Eye of Command",
    T = "«Око командування»",
    D = "",
    O = "",
    P = "Дрек'Тар висловлює тобі похвалу. Калімдор гуде від розповідей про твої подвиги. Верховний вождь сяє від задоволення — твоя відважна оборона нашого клану дуже йому сподобалася.$B$BТи заслужив «Око командування».$B$BПред'яви свій знак розрізнення, командире $N.",
    C = "Скористайтеся силою емблеми. Нехай ворог почує ваші слова. Могутність Орди незаперечна!",
},

[7168] = {
    en = "Rise and Be Recognized",
    T = "Зростай і здобувай визнання",
    D = "",
    O = "",
    P = "Більшість не доживає до того, щоб піднятися над власною посередністю. Ти довів, що є зразковим солдатом, $c. Настав час.$B$BПред’яви свої знаки розрізнення.",
    C = "Нехай наші вороги побачать, що їх знищив солдат високого звання! Биймося за славу Штормпайка!$B",
},

[7169] = {
    en = "Honored Amongst the Guard",
    T = "Визнаний серед гвардії",
    D = "",
    O = "",
    P = "На базі всі обговорюють твої подвиги на Полі Битви! Ти завдав потужних ударів по ворогу, підірвавши його бойовий дух! За це ти заслужив почесне звання серед «Штормпайків».$B$BПокажи свою відзнаку.",
    C = "Король дізнався про твої подвиги на фронті, $c. Продовжуй відважно захищати Гвардію Штормпайка!",
},

[7170] = {
    en = "Earned Reverence",
    T = "Заслужена повага",
    D = "",
    O = "",
    P = "Я мушу знати, $N. Коли ти дивишся прямо в очі ворогу, чи бачиш ти там страх? Чи вони тепер тремтять у твоїй присутності? Вони мають усвідомити, що зазнали поразки!$B$BТи заслужив повагу серед Гвардії.$B$BПокажи свої знаки розрізнення!",
    C = "Коли ми вперше зустрілися, я й гадки не мав, що з тебе вийде герой. Вперед, солдате!",
},

[7171] = {
    en = "Legendary Heroes",
    T = "Легендарні герої",
    D = "",
    O = "",
    P = "Переді мною стоїть видатний герой Альянсу.$B$B<Лейтенант Хаггердін віддає честь.>$B$BМало хто заслужив таке звання серед «Штормпайків». Я бачив, як вороги падали перед тобою. Я бачив, як їхня рішучість розсипалася у вашій присутності. Коли ви вступаєте в бій, ви стаєте променем надії для наших військ!$B$BПокажіть свої знаки розрізнення.",
    C = "Безсумнівно, саме ти станеш носієм «Ока Командування»!",
},

[7172] = {
    en = "The Eye of Command",
    T = "«Око командування»",
    D = "",
    O = "",
    P = "Нехай почують твій голос, Командире $n! Нехай відчують страх. Покажи їм, яку силу має «Штормпайк» у їхніх лавах!$B$BПродемонструй свої знаки розрізнення.$B$B",
    C = "Саме ви повинні привести наші війська до перемоги, командире $n! Солдати перебувають під вашим командуванням. Вони виконуватимуть ваші прямі накази. Очольте їх... Знищіть «Морозного вовка».",
},

[7181] = {
    en = "The Legend of Korrak",
    T = "Легенда про Коррака",
    D = "Загарбники зі «Штормпайка» — не єдина загроза в цьому регіоні, солдате. В Долині війна ведеться на двох фронтах. За владу також борються канібали-тролі з племені «Зимовий сокира».$B$BЇх очолює Коррак Кровожер — жорстока й хитра bestia.$B$BУдар по Корраку може стати нищівним ударом для клану Вінтеракс. Вбий цю bestia і отримай нагороду!",
    O = "Згідно з легендою, ватажок могутніх тролів Вінтеракс з’являється коли забажає, щоб сіяти хаос серед мешканців Долини Альтерак.$B$BЯкщо Коррак дасть про себе знати, знищте його та поверніться до воєначальника Лаггронда.",
    P = "Майте на увазі, солдате, що «Штормпайк» також полює на Коррака.",
    C = "Залишилися лише армії «Штормпайк», які вторглися сюди, солдате. Молодець!",
},

[7201] = {
    en = "The Last Element",
    T = "Останній елемент",
    D = "На тих, хто наважиться заглибитися в глибини, чекає робота, $N.$B$B«Темні Залізні» досконало опанували мистецтво створення надзвичайно потужних големів.$B$BПопередні звіти наших шпигунів свідчать, що карлики використовують унікальне джерело енергії, яке надає їхнім творінням незрівнянну руйнівну силу.$B$BТільки уявіть, на що ми могли б здатні з нашими потворами, якби нам вдалося дістати цю суть стихій! Переверніть це місто з ніг на голову, якщо доведеться, але не повертайтеся, доки не знайдете цю сутність! Винагорода варта ризику.",
    O = "Відправляйся до Глибин Блекрока й знайди 10 одиниць «Есенції стихій». Тобі одразу спадає на думку обшукати големів та їхніх творців. Ти пригадуєш, що Вівіан Лаграв також щось бурмотіла про елементалів.$B",
    P = "Покажи їх мені!",
    C = "Чудово! Я негайно накажу відправити це кур’єром до Підмістя!$B$BА тобі — ось плата, як і обіцяв. Решту собі залиш, ти, брудна тварюко!",
},

[7202] = {
    en = "Korrak the Bloodrager",
    T = "Коррак, Кровожадний",
    D = "Місцеві тролі з племені Вінтеракс — це безжальні дикуни, які понад усе мріють додати наші кістки до свого огидного рагу.$B$BМи мусимо показати їм нашу міць!$B$BМи знайшли у їхніх печерах фоліанти, в яких детально описано їхню ієрархію керівництва. Ці артефакти свідчать, що їхній ватажок, Коррак Кровожадний, зазвичай залишається в тіні, доки не з’явиться привід заявити про себе.$B$BСмерть Коррака означатиме смерть клану Вінтеракс! Вбийте його й поверніться.",
    O = "Згідно з легендою, ватажок могутніх тролів Вінтеракс з’являється коли забажає, щоб сіяти хаос серед мешканців Долини Альтерак.$B$BЯкщо Коррак дасть про себе знати, знищте його та поверніться до лейтенанта Хаггердіна в Горах Альтерак.",
    P = "Будь обережним, солдате: «Морозні вовки» теж полюють на Коррака.",
    C = "Молодці. Тепер, коли Коррак мертвий, ми можемо повністю зосередитися на вигнанні мерзенних «Морозних вовків» з цього регіону.",
},

[7223] = {
    en = "Armor Scraps",
    T = "Уламки броні",
    D = "У Долині Альтерак постійно точаться битви, а запасів, які ми отримуємо з Айронфорджа, не вистачає, щоб екіпірувати наших досвідчених воїнів.$B$BЯкщо ви знайдете уламки обладунків на полі бою, допоможіть у веденні війни та принесіть ці уламки до мене!",
    O = "Принесіть 20 уламків броні Мурготу Глибококузнецю в Дун-Балдарі.",
    P = "Ти приніс якісь уламки обладунків, $N?",
    C = "Це чудові предмети, $N. Я можу використати їх для виготовлення нового спорядження для наших військ.$B$BЯкщо рівень моїх запасів стане достатньо високим, то, можливо, наші досвідчені бойові підрозділи вийдуть на поле бою!",
},

[7224] = {
    en = "Enemy Booty",
    T = "Ворожа здобич",
    D = "Коли будете битися з ворогом, збирайте уламки їхньої броні та приносьте їх мені. Я використаю ці уламки, щоб виготовити броню для наших військ!",
    O = "Принесіть 20 уламків обладунків ковалю Регзару в селищі Морозних Вовків.",
    P = "Як справи з полюванням, $N? Може, у тебе є для мене якісь уламки обладунків?",
    C = "Ці підійдуть якнайкраще. Я їх переплавлю й полагоджу, і ти навіть не здогадаєшся, що вони належали тим боягузам зі «Штормпайка»!$B$BДякую, $N. А я тим часом відполірую твою броню...",
},

[7241] = {
    en = "In Defense of Frostwolf",
    T = "На захист Фроствольфа",
    D = "У далекій країні, $c, лунають барабани війни. Улюблений клан вашого вождя зазнає нападу з боку підступної Гвардії Штормпайк з Айронфорджа.$B$BСудячи з вашого вигляду, я бачу, що ви справді загартовані в боях і готові приєднатися до справи «Морозних Вовків».$B$BСаме вам тепер належить зробити наступний крок у вашому розвитку.$B$BНа північ від Таррен-Мілл, в Альтераку, ти знайдеш вхід до Долини Альтерака. Саме там ти зустрінеш воєначальника Лаггронда. Поспішай $c, адже битва вже на носі!",
    O = "Відправляйтеся до Долини Альтерак, що розташована в горах Альтерак. Знайдіть і поговоріть з воєначальником Лаггроундом, який стоїть біля входу в тунель, щоб розпочати свою кар’єру солдата «Морозного Вовка». Долина Альтерак розташована на північ від Таррен-Мілл, біля підніжжя гір Альтерак.",
    P = "",
    C = "Щоб стати воїном «Морозного Вовка», спочатку треба пройти випробування...",
},

[7261] = {
    en = "The Sovereign Imperative",
    T = "Суверенний імператив",
    D = "Ми ведемо запеклу битву в долинах Альтерака. З одного боку на нас нападають канібалістичні тролі з племені Вінтеракс, а з іншого — дикий клан Морозних Вовків. Обидві сили потрібно знищити в ім’я короля Магні Бронзобородого! Захоплення, очищення та перетворення цієї землі є суверенним і територіальним імперативом для королівства Айронфордж.$B$BНа жаль, солдати не ростуть на деревах! З’явіться до лейтенанта Хаггердіна біля долини Альтерак, щоб розпочати свою службу та здобути честь у лавах «Штормпайк».",
    O = "Відправляйтеся до Долини Альтерак у передгір’ях Хіллсбрада. Біля вхідного тунелю знайдіть лейтенанта Хаггердіна та поговоріть з ним.$B$BЗа славу Бронзобородого!",
    P = "",
    C = "Приступимо до роботи!",
},

[7281] = {
    en = "Brotherly Love",
    T = "Братська любов",
    D = "Трагічно... Мій брат стоїть переді мною на полі бою: командир «Штормпайка».$B$BЗ чотирьох командирів «Штормпайка» він, без сумніву, найнебезпечніший. Можливо, якщо його вбити, Королева Банші зможе навернути його, як вона зробила це зі мною — показати йому, що він помиляється...$B$BГлибоко на ворожій території ти знайдеш мого брата. Вбий його й повернися до мене. Я вірю, що ти здатний виконати це завдання, солдате.$B$BІ, солдате, не йди сам.",
    O = "Відправляйтеся на територію Штормпайк і вбийте командира Карла Філіпса. Після виконання завдання поверніться до командира Луїса Філіпса.$B",
    P = "Як же йому, мабуть, боляче залишатися серед живих, коли його улюблений брат піднявся до досконалості.",
    C = "Твої героїчні вчинки не залишаться непоміченими, $N.$B$BЯ не можу гаяти часу, якщо хочу його врятувати. Треба зв’язатися з Сильваною!",
},

[7282] = {
    en = "Brotherly Love",
    T = "Братська любов",
    D = "Його треба позбавити страждань, солдате! Він не усвідомлює, що робить. Він став бездумним слугою жахливої Королеви Банші.$B$BРушай уперед, через Поле Битви, у глибини території Морозних Вовків. Знайди мого брата і знищ його. Його муки мають закінчитися.",
    O = "Відправляйтеся на територію «Морозних вовків» і вбийте командира Луїса Філіпса. Після виконання завдання поверніться до командира Карла Філіпса.$B",
    P = "З великим сумом я віддаю тобі цей наказ, солдате.",
    C = "Ти ж не забув спалити труп, правда?",
},

[7301] = {
    en = "Fallen Sky Lords",
    T = "Падіння володарів неба",
    D = "Ми взяли їх у полон, $r. Я маю на увазі їхніх командирів ескадрилій. У небі розгорнулася запекла битва, але вони врешті-решт зазнали поразки! На жаль, наших найкращих пілотів збили під час контратаки на фортецю «Фростволф». Ти повинен з’ясувати, що з ними сталося.$B$BОглянь «Тауер-Пойнт-Вест» та фортецю «Фроствулф». Це були їхні останні відомі місця перебування. Ретельно обшукай ці території.",
    O = "Відправляйтеся на територію Фроствольфів і знайдіть командирів ескадрилій Слідора, Віпора та Ічмана. Після виконання місії поверніться до командира Даффі.",
    P = "Є щось, про що я хотів би почути?",
    C = "Неймовірно! Ти ж їх звільнив, правда? Правда??? Ну, принаймні ми знаємо, де їх утримували.",
},

[7302] = {
    en = "Fallen Sky Lords",
    T = "Падіння володарів неба",
    D = "Наша повітряна підтримка в жалюгідному стані, $N. Командири ескадрилій були збиті над територією ворога. Ти повинен з’ясувати, що з ними сталося, щоб ми могли спробувати їх врятувати!$B$BГузе востаннє бачили, коли він пролітав над бункером «Айсвінг». «Військовий вершник» Джезтора було помічено поблизу лісопильні «Штормпайк». Мулверік… того безрозсудного дурня бачили, як він розбився поблизу північного бункера «Дун’Балдар».$B$BЦе вся інформація, якою я володію. Вирушайте! Ретельно обшукайте ці райони.",
    O = "Дізнайтеся, що сталося з командирами ескадрильї Гузе, Джезтором і Мулверіком. Після виконання місії поверніться до командира Мулфорта.",
    P = "Як йдуть полювання, солдате?",
    C = "Молодець! Інформація, яку ти відновив, стане безцінною для нашої справи.",
},

[7321] = {
    en = "Soothing Turtle Bisque",
    T = "Заспокійливий суп-біск із черепахи",
    D = "Хто сказав, що немертві нічого не розуміють у кулінарії? Візьміть, наприклад, мій секретний рецепт черепахового біску. Я знав людей, які повернулися б із мертвих лише заради того, щоб скуштувати миску цього супу! Хе-хе...$B$BДо речі, останнім часом я не мав можливості його приготувати. Раніше я сам ходив до озера Лордамере полювати на «щелепозубів» — отих огидних тварюк, але тепер не можу відірватися від роботи тут.$B$BЯкщо принесеш мені трохи черепашачого м’яса від «щелепозубів» і заспокійливих спецій, я покажу тобі, як це робиться!",
    O = "Принесіть 10 шматків м’яса черепахи та трохи заспокійливих спецій Крістофу Джеффкоуту в Таррен-Міллі.",
    P = "Вдалося знайти інгредієнти? Скажу тобі, цих альянсних черв'яків у цій місцевості зараз занадто багато... На мою думку, вони вже підібралися надто близько...",
    C = "Мій заспокійливий черепаховий суп зігріє вас холодної ночі... якщо ви, звісно, приділяєте цьому увагу.",
},

[7341] = {
    en = "A Fair Trade",
    T = "Справедлива торгівля",
    D = "",
    O = "",
    P = "Вітаю, $r. Я — Коларк, мисливець за головами з Громового Уступу. Я обмандрував значну частину світу й бачив багато чого.$B$BМої подорожі Південними морями привели до відкриття цих дивовижних стріл із торієвими наконечниками. На жаль, у мене є нескінченний запас стріл, але запас снарядів вичерпався. Ба, жоден таурен, що поважає себе, нізащо не став би користуватися таким кволим луком. Ці стріли ні на що не придатні!$B$BПропоную обмін: рівноцінний обмін торієвих снарядів на мої стріли з торієвими наконечниками. Згодні?",
    C = "Чудово! Я — таурен, який дотримується свого слова, $r. Стріли — твої.",
},

[7342] = {
    en = "Arrows Are For Sissies",
    T = "Стрілки — це для слабаків",
    D = "",
    O = "",
    P = "Ти можеш повірити в цю нісенітницю?! Остання партія боєприпасів із Хараноса виявилася зіпсованою! Тепер у нас як боєприпаси залишилися лише ці кволі, ні на що не придатні стріли! Що ж мені тепер робити з 500 000 стріл із торієвими наконечниками?$B$BОсь що я тобі скажу, хлопче. Якщо ти принесеш мені торієві снаряди, я обміняю їх на стріли з торієвими наконечниками — чесно! Домовилися?",
    C = "Це ж стовідсоткова угода! Стріли — твої.",
},

[7361] = {
    en = "Favor Amongst the Darkspear",
    T = "Прихильність серед Темних Списів",
    D = "<Наджак ричить.>$B$BЩе до появи нічних ельфів існували тролі. Саме від тролів походять нічні ельфи.$B$BЇхні бунтівні напади на мій народ не будуть терпітися. Стагхельм прагне знищити нас — не залишити жодного сліду від тих, хто народив його та його поплічників. Цього не станеться!$B$BЗа кожного нічного ельфа, якого ти вб’єш і обезголовиш, Наджак нагородить тебе прихильністю серед Темних Списів. Звістка про ваші подвиги рознесеться по всьому Калімдору та Східним Королівствам. Ідіть же й служіть «Темним Списам»!",
    O = "Вам доручено вбити гравців-нічних ельфів супротивника в Долині Альтерак.$B$BВбийте нічного ельфа та поверніться до Наджака Гексена в фортеці «Морозний Вовк» із відрубаною головою нічного ельфа.",
    P = "Вони прагнуть нас знищити? Це саме їх буде знищено.",
    C = "$N — це лише одна з тисяч. Проте робота виконана на високому рівні.",
},

[7362] = {
    en = "Ally of the Tauren",
    T = "Союзник тауренів",
    D = "Стара Відьма відправила мене на цю зону бойових дій, щоб я дослідив інші раси. А точніше, я маю зібрати зразки гномів. Магату насамперед цікавить їхня здатність до виживання. Так, гноми — хоч і жалюгідно слабкі та крихітні — виявляють надзвичайну стійкість як у бою, так і поза ним.$B$BНа щастя для вас, я шукаю хуліганів, які виконуватимуть доручення Магати. Поверніться до мене з жмутками гномівського волосся, і таурени визнають вас своїм союзником.",
    O = "Вам доручено вбити гравців-гномів супротивника в Долині Альтерак.$B$BВбийте гнома та поверніться до Равака Грімтотема у фортеці Морозних Вовків із пучком волосся гнома.",
    P = "Мені байдуже, звідки це волосся, $R.",
    C = "Так, це точно гном. Молодець, $R, але попереду ще багато роботи.",
},

[7363] = {
    en = "The Human Condition",
    T = "Людська доля",
    D = "Люди — такі огидні істоти.$B$B<Командир Філіпс кривить обличчя.>$B$BХоча я й справді є воїном «Морозного Вовка», я залишаюся слугою Сильвани.$B$BПід час служби я виконую додаткову роботу на стороні для Темних аптекарів Підміста.$B$BМені доручено збирати уламки людських кісток, які мають бути використані для лікування людських недуг.$B$BЯ уповноважений передавати це завдання своїм підлеглим.$B$BЗнайдіть їх. Вбийте їх. Принесіть мені їхні уламки кісток.",
    O = "Вам доручено вбити супротивників-людей у Долині Альтерак.$B$BВбийте людину та поверніться до командира Луїса Філіпса (який пересувається між лініями фронту та фортецею «Морозний вовк») із уламком людської кістки.$B$BЛіки від людської хвороби вже зовсім близько!",
    P = "Так, це правда. Мій брат — людина. Ганебно... Пляма на моїй майже бездоганній репутації.",
    C = "Було б простіше, якби вони просто змирилися зі своєю хворобою і піддалися твоїм цілющим дотикам. Хоча, мабуть, це було б не так цікаво. Продовжуй! Ми їх вилікуємо — так чи інакше.",
},

[7364] = {
    en = "Gnomeregan Bounty",
    T = "Завдання «Гномереган»",
    D = "Сам Великий Майстер відправив мене на це поле бою, щоб я захистив своїх братів і сестер-гномів. До нас надійшла звістка, що таурени виокремлюють гномів і вбивають їх. Найгірше те, що вони зривають пасма славного гномівського волосся з тіл полеглих. Ці звірства треба зупинити. Ми мусимо відповісти тим самим!$B$BЯ хочу, щоб їх позбавили копит, $c. Принесіть мені їхні копита! Проявіть себе союзником гномів.",
    O = "Вам доручено вбити гравців-тауренів супротивника в Долині Альтерак.$B$BВбийте таурена і поверніться до Дірка Свіндла в Дун’Балдарі з копитом таурена.",
    P = "Дай їм прочуханки, $N. Вони мають зрозуміти, що гноми не терпітимуть, коли їх принижують!",
    C = "*Дірк кидає копито у купу за собою.*",
},

[7365] = {
    en = "Staghelm's Requiem",
    T = "«Реквієм» Стагхельма",
    D = "Стагхельм віддав наказ. Усі тролі на полі бою мають бути знищені. На їхні безглузді твердження про те, що вони породили нічних ельфів, слід відповісти силою та належною упередженістю.$B$BВбийте їх і поверніться до мене з їхнім моджо. Повторюю: я хочу, щоб ви вкрали їхнє моджо.",
    O = "Вам доручено знищити ворожих гравців-тролів у Долині Альтерак.$B$BЗнищіть троля та поверніться до Атраманіса в Дун’Балдарі з предметом «Магія тролів Темного Списа».",
    P = "Я досі відчуваю сморід від цих смердючих тролів.",
    C = "Дякую, $N. Повітря стало трохи чистішим.",
},

[7366] = {
    en = "The Archbishop's Mercy",
    T = "Милосердя архієпископа",
    D = "Архієпископ настільки ж добрий, наскільки й мудрий. Щоб людина могла з милосердям дивитися на таку жалюгідну долю...$B$B<Командир Філіпс з недовірою хитає головою.>$B$BЗанадто добрий... Просто надто добрий.$B$BАрхієпископ просить нас змилосердитися над неживими та подарувати їм швидку й остаточну смерть. За цей величний прояв милосердя ми вимагаємо лише їхні чорні, сповнені хвороб серця.$B$BПринесіть мені серця Покинутих, щоб їх можна було урочисто спалити в Соборі Світла. Поспішайте, $N!",
    O = "Вам доручено вбити гравців-«Покинутих» у Долині Альтерак.$B$BВбийте одного з «Покинутих» і поверніться до командира Карла Філіпса (який бродить між лісопилкою та шахтою) із серцем «Покинутого».",
    P = "Бенедиктус! Я — лише пилинка в тіні його величі. Слава йому!",
    C = "Слава Бенедиктусу! Ще одна загублена душа, яку незабаром врятують розпечені полум’я Світла!$B$BІди, о воїне Світла! Треба врятувати ще більше душ!",
},

[7367] = {
    en = "Defusing the Threat",
    T = "Нейтралізація загрози",
    D = "«Фростволфи» встановили на своїх передових лініях та базах міни-пастки, $c. Вам слід бути обережними під час вторгнення на ворожу територію.$B$BЯкщо ви хочете завдати їм серйозного удару, вам необхідно знищити джерело їхніх протипіхотних боєприпасів — я маю на увазі їхнього фахівця з вибухових речовин. Якщо ви його вб’єте, ви зможете безпечно знешкодити міни. Поки він недієздатний, міни також залишатимуться неактивними.$B$BВи, ймовірно, знайдете його у вежі поблизу гарнізону «Крижана кров». Удачі!",
    O = "Знайдіть експерта з вибухових речовин з клану «Фростволф» і вбийте його. Після виконання завдання поверніться до експерта з вибухових речовин з клану «Стормпайк».",
    P = "",
    C = "",
},

[7368] = {
    en = "Defusing the Threat",
    T = "Нейтралізація загрози",
    D = "Я все знаю про наземні міни. Адже саме я встановлюю всі міни на лінії фронту тут.$B$BЯкщо ти хочеш знешкодити мінні поля «Штормпайка», тобі потрібно лише вбити їхнього сапера. Цей карликовий боягуз, без сумніву, ховається в першій вежі на Полі Сутички. Знешкодьте його, і ці наземні міни більше не спрацюють після знешкодження.$B$BЯкщо вам все-таки вдасться його вбити, поверніться сюди й повідомте мені. Жодна добра справа не повинна залишатися без нагороди.",
    O = "Знайдіть експерта зі вибухових речовин «Штормпайк» і вбийте його. Після виконання завдання поверніться до експерта зі вибухових речовин «Морозного Вовка».",
    P = "",
    C = "",
},

[7381] = {
    en = "The Return of Korrak",
    T = "Повернення Коррака",
    D = "Хоча Коррак і справді загинув, залишається одне питання: чи залишиться він мертвим? Тролі відомі своєю надприродною племінною магією. Я не здивувався б, якби полеглого вождя воскресили з мертвих, щоб він знову правив своїм кланом.$B$BВи знаєте, що робити, якщо таке колись трапиться.$B$B<Військовий командир Лагронд робить вказівним пальцем жест, ніби перерізаючи собі горло.>$B$BІ цього разу я хочу його череп. Просто пильнуй, солдате.$B$BВільний!",
    O = "Якщо Коррак Кровожадний повернеться на Кладовище Снігопаду, знайдіть його та знищіть.$B$BПоверніть Череп Коррака воєначальнику Лаггронду в Передгір’ях Хіллсбрада.",
    P = "Ти вже вбив Коррака Кровожерця, $c? Розвідники повідомили, що він перебуває десь поблизу Кладовища Снігопаду.",
    C = "Молодець, $n. Навіть найпотужніша магія вже не зможе воскресити Коррака. Ти знищив одну з головних загроз у Долині Альтерак, солдате.",
},

[7382] = {
    en = "Korrak the Everliving",
    T = "Коррак Вічноживий",
    D = "У всьому цьому є щось не так... Хтось подумав спалити труп Коррака? Ці тролі не зупиняться ні перед чим, аби воскресити свого полеглого ватажка — як це часто роблять синьошкірі язичницькі люди-звірі.$B$BПросто будьте пильні, $N. Не лякайтеся, якщо Коррак раптово з’явиться; а якщо це станеться, я хочу, щоб його стратили — а його труп спалили до попелу.$B$BДля впевненості відрубайте йому голову й принесіть мені його череп, перш ніж підпалити безживне тіло.",
    O = "Якщо Коррак Кровожадний повернеться на Кладовище Снігопаду, знайдіть його та знищіть.$B$BПоверніть Череп Коррака лейтенанту Хаггердіну в Підгір’ях Хіллсбрада.",
    P = "Ти вже вбив Коррака Кровожадного, $c? Розвідники повідомили, що він перебуває десь поблизу Кладовища Снігопаду.",
    C = "Молодець, $n. Навіть наймогутніша магія не змогла б тепер воскресити Коррака. Ти знищив серйозну загрозу для Долини Альтерак, солдате.",
},

[7383] = {
    en = "Crown of the Earth",
    T = "Корона Землі",
    D = "Однак у Телдрасілі не все було гаразд. Ретельно розроблені Стагхельмом плани щодо нового Світового Дерева здійснилися так, як він і сподівався, але була одна невеличка проблема — проблема, з якою можна пов’язати багато неприємностей, що сталися на Телдрасілі.$B$BПроте я поки що не буду про це розповідати. Тобі слід відвідати останню місячну криницю, що розташована на північному заході, у Гаї Оракула. Під гілками Дерева Оракула лежить перша й найпотужніша з наших криниць. Візьми флакон із її водою й повернися до мене.",
    O = "Наповніть флакон «Аметист» і поверніть його Корітрасу Мунрейджу в Доланаарі.",
    P = "Разом із друїдами Дерево Оракула та Верховний друїд ретельно стежили за ростом Телдрасіля. Але хоча ми й маємо новий дім, наші безсмертні життя так і не були відновлені.",
    C = "Перебувати в присутності Дерева Оракула… це майже як відчути, як мудрість набуває форми. Дозвольте мені продовжити розповідь…$B$BКоли Телдрасіл виріс, Архідруїд звернувся до драконів по їхнє благословення, як це колись у давні часи зробили дракони щодо Нордрасіла. Але Ноздорму, Володар Часу, відмовився дати своє благословення, дорікнувши друїду за його зарозумілість. Погодившись із Ноздорму, Алекстраза також відмовила Стагхельму, і без її благословення ріст Телдрасіла був неповноцінним і непередбачуваним...",
},

[7385] = {
    en = "A Gallon of Blood",
    T = "Галон крові",
    D = "У вас є можливість принести в жертву більшу кількість крові, взятої у наших ворогів. Я з радістю прийму жертви об’ємом у галон, $N.",
    O = "null",
    P = "Ти повинен знищити наших ворогів і принести мені їхню кров.",
    C = "Кров наших ворогів пролита. Я змішаю цю кров з рештою, яку вже зібрали. Як тільки жертвопринесення завершиться, Володар Льоду покаже цим псам із «Штормпайка» весь гнів клану «Морозних Вовків»!",
},

[7386] = {
    en = "Crystal Cluster",
    T = "Кристалічний кластер",
    D = "Бувають випадки, коли ви можете опинитися в епіцентрі боїв протягом кількох днів або навіть тижнів поспіль. Під час таких тривалих періодів бойових дій у вас можуть накопичитися великі скупчення кристалів бурі «Морозного вовка».$B$B«Коло» приймає такі дари, $N.",
    O = "null",
    P = "Солдати «Морозних вовків» носять з собою магічні амулети, які називаються «кристалами бурі». За допомогою цих амулетів ми можемо викликати Івуса. Рушай у дорогу й здобуй ці кристали, $N!",
    C = "Молодець, $N. Я використаю силу цих амулетів, щоб посилити магію, яка вже була зібрана. Коли буде накопичено достатньо сили, я сконцентрую зібрані енергії та звернуся до Володаря Лісу з проханням допомогти нашій справі.",
},

[7401] = {
    en = "Wanted: DWARVES!",
    T = "Потрібні: КАРЛИКИ!",
    D = "За наказом сержанта Язри Бладснарл усіх гномів на полі бою слід вбивати без попередження.$B$BЯкщо ви вб’єте гнома в бою, вирвіть йому хребет, залишивши безхребетну купу смороду та гнилі, щоб це послужило попередженням усім, хто наважиться протистояти могутності «Морозних вовків».$B$BПоверніться до сержанта Язри Кров'яного Шерстяного з доказом ваших героїчних подвигів.",
    O = "Вам доручено вбити гравців-гномів супротивника в Долині Альтерак.$B$BВбийте гнома та вирвіть йому хребет. Віднесіть хребет гнома сержанту Язрі Кров’яному в фортецю Морозних Вовків.",
    P = "Я торгую іронією оптом, солдате.",
    C = "Тепер у тебе є дозвіл винищувати гномів десятками, $C!$B$B<Язра на мить задумливо дивиться вдалину.>$B$BСвоє перше «розшпилювання» ніколи не забудеш...",
},

[7402] = {
    en = "Wanted: ORCS!",
    T = "Потрібні: ОРКИ!",
    D = "Згідно з наказом капрала Норега Стормпайка, усі боєздатні солдати Стормпайка зобов’язані вбивати всіх ворожих орків, яких вони зустрінуть на полі бою.$B$BСолдати зобов’язані вирвати бивень або зуб із пащі ворога та пред’явити цей зуб як доказ свого подвигу.$B$BНосіть захисні рукавички.",
    O = "Вам доручено знищити гравців-орків у Долині Альтерак.$B$BЗнищіть орка та поверніть його зуб капралу Норегу Штормпайку в Дун-Балдарі.",
    P = "Щоб вирвати зуби, потрібна затискачка?",
    C = "Добре, $N. Я чекаю на цих маленьких мишок.",
},

