[7429] = {
    en = "Free Knot!",
    T = "«Free Knot»!",
    D = "",
    O = "",
    P = "Вона називається «Ключ від кайданів Гордока» — ну, принаймні так її постійно називають ці «веселуни». Гадаю, вона може бути у будь-якого з огрів, але не впевнений, чи є вона саме у когось конкретного. Можливо, у охоронців більше шансів її знайти...$B$BТа про що я взагалі говорю — у тебе він же вже є, чи не так?! Це він там??!",
    C = "О, дякую, що визволили мене! Ти — номер один. Усі інші — на другому місці або нижче.$B$BЯ знала, що моє життя призначене для чогось більшого, ніж просто стати закускою для якогось людожера!",
},

[7441] = {
    en = "Pusillin and the Elder Azj'Tordin",
    T = "Пусіллін і Старший Аз'Тордін",
    D = "Я втратив пильність лише на мить, незнайомцю. У поспіху, намагаючись вирватися з лап занепалого Принца, мене пограбували. Найогидніший з демонів, імп Пусіллін, викрав мою книгу заклинань і ключ до колись величних залів Елдре’Таласа.$B$BКлюч мене більше не цікавить, адже я обміняв своє безсмертя на свободу, але мені вкрай потрібна моя книга заклинань.$B$BЗнайди імпа Пусілліна й поверни мою книгу.$B$BШукайте Пусілліна у кварталі Варпвуд у Діре-Маулі.",
    O = "Відправляйтеся до Діре-Маула та знайдіть імпа Пусілліна. Переконайте Пусілліна віддати вам «Книгу заклинань Аз’Тордіна» будь-якими необхідними засобами.$B$BЯкщо вам вдасться дістати «Книгу заклинань», поверніться до Аз’Тордіна в павільйоні Ларісс у Фераласі.",
    P = "Я ні про що не шкодую, незнайомцю. Королева вже давно померла. Твори Шен’Дралар були зіпсовані божевіллям принца Тортхельдріна. Я прагну лише свободи… Втечі…",
    C = "Ти знайшов це! Нехай прокляття впаде на того жалюгідного бешкетника. На жаль, мої матеріальні статки, м’яко кажучи, мізерні. Ти можеш вибрати щось із того, що я можу запропонувати.",
},

[7461] = {
    en = "The Madness Within",
    T = "Внутрішнє божевілля",
    D = "Ви вже наслухалися? Ви — $g чоловік:жінка; людина дії?$B$BЦьому божевіллю треба покласти край. Епоха безсмертних давно минула. Знищте охоронців, що оточують пілони, щоб ослабити силове поле. Коли це буде зроблено, знищте Іммол'тара. Коли сила Принца значно ослабне, атакуйте його й покінчіть з ним. Дайте спокій душам цього міста, мандрівнику.",
    O = "Ви повинні знищити охоронців, що оточують 5 пілонів, які забезпечують енергією В’язницю Іммол’тара. Як тільки пілони вимкнуться, силове поле, що оточує Іммол’тара, зникне.$B$BУвійдіть до в'язниці Іммол'тара та знищіть огидного демона, що стоїть у її самому серці. Нарешті, зіткніться з принцом Тортхельдріном в Атенеумі.$B$BПоверніться до Стародавнього Шен'дралара у внутрішньому дворику, якщо ви виконаєте це завдання.",
    P = "Будь обережним, мандрівнику. Принц... вміє переконувати.",
    C = "Ми дякуємо тобі, герою.",
},

[7462] = {
    en = "The Treasure of the Shen'dralar",
    T = "Скарб Шендралара",
    D = "У бібліотеці «Атенеум» ви знайдете стародавній скриню, заховану під сходами. Візьміть звідти те, що забажаєте.",
    O = "Поверніться до Атенеуму та знайдіть Скарб Шен'дралара. Отримайте свою нагороду!",
    P = "",
    C = "Ти відкриваєш скриню і бачиш...",
},

[7463] = {
    en = "Arcane Refreshment",
    T = "Таємне відновлення",
    D = "Маг рівня $r! Як дивно. Я не бачив нікого з вашого роду вже... о, що це там зараз відбувається? 500 років!$B$BУ мене є дещо, що втамує вашу спрагу, але спершу ви маєте виконати для мене одне завдання.$B$B<Лідрос хихикає.>$B$BВ Елдре’Таласі сталася аномалія. У східному крилі оселився водяний елементаль. Його присутність треба зафіксувати!$B$BВідправляйся до кварталу Варпвуд і витягни частину елементальної сутності Гідроспоуна. Принеси її мені, і я навчу тебе корисному заклинанню.",
    O = "Відправляйтеся до кварталу Варпвуд у Діре-Маулі та знищіть водяного елементаля Гідросповна. Поверніться до Хранителя знань Лідроса в Атенеумі з есенцією Гідросповна.",
    P = "Так? Я вас знаю?",
    C = "Чудово! А хто ти, нагадай ще раз? Та не має значення. Що я мав тобі дати? Гм... ну, ти ж маг, тож, можливо, це тобі знадобиться.",
},

[7478] = {
    en = "Libram of Rapidity",
    T = "Книга швидкості",
    D = "Майстер Вінталус загубив «Лібрам швидкості» у східному крилі. Цей Лібрам дозволить накласти на ваше спорядження невелике заклинання прискорення. Такі собі фокуси, чесно кажучи...$B$BУ будь-якому разі, якщо ви зацікавлені, вам доведеться пред’явити Лібрам разом із деякими базовими реагентами.$B$BГм... Гадаю, ще знадобиться кров героїв, незайманий чорний діамант і великі блискучі осколки. Можу й помилятися!$B$B<Лідрос знизує плечима.>",
    O = "Принесіть «Лібрам швидкості», 1 «Незайманий чорний діамант», 2 «Великі блискучі осколки» та 2 «Кров героїв» до Хранителя знань Лідроса в Дайр-Маулі, щоб отримати «Арканум швидкості».",
    P = "Що це таке? Мені треба ще багато чого каталогізувати!",
    C = "<Лідрос позіхає.>$B$BЯк і обіцяв, «Арканум швидкості». Не витрачай його весь в одному місці.$B$B<Лідрос хихикає.>",
},

[7479] = {
    en = "Libram of Focus",
    T = "Книга зосередженості",
    D = "Цей лібрам ледь не привернув увагу одного з молодших фамільярів Хранителя Знань. Бідолаха, йому було всього кілька тижнів.$B$BТим із вас, хто має більший хист до магії, цей предмет може здатися цікавим.$B$B«Лібрам зосередження» загубився в цьому крилі. Можу лише припустити, що його має в своєму володінні один із духів Високородних.$B$BПринесіть «Лібрам» разом із кількома великими блискучими осколками, шкірою тіні та бездоганним чорним діамантом, і я викличу Арканум.",
    O = "Принесіть «Лібрам зосередженості», 1 «Незайманий чорний діамант», 4 «Великі блискучі осколки» та 2 «Шкіри тіні» до Хранителя знань Лідроса в Діре-Маулі, щоб отримати «Арканум зосередженості».",
    P = "Знову ти? Що тобі ще може знадобитися?",
    C = "Не поранься під час накладання чар, $R.",
},

[7480] = {
    en = "Libram of Protection",
    T = "Книга захисту",
    D = "Він плакав, як немовля, через втрату цієї книги. Зрозумійте, я сам плакав через втрату текстів — немає більшої втрати, ніж втрата знань та історії, — але плакати через цей майже марний набір заклинань? Абсурд! Це змусило мене подумати, що Принц зробив йому ласку, здираючи шкіру з його кісток.$B$BПринесіть Лібрам разом із незайманим чорним діамантом, великими блискучими осколками та пошарпаним швом огиди, і я відтворю Арканум.$B$BО, і перевірте північне крило.",
    O = "Принесіть «Лібрам захисту», 1 «Незайманий чорний діамант», 2 «Великі блискучі осколки» та 1 «Пошарпану нитку потвори» до Хранителя знань Лідроса в Дайр-Маулі, щоб отримати «Арканум захисту».",
    P = "Моє терпіння запобігає твоїм стражданням.",
    C = "Так, так... Заспокойся. Як і обіцяв, ось твоє «Арканум».",
},

[7481] = {
    en = "Elven Legends",
    T = "Легенди ельфів",
    D = "Кілька років тому самотній ельфійський майстер на ім’я Каріель Вінталус втік від руйнувань на своїй батьківщині, взявши з собою кілька стародавніх ельфійських артефактів.$B$BНаші пошуки цього зниклого майстра привели нас від руїн Квель-Таласа, через Палаючі степи, через великі простори моря, аж до Фераласа.$B$BМи підозрюємо, що ельф шукав притулку в залах Елдре'Таласа (яке зараз відоме як Діре Маул).$B$BТи повинен знайти його, мандрівнику. Живий він чи мертвий — знання, які він мав, необхідно повернути!",
    O = "Знайдіть у «Діре Маул» Каріеля Вінталуса. Поверніться до мудреця Королуска в таборі Моджаче та повідомте йому всю інформацію, яку вам вдасться зібрати.",
    P = "Моя колега, вчена з народу нічних ельфів, Рунетхорн, набирає союзників для виконання цього завдання.",
    C = "Шкода… справжня трагедія. Кажеш, речі загубилися? Ніяких слідів про нього, так?",
},

[7482] = {
    en = "Elven Legends",
    T = "Легенди ельфів",
    D = "Кілька років тому самотній ельфійський майстер на ім’я Каріель Вінталус втік від руйнувань на своїй батьківщині, взявши з собою кілька стародавніх ельфійських артефактів.$B$BНаші пошуки цього зниклого майстра привели нас від руїн Кве'Таласа, через Палаючі степи, через великі простори моря, аж до Фераласа.$B$BМи підозрюємо, що ельф шукав притулку в залах Елдре'Таласа (яке зараз відоме як Дайр-Маул).$B$BТи мусиш знайти його, мандрівнику. Живий він чи мертвий — знання, які він мав, потрібно повернути!",
    O = "Знайдіть у «Діре Маул» Каріеля Вінталуса. Поверніться до вченого Рунетхорна у Фетермуні та повідомте йому всю інформацію, яку вам вдасться зібрати.",
    P = "Мій соратник, мудрець-таурен Королуск, набирає союзників для виконання цього завдання.",
    C = "Шкода… справжня трагедія. Кажете, речі загубилися? Ніяких слідів його, так?",
},

