[7486] = {
    en = "A Hero's Reward",
    T = "Нагорода героя",
    D = "$N, ваші заслуги перед Воєначальниками перевершили всі наші очікування щодо мешканців цього світу.$B$BМи не розуміємо, як ваш народ розуміє поняття вдячності чи винагороди за добрі вчинки, але в цьому випадку... можливо, винагорода є виправданою.$B$BПід хвилями біля південного краю цього острова ти знайдеш скриню. У ній ти знайдеш свою... винагороду.$B$BІди, $N. Отримай свою винагороду.",
    O = "Отримайте свою нагороду зі скрині Гідраксіса.",
    P = "",
    C = "Голос Гідраксиса лунає з-під поверхні води...$B$B«Обери те, що тобі найбільше підходить, $N. Нехай це захистить тебе від ворогів Володарів Води».",
},

[7487] = {
    en = "Attunement to the Core",
    T = "Гармонізація з внутрішньою сутністю",
    D = "Навколо нас розриви з’являються, розширюються й руйнуються, $r. Усього за два кроки від того місця, де я стою, є розрив, що веде крізь глибини Чорноскельної гори, у пащу Володаря Вогню.$B$BЗдивовані? Шкода... Смертні раси не можуть осягнути те, чого не можуть побачити, торкнутися чи відчути.$B$BЗапевняю вас, портал існує, і потрапити туди можна.$B$BЯ зацікавив вас? Налаштування — це просто. Відправтеся в Глибини Чорної Скелі й знайдіть фрагмент ядра. Принесіть його мені, і я налаштую вашу сутність на портал.",
    O = "Відправляйтеся до вхідного порталу «Розплавлене ядро» у «Глибинах Чорної скелі» та знайдіть фрагмент ядра. Поверніться до Лотоса Рифтвейкера в «Горі Чорної скелі», коли знайдете фрагмент ядра.",
    P = "Перш ніж отримати доступ, ви повинні гармонізувати свою душу з «Розплавленим ядром».",
    C = "Тепер я можу перенести вас до Розплавленого Ядра. Скажіть лише слово — і все буде зроблено.",
},

[7488] = {
    en = "Lethtendris's Web",
    T = "Веб-сайт Lethtendris",
    D = "Маг Летхендріс — жорстока кровна ельфійка, чия жорстокість поступається лише її збоченій залежності від магії, — втекла до Діре-Маула. Вона створила пристрій — павутину, що уловлює магічну енергію цього місця, і ми побоюємося, що, якщо її не зупинити, вона завдасть непоправної шкоди нашому світу!$B$BЗупини її, $N. Знайди її та відбери її павутину. Ймовірно, вона перебуває поблизу сатирів у кварталі Варпвуд у Діре-Маулі. Принеси павутину до мене, щоб її силу можна було безпечно випустити назад у дику природу...",
    O = "Принесіть «Павутину Летхендріса» Латронікусу Місячному Спису в фортецю «Пір’яний Місяць» у Фераласі.",
    P = "У тебе є павутина, $N? Її сконцентровану магічну енергію треба розсіяти!",
    C = "Ти відновив Павутину! Молодець, $N! Летендріс, як і багато ельфів її роду, не бачить небезпеки, яку зловживання магією може становити для нашого світу. Вони вважають себе володарями магії; вони не усвідомлюють, що є рабами власної залежності. Її смерть засмучує мене, але це було необхідно.$B$BДякую, $N. Я подбаю про те, щоб енергія, що міститься в павутині, безпечно вивільнилася на великій території, а потім знищу її, щоб запобігти майбутнім зловживанням магією.",
},

[7489] = {
    en = "Lethtendris's Web",
    T = "Веб-сайт Lethtendris",
    D = "Кровна ельфійка Леттендріс переступила межу. Вона так прагнула зібрати магічну силу, що пішла проти волі своїх побратимів і створила підступний пристрій — павутину, призначену для висмоктування спотвореної магічної енергії Діре Маула. Навіть зараз вона збирає цю енергію і планує спрямувати її проти своїх ворогів.$B$BЛеттендріс треба зупинити. Знайдіть її у кварталі Варпвуд у Діре-Маулі, переможіть її та принесіть мені її павутину, щоб її можна було передати більш розсудливим кровним ельфам для дослідження.",
    O = "Принесіть «Павутину Летхендріса» Тало Торнхуфу в табір Моджаче у Фераласі.",
    P = "$N, у тебе є «Павутина Летхендріса»?",
    C = "Ти добре впорався, $N. Ця павутина містить у собі величезні запаси магії Діре-Маула, і я побоююся, які руйнівні наслідки можуть настати, якщо ці енергії потраплять до рук такої безвідповідальної особи, як Летхендріс. Я сумую через її смерть, але знаю, що за життя вона ніколи не змогла б розлучитися зі своєю павутиною.$B$BДякую, $N. Я надішлю павутину учням магії, які є відповідальнішими за Леттендріс. Вони стануть новими охоронцями її сили.",
},

[7490] = {
    en = "Victory for the Horde",
    T = "Перемога Орди",
    D = "Ти здійснив неможливе. Мати-засновниця Чорного драконячого полку лежить мертвою у тебе під ногами. Візьми її голову й принеси її своєму вождю.",
    O = "Віднесіть голову Оніксії до Тралла в Оргримарі.",
    P = "<Стоїчна поведінка Тралла на мить змінилася, коли він побачив величезну голову Оніксії. Могутній «Молот Долі» ледь не вискочив із піхв.>",
    C = "Це велика перемога для Орди, $N. Ти вже стільки разів прославляв свого Вождя. Настав час Вождю віддячити тобі.",
},

[7491] = {
    en = "For All To See",
    T = "На загальний огляд",
    D = "Верховний володар Рунтхак чекає на тебе в Долині Сили.$B$B<Трал вітає тебе.>$B$BНе змушуй людей чекати, герою.",
    O = "Знайдіть повелителя Рунтака в Долині Сили.",
    P = "",
    C = "Оберіть свою нагороду — і нехай розпочнеться святкування вашої славетної перемоги.",
},

[7492] = {
    en = "Camp Mojache",
    T = "Табір Мохаче",
    D = "Тало Торнхуф, старійшина тауренів у Фераласі, надсилає прохання про допомогу. Він не надав багато подробиць, але зазначив, що йому потрібні агенти для вирішення справи, яка є водночас делікатною… і надзвичайно важливою.$B$BСлужи Орді, $N. Відправись до табору Моджаче у Фераласі та поговори з Тало.",
    O = "Поговоріть із Тало Торнхуфом у таборі Моджаче в Фераласі.",
    P = "",
    C = "Ах, як приємно бачити, що $C відгукнувся на мій заклик. Мені потрібна твоя допомога, $N, і я побоююся, що вона заведе тебе на небезпечний шлях...$B$BШлях до Діре-Маула.",
},

[7493] = {
    en = "The Journey Has Just Begun",
    T = "Подорож тільки-но розпочалася",
    D = "",
    O = "",
    P = "",
    C = "Вбивця драконів і досвідчений шкіряник? Ти не перестаєш мене дивувати, герою. Я вражений.$B$BБудь ласка, прийми те, чого я тебе зараз навчу. Ці знання стануть безцінними, якщо ти збираєшся знищити те, що залишилося від Чорного драконячого полку.$B$BСтвори плащ із луски матері-матки. Він захистить тебе та твоїх союзників від запального подиху Володаря Чорної Скелі… Нефаріана.",
},

[7494] = {
    en = "Feathermoon Stronghold",
    T = "Федермунська фортеця",
    D = "$N! У Фераласі потрібна ваша допомога!$B$BМаг-розбійник Леттендріс втік до стародавніх ельфійських руїн Елдре’талас, які тепер називаються «Діре Маул». Вважається, що вона володіє предметом, наділеним небезпечною магічною енергією, який необхідно повернути.$B$BЛатронікус Мунспір просить агентів проникнути в «Діре Маул» і забрати цей предмет у Леттендріс.$B$BСлужіть Альянсу! Знайдіть Латроніка в фортеці «Пір’яний Місяць» у Фераласі.",
    O = "Поговоріть із Латронікусом Місячним Списом у фортеці «Пір’яний Місяць» у Фераласі.",
    P = "",
    C = "Вітаю, $N. Я радий тебе бачити, але шкодую, що наша зустріч відбувається не в більш приємних обставинах.$B$BСлухай уважно, бо у мене для тебе є надзвичайно важливе завдання...",
},

