[7793] = {
    en = "A Donation of Silk: Stormwind",
    T = "Подарунок у вигляді шовку: Штормвінд",
    D = "",
    O = "",
    P = "Як і у випадку з більшістю інших тканин, наші запаси шовку зараз на рекордно низькому рівні. З огляду на стан наших запасів, нам від вас знадобиться лише шістдесят шматків шовку загалом; ми зможемо досягти нашої мети завдяки підтримці інших.$B$BДозвольте зауважити, що такий благодійний дарунок, як шовк, безсумнівно підвищить ваш авторитет у місцевій громаді! Якщо ви маєте при собі ці шістдесят шматків шовкової тканини й готові їх пожертвувати, я можу забрати їх у вас прямо зараз.",
    C = "Чудово! Дякуємо вам за щедрий внесок, $N!",
},

[7794] = {
    en = "A Donation of Mageweave: Stormwind",
    T = "Пожертва «Магічного полотна»: Штормвінд",
    D = "",
    O = "",
    P = "Запаси «Магічного полотна» підходять до кінця, і нам дуже знадобиться ваша допомога, щоб поповнити їх! Якщо ми розраховуватимемо на підтримку всієї спільноти, нам знадобиться лише 60 шматків «Магічного полотна» від кожного з вас, щоб досягти нашої мети. Запевняю вас, така щедрість не залишиться непоміченою у Штормграді!$B$BЯкщо у вас є шістдесят шматків тканини «магічного плетіння» і ви готові їх пожертвувати, я можу прийняти їх від вас прямо зараз.",
    C = "Чудово! Ми дякуємо вам за щедрий внесок, $N!",
},

[7795] = {
    en = "A Donation of Runecloth: Stormwind",
    T = "Пожертва рунічної тканини: Штормвінд",
    D = "",
    O = "",
    P = "$n, ви зробили величезний внесок у нашу акцію зі збору тканини. Поки ми наполегливо працюємо над поповненням наших запасів, запаси одного виду тканини залишаються вкрай низькими — рунічної тканини. Ми вкрай потребуємо її, і сподіваємося, що ви зможете допомогти нам, як і раніше!$B$BЯкщо ви готові, будь ласка, принесіть мені стільки рунічної тканини, скільки зможете. Спочатку ми приймемо одноразовий внесок у розмірі шістдесяти одиниць, а далі подивимося.",
    C = "Чудово — ці речі одразу знадобляться, запевняю вас. Ще раз дякую за допомогу! Без вас ми б точно не впоралися.$B$BЗ огляду на всі ваші попередні пожертви, я, безперечно, оброблю будь-які додаткові пожертви рунічної тканини, які ви захочете зробити в майбутньому. Просто обов’язково повідомте мене, і я особисто подбаю про те, щоб ваші добрі справи не залишилися непоміченими!",
},

[7796] = {
    en = "Additional Runecloth: Stormwind",
    T = "Додаткова рунічна тканина: Штормвінд",
    D = "",
    O = "",
    P = "Як тільки ти будеш готовий здати стос рунічної тканини, я його прийму.",
    C = "$N — якби не такі герої, як ви, які працюють на благо племені, ми б, безсумнівно, страждали. Дякуємо вам за ваші постійні зусилля!",
},

[7798] = {
    en = "A Donation of Silk: Darnassus",
    T = "Подарунок у вигляді шовку: Дарнас",
    D = "",
    O = "",
    P = "Як і у випадку з більшістю інших тканин, наші запаси шовку зараз на рекордно низькому рівні. З огляду на стан наших складів, нам від вас знадобиться всього шістдесят шматків шовку; за підтримки інших ми, безсумнівно, зможемо досягти поставленої мети.$B$BДозвольте зауважити, що такий благодійний дар, як шовк, безсумнівно підвищить ваш авторитет у місцевій громаді! Якщо у вас є ці шістдесят шматків шовкової тканини і ви готові їх пожертвувати, я можу забрати їх у вас прямо зараз.",
    C = "Чудово! Дякуємо вам за щедрий внесок, $N!",
},

[7799] = {
    en = "A Donation of Mageweave: Darnassus",
    T = "Пожертва «Магічного полотна»: Дарнасс",
    D = "",
    O = "",
    P = "Запаси «Магічного полотна» підходять до кінця, і нам знадобиться ваша допомога, щоб поповнити їх! Якщо ми розраховуватимемо на підтримку всієї спільноти, то для досягнення нашої мети нам знадобиться лише 60 шматків «Магічного полотна» від кожного з вас. Запевняю вас, така щедрість не залишиться непоміченою в Дарнассі!$B$BЯкщо у вас є шістдесят шматків тканини «магічне полотно» і ви готові їх пожертвувати, я можу прийняти їх від вас прямо зараз.",
    C = "Чудово! Дякуємо вам за щедрий внесок, $N!",
},

[7800] = {
    en = "A Donation of Runecloth: Darnassus",
    T = "Пожертва рунічної тканини: Дарнасс",
    D = "",
    O = "",
    P = "$n, ви зробили величезний внесок у нашу акцію зі збору тканини. Ми наполегливо працюємо над поповненням наших запасів, але запаси одного виду тканини залишаються вкрай низькими — рунічної тканини. Ми вкрай її потребуємо і сподіваємося, що ви зможете допомогти нам, як і раніше! $B$BЯкщо ви готові, будь ласка, принесіть мені стільки рунічної тканини, скільки зможете. Спочатку ми приймемо пожертву в розмірі шістдесяти одиниць, а далі подивимося.",
    C = "Чудово — це одразу знайде застосування, запевняю вас. Ще раз дякую за допомогу! Без вас ми б, безперечно, були б у скрутному становищі.$B$BЗ огляду на всі ваші попередні пожертви, я, безперечно, оброблю будь-які додаткові пожертви рунічної тканини, які ви захочете зробити в майбутньому. Просто обов’язково повідомте мене, і я особисто подбаю про те, щоб ваші добрі справи не залишилися непоміченими!",
},

