[7834] = {
    en = "A Donation of Silk: Darkspear Tribe",
    T = "Подарунок у вигляді шовку: Плем’я Темних Списів",
    D = "",
    O = "",
    P = "Як і у випадку з більшістю інших тканин, наші запаси шовку перебувають на рекордно низькому рівні. З огляду на стан наших запасів, нам від вас знадобиться лише шістдесят шматків шовку загалом; за підтримки інших ми, безсумнівно, зможемо досягти поставленої мети.$B$BДозвольте додати, що такий благодійний дар, як шовк, безсумнівно підвищить ваш авторитет у місцевій громаді! Якщо у вас є ці шістдесят шматків шовкової тканини і ви готові їх пожертвувати, я можу забрати їх у вас прямо зараз.",
    C = "Чудово! Дякуємо вам, $N, за щедрий внесок!",
},

[7835] = {
    en = "A Donation of Mageweave: Darkspear Tribe",
    T = "Пожертва «Магічного полотна»: Плем’я Темних Списів",
    D = "",
    O = "",
    P = "Запаси «Магічного полотна» підходять до кінця, і нам потрібна ваша допомога, щоб поповнити їх! Якщо ми розраховуватимемо на всю спільноту, нам знадобиться лише 60 шматків «Магічного полотна» від кожного з вас, щоб досягти нашої мети. Запевняю вас, така щедрість не залишиться непоміченою тролями Темного Списа!$B$BЯкщо у вас є шістдесят шматків тканини «магічне плетіння» і ви готові їх пожертвувати, я можу прийняти їх від вас прямо зараз.",
    C = "Чудово! Дякуємо вам за щедрий внесок, $N!",
},

[7836] = {
    en = "A Donation of Runecloth: Darkspear Tribe",
    T = "Пожертва рунічної тканини: Плем’я Темних Списів",
    D = "",
    O = "",
    P = "$n, ви зробили величезний внесок у нашу акцію зі збору тканини. Ми наполегливо працюємо над поповненням наших запасів, але запаси одного виду тканини залишаються вкрай низькими — рунічної тканини. Ми вкрай потребуємо її, і сподіваємося, що ви зможете допомогти нам, як і раніше!$B$BЯкщо ви готові, будь ласка, принесіть мені стільки рунічної тканини, скільки зможете. Спочатку ми приймемо одноразову пожертву в розмірі шістдесяти одиниць, а далі будемо дивитися.",
    C = "Чудово — це одразу знайде застосування, запевняю вас. Ще раз дякую за допомогу! Без вас ми б, безперечно, були б у скруті.$B$BЗ огляду на всі ваші попередні пожертви, я, звичайно ж, оброблю будь-які додаткові пожертви рунічної тканини, які ви захочете зробити в майбутньому. Просто обов’язково повідомте мене, і я особисто подбаю про те, щоб ваші добрі справи не залишилися непоміченими!",
},

[7837] = {
    en = "Additional Runecloth: Darkspear Tribe",
    T = "Додаткова рунічна тканина: Плем’я Темних Списів",
    D = "",
    O = "",
    P = "Як тільки ви будете готові здати стос рунічної тканини, я його прийму.",
    C = "$N — якби не такі герої, як ви, які працюють на благо племені, нам, безсумнівно, довелося б нелегко. Дякуємо вам за ваші постійні зусилля!",
},

[7838] = {
    en = "Arena Grandmaster",
    T = "Грандмайстер «Арени»",
    D = "",
    O = "",
    P = "Глупець! Принеси мені 12 сувенірів Майстра Арени, і тоді ти станеш Великим майстром Арени Гурубаші! Арррр!",
    C = "Ти пролив чимало крові на підлозі Арени, і я з радістю призначаю тебе Великим майстром Арени!",
},

[7839] = {
    en = "Vilebranch Hooligans",
    T = "Хулігани з Вайлбранча",
    D = "Негідники з Вілебранча вторглися в наше село і вкрали мої інструменти! У мене є запасні інструменти, але той набір, який вони вкрали, був подарунком від добросердого гнома, який врятував мені життя, коли я був ще молодим орком.$B$BЯ хочу повернути ці інструменти, $N — вони для мене значать усе.$B$BМаркхор повідомив, що інструменти було помічено поблизу храмів Агол'вата та Шаол'вата.$B$BЦі храми знаходяться у північно-східній частині Глибинних земель.$B$BЗнайдіть мої інструменти!",
    O = "Сміт Слагтрі з села Ревантуск у Глибинних землях просить вас знайти загублені інструменти Слагтрі. Поверніться до нього, коли виконаєте це завдання.$B$BВи пригадуєте, що коваль Слагтрі згадував, що інструменти можуть бути в одному з храмів Вайлбранч у північно-східній частині Глибинки. Також варто перевірити Скалу Скалк.",
    P = "Слід остерігатися тролів з регіону Вайлбранч, $N. Це безжальні, кровожерливі нелюди.",
    C = "Мої інструменти! Ти їх знайшов! О, який чудовий день! Дякую, $N.",
},

[7840] = {
    en = "Lard Lost His Lunch",
    T = "Лард втратив свій обід",
    D = "Лард влаштовував пікнік у таємному особливому місці, коли потворний і злий Вайлбранч вдарив Ларда великою палицею. Лард побіг назад до Ревантуска, але забув свій обід. Лард голодний. Може, ти повернешся до таємного особливого місця й принесеш Ларду обід? Лард боїться. Біжи на північ! Острів, що на півночі, — це й є те таємне особливе місце.",
    O = "Лард із селища Ревантуск у Глибинних землях просить вас знайти «Обід Ларда». Поверніться до нього, коли виконаєте це завдання.$B$BЛард згадав, що залишив його на острові на півночі. Стережіться тролів з роду Вайлбранч.",
    P = "<Лард погладжує свій величезний живіт.>$B$BЛард такий голодний.",
    C = "<Лард бере у тебе величезний шматок м’яса й накидається на нього.>$B$BЦе те, що треба! Дякую, малятко.$B$BЛард приготує тобі спеціальний кошик для пікніка за допомогу.",
},

[7841] = {
    en = "Message to the Wildhammer",
    T = "Послання до Диких Молотів",
    D = "«Дикі Молоти» укладають угоди з нашими ворогами, укладають нові союзи. Цього разу вони співпрацюють із високими ельфами, друже.$B$B<Ото плюється.>$B$BНам треба надіслати цим гномам з племені «Диких Молотів» повідомлення — повідомлення, написане кров’ю наших ворогів. Винищуйте кожного високого ельфа з Хайвейлу, якого зустрінете, залишайте їхні тіла як попередження.$B$BНіколи не зв’язуйтеся з тролями!",
    O = "Ото Моджі'ко з селища Ревантуск у Глибинних землях просить вас знищити 15 «Перегонців з Хайвейла», 15 «Розвідників з Хайвейла», 15 «Снайперів з Хайвейла» та 15 «Рейнджерів з Хайвейла». Поверніться до нього, коли завдання буде виконано.$B$BВи можете знайти високих ельфів Хайвейла в хатині «Квель'Даніл» у північно-західній частині Замежжя.",
    P = "Ти занадто чистий, чувак. Треба трохи розважитися — вступити в брудну сутичку з ворогом.",
    C = "Схоже, що «Ревантуски» теж укладають нові союзи, друже! Ти добре попрацював.",
},

[7842] = {
    en = "Another Message to the Wildhammer",
    T = "Ще одне послання до Диких Молотів",
    D = "Кажуть, що «Дикі молоти» та грифони так само близькі один до одного, як тролі та їхні подруги. Огидно, але ми зможемо використати це на свою користь, друже. Надішлемо їм ще одне повідомлення.$B$BВбивайте всіх грифонів, яких побачите в Замежжя, збирайте їхнє пір’я. З нього ми складемо останнє повідомлення.",
    O = "Ото Моджі'ко з села Ревантуск у Глибинних землях просить вас принести йому 10 довгих витончених пір'їн грифонів, що мешкають у Глибинних землях. Поверніться до нього, коли виконаєте це завдання.$B$BВідомо, що грифони мешкають у всіх регіонах Глибинки.",
    P = "Останнє повідомлення точно їх відлякає. Або це, або дуже-дуже розлютить їх.",
    C = "О, чувак, це буде круто. Залишився ще один крок — і «Дикі Молоти» зрозуміють, що з тролями не жартують!",
},

[7843] = {
    en = "The Final Message to the Wildhammer",
    T = "Останнє послання до Диких Молотів",
    D = "<Ото вручає тобі довге, залите кров’ю спис, обмотане кількома пір’їнами грифона.>$B$BВізьми це, друже. Віднеси це на Вершину Орлиного Гнізда, у самий центр міста, біля колодязя. Вбий його туди! Вбий його прямо в землю! Покажи тим гномам, що тролі не жартують! Повертайся, коли це зробиш. Сподіваюся, ти повернешся живим.",
    O = "Ото Моджі'ко з селища Ревантуск у Глибинних землях просить вас вирушити до Піку Орлиного Гнізда у західній частині Глибинних земель і залишити «Останнє послання до Диких Молотів» біля криниці в центрі селища. Поверніться до нього, коли виконаєте це завдання.$B$BОстерігайтеся розлючених гномів «Диких молотів» та недисциплінованих членів Альянсу.",
    P = "Чого ж ти так зволікаєш, друже?",
    C = "Якби ж я міг бути там, щоб побачити вираз їхніх облич, друже. Вони збирають валізи? Покидають місто?$B$BТи добре впорався, $N. Дуже добре. Ото нагородить тебе великою удачею.",
},

[7844] = {
    en = "Cannibalistic Cousins",
    T = "Кузени-канібали",
    D = "У Глибинках мешкають три різні племені тролів, $N. На цьому схожість між цими племенами й закінчується: ми всі — тролі і живемо у Глибинках.$B$B«Вільбранч» — як і натякає їхня назва — це розбещена зграя, що живиться тілами інших тролів та гуманоїдів.$B$BЯкби тут був Зул'джин, він би знищив їх усіх одним рухом руки — на жаль, Зул'джин ще не повернувся, і нам доводиться покладатися лише на власні сили.$B$BСаме вам належить знищити цю нечисть у цьому регіоні!",
    O = "Містик Яйо'джин із селища Ревантуск у Глибинках просить вас вбити 30 «Шкуродерів з Вілбранча» та 15 «Провісників з Вілбранча». Поверніться до неї, коли виконаєте це завдання.$B$BЯйо'джин зазначила, що цих тролів можна знайти поблизу храмів Шаол'вата та Агол'вата в північно-східній частині Замежжя.",
    P = "Провісники та спекулянти з Вілебранча населяють північно-східну частину Глибинки.",
    C = "Молодець, $C. Навіть сам Зул’джин не зміг би впоратися краще!",
},

[7845] = {
    en = "Kidnapped Elder Torntusk!",
    T = "Викрали старійшину Торнтюска!",
    D = "Мого друга викрали дикуни з Вайлбранча під час зухвалого нічного нальоту на наше село. Наші шпигуни повідомили мені, що він досі живий і перебуває в полоні на вершині Джинта’алора. Кажуть, що підла жриця Гекс готує його до жертвопринесення безликому богу крові, Хаккару.$B$BТи мусиш врятувати його, $N! Наше село не витримає такої великої втрати.",
    O = "Праймал Торнтаск із селища Равентуск у Замежжя просить вас врятувати її партнера, Старшого Торнтаска, з Джинта’алора.$B$BВам повідомили, що його утримують у полоні на вершині Джинта'алора — столиці Вілбранчів, розташованої в південній частині Замежжя.",
    P = "",
    C = "Ти повинен діяти швидко, $N. Напевно, охоронців уже попередили про твою присутність.",
},

[7846] = {
    en = "Recover the Key!",
    T = "Відновіть ключ!",
    D = "Ключ від моїх кайданів зберігає Хітах’я, Хранителька. Вона перебуває в сусідній печері. Будь обережним, $c, адже її добре охороняють.$B$BВбий її та принеси ключ, щоб звільнити мене від кайданів. Тільки тоді я зможу повернутися додому.",
    O = "Старійшина Торнтusk у Джинта'алорі просить вас вбити Хіта'я, Хранителя, щоб дістати ключ від кайданів, якими він скутий. Поверніться до старійшини Торнтusk, коли знайдете ключ.",
    P = "Треба поспішати!",
    C = "Нарешті свобода! Дякую, $N. Ревантуск дізнається про твої подвиги!",
},

[7847] = {
    en = "Return to Primal Torntusk",
    T = "Повернутися до «Первісного Торнтуска»",
    D = "Повернися до моєї подруги, Праймал Торнтуск, у селі Ревантуск. Скажи їй, що я повертаюся додому! Вона обов’язково тебе винагородить.",
    O = "Старійшина Торнтуск у Джинта'алорі хоче, щоб ви повернулися до Первісного Торнтуска у селі Ревантуск із звісткою про його порятунок.",
    P = "",
    C = "Ти зробив велику послугу Ревантуску, $N! Ми тобі дуже вдячні.",
},

[7848] = {
    en = "Attunement to the Core",
    T = "Гармонія з внутрішньою сутністю",
    D = "Навколо нас розриви з’являються, розширюються і руйнуються, $r. Усього за два кроки від того місця, де я стою, є розрив, що веде крізь глибини Чорноскельної гори, у пащу Володаря Вогню.$B$BЗдивовані? Шкода... Смертні раси не можуть осягнути те, чого не бачать, не торкаються і не відчувають.$B$BЗапевняю вас, портал існує, і пройти крізь нього можливо.$B$BЯ зацікавив вас? Налаштування — це просто. Відправтеся в Глибини Чорної Скелі та знайдіть фрагмент ядра. Поверніть його мені, і я налаштую вашу сутність на портал.",
    O = "Відправляйтеся до входу в «Розплавлене ядро» у «Глибинах Чорної скелі» та знайдіть «Фрагмент ядра». Після того як ви знайдете «Фрагмент ядра», поверніться до Лотоса Рифтвейкера на «Горі Чорної скелі».",
    P = "Перш ніж отримати доступ, ви повинні налаштувати свою душу на «Розплавлене ядро».",
    C = "Тепер я можу перенести вас до «Розплавленого ядра». Скажіть лише слово — і все буде зроблено.",
},

[7849] = {
    en = "Separation Anxiety",
    T = "Тривога розлуки",
    D = "Як і багато хто в нашому селі, я теж втратив близьку людину, яка загинула в дикій природі. На жаль, це був мій брат-близнюк Малхор — його викрали «Вільбранч» під час того самого нальоту, що й подругу Торнтуска.$B$BНа жаль, йому не судилося вижити, і його стратили швидко та жорстоко; його останки стали поживою для слизових тварюк та вовків Вілбранча.$B$BВрятувати його життя вже запізно, але врятувати його душу ще не пізно. Знайди його останки, $N.",
    O = "Мисливець Маркхор із села Ревантуск у Глибинних землях просить вас знайти останки його брата-близнюка. Знайдіть і поверніть мисливцеві Маркхору «Череп мисливця Малкхора» та «Кістки мисливця Малкхора».$B$BМархор згадав, що останки його брата стали поживою для слизових істот та вовків у Вайлбранчі. Він також зазначив, що в Джинта'алорі є сміттєзвалище, заповнене слизовими істотами, а також вовча нора. Обидва ці місця знаходяться поблизу вершини храму.",
    P = "Коли я отримаю його останки, я відвезу їх до Яйоджіна і подбаю про те, щоб їх підготували до гідного поховання.",
    C = "Мій найдорожчий брате, як же я за тобою сумуватиму...$B$BДякую тобі за допомогу, $N. У моїх очах ти — справжній герой.",
},

[7850] = {
    en = "Dark Vessels",
    T = "«Темні судна»",
    D = "Вайлбранчі борються з надприродною люттю. Це відбувається через мерзенні магічні витвори Вайл-жриці Гекс.$B$BПо всьому Джинта’алору ви знайдете темні посудини зі спотвореною кров’ю. Ці посудини випромінюють мерзенну магію безликого Бога крові, наділяючи Вілбранчів силою, а також доводивши їх до божевілля.$B$BВикрадіть ці посудини та поверніть їх мені, щоб я міг усунути скверну й, зрештою, послабити владу Бога крові.",
    O = "Первісний Торнтуск у селищі Ревантуск у Глибинних землях просить вас знайти 10 посудин із зіпсованою кров’ю в Джинта’алорі. Поверніться до Первісного Торнтуска, коли виконаєте це завдання.",
    P = "Будьте обережні у бою з Вайлбранчем, $N. Їхній розум затьмарений — вони б’ються до смерті.",
    C = "Темна енергія, що керувала Вілебранчем, була знята — принаймні наразі. Ми мусимо завжди залишатися пильними у нашій боротьбі зі злом, адже навіть якщо Вільну жрицю знищено, на її місце незабаром прийде інша.",
},

[7861] = {
    en = "Wanted: Vile Priestess Hexx and Her Minions",
    T = "Розшукуються: підла жриця Гекс та її поплічники",
    D = "За наказом Праймала Торнтуска підступна жриця Гекс та її поплічники мають бути притягнуті до відповідальності!$B$BЗа вбивство підступної жриці Гекс та всієї її елітної гвардії Аман'засі призначено велику винагороду.",
    O = "Вам доручено вбити підлу жрицю Гекс та 20 вартових Аман’засі з П’ятого гілля. Після виконання цього завдання зверніться до Первісного Торнтуска в селі Ревантуск у Глибинних землях.$B$BЗлісна жриця Гекс та охоронці Аман'засі знаходяться на вершині Джинта'алор у Глибинних землях.",
