[8110] = {
    en = "Enchanted South Seas Kelp",
    T = "Чарівні водорості Південних морів",
    D = "",
    O = "",
    P = "",
    C = "Бачиш ось ці водорості, чувак? Вони з Південних морів. Ми просто додаємо трохи моджо і трохи магії, і вони набувають властивостей, які найбільше підходять їхньому власнику.$B$BТи ж $c, тож це буде легко, чувак. Просто обмотай їх навколо шиї й подумай про природу, білок чи що завгодно, що вам, людям, подобається.",
},

[8111] = {
    en = "Enchanted South Seas Kelp",
    T = "Чарівні південноморські водорості",
    D = "",
    O = "",
    P = "Привіт, друже! Радий знову тебе бачити. У племені всі говорять про те, як ти вбив Хаккарі та все таке. Молтор доручив мені додати більше магії до твого талісмана. Просто дай його сюди, і Майвікі зробить його кращим.",
    C = "Цей нашийник не для куріння, чувак! Ти повинен використовувати його для боротьби зі злом.",
},

[8112] = {
    en = "Enchanted South Seas Kelp",
    T = "Чарівні південноморські водорості",
    D = "",
    O = "",
    P = "Як там той талісман, друже? Схоже, настав час додати трохи більше магії та чарівності до його листя. Йому потрібно трохи розквітнути серед цієї в’ялості. Дай його сюди, і Майвікі одразу все налагодить.",
    C = "А тепер іди до злісних тролів у Зул’Гурубі й покажи їм, на що здатні твої сили природи, друже!",
},

[8113] = {
    en = "Pristine Enchanted South Seas Kelp",
    T = "Незаймана чарівна водорость Південних морів",
    D = "",
    O = "",
    P = "$n! Давно тебе не бачив. Ти знав, що сам король Растахан наказав мені додати останній штрих чарівності та магії до твого талісмана? Це правда, друже! Я б не повірив, якби не побачив це на власні очі. Дай-но сюди.",
    C = "$n Друже, це була чудова подорож. Продовжуй знищувати й придушувати Хаккара та його поплічників.",
},

[8114] = {
    en = "Control Four Bases",
    T = "Контроль над чотирма базами",
    D = "$N, ти переніс битву за Аратську улоговину на територію наших ворогів і здобув великі заслуги на тому полі бою. Ти довів нам свою цінність як $c і показав нашим ворогам, що ми не підкоримося їхнім підлостям!$B$BОскільки ти довів свою цінність для нас, я маю для тебе складне завдання. Я хочу, щоб ти захопив і утримував щонайменше чотири бази в Аратській улоговині. Якщо тобі це вдасться, ми не лише забезпечимо себе життєво важливими ресурсами, а й продемонструємо Орді нашу перевагу!$B$BІди, $N, і хай тобі щастить.",
    O = "Увійдіть до Басейну Араті, захопіть і утримуйте чотири бази одночасно, а потім поверніться до фельдмаршала Ослайта в Рефудж-Пойнт.",
    P = "Ти ще не захопив чотири бази, $N. Повернися до Аратської улоговини й виконай доручене тобі завдання!",
    C = "Чудова робота, $n! До мене підійшов схвильований розвідник і розповів про твої подвиги. Ми, члени Ліги Аратора, дуже задоволені! $B$B Ти швидко стаєш місцевим героєм серед солдатів Ліги, і сьогоднішній подвиг ще раз підтверджує твою бездоганну репутацію.",
},

[8115] = {
    en = "Control Five Bases",
    T = "Контроль п’яти баз",
    D = "$N, боротьба за ресурси Аратської улоговини — це криваве випробування. Ваші послуги Лізі Аратора не тільки вкрай необхідні, але й високо цінуються.$B$BІ у нас є для вас ще одне завдання.$B$BЛіга бажає завдати потужного удару по окупантам Аратської улоговини — Осквернителям. Ми хочемо вигнати їх з усіх стратегічних точок на полі бою!$B$BЦе буде нелегко, але якщо хтось і зможе це зробити, то це саме ви.",
    O = "Одночасно захопіть 5 баз у Басейні Араті, а потім поверніться до фельдмаршала Ослайта в Притулку-Пойнті.",
    P = "Ти ще не виконав свою місію, $N. Це важко, але я твердо вірю в тебе.",
    C = "Ти це зробив! Ти захопив усі бази! Молодець, $N!$B$BБули ті, хто сумнівався у твоїх шансах, але я знав, що ти це зможеш. Дякую тобі, і знай, що Ліга Аратора дуже поважає тебе, так само як «Осквернителі Забутих» мусять боятися навіть згадки твого імені!",
},

[8116] = {
    en = "Vision of Voodress",
    T = "Бачення Вудресс",
    D = "",
    O = "",
    P = "",
    C = "У тебе з Майвікі є щось спільне, друже. Ми обоє — $c! Хоча Майвікі — скоріше містик, а ти — скоріше новачок. Та все ж ми обоє знаємо, що приносять великі духи.$B$BЯк подарунок я дарую тобі цю кулю, щоб ти носив її на шиї. Зазирни глибоко всередину і побач село Вудрес у Південних морях! Нехай це підніме тобі настрій!",
},

[8117] = {
    en = "Vision of Voodress",
    T = "Бачення Вудресс",
    D = "",
    O = "",
    P = "Гарні новини, $n. Молтор останнім часом не перестає тебе хвалити. Він каже, що ти перетворюєшся на справжнього героя Зандалара.$B$BВін також просить Майвікі ще трохи відполірувати твою кулю! Дай його сюди, щоб Майвікі могла зробити зображення яскравішим.",
    C = "Стережись злих духів Хаккарі, друже. Чесно кажучи, вони справді моторошні.",
},

[8118] = {
    en = "Vision of Voodress",
    T = "Бачення Вудресс",
    D = "",
    O = "",
    P = "Ша-мон! Майвікі пожартував!$B$B<Майвікі сміється.>$B$BТо ти використовував духів та стихії проти наших ворогів у Зул’Гурубі, так? Слава духам!$B$BМайвікі розквітне твою кулю. Дай її сюди, $n.",
    C = "Поглянь на це зараз, $n. Вудреси тепер видно ще чіткіше, так? Нехай первісна сила протікає крізь тебе, друже.",
},

[8119] = {
    en = "The Unmarred Vision of Voodress",
    T = "Незаплямоване бачення Вудресс",
    D = "",
    O = "",
    P = "<Майвікі вказує на твій талісман.>$B$BПоглянь на нього, $n! Він ожив. Духи танцюють навколо кулі.$B$BВіддай його Майвікі, щоб вона могла внести останнє коригування.",
    C = "Одного дня, $n, ти зможеш використовувати цю кулю, щоб безпосередньо спілкуватися зі мною. Коли ця битва з Хаккаром закінчиться і Майвікі повернеться додому. Давай закличемо духів і попросимо їх, щоб цей день настав якнайшвидше.",
},

[8120] = {
    en = "The Battle for Arathi Basin!",
    T = "Битва за Аратську улоговину!",
    D = "Як ви, безсумнівно, вже чули, Ліга Аратора відправляє великі війська до Аратської улоговини. Прагнучи продовольства та припасів, ці дурні з Альянсу мають намір захопити та контролювати багаті ресурси цього краю. Ми мусимо показати їм, що Араті більше ніколи не стане домівкою для людей!$B$BВідправляйся до Аратської улоговини й атакуй шахту, лісопильню, кузню та стайні. Зніміть прапори ворогів, проголосивши ці території територіями Орди.$B$BІдіть, $N. Повідомте мені, коли це завдання буде виконано.",
    O = "Здійсніть напад на шахту, лісопильню, кузню та стайню в Аратській улоговині, а потім поверніться до Майстра Смерті Двайра в Хаммерфолі.",
    P = "",
    C = "До мене звернувся розвідник «Дефайлерів» із звітом про твій успіх, $n. Молодець.$B$BЯк ти дізнаєшся, щоб виграти битву за Аратську улоговину, ми маємо бути завжди пильними та придушувати будь-які спроби експансії Альянсу. Зроби це, і наша перемога тут буде гарантована.",
},

[8121] = {
    en = "Take Four Bases",
    T = "Займи чотири бази",
    D = "$N Поки в Аратській улоговині точаться запеклі бої, звістки про твої подвиги поширилися далеко. Ти користуєшся великою повагою серед нас, що вселяє в мене впевненість: ти виконаєш завдання, яке я тобі зараз доручаю.$B$BНастав час надіслати повідомлення Лізі Аратора. Ми мусимо показати їм, що їхні позиції в Аратській улоговині хиткі й можуть бути швидко втрачені. Ми продемонструємо це, одночасно утримуючи чотири стратегічні пункти в Аратському басейні.$B$BДосягні успіху в цьому, $N, і завоюй велику повагу серед Осквернителів.",
    O = "Захопіть одночасно чотири бази в Аратській улоговині, а потім поверніться до Майстра Смерті Двайра в Хаммерфолі.",
    P = "Поверніться до Аратської улоговини, $N, і виконайте завдання, з яким вас туди відправили! Захопіть і утримуйте чотири бази!",
    C = "Молодець, $N! Твої останні дії в Аратській улоговині були досить складними, тож твої успіхи заслуговують на високу оцінку. Ліга Аратора, мабуть, досі не оговталася від останніх сутичок в улоговині, зализує рани і, сподіваймося, переосмислює своє рішення воювати саме тут.",
},

[8122] = {
    en = "Take Five Bases",
    T = "Займи п’ять баз",
    D = "Нам важко це побачити, оскільки ми так глибоко занурені в конфлікт, але наші розвідники повідомляють про ослаблення рішучості Ліги Аратора. Ми мусимо скористатися цією нагодою й завдати їм нищівного удару! Повертайся до Аратської улоговини й кинься в бій проти наших ворогів. Прокляніть їх, вбийте їх і захопіть усі п’ять стратегічних баз! Нехай їхні солдати з криками та в крові тікають з лінії фронту, а на їхніх стогнучих вустах лунають розповіді про вашу жорстокість.$B$BЗробіть це — і здобудете велику перемогу для Осквернителів.",
    O = "Захопіть одночасно п’ять баз у Басейні Араті, а потім поверніться до Майстра Смерті Двайра в Хаммерфолі.",
    P = "Повертайся до Аратської улоговини, $N, і виконай завдання, з яким тебе туди відправили! Захопи та утримуй усі п’ять баз!",
    C = "Крики Альянсу, коли ти та твої побратими напали на них, було чутно навіть звідси, $N. Мені майже шкода їх за той біль і страх, які ти приніс у їхні ряди. Майже, але не зовсім.$B$BТвоя цінність для Осквернителів не підлягає сумніву. Твої подвиги в Аратській улоговині були надзвичайно вражаючими й відгукнулися в палатах Варіматраса… та й у самій Темній Леді.",
},

[8123] = {
    en = "Cut Arathor Supply Lines",
    T = "Перерізати лінії постачання Аратора",
    D = "Ліга Аратора не шкодує коштів у своїх зусиллях з відвоювання Араті. Вони, а також усі раси Альянсу, зараз прямують до цього віддаленого регіону, маючи намір розширити свою територію від Мису Притулку. Ми мусимо їх зупинити, і найкращий спосіб це зробити — позбавити їх запасів.$B$BТи можеш нам допомогти, $N. Зайди в Аратську улоговину, відому своїми багатими копальнями, родючими землями та вправними ремісниками. Захопи та утримуй кожну базу, яку зможеш, виграй битву та повернися до мене з Знаком честі, який ти здобудеш.",
    O = "Виграйте битву за Аратську улоговину, отримайте «Знак честі Аратської улоговини» та поверніть його Смертошукачу Мортісу в Хаммерфолі.",
    P = "Що там, $R? У тебе є «Знаки честі»? Повертайся до Аратської улоговини, знищ шкідників Альянсу та захопи їхні ресурси для Темної Леді!",
    C = "<Дестстокер Мортіс посміхається>$B$BНашим ворогам було завдано ще одного вирішального удару, $n. Завдяки вашим діям Аратська улоговина незабаром перейде під контроль Осквернителів.",
},

[8124] = {
    en = "More Resource Crates",
    T = "Ще більше ящиків з ресурсами",
    D = "Ліга Аратора не шкодує коштів у своїх зусиллях з відвоювання Араті. Вони, а також усі раси Альянсу, зараз прямують до цього віддаленого регіону, маючи намір розширити свою зону контролю від Мису Притулку. Ми мусимо їх зупинити, і найкращий спосіб це зробити — позбавити їх запасів.$B$BТи можеш нам допомогти, $N. Увійди до Аратської улоговини, відомої своїми багатими копальнями, родючими землями та вправними ремісниками. Захопи та контролюй усі бази, які зможеш, виграй битву та повернися до мене з отриманими ресурсами.",
    O = "Виграйте битву за Аратську улоговину, отримайте ящик з ресурсами Араті та поверніть його Смертоносному Мортісу в Хаммерфолі.",
    P = "$N, у «Осквернителів» для тебе є постійне завдання: повернутися в Аратську улоговину, дістати ще ящиків з ресурсами та принести їх мені.",
    C = "Дуже добре. Я негайно передам це нашим інтендантам, а моїм начальникам буде надіслано подяку за ваші дії.$B$BЩе раз дякую $N. Ваш внесок у наші бої помічають як прості солдати, так і високопоставлені воєначальники.",
},

[8141] = {
    en = "Zandalrian Shadow Talisman",
    T = "Зандальріанський талісман тіні",
    D = "",
    O = "",
    P = "",
    C = "Ти швидко прогресуєш, юний $c. Мабуть, настав час посвятити тебе в «Шера Алі’х» — зандаларів «Руки Смерті». Протягом тисячоліть ми виконували роль найманих вбивць для Імперії Зандалара. Занадто довго ми сиділи склавши руки, дозволяючи Хаккарі набирати силу. Ми знову стикаємося з Хаккаром, але цього разу без підтримки об’єднаного $r фронту. Саме ти та твої союзники повинні допомогти перемогти Бога Крові та його поплічників!$B$BНоси цей талісман, і нехай він допомагає тобі у твоїх мандрівках.",
},

[8142] = {
    en = "Zandalrian Shadow Talisman",
    T = "Зандальріанський талісман тіні",
    D = "",
    O = "",
    P = "Вражаюче, $n. У тебе є талант до вбивства, якого я вже багато років не відчував у нікого іншого. Навіть Молтор знає про те, що ти зробив для Зандалара. Настав час ще більше посилити твій талісман. Дай його мені.",
    C = "Залишилося лише одне поліпшення, яке можна накласти на талісман, $c. Коли настане відповідний момент, я застосую це поліпшення.",
},

[8143] = {
    en = "Zandalrian Shadow Talisman",
    T = "Зандальрійський талісман тіні",
    D = "",
    O = "",
    P = "Я відчуваю, що ти завдав безліч смертей хакарі, $n. Від тебе тхне їхньою магією.$B$BПрипускаю, що талісман «Тінь» допоміг у цьому винищенні? Віддай його мені, і я підсилю його силу.",
    C = "Від вбивці твого калібру слід триматися подалі. Твої вороги повинні навчитися поваги! І ти отримаєш саме це, коли ворог побачить блиск «Руки Смерті» — але тоді вже буде занадто пізно...",
},

[8144] = {
    en = "Zandalrian Shadow Mastery Talisman",
    T = "Зандальріанський талісман майстерності тіні",
    D = "",
    O = "",
    P = "Він прагне зростати, $n. Талісман увібрав у себе все, що ти зробив. Тисячі трупів тролів, що завалюють Зул’Гуруб, підживили його силу. Віддай його мені, і я здійсню останнє вдосконалення.",
    C = "Це останній раз, коли ми розмовляємо під егідою Шери Аліх. Ви знаєте все, що потрібно. Візьміть талісман і продовжуйте вбивати. Не можна ні в якому разі дозволити Хаккару покинути Зул’Гуруб.",
},

[8145] = {
    en = "The Maelstrom's Tendril",
    T = "«Вій» «Маелстрома»",
    D = "",
    O = "",
    P = "",
    C = "Серед зандаларіанців професія $c користується великою повагою. Наші найкращі мисливці вирушають до краю Виру, щоб довести свою рішучість.$B$BЗ глибин моря вони витягують пасма водоростей, відомі як «Пагони Виру». Потім з цих водоростей плетуть талісман, який зачаровують, щоб підвищити влучність і силу пострілу.$B$BЗараз я дарую тобі один талісман, сплетений із «Пагонів Маелстрому». У міру того, як твій зв’язок із Зандаларом міцнішатиме, я вплету в талісман ще більше сили.",
},

[8146] = {
    en = "The Maelstrom's Tendril",
    T = "«Вітець Виру»",
    D = "",
    O = "",
    P = "Навіть звідси я чую, як твої залпи розправляються з нашими ворогами. Їхні крики болю лунають навколо.$B$BТи здобув собі неабияку славу серед тролів Зандалара, $n. Ми вдячні тобі за все, що ти зробив.$B$BДай мені свій талісман, щоб я міг додати до нього ще одне плетіння.",
    C = "Залишилося лише одне плетіння, яке я зможу додати до вашого талісмана, $c",
},

[8147] = {
    en = "The Maelstrom's Tendril",
    T = "«Вій» Виру",
    D = "",
    O = "",
    P = "Ах, $n, як приємно знову відчувати твій запах.$B$B<Фалтір посміхається.>$B$BВибач за моє почуття гумору. Іноді воно буває дуже огидним.$B$BЯ відчуваю, що ти завдав великого горя нашим ворогам. Сили Хаккара з люттю вигукують твоє ім’я. Це просто чудово.$B$BТи заслужив ще один візерунок на своєму талісмані. Подай його мені.",
    C = "Нехай вони шукають спокути, коли у вас закінчаться боєприпаси.",
},

[8148] = {
    en = "The Maelstrom's Wrath",
    T = "Гнів Виру",
    D = "",
    O = "",
    P = "Молтор передає повідомлення від короля Растахана, $n. Королівський двір надзвичайно вражений тим, як ви розгромили війська Хаккарі. Мені доручено нагородити вас останнім елементом для вашого талісмана. Простягніть його мені.",
    C = "Твоя подорож тільки-но розпочалася, юний $c. Можливо, одного дня ти відвідаєш Маелстром і зазирнеш у саме серце світу.$B$BБажаю тобі сили та витримки!",
},

[8149] = {
    en = "Honoring a Hero",
    T = "Вшанування героя",
    D = "Під час Свята врожаю в Азероті ми дякуємо героям за жертви — а в деяких випадках і за найвищі жертви — які вони принесли заради нас. Альянс вшановує багатьох героїв, але історія Утера Світлоносного є найтрагічнішою з усіх.$B$BДопоможіть нам вшанувати Утера, доставивши цю жертву до його могили у Західних Землях Чуми. Покладіть її біля його статуї, а потім поверніться до мене. Я буду тут лише до кінця свята, тож не гайте часу — віддайте Утеру належну шану.",
    O = "Відправляйтеся до Могили Утера в Західних Землях Чуми, використайте «Данину Утеру» біля його статуї, а потім поверніться до Вагнера Хаммерстрайка, що знаходиться за межами Айронфорджа, до закінчення Свята врожаю.",
    P = "Чи відвідали ви Могилу Утера і залишили там данину?$B$BДля менш досвідчених мандрівників це може бути небезпечною подорожжю; відносно безпечнішим способом дістатися туди може бути шлях на північ від річки, що протікає через Хіллсбрад у Землі Чуми. Вона бере початок з озера, що прилягає до Пагорба Скорботи; рухайтеся на захід вгору по пагорбах, тримаючись подалі від сусідньої гробниці... тієї, що заполонена Плетью.",
    C = "Утер був героєм серед героїв. Я навіть уявити собі не можу, яку муку він відчув, коли Артас — його найкращий учень, якого Утер любив як рідного сина — зрадив усе людство. Проте він піднявся, щоб спробувати зупинити Артаса, і за це його назавжди запам'ятають як справжнього паладина. Він боровся до самого кінця, думаючи лише про тих, кого міг врятувати.$B$BДякую, $N. Сьогодні ти віддав шану великому герою, вшанувавши його дух і дух Свята врожаю.",
},

[8150] = {
    en = "Honoring a Hero",
    T = "Вшанування героя",
    D = "Під час Свята врожаю в Азероті ми дякуємо героям за їхні жертви — а в деяких випадках і за найвищу жертву — яку вони принесли заради нас. Орда вшановує багатьох героїв, але ніхто з них не уособлює силу та самопожертву так, як Гром Пекельний Крик.$B$BДопоможіть нам вшанувати Грома, доставивши цю жертву до його пам’ятника в Каньйоні Падіння Демонів у Попеліній Долині. Покладіть її біля підніжжя пам’ятника, а потім поверніться до мене. Я буду тут лише до кінця свята, тож не гайте часу — віддайте Грому належну шану.",
    O = "Відправляйтеся до пам’ятника Грому в Каньйоні Падіння Демонів у Попеліній Долині та використайте «Данину Грому» біля підніжжя пам’ятника. Поверніться до Явніра Нашака, що стоїть за межами Оргримара, до закінчення Свята врожаю.",
    P = "Чи відвідали ви пам’ятник Грому і залишили там свою данину пошани?$B$BМісце, де стоїть пам’ятник, досі оповите тлінним впливом Палкого Легіону. Якщо ви ще не дуже досвідчені в пригодних мандрівках, будьте пильні, наближаючись до пам’ятника.",
    C = "Повне ім’я Грома — Громаш — означає «Серце Велетня»; саме цього, а то й більше, знадобилося, щоб самотужки протистояти Маннороту. Гадаю, Вождь Війни найкраще висловився, коли сказав, що прокляття орків почалося й закінчилося разом із Громом. Цілком доречно, що жертва Грома — і, можливо, його спокута — стала джерелом, з якого сьогодні черпає силу Орда.$B$BДякую, $N. Сьогодні ти вшанував великого героя, віддавши данину поваги його духу та духу Свята врожаю.",
},

[8151] = {
    en = "The Hunter's Charm",
    T = "Чарівність мисливця",
    D = "Огтінк з Азшари розіслав заклик до досвідчених мисливців, таких як ви. Він — мисливець-фурболг, який покинув своє плем’я, щоб допомогти Колу Сенаріону. Його вчення покликане збагатити мудрість тих, хто поділяє його ремесло, та наставити їх на шлях збереження рівноваги. Вам варто поговорити з ним.$B$BОгтінк мешкає на вершині скель Азшари, на північний схід від Руїн Ельдарата.",
    O = "Поговоріть з Огтінцем в Азшарі.",
    P = "",
    C = "Моя мета більше не полягає в полюванні, а в навчанні $C. Саме це мені випало від долі.$B$BСтворіть разом зі мною амулет $C — колекцію трофеїв від впольованої здобичі, яка нагадуватиме вам про ваші минулі випробування та перемоги. Зрештою я залишу амулет собі, але нагороджу вас чимось іншим.",
},

[8153] = {
    en = "Courser Antlers",
    T = "Роги Курсера",
    D = "Цей скакун має найпотужніші роги серед усіх відомих земель. Такі роги слугують йому для захисту: він проколює ними нападника, часто пошкоджуючи при цьому самі роги. Ідеальні, природні роги — ознака духу тварини, сповненого безмежної впевненості.$B$BЯкщо ти триматимеш такі роги, це наділить і тебе такою самою впевненістю.$B$BПолюй на мохокопитного скакуна, знайди ідеальні роги та принеси їх мені.",
    O = "Принесіть пару рогів «Ідеального бігуна» Огтінцу в Азшарі. Огтінц мешкає на вершині скель на північний схід від Руїн Ельдарата.",
    P = "Ти вже знайшов роги?",
    C = "Щоб їх здобути, потрібно мати гострий зір і неабияке терпіння. Молодець.",
},

[8154] = {
    en = "Arathi Basin Mark of Honor!",
    T = "Знак честі Араті-Басейну!",
    D = "Війну треба вести за допомогою солдатів — це підтвердить будь-який солдат. Вони також скажуть, що битва, в якій воюють із поганим спорядженням або на порожній шлунок, програна ще до її початку!$B$BОсь чому Аратська улоговина має таке велике значення. У цій улоговині є ключові райони, де зосереджені найважливіші ресурси. Метали, зброя, їжа, деревина — все це потрібно, і все це можна здобути саме там.$B$BОсь що я хочу від тебе, $N. Увійди в Аратську улоговину, виграй битву, утримуючи більше баз, ніж ворог, і повернися до мене з «Знаком честі».",
    O = "Виграйте битву за Аратську улоговину, отримайте «Знак честі Аратської улоговини» та поверніть його сержанту Макліру в Притулку-Пойнті.",
    P = "Чи є у тебе Знаки честі, $N? Без них Ліга Аратора не зможе вести повноцінну битву...",
    C = "Ти здобув «Марку»! Чудова робота! Я надішлю ресурси нашим інтендантам, які зможуть швидко розподілити їх між нашими військами.$B$BДякую, $N. Дійсно, саме завдяки успішним місіям, таким як та, яку ти виконав, і виграються війни.",
},

[8155] = {
    en = "Arathi Basin Mark of Honor!",
    T = "Знак честі «Басейн Араті»!",
    D = "Війну треба вести за допомогою солдатів — це підтвердить будь-який солдат. Вони також скажуть, що битва, в якій воюють із поганим спорядженням або на порожній шлунок, програна ще до її початку!$B$BОсь чому Аратська улоговина має таке важливе значення. У цій улоговині є ключові райони, де знаходяться життєво необхідні ресурси. Метали, зброя, їжа, деревина — все це потрібно, і все це можна здобути саме там.$B$BОсь чого я від тебе хочу, $N. Увійди до Аратської улоговини, виграй битву, утримуючи більше баз, ніж ворог, і повернися до мене з «Знак честі».",
