[8195] = {
    en = "Zulian, Razzashi, and Hakkari Coins",
    T = "Монети Зуліана, Раззаші та Хаккарі",
    D = "Я шукаю «Взірці сили», відомі як «Монети племен». Це валюта, якою користуються різні мешканці Зул’Гуруба, і кожна з них наділена ледь помітним, але потужним магічним впливом.$B$BІснує дев’ять різних видів цих монет. Деякі з них користуються попитом серед моїх співвітчизників, оскільки за них герої Зандалара можуть придбати різноманітні види броні. Якщо у вас є зайві монети, я обміняю набір із трьох монет на один із наших «Жетонів честі». Ви можете використати ці жетони у торговця Рін’вошо; він пропонує нашим героям за них спеціальні предмети.",
    O = "",
    P = "Я шукаю «Взірці сили», відомі як «Монети племен». Вони є валютою, якою користуються різні мешканці Зул’Гуруба, і кожна з них наділена тонкою, але потужною магією.$B$BІснує дев’ять різних видів цих монет. Деякі з них користуються попитом серед моїх співвітчизників через те, що вони дають змогу придбати різноманітні види броні для героїв Зандалара. Якщо у вас є зайві монети, я обміняю один із наших «Жетонів честі» на набір із трьох таких монет. Ви можете використати ці жетони у торговця Рін’вошо; він пропонує нашим героям спеціальні предмети в обмін на них.",
    C = "Чудово — цей набір монет стане чудовим доповненням до нашої колекції, яка постійно поповнюється… і ми використаємо його для захисту племені від наступу Бога Крові. Ти заслужив цей Знак Честі, $N, а також вдячність племені!",
},

[8196] = {
    en = "Essence Mangoes",
    T = "Есенція «Манго»",
    D = "",
    O = "",
    P = "На багатьох островах Південних морів росте манго з надзвичайно сильною есенцією. Вже одне манго додасть сил тим, хто його з’їсть, як фізично, так і морально. Якщо ви ще ніколи його не куштували, то дуже багато втрачаєте!$B$BНа цьому острові у нас достатньо запасів, щоб запропонувати вам кілька плодів в обмін на жетон честі Зандалара. Зверніться до Вінчакси, якщо вам потрібно дізнатися, як отримати жетони; інакше давайте перейдемо до справи!",
    C = "Чесна угода, друже — будь ласка, насолоджуйся соковитими плодами Південних морів з благословення племені.",
},

[8201] = {
    en = "A Collection of Heads",
    T = "Колекція голів",
    D = "Це правда. Зараз Хаккар мешкає в Зул’Гурубі, купаючись у силі наших богів. Зачаровані верховні жерці тепер спрямовують енергію наших найсвятіших божеств до «Розривача душ», який незабаром отримає силу, що перевершить будь-яку істоту Азерота. Його треба зупинити!$B$BВізьми цей священний шнур і нанижи на нього голови верховних жерців, винних у спрямуванні енергії наших богів.$B$BКоли ти це зробиш, повертайся до мене.",
    O = "Зберіть 5 голів каналізаторів, а потім поверніть колекцію голів тролів Ексзалу на острові Йоджамба.",
    P = "У тебе є колекція голів, $N? Ми мусимо не дати Хаккару набрати ще більше сили!",
    C = "Ти здобув голови! Ти зупинив розкрадання сили наших богів і ослабив Хаккара!$B$BТвої вчинки — справді героїчні, $N. Нехай голови цих тролів-рабів благатимуть тебе про пощаду ще довго після того, як їхня кров застигне.",
},

