},

[8222] = {
    en = "Glowing Scorpid Blood",
    T = "Сяюча кров скорпіда",
    D = "",
    O = "",
    P = "За весь час роботи на ярмарку я дізнався багато цікавого про покупців. Ось одна з таких перлин мудрості: покупці обожнюють все, що світиться! Неважливо, що саме — можна взяти зламану ніжку стільця й зробити так, щоб вона світилася, і кожна дитина збіжиться з миль навколо, щоб її отримати!$B$BОтже, $N, мені потрібна світиться кров скорпідів. Її можна знайти у скорпідів у Сіллітусі, у Спопелених землях або на Палаючих степах.",
    C = "Чудова робота, $N! Дуже дякую! Я зроблю фарбу з цієї крові й перетворю всіляке дешеве барахло на сяючі скарби!$B$BОсь твої квитки, і ще раз дякую!",
},

[8223] = {
    en = "More Glowing Scorpid Blood",
    T = "Ще більше сяючої крові скорпіда",
    D = "",
    O = "",
    P = "Ця кров скорпіда чудово працює, $N! Дивовижно, як трохи блиску й сяйва можуть перетворити звичайний мотлох на коштовну прикрасу. Покупцям це дуже подобається, а ж саме в цьому й полягає суть, чи не так...$B$BТи мені дуже допоміг, $N, і хоча я не маю великої потреби в ще більшій кількості світиться крові скорпіда, якщо ти принесеш мені ще, я все одно обміняю тобі кілька квитків.",
    C = "Ще раз дякую, $N. Ось ваші квитки!",
},

