[8231] = {
    en = "Wavethrashing",
    T = "Хвильовий удар",
    D = "Хвильобій — це амфібійна істота, що мешкає виключно тут, в Азшарі. Вони сильні та витривалі.$B$BМіцна, відбиваюча світло луска хвилебійця відображає силу мисливця.$B$BВідстежте та вполюйте хвилебійців уздовж узбережжя Азшари й принесіть мені їхню луску.",
    O = "Принесіть 6 лусок «Хвилерозбивача» Огтінцу в Азшарі. Огтінц мешкає на вершині скель на північний схід від Руїн Ельдарата.",
    P = "Чи вдалося вам досягти успіху?",
    C = "Хвильорізи не так легко перемогти, тим більше у їхньому водному середовищі.$B$BТи довів, що готовий полювати навіть на ще небезпечнішу здобич.",
},

[8232] = {
    en = "The Green Drake",
    T = "«Зелений Дрейк»",
    D = "Тепер я доручаю тобі небезпечне полювання: вбий зеленого дракона Морфаза і принеси мені його зуб. Морфаз мешкає в глибинах Храму Атал’Хакара, вхід до якого знаходиться в Болоті Скорботи.$B$BЯкщо ти хочеш перемогти його, не вирушай сам. Цей дракон — ворог багатьох — знайди інших, хто також прагне знищити його.$B$BЗуб дракона уособлює силу, яку мисливець знайде в компанії інших. Принесіть його мені, і ви багато чого навчитеся.",
    O = "Принесіть «Зуб Морфаза» Огтінцу в Азшарі. Огтінц мешкає на вершині скель на північний схід від Руїн Ельдарата.",
    P = "Я бачу мудрість у твоїх очах, $N. Твоє полювання вже закінчилося?",
    C = "Ти опанував стародавні традиції, $N, і за це я дарую тобі подарунок із часів, коли я був $C.",
},

[8233] = {
    en = "A Simple Request",
    T = "Просте прохання",
    D = "Лорд Йорах Рейвенхолдт просить вас з’явитися до нього. Це таємна справа, і я не можу розповісти більше.$B$BМаєток Рейвенхолдт розташований у передгір’ях Хіллсбрада — шукайте стежку в горах на північний захід від фортеці Дурнхолд.",
    O = "Поговоріть з лордом Йорахом Рейвенхольдтом у маєтку Рейвенхольдт.",
    P = "",
    C = "Ласкаво просимо, ласкаво просимо, ласкаво просимо! Будь ласка, $N, сідай і обговоримо зі мною одну просту справу.$B$BРозумієте, $N, я нещодавно втратив щось дороге для мене, і, якщо говорити відверто, я хочу це повернути за будь-яку ціну. Ви теж від цього виграєте, не хвилюйтеся! О так, щось дуже приємне.$B$BНу що скажете, $N... готові до пригод?",
},

[8234] = {
    en = "Sealed Azure Bag",
    T = "Герметичний синій пакет",
    D = "Почнемо з головного. Я загубив невелику синю сумку, вміст якої є моєю особистою справою.$B$BНе витрачайте час на пошуки злодіїв, бо вони вже мертві. Ми знаємо лише те, що ці дурні не змогли відкрити сумку, тож продали її якомусь шаманові з племені Тімбермау в Азшарі як священну реліквію. Розумно.$B$BМені потрібно, щоб ти вирушив до Азшари й відібрав її у шамана — або дипломатично... або силою. Ставлю на перший варіант, він має більше шансів на успіх. Як тільки отримаєш сумку, віднеси її до архімага Ксилема.",
    O = "Отримайте «Запечатаний блакитний мішок» у шамана племені Тімбермоу в Азшарі. Потім віднесіть мішок архімагу Ксілему, якого також можна знайти в Азшарі.",
    P = "Я тебе знаю?",
    C = "Бачу, у тебе сумка лорда Рейвенхолда. Чому ти відразу не сказав, хлопче?",
},

[8235] = {
    en = "Encoded Fragments",
    T = "Зашифровані фрагменти",
    D = "Лорд Рейвенхолдт попросив нас обох про послугу. Він хоче зняти закляття з цієї сумки.$B$BНа жаль, деякі з моїх книг про зняття заклять нещодавно викрали, а потім дикуни їх знищили. Те, що залишилося від моїх книг, для мене все ще цінне.$B$BЯкщо ви принесете мені достатньо зашифрованих уривків, я зможу зібрати їх до купи. Найкращий спосіб це зробити — вбити звірів Азшари, оскільки вони мають звичку підбирати практично все підряд.",
    O = "Принесіть 10 закодованих фрагментів архімагу Ксілему в Азшарі.",
    P = "Чи знайшли ви достатньо фрагментів, щоб продовжити мою роботу?",
    C = "Схоже, ти підібрав кілька найкращих уривків. Можливо, ти все-таки не такий вже й нікчемний.",
},

[8236] = {
    en = "The Azure Key",
    T = "Ключ Azure",
    D = "На розшифрування уламків і зняття закляття знадобиться деякий час. Коли я закінчу, я особисто доставляю мішок лорду Рейвенхолдту.$B$BЗалишається ще питання щодо ключа, який, як кажуть, зберігає зелений дракон на ім’я Морфаз. Дрейк оселився в глибинах Храму Атал'Хаккара, вхід до якого знаходиться в Болоті Скорботи.$B$BЗберіть своїх друзів і вирушайте до його лігва. Лорд Рейвенхолдт чекатиме на ваше повернення з ключем.",
    O = "Поверніть ключ Azure лорду Йорачу Рейвенхолдту.",
    P = "Сумка від Архімага Ксайлема вже надійшла, ти вже знайшов ключ?",
    C = "Ключ! Я думав, що він назавжди загубився. Будь ласка, візьми з моїх запасів зачарований одяг — він призначений для розбійників, що відзначаються винятковою майстерністю та відданістю. Слід знати, що з $N не варто жартувати!$B$B<Йорах відкриває мішок, і його огортає золоте сяйво, що виривається зсередини. Він широко розплющує очі й заворожено дивиться...>",
},

[8238] = {
    en = "Gurubashi, Vilebranch, and Witherbark Coins",
    T = "Монети Гурубаші, Вайлбранч та Вітербарк",
    D = "Я шукаю «Взірці сили», відомі як «Монети племен». Вони є валютою, якою користуються різні мешканці Зул’Гуруба, і кожна з них наділена тонкою, але потужною магією.$B$BІснує дев’ять різних видів цих монет. Деякі з них користуються попитом серед моїх співвітчизників, оскільки за них герої Зандалара можуть придбати різноманітні види броні. Якщо у вас є зайві монети, я обміняю вам один із наших «Жетонів честі» на набір із трьох таких монет. Ви можете використати ці жетони у торговця Рін’вошо; він пропонує нашим героям за них особливі предмети.",
    O = "",
    P = "Я шукаю «Зразки сили», відомі як «Монети племен». Це валюта, якою користуються різні мешканці Зул’Гуруба, і кожна з них наділена тонкою, але потужною магією.$B$BІснує дев’ять різних видів цих монет. Деякі з них користуються попитом серед моїх співвітчизників, оскільки за них герої Зандалара можуть придбати різноманітні види броні. Якщо у вас є зайві монети, я обміняю набір із трьох монет на один із наших «Жетонів честі». Ви можете використати ці жетони у торговця Рін'вошо; він пропонує нашим героям за них особливі предмети.",
    C = "Чудово — цей набір монет стане чудовим доповненням до нашої колекції, що постійно зростає... і ми використаємо його для захисту племені від наступу Бога Крові. Ти заслужив цей Знак Честі, $N, а також вдячність усього племені!",
},

