[8266] = {
    en = "Ribbons of Sacrifice",
    T = "Стрічки жертви",
    D = "Я розумію, що іноді буває важко здобути перемогу в Ущелині Воєнної Пісні. Проте ваші зусилля заради нас — навіть якщо перемога не вдається — мають велике значення.$B$BЯкщо ви пройдете одне з випробувань у «Ущелині Війни пісень» і не здобудете перемоги, ви все одно отримаєте «Стрічку жертви». Принесіть її мені, щоб Стражі могли винагородити вас за те, що ви діяли в наших інтересах… навіть якщо цього разу вам не вдалося перемогти.",
    O = "Принесіть «Стрічки жертви» до Вартового Фарсонга, щоб Вартові могли винагородити вас за те, що ви діяли в наших інтересах.",
    P = "",
    C = "Що ж, ти не втік перед обличчям поразки. Ти не відступив, $N, і, зрештою, саме це й робить людину справжнім героєм. Без сумніву, наступного разу ти переможеш... але, попри все, ми дякуємо тобі за твої зусилля.",
},

[8267] = {
    en = "Ribbons of Sacrifice",
    T = "Стрічки жертви",
    D = "Я розумію, що іноді буває важко здобути перемогу в Ущелині Воєнної Пісні. Проте ваші зусилля заради нас — навіть якщо перемога не вдалася — мають велике значення.$B$BЯкщо ви пройдете одне з випробувань у «Ущелині Воєнної пісні» і не здобудете перемоги, ви все одно отримаєте «Стрічку жертви». Принесіть її мені, щоб «Передовий загін» міг винагородити вас за те, що ви діяли в наших інтересах... навіть якщо цього разу вам не вдалося перемогти.",
    O = "Принесіть «Стрічки жертви» капітану Шаттерскаллу, щоб «Авангард» міг винагородити вас за те, що ви діяли від нашого імені.",
    P = "",
    C = "Що ж, ти не втік перед обличчям поразки. Ти не відступив, $N, і, зрештою, саме це й робить людину справжнім героєм. Без сумніву, наступного разу ти переможеш... але, попри все, ми дякуємо тобі за твої зусилля.",
},

