},

[8271] = {
    en = "Hero of the Stormpike",
    T = "Герой Штормпіка",
    D = "Місцеві тролі з племені Вінтеракс — це безжальні дикуни, які понад усе мріють додати наші кістки до свого огидного рагу.$B$BМи мусимо показати їм нашу міць!$B$BМи вилучили з їхніх печер фоліанти, в яких детально описано їхню ієрархію керівництва. Ці артефакти свідчать, що їхній ватажок, Коррак Кровожер, зазвичай залишається прихованим, доки не з’явиться привід заявити про свою присутність.$B$BСмерть Коррака означатиме смерть клану Вінтеракс! Вбийте його й повертайтеся.",
    O = "Згідно з легендою, ватажок могутніх тролів Вінтеракс з’являється коли завгодно, щоб сіяти хаос серед мешканців Долини Альтерак.$B$BЯкщо Коррак дасть про себе знати, знищте його та поверніться до лейтенанта Хаггердіна в Альтеракських горах.",
    P = "Будь обережним, солдате: «Морозні вовки» теж полюють на Коррака.",
    C = "Молодці. Тепер, коли Коррак мертвий, ми можемо повністю зосередитися на вигнанні мерзенних «Морозних вовків» з цього регіону.",
},

[8272] = {
    en = "Hero of the Frostwolf",
    T = "Герой «Морозного вовка»",
    D = "Загарбники зі «Штормпайка» — не єдина загроза в цьому регіоні, солдате. В Долині війна ведеться на двох фронтах. За владу також борються тролі-канібали з племені «Зимовий сокира».$B$BЇх очолює Коррак Кровожадний — жорстока й хитра bestia.$B$BУдар по Корраку може стати нищівним ударом для клану Вінтеракс. Вбий цю bestia і отримай нагороду!",
    O = "Згідно з легендою, ватажок могутніх тролів Вінтеракс з’являється коли забажає, щоб сіяти хаос серед мешканців Долини Альтерак.$B$BЯкщо Коррак дасть про себе знати, знищте його та поверніться до воєначальника Лаггронда.",
    P = "Майте на увазі, солдате, «Штормпайк» також полює на Коррака.",
    C = "Залишилися лише армії «Штормпайк», що вторглися сюди, солдате. Молодець!",
},

[8273] = {
    en = "Oran's Gratitude",
    T = "Вдячність Орана",
    D = "",
    O = "",
    P = "",
    C = "Хіба це не цікаво? Ви кажете, що знайшли цю табличку на маленькому безлюдному острові біля скель «Оверлук» у «Глибинках», $C? Дійсно, дуже цікаво. <Оран обережно ховає планшет і потирає долоні.>$B$BДякую вам за ваші зусилля в цій справі. Наша Темна Леді буде дуже задоволена цією знахідкою. Ось, дозвольте мені винагородити вас відповідно.",
},

[8275] = {
    en = "Taking Back Silithus",
    T = "Відвоювання Сілітуса",
    D = "Увага, герої Альянсу! Загроза з боку силітидів залишалася без уваги надто довго. Не маючи жодного серйозного опору, вони весь цей час готувалися до масштабної експансії. $B$BВійська Кола Сенаріона збираються в Сілітусі, щоб дати відсіч цим жахливим істотам, і всі боєздатні мандрівники закликаються приєднатися до нас!$B$BНе чекайте, поки буде запізно! Допоможіть нам захистити Азерот! Зверніться до Віндколлера Праудхорна у Твердині Сенаріону, щоб отримати конкретні вказівки!",
    O = "Поговоріть з Віндколлером Праудхорном у фортеці Сенаріон у Сілітусі.",
    P = "",
    C = "Чудово, ще один новобранець, який відгукнувся на заклик до зброї проти силітидів. Ласкаво просимо до Цитаделі Сенаріону, $C. Мені приємно бачити, що слова наших посланців досягають героїв вашого калібру. Тут ви знайдете безліч можливостей допомогти нам у наших зусиллях, і я сподіваюся, що ви швидко доведете, що є цінним союзником нашої справи.",
},

[8276] = {
    en = "Taking Back Silithus",
    T = "Відвоювання Сілітуса",
    D = "Увага, воїни Орди! Є загроза, якій ми занадто довго не чинили опору. Землетруси поблизу гнізд силітидів по всьому Азероту сповістили нас про великі переміщення цих істот, які готуються до розширення своїх територій.$B$BВійська Кола Сенаріона збираються в Сілітусі, щоб дати відсіч силітидам, доки не стало занадто пізно! Вони більше не будуть оскверняти наші землі!$B$BУсі боєздатні воїни мають з’явитися до Вітрозакликача Праудхорна у Твердині Сенаріону! Сілітиди будуть розгромлені!",
    O = "Поговоріть із Віндколлером Праудхорном у фортеці Сенаріон у Сілітусі.",
    P = "",
    C = "Чудово, ще один новобранець відгукнувся на заклик до зброї проти силітидів. Ласкаво просимо до Цитаделі Сенаріону, $C. Мені приємно бачити, що слова наших посланців досягають героїв вашого калібру. Тут ви знайдете безліч можливостей допомогти нам у наших зусиллях, і я сподіваюся, що ви швидко доведете, що є цінним союзником нашої справи.",
},

[8277] = {
    en = "Deadly Desert Venom",
    T = "Смертельна отрута пустелі",
    D = "Бітікс Фіклеспрагг до ваших послуг! Мій двоюрідний брат Ноггл заробляє на життя, збираючи рідкісні трави для алхіміків Ценаріонського форту. Принаймні, раніше так було. З останньої подорожі він повернувся з сильною отрутою, що текла в його жилах.$B$BМені вдалося сповільнити дію отрути, але щоб повністю її нейтралізувати, мені потрібні зразки отрути того, що його вжалило.$B$BНоггл прибув з півночі, тож я готовий поставити на це свою сорочку: це, мабуть, справа рук кам’яних скорпіонів або піщаних бігунів. Принесіть мені кілька жалок і іклів, і я спробую виготовити для нього протиотруту.",
    O = "Бітікс Фіклеспрагг у фортеці Сенаріон у Сілітусі просить вас зібрати 8 жалок скорпіонів «Кам’яний батіг» та 8 іклів піщаних бігунів. Поверніться до неї, коли виконаєте завдання.",
    P = "Ти вже закінчив збирати ці зразки? Ми можемо втратити Ноггла будь-якої миті!",
    C = "Тримай кулаки, друже! Сподіваймося, що нам вдасться врятувати Ноггла!",
},

[8278] = {
    en = "Noggle's Last Hope",
    T = "Остання надія Ноггла",
    D = "Чорт забирай! Протиотрута не подіяла. Напевно, Ноггла вкусила одна з найсильніших істот з далекого півдня.$B$BМені потрібно, щоб ти поїхав туди й привіз мені ще кілька зразків, $N. Хороша новина в тому, що, оскільки їхня отрута сильніша, мені знадобиться менше зразків. Погана новина в тому, що в південній місцевості повзає більше видів отруйних істот, тож тобі доведеться збирати зразки з різних джерел.",
    O = "Бітікс Фіклеспраг у фортеці Сенаріон у Сілітусі просить вас зібрати 3 жала «Кам'яного батога», 3 жала «Шкіроздирача Кам'яного батога» та 3 ікла «Скельного мисливця».",
    P = "Це наш останній шанс врятувати Ноггла! Поспішайте!",
    C = "Так! Схоже, це спрацювало, Ноггл приходить до тями. Ми тобі дуже вдячні!",
},

[8279] = {
    en = "The Twilight Lexicon",
    T = "«Лексикон Сутінків»",
    D = "«Молот Сутінків» не щадить тих, хто покидає їхні лави. Вони й досі полюють на мене, наче я якась звірина! Зрозуміло, що їхній ворог — мій друг!$B$BЩоб розшифрувати цю табличку, мені знадобиться книга, якою користуються їхні писарі для кодування таємних повідомлень: «Лексикон Сутінків». Це настільки важливий інструмент, що три розділи книги зберігаються в різних місцях! Офіцери, яким довірено «Лексикон», відомі як «Хранителі Сутінків» — шукай їх у таборах «Молота Сутінків».",
    O = "Віднесіть три розділи «Лексикону Сутінків» до відлюдника Ортелла в Сілітусі.",
    P = "Хто там? А, це ти! Ти вже знайшов усі розділи «Лексикону»?",
    C = "Так! Ось і частини книги! Тоді давай почнемо, $N.$B$BЗаміни кожне третє слово на слова з другого розділу... а потім заміни кожне друге слово на слова з першого розділу... Хвилинку, чи я щось переплутав?",
},

[8280] = {
    en = "Securing the Supply Lines",
    T = "Забезпечення безпеки ліній постачання",
    D = "Фортеця Сенаріон — це місце, що має надзвичайне стратегічне значення. Я переконаний, що доки ми утримуємо її, наша перемога над силітидами гарантована. Звісно, за умови, що нам вдасться забезпечити безперебійне постачання.$B$BПустельні черв'яки виявилися більшою загрозою для наших караванів із провіантом, ніж навіть самі силітиди. Саме сьогодні вранці велику партію «зерна завтрашнього дня» розграбувала група нападників-дреджів. Мені потрібно, щоб ви зменшили їхню чисельність, аби забезпечити безпеку наших поставок.",
    O = "Віндколлер Праудхорн у фортеці Сенаріон у Сілітусі хоче, щоб ви вбили 15 штурмовиків Дредж.",
    P = "Страйкарі з днопоглиблювальних суден становлять серйозну загрозу, і з цим питанням треба розібратися якнайшвидше!",
    C = "Я щиро вдячний вам. Ваші зусилля, спрямовані на допомогу Цитаделі Сенаріону, стали свідченням справжньої хоробрості.",
},

[8281] = {
    en = "Stepping Up Security",
    T = "Посилення заходів безпеки",
    D = "До цього часу ти показав справді зразкову ефективність, $N. Однак наші лінії постачання ще не є цілком безпечними. За відсутності дредж-страйкерів їхні більші південні родичі неодмінно прийдуть на північ, щоб зайняти їхнє місце.$B$BВам доведеться знищити чимало дредж-крашерів, щоб тримати їх на відстані, але ми не можемо залишати безпеку наших ліній постачання на волю випадку.",
    O = "Віндколлер Праудхорн у фортеці Сенаріон у Сілітусі просить вас вбити 20 «Дредж-крашерів».",
    P = "Днопоглиблювальні дробарки становлять серйозну загрозу, і з ними потрібно негайно розібратися!",
    C = "Чудово! Ти довів, що є цінним союзником у підготовці до війни проти силітидів.",
},

[8282] = {
    en = "Noggle's Lost Satchel",
    T = "Загублена сумка Ноггла",
    D = "Де я? Де моя сумка? *задихаючись* Мабуть, я її загубив, коли тікав від Десклепса, гігантського скорпіда. У поспіху, намагаючись врятуватися, я натрапив на гніздо «каменних батогів».$B$BУ сумці, яку я ніс, були всілякі рідкісні реагенти. Без них ми з Бітіксом не зможемо виготовити зілля, які потрібні «Крепості Сенаріону». Я ще занадто слабкий, щоб підвестися, але я можу винагородити тебе, якщо ти принесеш мої реагенти.$B$BЯ зіткнувся з Десклапсом у південному гірському масиві, за табором Бронзоборода.",
    O = "Знайдіть сумку Ноггла в горах на півдні Сілітуса та поверніть її йому в Цитаделі Сенаріону.",
    P = "Все ще не знайшов свою сумку? Ну що ж, треба дякувати долі — принаймні отрута вже виведена з організму.",
    C = "Так! Ти повернув мою сумку. І всі мої рідкісні реагенти на місці! Я буду тобі в боргу ще довго.",
},

[8283] = {
    en = "Wanted - Deathclasp, Terror of the Sands",
    T = "Розшукується — «Смертельний захват», «Жах пісків»",
    D = "Вважається, що жахливий скорпід «Смертельний захват» відступив до південного гірського хребта через посилення активності силітидів. Вона становить велику загрозу для патрулів та експедицій у південних регіонах. Тим, хто візьме участь у її знищенні, буде виплачено щедру винагороду. Щодо винагороди звертайтеся до капітана Віша Козуса, який перебуває на вершині сторожової вежі Ценаріонського форту.",
    O = "Принесіть «Клешню Смерті» Вішу Козусу, капітану гвардії.",
    P = "Мені знадобиться клешня цієї істоти як доказ виконання завдання. Немає клешні — немає винагороди.",
    C = "Чудово! Тепер, коли «Смертельний захват» знищено, ми можемо вільно використовувати південний гірський хребет як стратегічний шлях для обходу гнізд силітидів. Ми дуже цінуємо вашу роботу.",
},

[8284] = {
    en = "The Twilight Mystery",
    T = "Таємниця сутінків",
    D = "Колись на північному заході від цього місця процвітав табір прихильників культу «Молота Сутінків». Якщо ви зараз наважитеся вирушити туди, то побачите, що ця місцевість кишить елементалями, а про те, де колись був табір, свідчать лише розкидані шматки дерева та полотна.$B$BЯ знайшов на цьому місці кілька уламків глиняної таблички, але їх занадто мало, щоб скласти з них щось корисне. Спробуйте знайти решту уламків таблички, щоб ми змогли пролити світло на присутність «Молота Сутінків» тут, у Сілітусі.",
    O = "Геолог Ларксбейн у фортеці Сенаріон у Сілітусі просить вас зібрати 8 уламків табличок Сутінків.",
    P = "Розорений табір знаходиться на північний захід від цього місця. Повертайся, коли збереш усі уламки.",
    C = "Як я й підозрював. Я можу розшифрувати окремі слова на табличках, але вони, здається, позбавлені будь-якої логіки чи сенсу. Секти «Молота Сутінків» нерідко використовують шифри, щоб приховати зміст своїх текстів; нам доведеться звернутися до когось, хто краще розбирається в таких речах.",
},

[8285] = {
    en = "The Deserter",
    T = "Дезертир",
    D = "Ходять чутки, що член «Молота Сутінків» на ім’я Ортелл зрадив свою секту. Кажуть, він сховався в горах на південь від селища Саутвінд, де живе відлюдником. Можливо, ви зможете заручитися його допомогою у розшифровці таблички.$B$BВізьміть відреставровану табличку з собою та знайдіть Ортелла.",
    O = "Віднесіть відреставровану табличку до відлюдника Ортелла в Сілітусі.$B",
    P = "Ти! Як ти мене знайшов? Хто ти такий? За тобою ж ніхто не стежив, правда? Говори!",
    C = "Бачу, ти знайомий з моєю колишньою організацією. Мабуть, ти з «Цінаріонського форту». $B$BТи шукаєш інформацію, щоб використати її проти них? Підійди ближче, можливо, ми зможемо допомогти одне одному.",
},

[8286] = {
    en = "What Tomorrow Brings",
    T = "Що принесе завтра",
    D = "Обійми смерті вже майже охопили моє єство, коли він втрутився. Він лише раз подув на моє понівечене тіло, а потім терпляче чекав, поки піски часу очистять мої рани.$B$B«Ти залишишся тут назавжди, якщо доведеться», — сказав він, і цими словами я став Спостерігачем.$B$BА тепер поглянь на пустелю. На нас насувається друга війна. Ти мусиш відшукати місце спочинку Бронзового. Відправись до Печер Часу й дізнайся, чи повернувся володар. Я мушу бути впевненим, перш ніж зможу рухатися далі.",
    O = "Відправляйтеся до Печер Часу в Танарісі та знайдіть Анахроноса, нащадка Ноздорму.",
    P = "Чи повернувся Анахронос?",
    C = "Все так, як і має бути — Великий воскрес. Моя варта добігає кінця...",
},

[8287] = {
    en = "A Terrible Purpose",
    T = "Жахлива мета",
    D = "Гаразд, ось ми й тут… Мушу сказати, це досить цінна інформація! Я бачив, як війська «Круга Сенаріону» прибули до Сілітуса. Вони планують вигнати «Молот Сутінків», чи не так? Це стане в нагоді. $B$BВіднеси цей пергамент їхньому ватажкові, командиру Мараліту. Незабаром «Молот Сутінків» буде розгромлено, і я назавжди вирвуся з їхніх лап!",
    O = "Віднесіть пергамент із розшифрованою табличкою командиру Мараліту.",
    P = "Що це ти мені приніс, $N?",
    C = "Це справді дуже цікава інформація, $N. Вона проливає світло на присутність «Молота Сутінків» у Сілітусі та, безсумнівно, допоможе нам у боротьбі проти них. Ваші зусилля будуть щедро винагороджені, $C.",
},

[8288] = {
    en = "Only One May Rise",
    T = "Лише один може перемогти",
    D = "Немає часу гаяти! Треба знайти героя! Для виконання завдання, яке я даю, знадобиться ціла армія, але лише один із натовпу претендентів на звання чемпіона зможе взяти на себе тягар і відповідальність союзника Роду.$B$BУ лігві Володаря Чорної Скелі мешкає найжорстокіша звір. Володар Рою Лашлейер охороняє Зали Розбрату, перекриваючи шлях до внутрішнього святилища Нефаріана. Вбий цю огидну потвору й принеси мені його голову. Зроби це — і ти зможеш перейти до наступного етапу своєї подорожі.",
    O = "Поверніть голову Брудлорда Лашлеєра Барістольту з «Мінливих пісків» у фортеці Сенаріон у Сілітусі.",
    P = "Ви повинні заслужити прихильність Потомства Ноздорму.",
    C = "Чи зможете ви стати першим за тисячу років, хто здобуде прихильність Бронзового зграї?",
},

