[8290] = {
    en = "Vanquish the Invaders!",
    T = "Знищте загарбників!",
    D = "За цим тунелем на тебе чекає поле битв і хаосу, юний $c. Орда продовжує знищувати наш священний ліс, вирубуючи вічнозелені дерева, щоб заправити ними свої бойові машини.$B$BУвійди в Ущелину Воєнної Пісні та захисти фортецю Срібне Крило. Відкиньте вторгнення військ Орди!$B$BЗробіть це — і отримайте талісман за заслуги. Принесіть мені такий талісман, $N, і я винагороджу вас.",
    O = "Увійдіть до Ущелини «Військової пісні» та переможіть Орду, отримайте Знак честі Ущелини «Військової пісні» і поверніться до вартового Фарсонга у Гайі Срібного Крила.",
    P = "Чи брали ви участь у боях у «Ущелині Воєнної Пісні» та захищали «Твердиню Срібного Крила»?",
    C = "Ти довів свою цінність для наших зусиль у «Ущелині Воєнної Пісні». Продовжуй допомагати нашій справі та принось мені більше «Знаків честі». Зроби це, і ти завоюєш ще більшу довіру з нашого боку.",
},

[8291] = {
    en = "Vanquish the Invaders!",
    T = "Знищіть загарбників!",
    D = "За цим тунелем на тебе чекає поле битви та хаосу, юний $c. Орда продовжує нищити наш священний ліс, вирубуючи вічнозелені дерева, щоб забезпечити паливом свої бойові машини.$B$BУвійди до Ущелини Воєнної Пісні та захисти Твердиню Срібного Крила. Відкинь нападників з Орди!$B$BЗроби це, і ти отримаєш Знак Честі. Принеси його мені, $N, і я винагороджу тебе.",
    O = "Увійдіть до Ущелини «Військової пісні» та переможіть Орду, отримайте Знак честі Ущелини «Військової пісні» і поверніться до вартового Фарсонга в Гаї Срібного Крила.",
    P = "Чи брали ви участь у боях у Ущелині Воєнної Пісні та захищали Твердиню Срібного Крила?",
    C = "Ти довів свою цінність для наших зусиль у «Ущелині Воєнної пісні». Продовжуй допомагати нашій справі та принось мені ще більше «Знаків честі». Зроби це — і ти завоюєш ще більшу довіру з нашого боку.",
},

[8292] = {
    en = "Marks of Honor",
    T = "Знаки честі",
    D = "",
    O = "",
    P = "Ти заслужив очки за останнє завдання. Принеси мені ще «Знак честі» — і отримаєш нагороду.",
    C = "Дякую, $N. Твої подвиги в Ущелині «Воєнної пісні» відлунюють по всьому Лісі Попелу.",
},

[8293] = {
    en = "Marks of Honor",
    T = "Знаки честі",
    D = "",
    O = "",
    P = "Ти отримав очки за останнє завдання. Принеси мені ще «Знаків честі» — і отримаєш нагороду.",
    C = "Нічні ельфи та їхні союзники мають тремтіти навіть від самого шепоту твого імені! За Орду!$B$BТи довів свою цінність для нашої справи в Ущелині Воєнної Пісні. Продовжуй лютувати проти Срібнокрилих Вартових! Принеси мені ще більше Знаків Честі!",
},

[8294] = {
    en = "Quell the Silverwing Usurpers",
    T = "Зупиніть узурпаторів Срібного крила",
    D = "Дикі простори лісу Ешенвейл підкоряться могутності Орди, $r. Ніщо з того, що скажуть чи зроблять Сріблясті крила, не зможе зупинити наш суверенний імператив. Калімдор належить Орді. Як вони сміють намагатися завадити нам забрати те, що по праву належить нам!$B$BНехай гордість наповнює твоє серце, коли ти знищуєш їхні кволі спроби уповільнити наш поступ. Знищте вартових «Срібного крила» та заробіть Знак честі. Поверніться до мене з цим Знаком, $N, і ви отримаєте нагороду.$B",
    O = "Увійдіть до Ущелини «Військової пісні» та переможіть Альянс, отримайте Знак честі Ущелини «Військової пісні» і принесіть його капітану Шаттерскаллу в табір Мор'шан.",
    P = "Кров наших ворогів — це знак честі. Чи є у тебе такий знак?",
    C = "<Капітан Шеттерскалл тріумфально реве>$B$BСкільки ще вони зможуть витримати? Скільки ще мерзоти Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, $R...",
},

[8295] = {
    en = "Quell the Silverwing Usurpers",
    T = "Зупиніть узурпаторів «Срібного крила»",
    D = "Дикі простори лісу Ешенвейл підкоряться могутності Орди, $r. Жодні слова чи дії Сріблястокрилих не зможуть зупинити наш неминучий порив. Калімдор належить Орді. Як вони сміють намагатися завадити нам забрати те, що по праву належить нам!$B$BНехай гордість наповнює твою груди, коли ти знищуєш їхні кволі спроби уповільнити наш поступ. Знищ вартових «Срібного крила» і зароби знак честі «Воєнної пісні». Поверніться до мене з таким знаком, $N, і ви отримаєте нагороду.$B",
    O = "Увійдіть до Ущелини «Військової пісні» та переможіть Альянс, отримайте Знак честі Ущелини «Військової пісні» і принесіть його капітану Шаттерскаллу в табір Мор’шан.",
    P = "Кров наших ворогів — це знак честі. Чи є у тебе такий знак?",
    C = "<Капітан Шаттерскалл тріумфально реве>$B$BСкільки ще вони зможуть витримати? Скільки ще мерзоти Альянсу має загинути від рук Орди, щоб вони відступили? Тільки час покаже, $R...",
},

