},

[8299] = {
    en = "Cut Arathor Supply Lines",
    T = "Перерізати лінії постачання Аратора",
    D = "Ліга Аратора не шкодує коштів у своїх зусиллях з відвоювання Араті. Вони, а також усі раси Альянсу, зараз прямують до цього віддаленого регіону, маючи намір розширити свою територію від Мису Притулку. Ми мусимо їх зупинити, і найкращий спосіб це зробити — позбавити їх запасів.$B$BТи можеш нам допомогти, $N. Увійди в Аратську улоговину, відому своїми багатими копальнями, родючими землями та вправними ремісниками. Захопи та утримуй кожну базу, яку зможеш, виграй битву та повернися до мене з Знаком честі, який ти здобудеш.",
    O = "Виграйте битву за Аратську улоговину, отримайте «Знак честі Аратської улоговини» та поверніть його Смертошукачу Мортісу в Хаммерфолі.",
    P = "Що це, $R? У тебе є «Знаки честі»? Повертайся до Аратської улоговини, знищ шкідників Альянсу та захопи їхні ресурси для Темної Леді!",
    C = "<Десстalker Мортіс посміхається>$B$BНашим ворогам було завдано ще одного вирішального удару, $n. Завдяки твоїм подвигам Аратська улоговина незабаром перейде під контроль Осквернителів.",
},

[8300] = {
    en = "More Arathi Basin Marks of Honor",
    T = "Більше знаків честі з Аратської улоговини",
    D = "",
    O = "",
    P = "$N, у «Осквернителів» для тебе є постійне завдання: повернутися в Аратську улоговину, зібрати більше знаків честі та принести їх мені.",
    C = "Дуже добре. Я негайно передам це нашим інтендантам, а моїм начальникам буде надіслано подяку за ваші дії.$B$BЩе раз дякую $N. Ваш внесок у нашу боротьбу помічають як прості солдати, так і високопоставлені воєначальники.",
},

[8301] = {
    en = "The Path of the Righteous",
    T = "Шлях праведних",
    D = "Потомство Ноздорму від природи ставиться з недовірою до нижчих рас. Хоча ти й довів мені, що маєш задатки героя, настав час довести це моєму господареві.$B$BХайв'Аші, Хайв'Зора, Хайв'Регал: усі вони кишать життям і становлять загрозу для нашого існування. Вбий силітидів у цих вуликах і візьми у них по фрагменту панцира. Коли не зможеш нести більше, повернися до мене, і я зміцню твою рішучість.",
    O = "Зберіть 200 уламків панцира силітидів і поверніться до Барістолта.",
    P = "Їхня недовіра до смертних рас має глибоке історичне коріння; але, на жаль, цю історію краще залишити для «Роду», щоб він розповів її, коли настане відповідний час.",
    C = "Ти не самотній, герою. Зараз я надам тобі можливість призначати помічників, які допомагатимуть тобі у твоїх подорожах. Якщо ти маєш стати захисником свого народу, тобі знадобиться допомога у виконанні твоїх завдань та обов’язків.",
},

[8302] = {
    en = "The Hand of the Righteous",
    T = "Рука праведника",
    D = "Вибирай своїх помічників з розумом, смертний. Щоразу, коли ти повертатимешся, виконавши завдання, тобі дозволять обрати нового помічника.$B$BТож я вимагаю більше уламків панцира. Не гай часу!",
    O = "Зберіть 200 уламків панцира силітидів і поверніться до Барістолта.",
    P = "Можливо, одного дня вся фортеця Сенаріон працюватиме під твоїм керівництвом.",
    C = "Молодець, герою. Тепер ти отримаєш можливість призначити заступником іншого агента Ноздорму.",
},

[8303] = {
    en = "Anachronos",
    T = "Анахронос",
    D = "Настав час, $N.$B$BЯ мушу вибачитися за те, що так довго тримав це в таємниці. Ворогів безліч, навіть прямо під нашим носом. Будь ласка, прочитай цю книгу й навчися. Візьми знання, які я тобі даю, і знайди нашого вчителя.",
    O = "Знайдіть Анахроноса в Печерах Часу в Танарісі.",
    P = "",
    C = "Ти — надія Калімдора, $N.",
},

[8304] = {
    en = "Dearest Natalia",
    T = "Найдорожча Наталя",
    D = "Моя дорога Наталія зникла безвісти.$B$BЧесно кажучи, вона поводилася дивно вже кілька тижнів до свого зникнення. Я не раз ловив її на тому, що вона розмовляла сама з собою, коли навколо нікого не було. Вона наполягала, що все гаразд і що їй треба дозволити продовжувати дослідження.$B$BВостаннє її бачили, коли вона прямувала до табору Бронзобородого на півдні.$B$BМоїх солдатів занадто мало, $N. Мені потрібно, щоб ти вирушив до табору Бронзоборода і допитав тих гномів.",
    O = "Командир Мараліт у фортеці Сенаріон на Сілітусі просить вас допитати мешканців табору Бронзоборода. Табір Бронзоборода знаходиться на південь від фортеці Сенаріон.$B$BЗібравши необхідну інформацію, поверніться до командира Мараліта.",
    P = "Не гай часу, $N!",
    C = "<Командир Мараліт задумливо схиляє голову.>$B$BНезалежно від того, жива вона чи мертва, я мушу вчинити правильно. Її треба знайти. На жаль, я пов’язаний обов’язками щодо цього форпосту. Чи допоможеш ти мені ще раз, $N?",
},

[8305] = {
    en = "Long Forgotten Memories",
    T = "Давно забуті спогади",
    D = "У південній пустелі Сілітус, неподалік від священного бар’єру, знаходиться єдина кристалічна сльоза. Ця сльоза є символом великих втрат, яких ми зазнали під час Війни рухомих пісків. Знайдіть цю сльозу та зазирніть у її глибини, щоб досягти просвітлення.$B",
    O = "Знайдіть «Кристалічну сльозу» в Сілітусі та зазирніть у її глибини.",
    P = "",
    C = "Ви відчуваєте величезний смуток, що витає навколо цього кристала. Ця сила настільки потужна, що вам здається, ніби ви ось-ось знепритомнієте й помрете від смутку.",
},

[8306] = {
    en = "Into The Maw of Madness",
    T = "У пащу божевілля",
    D = "Мені потрібно, щоб ти відправився до «Хайв’Регал» і з’ясував, що сталося з моєю найдорожчою Наталією, $N. Це буде для тебе нелегким завданням. Перш ніж стрибнути з головою у пащу божевілля, обов’язково повернися й поговори з тими гномами. Можливо, вони зможуть дати тобі кілька порад щодо того, як впоратися з силітидами, що мешкають у цьому вулику.$B$BІ $N, якщо вона справді така божевільна, як про неї кажуть... роби те, що мусиш.$B$B<Командир Мар'аліт відвертається від тебе.>$B",
    O = "Командир Мар’аліт із фортеці Сенаріон у Сілітусі просить вас знайти його кохану Наталію. Зібрана вами інформація вказує на те, що пані Наталію Мар’аліт можна знайти в районі Хайв’Регал на півдні.$B$BНе забудьте завітати до гномів у таборі Бронзоборода, перш ніж вирушати до «Хайв-Регал». Можливо, вони матимуть для вас додаткове завдання та поради.$B$BІ $N, пам'ятайте слова командира: «Робіть те, що мусите...»",
    P = "Наталія?",
    C = "<Командир Мараліт притискає руку до грудей.>$B$BК'Тхун? Що це все означає? Хто такий К'Тхун? Як цей нечистий зміг перетворити мою милу Наталію на того монстра, якого ти описав?",
},

[8307] = {
    en = "Desert Recipe",
    T = "Рецепт «Пустеля»",
    D = "Пристосуватися до життя в пустелі було, м'яко кажучи, нелегко. Я не тільки сумую за птахами та деревами Обердіна, але й наш вибір їжі суттєво обмежений через це посушливе середовище. Я намагаюся дізнатися більше про пустельні трави, але їх небагато.$B$BЯ бачила, як групи «Молота Сутінків» з табору на захід від нас полюють на піщаних черв’яків, щоб прогодуватися. М’ясо піщаних черв’яків таке гірке, що я навіть уявити не можу, як їм вдається зробити його їстівним. Будьте пильні, якщо підете до їхнього табору, і дайте мені знати, якщо дізнаєтеся щось нове.",
    O = "Шукайте інформацію про приготування м’яса піщаного черв’яка в таборі «Молот Сутінків», що на захід від Цитаделі Сенаріону.",
    P = "",
    C = "Ця книга містить кілька звичайних рецептів і декілька незвичайних. Проглянувши її протягом кількох секунд, ви натрапляєте на рецепт, у якому використовується м’ясо піщаного черв’яка.",
},

[8308] = {
    en = "Brann Bronzebeard's Lost Letter",
    T = "Загублений лист Бранна Бронзобородого",
    D = "До відома всіх, кого це стосується:$B$BЯкщо ви це читаєте, то я або вже мертвий, або незабаром помру. Важко сказати. У будь-якому разі, більшість екіпажу вже мертва.$B$BЗнайшов інформацію про Титана. Велика битва між ним і Старим Богом. Так, справжнім Старим Богом. Знайшов стародавній тунель, що веде до Ан’Кіраджа. Йду туди.$B$BВіднесіть цей лист до мого старого табору. Подбайте, щоб моя мавпа отримувала достатньо їжі, води та обіймів.$B$B— Бранн Бронзобородий, Екстремальний Дослідник$B$BP.S. Стережіться божевільного нічного ельфа, який поклоняється Старому Богу.",
    O = "Віднесіть лист Бранна Бронзобородого до табору Бронзобородих на півдні Сілітуса.",
    P = "Ой, лишенько.",
    C = "Ну, це багато що пояснює. Якщо тобі колись вдасться пробратися в Ан’Кірадж, придивляйся до старого Бранна. Боюся, що без своєї мавпи він буде безсилий.",
},

[8309] = {
    en = "Glyph Chasing",
    T = "Полювання за гліфами",
    D = "Після нашого першого проникнення у вулики та подальшого божевілля пані Мараліт ці три вулики просто вивергають комах! Підвищена активність може бути пов’язана з гліфами, що вкривають ті дивні кристали.$B$BМи мусимо зробити знімки з кристалів у всіх трьох вуликах. Якщо нам вдасться отримати ці зліпки, ми, можливо, зможемо розібратися в цьому божевіллі.$B$BВізьми цей набір для зліпків і вирушай до цих вуликів, $N. Не повертайся, доки не отримаєш зліпки з кожного вулика.",
    O = "Рутгар Гліфшейпер у таборі Бронзоборода в Сілітусі просить вас відправитися до Хів'Аші, Хів'Зори та Хів'Регалу й дістати відбитки гліфів з кристалів з гліфами у кожному з цих вуликів.$B$BВикористовуйте набір геолога для транскрипції, щоб створити точну копію стародавніх гліфів. Поверніться до Рутгара Гліфшейпера, коли виконаєте це завдання.",
    P = "Якщо ти натрапиш у якомусь з «вуликів» на якусь божевільну дівчину-нічного ельфа, не забудь дати їй від нас копняка під зад.",
    C = "Я ніяк не можу розібратися в цих знаках. Нічого подібного я ще ніколи не бачив! Сподіваюся, дослідження Франкала допоможуть пролити світло на цю плутанину.",
},

[8310] = {
    en = "Breaking the Code",
    T = "Розшифровка коду",
    D = "Гадаю, я зможу створити еліксир, який допоможе нам легше розшифрувати символи та мову силітидів і кіраджі! Що мені для цього потрібно? Радий, що ти запитав! Мені потрібні мізки! А точніше — по одному мозку від кожного виду силітидів, що мешкають у вуликах. Принеси мені ці мізки, і робота Рутгара, можливо, не піде намарне.",
    O = "Франкал Стоунбрідж у таборі Бронзбірда в Сілітусі просить вас дістати мозок силітіда «Хайв'Зора», мозок силітіда «Хайв'Аші» та мозок силітіда «Хайв'Регал». Поверніться до Франкала, коли виконаєте це завдання.",
    P = "Іди пограйся з мавпочкою, малюку. У мене немає на це часу.",
    C = "Чудово! Не відходь занадто далеко, хлопче. Можливо, тобі доведеться виконати ще одне-два завдання.",
},

[8311] = {
    en = "Hallow's End Treats for Jesper!",
    T = "Солодощі на Хелловін для Джеспера!",
    D = "Я хочу піти по домівках за цукерками, але не можу, бо захворів. Якщо ти підеш замість мене, я обміняю цукерки, які ти принесеш, на ті, що вже маю! Гадаю, ці цукерки тобі сподобаються — вони перетворюють тебе на різні кумедні й страшні істоти!$B$BУ великих містах кожен власник готелю роздає цукерки на свято «Кінець Хеллоуїна» — поговори з ними й виконай завдання, які вони тобі дадуть! Також маленький гном на ім’я Талваш в Айронфорзі теж роздає цукерки. Коли ти збереш усі цукерки, принеси їх мені сюди!",
    O = "Поговоріть із господарями готелів у Штормвінд, Айронфорджі та Дарнассусі, а також із Талвашем дель Кісселем в Айронфорджі. Виконайте трюки, про які вони вас попросять, в обмін на ласощі, які вони пропонують.$B$BПоверніться до Джеспера в притулку Штормвінда з марципаном з Дарнассуса, желейною цукеркою з Гномерегана, нугою зі Штормвінда та м'ятною цукеркою з Айронфорджа.",
    P = "Ти вже закінчив ходити по домівках за цукерками? Мені шкода, що я не можу піти, бо захворів, але те, що ти мені допомагаєш, трохи піднімає мені настрій...",
    C = "Ого, ти зібрав їх усі! Ти просто супер!$B$BДякую, що ходив за цукерками замість мене. Ось, візьми ці гарбузові ласощі — думаю, вони тобі дуже сподобаються!$B$BЗ Днем Хеллоуїна, $N!",
},

[8312] = {
    en = "Hallow's End Treats for Spoops!",
    T = "Смаколики на Хелловін для «Спупів»!",
    D = "Я хочу піти по цукерки, але не можу, бо захворів. Якщо ти підеш замість мене, я обміняю цукерки, які ти отримаєш, на ті, що вже маю! Гадаю, ці цукерки тобі сподобаються — вони перетворюють тебе на щось і смішне, і страшне!$B$BУ кожному великому місті власники готелів роздають цукерки на свято «Кінець Хеллоуїна» — поговори з ними й виконай завдання, які вони тобі дадуть! Також цукерки роздає троль на ім’я Калі Ремік у селі Сен’джин. Коли ти збереш усі цукерки, принеси їх мені сюди!",
    O = "Поговоріть із власниками готелів в Оргримарі, Андерсіті та Громовому Утворі, а також із Калі Ремік у селі Сен'джин. Виконайте трюки, про які вони вас попросять, в обмін на ласощі, які вони пропонують.$B$BПоверніться до Спупса в сирітському притулку Оргримара з марципаном із Громового Утвезу, желейними цукерками «Темний Спис», нугою з Оргримара та м'ятними цукерками з Підземного міста.",
    P = "Ти вже закінчив ходити по домівках за цукерками? Мені шкода, що я не можу піти, бо захворів, але те, що ти мені допомагаєш, трохи піднімає мені настрій...",
    C = "Ого, ти зібрав їх усі! Ти просто супер!$B$BДякую, що ходив за цукерками за мене. Ось, візьми ці гарбузові ласощі — думаю, вони тобі дуже сподобаються!$B$BЗі святом Хеллоуїну, $N!",
},

[8313] = {
    en = "Sharing the Knowledge",
    T = "Обмін знаннями",
    D = "Хоча рецепт приготування м’яса піщаного черв’яка написаний розбірливо, у ньому згадуються трави та спеції, про які ти ніколи не чув. Каландрат, можливо, достатньо добре знається на рослинах, що ростуть у пустелі, щоб розібратися в цьому.",
    O = "Віднесіть зіпсовану сторінку з рецептом Каландрату в корчмі в Ценаріон-Холді.",
    P = "Ви запам'ятали рецепт? Сподіваюся, ви не залишите його тільки для себе!",
    C = "Давайте подивимося на це...$B$BЗдається, це досить просто. У них є свої власні назви для деяких трав, але їх досить легко розібратися. Ось, я вам покажу!",
},

[8314] = {
    en = "Unraveling the Mystery",
    T = "Розкриття таємниці",
    D = "Ми на порозі прориву, $N! Зроблені тобою знімки дозволили нам відтворити символи на цій кристалічній призмі. Судячи з усього, вони є засобом, за допомогою якого кіраджі та інші невідомі істоти передають різні повідомлення силітидам.$B$BНа жаль, це все, що нам вдалося розшифрувати з цих символів. Нам потрібно знайти спосіб розшифрувати повідомлення, приховані в кристалах.$B$BВіднесіть кристалічну призму з ієрогліфами геологу Ларксбейн у Цитаделі Сенаріону. Можливо, вона зможе допомогти.",
    O = "Рутгар Гліфшейпер у таборі Бронзоборода просить вас доставити «Кришталеву призму з гліфами» геологу Ларксбейну в фортеці Сенаріон у Сілітусі.",
    P = "Ой! Що це у тебе там, $N?",
    C = "Причина, через яку гноми не змогли розшифрувати символи, полягає в тому, що розшифровувати тут нічого. Щоб повідомлення було передано, рухомий зовнішній шар призми має точно збігатися з позначками на внутрішньому кристалі. Розумно...$B$BХоча ми й повинні змогти перекласти ці дані, спершу треба розшифрувати код. На поверхні призми є лише одна підказка — якщо, звичайно, знімки були зроблені правильно — і вона виглядає невтішно.",
},

[8315] = {
    en = "The Calling",
    T = "Покликання",
    D = "На гліфах зображено посланця Кіраджі, який зустрічається з трьома силітидами біля кісток великого дракона. Над гліфами — те, що я можу розцінити лише як якийсь код. Цей код цілком може бути ключем до виклику посланця.$B$BЯ створю копію коду з гліфів, яку ти повинен використати на піску біля Кісток Гракаронда. Якщо я правий, Повелителі прийдуть, думаючи, що нові дані готові до передачі. Знищ їх і зіткнися з посланцем. Він володіє ключем до кристалів...",
    O = "Геолог Ларксбейн у фортеці Сенаріон у Сілітусі просить вас відібрати кристалічний механізм розблокування у посланця Кіраджі.$B$BВам доручено віднести «Гліфи Покликання» до Кісток Граккаронда, що на південь від фортеці Сенаріон, і намалювати їх на піску. Якщо з'явиться посланець Кіраджі, вбийте його та заберіть кристалічний механізм розблокування. Якщо вам це вдасться, поверніться до геолога Ларксбейна.$B$BЗберіть армію для виконання цього завдання, $N!",
    P = "Треба скористатися нагодою, що трапилася, і діяти!",
    C = "У моїх руках — 20 000 років історії, $N!",
},

[8316] = {
    en = "Armaments of War",
    T = "Військова техніка",
    D = "",
    O = "",
    P = "",
    C = "Настає війна, $N, а разом із нею — невимовні жахи. Ти зробив усе, чого від тебе могли вимагати, і за це ти заслуговуєш на нагороду.$B$BЯкщо це... це пророцтво колись збудеться...$B$B<Геолог Ларксбейн зблід.>$B$BНаше спільне майбутнє може опинитися під загрозою.$B$BЦя зброя стане неоціненною підмогою у вашій кампанії в цій пустелі.",
},

[8317] = {
    en = "Kitchen Assistance",
    T = "Допомога на кухні",
    D = "Цей рецепт точно стане в нагоді. Мені краще взятися за роботу, щоб сьогодні встигнути приготувати копчені десертні вареники. Мені б не завадила допомога в їх приготуванні — я так віддячу, що тобі це вийде вигідно.",
    O = "Каландрат у Цитаделі Сенаріону потребує партію з 10 копчених пустельних пельменів.",
    P = "Як там справи з варениками?",
    C = "Чудово! Ви мене врятували. Ці вареники вийшли досить смачними. Не очікував, що «Молот Сутінків» зможе створити щось настільки смачне.",
},

[8318] = {
    en = "Secret Communication",
    T = "Таємне спілкування",
    D = "Деякі члени культу «Молота Сутінків» носять із собою маленькі папірці з написаним на них безглуздим текстом. Я хочу, щоб ти приніс мені стос таких папірців, $c.$B$BЯ не можу розібратися, що означає цей безглуздий текст, але це не має значення! За допомогою цих папірців різні групи культу таємно спілкуються між собою. Чим більше папірців ми вилучимо з обігу, тим менше вони зможуть спілкуватися!",
    O = "Принесіть 10 зашифрованих сутінкових текстів Бору Вайлдмейну в Цитадель Сенаріону.",
    P = "Ти приніс мені якісь тексти?",
    C = "Чудово! Я їх збережу, може, вони ще знадобляться.",
},

[8319] = {
