    P = "Скажи, які новини з фронту?",
    C = "Молодець, солдате! Продовжуй у тому ж дусі, і ми змусимо Орду втекти аж до Оргримара.",
},

[8385] = {
    en = "Concerted Efforts",
    T = "Спільні зусилля",
    D = "Ах, $N. Сподіваюся, ти й надалі ділитимешся своїм досвідом на різних фронтах. Багато наших хлопців і дівчат на передовій беруть приклад із таких досвідчених ветеранів, як ти.",
    O = "Принесіть 3 «Знаки честі» з Долини Альтерака, 3 «Знаки честі» з Аратського басейну та 3 «Знаки честі» з Ущелини Військової пісні бригадному генералу Альянсу, що перебуває за межами полів бою.",
    P = "Ах, $N. Сподіваюся, ти й надалі ділитимешся своїм досвідом на різних фронтах. Багато наших хлопців і дівчат на передовій беруть приклад із таких досвідчених ветеранів, як ти.",
    C = "Ти справді виправдовуєш свою репутацію, $N. Без таких людей, як ти, Альянс не мав би жодних шансів проти диких військ Орди.",
},

[8386] = {
    en = "Fight for Warsong Gulch",
    T = "Битва за Ущелину Воєнної Пісні",
    D = "«Срібнокрилі вартові» ведуть війну з «Військовими вершниками» через руйнування, які орки завдають лісу. Однак є й інші причини захищати саме цей ліс, окрім простої любові до природи.$B$BЛіс утворює стратегічний бар'єр, завдяки якому Ашенвейл можна захистити від масштабного нападу. Без нього Астранаар протримався б день-два, перш ніж його приєднали б до Пусток.$B$BЗробіть свій внесок у боротьбу з «Варсонговими розвідниками», $N! За Альянс!",
    O = "Принесіть 3 «Знаки честі» з Ущелини Воєнних пісень бригадному генералу Альянсу, що знаходиться за межами поля бою.",
    P = "Ти повернувся з новинами з фронту, $N?",
    C = "Молодець, $N! Ти гідно служив Альянсу.",
},

[8387] = {
    en = "Invaders of Alterac Valley",
    T = "Загарбники Долини Альтерак",
    D = "Битва за Альтерак триває! Ти повинен повернутися до Долини Альтерак і вкотре вигнати загарбників з території Морозних Вовків, $N!",
    O = "Принесіть 3 «Знаки честі Долини Альтерака» воєначальнику Орди, що перебуває за межами поля бою.",
    P = "Битва за Альтерак триває! Ти повинен повернутися до Долини Альтерак і вкотре вигнати загарбників з території Морозного Вовка, $N!",
    C = "Молодець, $N! Ти можеш пишатися собою. Загарбників Альянсу треба вигнати з Альтерака!",
},

[8388] = {
    en = "For Great Honor",
    T = "Заради великої честі",
    D = "Багато відважних бійців дивляться на тебе, $N. Ти й надалі залишаєшся прикладом для всіх у боротьбі проти Альянсу. Які новини ти приніс зі своїх подорожей?",
    O = "Принесіть 3 знаки честі «Долини Альтерака», 3 знаки честі «Басейну Араті» та 3 знаки честі «Ущелини Військової Пісні» до посланця Орди, що знаходиться за межами полів бою.",
    P = "Араті досі залита кров’ю великих воїнів, а звуки зіткнення сталі досі лунають по всьому Альтераку. Не марнуйте мій час, якщо не принесли новин з фронту!",
    C = "Ти й досі відданий Орді, $N. Радий бачити, що ти не розм'як.",
},

[8389] = {
    en = "Battle of Warsong Gulch",
    T = "Битва за Ущелину Воєнної Пісні",
    D = "Битва в Ущелині Воєнних Пісень проти Срібнокрилих Вартових має величезне значення. Під приводом захисту лісу, який їм не належить, Альянс прагне позбавити Орду одного з наших найбільших джерел деревини.$B$BНе допустіть цього, $N! Поверніться до мене з доказом того, що ви гідно служили Орді!",
    O = "Принесіть 3 «Знаки честі Воєнної пісні» воєнному посланцю Орди, що перебуває за межами полів бою.",
    P = "Битва в Ущелині Воєнних Пісень триває, $N. Зроби свій внесок, щоб вигнати Срібнокрилих Вартових з наших земель!",
    C = "Чудово! Ти довів свою цінність, захистивши наші позиції в Ущелині Війни Пісень! Нехай звістка про твою честь рознесеться по всьому нашому краю.",
},

[8390] = {
    en = "Conquering Arathi Basin",
    T = "Завоювання Аратської улоговини",
