},

[8499] = {
    en = "The Alliance Needs Thorium Bars!",
    T = "Альянсу потрібні торієві стрижні!",
    D = "Дуже мило з вашого боку поцікавитися потребами Альянсу. Окрім усіх інших заходів зі збору ресурсів, що наразі тривають, нам потрібна велика кількість торієвих брусків — саме за це я відповідаю. Торій буде використано для створення багатьох різних речей, необхідних для війни, насамперед для будівництва батальйону парових танків, які будуть доставлені повітрям до Сілітусу, щойно їх буде завершено. Чи можете ви допомогти нам у цій справі, $c?",
    O = "Принесіть 20 брусок торію леді Твінбрейд у Військовому кварталі в Айронфорзі.",
    P = "О, посилка від мого брата? Чудово! Сьогодні мені справді щастить!",
    C = "Тож Гноарн не довіряє моїм розвідувальним здібностям? Цікаво, чому...",
},

[8500] = {
    en = "The Alliance Needs More Thorium Bars!",
    T = "Альянсу потрібно більше торієвих стрижнів!",
    D = "Так приємно знову тебе бачити, $N. Сподіваюся, у тебе все добре. Це правда, що нам і досі потрібні торієві бруски. Якщо у тебе є зайві, я збираю їх для військових потреб Ань-Кіраджа.",
    O = "Принесіть 20 торієвих брусків леді Твінбрейд на аеродромі в Дун-Морозі.",
    P = "Так приємно знову тебе бачити, $N. Сподіваюся, у тебе все добре. Це правда, що нам і досі потрібні торієві бруски. Якщо у тебе є зайві, я збираю їх для військових потреб Ань-Кіраджа.",
    C = "Чудово, $C! Відмінно попрацювали. Я подбаю про те, щоб ці бруски потрапили на піддон і до рук ковалів та інженерів, які наполегливо працюють над поповненням запасів для нашої армії. Ще раз дякую, і якщо натрапите на ще більше брусків торію, обов’язково завітайте до нас.",
},

[8501] = {
    en = "Target: Hive'Ashi Stingers",
    T = "Ціль: «Хайв’Аші Стінгерс»",
    D = "У міру загострення військових дій присутність силітидів у цьому районі становить дедалі більшу загрозу для наших операцій. Вас обрано для участі в штурмі Хів'Аші, де вашою головною ціллю будуть літаючі жалові Хів'Аші.$B$BПісля виконання завдання звітуйте перед командиром Мар'алітом.",
    O = "Знищте 30 «Стінгерів» з племені Хайв’Аші та поверніться до командира Мар’аліта в фортеці Сенаріон у Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Бойове завдання XII».$B",
    P = "Ти хочеш мені щось сказати, $N?",
    C = "Чудова робота, $N. Твій внесок у напад на Хайв’Аші було відзначено.",
