},

[8539] = {
    en = "Target: Hive'Zora Hive Sisters",
    T = "Ціль: Сестри-вулики з «Хайв'Зора»",
    D = "Для участі в штурмі Хайв'Зори було залучено підкріплення. Вас обрано для знищення сестер-вуличок Хайв'Зори. Після виконання завдання з’явіться до командира Мар’аліта.",
    O = "Знищте 30 «Сестер вулика» Хіве'Зора та поверніться до командира Мар'аліта в фортеці Сенаріон у Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Бойовий брифінг V».",
    P = "Ти хочеш мені щось сказати, $C?",
    C = "Чудова робота, $N. Ти — гідний союзник.",
},

[8540] = {
    en = "Boots for the Guard",
    T = "Чоботи для гвардії",
    D = "У кінній дивізії охорони Кріпості Сенаріон відчувається нестача оздоблених мітрілових чобіт. Забезпечте партію таких чобіт і негайно доставте їх капітану Вішу Козусу в Кріпості Сенаріон.",
    O = "Принесіть 3 пари оздоблених мітрілових чобіт Вішу Козусу, капітану охорони в фортеці Сенаріон у Сілітусі. Для виконання цього завдання вам також потрібно принести «Інструкцію з логістичних завдань II».",
    P = "У тебе є щось для мене?",
    C = "Чудово. Нам це було дуже потрібно, $N. Гарна робота.",
},

[8541] = {
    en = "Grinding Stones for the Guard",
    T = "Шліфувальні камені для охорони",
    D = "У вартових Цитаделі Сенаріону не вистачає точильних каменів. Зберіть партію і негайно доставте її капітану Вішу Козусу в Цитаделі Сенаріону.",
    O = "Принесіть 10 щільних точильних каменів, 10 міцних точильних каменів і 10 важких точильних каменів Вішу Козусу, капітану охорони у фортеці Сенаріон у Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Інструкцію з логістичних завдань III».",
    P = "У тебе для мене щось є?",
    C = "Чудово. Нам це було дуже потрібно, $N. Гарна робота.",
},

[8542] = {
    en = "The Horde Needs Tin Bars!",
    T = "Орда потребує олов’яних брусків!",
    D = "Лок'тар, $r, я впевнений, ти вже знаєш, що нам доведеться воювати з комахами в Ан'Кіражі. Але спочатку Вождь вирішив, що нам треба зайнятися так званою «підготовкою». Хоча я б волів би заточувати зброю та кувати обладунки, я пишаюся тим, що мене обрали відповідальним за збір олов'яних злитків тут. Але без твоєї допомоги я цього не зможу зробити.$B$BТому мені потрібно, щоб ти пішов, виготовив олов'яні злитки й приніс їх мені сюди. Гадаю, мені знадобиться більше, ніж я можу порахувати.$B",
    O = "Принесіть 20 олов’яних брусків Грунту Маугу в Долину Духів в Оргримарі.",
    P = "Скільки у тебе там бляшаних брусків, $c? Думаю, після війни мені знадобиться хтось, хто навчить мене рахувати.",
    C = "Я щиро вдячний вам. Ваші зусилля, спрямовані на допомогу Цитаделі Сенаріону, стали свідченням справжньої хоробрості.",
},

[8543] = {
    en = "The Horde Needs More Tin Bars!",
    T = "Орда потребує більше олов’яних злитків!",
    D = "Дуже добре, бачу, ти серйозно ставишся до війни. Хоча я трохи нервую, чекаючи, коли вона почнеться, а це означає, що я розлючуся, якщо ти не почнеш швидше приносити товар. Може, я просто потренуюся на тобі.$B$BХа! А може й ні, бо хто тоді принесе мені олов'яні бруски?",
    O = "Принесіть 20 брусків олова Гранту Маугу в Дуротарі.",
    P = "Дуже добре, бачу, ти серйозно ставишся до війни. Хоча я трохи нервую в очікуванні її початку, і впевнений, що ти теж, $C. Коли вона розпочнеться, це буде велично. Орда, що мчить по пісках пустелі Сілітус, зі зброєю в руках, кидаючись на повну силу в натовп комах. Того дня всі отримають велику честь!$B$BХар! Але спершу нам потрібно більше олов'яних злитків. Цікаво, як така дрібниця може мати таке величезне значення, чи не так?",
    C = "Тром'ка, $N. Ти робиш честь мені та Орді своїми олов'яними злитками. Я покладу їх у стос, і тоді вони прийдуть та виготовлять з них різні речі. А коли все це буде зроблено, ми вирушимо на війну й покажемо кволому Альянсу, як боротися з комахами.$B$BА тепер принеси мені ще олов'яних злитків!",
},

[8544] = {
    en = "Conqueror's Spaulders",
    T = "Наплічники завойовника",
    D = "Серед нас ходять чутки, що вишукані наплічники, які носять смертні раси, спочатку були спробою наслідувати крила дракона.$B$BПринесіть мені ремені, якими користуються найвищі вожді Кіраджі, і я перетворю їх на набір наплічників, страшніших навіть за крила самого Нефаріана!",
    O = "Принесіть «Кіраджські пута командування», 2 «Ідоли ночі», 5 «Кам’яних скарабеїв» та 5 «Глиняних скарабеїв» до Андоргоса в Ан’Кіраджі. Щоб виконати це завдання, вам також потрібно досягти нейтральної репутації у «Роді Ноздорму».",
    P = "Ви вже зібрали всі необхідні мені компоненти?",
    C = "З матеріалів, які ти приніс, та з луски наших полеглих ворогів-кіраджі я виготовляю для тебе ці наплічники, смертний. Нехай вони нададуть тобі необхідний захист, а їхній вигляд вселятиме страх у наших ворогів.",
},

[8545] = {
    en = "The Horde Needs Mithril Bars!",
    T = "Орда потребує злитків мітрілу!",
    D = "$C, війна наближається, і єдине, що ми можемо зробити, — це підготуватися до неї. Ось тут ми з тобою можемо допомогти одне одному, друже. Розумієш, мені доручили зібрати всі злитки мітрілу, які нам знадобляться для виготовлення всього необхідного. І мені все ще потрібно більше!$B$BТож я сподіваюся, що ти зможеш вибратися туди й видобути для нас трохи мітрілу, а потім переплавити його на злитки. Здається, ти зможеш це для нас зробити?",
    O = "Принесіть 20 злитків мітрілу старшому сержанту Т'келі в Долину Духів в Оргримарі.",
    P = "Було б, звичайно, чудово мати всі злитки мітрілу, які нам потрібні для ведення війни в Ан’Кіраджі. Це тому ти повернувся, друже? Ти приніс мої злитки?",
    C = "Це буде гарний початок для тебе й для мене, $C. Це ще двадцять злитків мітрілу, які я зможу додати до запасів і викреслити зі списку. Усе це знайде гідне застосування у виробництві військового спорядження.$B$BОбов'язково зв'яжися зі мною, бо, як бачиш, схоже, нам знадобиться ще більше цих злитків мітрілу.",
},

[8546] = {
    en = "The Horde Needs More Mithril Bars!",
    T = "Орді потрібно більше злитків мітрілу!",
    D = "Ага, я радий, що ти тут, друже. Ти вже допомагав мені раніше, і тепер мені знову потрібна твоя допомога. Ми й досі намагаємося зібрати більше злитків мітрілу для військових потреб; збираємося виготовити купу броні, зброї та всього іншого, щоб розчавити тих жуків в Ан’Кіражі.$B$BТож якщо ти справжній друг, принеси мені ще кілька стосів злитків мітрілу. Я візьму все, що в тебе є, доки не наберемо необхідну кількість. У тебе є щось для мене зараз?",
    O = "Принесіть 20 злитків мітрілу старшому сержанту Т’келі в Долину Духів в Оргримарі.",
    P = "",
    C = "Це чудова робота, $N! Ще двадцять злитків — і ми на крок ближче до мети, а також отримаємо більше військових матеріалів. Я подбаю, щоб їх правильно склали. І якщо ти отримаєш ще одну партію злитків мітрілу, друже, обов’язково принеси їх сюди, до мене.",
},

[8548] = {
    en = "Volunteer's Battlegear",
    T = "Бойове спорядження волонтера",
    D = "Значки, які ви отримуєте за виконання бойових, логістичних та тактичних завдань для Цитаделі Сенаріону, — це не просто прикраса, $N.$B$BВам варто їх зберегти. Коли ви доведете свою лояльність до нашої організації, я зможу запропонувати вам частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 5 бойових значків «Сенаріон», 3 логістичних значків «Сенаріон» та 7 тактичних значків «Сенаріон» Варгусу в фортеці «Сенаріон» у Сілітусі. Щоб виконати це завдання, ви також повинні досягти рівня репутації «Дружній» у «Коло Сенаріон».",
    P = "У наших інтересах забезпечити наших найвідданіших союзників необхідним спорядженням, $N.",
    C = "Чудова робота, $N. Прийми це від імені Кола Сенаріона. Ти, безперечно, заслужив це, друже!",
},

[8549] = {
    en = "The Horde Needs Peacebloom!",
    T = "Орда потребує Пісблум!",
    D = "Кажуть, що кожне покоління має зіткнутися з випробуванням, яке визначає його долю. Я побоююся, що війна за Ан’Кірадж стане тим випробуванням, яке перевірить нашу мужність. Тож ми готуємося, і в цьому процесі дізнаємося, з чого ми зроблені.$B$BЯ зголосився допомогти Орді, зібравши якомога більше квітів миру, щоб з них можна було виготовити зілля для війни. Сподіваюся, ти тут, щоб допомогти мені. Якщо так, то мені потрібно, щоб ти приніс мені чималу кількість цієї трави. Чи допоможеш ти мені, $c?",
    O = "Принесіть 20 квіток «Миру» травнику Праудфезеру в Долину Духів в Оргримарі.",
    P = "Ти так швидко повернувся з «квіткою миру», $c?",
    C = "Це було нелегке завдання, проте ти впорався з ним на відмінно. Але не поспішай думати, що ти мене вразив, $N.",
},

[8550] = {
    en = "The Horde Needs More Peacebloom!",
    T = "Орда потребує більше «Мируквіту»!",
    D = "Знову вітаю, Абісмал. Я радий, що ти знову хочеш поговорити зі мною щодо нашої нескінченної потреби у «квітці миру». Війна триває, а разом із нею — і наше виробництво зілля та еліксирів, які допоможуть у майбутніх боях. Чи допоможеш ти нам знову, $C? Мені потрібна така сама кількість «квіту миру», як і раніше, тож якщо ти зможеш зібрати її та принести мені сюди, я буду тобі дуже вдячний. Звісно, якщо ти вже маєш її при собі, я з радістю прийму її від тебе прямо зараз",
    O = "Принесіть 20 квіток «Миру» травнику Гордопір’ю в Долину Духів в Оргримарі.",
    P = "",
    C = "Дякую тобі за твої невпинні зусилля, $N. Своєю безкорисливою щедрістю ти приносиш велику честь собі та своїм предкам, і про це дізнаються всі! Я зберігатиму ці трави так, щоб вони залишалися свіжими доти, доки вони не знадобляться. Ви вкотре демонструєте справжній дух Орди — боротьбу за перемогу та впевненість у тому, що разом ми зможемо її здобути.",
},

[8551] = {
    en = "The Captain's Chest",
    T = "Скриня капітана",
    D = "Раніше я плавав на кораблі звідси аж до Ратчета в Калімдорі. Я був успішним капітаном із бездоганною репутацією.$B$BАж поки...$B$BЦі прокляті морські велетні зруйнували моє життя! Вони розтрощили мій корабель, вбили мою команду і відправили мене на рятувальній шлюпці до Буті-Бей. А один із велетнів, Горлаш, вкрав мій капітанський скриню. Він сказав, що хоче використовувати її як табакерку. Яка нахабність!$B$BЯ чув, що Горлаш блукає узбережжям на схід відсюди. Знайди його й поверни мені скриню! Зроби це, і ти заслужиш вдячність капітана.",
    O = "Віднесіть скриню Смоттса до Геклбері Смоттса в Буті-Бей.",
    P = "Привіт, $N! Ти знайшов Горлаша? Той скриню я любив найбільше, адже в ньому був потайний відсік, де я зберігав свої найцінніші скарби!",
    C = "Ти знайшов його! О, який щасливий день! Дякую, $N. Повернення мого скрині трохи вгамувало вогонь у мені.$B$BАле моя помста ще не завершена...",
},

[8552] = {
    en = "The Monogrammed Sash",
    T = "Пояс з монограмою",
    D = "На цьому вишуканому поясі вздовж краю вишиті літери «HS».",
    O = "Поверніть стрічку з монограмою її власнику.",
    P = "Привіт. У вас є до мене якісь справи?",
    C = "Ти знайшов мою стрічку? Тоді... ти, мабуть, вбив морського велетня Мокраша! Ура!$B$BЯ радий, що цей мерзенний лиходій мертвий — Мокраш був одним із трьох морських велетнів, які розтрощили мої кораблі та вбили мою команду.$B$BТричі.$B$BТи — $C гідний, $N.",
},

[8553] = {
    en = "The Captain's Cutlass",
    T = "Капітанський шабля",
    D = "Після того, як я втратив свій перший корабель у бійці з цими велетнями, я придбав інший. Я назвав його «Помста Смоттса», завантажив на нього припаси та екіпаж і вирушив на пошуки лиходіїв. Я їх знайшов, але... вони мене перемогли. Вони розтрощили «Помсту Смоттса», вбили мою другу команду і посадили мене на ще один рятувальний човен.$B$BЦього разу інший велетень, Неголаш, вкрав мій шабель.$B$BЗустрінься з Неголашем і принеси мені мій шабель!$B$BПоговори зі Спроггером. Він був моїм кухарем на «Помсті Смоттса» і вижив під час останнього нападу. Він може допомогти тобі знайти велетня.",
    O = "Поговоріть зі Спроггером.",
    P = "",
    C = "Привіт-привіт, $N. Капітан сказав, що ти вирушаєш за Неголашем, так?",
},

[8554] = {
    en = "Facing Negolash",
    T = "Навпроти Неголаша",
    D = "Неголаш — голодний велетень.$B$BКоли велетні знищили наш корабель, Неголаш одразу ж попрямував до моєї кухні. Він не прагнув з’їсти членів екіпажу, як інші велетні. Неголаш хотів вина… і моїх крил грифа, запечених на грилі. Це моя фірмова страва, і мені довелося їхати аж до Пусток, щоб дістати рецепт!$B$BЯкщо хочеш заманити велетня, то дістань трохи вина та купу крил грифа. Покладіть їх у нашу стару рятувальну шлюпку, що стоїть на південний схід від нас уздовж узбережжя. Коли Неголаш відчує запах цієї їжі, він обов’язково прийде!",
    O = "Принесіть 10 крил канюка, приготованих на грилі, та 5 пляшок вина «Джунглвайн» до рятувального човна капітана Смоттса.$B$BУбийте Неголаша та принесіть шаблю Смоттса капітану Смоттсу в Странглторні.",
    P = "Ти взяв мій шаблю, $N?",
    C = "Ти отримав мій шабель від Неголаша! Не можу повірити, яка мені пощастила, $N! Зустріч з тобою змінила мою долю на краще, не сумнівайся в цьому!$B$BДякую! І якщо я колись придбаю новий корабель, а ти захочеш поплавати морями, ти будеш моїм почесним гостем.",
},

[8555] = {
    en = "The Charge of the Dragonflights",
    T = "Наступ драконівських зграй",
    D = "",
    O = "",
    P = "",
    C = "Еранікус, Ваеластраз і Азурегос… Без сумніву, ти знаєш про цих драконів, смертний. Тож не випадково саме вони відіграли таку важливу роль як охоронці нашого світу.$B$BНа жаль (і частково в цьому винна моя власна наївність), чи то через дії агентів Старих Богів, чи то через зраду тих, хто називав їх друзями, кожен із цих охоронців зазнав трагічної долі. Масштаби цих подій підсилили мою недовіру до вашого роду.$B$BРозшукайте їх... І $R, приготуйся до найгіршого.",
},

[8556] = {
    en = "Signet of Unyielding Strength",
    T = "Печатка незламної сили",
    D = "Ходять чутки, що персні, які носять лейтенанти Кіраджі, надають їм надзвичайні здібності. Теоретично зіпсовані дорогоцінні камені, якими вони прикрашені, можна замінити на чистіші матеріали, щоб створити незабруднені версії цих перснів.$B$BКоштовне каміння, що прикрашає ідолів Кіраджі, підійде чудово, оскільки його якість набагато вища.$B$BПринеси мені перстень та ідолів, і я виготовлю для тебе могутній перстень, $c.",
    O = "Принесіть 1 «Магістерське кільце Кіраджі», 2 «Мерехтливі ідоли», 5 «Бронзових скарабеїв» та 5 «Слонових скарабеїв» до «Закликачки вітрів Єссендри» у Сілітусі. Щоб виконати це завдання, ви також повинні досягти репутації «Шанований» у «Колі Сенаріону».",
    P = "Ти приніс мені обручку та матеріали, $N?",
    C = "Я заміню для тебе камінь на персні. Ти побачиш, що ефект виявиться набагато... приємнішим.",
},

[8557] = {
    en = "Drape of Unyielding Strength",
    T = "Плащ непохитної сили",
    D = "Радий чути, що ти допомагаєш нам у наступі на Ан’Кірадж, $N. Я можу виготовити для тебе захисний предмет, який стане в нагоді у боротьбі з нашим ворогом, $c.$B$BМені знадобиться кираджська тканина, розмір якої я, звісно, підгоню під тебе. Мені також знадобляться ідоли та скарабеї, з яких я зроблю відповідну застібку.$B$BОбіцяю, ти не будеш розчарований.",
    O = "Принесіть 1 бойову накидку Кіраджі, 2 оніксові ідоли, 5 срібних скарабеїв і 5 кістяних скарабеїв Кейлу Свіфтклоу в Сілітусі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Шанований» у «Коло Сенаріону».",
    P = "Ти приніс матеріали для плаща, $N?",
    C = "Ах так... цей плащ просто бездоганний.$B$BВізьми цей плащ, $N. Нехай він захистить тебе від злої магії Кіраджі.",
},

[8558] = {
    en = "Sickle of Unyielding Strength",
    T = "Серп незламної сили",
    D = "Кіраджі та їхні слуги користуються предметами, виготовленими з найрідкісніших і найдосконаліших матеріалів: кісток гігантських стародавніх істот, дорогоцінних каменів із глибин землі, чистих і міцних металів.$B$BОдин лише погляд на артефакти кіраджі наповнює мене бажанням попрактикуватися у своєму ремеслі, працюючи з їхніми розбитими та переплавленими уламками. Доведи свою відданість Колу, $N, і я виготовлю тобі потужну зброю з найкращих матеріалів кіраджі.",
    O = "Принесіть 1 кираджську рукоятку з шипами, 2 алебастрові ідоли, 5 кришталевих скарабеїв та 5 кам’яних скарабеїв до стража Харо в Сілітусі. Щоб виконати це завдання, ви також повинні досягти рівня репутації «Шанований» у «Коло Сенаріону».",
    P = "Ти приніс мені ті деталі, які мені потрібні, $N?",
    C = "Ти добре впорався, $C. Це рукоятка-шедевр… баланс ідеальний.$B$BБери свою зброю, $N. Опануй її з великою впевненістю та переможи наших ворогів!",
},

[8559] = {
    en = "Conqueror's Greaves",
    T = "Наголінники завойовника",
    D = "Магія кіраджі — сильна й стародавня. Наймогутніші кіраджі володіють предметами такої сили, що навіть дракон завагався б перед ними.$B$BПринесіть мені кіраджі-обв’язки управління та інші дрібні компоненти, і я виготовлю для вас пару потужних чобіт.$B$BВони стануть тобі в нагоді у боротьбі з ворогом.",
    O = "Принесіть «Кіраджські пута командування», 2 «Ідоли війни», 5 «Скарабеїв із слонової кістки» та 5 «Золотих скарабеїв» Кандростразу в Ань-Кіраджі. Для виконання цього завдання також необхідний нейтральний статус у фракції «Потомство Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $N?",
    C = "Ти добре впорався, $N. Ти довів, що ти не звичайний смертний.$B$BЯ дарую тобі це, будучи впевненим, що це допоможе тобі розгромити мерзенних кіраджі.",
},

[8560] = {
    en = "Conqueror's Legguards",
    T = "Наголінники завойовника",
    D = "Ти прагнеш довести свою цінність моєму роду, смертний? Гаразд, можливо, ми зможемо допомогти одне одному.$B$BСтародавній піщаний черв’як, Оуро, — істота легендарної сили. Ходять чутки, що його створив сам Стародавній Бог як знущання над життям.$B$BЙого шкіра незвичайна… товста, майже неприступна, але водночас гнучка, що дозволяє йому рухатися зі швидкістю та грацією набагато меншої істоти.$B$BПринеси мені зразок його шкіри разом з іншими другорядними компонентами, і я виготовлю тобі набедреники великої сили.",
    O = "Принесіть «Цілу шкіру Оуро», 2 «Ідоли смерті», 5 «Бронзових скарабеїв» та 5 «Скарабеїв із слонової кістки» Кандростразу в Ань-Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у «Роді Ноздорму».",
    P = "Ти приніс ті деталі, які мені потрібні, $N?",
    C = "Так... шкіра черв'яка стане чудовим захисним шаром. У поєднанні з найміцнішими частинами тіл кіраджі, яких ми знищили на шляху сюди, це має стати справді грізним обладунком. Нехай він допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!",
},

[8561] = {
    en = "Conqueror's Crown",
    T = "Корона завойовника",
    D = "Двоє Імператорів... їхнє невпинне шепотіння поволі підриває мій розум. Вони глузують з мене, знаючи, що я не можу зайти далі в їхні володіння, аби врятувати свого брата Арігоса.$B$BУ своїх видіннях я бачу їхні монструозні обличчя, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці символи сили Кіраджі на такі, що краще відповідатимуть нашим потребам.$B$BПринеси мені необхідні компоненти, $N. Я дам тобі головний убір з неперевершеною силою.",
    O = "Принесіть діадему Век'нілаша, 2 ідоли Сонця, 5 кам'яних скарабеїв та 5 кришталевих скарабеїв Андоргосу в Ах'Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у «Поколінні Ноздорму».",
    P = "Ти приніс мені ті деталі, про які я просив, $N?",
    C = "Ти досягнув успіху! Шепотіння Близнюкових Імператорів стихло.$B$BПрийми це як нагороду. Сам лише його вигляд вселить страх у серця кіраджі... він нагадає їм про їхніх полеглих вождів і про смертного, який їх убив.",
},

[8562] = {
    en = "Conqueror's Breastplate",
    T = "Нагрудник завойовника",
    D = "Неназваний Стародавній Бог повільно прокидається від свого сну під Ан’Кіраджем. Жахлива доля, що чекає на Азерот, може настати через кілька днів або років; час не має значення для істот його могутності.$B$BКоли зірки складуться сприятливо, він обрушить свій жахливий гнів на всі живі істоти. Ти повинен знайти його до того, як це станеться, і знайти спосіб покласти край його існуванню.$B$BЗроби це і принеси мені шматок його оболонки. Я нагороджу вас обладунками, яких ще жоден смертний не носив… обладунками, гідними того, хто вбив бога!",
    O = "Принесіть панцир Старого Бога, 2 ідоли війни, 5 срібних скарабеїв та 5 кістяних скарабеїв Ветсере в Ань-Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Пошанований» у «Поколінні Ноздорму».",
    P = "У своєму притулку в Ан'Кіражі жахливий К'Тун чекає, занурившись у сон.",
    C = "Я не очікував, що ти повернешся з тієї місії, $N.$B$BТи виконав долю, величнішу за долю більшості безсмертних істот.$B$BЗнищивши К'Туна, ти не лише врятував весь Азерот, а й змінив хід космічних подій, які виходять за межі твого розуміння.$B$BПрийми цей нагрудник як символ слави та тягаря, що стануть наслідком твоїх вчинків.$B$BНехай його сила допоможе тобі в випробуваннях, що чекають на тебе, вбивце богів!",
},

[8572] = {
    en = "Veteran's Battlegear",
    T = "Бойове спорядження ветерана",
    D = "Значки, які ви збираєте, виконуючи бойові, логістичні та тактичні завдання для Цитаделі Сенаріону, — це не просто прикраса, $N.$B$BВам варто їх зберегти. Коли ви доведете свою відданість нашій організації, я зможу запропонувати вам частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 7 бойових значків «Сенаріону», 4 логістичні значки «Сенаріону» та 4 тактичні значки «Сенаріону» Варгусу в фортеці «Сенаріон» у Сілітусі. Щоб виконати це завдання, ви також повинні досягти рівня репутації «Шанований» у «Крузі Сенаріону».$B",
    P = "У наших інтересах забезпечити наших найвідданіших союзників необхідним спорядженням, $N.$B",
    C = "Чудова робота, $n. Прийми це від імені Кола Сенаріона. Ти, безперечно, заслужив це, друже!",
},

[8573] = {
    en = "Champion's Battlegear",
    T = "Бойове спорядження чемпіона",
    D = "Значки, які ви отримуєте за виконання бойових, логістичних і тактичних завдань для «Цінаріонської фортеці», — це не просто прикраса, $N.$B$BВам варто їх зберегти. Коли ви доведете свою відданість нашій організації, я зможу запропонувати вам частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 15 бойових значків «Сенаріон», 20 логістичних значків «Сенаріон», 20 тактичних значків «Сенаріон» та 1 знак Сенаріуса Варгусу в фортеці «Сенаріон» у Сілітусі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Висока повага» у «Колі Сенаріон».$B",
    P = "У наших інтересах забезпечити наших найвідданіших союзників необхідним спорядженням, $N.",
    C = "Чудова робота, $N. Прийми це від імені Кола Сенаріона. Ти, безперечно, заслужив це, друже!",
},

[8574] = {
    en = "Stalwart's Battlegear",
    T = "Бойове спорядження «Сталварта»",
    D = "Значки, які ти збираєш, виконуючи бойові, логістичні та тактичні завдання для Віндколлер Праудхорна, — це не просто прикраса, $N.$B$BТобі варто їх зберегти. Коли ти доведеш свою відданість нашій організації, я зможу запропонувати тобі частину спорядження, яке ми зберігаємо для наших найближчих союзників, в обмін на ці значки.",
    O = "Принесіть 15 бойових значків «Сенаріон», 20 логістичних значків «Сенаріон», 17 тактичних значків «Сенаріон» та 1 знак Ремулоса Варгусу в фортеці «Сенаріон» у Сілітусі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Шанований» у «Коло Сенаріон».",
    P = "У наших інтересах забезпечити наших найвідданіших союзників необхідним спорядженням, $N.",
    C = "Чудова робота, $n. Прийми це від імені Кола Сенаріону. Ти, безперечно, заслужив це, друже!",
},

[8575] = {
    en = "Azuregos's Magical Ledger",
    T = "Чарівна книга рахунків Азурегоса",
    D = "Ти не можеш зрозуміти жодного слова в цій книзі обліку. Ти навіть не знаєш, якою мовою вона написана!",
    O = "Доставте «Магічну книгу рахунків Азургоса» Нараїну Сутфансі в Танарісі.",
    P = "Оооо! Яка чарівна пульсуюча штучка! Це для мене?",
    C = "<Нарайн зацікавлено розглядає лист.>$B$BЧудово, $R! Що там написано? Я ні слова не розумію драконічної мови.",
},

[8576] = {
    en = "Translating the Ledger",
    T = "Переклад бухгалтерської книги",
    D = "",
    O = "",
    P = "",
    C = "Почнемо з головного, $N! Нам треба з’ясувати, що саме Азурегос написав у цій книзі.$B$BТи кажеш, що він наказав тобі виготовити арканітовий буй і що це — схема? Дивно, що він написав це драконічною мовою. Цей старий козел знає, що я не можу розібратися в цій нісенітниці.$B$BЯкщо це має спрацювати, мені знадобляться мої окуляри для ворожіння, п’ятсотфунтове курча та другий том «Драконічної мови для чайників». Не обов’язково саме в такому порядку.",
},

[8577] = {
    en = "Stewvul, Ex-B.F.F.",
    T = "Стювул, колишня найкраща подруга",
    D = "Якщо мені доведеться щось перекладати, мені знадобляться мої окуляри для ворожіння. На жаль, їх ще досить давно вкрав мій колишній найкращий друг навіки, Стювул. Він розбив мені серце на п’ять частин, а потім залишив мене тут гнити.$B$BЗа допомогою моєї надійної кришталевої кулі я визначила, що він перебуває або біля Стіни Греймейна в Срібній Сосні, або в тому, що схоже на портальний світ у Замежжя, який зараз заполонює Палка Легіон. Ти повинен відшукати його й повернути мої окуляри, $N!",
    O = "Нарайн Сутфансі хоче, щоб ти знайшов його колишнього найкращого друга (BFF) Стювула та повернув окуляри для пророцтв, які Стювул у нього вкрав.",
    P = "",
    C = "Не можу повірити, що він мене знайшов. Я була впевнена, що позбулася його, коли була в Замежжя. Я туди не повернуся, $R! Ні за що, ніяк! Я більше не хочу бути його «найкращим другом назавжди» на півставки та рабинею на повну ставку.",
},

[8578] = {
    en = "Scrying Goggles? No Problem!",
    T = "Окуляри для ворожіння? Немає проблем!",
    D = "<Ти чуєш, як із ящика виривається зітхання полегшення.>$B$BТобі потрібні лише його окуляри для ворожіння? Чудово! Це не буде проблемою... Дай мені хвилинку, щоб... Гей! Де ж... Чорт забирай!$B$BНу, є погана новина і ще гірша. Погана новина в тому, що я загубив окуляри. Ще гірша новина — я загубив їх, коли минулого місяця нишпорив у Розплавленому ядрі. Так, у Розплавленому ядрі... Гадаю, на цьому наші справи завершені! Бувай!",
    O = "Знайдіть «Окуляри пророцтва» Нараїна та поверніть їх Нараїну Сутфенсі в Танарісі.",
    P = "«Розплавлене ядро», так? Сподіваюся, мої захисні окуляри ще цілі!",
    C = "Чудово! А де ж я поклав ту 500-фунтову курку і другий том «Драконіка для чайників»??? О, а ось тобі невеличка винагорода за твою важку працю!",
},

[8579] = {
    en = "Mortal Champions",
    T = "Смертні чемпіони",
    D = "",
    O = "",
    P = "Ми відчуваємо присутність наших поневолених побратимів у глибинах Ан’Кіраджа; проте навіть армія драконів не змогла б їх врятувати, $r.$B$BТе саме закляття, яке ув’язнило їх, міцно підпорядкувало б нас владі К’Туна, якби ми наблизилися до нього ще трохи.$B$BСтародавній Бог передбачив наше прибуття. Уся надія втрачена. Яку різницю може зробити такий простий смертний, як ти?",
    C = "Я бачу, що ти не звичайна людина, $N. Твої шанси проти Старого Бога, хоч і нескінченно малі, на даний момент все ж вищі, ніж наші. Адже, хоча він очікує на драконів біля своїх воріт, він не готовий до когось такого, як ти. $B$BТак само, як тисячу років тому Анакронос і Стагхельм перемогли кіраджі завдяки союзу смертних і драконів, ми теж укладемо угоду. Завоюй довіру Бронзового драконячого полку — і ти завоюєш нашу довіру. Лише тоді ми зробимо з тебе справжнього чемпіона.",
},

[8580] = {
    en = "The Horde Needs Firebloom!",
    T = "Орда потребує Фаєрблума!",
    D = "Гей, $c. Так, саме ти, друже! Там ціла купа вогняних квітів, які Орда вважає необхідними для війни з Ан’Кіражем. Може, вони використовують їх у класних штуках, що вибухають? А може, віддають їх Альянсу як паливо для парових танків? Хто знає? Тільки не Пеле’кейкі!$B$BАле Пеле’кейкі знає одне… він знає, що ти йому допоможеш і принесеш багато вогняних квітів, так, друже?",
    O = "Принесіть 20 «Вогняних квітів» Батрайдеру Пеле’кейкі в Долину Духів в Оргримарі.",
    P = "Не варто дратувати Пеле’кеїкі. Щоб порадувати Пеле’кеїкі, потрібно якнайшвидше принести йому багато вогняних квітів.",
    C = "Тримай кулаки, друже! Сподіваймося, що нам вдасться врятувати Ноггл!",
},

[8581] = {
    en = "The Horde Needs More Firebloom!",
    T = "Орді потрібно більше «Вогняних квітів»!",
    D = "Пеле'кеїкі знають, що ти прийшов допомогти. Принеси багато вогняних квітів — це його дуже порадує. Пеле'кеїкі можуть зробити великі бомби з вогняних квітів. Коли почнеться війна, кидай їх зі своєї кажанової літаючої машини на комах над Ан'Кіраджем. Але Пеле'кеїкі потрібно більше вогняних квітів, $C!$B$BТи маєш принести Пеле'кеїкі ці вогняні квіти, і то дуже швидко. Повернися з принаймні такою ж кількістю, як минулого разу, і Пеле'кеїкі буде задоволений.",
    O = "Принесіть 20 «Вогняних квіток» Батрайдеру Пеле’кеїкі в Долину Духів в Оргримарі.",
    P = "",
    C = "Це ж не жарт, $C? Ти так швидко приніс Пеле'кеїкі вогняні квіти? Пеле'кеїкі зараз їх перераховує, чувак! Ти робиш Пеле'кеїкі таким щасливим, що він усім розповідає: $N — найкращий збирач вогняних квітів за всю історію! Пеле'кейкі не може дочекатися початку війни. Тепер ми справді запалимо небо над Сілітусом, правда, брате?!",
},

[8582] = {
    en = "The Horde Needs Purple Lotus!",
    T = "Орда потребує фіолетового лотоса!",
    D = "Фіолетовий лотос, $c, є реагентом для приготування безлічі зілля, еліксирів та масел, деякі з яких стануть нам у нагоді в Ан’Кіражі. Нам доведеться виготовити величезну кількість цих зілля для військових потреб. А я збираюся провести експерименти, щоб знайти й інші способи застосування лотоса. Але для цього мені знадобиться велика кількість цих квітів.$B$BОсь тут і з’являєтеся ви. Вийдіть у поле й назбирайте якомога більше фіолетових лотосів. Чи готові ви зробити це для нас?",
    O = "Принесіть 20 фіолетових лотосів аптекарці Джезель у Долині Духів в Оргримарі.",
    P = "Ти вже повернувся з фіолетовим лотосом, про який я просив, $c? Дуже важливо, щоб ти зробив це якомога швидше, інакше все, що я тут намагаюся зробити, піде нанівець.",
    C = "Гідні похвали зусилля, $c. Я виміряю ці зразки для їхнього відповідного використання та зазначу ваш внесок. Після цього фіолетовий лотос потрібно буде належним чином зберігати, доки я не буду готовий до їхнього використання. Що стосується вас, то, якщо ви все ще готові допомогти, я припускаю, що мені знадобиться ще більше фіолетового лотоса. Будь ласка, зв’яжіться зі мною трохи пізніше.",
},

[8583] = {
    en = "The Horde Needs More Purple Lotus!",
    T = "Орді потрібно більше фіолетового лотоса!",
    D = "Справді, схоже, що нам потрібно ще більше фіолетового лотоса, $C. Хоча мої власні дослідження ще не дозволили визначити нове корисне застосування цієї рослини, є перевірені та надійні методи, які ще не застосовувалися.$B$BМені потрібно, щоб ти ще раз вирушив у поле й зібрав щонайменше двадцять зразків фіолетового лотоса. Принеси їх мені сюди.",
    O = "Принесіть 20 фіолетових лотосів аптекарю Джезелю в Долині Духів в Оргриммарі.",
    P = "Справді, схоже, що нам потрібно ще більше фіолетового лотоса, $c. Хоча мої власні дослідження ще не дозволили виявити нового корисного застосування цієї рослини, є перевірені методи, які ще не були застосовані.$B$BМені потрібно, щоб ти ще раз вирушив у поле і зібрав щонайменше двадцять зразків фіолетового лотоса. Принеси їх мені сюди.",
    C = "Чудова та ретельна робота, $N. Ваша старанність заслуговує на похвалу, як і ваша оперативність. Я особисто подбаю про те, щоб жоден із цих фіолетових лотосів не пропав даремно.$B$BЩе раз дякую, і якщо ти знайдеш ще фіолетових лотосів, не вагайся принести їх мені якнайшвидше.",
},

[8584] = {
    en = "Never Ask Me About My Business",
    T = "Ніколи не питай мене про мої справи",
    D = "Якщо є щось, що вам варто знати про мене, то це ось що: НІКОЛИ не питайте мене про мої справи! Я займаюся речами, які ви просто не зможете зрозуміти. Наприклад: чи знаєте ви, що таке психотронний музледорф? Звісно, що ні! І саме тому планування залишаємо мені, а пошук — вам.$B$BЯк я вже казав раніше, щоб це спрацювало, нам знадобиться курка вагою 500 фунтів.$B$BВідправляйтеся до Гаджетзану й поговоріть із Діржем Квікклівом — він допоможе вам розпочати пошуки відповідного екземпляра.$B",
    O = "Нарайн Сутфансі в Танарісі просить вас поговорити з Діржем Квікклівом у Гаджетзані.",
    P = "",
    C = "<Дірдж чухає голову.>$B$BКурятина вагою 500 фунтів? Такого не буває! Принаймні, тепер уже ні. Я знав одну таку курку... Чорна Курка Смерті...$B$B<Голос Діржа стихає.>$B$BАле так, ніхто ніколи не бачив ту курку й не залишився живим, щоб розповісти про це. У мене є ідея, яка може принести користь нам обом, хлопче.",
},

[8585] = {
    en = "The Isle of Dread!",
    T = "Острів жаху!",
    D = "Легенда розповідає, що хімероки з Острова Жаху у Фераласі мають найсоковитішу та найніжнішу їжу, яку тільки можна собі уявити! У цих хімероків є батько, який, залежно від того, як його приготувати, може виглядати як 500-фунтова курка, а може й ні.$B$BВідправляйся на Острів Жаху, вбий лорда Лакмаерана і принеси мені його свіжу тушу. Це має задовольнити гнома. Щоб задовольнити мене, тобі доведеться роздобути трохи філе хімерока.$B$BЗроби це — і ти отримаєш свою 500-фунтову курку та ще дещо на додачу.$B",
    O = "Знайдіть тушу Лакмаерана та 20 філе хімаерока для Діржа Квіккліва в Танарісі.",
    P = "Мммм... Чімаерок...",
    C = "Погляньте, як мармурово виглядають ці філе! Просто фантастика!$B$BА тепер щодо цієї курки... Гм, дайте-но подумати. Мені знадобиться кілька хвилин, щоб придумати рецепт.",
},

[8586] = {
    en = "Dirge's Kickin' Chimaerok Chops",
    T = "«Кікін» Діржа: «Хімаерокові удари»",
    D = "Мій рецепт готовий! Тепер мені від тебе потрібні лише ракетне паливо та глибинна сіль. Про спеції я подбаю сам, а м’ясо, яке ти мені приніс, покриє решту.$B$BКоли ти принесеш мені те, про що я просив, курка буде готова, і її можна буде віднести Нараїну.",
    O = "Дірдж Квіккліф у Гаджетзані просить вас принести йому 20 одиниць «Гоблінського ракетного палива» та 20 одиниць «Глибококам’яної солі».",
    P = "Поспішай, хлопче. Не хочемо, щоб це м'ясо зіпсувалося.",
    C = "Готово! Представляю вам моє найкраще творіння: «Кікін’ Чімаерок Чопс» від Dirge!",
},

[8587] = {
    en = "Return to Narain",
    T = "Повернутися до Нараїна",
    D = "Я гоблін, який дотримується свого слова, хлопче. Ось твоя 500-фунтова курка.$B$BНавіщо гному 500-фунтова курка — я ніколи не зрозумію...$B$B<Дірдж бурчить щось незрозуміле.>$B$BМабуть, щоб у ній спати... Брудні гноми...",
    O = "Доставте 500-фунтову курку Нараїну Сутфансі в Танарісі.",
    P = "Що це за чудовий запах?",
    C = "<Нарайн встромляє обидві кулаки у величезну курку, набиваючи рот смачним делікатесом від Дірджа.>$B$BМммм... Це просто неймовірно! Найкраща курка, яку я коли-небудь куштував!",
},

[8588] = {
    en = "The Horde Needs Heavy Leather!",
    T = "Орді потрібна міцна шкіра!",
    D = "Оскільки ми готуємося до війни, мабуть, найкраще буде спочатку запастися всіма необхідними товарами, чи не так, друже? Одним із основних видів військових матеріалів, які ми виробляємо, є товста шкіра. Ми використовуватимемо її практично для всього: від підсилення до броні, а також для старих добрих простих брезентів.$B$BАле спершу нам треба дістати її побільше. Це твоє завдання, $c. Нагостри ніж і принеси мені зв’язку. Потім поговоримо далі.",
    O = "Принесіть 10 шматків товстої шкіри шкірянику Джамані в Долині Духів в Оргримарі.",
    P = "У мене немає часу на ігри, якщо ти тут лише для того, щоб базікати, $c. Занадто багато стосів важкої шкіри, які потрібно вичинити. Повертайся, коли принесеш мені хоча б десять.",
    C = "О, ви дійсно маєте ту товсту шкіру, яка мені була потрібна. Твоє лезо справді гостре, $c; це чудова шкіра! Тепер, коли ми так вдало розпочали співпрацю, я подбаю про те, щоб твій внесок був використаний з користю. А якщо тобі трапиться ще товстої шкіри, принеси її мені.",
},

[8589] = {
    en = "The Horde Needs More Heavy Leather!",
    T = "Орді потрібно більше важкої шкіряної броні!",
    D = "Це правда, $C, мені все ще потрібно більше міцної шкіри. Замовлення від генералів та їхніх інтендантів здаються нескінченними. І це ще ніщо порівняно з тим, чого вимагають капітани цепелінів!$B$BМені треба терміново зібрати свою квоту. Бекун, принеси мені ще кілька стосів важкої шкіри, як тільки зможеш!",
    O = "Принесіть 10 шматків товстої шкіри шкірянику Джамані в Долині Духів в Оргримарі.",
    P = "Це правда, $c, мені все ще потрібно більше товстої шкіри. Замовлення від генералів та їхніх інтендантів здаються нескінченними. І це ще ніщо порівняно з тим, що вимагають капітани цепелінів!$B$BМені треба терміново зібрати свою квоту. $N, принеси мені ще кілька стосів міцної шкіри, як тільки зможеш!",
    C = "Ти просто молодець, друже! Дуже дякую за цю товсту шкіру. Кожна дрібниця наближає нас до мети. Я просто складу це в купу, щоб інші шкіряники могли взятися за роботу.$B$BЩе раз дякую, $N, і якщо натрапиш на ще якісь стоси товстої шкіри, ти знаєш, де мене знайти.",
},

[8590] = {
    en = "The Horde Needs Thick Leather!",
    T = "Орда потребує товстої шкіри!",
    D = "Я радий, що ти вирішив поговорити зі мною про це, $c. Схоже, підготовка Орди до майбутньої війни за Ан’Кірадж йде повним ходом. Але нам з тобою все ще потрібно внести свій вклад.$B$BМене попросили зібрати велику кількість товстих шкір для виготовлення різноманітного військового спорядження, і мені потрібна твоя допомога — ти повинен вирушити туди й зібрати їх. Якщо ти вирішиш допомогти, на тебе чекають честь і вдячність Орди. Ти погодишся?",
    O = "Принесіть 10 шматків товстої шкіри сержанту Умалі в Долині Духів в Оргримарі.",
    P = "$C, ти так швидко повернувся з тими десятьма шматками товстої шкіри, про які ми домовлялися?",
    C = "Гарна робота, $c. Я впевнений, що ці товсті шкіряні шкури знадобляться для зміцнення цепелінів та виготовлення різноманітних видів броні й зброї. Я дякую тобі від себе та від імені Орди. Завітай до нас знову, якщо під час своїх мандрів натрапиш на ще більше товстої шкіри, і нехай тобі щастить.",
},

[8591] = {
    en = "The Horde Needs More Thick Leather!",
    T = "Орді потрібно більше товстої шкіри!",
    D = "Друїде, як бачиш, мені все ще потрібно зібрати більше товстої шкіри. Я ще раз прошу тебе допомогти мені з цим завданням і обіцяю, що якщо ти його виконаєш, твої зусилля будуть гідно оцінені.$B$BЧас не чекає! Повернися до мене з товстою шкірою, щоб ми могли завершити наші приготування й вирушити на війну, герою!",
    O = "Принесіть 10 шматків товстої шкіри сержанту Умалі в Долину Духів в Оргримарі.",
    P = "$C, як бачиш, мені ще потрібно зібрати більше товстої шкіри. Я ще раз прошу тебе допомогти мені з цим завданням і обіцяю, що якщо ти його виконаєш, твої зусилля будуть гідно оцінені.$B$BЧас не чекає! Поверніться до мене з товстою шкірою, щоб ми могли завершити наші приготування й вирушити на війну, $g герою : героїне!",
    C = "Ти це зробив, $N, я знав, що ти це зробиш! Ще раз дякую від імені всієї Орди. Твої зусилля були помічені й високо оцінені. А якщо у тебе знайдеться ще товстої шкіри, яку ти хотів би пожертвувати, принеси її мені сюди.$B$BЛок'тар Огар, $c!",
},

[8592] = {
    en = "Tiara of the Oracle",
    T = "Тіара Оракула",
    D = "Двоє Імператорів... їхнє невпине шепотіння поволі підриває мій розум. Вони глузують з мене, знаючи, що я не можу зайти далі в їхні володіння, аби врятувати свого брата Арігоса.$B$BУ своїх видіннях я бачу їхні монструозні обличчя, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці символи могутності Кіраджі на такі, що краще відповідатимуть нашим потребам.$B$BПринеси мені необхідні компоненти, $N. Я дам тобі головний убір з неперевершеною силою.",
    O = "Принесіть діадему Век’нілаша, 2 ідоли Мудреця, 5 срібних скарабеїв та 5 кістяних скарабеїв Андоргосу в Ан’Кіражі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у «Поколінні Ноздорму».",
    P = "Ти приніс мені ті деталі, про які я просив, $N?",
    C = "Ти впорався! Шепотіння Близнюкових Імператорів вщухло.$B$BПрийми це як нагороду. Один лише його вигляд вселить страх у серця кіраджі... він нагадає їм про їхніх загиблих вождів і про смертного, який їх убив.",
},

[8593] = {
    en = "Trousers of the Oracle",
    T = "Штани Оракула",
    D = "Ти прагнеш довести свою цінність моєму роду, смертний? Гаразд, можливо, ми зможемо допомогти один одному.$B$BСтародавній піщаний черв’як, Оуро, — істота легендарної сили. Ходять чутки, що його створив сам Стародавній Бог як знущання над життям.$B$BЙого шкіра незвичайна… товста, майже непробивна, але водночас гнучка, що дозволяє йому рухатися зі швидкістю та грацією набагато меншої істоти.$B$BПринеси мені зразок його шкіри разом з іншими дрібними компонентами, і я виготовлю тобі набедреники великої сили.",
    O = "Принесіть Кандростразу в Ань-Кірадж неушкоджену шкуру Оуро, 2 ідоли життя, 5 золотих скарабеїв та 5 глиняних скарабеїв. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у Роді Ноздорму.",
    P = "Ти приніс ті деталі, які мені потрібні, $N?",
    C = "Так... шкіра черв'яка стане чудовим захисним шаром. У поєднанні з найміцнішими частинами тіл кіраджі, яких ми знищили на шляху сюди, це має стати грізним елементом броні. Нехай вона допоможе тобі протистояти невимовним жахам, що чекають на тебе всередині!",
},

[8594] = {
    en = "Mantle of the Oracle",
    T = "Мантія Оракула",
    D = "Серед нас ходять чутки, що вишукані плечові обладунки, які носять смертні раси, спочатку були спробою відтворити крила дракона.$B$BПринесіть мені ремені, якими користуються найвищі вожді кіраджі, і я перетворю їх на набір наплічників, страшніших навіть за крила самого Нефаріана!",
    O = "Принесіть «Кіраджські пута влади», 2 «Ідоли відродження», 5 «Срібних скарабеїв» та 5 «Слонових скарабеїв» Андоргосу в Ан’Кіраджі. Щоб виконати це завдання, вам також потрібно досягти нейтральної репутації з «Потомством Ноздорму».",
    P = "Ви вже зібрали всі необхідні мені компоненти?",
    C = "З матеріалів, які ти приніс, та з луски наших повалених ворогів-кіраджі я виготовляю для тебе ці наплічники, смертний. Нехай вони нададуть тобі необхідний захист, і нехай сам їхній вигляд вселяє страх у наших ворогів.",
},

[8595] = {
    en = "Mortal Champions",
    T = "Смертні чемпіони",
    D = "Я бачу, що ти не звичайний смертний, $n. Твої шанси проти Старого Бога, хоч і нескінченно малі, на даний момент більші, ніж наші. Адже, хоча він очікує на драконів біля своїх воріт, він не готовий до появи когось такого, як ти.$B$BТак само, як тисячу років тому Анакронос і Стагхельм перемогли Кіраджі завдяки союзу смертних і драконів, ми теж укладемо угоду. Завоюй довіру Бронзового Драконячого Польоту — і ти завоюєш нашу довіру. Лише тоді ми зробимо з тебе справжнього чемпіона.",
    O = "",
    P = "Вбивство одного з володарів Кіраджі — це значне досягнення для смертного, $N. Однак їх багато, і вони могутні. Продовжуй перемагати їх, щоб довести свою гідність як нашого чемпіона.",
    C = "Ти й надалі добре нам служиш, $N. Наш договір залишається в силі.",
},

[8596] = {
    en = "Footwraps of the Oracle",
    T = "Обгортання ніг Оракула",
    D = "Магія кіраджі — могутня й древня. Наймогутніші кіраджі володіють предметами такої сили, що навіть дракон змушений би задуматися.$B$BПринесіть мені кірадзькі амулети управління та інші дрібні компоненти, і я виготовлю для вас пару потужних чобіт.$B$BВони стануть вам у нагоді в боротьбі з ворогом.",
    O = "Принесіть «Кіраджські пута влади», 2 «Ідоли смерті», 5 «Бронзових скарабеїв» та 5 «Золотих скарабеїв» Кандростразу в Ан’Кіраджі. Для виконання цього завдання також необхідний нейтральний статус у фракції «Потомство Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $N?",
    C = "Ти добре впорався, $N. Ти довів, що ти не звичайний смертний.$B$BЯ дарую тобі це, впевнений, що це допоможе тобі розгромити підлих кіраджі.",
},

[8597] = {
    en = "Draconic for Dummies",
    T = "«Драконіка для початківців»",
    D = "Я знав, що ця книга колись стане в нагоді! На щастя, я мав достатньо кмітливості та передбачливості, щоб сховати її в безпечному місці.$B$BНе хвилюйся, вона лежить у такому місці, що ніхто й подумати не зможе, де її шукати! Мені знадобився гірокоптер, щоб дістатися туди вперше. На жаль, на зворотному шляху я розбився на пляжі. Саме завдяки цій аварії я й отримав ці надзвичайні гномські екстрасенсорні здібності!$B$BШукайте мій розбитий гірокоптер десь на пляжі Лендс-Енд і пливіть звідти на південь! Ви одразу впізнаєте це місце, коли його побачите!",
    O = "Знайдіть книгу Нараїна Сутфансі, заховану на одному з островів Південних морів.",
    P = "",
    C = "Книга зникла! На вершині купки землі лежить записка.",
},

[8598] = {
    en = "rAnS0m",
    T = "rAnS0m",
    D = "<Текст на цій записці складається з різних шрифтів, наклеєних на поверхню пергаменту.>$B$BУ нас є твоя дорогоцінна книга, гноме. Якщо ти коли-небудь хочеш її знову побачити, ти зробиш саме те, що ми попросимо.$B$B<Наведено докладний перелік інструкцій, що займає 3 сторінки.>$B$BПринеси гроші й приходь сам!",
    O = "Поверніть лист з вимогою викупу Нараїну Сутфансі в Танарісі.$B",
    P = "Скажи, що сталося?",
    C = "<Обличчя Нараїна яскраво почервоніло.>$B$BВони що, хочуть вкрасти мою... книгу!? Я їм покажу, що значить зв’язуватися з гномом-екстрасенсом!",
},

[8599] = {
    en = "Love Song for Narain",
    T = "Пісня кохання для Нараїна",
    D = "До мене нечасто заходять гості. Насправді, востаннє до мене завітав гість, коли я врятувала того милого, чарівного гнома з уламків розбитої літаючої машини.$B$B<Мерідіт дивиться в порожнечу, занурившись у спогади.>$B$BВи його знаєте? Нараїна? Нараїна Сутфенсі? О, для мене було б так важливо, якби хтось передав йому від мене повідомлення. Я мушу сказати йому, що відчуваю! Я знаю, що це кохання! Я просто це знаю!$B$BЧи не могли б ви передати повідомлення Нараїну? Я була б вам вічно вдячна!",
    O = "Візьміть «Лист кохання від Мерідіт до Нараїна Сутфенсі» у Танарісі.",
    P = "Від тебе пахне рибою!",
    C = "Що!?$B$B<Нараїн починає нервово крутитися.>$B$BНу, е-е... Що ти хочеш, щоб я зробив??? Вона ж риба! Риба, кажу тобі! А я — гном. У нас ніколи нічого не вийде.",
},

[8600] = {
    en = "The Horde Needs Rugged Leather!",
    T = "Орда потребує міцної шкіри!",
    D = "Я вважаю, що те, як ніж лежить у долоні, важливіше, ніж його гострота. Навіть найтупіше лезо може різати, якщо на нього правильно тиснути, чи не так, $c? Але у нас з тобою таких проблем немає, адже ми завжди підтримуємо леза в ідеальному стані, чи не так? $B$BЩо ж, неважливо. У мене є завдання для тебе. На службі Орді та щоб внести свій вклад у військові зусилля проти Ан’Кіраджа, я хочу, щоб ти приніс мені кілька шматків міцної шкіри. Ти ж це зробиш, чи не так?",
    O = "Принесіть 10 одиниць міцної шкіри доктору Серратусу в Долині Духів в Оргримарі.",
    P = "Невже тобі потрібно стільки часу, щоб відрізати для мене десять шматків міцної шкіри! Може, тобі варто нагострити свій ніж для зняття шкіри? Або, можливо, я помиляюся, і вони вже є у твоїй сумці?",
    C = "Гаразд, схоже, ти впорався з цим досить непогано, хоча деякі з цих шкур виглядають трохи пошарпаними по краях. Неважливо, завдання виконано, і ти заслужив свою нагороду. Якщо тобі трапиться ще одна стоса шорсткої шкіри, обов’язково принеси її мені якнайшвидше.",
},

[8601] = {
    en = "The Horde Needs More Rugged Leather!",
    T = "Орда потребує більше міцної шкіри!",
    D = "Підготовка до майбутньої війни в Ан’Кіражі триває, $C. Однак, щоб ми не відстали, або принаймні щоб не я став причиною нашого відставання, я хочу, щоб ти приніс ще одну партію міцної шкіри. Буду дуже вдячний за вашу оперативну реакцію на це прохання, $N.",
    O = "Принесіть 10 одиниць міцної шкіри доктору Серратусу в Долині Духів в Оргримарі.",
    P = "Підготовка до майбутньої війни в Ан’Кіражі триває, $c. Однак, щоб ми не відстали, або принаймні щоб не я став причиною нашого відставання, я хочу, щоб ти приніс ще одну партію міцної шкіри. Буду дуже вдячний за вашу оперативну реакцію на це прохання, $N.",
    C = "Практика, практика, практика. Добре заточений ніж і вміння ним користуватися допоможуть тобі далеко просунутися в цьому світі, $N. Схоже, леза на цих шкурах кращі, ніж на попередніх. Ти купив новий ніж? $B$BУ будь-якому разі, ми дякуємо тобі за твої зусилля. Ваш внесок зафіксовано, і я можу запевнити вас, що він буде використаний з користю. Якщо у вас з’явиться більш міцна шкіра, обов’язково поверніться й поговоріть зі мною, бо вона, ймовірно, мені знадобиться.",
},

[8602] = {
    en = "Stormcaller's Pauldrons",
    T = "Наплічники «Закликача бурі»",
    D = "Серед нас ходять чутки, що вишукані плечові обладунки, які носять смертні раси, спочатку були спробою наслідувати крила дракона.$B$BПринесіть мені ремені, які носять найвищі вожді Кіраджі, і я перетворю їх на набір наплічників, страшніших навіть за крила самого Нефаріана!",
    O = "Принесіть «Кірадзькі пута панування», 2 «Ідоли життя», 5 «Золотих скарабеїв» та 5 «Кришталевих скарабеїв» Андоргосу в Ан’Кіраджі. Для виконання цього завдання вам також потрібно досягти нейтральної репутації у «Поколінні Ноздорму».",
    P = "Ви вже зібрали всі необхідні мені компоненти?",
    C = "З матеріалів, які ти приніс, та з луски наших повалених ворогів-кіраджі я виготовляю для тебе ці наплічники, смертний. Нехай вони нададуть тобі необхідний захист, а їхній вигляд вселить страх у наших ворогів.",
},

[8603] = {
    en = "Vestments of the Oracle",
    T = "Одяг Оракула",
    D = "Неназваний Стародавній Бог повільно прокидається від свого сну під Ан’Кіраджем. Страшна доля, що чекає на Азерот, може настати через кілька днів або років; час не має значення для істот його могутності.$B$BКоли зірки складуться сприятливо, він обрушить свій жахливий гнів на всі живі істоти. Ти повинен знайти його до того, як це станеться, і знайти спосіб покласти край його існуванню.$B$BЗроби це і принеси мені шматок його оболонки. Я нагороджу вас обладунками, яких ще жоден смертний не носив… обладунками, гідними того, хто вбив бога!",
    O = "Принесіть «Оболонку Старого Бога», 2 «Ідоли Смерті», 5 «Кам’яних скарабеїв» та 5 «Кришталевих скарабеїв» Ветсере в Ань-Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Шанований» у «Роді Ноздорму».",
    P = "У своєму притулку в Ан'Кіражі жахливий К'Тун чекає, занурившись у сон.",
    C = "Я не очікував, що ти повернешся з тієї місії, $N.$B$BТи виконав долю, величнішу за долю більшості безсмертних істот.$B$BЗнищивши К'Туна, ти не лише врятував весь Азерот, а й змінив хід космічних подій, що виходять за межі твого розуміння.$B$BПрийми ці облачення як символ слави та тягаря, що стануть наслідком твоїх вчинків.$B$BНехай їхня сила допоможе тобі в випробуваннях, що чекають на тебе, вбивце богів!",
},

[8604] = {
    en = "The Horde Needs Wool Bandages!",
    T = "Орда потребує вовняних бинтів!",
    D = "Вітаю, $c. У рамках підготовки до війни в Ан'Кіражі я координую зусилля Орди зі збору вовняних бинтів. На жаль, у польових умовах наші солдати не можуть розраховувати на присутність цілителя, який би врятував їм життя. Повірте, я знаю це з власного досвіду. Тому ми збираємо для них усі ці аптечки першої допомоги.$B$BЯкщо у вас є час, мені потрібно багато вовняних бинтів. Принесіть їх мені сюди, і я подбаю про те, щоб ви отримали належну винагороду.",
    O = "Принесіть 20 вовняних бинтів цілителю Лонграннеру в Долині Духів в Оргримарі.",
    P = "О, $c, ти так швидко повернувся з вовняними бинтами?",
    C = "Я щиро вдячний вам. Ваші зусилля, спрямовані на допомогу Ценаріонській фортеці, стали свідченням справжньої відваги.",
},

[8605] = {
    en = "The Horde Needs More Wool Bandages!",
    T = "Орді потрібні ще вовняні бинти!",
    D = "Радий знову бачити тебе, $C. Ми тут і далі готуємося до війни, і мені як і раніше потрібна будь-яка допомога з твого боку у зборі вовняних бинтів. Буду дуже вдячний за будь-яку підтримку. Сподіваюся лише, що наших зусиль вистачить. Я втратив занадто багато благородних душ на вчорашніх полях битв, щоб не зробити всього, що в моїх силах, аби це більше не повторилося.",
    O = "Принесіть 20 вовняних бинтів цілителю Лонграннеру в Долині Духів в Оргримарі.",
    P = "",
    C = "Ти — чесний $C, $N! Я подбаю про те, щоб ці бинти потрапили в потрібні руки. Я дякую вам від себе та від імені Орди.$B$BІдіть з миром, і поверніться до мене, якщо у вас з’явиться зайва вовняна бинта. Нам тут знадобиться будь-яка допомога.",
},

[8606] = {
    en = "Decoy!",
    T = "Приманка!",
    D = "Я придумав! Ось що ми зробимо. Я наповню мішок камінням, а ти його здаси. Я знаю, що там було написано, що я маю здійснити доставку, і я це зроблю — так би мовити.$B$B<Нараїн оглядає тебе з ніг до голови.>$B$BТак, ти впораєшся. Візьми цей тюрбан, халат і мішок із камінням та вирушай до місця передачі в Вінтерспрингу.$B$BЯ вклав усе необхідне в цей спеціальний набір. Коли вони з’являться, щоб забрати товар, знищ їх! Це навчить їх не зв’язуватися з Нараїном!$B",
    O = "Нарайн Сутфансі в Танарісі просить вас вирушити до Вінтерспринга та залишити «Мішок із золотом» у місці, вказаному викрадачами книг.",
    P = "",
    C = "Мені здається, ми, можливо, недооцінили цих викрадачів книг.",
},

[8607] = {
    en = "The Horde Needs Mageweave Bandages!",
    T = "Орда потребує бинтів «Магічне плетиво»!",
    D = "Я сподіваюся, що ти звертаєшся до мене, бо збираєшся допомогти зі збором, який мені доручили? Чудово! Будь-якими засобами, і я маю на увазі будь-якими, я хочу, щоб ви зібрали значну кількість бинтів із магічного полотна. Було б добре, щоб вони були свіжими, але це не обов’язково. Принесіть їх мені сюди, $c, і я особисто подбаю про те, щоб ви отримали належну винагороду.",
    O = "Принесіть 20 бинтів «Магічне плетиво» леді Каллоу в Долину Духів в Оргримарі.",
    P = "Не підведи мене і не постав у незручне становище, $c! Повертайся сюди якомога швидше з тими бинтами «Мейджвів», про які ми домовлялися.",
    C = "Дивно, але цілком прийнятно. Можливо, я недооцінив твої «здібності», $c. Можливо. Ти виконав дуже просте завдання, і за це отримаєш непропорційно велику винагороду. Але нехай це не впаде тобі в голову. Якщо ти справді хочеш довести свою спроможність, тобі слід вирушити туди й принести мені ще одну в'язку бинтів із магічного полотна.",
},

[8608] = {
    en = "The Horde Needs More Mageweave Bandages!",
    T = "Орді потрібно більше бинтів «Магічне плетиво»!",
    D = "Ти повернувся? Цікаво. Як бачиш, я й досі збираю ресурси для «військових потреб» Ан’Кіраджа. А це означає, що мені потрібно, щоб ти ще раз пішов і зібрав для мене стос бинтів із магічного полотна. З нетерпінням чекаю на твоє повернення, $C.",
    O = "Принесіть 20 пов'язок «Магічне плетіння» леді Каллоу в Долину Духів в Оргримарі.",
    P = "Ти повернувся? Цікаво. Як бачиш, я й досі збираю ресурси для «військових потреб» Ан’Кіраджа. А це означає, що мені потрібно, щоб ти ще раз пішов і зібрав для мене стос бинтів із магічного полотна. З нетерпінням чекаю на твоє повернення, $c.",
    C = "Неймовірно, $c, ти справді знову це зробив! Що ж, кажуть, що я маю хороший смак у виборі тих, кого беру до своєї служби. Добре, твій внесок взято до відома, і ти отримаєш соціальні пільги, на які заслужив своїми зусиллями. Проте я пропоную тобі повернутися і зібрати ще одну в'язку бинтів із магічного полотна, якщо ти справді хочеш довести свою цінність.",
},

[8609] = {
    en = "The Horde Needs Runecloth Bandages!",
    T = "Орда потребує бинтів із рунічної тканини!",
    D = "Схоже, що Орда та Альянс неминуче рухаються до війни в Ан’Кіражі. Дивно, але це не війна одна проти одної, а скоріше проти силітидів та тієї сили, яка ними керує. Також дивно, що обидві сторони роблять усе можливе, аби зібрати ресурси, необхідні для успішного ведення війни.$B$BЯ збираю бинти з рунічної тканини, щоб роздати їх солдатам, але без допомоги, сподіваюся, вашої, мені це не вдасться. Чи можете ви мені в цьому допомогти, $c?$B",
    O = "Принесіть 20 бинтів із рунічної тканини Стоунгарду Клейхуфу в Долину Духів в Оргримарі.",
    P = "Гадаю, війна розпочнеться незабаром, $c. Дякую вам за час і зусилля, які ви присвятили допомозі у виконанні наших завдань зі збору ресурсів. Ви повернулися тому, що дістали бинти з рунічної тканини, про які ми раніше говорили?",
    C = "Супер, ти впорався!",
},

[8610] = {
    en = "The Horde Needs More Runecloth Bandages!",
    T = "Орді потрібно більше бинтів із рунічної тканини!",
    D = "Час, коли ми з головою поринемо у вир битви в Ан’Кіраджі, наближається, жрецю. Але спершу ми маємо зібрати сили та підготуватися, щоб вистояти під натиском комах та їхніх повелителів.$B$BЯкщо ти знову тут, то, мабуть, хочеш зробити ще один внесок у військові потреби у вигляді бинтів із рунічної тканини? Будь ласка, зроби це якомога швидше й знову повернися до мене.",
    O = "Принесіть 20 бинтів із рунічної тканини Стоунгарду Клейхуфу в Долину Духів в Оргримарі.",
    P = "",
    C = "Те, що ти робиш, $N, — це справді безкорисливий вчинок. Він, ймовірно, врятує життя багатьох бійців в Ан’Кіражі. Дякую вам і знайте, що Орда щиро вдячна вам за ваш внесок. Якщо ви створите або знайдете ще більше бинтів із рунічної тканини, будь ласка, принесіть їх мені сюди.",
},

[8611] = {
    en = "The Horde Needs Lean Wolf Steaks!",
    T = "Орда потребує стейків із худорлявого вовка!",
    D = "Я тут не для того, щоб просто гарненько засмагнути, $c. Треба готуватися до війни. Якщо ми збираємося розгромити тих комах в Ан’Кіражі, то мусимо бути готовими, і це стосується також і їжі!$B$BМене змушують збирати й солити тут нежирні вовчі стейки для майбутньої війни. Але оскільки мені треба залишитися тут, щоб про все це подбати, тобі треба піти, вбити кілька вовків, а потім приготувати з м’яса нежирні вовчі стейки й принести їх мені сюди. Ти все зрозумів?",
    O = "Принесіть 20 стейків худорлявого вовка Кровоохоронцю Раутару в Долину Духів в Оргримарі.",
    P = "Ти вже знову приніс ті пісні вовчі стейки, $c? Мені байдуже, пересмажені вони чи «татарські» — головне, щоб були смачні, і принеси їх мені швидше!",
    C = "Гаразд, ця купа м’яса мені здається непоганою. Я її посолю, а потім складу на зберігання — сподіваюся, воно збереже свіжість і буде придатним до вживання, коли настане час.$B$BДякую за внесок, $c. Як думаєш, ти міг би принести мені ще одну решітку?",
},

[8612] = {
    en = "The Horde Needs More Lean Wolf Steaks!",
    T = "Орді потрібно більше стейків із худорлявого вовка!",
    D = "Як бачиш, $C, нам ще треба спакувати більше їжі для солдатів. Не знаю, чи ти коли-небудь був на війні, але як тільки пройде початковий шок від побаченого на полі бою, можеш дуже зголодніти. Минулого разу ти добре впорався, тож сподіваюся, що цього разу ти зробиш те саме, а може, навіть трохи швидше, і принесеш мені ще одну стопку тих пісних вовчих стейків.",
    O = "Принесіть 20 стейків худорлявого вовка Кровоохоронцю Раутару в Долину Духів в Оргримарі.",
    P = "Як бачиш, $c, нам ще треба запастися їжею для солдатів. Не знаю, чи доводилося тобі колись воювати, але коли пройде початковий шок від бойових дій, можеш неабияк зголодніти. Минулого разу ти добре впорався, тож сподіваюся, що цього разу ти зробиш те саме, а може, навіть трохи швидше, — принесеш мені ще одну стопку тих нежирних вовчих стейків.",
    C = "Схоже, ти або хтось із твоїх знайомих — справжній кулінар, $N. Від цих пісних вовчих стейків у мене аж слинка тече; гадаю, ніхто й не помітить, якщо кілька з них зникнуть. У будь-якому разі, добре попрацював. Я подбаю, щоб хтось їх як слід запакував, щоб вони не зіпсувалися надто сильно.$B$BЯкщо знайдеш ще, знаєш, де мене знайти.",
},

[8613] = {
    en = "The Horde Needs Spotted Yellowtail!",
    T = "Орда потребує плямистого жовтохвоста!",
    D = "Сьогодні чудовий день для риболовлі, чи не так, друже? Це добре, бо, схоже, мені знадобиться чимало риби. Орда попросила мене організувати для них збір величезної кількості плямистого жовтохвоста. Кажуть, що вона їм потрібна для війни, до якої вони готуються в Ан’Кіражі. Я сказав їм, що зроблю все, що в моїх силах. Тож мені потрібна допомога. Ти допоможеш мені, $c?",
    O = "Принесіть 20 плямистих жовтохвостів рибалці Лін'до в Долину Духів в Оргримарі.",
    P = "Спрайт-дартери можуть бути небезпечними створіннями, якщо їх спровокувати. Будь обережним у спілкуванні з ними, $C. І будь ще обережнішим щодо нічних ельфів у цій місцевості. Ці настирливі дурні зазвичай ховаються в лісах.$B$BКоли ти назбираєш достатньо крил, дай мені знати — я обов’язково щедро тебе винагороджу!",
    C = "Чудово, $C! Це якраз те, що треба. Тут вистачить, щоб зшити плащ для Корріна, а може, навіть і більше! Дякую.$B$BСподіваюся, подорож не була надто небезпечною? Околиці Фераласу не славляться своєю поблажливістю, але ти, очевидно, впорався на відмінно.$B$BЩе раз дякую, $C.",
},

[8614] = {
    en = "The Horde Needs More Spotted Yellowtail!",
    T = "Орді потрібно більше плямистих жовтохвостів!",
    D = "Отже, як бачите, нам і далі знадобиться чимало рибки. Учасникам майбутньої війни за Ан’Кірадж знадобиться чимало їжі, тож мені треба зібрати якомога більше плямистого жовтохвоста. Ви ловите їх, готуєте і приносите мені сюди, а я висловлюю вам подяку від себе та від імені Орди.",
    O = "Принесіть 20 плямистих жовтохвостів рибалці Лін’до в Долині Духів в Оргримарі.",
    P = "",
    C = "Це найкращий улов досі, $N! Справжня, чесна праця. І навіть без кісток! Дякую тобі за цю плямисту рибу, друже. Заходь ще, якщо зловиш ще кілька!",
},

[8615] = {
    en = "The Horde Needs Baked Salmon!",
    T = "Орда потребує запеченого лосося!",
    D = "Війна з Ан’Кіраджем — це грандіозне завдання, $c. Усі матеріали, що тут збираються, — чи то метал для зброї, чи то їжа, — однаково важливі. Адже якщо ви не їли кілька днів поспіль, у вирішальний момент у вас не вистачить сил підняти сокиру.$B$BТому ми збираємо стільки їжі, скільки можемо. Я збираю запечений лосось — страву, яку обрали як за її поживність, так і за те, що вона добре зберігається. Чи можете ви допомогти мені з цим завданням, $c?",
    O = "Принесіть 20 порцій запеченого лосося вождю Шарпклоу в Долину Духів в Оргримарі.",
    P = "Спрайт-дартери можуть бути небезпечними створіннями, якщо їх спровокувати. Будь обережним у спілкуванні з ними, $C. І будь ще обережнішим щодо нічних ельфів у цій місцевості. Ці набридливі дурні також зазвичай ховаються в лісах.$B$BКоли ви назбираєте достатньо крил, дайте мені знати — я обов’язково щедро вас винагороджу!",
    C = "Чудово, $C! Це якраз те, що треба. Тут вистачить, щоб зшити плащ для Корріна, а може, навіть і більше! Дякую.$B$BСподіваюся, подорож не була надто небезпечною? Край Фералас не славиться своєю поблажливістю, але ти, очевидно, впорався досить добре.$B$BЩе раз дякую, $C.",
},

