[8620] = {
    en = "The Only Prescription",
    T = "Єдиний рецепт",
    D = "Я мав би здогадатися. Мій заклятий ворог, доктор Вівіл, знову витворяє свої старі витівки! І ось тепер, завдяки твоїй поразці у Вінтерспрингу, доктор Вівіл знищив мою книгу! Як ти тепер збираєшся врятувати світ, герою?$B$BУ записці, яку я отримав, йшлося про те, що єдиний відомий примірник «Драконічної мови для початківців: Том II» було розірвано на 8 частин і розвіяно вітром! Якщо тобі якось вдасться знайти ці зниклі розділи, скористайся цією магічною палітуркою, щоб зібрати їх до купи й повернути мені.",
    O = "Знайдіть 8 втрачених розділів книги «Драконічна мова для початківців», об’єднайте їх із «Чарівним переплетінням» і поверніть готову книгу «Драконічна мова для початківців: Том II» Нараїну Сутфенсі в Танарісі.",
    P = "Я одягаю штани так само, як і ти — по одній нозі за раз. Тільки коли я вже вдягнув штани, я роблю арканітові буї. Арканітові буї, крихітко!",
    C = "Фантастика! Не можу повірити, що ви взяли на себе таку мороку! Ви що, якась машина? Якби це був я, я б, мабуть, просто дозволив би світу зруйнуватися.$B$BСхиляю перед вами свій тюрбан, сер. І жодна добра справа не повинна залишатися без нагороди.",
},

[8621] = {
    en = "Stormcaller's Footguards",
    T = "Охоронці «Штормового заклинателя»",
    D = "Магія кіраджі — могутня й древня. Наймогутніші кіраджі володіють предметами такої сили, що навіть дракон завагався б перед ними.$B$BПринесіть мені кіраджі-обв’язки панування та інші другорядні компоненти, і я виготовлю для вас пару потужних чобіт.$B$BВони стануть вам у нагоді в боротьбі з ворогом.",
    O = "Принесіть «Кіраджські пута панування», 2 «Ідоли мудреця», 5 «Бронзових скарабеїв» та 5 «Глиняних скарабеїв» Кандростразу в Ан’Кіраджі. Для виконання цього завдання також необхідний нейтральний статус у фракції «Потомство Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $n?",
    C = "Ти добре впорався, $n. Ти довів, що ти не звичайна людина.$B$BЯ дарую тобі це, впевнений, що це допоможе тобі розгромити підлих кіраджі.",
},

[8622] = {
    en = "Stormcaller's Hauberk",
    T = "Кольчуга «Закликача бурі»",
    D = "Неназваний Стародавній Бог повільно пробуджується від сну під Ан’Кіраджем. Жахлива доля, що чекає на Азерот, може настати через кілька днів або років; час не має значення для істот його могутності.$B$BКоли зірки складуться сприятливо, він обрушить свій жахливий гнів на всі живі істоти. Ти повинен знайти його до того часу і знайти спосіб покласти край його існуванню.$B$BЗроби це і принеси мені шматок його оболонки. Я подарую тобі обладунки, яких ще жоден смертний не носив… обладунки, гідні того, хто вбив бога!",
    O = "Принесіть панцир Старого Бога, 2 ідоли Мудреця, 5 срібних скарабеїв і 5 кістяних скарабеїв Ветсере в Ан'Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Шанований» у «Племені Ноздорму».",
    P = "Ти вже придбав ті речі, про які я просив, $n?",
    C = "Я не очікував, що ти повернешся з тієї місії, $n.$B$BТи виконав долю, величнішу за долю більшості безсмертних істот.$B$BЗнищивши К'Туна, ти не лише врятував весь Азерот, а й змінив хід космічних подій, що виходять за межі твого розуміння.$B$BПрийми цей нагрудник як символ слави та тягаря, що стануть наслідком твоїх вчинків.$B$BНехай його сила допоможе тобі у випробуваннях, що чекають на тебе, вбивце богів!",
},

[8623] = {
    en = "Stormcaller's Diadem",
    T = "Діадема Прикликача Бурі",
    D = "Двоє Імператорів... їхнє невпине шепотіння поволі підриває мій розум. Вони глузують з мене, знаючи, що я не можу зайти далі в їхні володіння, аби врятувати свого брата Арігоса.$B$BУ своїх видіннях я бачу їхні монструозні обличчя, прикрашені могутніми коронами. Але я помщуся... Я перетворю ці символи сили Кіраджі на такі, що краще відповідатимуть нашим потребам.$B$BПринеси мені необхідні компоненти, $N. Я дам тобі головний убір з неперевершеною силою.",
    O = "Принесіть діадему Век'лора, 2 ідоли відродження, 5 кам'яних скарабеїв і 5 кришталевих скарабеїв Андоргосу в Ан'Кіражі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у «Поколінні Ноздорму».",
    P = "Ти придбав ті речі, про які я просив, $n?",
    C = "Ти впорався! Шепотіння Близнюкових Імператорів стихло.$B$BВізьми це як нагороду. Один лише його вигляд вселить страх у серця кіраджі... він нагадає їм про їхніх полеглих вождів і про смертного, який їх вбив.",
},

[8624] = {
    en = "Stormcaller's Leggings",
    T = "Штани «Викликач бурі»",
    D = "Ти прагнеш довести свою цінність моєму роду, смертний? Гаразд, можливо, ми зможемо допомогти одне одному.$B$BСтародавній піщаний черв’як, Оуро, — істота з легендарною силою. Подейкують, що його створив сам Стародавній Бог як знущання над життям.$B$BЙого шкіра незвичайна... товста, майже непробивна, але водночас гнучка, що дозволяє йому рухатися зі швидкістю та грацією набагато меншої істоти.$B$BПринеси мені зразок його шкіри разом з іншими дрібними компонентами, і я виготовлю тобі набедреники великої сили.",
    O = "Принесіть Шкіру Великого Піщаного Черв’яка, 2 Ідоли Розбрату, 5 Бронзових скарабеїв та 5 Скарабеїв із слонової кістки Кандростразу в Ань-Кіраджі. Щоб виконати це завдання, вам також потрібно досягти рівня репутації «Дружній» у «Поколінні Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $n?",
    C = "Так... шкіра черв'яка стане чудовим захисним шаром. У поєднанні з найміцнішими частинами тіл кіраджі, яких ми знищили по дорозі сюди, це має стати грізним елементом обладунків. Нехай це допоможе тобі протистояти невимовним жахам, що чекають всередині!",
},

[8625] = {
    en = "Enigma Shoulderpads",
    T = "Наплічники «Енігма»",
    D = "Серед нас ходять чутки, що вишукані наплічники, які носять смертні раси, спочатку були спробою наслідувати крила дракона.$B$BПринесіть мені ремені, якими користуються найвищі вожді Кіраджі, і я перетворю їх на набір наплічників, страшніших навіть за крила самого Нефаріана!",
    O = "Принесіть «Кіраджські пута панування», 2 «Ідоли смерті», 5 «Кам’яних скарабеїв» та 5 «Бронзових скарабеїв» до Андоргоса в Ан’Кіраджі. Щоб виконати це завдання, вам також потрібно досягти нейтральної репутації з «Поколінням Ноздорму».",
    P = "Ви вже зібрали всі необхідні мені компоненти?",
    C = "З матеріалів, які ти приніс, та з луски наших повалених ворогів-кіраджі я виготовляю для тебе ці наплічники, смертний. Нехай вони нададуть тобі необхідний захист, а їхній вигляд вселить страх у наших ворогів.",
},

[8626] = {
    en = "Striker's Footguards",
    T = "Захисні накладки на ноги для нападників",
    D = "Магія кіраджі — могутня й древня. Наймогутніші кіраджі володіють предметами такої сили, що навіть дракон завагався б перед ними.$B$BПринесіть мені кіраджі-обв’язки управління та інші другорядні компоненти, і я виготовлю для вас пару потужних чобіт.$B$BВони стануть вам у нагоді в боротьбі з ворогом.",
    O = "Принесіть «Кірадзькі пута командування», 2 «Ідоли життя», 5 «Кам’яних скарабеїв» та 5 «Кістяних скарабеїв» Кандростразу в Ань-Кіраджі. Для виконання цього завдання також необхідний нейтральний статус у фракції «Потомство Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $N?",
    C = "Ти добре впорався, $N. Ти довів, що ти не звичайна людина.$B$BЯ дарую тобі це, будучи впевненим, що це допоможе тобі розгромити мерзенних кіраджі.",
},

[8627] = {
    en = "Avenger's Breastplate",
    T = "Нагрудник Месника",
    D = "Неназваний Стародавній Бог повільно прокидається зі свого сну під Ан’Кіраджем. Жахлива доля, яка чекає на Азерот, може настати через кілька днів або років; час не має значення для істот його могутності.$B$BКоли зірки складуться сприятливо, він обрушить свій жахливий гнів на всіх живих істот. Ти мусиш знайти його до того часу й знайти спосіб покласти край його існуванню.$B$BЗроби це й принеси мені шматок його оболонки. Я нагороджу вас обладунками, яких ще жоден смертний не носив… обладунками, гідними того, хто вбив бога!",
