[8634] = {
    en = "Enigma Boots",
    T = "Черевики Enigma",
    D = "Магія кіраджі — могутня й древня. Наймогутніші кіраджі володіють предметами такої сили, що навіть дракон завагався б перед ними.$B$BПринесіть мені кірадзькі ремені панування та інші дрібні компоненти, і я виготовлю для вас комплект потужних чобіт.$B$BВони стануть вам у нагоді в боротьбі з ворогом.",
    O = "Принесіть «Кіраджські пута панування», 2 «Ідоли Сонця», 5 «Срібних скарабеїв» та 5 «Кришталевих скарабеїв» Кандростразу в Ан’Кіраджі. Для виконання цього завдання також необхідний нейтральний статус у фракції «Потомство Ноздорму».",
    P = "Ти придбав ті предмети, про які я просив, $N?",
    C = "Ти добре впорався, $N. Ти довів, що ти не звичайна людина.$B$BЯ дарую тобі це, будучи впевненим, що це допоможе тобі розгромити огидних кіраджі.",
},

[8635] = {
    en = "Splitrock the Elder",
    T = "Сплітрок Старший",
    D = "",
    O = "",
    P = "",
    C = "Битви минулих століть — це насіння, з якого виростають легенди. Ти живеш у час героїв, юний друже. Нехай твоя легенда пустить коріння й розквітне.$B$BБажаю тобі всього найкращого, $N, і дарую тобі цей знак...",
},

[8636] = {
    en = "Rumblerock the Elder",
    T = "Румблерок Старший",
    D = "",
    O = "",
    P = "",
