[8762] = {
    en = "Metzen the Reindeer",
    T = "Олень Метцен",
    D = "Сталася катастрофа! Оленя Метцена викрали!$B$BМетцен — один із восьми оленів Великого батька Зими — і є власністю компанії «Смоківуд Пастурес». Ми отримали не один, а ДВА листи з вимогою викупу від угруповань, які стверджують, що Метцен у них. Свята вже в розпалі, а у нас тут майже порожня скарбничка! Будь ласка — знайдіть Метцена та поверніть його нам!$B$BПерегляньте листи з вимогою викупу, щоб знайти підказки, і посипте його цим оленячим пилом — він звільнить його від будь-яких пут!$B$BБудь ласка, поспішайте!",
    O = "Знайдіть оленя Метцена. Використовуйте надані вам нотатки як підказки щодо того, де його утримують.$B$BКоли знайдете Метцена, майте при собі мішечок з оленячим пилом, щоб посипати його цим пилом; це має звільнити Метцена з полону.$B$BПісля звільнення Метцена поверніть мішечок з оленячим пилом Вулморту Джинглпокету в Айронфорзі.",
    P = "$N! Ти його знайшов? Чи достатньо інформації було в записках із сумки, яку я тобі дав, щоб знайти Метцена? Мені страшно навіть уявити, що ті жорстокі бандити можуть з ним зробити... але ми ніяк не можемо собі дозволити заплатити такий шалений викуп!",
    C = "Ти це зробив! Ура!$B$BМетцен щойно повернувся до стайні Великого батька Зими — так, Метцен справді вміє літати! Пил спрацював як за помахом чарівної палички; я й знав, що так буде. Ти врятував Свято Зимової Завіси, а також Пасовища Смоківуд від катастрофи. Дякую, $N.$B$BПослухай… через те, що ти тут зробив, я хочу, щоб ти взяв це. Це щось ДУЖЕ особливе; якщо у тебе є верховий звір, думаю, тобі це сподобається. Зі Зимовим святом!",
},

[8763] = {
    en = "The Hero of the Day",
    T = "Герой дня",
    D = "Послухай... Мені, власне, не слід тобі цього розповідати, але оскільки ти сьогодні наш герой і все таке...$B$BУ цю пору року свіжий падуб зустрічається всюди, але він ніколи довго не зберігається. У нас є машина, яка консервує падуб — він ніколи не псується! Ми використовуємо його, щоб додати колориту святам... і збільшити прибутки влітку!$B$BЯ дозволю тобі скористатися консерватором, але тільки якщо ти майстер-кухар. Тобі знадобиться трохи глибинної солі та дві, три, ну, скажімо, п’ять золотих. Ти отримаєш гарну партію, яку зможеш залишити собі.",
    O = "Принесіть 1 одиницю солі «Діпрок» та 5 золотих монет до будь-якого автомата «Зберігач падуба», після чого ви отримаєте 5 одиниць «Збереженого падуба».",
    P = "На перший погляд машина «Holly Preserver» схожа на якийсь дистилятор, але при уважному огляді в ній можна помітити деякі зміни, характерні для гоблінів. Проте, судячи з ваших кулінарних навичок, ви, здається, розумієте, як працює ця машина. $B$BУ машині вже є свіжа падуб — вам потрібно лише додати трохи глибокогірської солі та п’ять золотих монет, щоб запустити машину.",
    C = "Коли машина починає працювати, вона видає легкий гуркіт і випускає невелику кількість пари. Незабаром після цього вона зупиняється, про що свідчить ще один невеликий струмінь пари, що виривається з неї. Відкривається люк, і звідти видніється партія консервованого падуба!",
},

