[8770] = {
    en = "Target: Hive'Ashi Defenders",
    T = "Ціль: Захисники Хайв'Аші",
    D = "У міру загострення військових дій присутність силітидів у цьому районі становить дедалі більшу загрозу для наших операцій. Вас обрано для участі в штурмі Хайв'Аші, де вашою основною ціллю будуть захисники Хайв'Аші.$B$BПісля виконання завдання звітуйте перед командиром Мар'алітом.",
