[8789] = {
    en = "Imperial Qiraji Armaments",
    T = "Імперська зброя Кіраджі",
    D = "Ми не сиділи склавши руки протягом тисячоліття, $N.$B$BМи спостерігали, як ці звірі пожирають один одного, коли їхня корисність вичерпується. Ми слухали, як вони плели інтриги та планували знищити наш світ. І ми дізналися про їхню внутрішню зраду.$B$BУ них є слабкі місця, і ми знаємо, як використати ці слабкі місця на свою користь.$B$BЗнайдіть і принесіть мені їхнє обрядове озброєння: у поєднанні з елементом, створеним із нестабільності їхнього власного Бога, воно стане силою, з якою доведеться рахуватися.",
    O = "Аригос у Храмі Ан'Кірадж виготовить для вас зброю, просочену елемітієм, якщо ви принесете йому імперську зброю кіраджів та 3 руди елемітію.",
    P = "Знайди те, про що я просив. Ти станеш більшим, ніж сума твоїх частин, чемпіоне.",
    C = "Ці зброї, просякнуті Елементіумом, з неймовірною легкістю розріжуть Кіраджі та їхнього Бога.",
},

[8790] = {
    en = "Imperial Qiraji Regalia",
    T = "Імперські регалії Кіраджі",
    D = "Аригос висуває гіпотезу, що елемент, який походить із конфліктів між Старими Богами та їхніми слугами, за певних умов також є надзвичайно смертоносним для них. Я говорю про Елементіум, смертний.$B$BЗнайди та принеси мені Імперські регалії Кіраджі та цей токсичний елемент, і я наділю зброю великою силою.$B",
    O = "Мерітра з «Сну» у Храмі Ан’Кірадж виготовить для вас зброю, просочену елемітієм, якщо ви принесете їй Імперські регалії Кіраджі та 3 руди елемітію.$B",
    P = "Ти знищиш їх і звільниш нас від цих кайданів.",
    C = "Використовуй цей предмет з розумом, $N. Нехай вони відчують той біль, який так прагнуть заподіяти іншим.",
},

[8791] = {
