[8798] = {
    en = "A Yeti of Your Own",
    T = "Свій власний Єті",
    D = "",
    O = "",
    P = "",
    C = "Слухай! А знаєш що?! Ти теж інженер! Тож, оскільки ти допоміг мені провчити моїх друзів, я навчу тебе, як зробити свого власного механічного єті! Тепер веселощі можуть тривати вічно-вічно, і ти зможеш лякати кого завгодно! Звісно, за умови, що ти зможеш роздобути деталі для його створення. $B$BЩо скажеш, $N? Хочеш дізнатися секрет створення механічного єті?",
},

[8799] = {
    en = "The Hero of the Day",
    T = "Герой дня",
    D = "Послухай... Насправді я не маю права тобі цього розповідати, але оскільки ти сьогодні наш герой і все таке...$B$BУ цю пору року свіжий падуб можна знайти скрізь, але він ніколи довго не зберігається. У нас є машина, яка консервує падуб — він ніколи не псується! Ми використовуємо його, щоб додати колориту святам... і збільшити прибутки влітку!$B$BЯ дозволю тобі скористатися консерватором, але тільки якщо ти майстер-кухар. Тобі знадобиться трохи глибинної солі та дві, три… ну, скажімо, п’ять золотих. У результаті ти отримаєш гарну партію, яку зможеш залишити собі.",
    O = "Принесіть 1 одиницю солі «Діпрок» та 5 золотих монет до автомата «Консерватор падуба», після чого ви отримаєте 5 одиниць «Консервованого падуба».",
    P = "На перший погляд машина «Holly Preserver» схожа на якийсь дистилятор, але при уважному огляді в ній можна помітити деякі зміни, характерні для гоблінів. Проте, судячи з ваших кулінарних навичок, ви, здається, розумієте, як працює ця машина. $B$BУ машині вже є свіжа падуб — вам потрібно лише додати трохи глибинної солі та п’ять золотих монет, щоб запустити машину.",
    C = "Коли машина починає працювати, вона видає легкий гуркіт і випускає невелику кількість пари. Незабаром після цього вона зупиняється, про що свідчить ще один невеликий струмінь пари, що виривається з неї. Відкривається люк, і звідти видніється партія консервованого падуба!",
},

[8800] = {
    en = "Cenarion Battlegear",
    T = "Бойове спорядження Сенаріону",
    D = "Виконуючи завдання, які вам доручають під час війни, вам варто поговорити з ковалем Варгусом. Покажіть йому всі значки, які ви заробили по ходу справи. Він надасть вам спорядження, яке відповідатиме вашому рівню відданості нашій справі.",
    O = "Поговоріть із Варгусом у фортеці «Сенаріон» у Сілітусі.",
    P = "",
    C = "Тебе прислав Калдон? Добре, подивимося, чим ми зможемо тобі допомогти.",
},

[8801] = {
    en = "C'Thun's Legacy",
    T = "Спадщина К'Туна",
    D = "Стіни Ан'Кіраджа тремтять. Сила зла, старша за сам світ, була знищена.$B$BКоли ви дивитеся на залишки колосальної потвори, ваше серце майже завмирає. Навіть після смерті ти відчуваєш навколо себе спадщину зла К'Туна.$B$BТи зробив те, що вважалося неможливим.$B$BТи хапаєш очне стебло цього демона й надійно ховаєш його у свій рюкзак.$B$BВіднеси Око К'Туна до драконів у сусідній залі.",
    O = "Віднесіть «Око К’Туна» Каеластразу в Храмі Ан’Кірадж.",
    P = "$GLord:Lady; $N, ти визволив нас з його лещат.",
    C = "Ми покинемо це місце самостійно, $GLord:Lady; $N — щойно переконаємося, що зло, яке таїться тут, повністю знищено. Ваша легендарна подорож майже добігає кінця.",
},

[8802] = {
    en = "The Savior of Kalimdor",
    T = "Спаситель Калімдора",
    D = "Ти вирушаєш до Печер Часу, $G Лорд:Леді; $N. Анахронос чекає на твоє повернення. Передай йому око К'Туна, адже він, безсумнівно, захоче додати його до колекції свого господаря.$B",
    O = "Віднесіть «Око К'Туна» Анакроносу в Печерах Часу.",
    P = "$GLord:Lady; $N! Все скінчилося...",
    C = "Майстер залишив це для тебе, чемпіоне. З вічного сховища: колекція артефактів, що охоплює тисячі років — вибір за тобою.",
},

[8803] = {
    en = "A Festive Gift",
    T = "Святковий подарунок",
    D = "",
    O = "",
    P = "",
    C = "У записці до цього подарунка написано: $B$BДля $n, $B$BСподіваючись, що це допоможе тобі поширити теплі вісті та святковий настрій по всьому Азероту. $B$BВід Великого Батька Зими",
},

[8804] = {
    en = "Desert Survival Kits",
    T = "Набори для виживання в пустелі",
    D = "З прибуттям нових рекрутів до Цитаделі Сенаріону постає проблема їхнього виживання в пустелі. Зневоднення, а також численні отруйні істоти становлять серйозну загрозу для недосвідчених добровольців. Зберіть необхідні речі для набору виживання в пустелі та принесіть їх Каландрату в Цитаделі Сенаріону.",
    O = "Принесіть 4 кулі з водою, 4 потужні протиотрути та 4 копчені пустельні пельмені Каландрату в таверні в Ценаріон-Холді в Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Інструкцію з логістичного завдання I».",
