    C = "Чудово! Нам саме це було потрібно, $N. Дякуємо.",
},

[8805] = {
    en = "Boots for the Guard",
    T = "Чоботи для гвардії",
    D = "У кінному підрозділі охорони Цитаделі Сенаріону бракує оздоблених мітрілових чобіт. Забери партію таких чобіт і негайно достави їх капітану Вішу Козусу в Цитаделі Сенаріону.",
