[8806] = {
    en = "Grinding Stones for the Guard",
    T = "Шліфувальні камені для охорони",
    D = "У вартових «Оплоту Сенаріону» не вистачає точильних каменів. Зберіть партію і негайно доставляйте їх капітану Вішу Козусу в «Оплоті Сенаріону».",
    O = "Принесіть 10 щільних шліфувальних каменів, 10 твердих шліфувальних каменів і 10 важких шліфувальних каменів Вішу Козусу, капітану охорони в фортеці Сенаріон у Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Інструкцію з логістичного завдання III».",
    P = "У тебе є щось для мене?",
    C = "Чудово. Нам це було дуже потрібно, $N. Гарна робота.",
},

[8807] = {
    en = "Scrying Materials",
    T = "Матеріали для ворожіння",
    D = "Дослідження геолога Ларксбейн виявилися надзвичайно цінними для нашої діяльності в Сілітусі. Нещодавно вона попросила надати матеріали для ворожіння, які вона використовує у своїх дослідженнях.$B$BБудь ласка, зберіть ці матеріали та передайте їх їй безпосередньо, щоб вона могла продовжити свої дослідження.",
    O = "Принесіть 1 великий блискучий осколок, 1 великий сяючий осколок і 1 величезний смарагд геологу Ларксбейну в фортеці Сенаріон у Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Інструкцію щодо логістичного завдання V».",
    P = "У тебе є щось для мене, $N?",
