},

[8809] = {
    en = "Extraordinary Materials",
    T = "Незвичайні матеріали",
    D = "Варгус, коваль з Кріпості Сенаріон, попросив надати зачаровані матеріали, необхідні для виготовлення потужної зброї для наших військ. Знайдіть ці матеріали та принесіть їх безпосередньо Варгусу, щоб війська Кріпості Сенаріон і надалі були добре озброєні.",
    O = "Принесіть 2 зачаровані злитки торію та 2 зачаровані шматки шкіри Варгусу в Цитадель Сенаріону в Сілітусі. Щоб виконати це завдання, вам також потрібно принести «Інструкцію з логістичних завдань IX».",
    P = "У тебе є щось для мене, $N?",
