},

[8811] = {
    en = "One Commendation Signet",
    T = "Одна відзнака «Commendation Signet»",
    D = "",
    O = "",
    P = "Тим авантюристам, у яких є лише одна печатка визнання, я обміняю її на невелику кількість очок визнання в Айронфорзі.$B$BПрошу мати на увазі, що краще здавати одразу стос із десяти печаток; у такому разі ваші зусилля отримають більше визнання. Ми пропонуємо послугу обміну однієї печатки для тих, хто не має достатньо печаток для повного стосика з десяти.$B$BЗ огляду на це, я готовий допомогти вам, якщо ви все ж бажаєте здати одну печатку.",
    C = "Чудово — ваші досягнення занесені до реєстру, і ваші зусилля отримали належне визнання. Продовжуйте у тому ж дусі, $c.$B$BЯкщо у вас є ще якісь печатки, які потрібно здати, я готовий надати вам подальшу допомогу в цьому питанні.",
},

