[8839] = {
    en = "Ten Commendation Signets",
    T = "Десять знаків похвали",
    D = "",
    O = "",
    P = "Я приймаю знаки пошани від мандрівників, які отримали їх під час виконання службових обов’язків. За кожні десять знаків, які ви мені передасте, я подбаю про те, щоб ви отримали значне визнання своїх подвигів серед вигнанців Гномерегана. Я також приймаю окремі знаки, але за значно меншу винагороду. Нас набагато більше цікавлять великі подвиги на службі, хоча жоден подвиг не залишиться без уваги.$B$BЗ огляду на це, я з радістю прийму ваші знаки, якщо ви готові здати набір.",
    C = "Чудово! Ти пішов на неабияку жертву, щоб заробити ці печатки, і твої заслуги будуть належним чином оцінені. Саме такі мандрівники, як ти, $N, справді змінюють світ на краще.$B$BДай мені знати, якщо у тебе є ще печатки, які ти хочеш здати; я з радістю допоможу тобі обміняти ті, які тобі потрібні.",
},

[8840] = {
    en = "One Commendation Signet",
    T = "Одна відзнака «Сігнет»",
    D = "",
    O = "",
    P = "Тим мандрівникам, у яких є лише одна печатка за заслуги, я обміняю її на невелику кількість очок визнання в Оргримарі.$B$BЗверніть увагу, що краще відразу здати стос із десяти печаток; у цьому випадку ваші зусилля отримають більше визнання. Ми пропонуємо обмін однієї печатки як послугу для тих, у кого їх недостатньо для повного стосика з десяти.$B$BЗ огляду на це, я готовий допомогти вам, якщо ви все ж бажаєте здати одну печатку.",
    C = "Дуже добре — ваші досягнення занесені до реєстру, і ваші зусилля належним чином оцінені. Продовжуйте в тому ж дусі, $C.$B$BЯкщо у вас є ще якісь печатки, які потрібно здати, я зможу надати вам подальшу допомогу в цьому питанні.",
},

[8841] = {
    en = "Ten Commendation Signets",
    T = "Десять знаків похвали",
    D = "",
    O = "",
    P = "Я приймаю знаки пошани від мандрівників, які отримали їх під час виконання службових обов’язків. За кожні десять знаків, які ви мені передасте, я подбаю про те, щоб ви отримали значне визнання своїх подвигів у Оргримарі. Я також приймаю поодинокі знаки, але рівень визнання за них буде значно нижчим. Нас набагато більше цікавлять видатні подвиги на службі, хоча жоден подвиг не залишиться без уваги.$B$BЗ огляду на це, я з радістю прийму ваші печатки, якщо ви готові здати набір.",
    C = "Чудово! Ти приніс неабияку жертву, щоб заробити ці печатки, і твої заслуги будуть належним чином оцінені. Саме такі мандрівники, як ти, $N, справді змінюють світ на краще.$B$BДай мені знати, якщо у тебе є ще печатки, які ти хочеш здати; я з радістю допоможу тобі обміняти ті, які тобі потрібні.",
},

[8842] = {
    en = "One Commendation Signet",
    T = "Одна відзнака «Commendation Signet»",
    D = "",
    O = "",
    P = "Тим мандрівникам, у яких є лише одна печатка похвали, я обміняю її на невелику кількість очок визнання у «Громовому Утворі».$B$BМайте на увазі, що краще відразу здати стос із десяти печаток; у такому разі ваші зусилля отримають більше визнання. Ми пропонуємо послугу обміну однієї печатки для тих, у кого їх недостатньо для повного стосика з десяти.$B$BЗ огляду на це, я готовий допомогти вам, якщо ви все ж бажаєте здати одну печатку.",
    C = "Дуже добре — ваші досягнення занесені до реєстру, і ваші зусилля належним чином визнані. Продовжуйте в тому ж дусі, $C.$B$BЯкщо у вас є ще якісь печатки, які потрібно здати, я зможу надати вам подальшу допомогу в цьому питанні.",
},

[8843] = {
    en = "Ten Commendation Signets",
    T = "Десять знаків похвали",
    D = "",
    O = "",
    P = "Я приймаю знаки похвали від мандрівників, які отримали їх під час виконання службових обов’язків. За кожні десять знаків, які ви мені передасте, я подбаю про те, щоб ви отримали значне визнання своїх подвигів у Громовому Утворі. Я також приймаю окремі знаки, але за значно меншу винагороду. Нас набагато більше цікавлять великі подвиги, хоча жоден подвиг не залишиться без уваги.$B$BЗ огляду на це, я з радістю прийму ваші знаки, якщо ви готові здати набір.",
    C = "Чудово! Ти пішов на неабияку жертву, щоб заробити ці печатки, і твої заслуги будуть належним чином оцінені. Саме такі мандрівники, як ви, $N, справді змінюють світ на краще.$B$BПовідомте мене, якщо у вас є ще печатки, які ви хочете здати; я з радістю допоможу вам обміняти ті, які вам потрібні.",
},

[8844] = {
    en = "One Commendation Signet",
    T = "Одна відзнака «Commendation Signet»",
    D = "",
    O = "",
    P = "Тим мандрівникам, у яких є лише одна печатка за заслуги, я обміняю її на невелику кількість очок визнання у племені Темних Списів.$B$BМайте на увазі, що краще здати відразу стос із десяти печаток; у такому разі ваші зусилля отримають більшу оцінку. Ми пропонуємо обмін однієї печатки як послугу для тих, у кого не вистачає печаток для повного стоса з десяти.$B$BЗ огляду на це, я готовий допомогти вам, якщо ви все ж бажаєте здати лише одну печатку.",
    C = "Дуже добре — ваші досягнення занесені до реєстру, і ваші зусилля отримали належне визнання. Продовжуйте в тому ж дусі, $C.$B$BЯкщо у вас є ще якісь печатки, які потрібно здати, я зможу надати вам подальшу допомогу в цьому питанні.",
},

[8845] = {
    en = "Ten Commendation Signets",
    T = "Десять знаків похвали",
    D = "",
    O = "",
    P = "Я приймаю знаки похвали від мандрівників, які отримали їх під час виконання службових обов’язків. За кожну десятку, яку ви мені передасте, я подбаю про те, щоб ви отримали значне визнання своїх подвигів з боку племені Темного Списа. Я також приймаю окремі знаки, але за значно меншу винагороду. Нас набагато більше цікавлять великі подвиги, хоча жоден подвиг не залишиться без уваги.$B$BОтже, я з радістю прийму ваші знаки, якщо ви готові здати набір.",
    C = "Чудово! Ти приніс неабияку жертву, щоб заробити ці печатки, і твої заслуги будуть належним чином оцінені. Саме такі мандрівники, як ти, $N, справді змінюють світ на краще.$B$BДай мені знати, якщо у тебе є ще печатки, які ти хочеш здати; я з радістю допоможу тобі обміняти ті, які тобі потрібні.",
},

[8846] = {
    en = "Five Signets for War Supplies",
    T = "П’ять печаток для військових поставок",
    D = "",
    O = "Що ж, тоді все вирішено; ось твої матеріальні засоби, $c. Якщо ти бажаєш здійснити додатковий обмін, я готовий це схвалити. Просто дай мені знати, і я все владнаю.$B$BПродовжуй у тому ж дусі, $N. Нам потрібні всі матеріальні ресурси, які ми зможемо зібрати, якщо хочемо виграти цю справу. Якщо кожен з нас зробить свою справу, то перемога буде нашою!",
    P = "А, ти прийшов по додаткові припаси для себе, так? Ну, я, звичайно, розумію необхідність у додаткових матеріалах… просто озирнись навколо, якщо тобі потрібні докази.$B$BЯ видам тобі додаткові припаси, але в обмін ти повинен будеш надати мені відповідну кількість знаків похвали. Ви не отримаєте жодного визнання за те, що віддасте печатки таким чином, але, можливо, знайдете щось корисне, що допоможе вам вижити, коли нарешті розпочнеться битва.",
    C = "Що ж, тоді все вирішено; ось твої матеріали, $c. Якщо ти хочеш здійснити додатковий обмін, я готовий це схвалити. Просто дай мені знати, і я все влаштую.$B$BПродовжуй у тому ж дусі, $N. Нам потрібні всі матеріальні ресурси, які ми зможемо зібрати, якщо хочемо виграти цю справу. Якщо ми всі зробимо свою справу, то перемога буде за нами!",
},

[8847] = {
    en = "Ten Signets for War Supplies",
    T = "Десять печаток для військових поставок",
    D = "",
    O = "Що ж, тоді все вирішено; ось твої матеріали, $c. Якщо ти хочеш здійснити додатковий обмін, я готовий це схвалити. Просто дай мені знати, і я все влаштую.$B$BПродовжуй у тому ж дусі, $N. Нам потрібні всі матеріальні ресурси, які ми зможемо зібрати, якщо хочемо виграти цю справу. Якщо кожен з нас виконає свою частину роботи, то перемога буде нашою!",
    P = "А, ти прийшов по додаткові припаси для себе, так? Ну, я, звичайно, розумію, що додаткові матеріали можуть знадобитися... просто озирнись навколо, якщо тобі потрібні докази.$B$BЯ видам тобі додаткові припаси, але в обмін ти повинен будеш надати мені відповідну кількість знаків похвали. Ви не отримаєте жодного визнання за те, що віддасте печатки таким чином, але, можливо, знайдете щось корисне, що допоможе вам вижити, коли нарешті розпочнеться битва.",
    C = "Що ж, тоді все вирішено; ось твої матеріали, $c. Якщо ти хочеш здійснити додатковий обмін, я готовий це схвалити. Просто дай мені знати, і я все влаштую.$B$BПродовжуй у тому ж дусі, $N. Нам потрібні всі матеріальні ресурси, які ми зможемо зібрати, якщо хочемо виграти цю справу. Якщо ми всі зробимо свою справу, то перемога буде нашою!",
},

