[8857] = {
    en = "Secrets of the Colossus - Ashi",
    T = "«Таємниці Колоса» — Аші",
    D = "Я шукаю загартованих у боях мандрівників, які готові й здатні доставити свіжий зразок оболонки з тіла вбитого Колоса Аші до Оглторпа в Буті-Бей. Ні, ні, я не хочу, щоб ви наближалися до трупа цієї потвори. Просто візьміть один із моїх зразків і покваптеся. У гнилому вигляді ці зразки йому ні до чого!",
    O = "Віднесіть «Шкаралупу Колоса з Аші» до Оглеторпа Обнотікуса в Буті-Бей.$B",
    P = "Так? А що у тебе там?",
    C = "О, які ж курчата я зроблю з цієї дивовижної лушпини! Молодець, мій $g хлопчик:дівчинка;!",
},

[8858] = {
    en = "Secrets of the Colossus - Regal",
    T = "«Таємниці Колоса» — «Регал»",
    D = "Немає нічого, чого б я хотів більше, ніж засунути цю комашину шкаралупу в товсту пику Ойлфісту… Тільки от я застряг тут, збираючи зразки з того перерослого таргана. З огляду на розміри цієї тварюки, я просиджу тут аж до ранку.$B$BВіднеси цей зразок Ойлфісту від мого імені і зроби це швидко, $c. Він платить КРУТО!$B$BАга, Торіум-Пойнт — це в Ущелині Сьорін.",
    O = "Віднесіть «Колос із панцира Регала» до наглядача Ойлфіста в Палючому ущелині.$B",
    P = "Хм...",
    C = "Чудово. З цього хітину ми, безперечно, зможемо створити неймовірно міцні обладунки. Ось багатства, які тобі обіцяли.",
},

[8859] = {
    en = "Secrets of the Colossus - Zora",
    T = "«Таємниці Колоса» — Зора",
    D = "Мої слуги ледь не загинули, намагаючись дістати цей зразок. Ви обов’язково мусите поквапитися! Лорд Максвелл Тиросус з нетерпінням чекає на свіжий зразок оболонки. Він вважає, що таємниці цього Колоса можуть допомогти нам у війні проти Плеті!$B$BЧому ви досі тут!? До «Надії Світла»! Так, ви отримаєте щедру винагороду за свої зусилля...$B",
    O = "Віднесіть «Остатки Колоса Зори» лорду Максвеллу Тиросусу до каплиці «Надія Світла» у Східних Землях Чуми.$B",
    P = "Ти виглядаєш трохи незграбно в цих черевиках, друже.",
    C = "Чудово і вчасно! Молодець, $g хлопче/дівчино;.",
},

[8860] = {
    en = "New Year Celebrations!",
    T = "Новорічні святкування!",
    D = "У Штормвінді влаштовують новорічне свято! Сьогодні протягом усього дня можна отримати безкоштовні напої, а ввечері влаштують феєрверк! Має бути досить гарно… але сьогодні вечірку влаштовує й Буті-Бей; б’юся об заклад, там буде ще краще!$B$BЩо ж, у будь-якому разі, трактирниця Еллісон у Штормвіні потребує запасу страв із «Димного лісу», щоб нагодувати всіх гостей вечірки. Чи не могли б ви зробити мені послугу й доставити їх!$B$BДякую, $N! Господиня готелю Еллісон перебуває в «Позолоченій троянді», що в Торговому районі Штормвінда.",
    O = "Віднесіть товари «Смоківуд» до кормлярки Еллісон у Штормграді.",
    P = "Вітаю! Ви прийшли на вечірку? А може, вам просто потрібно дати відпочити своїм втомленим ногам...",
    C = "О, мої запаси зі «Смоківуда»! Чудово! Вони мені знадобляться, щоб нагодувати всіх мешканців міста на свято!$B$BДякую, $N. Ось тобі плата, і не забудь випити та потанцювати з гуляками на вулиці!",
},

[8861] = {
    en = "New Year Celebrations!",
    T = "Новорічні святкування!",
    D = "У Громовому Утворі влаштовують новорічне свято! Протягом усього дня там можна буде безкоштовно випити, а вночі влаштують феєрверк!$B$BМає бути досить класно... але сьогодні вечірка відбудеться й у Буті-Бей; б’юся об заклад, там буде ще краще!$B$BЩо ж, у будь-якому разі, трактирниця Пала з Тандер-Блаффа потребує запасу страв із «Димної лісової галявини», щоб нагодувати всіх гостей вечірки. Чи не могли б ви зробити мені послугу й доставити їх!$B$BДякую, $N! Готельєрка Пала перебуває в готелі біля мосту, що веде до Хантерс-Райз.",
    O = "Віднесіть товари «Смоківуд» до кормлівиці Пали в Тандер-Блаффі.",
    P = "Доброго дня, $C! Ти приїхав до Громового Утюгу на наші святкування? Або ти тут, щоб відпочити втомлене копито між полюваннями?",
    C = "О, чудово! Ці запаси допоможуть нагодувати всіх наших людей, які зібралися тут, щоб відсвяткувати Новий рік!$B$BДякую тобі, $N. Я у тобі в боргу. Будь ласка, візьміть ці монети... і прислухайтеся до моєї поради — пийте досхочу з бочок, що стоять надворі, і приєднуйтеся до наших гуляк у святковому танці!",
},

[8862] = {
    en = "Elune's Candle",
    T = "Свічка Елуни",
    D = "",
    O = "",
    P = "Свічка Елуни — це артефакт, який викликає велику повагу у послідовників Місячного фестивалю. Усередині свічки зберігається справжнє місячне світло, готове вирватися назовні!$B$BЦе світло нешкідливе для більшості істот, але ви побачите, що Омен та його поплічники отримують від нього опіки й засліплюються.",
    C = "Гаразд, тоді — я приймаю ці монети предків. Будь ласка, візьміть свічку Елуни з моїм благословенням. А ще, будь ласка, насолоджуйтесь цими безкоштовними феєрверками.",
},

[8863] = {
    en = "Festival Dumplings",
    T = "Фестиваль пельменів",
    D = "",
    O = "",
    P = "Якщо ти зголоднів, то ти потрапив у потрібне місце, друже! Пельмені — це традиційна страва Місячного фестивалю; їх подають ще з часів першого Місячного фестивалю, і я радий, що можу запропонувати їх і на цьому фестивалі.$B$B В обмін на всього лише одну монету предків я поділюся з тобою дегустацією однієї з найсмачніших страв, які ти коли-небудь куштував!",
    C = "Чудово — будь ласка, скуштуйте ці вареники як мій подарунок. Хоча це лише невеликий знак вдячності за ту честь, яку ви заслужили своїми вчинками, гадаю, вам все одно сподобається. Якщо у вас є ще монети предків, я готовий запропонувати вам натомість широкий вибір товарів.",
},

[8864] = {
    en = "Festive Lunar Dresses",
    T = "Святкові сукні в стилі «Лунний»",
    D = "",
    O = "",
    P = "У мене є колекція суконь, які можуть вас зацікавити. Такі сукні носили в давнину під час Місячного фестивалю, і та колекція, яку я маю сьогодні, — мабуть, найкраща з усіх, що я коли-небудь бачила. Кожна з них виготовлена вручну лише з найякісніших і найм’якших матеріалів.$B$BВ обмін на кілька монет предків я дозволю вам вибрати один із трьох фасонів, які у мене є, щоб ви могли залишити його собі. Чи влаштовує вас така пропозиція?",
    C = "Гаразд, тоді — я приймаю ці монети предків. Будь ласка, візьміть свою сукню з моїм благословенням. А ще, будь ласка, насолоджуйтеся цими безкоштовними феєрверками.$B$BТак само, як ви вшанували своїх старших, ви вшановуєте мене своєю присутністю. Дякую вам, і нехай ваше Місячне свято буде радісним.",
},

[8865] = {
    en = "Festive Lunar Pant Suits",
    T = "Святкові місячні брючні костюми",
    D = "",
    O = "",
    P = "Я рада повідомити вам, що у мене є чудовий вибір святкових брючних костюмів, які ви можете придбати... але лише в обмін на монети предків. Якщо для вас важлива мода, то це саме те, що ви шукаєте! Запевняю вас, що таких брючних костюмів ви ніде більше не знайдете.$B$BВ обмін на кілька монет предків я дозволю вам вибрати один із трьох моделей, які у мене є, і залишити його собі. Чи влаштовує вас така пропозиція?",
    C = "Гаразд, тоді — я приймаю ці монети, що символізують моє походження. Будь ласка, забирайте свій брючний костюм — я благословляю вас. А ще, будь ласка, насолоджуйтеся цими безкоштовними феєрверками.",
},

[8866] = {
    en = "Bronzebeard the Elder",
    T = "Бронзобородий Старший",
    D = "",
    O = "",
    P = "",
    C = "Приємно знати, що мешканці цієї землі й досі вшановують стародавні народи. Бажаю тобі всього найкращого, $N, і дарую тобі цей знак...",
},

[8867] = {
    en = "Lunar Fireworks",
    T = "Місячний феєрверк",
    D = "Щороку друїди Місячної галявини влаштовують свято на честь великої перемоги нашого міста над древнім злом.$B$BМи вшановуємо мудрість наших старших, беремо участь у розкішних бенкетах і, звісно ж... запускаємо феєрверки!$B$BЗа невелику пожертву ви можете придбати барвисті ракети у нашого продавця. Спробуйте скористатися деякими з пускових установок, що знаходяться тут, $N.",
    O = "Запустіть 8 місячних феєрверків і 2 кластерні феєрверки, а потім поверніться до Посланця Місячного фестивалю в будь-якій столиці.",
    P = "Ти знайшов пускові установки, $N?",
    C = "Молодець, $N.$B$BОскільки ти вже ввійшов у атмосферу свята, чому б тобі не прийняти це запрошення на фестиваль у Місячній галявині?$B$BЦе досить веселе свято, якщо у тебе є вільний час. Ми ділимося їжею, напоями, історіями і, звісно ж... ще більше феєрверків!$B$BВідкрий запрошення, стоячи всередині кола сильного місячного світла, і ти опинишся в Місячній галявині.",
},

[8868] = {
    en = "Elune's Blessing",
    T = "Благословення Елуни",
    D = "Звір Омен колись був героєм цього світу. Вовк, наділений великою силою та удачею, Омен воював пліч-о-пліч з героями Війни Древніх, аж поки не піддався демонічній магії. Повернувшись проти своїх союзників, він лютував по всьому Азероту, сіючи за собою смерть і жах.$B$BЗрештою його було переможено саме тут, у Місячній галявині, і тепер Омен спочиває серед мулу озера Елунеара. Але щороку, під час свята, він прокидається...$B$BЗберіть загони, $N, і викличте та переможіть звіра Омена. Заслужіть благословення Елуни!",
    O = "Прикликайте Омена, переможіть його та отримайте Благословення Елуни. Поверніться до Валадара Старсонга у Нічному Притулку",
    P = "",
    C = "Молодець, $N. Перемога над Оменом повернула його дух у води Елунеари. Хоча сама bestia благословенна Елунею і тому не може померти, її гнів вщухне ще на рік.",
},

