},

[8877] = {
    en = "Firework Launcher",
    T = "Установка для запуску феєрверків",
    D = "",
    O = "",
    P = "Хоча ракети — це чудовий спосіб відсвяткувати, але щоб побачити їх у всій красі… їх треба запустити з пускової установки.$B$BПринесіть мені монети предків, і я поділюся з вами знаннями про те, як створювати ракетні пускові установки, подібні до тих, що ви бачите в Місячній галявині.",
    C = "Ось, $N. Ось схема для створення пускової установки для феєрверків. Розмістіть пускові установки там, де ви хочете відсвяткувати, а потім запросіть друзів приєднатися до вас!",
},

[8878] = {
    en = "Festive Recipes",
    T = "Святкові рецепти",
    D = "",
    O = "",
    P = "Сукні та брючні костюми, які ви бачите, — це традиційний одяг, що носили багато років тому. Їх носять на честь давніх традицій та близьких, які пішли з життя.$B$BЯкщо ви принесете мені монети предків, $N, я дам вам викрійку для пошиття традиційних червоних суконь або костюмів.",
    C = "Ось схеми, $N. Я впевнений, що ви знайдете результат застосування цих знань справді прекрасним.",
},

[8879] = {
    en = "Large Rockets",
    T = "Великі ракети",
    D = "",
    O = "",
    P = "Великі фестивальні ракети яскраво освітлюють небо — лише ракетні залпи можуть зрівнятися з їхньою пишністю!$B$BПринеси мені монети предків, $N, і я поділюся знаннями про те, як їх створювати.",
    C = "Гаразд — я приймаю ці монети предків. Ось твої рецепти, $N. Нехай вони допоможуть тобі поширювати славу Елуни!",
},

[8880] = {
    en = "Cluster Rockets",
    T = "Кластерні ракети",
    D = "",
    O = "",
    P = "Кластерні ракети — це сукупність окремих ракет, і їхня краса просто вражає! Принесіть мені монети предків, і я поділюся з вами знаннями про те, як їх створювати...",
    C = "Ось, $N. Візьми ці рецепти й дізнайся їхні секрети. Бажаю тобі успіху, і з нетерпінням чекаю на твої чудові творіння.",
},

[8881] = {
    en = "Large Cluster Rockets",
    T = "Великі кластерні ракети",
    D = "",
    O = "",
    P = "Створення великих кластерних ракет вимагає значних ресурсів і майстерності, але їхня досконалість і краса варті цих зусиль! Принесіть мені монети предків, і я поділюся з вами знаннями про те, як їх виготовляти.",
    C = "Дякую, $N. Ось рецепт великих кластерних ракет. Нехай ваші вироби приносять радість і удачу всім, хто дивиться на них, піднявши голову до неба.",
},

[8882] = {
    en = "Cluster Launcher",
    T = "Запускач кластерів",
    D = "",
    O = "",
    P = "Найграндіозніші феєрверкові шоу не можуть обійтися без кластерних ракет, а ці кластерні ракети мають запускатися саме з кластерних пускових установок! Хіба ж не логічно, щоб ти опанував секрети виготовлення кластерних пускових установок? Принеси мені монети предків, і я поділюся з тобою цими знаннями.",
    C = "Ось ваша схема. Уважно її вивчіть і опануйте...",
},

[8883] = {
    en = "Valadar Starsong",
    T = "Валадар Старсон",
    D = "Тепер, коли ви отримали запрошення на Місячний фестиваль, можете вирушати до Місячної галявини! Там ви знайдете безліч святкувальників, а в селі Нічний притулок Валадар Старсонґ та його сестра Фаріель чекають на тих, хто бажає долучитися до святкування.$B$BВідправляйтеся до Місячної галявини крізь яскраве місячне світло та поговоріть із Валадаром Старсонгом; дізнайтеся, які призи ви можете отримати під час фестивалю!",
    O = "Використайте своє «Запрошення на Місячний фестиваль» у місячному світлі, щоб дістатися до Місячної галявини. Після прибуття поговоріть із Валадаром Старсонгом у Нічному притулку.",
    P = "",
    C = "$N, ласкаво просимо до Найтхевена — місця проведення Місячного фестивалю! Хоча зазвичай наше селище є віддаленим і ізольованим від інших народів Азерота, у цей святковий час ми відкриваємо свої обійми та серця для всіх.$B$BНасолоджуйтесь візитом, $n, і зверніться до мене або до моєї сестри, коли будете готові.",
},

[8893] = {
    en = "The Super Egg-O-Matic",
    T = "«Супер Егг-О-Матік»",
    D = "",
    O = "",
    P = "«Супер Егг-О-Матік» — це найновіший винахід Кергла Кранклхопа. Це справді вражаючий механізм.$B$B«Супер Егг-О-Матік» починає бурхливо іскритися, щойно ви наближаєтеся до панелі керування.",
    C = "Ви кладете яйце гіппогрифа в машину. Лунає серія звукових сигналів, супроводжувана дивними механічними звуками.$B$BСхоже, «Еггометр» зважив, виміряв і упакував ваше яйце. Оце й справді швидке обслуговування!",
},

[8897] = {
    en = "Dearest Colara,",
    T = "Найдорожча Колара,",
    D = "Мені доводиться нести варту тут, біля воріт, але я постійно хвилююся за свою кохану, Колару. Я бачу її лише на кілька годин, якщо пощастить, і… ну, погляньте тільки на мене. Я отримую зарплату рядового офіцера, і мене будь-якого дня можуть відправити на фронт.$B$BЧи не забуде вона про мене? У місті багато чоловіків. Багато багатих.$B$BУ будь-якому разі, я щось там накидав… нічого особливого, але якби ти міг передати це їй від мене, було б чудово.",
    O = "Передайте ретельно написану записку лейтенанта Хелдрика Коларі Дін біля банку в Штормграді.",
    P = "Привіт, красунчику. Чим можу тобі допомогти?",
    C = "О, як це мило! Він вперше мені щось надіслав. Як гадаєш, він починає ставитися до мене серйозно?$B$BКолара Гелдрік? Гадаю, це звучить непогано. О, але я забігаю наперед. Дякую.",
},

[8898] = {
    en = "Dearest Colara,",
    T = "Найдорожча Колара,",
    D = "Я познайомився з однією дівчиною у Штормвінд, коли востаннє був там у справах банку. Вона вкрала моє серце. Тепер я не можу перестати про неї думати! Я хотів би надіслати їй це повідомлення — я переписав його вже дванадцять разів!$B$BПоштова скринька вже переповнена, а я хочу бути впевненим, що воно дійде до адресата.$B$BЯкщо ти прямуєш у той бік, чи не міг би ти мені допомогти?",
    O = "Доставте зім'ятий лист до Колари Дін біля банку в Штормграді.",
    P = "Привіт, красунчику. Чим можу тобі допомогти?",
    C = "Тормек? О так, я його пам’ятаю. У нього була досить гарна борода, а під нею — приємна посмішка.$B$BО, не можу повірити, що він мене впізнав!",
},

[8899] = {
    en = "Dearest Colara,",
    T = "Найдорожча Колара,",
    D = "Як описати її красу? Тисячі років слів — а я все одно не знаходжу слів.$B$BЦі смертні збивають з пантелику і роблять нас белькотливими дурнями.$B$BЯ занадто довго вдивлявся в ці слова. Більше ніякого виразного змісту я не можу з них витиснути. Ні, вона має отримати це зараз, інакше якийсь інший залицяльник неодмінно приверне її увагу.",
    O = "Доставте «Бездоганний лист» Коларі Дін біля банку в Штормграді.",
    P = "Привіт, красунчику. Чим можу тобі допомогти?",
    C = "Я ще ніколи не отримувала нічого подібного. Як чудово!",
},

[8900] = {
    en = "Dearest Elenia,",
    T = "Найдорожча Еленія,",
    D = "Вона була така сумна. Я це побачив, коли зміг зазирнути за її зовнішній вигляд. Тобто, вона здавалася сумною — хіба не так?$B$BАле після розмови з нею між нами виник зв’язок. Я не думав, що хтось зможе зрозуміти мої думки, але вона змогла.$B$BКоли я розповів про це іншим, вони посміялися з мене, тож я більше з нею не розмовляв. Але я сумую за нею. Чи не могли б ви передати їй цей лист від мене? Я хочу бути впевненим, що він потрапить до неї.",
    O = "Передайте злегка пом'яту записку Еленії Хейдон, яка знаходиться біля банку в Підмісті.",
    P = "А, до речі, чим я заслужив таку честь?",
    C = "Не очікував би, що орк виявиться таким красномовним. Звісно, досі у нас так і не було нагоди по-справжньому їх пізнати. Дякую, що показали мені це.",
},

[8901] = {
    en = "Dearest Elenia,",
    T = "Найдорожча Еленіє,",
    D = "Чи знав ти коли-небудь кохання, юнаку? Для мене це було чимось чужим аж донедавна, коли я зустрів дівчину з Підмістя — Еленію. Для представників мого роду досить рідко буває, щоб хтось заглядав за межі нашого світу, не кажучи вже про тих, хто належить до Забутих.$B$BАле тепер думки про неї не дають мені спокою ні вдень, ні вночі.$B$BЯкщо зможеш, передай їй цей лист. Я хочу, щоб вона приїхала сюди, до Мулгора. Сподіваюся, вона погодиться.",
    O = "Передайте ретельно написаний лист Еленії Хейдон біля банку в Нижньому місті.",
    P = "А, до речі, чим я заслужив таку честь?",
    C = "Які теплі слова пише мені Темма. Але, хоч як би мене не зворушували його слова, я не можу прийняти кохання таурена. У думках, тілі та душі ми надто різні.$B$BДобре, що мені не доводиться отримувати ці його думки особисто. Я не змогла б знести, що розбиваю йому серце.",
},

[8902] = {
    en = "Dearest Elenia,",
    T = "Найдорожча Еленіє,",
    D = "Дуже давно я був заручений з Еленією, моєю коханою з дитинства. Минуло багато років, відколи я востаннє думав про неї, але останнім часом вона часто спадає мені на думку.$B$BМожливо, навіть попри все, що минуло, у наших життях ще знайдеться місце для нашої любові.$B$BЯ впевнений, що вона теж змінилася. Чи не могли б ви передати їй цей лист від мене? Я занадто хвилююся, щоб вручити його особисто.",
    O = "Передайте цей лист, написаний з любов’ю, Еленії Хейдон біля банку в Підмісті.",
    P = "А, до речі, чим я заслужив таку честь?",
    C = "Це пробуджує спогади з минулого життя, $N. Еленія Тор. Це мало бути моє ім’я, знаєш. Ми б влаштували прекрасну церемонію на березі озера. Коли він піде на пенсію, ми знайдемо ферму, де зможемо доживати свої дні.$B$BТоді це були прості мрії.$B$BАле якби він побачив мене зараз, сумніваюся, що він взагалі впізнав би в мені Еленію. Лише холодне тіло і мертве серце...",
},

[8903] = {
    en = "Dangerous Love",
    T = "Небезпечне кохання",
    D = "У цій епідемії кохання є щось неприродне. Це непристойно, це ріже око, а в гіршому випадку це може становити загрозу для безпеки самого Альянсу.$B$BТільки уявіть: а що, якби охоронці також піддалися цій дивній хворобі? Треба щось робити.$B$BПідійдіть до одного з охоронців тут, у Штормграді, і перевірте, чи не піддалися вони цій дурниці.",
    O = "Здобудьте картку гвардійця Штормграда та поверніть її Арістану Моттару в Штормграді.",
    P = "Чи я мав рацію, турбуючись? Чи охоронці теж страждають від цієї любовної хвороби?",
    C = "Тож це правда. Це неймовірно. Як це могло статися? Дайте мені хвилинку подумати. У цьому має бути якась причина.",
},

[8904] = {
    en = "Dangerous Love",
    T = "Небезпечне кохання",
    D = "У цій епідемії кохання є щось неприродне. Це огидно, і, оскільки вона послаблює нашу захисну здатність, це може становити загрозу для всіх нас.$B$BДосить погано, що так багато наших людей втягнуто в цю безглузду поведінку. Але, як на мене, це поширилося навіть на наших охоронців, які мали б бути імунними до таких речей.$B$BЗнайдіть одного з наших охоронців і перевірте, чи не піддався він цій дурості.",
    O = "Здобудьте «Запліснявілу картку Охоронця» та принесіть її Фенстаду Аргілу в Підмісті.",
