[8921] = {
    en = "The Ectoplasmic Distiller",
    T = "«Ектоплазматичний дистилятор»",
    D = "А, тобі потрібен мій останній проект… позавимірний детектор привидів! На жаль, у мене закінчилися кошти та робоча сила.$B$BТи готовий допомогти? Чудово! Наше перше завдання — створити пристрій для збору самої сутності смерті! Створити ектоплазмовий дистилятор буде нелегко, $N.$B$BМені знадобиться, щоб ти приніс мені арканітовий перетворювач, кілька великих вічних есенцій та олію з кам’яної луски. Також мені знадобиться трохи вулканічного попелу з лавових озер у Палаючих степах для створення фільтра.",
    O = "Поверніться до Мукса Манаскремблера в Гаджетзані з 1 «Делікатним арканітовим перетворювачем», 4 «Великими вічними есенціями», 10 «Каменною олією», 25 «Вулканічним попелом» та 40 золотими монетами.",
    P = "Я розумію, що матеріали трохи дорогі... але запевняю вас, що кожен із них буде необхідним!",
    C = "Це саме ті матеріали, які мені були потрібні. І дуже вчасно, $N!$B$BВже за кілька хвилин твій дистилятор буде готовий до роботи! А поки що візьми це як винагороду за допомогу в моєму проекті.",
},

[8922] = {
    en = "A Supernatural Device",
    T = "Надприродний пристрій",
    D = "Я мушу знайти спосіб поговорити з Антіоном Гармоном… а точніше — з його привидом!$B$BЯ знаю одного інженера, який виявляє дивний інтерес до надприродного. Він стверджує, що може сконструювати машину, яка дозволить йому спілкуватися з померлими!$B$BЗібрана тобою кров призначалася саме для нього; вирушай до Гаджетзана й віднеси її йому як плату за його послуги!",
    O = "Віднесіть запечатаний контейнер з кров’ю до Мукса Манаскремблера в Гаджетзані, що в Танарісі.",
    P = "У тебе для мене щось є?",
    C = "Чудово! Якраз закінчувалися!$B$BТи кажеш, що тебе прислала Деліана?",
},

[8923] = {
    en = "A Supernatural Device",
    T = "Надприродний пристрій",
    D = "Ти, мабуть, досить сміливий, якщо залишився після всього цього. Або ж я привернув твою увагу тим шматком обладунку, який тобі дав. У мене є ще такі, якщо ти й надалі зацікавлений у тому, щоб допомогти мені.$B$BЗразки отрути, які ти зібрав, призначені для мого знайомого, Мукса Манаскрамблера — інженера, який цікавиться надприродним. Його останній проєкт — пристрій, що дозволяє спілкуватися з померлими! Моя остання надія — зв’язатися з Антіоном і дізнатися більше про моє становище.",
