[8945] = {
    en = "Dead Man's Plea",
    T = "Благання померлого",
    D = "Я надам тобі інформацію, про яку ти просиш, $N. Але зараз є більш нагальні справи.$B$BМою кохану дружину взяли в полон неживі негідники з Рівендаре.$B$BЯ рішуче заперечував проти того, щоб вона приєдналася до безглуздого хрестового походу «Срібного Світанку», але це вже не має значення. Ти повинен завершити те, що я намагався зробити, — ти повинен врятувати Ісіду з лап барона!",
    O = "Зайдіть до Стратхолма та врятуйте Ісіду Гармон від барона Рівендаре.",
    P = "Скажи, чи жива Ісіда?",
    C = "Дякую, що врятували мене... Я боявся за своє життя. Будь ласка, прийміть це як невеликий знак моєї вдячності.$B$BАнтіон — це... ні... це не може бути він...",
},

[8946] = {
    en = "Proof of Life",
    T = "Доказ того, що людина жива",
    D = "Найжорстокіша доля — те, що мій коханий загинув, намагаючись врятувати мене. Проте ти стверджуєш, що маєш здатність спілкуватися з ним.$B$BПередай йому цей медальйон як доказ того, що я в порядку. Він не повинен затримуватися в цьому світі; моє серце цього не витримає.$B$BПрощавай, $N. Я завжди буду тобі вдячна.",
    O = "Віднесіть медальйон Ісиди до Антіона Гармона у Східних Землях Чуми.",
    P = "Ісіда... вона жива?",
    C = "Цей медальйон... ти знайшов її! Нарешті я зможу спочивати з миром.$B$BТепер я відповім на всі твої запитання, $N. Але поспішай, бо мені залишилося небагато часу в цьому світі.",
},

[8947] = {
    en = "Anthion's Strange Request",
    T = "Дивне прохання Антіона",
    D = "Ми не усвідомлювали важливості медальйона Валтхалака, тому його розділили разом з рештою трофеїв. Перший уламок забрав карлик на ім’я Телдрен. Я спробував відібрати його в нього, але він побив мене до напівсмерті. Вам доведеться відібрати цей уламок силою.$B$BЗ останніх новин, що я про нього чув, він став гладіатором у карликів Темного Заліза. Хоча змусити його битися з тобою буде не так уже й просто.$B$BЗбери для мене наступні матеріали. Вони тобі знадобляться.",
    O = "Принесіть 3 злитки темного заліза, 20 одиниць зачарованої шкіри, 3 одиниці місячної тканини та 4 одиниці вичиненої міцної шкіри до Антіона Гармона у Східних Землях Чуми.",
    P = "Ти отримав ті матеріали, про які я просив, $N?",
    C = "Чудово. Я перетворю це на щось, що краще відповідатиме нашим потребам.",
},

[8948] = {
    en = "Anthion's Old Friend",
    T = "Старий друг Антіона",
    D = "Телдрен — не з тих, хто охоче бере участь у чесному поєдинку. Я створив цей прапор, щоб відобразити кольори його роду.$B$BЗавдяки додатковим магічним чарам цей прапор спровокує його так, що він не зможе встояти.$B$BМій давній знайомий на ім’я Фалрін знає точний порядок дій. У нього є особливий спосіб… дратувати людей. Ти знайдеш його в бібліотеці в Діре-Маулі.",
    O = "Віднесіть незавершене «Прапор провокації» до Фалріна Трешшепера в бібліотеці в Діре-Маулі.",
    P = "Говори, незнайомцю, хіба ти не бачиш, що я зайнятий?",
    C = "Ти кажеш, що тебе прислав Антіон? А я думав, він помер. Мабуть, у житті я чув і дивніші речі.$B$BГаразд, тоді. Що ти хочеш, щоб я зробив із цим прапором?",
},

[8949] = {
    en = "Falrin's Vendetta",
    T = "«Помста Фалріна»",
    D = "Так, це правда, що я знайомий із тим заклинанням, яке тобі потрібно, $c. Проте я не з тих, хто робить послуги просто так, навіть якщо тебе сюди прислав мій старий друг.$B$BЯ відчуваю лише ненависть і презирство до наших брутальних сусідів-огрів. І не тільки до них — я ненавиджу послідовників Омока так само сильно, як і тих, хто слідує за королем Гордоком.$B$BЯ хочу, щоб ти їх убив. Вбий їх якнайбільше! Принеси мені намиста, які вони носять на шиї, як доказ того, що ти виконав завдання. Зроби це, і ми поговоримо про твоє прохання.",
    O = "Зберіть 25 бойових намистин огрів у огрів у «Діре-Маулі» або «Шпилі Чорної Скелі» та поверніться до Фалріна Трешейпера в Атенеумі в «Діре-Маулі».",
    P = "Ти виконав те прохання, з яким я до тебе звернувся, $N?",
    C = "Хм... як не дивно, мені аж ніяк не стало легше від того, що мій брат загинув від рук тих нелюдів.$B$BНу що ж, ти виконав свою частину угоди. Подивимося, що я можу для тебе зробити.",
},

[8950] = {
    en = "The Instigator's Enchantment",
    T = "Чарівність Підбурювача",
    D = "Я можу досить легко накласти на прапор те зачарування, яке тобі потрібно, $N. На жаль, у мене немає необхідних матеріалів, оскільки про таке зачарування просять дуже рідко.$B$BМені знадобиться есенція одного з привидів Елдрета, що бродять цими залами, жменя темних рун Шоломанса та кілька великих блискучих осколків. Принесіть мені ці реагенти, і я виконаю це завдання для вас.",
    O = "Принесіть Фалріну Трешейперу в «Діре Маул» наступне: 1 «Есенцію глузливого привида», 4 «Темні руни» та 8 «Великих блискучих осколків».",
