[8960] = {
    en = "Bodley's Unfortunate Fate",
    T = "Нещаслива доля Бодлі",
    D = "Тож нам треба знайти решту медальйона? Знайти Бодлі буде не так вже й просто. Він повернувся до Гори Чорної Скелі, щоб спробувати знову проникнути до Шпиля Чорної Скелі, і більше не повернувся.$B$BЯ б порадив взяти з собою прилад гобліна для виявлення привидів, бо, боюся, могло статися найгірше.",
    O = "Відправляйтеся до гори Блекрок і скористайтеся «Міжвимірним виявником привидів», щоб знайти Бодлі поблизу Шпиля Блекрок.",
    P = "",
    C = "Я так рада, що ти мене бачиш. Нарешті з кимсь можна поговорити!$B$BЧи допоможеш ти нам, $N? Допоможеш виправити те зло, яке ми заподіяли, і навести лад? Якщо це правда, що ти вже маєш верхню частину амулета лорда Валталака, то, гадаю, я зможу вказати тобі правильний шлях, щоб ти знайшов інші дві частини, об’єднав їх і поклав край усьому цьому.$B$BО, до речі, привіт, мене звати Бодлі. Приємно познайомитися!",
},

[8961] = {
    en = "Three Kings of Flame",
    T = "Троє королів полум’я",
    D = "Щоб викликати лорда Валталака, нам спочатку потрібно зібрати інші дві третини амулета. Для цього нам знадобиться жаровня та спеціальне вугілля, яке можна в ній розпалити.$B$BУ трьох «вельмож вогню» — лорда Інцедіуса в Глибинах Чорної Скелі, піроохоронця Емберсіра в Шпилі Чорної Скелі та герцога Синдерса в Сілітусі — є те, що нам потрібно. Зберіть у кожного з них по шматочку їхніх останків, а потім поверніться до мене зі Священним жаровим ковшем, який можна придбати у «Срібного Світанку», якщо ви маєте у них репутацію «Почесний».",
    O = "Зберіть «Інкендіцит» Інкендіуса, «Жар» Емберсіра та «Попіл» Сайндерса, а також «Освячений жаровню», і поверніть їх Бодлі в горі Чорна Скеля.",
    P = "Це була наша дурість... наша загибель — те, що ми взяли те останнє замовлення. Якби тільки ми не вкрали ненавмисно дух лорда Валталака, який містився в амулеті; якби тільки в нашій групі найманців не було тих, хто виявився настільки жадібним і розділив його між собою. Я був би сьогодні живий, можливо, випивав би пиво або підкидав би в повітря одну зі своїх дітей.$B$B$N, не дозволяйте, щоб жадібність негідників із нашої колишньої найманої компанії стала і вашою загибеллю.",
    C = "Я вражений, $C, але не можна гаяти часу. Я доручу тобі наступне завдання, адже тобі ще потрібно буде дістати кілька важливих компонентів, перш ніж ми зможемо продовжувати.$B$BЗвернися до мене знову, коли відчуєш, що готовий до виклику, який чекає на тебе попереду.",
},

[8962] = {
    en = "Components of Importance",
    T = "Важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли у нас є жаровня та засоби для її розпалювання, нам все ще потрібен ще один компонент, яким її наповнити; щось, що стане достатньо сильним фокусом, аби привабити дух мого покійного, колишнього товариша.$B$BМор Грейхуф, наш найвидатніший друїд, мав багато близьких друзів серед членів «Круга Сенаріона», деякі з яких загинули від рук силітидів. Мені потрібно, щоб ти дістав кілька «Друїдських останків» у силітидів, які мешкають в околицях Хайв’Регала на південному сході Сілітуса.",
    O = "Знайдіть «Останки друїда» та поверніть їх Бодлі в горі Чорна Скеля.",
    P = "То ти вже повернувся, $C, з тим, що я тебе послав зібрати?",
    C = "Відмінно зроблено, $N. Я влию сутність останків у жаровню.$B$BТепер залишається лише спуститися в нижню частину Шпиля Чорної Скелі, до зали, де в Таз'Алаорі мешкає Воєнний Майстер Вун, і за допомогою жаровні викликати спотворений дух мого колишнього соратника, Мора Грейхуфа. Він не знайде спокою, доки у нього не заберуть частину амулета.",
},

[8963] = {
    en = "Components of Importance",
    T = "Важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли у нас є жаровня та все необхідне, щоб її розпалити, нам ще потрібен один компонент, яким її потрібно наповнити; щось, що стане достатньо сильним центром тяжіння, аби привабити дух мого покійного колишнього товариша.$B$BІсаліен, наша жриця, виросла у Вінтерспрингу, у селі Старбріз. Мені потрібно, щоб ти дістав реліквію селища Старбріз у гігантів Фростмаул з ущелини Фроствіспер на півдні Вінтерспринга, які час від часу влаштовують набіги на північ.",
    O = "Знайдіть реліквію «Селище Старбріз» і поверніть її Бодлі в горі Блекрок.",
    P = "То ти вже повернувся, $C, з тим, за чим я тебе відправив?",
    C = "Відмінно попрацював, $N. Я влию сутність реліквії в жаровню.$B$BТепер залишається лише відправитися до Святилища Елдретарра у східному крилі Діре-Маула та за допомогою жаровні викликати дух моєї колишньої соратниці, Ісаліен. Її дух був спотворений тим, що вона володіла частиною амулета Валталака та частиною його душі, що містилася в ньому.",
},

[8964] = {
    en = "Components of Importance",
    T = "Важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли у нас є жаровня та засоби для її розпалювання, нам все ще потрібен ще один компонент, яким її наповнити; щось, що забезпечить достатньо сильний фокус, аби викликати останки моїх покійних колишніх товаришів.$B$BБрат і сестра, Джарієн та Сотос, були прихильниками вчення «Скарлетного хрестового походу». Вони прагнули стати лицарями в цій огидній організації. Відправляйся до «Руки Тира» у Східних Землях Чуми та забери там у преторіанців «Блискучий меч фанатизму».",
    O = "Знайдіть «Блискучий меч фанатизму» та поверніть його Бодлі в горі Чорна Скеля.",
    P = "То ти вже повернувся, $C, з тим, за чим я тебе відправив?",
    C = "Відмінно виконано, $N. Я вкладу суть меча в жаровню.$B$BТепер залишилося лише проникнути до «Багряного трону» всередині «Скарлатового бастіону» у Стратхолмі та за допомогою жаровні викликати останки моїх колишніх соратників — Джарієна та Сотоса. Їхні душі ще більше спотворилися через те, що вони заволоділи уламком амулета Валталака та духом, що в ньому мешкає.",
},

[8965] = {
    en = "Components of Importance",
    T = "Важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли у нас є жаровня і засоби, щоб її розпалити, нам ще потрібен один компонент, яким її потрібно наповнити; щось, що стане достатньо сильним фокусом, аби привабити дух мого покійного колишнього товариша.$B$BНекромант-огр Кормок, який подорожував разом із нами, із задоволенням викликав душі вигнаних померлих з Острова Очищення, що лежить біля південного узбережжя Підніжжя Хіллсбрада. Відправляйся туди й знайди трохи Попелу Душ Вигнаних серед їхніх останків.",
    O = "Знайдіть «Попіл душ вигнанців» і поверніть його Бодлі в горі Чорна Скеля.",
    P = "То ти вже повернувся, $C, з тим, що я тебе послав зібрати?",
    C = "Відмінно виконано, $N. Я влию суть попелу в жаровню.$B$BТепер залишилося лише проникнути до Шоломанса, до покоїв Раса Фроствіспера, і за допомогою жаровні викликати духа мого колишнього соратника, Кормока. Уламок амулета та дух Валталака, що міститься в ньому, ще більше спотворили його, і він не знайде спокою, доки ти силою не відбереш це у нього.",
},

[8966] = {
    en = "The Left Piece of Lord Valthalak's Amulet",
    T = "Ліва частина амулета лорда Валталака",
    D = "Мій друг, Мор Грейхуф, став першою жертвою одержимості уламком амулета лорда Валталака та фрагментом згубного духу, що містився в ньому. Викравши книгу заклинань і амулет Валталака, ми втекли, рятуючи життя, з верхньої частини Шпиля Чорної Скелі. По дорозі Мор впав у нижню частину вежі.$B$BПізніше ми дізналися, що він вижив після падіння, але його схопив і катував воєнний майстер Вун. Кілька примарних вбивць проникли всередину й убили його прямо на очах у Вуна.",
    O = "Використайте «Жаровню заклику», щоб викликати дух Мора Грейхуфа та вбити його. Поверніться до Бодлі в горі Чорна Скеля, маючи при собі ліву частину амулета лорда Валталака та «Жаровню заклику».",
    P = "Тож все завершено? Ти знайшов ліву частину амулета лорда Валталака і нарешті дав спокій душі мого старого товариша, Мора Грейхуфа?",
    C = "Ти зробив велику справу, $N. Одна душа спочиває з миром, але попереду ще багато роботи, перш ніж ми зможемо залишити все це позаду.$B$BНа жаль, я не знаю, де перебуває той, хто помер, маючи при собі праву частину амулета. Але не бійся: за життя я трохи займався мистецтвом ворожіння, тож маю для тебе ще одне завдання, яке допоможе нам відшукати останню частину.",
},

[8967] = {
    en = "The Left Piece of Lord Valthalak's Amulet",
    T = "Ліва частина амулета лорда Валталака",
    D = "Пізніше, коли ми самі робили все можливе, щоб вижити, нам стало відомо, що Ісаліен, жриця нічних ельфів із нашої групи, вирушила до прабатьківського міста нічних ельфів, яке зараз відоме як Дайр-Маул. З того, що нам вдалося з’ясувати, вона вирушила туди як з особистих причин, так і для того, щоб розгадати таємниці частини амулета, що була в її володінні.$B$BОднак їй це не вдалося. До нас дійшла звістка, що біля Святилища Елдретарра на неї влаштував засідку Альззін Дикий Творець разом зі своїми військами.",
    O = "Використайте «Жаровню заклику», щоб викликати дух Ісаліен і знищити її. Поверніться до Бодлі в горі Чорна Скеля, маючи при собі ліву частину амулета лорда Валталака та «Жаровню заклику».",
    P = "Напевно, ти ще не впорався із порятунком душі Ісаліена та пошуком лівої частини амулета лорда Валталака, $N?",
    C = "Дякую, $N, за те, що ти дав спокій душі Ісаліен. Тепер, можливо, вона знайде спокій у своїй богині. Але попереду нас ще чекає чимало роботи, якщо ми хочемо вибратися з цієї халепи, в якій опинилися.$B$BНа жаль, я не знаю, де перебуває той, хто помер, маючи при собі праву частину амулета. Але не бійтеся; за життя я трохи займався мистецтвом ворожіння, тож маю для вас ще одне завдання, яке допоможе нам відшукати останню частину.",
},

[8968] = {
    en = "The Left Piece of Lord Valthalak's Amulet",
    T = "Ліва частина амулета лорда Валталака",
    D = "Брат і сестра, Джарієн та Сотос, вирішили приєднатися до «Скарлетного хрестового походу» після розформування нашої найманської роти. Вони забрали з собою ліву частину амулета лорда Валталака. Я кажу: «І добре, що їх немає», але нам потрібно повернути цю частину.$B$BЗ того, що нам вдалося з’ясувати, їх насправді вбив сам Великий хрестоносець Датрохан за те, що вони не пройшли обряди ініціації у його покоях у «Скарлатовому бастіоні».$B$BУ будь-якому разі, нам… тобто тобі, все одно доведеться повернути цю частину амулета.",
    O = "Використайте «Жаровню заклику», щоб викликати Джарієна та Сотоса і вбити їх. Поверніться до Бодлі в горі Чорна Скеля, маючи при собі ліву частину амулета лорда Валталака та «Жаровню заклику».",
    P = "Тож чи означає це, $C, що ти вже дав спокій душам тих двох дурнів і знайшов ліву частину амулета лорда Валталака?",
    C = "Мабуть, це на краще, що душі тих двох нарешті знайшли спокій, хоч я й не любив їх, коли вони були живі. У будь-якому разі, ми отримали те, що шукали, і це, безперечно, добре!$B$BНа жаль, я не знаю, де перебуває той, хто помер, маючи при собі потрібну частину амулета. Але не бійтеся: за життя я трохи займався мистецтвом ворожіння, тож маю для вас ще одне завдання, яке допоможе нам відшукати останню частину.",
},

[8969] = {
    en = "The Left Piece of Lord Valthalak's Amulet",
    T = "Ліва частина амулета лорда Валталака",
    D = "Тепер у нас є все необхідне, тож настав час обговорити, кого саме ти збираєшся викликати.$B$BКормок був цілком пристойним для огра, аж доки не захопився некромантією. Після цього ситуація стала моторошною практично для всіх членів загону. Тож не дивно, що він взяв свою частину амулета й повернувся до свого нового дому — Шоломанса.$B$BАле навіть там, а може, саме там, він не був у безпеці від примарних вбивць. Вони вбили його просто на очах у його господаря, Раса Фроствіспера.",
    O = "Використайте «Жаровню заклику», щоб викликати духа Кормока та вбити його. Поверніться до Бодлі в Чорноскельній горі, маючи при собі ліву частину амулета лорда Валталака та «Жаровню заклику».",
    P = "Я висловлюю тобі, $N, свою вдячність, якщо ти повернувся з лівою частиною амулета. Якщо ж ні, будь ласка, подбай про це, адже, запевняю тебе, часу гаяти немає!",
    C = "Гарна робота, $N! Кормок був не таким вже й поганим, як на огра, принаймні поки був живий, тож сподіваюся, він отримає той спокій, на який заслуговує. Але попереду ще багато роботи. $B$BНа жаль, я не знаю, де перебуває той, хто помер, маючи при собі праву частину амулета. Але не бійтеся; за життя я трохи займався мистецтвом ворожіння, тож маю для вас ще одне завдання, яке допоможе нам відшукати останню частину.",
},

[8970] = {
    en = "I See Alcaz Island In Your Future...",
    T = "Я бачу острів Альказ у твоєму майбутньому...",
    D = "Як я вже казав, $c, за свого життя я навіть замислювався над тим, щоб стати ворожителем. Але насправді це не приносило стільки прибутку, скільки можна було б уявити, головним чином тому, що це небезпечно, а реагенти — рідкісні й дорогі. Проте я знаю достатньо, щоб визначити місцезнаходження останнього елемента амулета, а разом із ним — і дух мого колишнього товариша.$B$BОсь тут і потрібна твоя допомога, $N. Мені потрібно, щоб ти вирушив на острів Альказ біля узбережжя Болота Дастволл і зібрав «Кров’яні водорості» у нагів Страшаз, які там мешкають.",
    O = "Зберіть 20 одиниць «Кривавої водорості» у наги Страшаз, а потім поверніться до Бодлі в горі Чорна Скеля.",
    P = "Кров'яний ламінарій, $N, велика купа цього — ось що мені потрібно для підживлення моїх магічних заклинань. Тобі, мабуть, доведеться взяти з собою щонайменше кількох друзів на острів Альказ, щоб його зібрати... ці Страшази — справді неприємна зграя!",
    C = "Чесно кажучи, $N, я здивований, що ти повернувся цілим і неушкодженим. Хоча, з іншого боку, думаю, острів Альказ — це зараз найменша з твоїх турбот.$B$BГаразд, дай мені хвилинку... ворожіння — це не те, що можна просто клацнути пальцями й очікувати точних відповідей.",
},

[8977] = {
    en = "Return to Deliana",
    T = "Повернутися до Деліани",
    D = "Було дуже приємно працювати з тобою, $N. Ось готовий продукт.$B$BСподіваюся, він стане тобі в нагоді у твоїх поточних справах. І, до речі, якщо не заперечуєш, допоможи поширити інформацію. Я б не проти мати більше клієнтів!",
    O = "Принесіть «Прилад для виявлення позавимірних привидів» Деліані в Айронфорджі.",
    P = "Ти повернувся?",
    C = "Чудово! Ти добре впорався, $N. Не впевнений, що можу довіряти майстерності гобліна, але у мене немає іншого вибору.",
},

[8978] = {
    en = "Return to Mokvar",
    T = "Повернутися до Моквара",
    D = "Було приємно працювати з вами, $N. Ось готовий продукт.$B$BСподіваюся, він стане вам у нагоді у ваших поточних справах. І, до речі, якщо не складно, допоможіть поширити інформацію. Я був би радий отримати більше клієнтів!",
    O = "Поверніться до Моквара в Оргримарі з «Міжвимірним виявником привидів».",
    P = "Ви вже повернули пристрій?",
    C = "Ти повернувся з пристроєм! Я вражений твоєю відданістю, $N. Чудова робота.",
},

[8979] = {
    en = "Fenstad's Hunch",
    T = "Передчуття Фенстада",
    D = "Гадаю, я знаю причину цієї недавньої поведінки. Чи відчували ви на вітрі новий аромат, що перебиває сморід каналів? Нові одеколони та парфуми, які увійшли в моду?$B$BНаше мислення затьмарене якоюсь огидною алхімією.$B$BЄ лише один спосіб переконатися — принесіть пляшку одеколону та парфумів моєму другові, аптекарю Зінге. Королівське товариство аптекарів з’ясує правду.$B$B Я відшкодую вам витрати на їх придбання, коли ви повернетеся.",
    O = "Принесіть 1 флакон одеколону та 1 флакон парфумів до аптекаря Зінге в Аптекаріумі Підміста.",
    P = "Чим можу вам допомогти?",
    C = "Бачу, це ще одна з його маній, Фенстада. Невже він вважає, що Королівське товариство аптекарів не має нічого кращого, ніж проводити його дрібні розслідування?$B$BГаразд, я ще раз піду йому назустріч.",
},

[8980] = {
    en = "Zinge's Assessment",
    T = "Оцінка Зінге",
    D = "Це несподівано. Схоже, Фенстад, можливо, все-таки натрапив на щось. Я виявив сліди речовин, що використовуються в зіллях для контролю над розумом.$B$BНе є чимось надзвичайним, що парфуми містять деякі з цих речовин, але кілька інгредієнтів, які я виявив... Це серйозна алхімія, на рівні здібностей члена Королівського товариства аптекарів.",
    O = "Поверніться до Фенстада Аргіла біля банку в Підмісті.",
    P = "",
    C = "Отже, я мав рацію. Не можна гаяти часу. Треба з’ясувати, звідки беруться ці зіпсовані аромати.$B$BОсь, це вам як компенсація за куплені одеколон і парфуми.",
},

[8981] = {
    en = "Gift Giving",
    T = "Подарунки",
    D = "",
    O = "",
    P = "Ви прийшли, щоб подарувати своєму улюбленому лідеру знак любові та шани?",
    C = "Чудово! Чудово! Я додам це до купи інших подарунків.$B$BЯ й не очікував, що їх буде так багато! Ви, мабуть, справді любите своїх керівників.$B$BА тепер дозвольте мені додати ще один до загальної кількості...",
},

[8982] = {
    en = "Tracing the Source",
    T = "Відстеження джерела",
    D = "Ми маємо з’ясувати, хто є постачальником. Я помітив, що аптекарка Катріна мала у своєму рюкзаку флакон парфумів. Вона сказала мені, що придбала його у Нормана, власника готелю.",
    O = "Поговоріть із трактирником Норманом у Підмісті.",
    P = "",
    C = "Ах так, я нещодавно отримав партію парфумів та одеколону. Не знаю, як довго вони протримаються на полицях — схоже, ніхто не може ними насититися.$B$BЯкщо мене запитати, то я не розумію, чому з цього роблять таку велику справу.",
},

[8983] = {
    en = "Tracing the Source",
    T = "Відстеження джерела",
    D = "З моїм товаром щось не так? Ну, я ще ніколи не бачила, щоб стільки людей так сильно чогось хотіли.$B$BЯ придбала цей товар у торговця на ім’я Мара Реннік. Вона нещодавно переїхала до міста.$B$BВона згадала, що має кілька товарів, які потрібно доставити кравцю в Кварталі магів.",
    O = "Поговоріть з Марою Реннік у кравецькій майстерні в Кварталі магів Підміста.",
    P = "",
    C = "Боюся, що я продав весь свій запас парфумів та одеколону Норману, господареві готелю. Якщо ви хочете їх придбати, вам слід поговорити з ним — за умови, що у нього ще щось залишилося.$B$BПроте не варто зволікати. Гадаю, ви знайдете $g одеколон:парфуми; неперевершеними.",
},

[8984] = {
    en = "The Source Revealed",
    T = "Джерело розкрито",
    D = "Послухайте, дії якогось недобросовісного аптекаря — не моя справа. Якщо він підриває наші зусилля, то я першим вкажу вам правильний напрямок$B$BА якщо він невинний, то йому нема чого приховувати, чи не так?$B$BЯ придбав товари в аптекаря Стафрона Лерента. Він працює у віддаленому місці за маєтком Рейвенхолдт, на пагорбах над Гілсбрадом. Чесно кажучи, він мені здався трохи дивним.",
    O = "Знайдіть аптекаря Стаффрона Лерента в Передгір’ях Хіллсбрада, за маєтком Рейвенхолдт.",
    P = "",
    C = "Так, це я створив ці аромати. Чудовий запах, чи не так? Непереборний.$B$BЯк тільки воїни Альянсу та Орди однаково піддадуться цим почуттям кохання, вони будуть безсилі зупинити підйом Ради Тіней.$B$BВони будуть ослаблені, непідготовлені. Турбуючись про своїх коханих, вони втратять свою силу.$B$BРішення було таким простим. Чому я так довго не міг його знайти? Слабкість усіх криється в серці. І ви нічого не зможете вдіяти, щоб зупинити неминуче.",
},

[8985] = {
    en = "More Components of Importance",
    T = "Інші важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам все ще потрібен ще один компонент, яким можна наповнити жаровню; щось, що забезпечить достатньо сильний фокус, щоб привабити дух мого покійного колишнього товариша.$B$BІзаліен, наша жриця, виросла у Вінтерспрингу, у селищі Старбріз. Мені потрібно, щоб ти здобув реліквію селища Старбріз у гігантів Фростмаул з ущелини Фроствіспер на півдні Вінтерспринга, які час від часу влаштовують набіги на північ.",
    O = "Знайдіть реліквію «Селище Старбріз» і поверніть її Бодлі в горі Блекрок.",
    P = "То ти вже повернувся, $C, з тим, що я тебе послав зібрати?",
    C = "Відмінно виконано, $N. Я влию сутність реліквії в жаровню.$B$BТепер залишається лише відправитися до Святилища Елдретарра у східному крилі Діре-Маула та за допомогою жаровні викликати дух моєї колишньої соратниці, Ісаліен. Її дух був спотворений через те, що вона володіла частиною амулета Валталака та частинкою його душі, що містилася в ньому.$B$BО, до речі, у мене залишилося трохи кривавої водорості з твоєї подорожі на острів Альказ, тож я зробив з неї кілька зілля для тебе. Обирай на свій смак!",
},

[8986] = {
    en = "More Components of Importance",
    T = "Інші важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам все ще потрібен ще один компонент, яким можна наповнити жаровню; щось, що стане достатньо сильним осередком, аби привабити дух мого покійного, колишнього товариша.$B$BМор Грейхуф, наш найвидатніший друїд, мав багато близьких друзів серед членів Кола Сенаріона, деякі з яких загинули від рук силітидів. Мені потрібно, щоб ти дістав кілька друїдських останків у силітидів, які мешкають в околицях Хайв’Регал на південному сході Сілітуса.",
    O = "Знайдіть «Рештки друїда» та поверніть їх Бодлі, що знаходиться всередині Гори Чорної Скелі.",
    P = "То ти вже повернувся, $C, з тим, що я тебе послав зібрати?",
    C = "Відмінно виконано, $N. Я влию сутність останків у жаровню.$B$BТепер залишається лише спуститися в нижню частину Шпиля Чорної Скелі, до кімнати, де в Таззалаорі мешкає Воєнний Майстер Вун, і за допомогою жаровні викликати спотворений дух мого колишнього соратника, Мора Грейхуфа. Він не знайде спокою, доки у нього не заберуть уламок амулета.$B$BО, до речі, у мене залишилося трохи кривавої водорості з твоєї подорожі на острів Альказ, тож я приготував для тебе кілька зілля. Вибирай на свій смак!",
},

[8987] = {
    en = "More Components of Importance",
    T = "Інші важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам все ще потрібен ще один компонент, яким слід наповнити жаровню; щось, що забезпечить достатньо сильний фокус, щоб викликати останки моїх покійних колишніх товаришів.$B$BБрат і сестра, Джарієн і Сотос, були прихильниками вчення «Скарлатного хрестового походу». Вони прагнули отримати лицарське звання в цій огидній організації. Відправляйся до «Руки Тира» у Східних Землях Чуми та забери там у преторіанців «Блискучий меч фанатизму».$B",
    O = "Знайдіть «Блискучий меч фанатизму» і поверніть його Бодлі, який перебуває всередині Гори Чорної Скелі.",
    P = "То ти вже повернувся, $C, з тим, за чим я тебе відправив?",
    C = "Відмінно виконано, $N. Я вкладу суть меча в жаровню.$B$BТепер залишилося лише проникнути до «Багряного трону» всередині «Скарлатового бастіону» у Стратхолмі та за допомогою жаровні викликати останки моїх колишніх соратників — Джарієна та Сотоса. Їхні душі ще більше спотворилися через те, що вони володіють уламком амулета Валталака та його духом, що мешкає в ньому.$B$BО, до речі, у мене залишилося трохи кривавої водорості з твоєї подорожі на острів Альказ, тож я зробив з неї кілька зілля для тебе. Обирай на свій смак!",
},

[8988] = {
    en = "More Components of Importance",
    T = "Інші важливі компоненти",
    D = "$C, слухай уважно. Тепер, коли ми знаємо, де знаходиться остання частина амулета, нам все ще потрібен ще один компонент, яким слід наповнити жаровню; щось, що стане достатньо сильним фокусом, аби привабити дух мого покійного, колишнього товариша.$B$BНекромант-огр на ім’я Кормок, який подорожував разом із нами, із задоволенням викликав душі вигнаних мертвих з Острова Очищення, що розташований біля південного узбережжя Підніжжя Хіллсбрада. Відправляйся туди й візьми трохи «Попелу душ вигнаних» з їхніх останків.",
    O = "Знайдіть «Попіл душ вигнанців» і поверніть його Бодлі в горі Блекрок.",
    P = "То ти вже повернувся, $C, з тим, за чим я тебе відправив?",
    C = "Відмінно спрацювали, $N. Я влию сутність попелу в жаровню.$B$BТепер залишилося лише проникнути до Шоломанса, до покоїв Раса Фроствіспера, і за допомогою жаровні викликати дух мого колишнього соратника, Кормока. Уламок амулета та дух Валталака, що мешкає в ньому, ще більше спотворили його, і він не знайде спокою, доки ти силою не відбереш це у нього.$B$BО, до речі, у мене залишилося трохи кривавої водорості з твоєї подорожі на острів Альказ, тож я зробив з неї кілька зілля для тебе. Обирай на свій смак!",
},

[8989] = {
    en = "The Right Piece of Lord Valthalak's Amulet",
    T = "Права частина амулета лорда Валталака",
    D = "Мій друг, Мор Грейхуф, став першою жертвою одержимості фрагментом амулета лорда Валталака та спотворюючого духу, що містився в ньому. Викравши книгу заклинань і амулет Валталака, ми втекли, рятуючи життя, з верхньої частини Шпиля Чорної Скелі. По дорозі Мор впав у нижню частину вежі.$B$BПізніше ми дізналися, що він вижив після падіння, але його схопив і катував воєнний майстер Вун. Кілька примарних вбивць проникли всередину й убили його прямо на очах у Вуна.",
    O = "Використайте «Жаровню заклику», щоб викликати дух Мора Грейхуфа та вбити його. Поверніться до Бодлі в горі Чорна Скеля, маючи при собі відновлений «Амулет лорда Валталака» та «Жаровню заклику».",
    P = "Тож все завершено? Ти знайшов потрібну частину амулета лорда Валталака, зібрав амулет у єдине ціле і, нарешті, дав спокій душі мого старого товариша, Мора Грейхуфа?",
    C = "Дякуємо за допомогу Мору Грейхуфу, $N. Ще один дух знайшов спокій, і тепер ми маємо відновлений амулет! Але попереду нас ще чекає найважче випробування.$B$BЩоб жаровня була готова до виклику лорда Валталака, потрібно зібрати ще кілька предметів і принести їх мені сюди.",
},

[8990] = {
    en = "The Right Piece of Lord Valthalak's Amulet",
    T = "Права частина амулета лорда Валталака",
    D = "Пізніше, коли ми самі робили все можливе, щоб вижити, нам стало відомо, що Ісаліен, жриця нічних ельфів із нашої групи, вирушила до прабатьківського міста нічних ельфів, яке зараз відоме як «Дайр Маул». З того, що нам вдалося дізнатися, вона вирушила туди як з особистих причин, так і для того, щоб розгадати таємниці частини амулета, що була в її володінні.$B$BОднак їй не вдалося дістатися до місця призначення. До нас дійшла звістка, що біля Святилища Елдретарра на неї влаштував засідку Альзін Дикий Творець разом зі своїми військами.",
    O = "Використайте «Жаровню заклику», щоб викликати дух Ісаліен і знищити її. Поверніться до Бодлі в горі Блекрок із відновленим «Амулетом лорда Валталака» та «Жаровнею заклику».",
    P = "Напевно, ти ще не впорався із порятунком душі Ісаліена та пошуком потрібної частини амулета лорда Валталака, $N? Не забудь з'єднати частини амулета, перш ніж передати його мені.",
    C = "Дякую, $N, за те, що ти дав спокій душі Ісаліен. Тепер, можливо, вона знайде спокій поруч зі своєю богинею. А ще у нас є відновлений амулет! Але попереду нас ще чекає найважче випробування.$B$BЩоб жаровня була готова до виклику лорда Валталака, потрібно зібрати ще кілька предметів і принести їх мені сюди.",
},

[8991] = {
    en = "The Right Piece of Lord Valthalak's Amulet",
    T = "Права частина амулета лорда Валталака",
    D = "Брат і сестра, Джарієн та Сотос, вирішили приєднатися до «Скарлетного хрестового походу» після розформування нашої найманої роти. Вони забрали з собою праву частину амулета лорда Валталака. Я скажу: «І добре, що вони пішли», але нам потрібно повернути цю частину.$B$BЗ того, що нам вдалося з’ясувати, їх насправді вбив сам Великий хрестоносець Датрохан за те, що вони не пройшли обряди ініціації у його покоях у «Скарлет-Бастіоні».$B$BУ будь-якому разі, нам... тобто тобі, все одно доведеться повернути цю частину амулета.",
    O = "Використайте «Жаровню заклику», щоб викликати Джаріена та Сотоса і вбити їх. Поверніться до Бодлі в горі Чорна Скеля, маючи при собі відновлений «Амулет лорда Валталака» та «Жаровню заклику».",
    P = "Тож чи означає це, $C, що ти вже дав спокій душам тих двох дурнів і знову зібрав уламки амулета лорда Валталака?",
    C = "Мабуть, це на краще, що душі тих двох нарешті знайшли спокій, хоч я й не любив їх, коли вони були живі. У будь-якому разі, ми отримали те, що шукали, і тепер амулет знову зібрано! Але попереду нас ще чекає найважче випробування.$B$BЩоб жаровня була налаштована на виклик лорда Валталака, потрібно зібрати ще кілька предметів і принести їх мені сюди.",
},

[8992] = {
    en = "The Right Piece of Lord Valthalak's Amulet",
    T = "Права частина амулета лорда Валталака",
    D = "Тепер у нас є все необхідне, тож настав час обговорити, кого саме ти будеш викликати наступним.$B$BКормок був цілком прийнятним для огра, доки не захопився некромантією. Після цього ситуація стала моторошною практично для всіх членів загону. Тож не дивно, що він взяв свою частину амулета й повернувся до свого нового дому — Шоломансу.$B$BАле навіть там, а може, особливо там, він не був у безпеці від примарних вбивць. Вони вбили його прямо на очах у його господаря, Раса Фроствіспера.",
    O = "Використайте «Жаровню, що кличе», щоб викликати духа Кормока та вбити його. Поверніться до Бодлі в Чорноскальній горі, взявши з собою відновлений «Амулет лорда Валталака» та «Жаровню, що кличе».",
    P = "Я висловлюю тобі, $N, свою вдячність, якщо ти повернувся з готовим амулетом. Якщо ж ні, то, будь ласка, подбай про це, адже, запевняю тебе, часу гаяти немає!",
    C = "Гарна робота, $N! Кормок був не таким вже й поганим, як на огра, принаймні поки був живий, тож сподіваюся, він знайде спокій, на який заслуговує. А тепер у нас є готовий амулет! Але попереду нас ще чекає найважче випробування.$B$BЩоб жаровня була налаштована на виклик лорда Валталака, потрібно зібрати ще кілька предметів і принести їх мені сюди.",
},

[8993] = {
    en = "Gift Giving",
    T = "Подарунки",
    D = "",
    O = "",
    P = "Ви прийшли, щоб подарувати своєму улюбленому лідеру знак любові та шани?",
    C = "Чудово! Чудово! Я додам це до купи інших подарунків.$B$BЯ й не сподівався, що їх буде так багато! Ви, мабуть, справді любите своїх керівників.$B$BА тепер дозвольте мені додати ще один до загальної кількості...",
},

[8994] = {
    en = "Final Preparations",
    T = "Останні приготування",
    D = "Ми вже майже досягли мети, $c. Залишилося лише дістати ще кілька компонентів, щоб я міг налаштувати жаровню та дозволити їй прикликати лорда Валталака.$B$BДля початку я мушу попросити тебе вирушити до Шпиля Чорної Скелі й знищити орків, що там мешкають. Вони носять нарукавники, які містять мікроелементи, що мені знадобляться, тож мені знадобиться чимало таких, щоб вилучити з них потрібну кількість. Потім, щоб завершити процес наділення магією, вам потрібно буде принести мені Флакон найвищої сили.$B$BУдачі, $N!",
    O = "Зберіть 40 браслетів «Чорної скелі» та отримайте флягу «Вищої сили». Поверніть їх Бодлі, який знаходиться в горі Чорної скелі.",
    P = "Ми пройшли довгий шлях, $N, і я просто хотів сказати: що б не сталося, дякую тобі! Ти ризикував власним життям, намагаючись допомогти тим, хто вижив із нашої найманої роти «Завуальоване лезо», і, на мою думку, тепер ти — один із нас.",
    C = "Ось і все. Я витягну метал із нарукавників і наділю жаровню цими останніми компонентами. Тоді він буде готовий, щоб ти міг викликати лорда Валталака і нарешті повернути йому його амулет духу.$B$BТи пройшов чималий шлях, $N, не здавайся зараз, коли кінець уже на горизонті!",
},

[8995] = {
    en = "Mea Culpa, Lord Valthalak",
    T = "«Mea Culpa», лорд Валталак",
    D = "Тепер усе готово, $N.$B$BЗа життя лорд Валталак мешкав у приміщенні, яке зараз є покоями Звіра. Відправляйся туди та скористайся «Жаровнею заклику», щоб викликати лорда Валталака. Це відновить його тіло, тож його доведеться вбити ще раз. Я б спершу розправився зі Звіром і обов’язково взяв із собою достатньо друзів, щоб вижити у верхній частині Шпиля Чорної Скелі.$B$BЯк тільки ти розправишся з Валталаком, використай амулет на його трупі. Тепер, коли його душа знову об’єдналася з тілом, він, ймовірно, також захоче повернути свій амулет.$B$BУдачі!",
    O = "Використайте «Жаровню заклику», щоб викликати лорда Валталака. Знищіть його, а потім застосуйте «Амулет лорда Валталака» до його трупа. Після цього поверніть «Амулет лорда Валталака» Духу лорда Валталака.",
    P = "$C, ти насмілюєшся порушувати мій спокій!",
    C = "Тобі пощастило, що я знаю: ти не належиш до тієї групи, яка спочатку вкрала це у мене.$B$BТепер я заберу те, що належить мені, смертний! Віддай мені амулет!",
},

[8996] = {
    en = "Return to Bodley",
    T = "Повернутися до Бодлі",
    D = "Цього разу я проігнорую твою зухвалість, $c, адже сьогодні ти вчинив благородно — повернув мені решту мого вкраденого духу. Незважаючи на твою очевидну слабкість, $r, ти проявив мужність, якої не вистачило тим, хто мене пограбував, і якої, мабуть, у них ніколи не буде!$B$BПовертайся до них, поки я не передумав і не вбив тебе тут же, на місці. Повертайся й скажи їм, що вони в безпеці… поки що.",
    O = "Поверніться до Бодлі, що знаходиться всередині Гори Блекрок, і передайте йому «Жаровню, що кличе».",
    P = "$N, ти повернувся і досі живий! Ну, принаймні хтось із нас живий.$B$BТи обов’язково повинен мені все розповісти!",
    C = "Він справді все це сказав? Ого, не можу повірити, що він збирається відкликати примарних вбивць і переслідувачів, навіть якщо він і натякнув на те, що в майбутньому може завдати моїм живим супутникам ще більшої шкоди.$B$BЦе чудовий день, $N! Ти досягнув того, що вдалося небагатьом, і хоча б частково звільнив нас від деяких наших минулих гріхів.$B$BДякую! На знак вдячності я хотів би подарувати тобі ось це. Ти зможеш використовувати його, щоб викликати духів у тих самих місцях, де вже з’являлися привиди, а також у кількох інших.",
},

[8997] = {
    en = "Back to the Beginning",
    T = "Назад до початку",
    D = "Мабуть, це на прощання, друже мій. Але я завжди буду тут, якщо ти захочеш повернутися й поговорити зі мною час від часу. Мабуть, поки ти будеш тинятися, чекаючи, поки твої друзі приєднаються до тебе для рейду на Чорнокам’яну Вежу.$B$BІди, поки я не почав плакати. Повертайся до Деліани в Айронфорзі й розкажи їй, що сталося.",
    O = "Поговоріть з Деліаною в «Високому троні» в Айронфорзі.",
    P = "",
    C = "Я дуже радий, що ти благополучно повернувся до мене, $N. Ти виглядаєш добре, хоча й трохи стомленим.$B$BНу ж бо, розкажи мені про все, що сталося.",
},

