[9247] = {
    en = "The Keeper's Call",
    T = "«Поклик Хранителя»",
    D = "$N,$B$BУ минулому ви служили інтересам «Сріблястого Світанку», завжди докладаючи максимум зусиль. Тепер, у час найбільшої скрути, ми знову звучимо заклик до зброї.$B$B$N, будь ласка, зверніться до Хранителя списків у Каплиці Надії Світла у Східних Землях Чуми, якщо ви готові ще раз допомогти нам.",
    O = "Віднесіть листа від Хранителя сувоїв йому до каплиці «Надія Світла» у Східних Землях Чуми.",
    P = "",
    C = "",
},

[9248] = {
