},

[9364] = {
    en = "Fragmented Magic",
    T = "Роздроблена магія",
    D = "Мої дослідження виявили унікальне призначення призматичної мушлі.$B$BВізьміть мушлю з собою та застосуйте заклинання «Поліморфія» до Спітелашів в Азшарі. Якщо ви зачекаєте кілька миттєвостей, хаотична аура мушлі змусить їх на кілька миттєвостей розділитися на кілька менших клонів. Вбийте цих клонів якомога швидше, і оболонка збере їхню сутність.$B$BКоли оболонка наповниться, поверніть її мені.",
    O = "Застосуйте заклинання «Поліморф» до Спітелаша з Азшари та знищіть клони, які з’являться через кілька секунд. Після того як ви знищите 50 клонів, отриманих заклинанням «Поліморф», поверніться до архімага Ксилема в Азшарі.",
    P = "Ви вже зібрали магію?",
