[9367] = {
    en = "The Festival of Fire",
    T = "Фестиваль вогню",
    D = "Знову настало літо!$B$BЩороку, згідно з традицією, обирають «Хранителів вогню», які доглядають за багаттями в наших столицях. Поки по всьому Азероту палають багаття, надзвичайно важливо, щоб наше було найгарячішим і найяскравішим, аби належним чином вшанувати цю пору року.$B$BНасправді, у мене є для тебе завдання, якщо ти не проти. Я ще не чув, чи правильно горять багаття у всіх столицях. Поїдь туди сам і погрійся біля вогню — переконайся, що вони гарячі!",
    O = "Доторкніться до багаття у Штормграді, Айронфорзі та Дарнассусі, а потім поговоріть із майстром знань фестивалю в столицях.",
    P = "Тобі пощастило, $N?",
    C = "Чудово! Схоже, цього року ми призначили сумлінних «Хранителів вогню», якщо багаття дійсно так добре доглянуті, як ви стверджуєте. Дякую, що перевірили їх за мене; ось, візьміть це як невеликий знак моєї поваги.",
},

[9368] = {
    en = "The Festival of Fire",
    T = "Фестиваль вогню",
    D = "Знову настає Літо!$B$BЩороку, згідно з традицією, обирають «Хранителів вогню», які доглядають за багаттями в наших столицях. Поки по всьому Азероту палають вогнища, надзвичайно важливо, щоб саме наше було найгарячішим і найяскравішим, аби гідно вшанувати цю пору року.$B$BНасправді, у мене є доручення для тебе, якщо ти не проти. Я ще не чув, чи правильно горять багаття у всіх столицях. Поїдь туди сам і погрійся біля вогню — переконайся, що вони гарячі!",
    O = "Доторкніться до багаття в Оргримарі, Грім-Блаффі та Андерсіті, а потім поговоріть із оповідачем фестивальних історій у столицях.",
    P = "Тобі пощастило, $N?",
    C = "Чудово! Схоже, цього року ми призначили сумлінних «Хранителів вогню», якщо багаття справді такі доглянуті, як ти кажеш. Дякую, що перевірив їх за мене; ось, візьми це як невеликий знак моєї поваги.",
},

[9378] = {
    en = "DND FLAG The Dread Citadel - Naxxramas",
    T = "Прапор DND «Страшна цитадель — Наксрамас»",
    D = "У самому серці Чумового лісу знаходиться вхід до жахливої цитаделі Наксрамас. Раніше всі спроби проникнути туди були зірвані магічними захисними заклинаннями, накладеними на рунічний портал. Принаймні, так було дотепер.$B$BМи придумали спосіб проникнути всередину за допомогою своєрідного постійного магічного маскування — стародавнього заклинання Кірін-Тор, до якого я вніс кілька власних модифікацій. Слід зазначити, що таке маскування коштує дорого, однак ваша відданість справі Світанку непохитна! Ми скасуємо всі пов’язані з цим витрати.",
    O = "Архімаг Анжела Досантос у Каплиці Надії Світла на Східних Землях Чуми безкоштовно надасть вам «Таємниче маскування». Ви повинні мати репутацію «Високошанований» у ордені «Срібного Світанку».",
    P = "",
    C = "",
},

[9386] = {
    en = "A Light in Dark Places",
    T = "Світло в темних місцях",
    D = "Ти ж дуже завзятий, чи не так? Якщо ти готовий знову заглибитися в підземелля, я з радістю винагороджу тебе.$B$BЗнайди вогнища, що палають у Стратхолмі, Сколомансі, Дайр-Маулі та в самих залах Чорнокам'яної Вежі; я з нетерпінням чекаю на твоє повернення, $N.",
    O = "Знайдіть і торкніться багаття, розташованих у «Шпилі Чорної Скелі», «Страшному Маулі», «Сколомансі» та «Стратхолмі», а потім поговоріть із «Хранителем вогню фестивалю».",
    P = "",
    C = "",
},

[9388] = {
    en = "Flickering Flames in Kalimdor",
    T = "Мерехтливі полум’я в Калімдорі",
    D = "Сьогодні по всьому світу палає безліч вогнів, $n. Найскладнішими у догляді є ті, що горять зеленим вогнем; без нагляду вони не залишаються запаленими надовго. Переконайтеся, що смарагдові вогні на Калімдорі все ще палають для нашого Хранителя Вогню, га?$B$BВи знайдете їх поблизу Ратчета в Пустошах, недалеко від «Глейва Майстра» на Темному Березі, у лісі Ешенвейл біля мосту поблизу застави «Срібне Крило», а також біля дороги до скелі Віндшир уздовж головної дороги в Горах Кам’яного Копита.",
    O = "Відвідайте багаття в Ешенвейлі, Пустках, Темному березі та Горах Кам’яного Копита, а потім поговоріть із Хранителем вогню фестивалю.",
    P = "Багаття не згаснуть, доки фестиваль не закінчиться!",
    C = "Ааа, так вони все-таки ще горять. Я радий; було б погано, якби ці вогні згасли раніше часу. Ти добре впорався, $N. Прийми це з моїм благословенням.",
},

[9389] = {
    en = "Flickering Flames in the Eastern Kingdoms",
    T = "Мерехтливі полум’я у Східних Королівствах",
    D = "Фестиваль літнього вогню традиційно осяює землю безліччю полум’я. Дехто вважає, що зелені вогні — найкращі, оскільки їх найважче підтримувати, а їхній відтінок є таким особливим.$B$BПереконайтеся, що вони досі палають у Східних Королівствах для нашого Хранителя Вогню. Вони розташовані поблизу Дун-Модра у Водно-болотних землях, недалеко від селища Пайрвуд у Сріблясто-сосновому лісі, на скелях, що височіють над маяком у Вестфолі, та біля зруйнованої вежі на передгір’ях Гіллсбрада.",
    O = "Відвідайте багаття в передгір’ях Хіллсбрада, Лісі Сільверпайн, Вестфолі та на Болотах, а потім поговоріть із Хранителем вогню фестивалю.",
    P = "Ви вже виконали своє завдання?",
    C = "Отже, ти повернувся і побачив смарагдові полум’я континенту. Що скажеш, мм? Безперечно, рідкісне й чудове видовище. Однак я розумію, що матеріальні нагороди цінуються більше… тож, будь ласка, візьми це за твої клопоти.",
},

[9415] = {
    en = "Report to Marshal Bluewall",
    T = "Звіт маршалу Блюволу",
    D = "Ви — нові рекрути маршала Блюволла? Звісно, що так.$B$BЧого ж ви чекаєте? У пустелі гинуть хороші солдати. Хіба вам не хочеться приєднатися до них?$B$BА тепер рушайте і не засихайте по дорозі.",
    O = "Поговоріть з маршалом Блюволом у таборі Альянсу поблизу Хайв'Зори.",
    P = "",
    C = "Альянсу потрібні всі боєздатні бійці, яких тільки можна залучити. Орда постійно отримує підкріплення з північної частини континенту, і нам доводиться нелегко, щоб не відставати від неї.$B$BДозвольте мені пояснити вам ситуацію.",
},

[9416] = {
    en = "Report to General Kirika",
    T = "Звіт генералу Кіріці",
    D = "Мабуть, ти — один із нових рекрутів генерала Кіріки. Давно вже час було з’явитися. У пустелі тіло швидко виснажується.$B$BКарлики щодня отримують підкріплення, і ми не можемо дозволити собі втрачати позиції в боротьбі за ресурси в Сілітусі.$B$BОтримайте інструкції від генерала. Моє завдання — не навчати вас, а лише знайти.",
    O = "Поговоріть із генералом Кірікою у таборі Орди поблизу Хайв’Регала.",
    P = "",
    C = "Добре, що ти тут, але немає часу на зайві балачки. Тобі потрібні вказівки, а потім тобі треба вирушати туди.$B$BСлухай уважно.",
},

[9419] = {
    en = "Scouring the Desert",
    T = "Пошуки в пустелі",
    D = "Нещодавно ми дізналися, що Орда розшукує ресурси в пустелі Сілітус, але не приділяли цьому особливої уваги. Ми вважали, що розміщувати великі війська в цій спекотній пустелі не має сенсу.$B$BОднак згодом ми усвідомили важливість цих ресурсів, і тепер поспішаємо надолужити згаяне.$B$BЯкщо ви готові допомогти, вам слід вирушити в пустелю, добути силітист і принести його сюди.",
    O = "Знайдіть силітист і доставте його до силітистового екстрактора, а потім поговоріть з маршалом Блюволом у таборі Альянсу поблизу Хайв’Зори.",
    P = "Будьте обережні, але й дійте швидко. У нас немає часу на зволікання.",
    C = "Слава Світлу, що вам це вдалося.$B$BЯкби ж ми тільки почали це раніше, наша ситуація не була б такою відчайдушною. Ми мусимо не допустити, щоб багатства пустелі потрапили до рук Орди.",
},

[9422] = {
    en = "Scouring the Desert",
    T = "Пошуки в пустелі",
    D = "Вже деякий час ми видобуваємо кристали в пустелі Сілітус. Єдиною небезпекою для нас були істоти, які оселилися в цьому місці, а також пригнічуючі пісок, пил і спека.$B$BАле тепер, схоже, Альянс дізнався про те, що ми тут знайшли. Тепер між нами розгорілася гонка за природні ресурси, і ми маємо не дати їх іншим.$B$BМені потрібна кожна пара рук, яка тільки є. Сподіваюся, я можу розраховувати на вашу допомогу.",
    O = "Знайдіть силітист, доставте його до установки з видобутку силітисту, а потім поговоріть із генералом Кірікою в таборі Орди поблизу Хайв’Регала.",
    P = "Будьте обережні — пустеля таїть у собі небезпеку, $n. Поки Альянс чатує серед дюн, кожен крок може стати для вас останнім.",
    C = "Ти добре попрацював, $N. Ці ресурси будуть додані до наших запасів, і кожна дрібниця — це наша вигода та втрата для ворога.",
},

[9664] = {
    en = "Establishing New Outposts",
    T = "Створення нових передових пунктів",
    D = "Ласкаво просимо до Земель Чуми, $n. Як вам відомо, Покинуті та їхні союзники утримують землі на захід від нас, незважаючи на всі наші зусилля. Командири Альянсу вирішили, що тут, на сході, ми зведемо нові укріплення, щоб ще більше затягнути зашморг навколо наших ворогів.$B$BЗ цією метою слід захопити та відбудувати вежі, які були покинуті ще за часів Лордаерона. Ці землі небезпечні, і нам знадобиться ваша допомога.",
    O = "Захопіть вежу «Корона-гвардія», вежу «Східна стіна», вежу «Північний прохід» та вежу «Чорнобильний ліс» у Східних Чорнобильних землях, а потім поверніться до посланця Вайтбірда в каплиці «Надія Світла».",
    P = "Коли вежі опиняться під нашим контролем, ми незабаром зможемо оточити «Покинутих». Після цього їх розгром стане лише питанням часу.",
    C = "Дуже добре, $N. Нам буде важливо утримати ці вежі від майбутніх атак, і для цього нам може знадобитися ваша допомога, доки не прибуде підкріплення для забезпечення безпеки цієї території.",
},

[9665] = {
    en = "Bolstering Our Defenses",
    T = "Зміцнення нашої оборони",
    D = "Агенти «Покинутих» викрили змову Альянсу, спрямовану на створення нових баз тут, у Східних Землях Чуми, у покинутих вежах по всій цій місцевості.$B$BМи не можемо дозволити їм закріпитися на наших східних кордонах, тому мусимо відбити це вторгнення Альянсу. Наші поточні плани полягають у тому, щоб вигнати їх із усіх веж, які вони, можливо, вже захопили, та утримати ті, що перебувають під нашим контролем, від подальших атак.",
    O = "Захопіть вежі «Корона-Гвардія», «Іствелл», «Нортпасс» та «Чумовий ліс» у Східних Чумових землях, а потім поверніться до посланця Гормока в каплиці «Надія Світла».",
    P = "Вони, мабуть, дурні, якщо думають, що ми дозволимо їм створити бази так близько до однієї з наших столиць.$B$BМи будемо знищувати їхні сили, поки вони не кинуть бій і не відступлять на південь.",
    C = "Це гарна новина, $N. У Землях Чуми нас чекає безперервна боротьба, доки ми повністю не відкинемо війська Альянсу.$B$BДо того дня я сподіваюся, що ми й надалі зможемо розраховувати на вашу допомогу.",
},

[20000] = {
    en = "[DEPRECATED] Orb of Pure Light",
    T = "[ЗАСТАРІЛО] Сфера чистого світла",
    D = "Сфера сяє так само яскраво, як Сонце, всередині грізних стін Наксрамаса.$B$BПісля перемоги над Вершниками, коли наступне випробування вже не за горами, ви вирішуєте взяти сферу з собою і, якщо виживете, повернути її до Каплиці Надії Світла.",
    O = "Віднесіть Сферу Чистого Світла Максвеллу Тиросу в Каплицю Надії Світла у Східних Землях Чуми.",
    P = "",
    C = "То ти знайшов це одразу після своєї перемоги?",
},

[20001] = {
    en = "[DEPRECATED] Seek Help Elsewhere",
    T = "[ЗАСТАРІЛО] Зверніться за допомогою в інше місце",
    D = "Я ще ніколи не бачив нічого подібного, $N.$B$BСхоже, ніби сама суть Світла випромінюється з цієї кулі — дивного предмета, який залишив після себе Попелоносець, коли звільнився з лап Плеті.$BЯ справді не можу витратити час, щоб допомогти тобі з цим. Навіть якщо Цитадель Жаху впала, нам ще далеко до перемоги. Хоча Архіліч і був переможений, ми ще не знайшли його філактерію.$B$B«Срібний Світанок» — це суцільний хаос, втрат було багато, а ті з нас, хто залишився, вкрай виснажені. Хоча тут ти не знайдеш допомоги, я знаю, куди тебе направити, і впевнений, що він зможе тобі допомогти.$BЗвернися до Тіріона Фордрінга, тут, у Східних Землях Чуми, на захід від нас.$B$BМені справді шкода, і я бажаю тобі удачі.",
    O = "Знайдіть Тіріона Фордрінга у Східних Землях Чуми.",
    P = "",
    C = "Максвелл — розумна людина, і його вибір був справедливим.",
},

[20002] = {
    en = "[DEPRECATED] To Wake the Ashbringer",
    T = "[ЗАСТАРІЛО] Як пробудити «Порохоносія»",
    D = "<Тіріон деякий час мовчки розглядає кулю.>$B$BНа Світло!$BЦя чиста сутність, ця первинна енергія Світла — це, безсумнівно, сам Александрос!$BЙого душа, що перебувала у стані спокою, перетворилася на цю кулю, але з якою метою?$BЯ не можу цього осягнути, але, можливо, ми можемо спробувати його розбудити. Не впевнений, що це правильний вибір слів у цьому випадку. Але як ми взагалі можемо це зробити?$BЩось знайоме може допомогти.$B$BСлухай $N. Сайдан Датрохан був одним із найперших паладинів, моїм другом і другом Александроса, але в якийсь момент він збожеволів. Що в ті часи, як з’ясувалося, було спричинено певним демонічним впливом.$BКоли Рено вбив його батька, Сайдан забрав табард «Попелоносія» як трофей.$BВодночас, якщо моя інформація правильна, барон Рівендар гордо носив плащ Александроса, щоб з нього посміятися.$B$BТвоє завдання — вирушити до Стратхолма й знайти ці предмети, що колись належали Попелоносецю. Візьми кулю з собою, я впевнений, що вона викличе якусь реакцію. А я тим часом спробую розібратися в цій ситуації.",
    O = "Знайдіть у Стратхолмі «Табард Поносяча Попелу» та «Плащ Александроса».",
    P = "",
    C = "Тобі вдалося їх віднайти — хоч і пошарпані, але все ж.",
},

[20003] = {
    en = "[DEPRECATED] Spirit of the Ashbringer",
    T = "[ЗАСТАРІЛО] Дух «Поносяча попелу»",
    D = "Я відчуваю це $N.$BДух Александроса та його прагнення справедливості. Ці землі надто зіпсовані, щоб ми могли зв’язатися з ним; якщо ми хочемо коли-небудь дістатися до нього, нам потрібно місце, наповнене Світлом.$BПід керівництвом Світла я відчуваю, що нам слід вирушити до гробниці Утера.$BЗавершіть усі справи, що у вас залишилися, і зустріньтеся зі мною там. Моє єдине бажання — щоб цей фрагмент його духу був готовий спілкуватися та співпрацювати з нами.$BЧас покаже.$BДо гробниці Утера!",
    O = "Зустріньтеся з Тіріоном Фордрінгом біля гробниці Утера у Західних Землях Чуми.",
    P = "",
    C = "Ось і він $N. Він ось-ось з’явиться. $BСтій рівно — його аура може трохи пригнічувати.",
},

[20004] = {
    en = "An Act of Humility",
    T = "Акт смирення",
    D = "<Александрос пильно дивиться тобі в очі.>$B$BОтже, той, хто звільнить мене від вічного нежиття, — це й той, хто отримає моє послання. Світло вказало мені цей шлях.$BСлухай уважно, $N. Я — Александрос Могрейн, Порохоносець. Колись я був членом того, що тепер називається огидним Скарлетним Хрестовим походом.$B$BПаладин, чоловік, батько, а тепер — лише привид. Мій дух не знає спокою, і я не можу й не збираюся відійти, доки не буде відновлено справедливість. Так, ти правильно почув: це не справедливість Світла, а справедливість Порохоносія.$BЯ готовий поділитися з тобою інформацією, яка дозволить тобі стати частиною чогось величного.$B$BІнформація, яка раз і назавжди призведе до краху «Скарлетного хрестового походу». І так, як не дивно, вам ще належить покласти їм край.$BЯ прошу смиренності від того, хто переміг мене в бою, від того, хто звільнив мою душу. Схиліться перед Попелоносцем, дайте мені відчути, що моя легенда серед смертних нашого світу ще не згасла.",
    O = "Вклоніться Поношучу Попелу.",
    P = "",
    C = "Це просте завдання, яке покаже, якого кольору ваша душа.",
},

[20005] = {
    en = "The Foul Stench of the Scarlet Crusade",
    T = "Огидний сморід «Скарлетного хрестового походу»",
    D = "Покинувши свою смертну оболонку, Світло відкрило мені багато різних речей.$BМоє життя, мою місію, моє майбутнє.$BТепер я прагну лише одного — покласти край «Скарлетському хрестовому походу».$BБріджет Аббендіс відступила до Скарлетського монастиря. Вона наказала набрати більше людей і винайшла нове зілля, яке миттєво поклало б кінець нежиті.$B$BСхоже, її плани виявилися марними з того дня, як вона вирішила сховатися у своїх покоях для медитації. Світло, як бачите, має свої власні шляхи, загадкові для нас. Вона мала намір накопичити більше сили заради мети, яка є нічим іншим, як дурістю. На схід від «Руки Тира» «Скарлетний хрестовий похід» готується до походу на північ, чекаючи на повернення свого лідера, щоб розпочати дію.$B$BАле всупереч усім очікуванням темна сила проникла до Монастиря під час її медитації й назавжди затьмарила і без того фанатичні уми.$BВони більше не бачать різниці між живими та неживими. Їхнє використання магії тіней походить від іншої сили, яка може зрівнятися із самим Світлом.$BНастав час вирішити, чи готові ви довести свою відвагу.$B$BНаксрамас справді був загрозою, але сили, що діють тут, цілком можуть перевершити його. Чи готові ви $N?",
    O = "Зверніться до Духа Александроса Могрейна.",
    P = "",
    C = "Дуже добре. Ти, здається, готовий.$BОдин порада, перш ніж ти підеш, <ім’я>. Таких, як ти, таких, як я, завжди забуватимуть. Запам’ятай це назавжди: люди цього світу ніколи не згадають твоє ім’я, ніколи не згадають твоє обличчя, але завжди пам’ятатимуть твої вчинки.$B",
},

[39000] = {
    en = "Goblin Brainwashing Device",
    T = "Пристрій для промивання мізків гоблінів",
    D = "Підходьте, друзі, і погляньте на чарівну — е-е-е... машину для створення туману Візлова!$B$B<Візлов оглядає вас з голови до ніг.>$B$BАга, потенційний покупець! Ти, мабуть, приїхав з іншого кінця світу, щоб побачити дива, на які здатні мої машини.$B$BНі? Ну що ж, не має значення. Тоді це, мабуть, доля! Або те божество, у яке ти віриш, привело тебе до мене. Послухай, ця машина творить дива, хлопче. Вона може розширити твої фізичні та розумові здібності!$B$BІ все, що тобі потрібно зробити, — це вкинути в неї золото, щоб вона запрацювала! То що скажеш? Заплати десять золотих, щоб її активувати. Звісно, мені знадобиться 340 — е-е-е... на матеріали, так, саме на матеріали!",
    O = "Дайте Візлоу 350 золотих монет, щоб він міг придбати та активувати таємничу машину.",
    P = "Ти вже отримав золото?",
    C = "Ти справді хочеш її купити?!$B$BНу, звичайно, ти ж хочеш — це ж чудова нагода. О, і підпиши цей документ — там просто зазначено, що тепер ця машина належить тобі, і… е-е…$B$B<Візлоу щось бурмоче.>$B$BЩо ти усвідомлюєш ризики.",
},

[39001] = {
    en = "Curiosity Leads Us Forward",
    T = "Цікавість веде нас вперед",
    D = "Отой модний сенатор нікого не обдурить! Член Ліги Дослідників, звичайно ж! Ба! Що за порожні балачки!$B$BСкажу тобі так: ти ніколи не зможеш називати себе Дослідником, якщо не обстежиш кожен куточок і щілинку власноруч!$B$BЗвісно, він ніколи не забирався далі, ніж цей кар’єр. Але, бачу, мені не доведеться тебе вмовляти поблукати трохи й дізнатися все самому, еге ж?$B$BДобре. Я хотів би, щоб ти розповів мені, що ти дізнаєшся в тій печері з усіма цими трогами.$B$BВони ж мусили звідкись з’явитися, правда?",
    O = "Дослідіть печеру кар'єру Гол'болар.",
    P = "Якби ж у нас були маги, які б співпрацювали з нами в наших дослідженнях, замість того, щоб бавитися з усіма цими дрібничками, до яких вони, здається, прилипли, наче гобліни до золота!$B$BЕх… Розчарування нас нікуди не приведуть, правда? Тож… не забудьте відпочити, коли закінчите тут.",
    C = "Розкажи ж! Були якісь ознаки того, звідки вони взялися? Якісь артефакти?$B$BІнструменти, якими вони, можливо, користувалися? Що-небудь? Що… І це все?$B$BПросто печера?? Тоді, мабуть, даремно витратив час. Але давай я тобі дам трохи монет. Ти добре впорався зі справою, хай там як.$B$BОсь, небагато, але це гарний початок, хлопче.",
},

