},

[39989] = {
    en = "Excessive Regulations",
    T = "Надмірне регулювання",
    D = "Це обурливо! Мені байдуже, що вам обіцяв той п’яниця-єпископ чи якийсь жадібний лорд. Королівство Штормвінд не продається! З цими корумпованими черв’яками я розберуся пізніше.$B$BЯ не дозволю, щоб мешканці Штормвінда стали жертвами вашої пірамідальної схеми. Ідіть і скажіть своїм покровителям, що закон залишиться в силі. Їм більше не дозволять експлуатувати надії та відчай довірливих людей.$B$BА тепер забирайтеся з моїх очей.",
    O = "Повідомте про це лобіста компанії Shell Co.",
    P = "",
    C = "Що сказав верховний лорд?! Це економічна катастрофа. Схоже, нам доведеться переїхати кудись, де поважають права вільного підприємництва. Штормвінд — це не що інше, як кубло нещастя.$B$BДякую за допомогу, $n. Хоча я не можу компенсувати твої витрати золотом, я можу дати тобі щось набагато цінніше.",
},

[39991] = {
    en = "Securing the Roads",
    T = "Забезпечення безпеки на дорогах",
    D = "Я радий, що ти вирішив приєднатися до нас $n. Я чув про твою роботу в цій галузі, і мушу сказати, що я вражений. Ви — саме та високомотивована людина, яка нам потрібна в цій організації.$B$BЯкщо ми хочемо утримати цей замок у довгостроковій перспективі, ми мусимо забезпечити безпеку наших ліній постачання. Я хочу, щоб ти влаштував засідку на того козла Валоркалла та раз і назавжди поклав кінець його патрулям. Його супроводжують охоронці, тож будь обережним — можливо, навіть візьми з собою ще одного агента на підмогу, але виконай завдання! Не повертайся до мене, доки він не буде мертвий.",
    O = "Вбийте лейтенанта Валоркалла та двох кавалеристів Стромгарда, які патрулюють разом із ним.",
    P = "Що я казав про те, щоб повертатися до мене, поки це ще не закінчилося?",
    C = "Молодець, $n. Бачу, ти не лише вправний, а й хитрий.",
},

[39992] = {
    en = "Securing the Keep",
    T = "Захист фортеці",
    D = "Тепер, коли єдиний шлях до фортеці Стромгард і з неї перебуває під нашим контролем, настав час захопити «Санктум» — останній оплот старого королівства.$B$BМені вже набрид цей так званий принц. Ти можеш повірити, що він оголосив нагороду за мою голову? Ха! Я хочу, щоб ти показав йому, хто тут головний. Коли все, що залишилося від минулого, буде мертвим і похованим, ми станемо справжніми господарями Стромгарда.",
    O = "Вбий принца Галена Троллбейна і повернися до лорда Фальконкреста.",
    P = "Що я казав про те, щоб повертатися до мене, поки все ще не закінчилося?",
    C = "Ти за один день зробив більше, ніж ці ідіоти навколо мене за місяць. Я подбаю про те, щоб тобі належним чином відшкодували твої послуги.$B$BПроте не плутай мою щедрість із слабкістю. Якби ти спробував щось зробити проти мене, ти загинув би так само швидко, як той принц. Не хочу, щоб у тебе виникли якісь думки.",
},

