[40885] = {
    en = "Dreamtonic",
    T = "[*] Dreamtonic",
    D = "",
    O = "",
    P = "На жаль, я не можу надати вам рецепт «Дрімтоніку» для самостійного виготовлення. Його відкрила людина, якої вже немає серед нас, і я не маю дозволу розкривати такі таємниці стороннім.$B$BПроте я можу запропонувати вам «Дрімтонік», який створив я сам, в обмін на ваші зусилля тут, у Гіялі. Принесіть мені один «Маленький осколок сну» в обмін на один «Дрімтонік». Це має бути справедливий обмін.",
    C = "Ефекти цієї суміші дуже сильні, тому не перестарайтеся.",
},

[40886] = {
    en = "Smelting Dreamsteel",
    T = "[*] Виплавка «Металу мрій»",
    D = "Уміння виплавляти «Мрію-сталь» — це мистецтво саме по собі. Хоча створення візерунків із злитків «Мрії-сталі» є досить складним завданням, це не затьмарює самого процесу виплавки.$B$BЯкщо ти бажаєш навчитися виготовляти власні злитки «Мрійної сталі» і не покладатися на інших, збери для мене п’ятнадцять «Яскравих осколків мрій» на знак своєї відданості Світовому Дереву.",
    O = "Зберіть 15 яскравих осколків мрій для Тантоса Евербріза в Норданаарі, що в Гіялі.",
    P = "Ти вже приніс «Осколки мрії», мандрівнику?",
    C = "Отже, ось ця книга, яка має навчити вас усього, що вам потрібно знати. Уважно вивчіть її та застосовуйте методи, описані в тексті.",
},

[40888] = {
