[40999] = {
    en = "Lost and Found",
    T = "[*] Бюро знахідок",
    D = "Якщо ти бажаєш дізнатися більше, мені знадобляться деякі послуги, перш ніж я зможу поділитися тими знаннями, які зможу витягти з цього пергаменту. Коли я вперше прибув до Каразану деякий час тому, я носив гравірований браслет, виготовлений із найчистішого золота. Він був символом мого статусу, але зник, відколи я блукаю цими залами.$B$BЯ впевнений, що залишив свій браслет десь у цих нижніх залах. Знайдіть його для мене, і я буду вам дуже вдячний.",
    O = "Знайдіть золотий браслет з гравіюванням для герцога Ротлена в Каразані.",
    P = "Ви знайшли мій браслет? Це був подарунок від моєї дружини.",
    C = "Ах, яка чудова робота... Я вже й забув, наскільки вона була розкішною.",
},

[41000] = {
    en = "Rothlen Family Brooch",
    T = "[*] Брошка родини Ротленів",
    D = "Я вдячний вам за те, що ви допомогли мені повернути мій гравірований золотий браслет, але я прагну чогось, що мені дорожче. Давно я залишив свою родину, щоб дістатися сюди, але в підсумку назавжди опинився у пастці.$B$BМені потрібна пам’ятка про минуле — щось, на що я зможу дивитися з найніжнішими спогадами. З нею я, можливо, знайду хоч якийсь спокій.$B$BКолись я походив із земель Лордаерона, а саме з міста Стратхольм; мій родинний будинок розташований у торговому районі. Знайдіть будинок Ротленів і поверніть мені мою родинну брошку.",
    O = "Знайдіть брошку родини Ротлен у Стратхолмі для герцога Ротлена в Каразані.",
    P = "Чи вдалося знайти брошку родини Ротленів?",
    C = "Стратхолм зруйновано? Мій рідний дім згорів?$B$B<Герцог Ротлен з подивом видихає повітря.>$B$BТакі новини глибоко зворушують мою душу. Я мушу щиро подякувати вам за те, що ви це знайшли, адже це справді остання пам’ятка про мою родину.",
},

