[50230] = {
    en = "Night's Exploration",
    T = "[*] Нічна експедиція",
    D = "Підійди сюди, мандрівнику!$B$BБачу, ти здібна людина, тож, оскільки доля звела нас разом, я навчу тебе чомусь корисному.$B$BЦе може стати тобі в нагоді тут, у джунглях!$B$BЯкщо ти принесеш мені міцну мотузку з Джакіліни, трохи олії від гоблінів із Буті-Бей та товсту палицю, яку знайдеш поблизу табору, то я відкрию тобі секрет, як за лічені хвилини змайструвати справжній факел, який знадобиться тобі в подорожах — чи то для нічних розвідок, чи то для захисту від диких тварин.$B$BБачиш ті, що біля нашого табору? Вони ніколи не гаснуть!",
    O = "Принесіть мотузку з Джакіліни, олію з Буті-Бей та палицю, знайдену поблизу табору, до експедиції Несінгварі для С. Дж. Ерлгадіна.",
    P = "Ви вже зібрали всі матеріали?",
    C = "А! Ти приніс матеріали. Чудово!$B$BДивись уважно!",
},

[50305] = {
