[50312] = {
    en = "Gnomes Are Genuine Inventors",
    T = "[*] Гноми — справжні винахідники",
    D = "Я впевнений, що ви чудово знаєте: ми, гноми, — найкращі винахідники. Якщо ви прагнете вдосконалити свої навички та знання, рано чи пізно вам доведеться навчатися у нас. Звісно, жоден гном не настільки дурний, щоб відмовитися від такого цікавого та захоплюючого партнерства, хоча, на жаль, іноді це може обійтися дорого.$B$BКоротше кажучи: нам потрібен хтось, хто доповнить нашу природну винахідливість та розумову активність своєю фізичною силою та витривалістю!$B$BЯкщо тобі вдасться керувати цим дивовижним шедевром гномської інженерії — який будь-який інший тупий гоблін просто назвав би гоночним автомобілем — тобі буде надана можливість ще ширше представляти наше блискуче товариство винахідників у «Міраж-рейсах»!$B$BКруто, правда?$B$BОсь інструкції, які ми спеціально розробили для представників інших рас, щоб полегшити розуміння та сприйняття.$B$BТак, можливо, тобі варто поговорити з нашою чарівною Долорес, щоб зареєструватися на тестові перегони, $N.$B$BУдачі, розумна істото!",
    O = "Знайди Долорес і прокотися на гоночному автомобілі гномів, щоб перевірити, чи витримає він хоча б старт.",
    P = "Звичайно ж, запускає двигун! Важелі для перемішування!",
    C = "Який шолом? Інструкція? Та годі! Кому вони взагалі потрібні?!",
},

[50313] = {
    en = "Mirage Raceway: Gnome's Team",
    T = "[*] «Міраж Рейсвей»: Команда Гнома",
    D = "Вітаємо, розумна істото! Ми дуже задоволені результатами, яких ви досягли під час випробування нашого інженерно-механічного пристрою, що виявилося надзвичайно корисним для отримання таких необхідних нам даних для аналізу. Ми готові запропонувати вам можливість постійної часткової участі в роботі нашої дослідницької групи та домовилися про винагороду за ваші зусилля.$B$BКоли ти будеш готовий приступити до збору даних, не забудь дотримуватися наданих інструкцій та рекомендованих заходів безпеки.$B$BГарного дня!",
    O = "Знайдіть Дейзі та пробіжіть коло з найкращим часом.",
    P = "Ти зрозумів, так?",
    C = "Не міняйте педалі місцями!",
},

[50315] = {
    en = "Gadgetzan Times: BREAKING NEWS!",
    T = "[*] «Gadgetzan Times»: НАЙСВІЖІШІ НОВИНИ!",
    D = "Ну ж бо, ну ж бо, купуйте свій примірник останнього випуску «Gadgetzan Times»! Тут ви дізнаєтеся справді сенсаційні новини!$B$BЩо? О, новини просто… сенсаційні!$B$BДуже скоро на Мерехтливих рівнинах, що, як ви знаєте, розташовані в Тисячі Голках, дві найвідважніші та найрозумніші команди змагатимуться у захопливих перегонах, відомих у всьому всесвіті як «Перегони Міраж»!",
    O = "Не пропустіть перший номер «Gadgetzan Times»!",
    P = "Ми завжди раді всім клієнтам!$B$BЩиро дякуємо, щиро дякуємо, будьте в курсі подій!",
    C = "Як це — ніхто більше про нас не знає?!",
},

[50316] = {
    en = "Race Against Time!",
    T = "[*] Гонка проти часу!",
    D = "Ха-ха-ха! Ти бачив їхні обличчя?! Просто чудова робота, друже!$B$BНу-ну, не треба соромитися, ти справді добре впорався, і я впевнений, що в гонці проти часу ти зможеш виступити ще краще!$B$BЗавдання досить просте. Сідаєш за кермо, натискаєш на педаль газу і мчиш, щоб побити найкращий час кола!$B$BЯкщо ти не зіткнешся з жодною вівцею, не з’їдеш з траси і не зупинишся, то зможеш перемогти!$B$BПриз? Звісно, є кілька призів. Не хвилюйся.",
    O = "Завершіть гонку з найкращим часом і поверніться до Дейзі в «Мерехтливих рівнинах», щоб отримати свою нагороду.",
    P = "Молодець, друже! Обов’язково заглянь до нас, коли будеш готовий повторити!",
    C = "Завдання досить просте. Сідайте за кермо, натисніть на педаль газу — і мчіть, щоб побити найкращий час кола!",
},

[50318] = {
    en = "Bracing The Inevitable",
    T = "[*] Готуючись до неминучого",
    D = "Хоча це чудово, що ми всі збираємося навколо красиво прикрашеної ялинки, на всіх диких тварин чекають серйозні неприємності. Як ви знаєте, вся екосистема, в якій ми живемо, може легко зазнати руйнування, якщо зникнуть деякі види, які виконують свою роль у тому, що всі намагаються зберегти.$B$BЯ говорю про місячних котиків. Якщо ви досі не в курсі, то врятувати їх надзвичайно важливо. Що ви маєте на увазі під «як»?!? Молоді місячні котики замерзнуть на смерть цієї зими, якщо ми нічого не зробимо... Я знаю!$B$BПринесіть їм наш святковий яєчний лікер, щоб вони зігрілися. Обійми теж підійдуть, але спочатку принесіть їм яєчний лікер! Де його взяти? Ну, я впевнений, що десь поруч у нас є рецепт…",
    O = "Принесіть святковий «Ег-ног» 15 лунним кішкам, щоб вони зігрілися.",
    P = "Ти вже приніс «Егг-ног» до «Мункінів»?",
    C = "Молодці! Тепер можна з упевненістю сказати, що ми вистоїмо!$B$BОсь тобі, Великий Батько Зима!",
},

