[50321] = {
    en = "The Icy Menace",
    T = "[*] Крижана загроза",
    D = "Я — Тінсел «Загублені рукавички», мої улюблені рукавички вкрали, о, чому ж я не можу плакати?! У мене є довгий список імен злодіїв, покарайте їх крижаним гнівом, бо вони вчинили неправильно! Ви можете запитати: чи це законно? Я зроблю так, щоб це стало законним, і досить швидко! Зробіть це для мене, і я підготую для вас маленьку затишну ялинку!",
    O = "Допоможіть Тінселу Лост-Гловсу помститися злодіям, які вкрали його улюблені рукавички!",
    P = "Кинь це!",
    C = "Молодець, $N.",
},

