},

[50328] = {
    en = "Jolly Holly Dances Prolly",
    T = "[*] Весела Голлі, мабуть, танцює",
    D = "Привіт, красунечко! Хіба ти не хотіла б трохи повеселитися з веселою Холлі прямо тут, моя люба? <сміється>$B$BЗвичайно, хотіла б, я це бачу в твоїх очах. Але… ти ж знаєш, що незабаром на нас чекає найвища інтимна насолода, правда? Гарні солодкі напої!$B$BНайкращий спосіб весело розважитися з Холлі!$B$BА тепер випий і станцюй для мене… гарний довгий солодкий танець, моя маленька мармеладка! Ха-ха!",
    O = "Напийся з Холлі, а потім /потанцюй з нею.",
    P = "Одружися під час Зимової завіси!",
    C = "Я-хо!",
},

[50330] = {
    en = "Peace Comes at a Price",
    T = "[*] Мир має свою ціну",
    D = "Грем — воїн. Моє завдання — захищати. Долина Зимової Завіси в небезпеці.$B$BВеликий злий вовк становить загрозу для села. Він нападає кожні кілька днів. <Грем показує тобі три пальці.>$B$BТи схожий на героя! Ти можеш допомогти! Знайди ще хороших воїнів! Напади на Сноубола, поки він спить! Він там, внизу.",
    O = "Знищте Великого снігового вовка на південь від Долини Зимової Завіси.",
    P = "Напади на Сноубола, поки він спить! Він там, внизу.",
    C = "Ти це зробив! Молодець! Моя повага і подяка!",
},

