[70020] = {
    en = "A Brother's Worried Mind",
    T = "[*] Стурбовані думки брата",
    D = "Мій молодший брат, Таупо, — талановитий друїд, і він досягнув набагато більшого, ніж я коли-небудь міг би мріяти, але він все одно залишається моїм молодшим братом.$B$BВін прямував до лісозаготівельного табору «Варсонґ», щоб, серед іншого, допомогти в боротьбі з демонічним зараженням. Я боюся, що він може потрапити в біду, оскільки йому доведеться пройти через Пагорб Фелфайр.$B$BБудь ласка, знайдіть мого молодшого брата. Я б зробив це сам, але не хочу, щоб він подумав, ніби я вважаю його нездатним, хоча й досі хвилююся. Він вирушив не так давно, рухаючись головною дорогою на схід — це шлях до лісозаготівельного табору.",
    O = "Знайдіть Таупо Форестстрайдера, брата Лорука, біля підніжжя пагорба Фелфайр.",
    P = "Так?",
    C = "Лорук послав тебе перевірити, як я? Він досі вважає мене маленьким телям без рогів?",
},

[70021] = {
    en = "Taupo's Duty",
    T = "[*] Обов'язки Таупо",
    D = "Це було благословенням Матері-Землі — народитися з таким турботливим старшим братом, і, як того хотіла доля, ось ти тут — саме та допомога, яка мені була потрібна.$B$BПо дорозі до Лісозаготівельного табору я побачила, як цей таурен хоробро бився з тими демонами, і зупинилася, щоб перев'язати йому рани. Мої навички допомогли зупинити кровотечу, але нам потрібна мазь, щоб повністю вилікувати його.$B$BУ річці ти знайдеш боглінгів — вбий їх і принеси мені їхні ядра, вони допоможуть нашому новому другові знову стати на ноги, і не хвилюйся $N, все це — заради рівноваги.",
    O = "Принесіть 10 ядер болотних істот з Таупо.",
    P = "Так?",
    C = "Дякую, $N, це допоможе нашому другові одужати.",
},

[70022] = {
    en = "Norvok of the Spear",
    T = "[*] Норвок Списник",
    D = "Я прямував до лісозаготівельного табору «Варсонг», коли зіткнувся з демонами; якби не цей друїд, я б не вижив.$B$BУ мене є дуже важливий звіт, адресований командувачу, який перебуває на місці, — командиру Грушаку. Я б одразу ж поквапився, але рани ще не позбавили мене болю, а моє спис загубилося в бою.$B$BПрошу вас знайти його, поки Таупо лікує мене. Під час пошуків — не щадіть жодного демона.",
    O = "Знищте 10 Палючих інферналів і 10 Фелгвардів.",
    P = "Так?",
    C = "Мої роги готові й нагострені, але, на жаль, моє спис вкрали ті демони — ці шкідники відчули на ньому благословення Матері-Землі!$B$BЦе не твоя провина $N, ти хоробро бився з ними, і за це я в боргу перед тобою; ось, візьми цей намисто на знак моєї вдячності.",
},

[70023] = {
    en = "Report to Commander Grushak",
    T = "[*] Звіт командувачу Грушаку",
